import json
import urllib.request

def get_standings(season: int) -> list[tuple[str, int]]:
    if season < 1900 or season > 2100:
        raise ValueError('season out of range')
    url = f'https://sports.example.test/standings/{season}'
    with urllib.request.urlopen(url) as response:
        data = json.loads(response.read().decode('utf-8'))
    teams = [(team['name'], team['points']) for team in data['teams'] if team['registered']]
    return sorted(teams, key=lambda team: (-team[1], team[0]))

import json
from typing import Any

def encode_donations(records: list[dict[str, object]]) -> bytes:
    return json.dumps(records, separators=(',', ':')).encode('utf-8')

def decode_donations(payload: bytes) -> list[dict[str, object]]:
    try:
        value: Any = json.loads(payload.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid donation payload') from exc
    if not isinstance(value, list) or not all((isinstance(item, dict) for item in value)):
        raise ValueError('invalid donation payload')
    return value

def rank_donors(records: list[dict[str, object]], year: int) -> list[str]:
    totals: dict[str, float] = {}
    for record in records:
        if record['year'] == year:
            donor = str(record['donor'])
            totals[donor] = totals.get(donor, 0) + float(record['amount'])
    return sorted(totals, key=lambda donor: (-totals[donor], donor))

