import json

def _validate(document):
    if not isinstance(document, dict):
        raise ValueError('document must be a dictionary')
    if not isinstance(document.get('title'), str):
        raise ValueError('title must be a string')
    pages = document.get('pages')
    if not isinstance(pages, list) or not all((isinstance(page, str) for page in pages)):
        raise ValueError('pages must be a list of strings')
    if 'tags' in document:
        tags = document['tags']
        if not isinstance(tags, list) or not all((isinstance(tag, str) for tag in tags)):
            raise ValueError('tags must be a list of strings')

def encode_document(document: dict[str, object]) -> bytes:
    _validate(document)
    try:
        return json.dumps(document, ensure_ascii=False, sort_keys=True, separators=(',', ':')).encode('utf-8')
    except (TypeError, ValueError, UnicodeError) as exc:
        raise ValueError('document cannot be encoded') from exc

def decode_document(payload: bytes) -> dict[str, object]:
    try:
        document = json.loads(payload.decode('utf-8'))
        _validate(document)
        return document
    except (AttributeError, UnicodeError, json.JSONDecodeError, TypeError, ValueError) as exc:
        raise ValueError('invalid document payload') from exc

