import json

def _normalize(lots):
    if not isinstance(lots, list):
        raise ValueError('lots must be a list')
    result = []
    for lot in lots:
        if not isinstance(lot, dict):
            raise ValueError('each lot must be a dictionary')
        if set(lot) != {'lot_id', 'title', 'current_bid'}:
            raise ValueError('invalid lot fields')
        lot_id = lot['lot_id']
        title = lot['title']
        bid = lot['current_bid']
        if not isinstance(lot_id, str) or not isinstance(title, str):
            raise ValueError('invalid lot text')
        if isinstance(bid, bool) or not isinstance(bid, (int, float)) or bid < 0:
            raise ValueError('invalid bid')
        result.append({'lot_id': lot_id, 'title': title, 'current_bid': bid})
    return sorted(result, key=lambda lot: (-lot['current_bid'], lot['lot_id']))

def serialize_lots(lots: list[dict[str, object]]) -> bytes:
    return json.dumps(_normalize(lots), separators=(',', ':')).encode('utf-8')

def deserialize_lots(data: bytes) -> list[dict[str, object]]:
    try:
        value = json.loads(data.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid lot data') from exc
    return _normalize(value)

