import html

def render_batch_table(batches: list[dict]) -> str:
    rows = []
    for batch in batches:
        if batch['liters'] <= 0:
            continue
        rows.append((batch['name'], batch))
    rows.sort(key=lambda item: item[0].casefold())

    def cell(value: object) -> str:
        return html.escape(str(value), quote=True)
    body = []
    for _, batch in rows:
        body.append('<tr><td>' + cell(batch['name']) + '</td><td>' + cell(batch['style']) + '</td><td>' + cell(f"{batch['liters']:.1f}") + '</td><td>' + cell(batch['status']) + '</td></tr>')
    return '<table><thead><tr><th>Name</th><th>Style</th><th>Liters</th><th>Status</th></tr></thead>' + '<tbody>' + ''.join(body) + '</tbody></table>'

