def serialize_reservations(reservations: list[dict[str, object]]) -> bytes:
    return json.dumps(reservations, ensure_ascii=False, separators=(',', ':')).encode('utf-8')

def deserialize_reservations(blob: bytes) -> list[dict[str, object]]:
    try:
        value = json.loads(blob.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError, AttributeError):
        raise ValueError('invalid reservation data')
    if not isinstance(value, list):
        raise ValueError('invalid reservation data')
    result = []
    for reservation in value:
        if not isinstance(reservation, dict):
            raise ValueError('invalid reservation')
