import html

def render_incident_table(incidents: list[dict[str, str]], status: str | None=None) -> str:
    required = {'id', 'title', 'severity', 'status', 'owner'}
    severity_order = {'high': 0, 'medium': 1, 'low': 2}
    selected = []
    for incident in incidents:
        if not required.issubset(incident):
            raise ValueError('missing incident field')
        if incident['severity'] not in severity_order:
            raise ValueError('invalid severity')
        if status is None or incident['status'] == status:
            selected.append(incident)
    selected.sort(key=lambda item: (severity_order[item['severity']], item['id']))
    rows = []
    for incident in selected:
        values = [incident['id'], incident['title'], incident['severity'], incident['status'], incident['owner']]
        cells = '</td><td>'.join((html.escape(value, quote=True) for value in values))
        rows.append(f'<tr><td>{cells}</td></tr>')
    return '<table><thead><tr><th>ID</th><th>Title</th><th>Severity</th><th>Status</th><th>Owner</th></tr></thead><tbody>' + ''.join(rows) + '</tbody></table>'

