    return json.dumps(rides, ensure_ascii=False, separators=(',', ':')).encode('utf-8')

def route_totals(blob: bytes) -> dict[str, int]:
    try:
        rides = json.loads(blob.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError, AttributeError):
        raise ValueError('invalid fare payload')
    if not isinstance(rides, list):
        raise ValueError('invalid fare payload')
    totals: dict[str, int] = {}
    for ride in rides:
        if not isinstance(ride, dict):
            raise ValueError('invalid ride')
        route = ride.get('route')
        cents = ride.get('cents')
        discounted = ride.get('discounted')
        if not isinstance(route, str) or not route or isinstance(cents, bool) or (not isinstance(cents, int)) or (cents < 0) or (not isinstance(discounted, bool)):
            raise ValueError('invalid ride')
        fare = (cents + 1) // 2 if discounted else cents
        totals[route] = totals.get(route, 0) + fare
    return totals

