def render_attendance(records: list[tuple[str, int, int]]) -> str:
    rows = []
    for name, attended, total in records:
        if total <= 0 or attended < 0 or attended > total:
            raise ValueError('invalid attendance counts')
        rate = attended / total * 100
        rows.append((name.casefold(), f'<tr><td>{name}</td><td>{rate:.1f}%</td></tr>'))
    rows.sort(key=lambda item: item[0])
    body = '\n'.join((row for _, row in rows))
    return '<table>\n<thead><tr><th>Student</th><th>Attendance</th></tr></thead>\n<tbody>\n' + body + '\n</tbody>\n</table>'

