import json
import math

def _normalise(records):
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    result = []
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('record must be an object')
        if not isinstance(record.get('certificate_id'), str) or not record['certificate_id']:
            raise ValueError('invalid certificate_id')
        if not isinstance(record.get('technology'), str):
            raise ValueError('invalid technology')
        hours = record.get('megawatt_hours')
        if isinstance(hours, bool) or not isinstance(hours, (int, float)) or (not math.isfinite(hours)):
            raise ValueError('invalid megawatt_hours')
        if isinstance(record.get('issued_year'), bool) or not isinstance(record.get('issued_year'), int):
            raise ValueError('invalid issued_year')
        result.append(dict(record))
    return sorted(result, key=lambda item: item['certificate_id'])

def encode_certificates(records: list[dict[str, object]]) -> bytes:
    return json.dumps(_normalise(records), separators=(',', ':'), ensure_ascii=False).encode('utf-8')

def decode_certificates(payload: bytes) -> list[dict[str, object]]:
    try:
        records = json.loads(payload.decode('utf-8'))
        return _normalise(records)
    except (ValueError, TypeError, UnicodeError, AttributeError) as exc:
        raise ValueError('invalid certificate payload') from exc

