def _validate(booking: object) -> dict[str, object]:
    if not isinstance(booking, dict):
        raise ValueError('booking must be a dictionary')
    if not isinstance(booking.get('room'), str) or not booking['room']:
        raise ValueError('invalid room')
    if not isinstance(booking.get('start'), int) or isinstance(booking['start'], bool):
        raise ValueError('invalid start')
    if not isinstance(booking.get('end'), int) or isinstance(booking['end'], bool):
        raise ValueError('invalid end')
    if booking['end'] <= booking['start']:
        raise ValueError('invalid time range')
    return booking

def encode_booking(booking: dict[str, object]) -> bytes:
    _validate(booking)
    try:
        return json.dumps(booking, ensure_ascii=False).encode('utf-8')
    except (TypeError, ValueError) as exc:
        raise ValueError('booking cannot be encoded') from exc

def decode_booking(payload: bytes) -> dict[str, object]:
    try:
        booking = json.loads(payload.decode('utf-8'))
    except (AttributeError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid booking payload') from exc
    return _validate(booking)

