import json

def _record(subscriber_id: str, plan: str, features: list[str]) -> dict:
    if not isinstance(subscriber_id, str) or not subscriber_id:
        raise ValueError('subscriber_id must be non-empty')
    if not isinstance(plan, str) or not plan:
        raise ValueError('plan must be non-empty')
    if not all((isinstance(feature, str) for feature in features)):
        raise ValueError('features must contain strings')
    return {'subscriber_id': subscriber_id, 'plan': plan, 'features': sorted(set(features))}

def make_provisioning_blob(subscriber_id: str, plan: str, features: list[str]) -> bytes:
    record = _record(subscriber_id, plan, features)
