import json

def encode_streams(streams: list[dict[str, int | str]]) -> bytes:
    return json.dumps(streams, separators=(',', ':')).encode('utf-8')

def calculate_royalties(payload: bytes, rates: dict[str, float]) -> dict[str, float]:
    streams = json.loads(payload.decode('utf-8'))
    totals: dict[str, int] = {}
    for record in streams:
        artist = record['artist']
        plays = record['plays']
        if plays < 0:
            raise ValueError('plays must be nonnegative')
        if artist not in rates:
            raise ValueError('missing artist rate')
        totals[artist] = totals.get(artist, 0) + plays
    return {artist: round(totals[artist] * rates[artist], 2) for artist in sorted(totals)}

