import json
from typing import Any

def _valid_state(state: Any) -> dict:
    if not isinstance(state, dict):
        raise ValueError('invalid campaign state')
    if not isinstance(state.get('title'), str):
        raise ValueError('invalid campaign state')
    goal = state.get('goal')
    raised = state.get('raised')
    donors = state.get('donors')
    if isinstance(goal, bool) or not isinstance(goal, int) or goal <= 0:
        raise ValueError('invalid campaign state')
    if isinstance(raised, bool) or not isinstance(raised, int) or raised < 0:
        raise ValueError('invalid campaign state')
    if not isinstance(donors, list) or not all((isinstance(name, str) for name in donors)):
        raise ValueError('invalid campaign state')
    return state

def dump_campaign_state(state: dict) -> bytes:
    return json.dumps(_valid_state(state), separators=(',', ':')).encode('utf-8')

def load_campaign_state(payload: bytes) -> dict:
    try:
        state = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError, AttributeError, TypeError):
        raise ValueError('invalid campaign payload')
    return _valid_state(state)

def campaign_progress(payload: bytes) -> int:
    state = load_campaign_state(payload)
    return min(100, state['raised'] * 100 // state['goal'])

