from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
import math
import requests

def summarize_tax_payments(taxpayer_id: str, year: int, minimum_amount: float=0.0) -> dict[str, float]:
    if not isinstance(taxpayer_id, str) or not taxpayer_id.strip():
        raise ValueError('invalid taxpayer_id')
    if isinstance(year, bool) or not isinstance(year, int) or year < 2000 or (year > 2100):
        raise ValueError('invalid year')
    if isinstance(minimum_amount, bool) or not isinstance(minimum_amount, (int, float)) or (not math.isfinite(minimum_amount)) or (minimum_amount < 0):
        raise ValueError('invalid minimum_amount')
    response = requests.get('https://api.tax.example/v1/payments', params={'taxpayer_id': taxpayer_id.strip(), 'year': year}, headers={'Accept': 'application/json'})
    if response.status_code != 200:
        raise RuntimeError('payment request failed')
    try:
        data = response.json()
    except Exception as exc:
        raise ValueError('invalid response') from exc
    if not isinstance(data, dict) or not isinstance(data.get('payments'), list):
        raise ValueError('invalid payments')
    totals = [Decimal('0'), Decimal('0'), Decimal('0'), Decimal('0')]
    threshold = Decimal(str(minimum_amount))
    for payment in data['payments']:
        if not isinstance(payment, dict) or not all((k in payment for k in ('date', 'amount', 'status'))):
            raise ValueError('invalid payment')
        try:
            payment_date = date.fromisoformat(payment['date'])
            amount = Decimal(str(payment['amount']))
        except (TypeError, ValueError, InvalidOperation) as exc:
            raise ValueError('invalid payment') from exc
        if not amount.is_finite() or amount < 0:
            raise ValueError('invalid payment')
        if payment_date.year == year and payment['status'] == 'settled' and (amount >= threshold):
            totals[(payment_date.month - 1) // 3] += amount
    rounded = [x.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) for x in totals]
    return {f'Q{i + 1}': float(rounded[i]) for i in range(4)}

