    url = base_url.rstrip('/') + '/runs/' + run_id
    response = requests.get(url, params={'include': 'samples,lanes'}, headers={'Authorization': 'Bearer ' + token}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError(f'run request failed: {response.status_code}')
    data = response.json()
    if not isinstance(data, dict) or not isinstance(data.get('samples'), list):
        raise ValueError()
    return data

def plan_sample_batches(manifest: dict, max_reads: int) -> list[list[str]]:
    if isinstance(max_reads, bool) or not isinstance(max_reads, int) or max_reads <= 0:
        raise ValueError()
    samples = manifest.get('samples')
    if not isinstance(samples, list):
        raise ValueError()
    checked = []
    for sample in samples:
        if not isinstance(sample, dict):
            raise ValueError()
        sid, lane, reads = (sample.get('id'), sample.get('lane'), sample.get('reads'))
        if not isinstance(sid, str) or not isinstance(lane, str) or isinstance(reads, bool) or (not isinstance(reads, int)) or (reads < 0):
            raise ValueError()
        checked.append((lane, -reads, sid, reads))
    checked.sort(key=lambda x: (x[0], x[1], x[2]))
    result, current, total = ([], [], 0)
    for lane, neg_reads, sid, reads in checked:
        if current and total + reads > max_reads:
            result.append(current)
            current, total = ([], 0)
        if reads > max_reads:
            if current:
                result.append(current)
                current, total = ([], 0)
            result.append([sid])
        else:
