def parse_sessions(text: str) -> list[dict]:
    result = []
    for number, line in enumerate(text.splitlines(), 1):
        if not line.strip():
            continue
        fields = []
        current = []
        escaped = False
        for char in line:
            if escaped:
                current.append(char)
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '|':
                fields.append(''.join(current))
                current = []
            else:
                current.append(char)
        if escaped:
            raise ValueError(f'invalid line {number}')
        fields.append(''.join(current))
        if len(fields) != 5:
            raise ValueError(f'invalid line {number}')
        try:
            when = date.fromisoformat(fields[0])
            minutes = int(fields[3])
            pain = int(fields[4])
        except (ValueError, TypeError):
            raise ValueError(f'invalid line {number}')
        if not fields[1] or not fields[2] or minutes < 0 or (not 0 <= pain <= 10):
            raise ValueError(f'invalid line {number}')
        result.append({'date': when, 'patient': fields[1], 'exercise': fields[2], 'minutes': minutes, 'pain': pain})
    return result

def summarize_sessions(records: list[dict]) -> list[dict]:
    groups = {}
    for record in records:
        key = (record['patient'], record['exercise'])
        item = groups.setdefault(key, {'visits': 0, 'minutes': 0, 'pain': 0})
        item['visits'] += 1
        item['minutes'] += record['minutes']
        item['pain'] += record['pain']
