import io
from datetime import date, datetime

def parse_inspection_feed(text: str) -> list[dict]:
    if not text.strip():
        return []
    rows = list(csv.reader(io.StringIO(text), delimiter=';'))
    rows = [[v.strip() for v in row] for row in rows if any((v.strip() for v in row))]
    if not rows or rows[0] != ['date', 'start', 'end', 'inspector', 'site', 'status']:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if len(row) != 6:
            raise ValueError('invalid row')
        d, start, end, inspector, site, status = row
        try:
            date.fromisoformat(d)
            a = datetime.strptime(start, '%H:%M')
            b = datetime.strptime(end, '%H:%M')
        except ValueError as exc:
            raise ValueError('invalid date or time') from exc
        if b <= a or not inspector or (not site) or (status not in {'scheduled', 'completed', 'cancelled'}):
            raise ValueError('invalid inspection')
        result.append({'date': d, 'start': start, 'end': end, 'inspector': inspector, 'site': site, 'status': status, 'minutes': (b - a).seconds // 60})
    return sorted(result, key=lambda r: (r['date'], r['start'], r['inspector'], r['site']))

def summarize_inspections(records: list[dict]) -> dict[str, dict[str, int]]:
    answer = {}
    for record in records:
        name = record['inspector']
        if name not in answer:
            answer[name] = {'minutes': 0, 'completed': 0, 'scheduled': 0, 'cancelled': 0}
        answer[name]['minutes'] += record['minutes']
        answer[name][record['status']] += 1
    return {name: answer[name] for name in sorted(answer)}

def render_schedule(records: list[dict], title: str) -> str:
    e = html.escape
    parts = ['<section class="schedule"><h1>', e(str(title)), '</h1>']
    if not records:
        return ''.join(parts) + '<p class="empty">No inspections</p></section>'
    current = None
    for r in records:
        if r['date'] != current:
            if current is not None:
                parts.append('</tbody></table></div>')
            current = r['date']
            parts.extend(['<div class="day" data-date="', e(r['date'], quote=True), '"><h2>', e(r['date']), '</h2><table><thead><tr><th>Time</th><th>Inspector</th><th>Site</th><th>Status</th><th>Minutes</th></tr></thead><tbody>'])
        parts.extend(['<tr><td>', e(r['start'] + '-' + r['end']), '</td><td>', e(r['inspector']), '</td><td>', e(r['site']), '</td><td class="', e(r['status'], quote=True), '">', e(r['status']), '</td><td>', e(str(r['minutes'])), '</td></tr>'])
    return ''.join(parts) + '</tbody></table></div></section>'

