import json

def encode_ticket_state(tickets: list[dict]) -> bytes:
    if not isinstance(tickets, list):
        raise ValueError('tickets must be a list')
    for record in tickets:
        _validate_record(record)
    return json.dumps(tickets, separators=(',', ':')).encode('utf-8')

def _validate_record(record):
    required = {'id', 'exhibit', 'category', 'price', 'quantity'}
    if not isinstance(record, dict) or set(record) != required:
        raise ValueError('invalid record')
    for key in ('id', 'exhibit', 'category'):
        if not isinstance(record[key], str) or not record[key]:
            raise ValueError('invalid record')
    if isinstance(record['price'], bool) or not isinstance(record['price'], (int, float)) or record['price'] < 0:
        raise ValueError('invalid record')
    if isinstance(record['quantity'], bool) or not isinstance(record['quantity'], int) or record['quantity'] < 0:
        raise ValueError('invalid record')

def summarize_ticket_state(payload: bytes, page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    try:
        records = json.loads(payload.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(records, list):
        raise ValueError('invalid payload')
    groups = {}
    for record in records:
