def encode_roster(records: list[dict]) -> bytes:
    return json.dumps(records, separators=(',', ':')).encode('utf-8')

def analyze_roster(blob: bytes, airport: str, page: int=1, page_size: int=10) -> dict:
    if not isinstance(airport, str):
        raise ValueError('invalid airport')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    try:
        records = json.loads(blob.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid roster') from exc
    if not isinstance(records, list):
        raise ValueError('invalid roster')
    groups = {}
    total = 0
    count = 0
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        if not all((key in record for key in ('name', 'airport', 'shift', 'hours'))):
            raise ValueError('invalid record')
        name = record['name']
        record_airport = record['airport']
        shift = record['shift']
        hours = record['hours']
        if not isinstance(name, str) or not isinstance(record_airport, str) or (not isinstance(shift, str)):
            raise ValueError('invalid record')
        if isinstance(hours, bool) or not isinstance(hours, (int, float)):
            raise ValueError('invalid record')
        if record_airport == airport:
            groups.setdefault(shift, [0, []])
            groups[shift][0] += hours
            groups[shift][1].append(name)
            total += hours
