from datetime import datetime
import requests

def fetch_attestations(base_url: str, organization: str, since: str) -> list[dict]:
    url = base_url.rstrip('/') + '/v1/attestations'
    page = 1
    result = []
    while True:
        response = requests.get(url, params={'organization': organization, 'since': since, 'page': page, 'limit': 100}, headers={'Accept': 'application/json'}, timeout=10)
        if response.status_code != 200:
            raise ValueError(f'HTTP {response.status_code}: {response.text}')
        try:
            body = response.json()
        except Exception as exc:
            raise ValueError('invalid JSON') from exc
        if not isinstance(body, dict) or not isinstance(body.get('attestations'), list):
            raise ValueError('invalid response')
        result.extend(body['attestations'])
        if not body.get('next_page'):
            return result
        page = body['next_page']

def summarize_attestations(records: list[dict]) -> dict:
    chosen = {}
    for index, record in enumerate(records):
        try:
            policy = record['policy_id']
            version = record['version']
            status = record['status']
            stamp = record['attested_at']
            controls = record['controls']
            if status not in {'compliant', 'non_compliant', 'pending'} or not isinstance(controls, list):
                raise ValueError
            version_key = tuple((int(x) for x in version.split('.')))
            moment = datetime.fromisoformat(stamp.replace('Z', '+00:00'))
        except (KeyError, TypeError, ValueError, AttributeError) as exc:
            raise ValueError('invalid attestation') from exc
        candidate = (moment, version_key, index, record)
        if policy not in chosen or candidate[:3] > chosen[policy][:3]:
            chosen[policy] = candidate
    policies = []
    totals = {'compliant': 0, 'non_compliant': 0, 'pending': 0}
    failures = 0
    for policy in sorted(chosen):
        record = chosen[policy][3]
        failed = []
        for control in record['controls']:
            if not isinstance(control, dict) or 'id' not in control or 'result' not in control:
                raise ValueError('invalid control')
            if control['result'] == 'failed':
                failed.append(control['id'])
        failed.sort()
        totals[record['status']] += 1
        failures += len(failed)
        policies.append({'policy_id': policy, 'version': record['version'], 'status': record['status'], 'attested_at': record['attested_at'], 'failed_controls': failed})
    return {'policies': policies, 'totals': totals, 'control_failures': failures}

