import html
from collections import defaultdict
from datetime import date

def render_visitor_report(records: list[dict[str, object]], start: str | None=None, end: str | None=None, page: int=1, per_page: int=10) -> str:
    if page < 1 or per_page < 1 or per_page > 100:
        raise ValueError('invalid pagination')

    def parse_date(value: str) -> date:
        try:
            return date.fromisoformat(value)
        except (TypeError, ValueError):
            raise ValueError('invalid date')
    first_date = parse_date(start) if start is not None else None
    last_date = parse_date(end) if end is not None else None
    if first_date is not None and last_date is not None and (first_date > last_date):
        raise ValueError('invalid range')
    grouped = defaultdict(lambda: {'visits': 0, 'visitors': set(), 'seconds': 0})
    for record in records:
        try:
            visitor = record['visitor']
            path = record['path']
            seconds = record['seconds']
            record_date = parse_date(record['date'])
        except (KeyError, TypeError):
            raise ValueError('invalid record')
        if not isinstance(visitor, str) or not isinstance(path, str) or (not isinstance(seconds, int)) or isinstance(seconds, bool) or (seconds < 0):
            raise ValueError('invalid record')
        if first_date is not None and record_date < first_date:
            continue
        if last_date is not None and record_date > last_date:
            continue
        item = grouped[path]
        item['visits'] += 1
        item['visitors'].add(visitor)
        item['seconds'] += seconds
    rows = sorted(grouped.items(), key=lambda item: (-item[1]['visits'], item[0]))
    total = len(rows)
    offset = (page - 1) * per_page
    selected = rows[offset:offset + per_page]
    body = ''.join((f"<tr><td>{html.escape(path, quote=True)}</td><td>{data['visits']}</td><td>{len(data['visitors'])}</td><td>{data['seconds'] / data['visits']:.1f}</td></tr>" for path, data in selected))
    if selected:
        shown_first = offset + 1
        shown_last = offset + len(selected)
    else:
        shown_first = shown_last = 0
    return f'<div class="report"><h1>Visitor analytics</h1><table><thead><tr><th>Path</th><th>Visits</th><th>Unique visitors</th><th>Average seconds</th></tr></thead><tbody>{body}</tbody></table><p class="summary">Showing {shown_first}-{shown_last} of {total} pages</p></div>'

