import json
_STATUSES = {'in_transit', 'delayed', 'delivered'}
_KEYS = {'shipment', 'country', 'day', 'units', 'status'}

def _check_events(events):
    if not isinstance(events, list):
        raise ValueError('events')
    for item in events:
        if not isinstance(item, dict) or set(item) != _KEYS:
            raise ValueError('event')
        if not isinstance(item['shipment'], str) or not item['shipment'] or (not isinstance(item['country'], str)) or (not item['country']) or (not isinstance(item['status'], str)) or (item['status'] not in _STATUSES) or (type(item['day']) is not int) or (type(item['units']) is not int) or (item['units'] < 0):
            raise ValueError('event')

def make_checkpoint(events: list[dict], cursor: int) -> bytes:
    _check_events(events)
    if type(cursor) is not int or cursor < 0 or cursor > len(events):
        raise ValueError('cursor')
