from datetime import datetime
from decimal import Decimal, ROUND_HALF_UP
import math

def render_renewal_page(records: list[dict[str, object]], page: int, page_size: int) -> str:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('invalid page size')
    cleaned = []
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        required = ('policy_number', 'customer', 'renewal_date', 'premium', 'status')
        if any((key not in record for key in required)):
            raise ValueError('missing field')
        policy = record['policy_number']
        customer = record['customer']
        date_text = record['renewal_date']
        status = record['status']
        premium = record['premium']
        if not all((isinstance(value, str) for value in (policy, customer, date_text, status))):
            raise ValueError('invalid field')
        try:
            date_value = datetime.strptime(date_text, '%Y-%m-%d').date()
        except ValueError:
            raise ValueError('invalid date')
        if status not in ('pending', 'renewed', 'lapsed'):
            raise ValueError('invalid status')
        if isinstance(premium, bool) or not isinstance(premium, (int, float)) or (not math.isfinite(premium)) or (premium < 0):
            raise ValueError('invalid premium')
