    cleaned.sort(key=lambda item: (item[0], item[1]))
    total = len(cleaned)
    start_index = (page - 1) * page_size
    shown = cleaned[start_index:start_index + page_size]
    if shown:
        first = start_index + 1
        last = start_index + len(shown)
    else:
        first = last = 0
    total_amount = sum((Decimal(str(item[5])) for item in cleaned), Decimal('0'))
    total_text = f"{total_amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP):.2f}"
    rows = []
    for _, policy, customer, date_text, status, premium in shown:
        amount = Decimal(str(premium)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        rows.append(f'<tr><td>{policy}</td><td>{customer}</td><td>{date_text}</td><td>{status}</td><td>${amount:.2f}</td></tr>')
    pages = (total + page_size - 1) // page_size
    return f"""<div class="renewals"><h1>Policy Renewals</h1><p class="summary">Showing {first}-{last} of {total} policies; total premium ${total_text}</p><table><thead><tr><th>Policy</th><th>Customer</th><th>Renewal date</th><th>Status</th><th>Premium</th></tr></thead><tbody>{''.join(rows)}</tbody></table><p class="page">Page {page} of {pages}</p></div>"""

