def _prepare(records, start_date, end_date):
    if not isinstance(records, (list, tuple)):
        raise ValueError('records must be a list or tuple')
    try:
        start = date.fromisoformat(start_date)
        end = date.fromisoformat(end_date)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if end < start:
        raise ValueError('invalid range')
    result = []
    for record in records:
        if not isinstance(record, dict) or any((field not in record for field in _FIELDS)):
            raise ValueError('invalid record')
        for field in ('return_id', 'customer', 'item', 'status', 'received', 'reason'):
            if not isinstance(record[field], str):
                raise ValueError('invalid text')
        if record['status'] not in _STATUSES:
            raise ValueError('invalid status')
        try:
            received = date.fromisoformat(record['received'])
            amount = Decimal(record['amount'])
        except (TypeError, ValueError, InvalidOperation):
            raise ValueError('invalid value')
        if amount < 0 or amount.as_tuple().exponent < -2:
            raise ValueError('invalid amount')
        amount = amount.quantize(Decimal('0.01'))
        if start <= received <= end:
            result.append((received, amount, record))
    result.sort(key=lambda x: (-x[0].toordinal(), -x[1], x[2]['return_id']))
    return (start, end, result)

def summarize_returns(records, start_date, end_date):
    _, _, selected = _prepare(records, start_date, end_date)
    totals = {status: 0 for status in _STATUSES}
    total = Decimal('0.00')
    for _, amount, record in selected:
        totals[record['status']] += 1
        total += amount
    return {'count': len(selected), 'totals': totals, 'amount_total': f'{total:.2f}'}

