    lines = ['<section class="returns-report">', f'<h1>Returns from {escape(start.isoformat())} to {escape(end.isoformat())}</h1>', f"""<p class="summary">{summary['count']} returns; approved: {summary['totals']['approved']} (${amounts['approved']:.2f}); rejected: {summary['totals']['rejected']} (${amounts['rejected']:.2f}); pending: {summary['totals']['pending']} (${amounts['pending']:.2f})</p>""", '<table>', '<thead><tr><th>Received</th><th>Return ID</th><th>Customer</th><th>Item</th><th>Reason</th><th>Status</th><th>Amount</th></tr></thead>', '<tbody>']
    for _, amount, record in selected:
        values = [record['received'], record['return_id'], record['customer'], record['item'], record['reason'], record['status']]
        values = [escape(value, quote=True) for value in values]
        lines.append(f'<tr><td>{values[0]}</td><td>{values[1]}</td><td>{values[2]}</td><td>{values[3]}</td><td>{values[4]}</td><td>{values[5]}</td><td>${amount:.2f}</td></tr>')
    lines.extend(['</tbody>', '</table>', '</section>'])
    return '\n'.join(lines)

