import requests

def fetch_assessments(endpoint: str, parcel_ids: list[str], tax_year: int, token: str) -> list[dict]:
    url = endpoint.rstrip('/') + '/v1/assessments'
    response = requests.get(url, params={'year': tax_year, 'parcel_ids': ','.join(parcel_ids)}, headers={'Authorization': 'Bearer ' + token, 'Accept': 'application/json'})
    if response.status_code != 200:
        raise RuntimeError(f'assessment service returned {response.status_code}')
    try:
        payload = response.json()
        items = payload['assessments']
        if not isinstance(items, list):
            raise ValueError
    except Exception as exc:
        raise ValueError('invalid assessment response') from exc
    result = []
    seen = set()
    for item in items:
        try:
            pid = item['parcel_id']
            municipality = item['municipality']
            prop = item['property_class']
            land = item['land_value']
            building = item['building_value']
            exemptions = item['exemptions']
            appeals = item['appeals']
            if any((not isinstance(x, str) for x in (pid, municipality, prop))) or pid in seen:
                raise ValueError
            if any((not isinstance(x, (int, float)) or isinstance(x, bool) or x < 0 for x in (land, building))):
                raise ValueError
            ex_total = 0
            for ex in exemptions:
                amount = ex['amount']
                if not isinstance(ex['code'], str) or not isinstance(amount, (int, float)) or isinstance(amount, bool) or (amount < 0):
                    raise ValueError
                ex_total += amount
            appeal_total = 0
            for appeal in appeals:
                amount = appeal['amount']
                if not isinstance(amount, (int, float)) or isinstance(amount, bool):
                    raise ValueError
                if appeal['status'] == 'approved':
                    appeal_total += amount
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid assessment record')
        seen.add(pid)
        result.append({'parcel_id': pid, 'municipality': municipality, 'property_class': prop, 'land_value': land, 'building_value': building, 'exemptions': ex_total, 'approved_appeals': appeal_total, 'net_assessment': land + building - ex_total - appeal_total})
    return sorted(result, key=lambda x: x['parcel_id'])

def rollup_assessments(records: list[dict]) -> list[dict]:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    groups = {}
    for record in records:
        try:
            key = (record['municipality'], record['property_class'])
            pid = record['parcel_id']
            value = record['net_assessment']
        except (KeyError, TypeError):
            raise ValueError('invalid normalized record')
        groups.setdefault(key, []).append((pid, value))
    output = []
    for (municipality, prop), values in groups.items():
        ordered = sorted(values, key=lambda x: x[1])
        nums = [x[1] for x in ordered]
        middle = len(nums) // 2
        median = nums[middle] if len(nums) % 2 else (nums[middle - 1] + nums[middle]) / 2
        if isinstance(median, float) and median.is_integer():
            median = int(median)
        output.append({'municipality': municipality, 'property_class': prop, 'parcel_count': len(values), 'total_net_assessment': sum(nums), 'median_net_assessment': median, 'parcel_ids': sorted((x[0] for x in values))})
    return sorted(output, key=lambda x: (x['municipality'], x['property_class']))

def assessment_report(endpoint: str, parcel_ids: list[str], tax_year: int, token: str) -> list[dict]:
    return rollup_assessments(fetch_assessments(endpoint, parcel_ids, tax_year, token))

