            pid = record['parcel_id']
            value = record['net_assessment']
        except (KeyError, TypeError):
            raise ValueError('invalid normalized record')
        groups.setdefault(key, []).append((pid, value))
    output = []
    for (municipality, prop), values in groups.items():
        ordered = sorted(values, key=lambda x: x[1])
        nums = [x[1] for x in ordered]
        middle = len(nums) // 2
        median = nums[middle] if len(nums) % 2 else (nums[middle - 1] + nums[middle]) / 2
        if isinstance(median, float) and median.is_integer():
            median = int(median)
