from datetime import datetime, timezone
import requests

def _time(value):
    if not isinstance(value, str):
        raise ValueError('invalid timestamp')
    try:
        parsed = datetime.fromisoformat(value[:-1] + '+00:00' if value.endswith('Z') else value)
        if parsed.tzinfo is None:
            raise ValueError
        return parsed.astimezone(timezone.utc)
    except Exception as exc:
        raise ValueError('invalid timestamp') from exc

def fetch_compliance(base_url: str, device_ids: list[str], token: str) -> list[dict]:
    unique = list(dict.fromkeys(device_ids))
    if not unique:
        return []
    response = requests.get(base_url.rstrip('/') + '/v1/compliance', params={'device_id': ','.join(unique)}, headers={'Authorization': 'Bearer ' + token}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError(f'compliance request failed: {response.status_code}')
    try:
        body = response.json()
        devices = body['devices']
        if not isinstance(body, dict) or not isinstance(devices, list):
            raise ValueError
        for device in devices:
            if not isinstance(device, dict) or not isinstance(device.get('device_id'), str) or (not isinstance(device.get('checks'), list)):
                raise ValueError
        return devices
    except (KeyError, TypeError, ValueError) as exc:
        raise ValueError('invalid response') from exc

def summarize_compliance(devices: list[dict], as_of: str) -> list[dict]:
    cutoff = _time(as_of)
    merged = {}
    for device in devices:
        if not isinstance(device, dict) or not isinstance(device.get('device_id'), str) or (not isinstance(device.get('checks'), list)):
            raise ValueError('invalid device')
        selected = merged.setdefault(device['device_id'], {})
        for check in device['checks']:
            if not isinstance(check, dict) or not isinstance(check.get('name'), str) or (not check['name']) or (check.get('status') not in {'pass', 'fail', 'unknown'}):
                raise ValueError('invalid check')
            stamp = _time(check.get('updated_at'))
            if stamp <= cutoff and (check['name'] not in selected or stamp > selected[check['name']][0]):
                selected[check['name']] = (stamp, check['status'])
    result = []
    for device_id in sorted(merged):
        statuses = [item[1] for item in merged[device_id].values()]
        passed, failed, unknown = (statuses.count('pass'), statuses.count('fail'), statuses.count('unknown'))
        state = 'failed' if failed else 'unknown' if unknown or not statuses else 'compliant'
        result.append({'device_id': device_id, 'status': state, 'passed': passed, 'failed': failed, 'unknown': unknown})
    return result

def compliance_report(base_url: str, device_ids: list[str], token: str, as_of: str) -> list[dict]:
    return summarize_compliance(fetch_compliance(base_url, device_ids, token), as_of)

