    except (TypeError, ValueError):
        raise ValueError('invalid appointment date')
    if parsed_date.strftime('%Y-%m-%d') != appointment_date:
        raise ValueError('invalid appointment date')
    if page < 1 or not 1 <= page_size <= 100:
        raise ValueError('invalid pagination')
    params = {'date': appointment_date}
    if specialty is not None:
        params['specialty'] = specialty
    response = requests.get('https://api.telemed.example/v1/availability', params=params, headers={'Accept': 'application/json'}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError('availability request failed')
    selected = []
    for item in response.json()['slots']:
        if item['status'] != 'available' or (item['specialty'] != specialty and specialty is not None):
            continue
        start = datetime.fromisoformat(item['start'])
        end = datetime.fromisoformat(item['end'])
        if start.date().isoformat() != appointment_date or end <= start:
            continue
        minutes = int((end - start).total_seconds() // 60)
        if minutes < 30:
            continue
        selected.append((start, float(item['fee']), item['doctor'], item, minutes))
    selected.sort(key=lambda x: (x[0], x[1], x[2]))
    first = (page - 1) * page_size
    result = []
    for _, fee, _, item, minutes in selected[first:first + page_size]:
        result.append({'start': item['start'], 'end': item['end'], 'doctor': item['doctor'], 'specialty': item['specialty'], 'fee': round(fee, 2), 'duration_minutes': minutes})
    return result

