def encode_certifications(records: list[dict]) -> bytes:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    try:
        return json.dumps(records, separators=(',', ':'), allow_nan=False).encode('utf-8')
    except (TypeError, ValueError, UnicodeError) as exc:
        raise ValueError('invalid records') from exc

def summarize_certifications(payload: bytes, min_score: float=0.0, offset: int=0, limit: int=20) -> list[dict]:
    if isinstance(min_score, bool) or not isinstance(min_score, (int, float)) or (not math.isfinite(min_score)) or (not 0 <= min_score <= 100):
        raise ValueError('invalid minimum score')
    if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
        raise ValueError('invalid offset')
    if isinstance(limit, bool) or not isinstance(limit, int) or limit <= 0:
        raise ValueError('invalid limit')
    try:
        records = json.loads(payload.decode('utf-8'))
    except (AttributeError, UnicodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(records, list):
        raise ValueError('invalid records')
    grouped = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        candidate = record.get('candidate')
        certification = record.get('certification')
        score = record.get('score')
        passed = record.get('passed')
        if not isinstance(candidate, str) or not candidate or (not isinstance(certification, str)) or (not certification) or isinstance(score, bool) or (not isinstance(score, (int, float))) or (not math.isfinite(score)) or (not 0 <= score <= 100) or (not isinstance(passed, bool)):
            raise ValueError('invalid record')
        if passed and score >= min_score:
            grouped.setdefault(candidate, []).append(score)
    result = [{'candidate': name, 'certifications': len(scores), 'average_score': round(sum(scores) / len(scores), 2)} for name, scores in grouped.items()]
    result.sort(key=lambda item: (-item['average_score'], -item['certifications'], item['candidate']))
    return result[offset:offset + limit]

