import re
import requests

def _version(value):
    m = re.fullmatch('(\\d+)\\.(\\d+)\\.(\\d+)(?:-([0-9A-Za-z.-]+))?', value)
    if not m:
        raise ValueError('invalid version')
    pre = m.group(4)
    return (int(m.group(1)), int(m.group(2)), int(m.group(3)), pre is None, pre or '')

def fetch_releases(project: str, token: str | None=None, include_drafts: bool=False) -> list[dict]:
    headers = {'Accept': 'application/json'}
    if token is not None:
        headers['Authorization'] = 'Bearer ' + token
    r = requests.get('https://docs.example.test/api/projects/' + project + '/releases', params={'include_drafts': '1' if include_drafts else '0'}, headers=headers, timeout=10)
    if r.status_code != 200:
        raise RuntimeError('request failed')
    data = r.json()
    if not isinstance(data, dict) or not isinstance(data.get('releases'), list):
        raise ValueError('invalid response')
    result = []
    for raw in data['releases']:
        if not isinstance(raw, dict) or not isinstance(raw.get('version'), str):
            raise ValueError('invalid release')
        key = _version(raw['version'])
        status = raw.get('status')
        if status != 'published' and (not (include_drafts and status == 'draft')):
            continue
        pages = {}
        for page in raw.get('pages', []):
            if not isinstance(page, dict) or not isinstance(page.get('slug'), str) or (not page['slug']) or (not isinstance(page.get('title'), str)) or (not isinstance(page.get('order'), int)):
                continue
            old = pages.get(page['slug'])
            if old is None or page['order'] < old['order']:
                pages[page['slug']] = {'slug': page['slug'], 'title': page['title'], 'order': page['order']}
        result.append({'version': raw['version'], 'status': status, 'updated': raw.get('updated'), 'pages': sorted(pages.values(), key=lambda p: (p['order'], p['slug'])), '_key': key})
    result.sort(key=lambda x: (x['_key'], x['status'] == 'published'), reverse=True)
    for item in result:
        del item['_key']
    return result

def render_navigation(releases: list[dict], version: str | None=None) -> dict:
    if not releases:
        raise ValueError('no releases')
    selected = releases[0] if version is None else next((r for r in releases if r.get('version') == version), None)
    if selected is None:
        raise KeyError(version)
    tree = {}
    for page in selected.get('pages', []):
        node = tree
        parts = page['slug'].split('/')
        for part in parts[:-1]:
            if part in node and (not isinstance(node[part], dict)):
                raise ValueError('path conflict')
            node = node.setdefault(part, {})
        leaf = parts[-1]
        if leaf in node and isinstance(node[leaf], dict):
            raise ValueError('path conflict')
        node[leaf] = page['title']
    return tree

def release_summary(releases: list[dict]) -> dict:
    return {'total_releases': len(releases), 'published': sum((r.get('status') == 'published' for r in releases)), 'drafts': sum((r.get('status') == 'draft' for r in releases)), 'total_pages': sum((len(r.get('pages', [])) for r in releases)), 'latest_version': releases[0]['version'] if releases else None}

