        raise ValueError('invalid min_rating')
    url = f'https://api.boardgames.example/v1/tournaments/{tournament_id}/registrations'
    response = requests.get(url, params={'min_rating': min_rating}, headers={'Accept': 'application/json'}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError('request failed')
