        if not isinstance(item, dict) or not required.issubset(item):
            raise ValueError('invalid reading')
        meter_id, date, kwh, item_status = (item[x] for x in ('meter_id', 'date', 'kwh', 'status'))
        if not isinstance(meter_id, str) or not isinstance(item_status, str) or (not isinstance(date, str)):
