    if not isinstance(city, str) or not city.strip():
        raise ValueError('invalid city')
    if not isinstance(start_date, str) or not isinstance(end_date, str):
        raise ValueError('invalid dates')
    try:
        start = date.fromisoformat(start_date)
        end = date.fromisoformat(end_date)
    except ValueError:
        raise ValueError('invalid dates')
    if start > end:
        raise ValueError('invalid date range')
    if isinstance(max_daily_rate, bool) or not isinstance(max_daily_rate, (int, float)) or max_daily_rate < 0:
        raise ValueError('invalid rate')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    response = requests.get('https://fleet.example.com/api/cars', params={'city': city.strip(), 'start_date': start_date, 'end_date': end_date, 'max_daily_rate': max_daily_rate}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError('fleet request failed')
    data = response.json()
    if not isinstance(data, dict) or not isinstance(data.get('cars'), list):
        raise ValueError('invalid fleet data')
    matches = []
    for car in data['cars']:
        try:
            if car['city'] == city.strip() and car['daily_rate'] <= max_daily_rate and (car['available_from'] <= start_date) and (car['available_to'] >= end_date):
                matches.append(car)
        except (KeyError, TypeError):
            raise ValueError('invalid car data')
    matches.sort(key=lambda item: (item['daily_rate'], str(item['id'])))
    total = len(matches)
    first = (page - 1) * page_size
    selected = matches[first:first + page_size]
