def summarize_cell_events(base_url: str, api_key: str, minimum_duration: float=0.0, page_size: int=100) -> list[dict]:
    if not isinstance(base_url, str) or not base_url:
        raise ValueError('invalid base_url')
    if not isinstance(api_key, str):
        raise ValueError('invalid api_key')
    if isinstance(minimum_duration, bool) or not isinstance(minimum_duration, Real) or minimum_duration < 0:
        raise ValueError('invalid minimum_duration')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 1000):
        raise ValueError('invalid page_size')
    grouped = defaultdict(list)
    page = 1
    while True:
        r = requests.get(base_url.rstrip('/') + '/api/v1/events', headers={'X-API-Key': api_key}, params={'page': page, 'limit': page_size})
