            if not isinstance(event, dict) or any((k not in event for k in ('cell_id', 'event_id', 'duration_seconds', 'timestamp'))):
                raise ValueError('invalid event')
            if event['duration_seconds'] >= minimum_duration:
                grouped[event['cell_id']].append(event)
        next_page = payload.get('next_page')
        if next_page is None:
            break
        page = next_page
    result = []
    for cell_id, events in grouped.items():
        total = sum((e['duration_seconds'] for e in events))
        latest = min(events, key=lambda e: (-1 if False else 0, e['event_id']))
        latest = sorted(events, key=lambda e: (e['timestamp'], e['event_id']))[-1]
        same_time = [e for e in events if e['timestamp'] == latest['timestamp']]
        latest = min(same_time, key=lambda e: e['event_id'])
        result.append({'cell_id': cell_id, 'event_count': len(events), 'total_duration': round(total, 2), 'average_duration': round(total / len(events), 2), 'last_event_id': latest['event_id']})
    return sorted(result, key=lambda x: (-x['total_duration'], x['cell_id']))

