import json
import math

def _validate_records(records):
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    for record in records:
        if not isinstance(record, dict) or set(record) != {'district', 'volume', 'priority'}:
            raise ValueError('invalid record')
        if not isinstance(record['district'], str) or not record['district']:
            raise ValueError('invalid district')
        if isinstance(record['volume'], bool) or not isinstance(record['volume'], (int, float)) or (not math.isfinite(record['volume'])) or (record['volume'] < 0):
            raise ValueError('invalid volume')
        if isinstance(record['priority'], bool) or not isinstance(record['priority'], int) or (not 0 <= record['priority'] <= 10):
            raise ValueError('invalid priority')

def encode_allocation_state(records: list[dict]) -> bytes:
    _validate_records(records)
    try:
        return json.dumps(records, separators=(',', ':'), allow_nan=False).encode('utf-8')
    except (TypeError, ValueError, UnicodeError) as exc:
        raise ValueError('cannot encode state') from exc

def summarize_allocations(blob: bytes, district: str | None=None, min_priority: int=0, offset: int=0, limit: int=20) -> list[dict]:
    if not isinstance(district, (str, type(None))) or district == '':
        raise ValueError('invalid district')
    if isinstance(min_priority, bool) or not isinstance(min_priority, int) or (not 0 <= min_priority <= 10):
        raise ValueError('invalid priority')
    if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
        raise ValueError('invalid offset')
    if isinstance(limit, bool) or not isinstance(limit, int) or (not 1 <= limit <= 100):
        raise ValueError('invalid limit')
    try:
        records = json.loads(blob.decode('utf-8'))
        _validate_records(records)
    except (AttributeError, UnicodeError, json.JSONDecodeError, TypeError, ValueError) as exc:
        raise ValueError('invalid state') from exc
    groups = {}
    for record in records:
        if (district is None or record['district'] == district) and record['priority'] >= min_priority:
            group = groups.setdefault(record['district'], {'district': record['district'], 'total_volume': 0.0, 'allocation_count': 0, 'highest_priority': 0})
            group['total_volume'] += record['volume']
            group['allocation_count'] += 1
            group['highest_priority'] = max(group['highest_priority'], record['priority'])
    result = list(groups.values())
    for group in result:
        group['total_volume'] = round(group['total_volume'], 2)
    result.sort(key=lambda item: (-item['total_volume'], -item['highest_priority'], item['district']))
    return result[offset:offset + limit]

