from html import escape

def render_kb_page(articles: list[dict], query: str='', page: int=1, per_page: int=10) -> str:
    if page < 1 or per_page < 1:
        raise ValueError('page and per_page must be positive')
    fields = ('id', 'title', 'category', 'summary', 'status', 'updated', 'views')
    checked = []
    for article in articles:
        if any((field not in article for field in fields)):
            raise ValueError('invalid article')
        if not isinstance(article['id'], int) or isinstance(article['id'], bool) or (not isinstance(article['views'], int)) or isinstance(article['views'], bool):
            raise ValueError('invalid article')
        if any((not isinstance(article[field], str) for field in fields[1:6])):
            raise ValueError('invalid article')
        checked.append(article)
    q = query.casefold()
    found = [a for a in checked if a['status'] == 'published' and (not q or q in a['title'].casefold() or q in a['summary'].casefold())]
    found.sort(key=lambda a: (a['category'].casefold(), a['title'].casefold(), a['id']))
    start = (page - 1) * per_page
    current = found[start:start + per_page]
    out = ['<div class="kb">', '<h1>Knowledge Base</h1>']
    if query:
        out.append(f'<p class="query">Search: {escape(query)}</p>')
    out.append(f'<p class="summary">Showing {len(current)} of {len(found)} articles</p>')
    groups = []
    for article in current:
        if not groups or groups[-1][0] != article['category']:
            groups.append((article['category'], []))
        groups[-1][1].append(article)
    for category, group in groups:
        out.extend([f'<section data-category="{escape(category)}">', f'<h2>{escape(category)}</h2>', '<ul>'])
        for article in group:
            out.append(f'''<li data-id="{article['id']}"><h3>{escape(article['title'])}</h3><p>{escape(article['summary'])}</p><span>{escape(article['updated'])} · {article['views']} views</span></li>''')
        out.extend(['</ul>', '</section>'])
    out.append('</div>')
    return '\n'.join(out)

