            donor = donation.get('donor')
            amount = donation.get('amount')
            if donation.get('status') == 'completed' and isinstance(donor, str) and donor and (not isinstance(amount, bool)) and isinstance(amount, (int, float)) and math.isfinite(amount) and (amount > 0):
                totals[donor] += amount
        next_page = payload.get('next_page')
