        if isinstance(next_page, bool) or not isinstance(next_page, int) or next_page <= 0:
            raise ValueError('invalid next_page')
        page = next_page
    return sorted(((donor, round(total, 2)) for donor, total in totals.items()), key=lambda item: (-item[1], item[0]))

