import requests
from numbers import Real

def _record(item):
    if not isinstance(item, dict) or set(item) != {'unit', 'month', 'charge', 'paid'}:
        raise ValueError('invalid record')
    unit = item['unit']
    month = item['month']
    charge = item['charge']
    paid = item['paid']
    if not isinstance(unit, str) or not unit or isinstance(month, bool) or (not isinstance(month, int)) or (not 1 <= month <= 12):
        raise ValueError('invalid record')
    if isinstance(charge, bool) or isinstance(paid, bool) or (not isinstance(charge, Real)) or (not isinstance(paid, Real)) or (charge < 0) or (paid < 0):
        raise ValueError('invalid record')
    return {'unit': unit, 'month': month, 'charge': float(charge), 'paid': float(paid)}

def _records(records):
    if not isinstance(records, list):
        raise ValueError('invalid records')
    return [_record(x) for x in records]

def fetch_dues(unit_ids: list[str], year: int) -> list[dict]:
    if not unit_ids or not isinstance(year, int) or isinstance(year, bool) or (not 2000 <= year <= 2100):
        raise ValueError('invalid request')
    if any((not isinstance(x, str) or not x for x in unit_ids)):
        raise ValueError('invalid unit')
    response = requests.get('https://billing.example.org/api/dues', params={'year': year, 'units': ','.join(sorted(unit_ids))}, headers={'Accept': 'application/json'}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError('dues request failed')
    try:
        data = response.json()
    except Exception as exc:
        raise ValueError('invalid response') from exc
    if not isinstance(data, dict) or not isinstance(data.get('dues'), list):
        raise ValueError('invalid response')
    result = _records(data['dues'])
    return sorted(result, key=lambda x: (x['unit'], x['month']))

def reconcile_dues(records: list[dict], through_month: int) -> dict[str, dict]:
    if isinstance(through_month, bool) or not isinstance(through_month, int) or (not 1 <= through_month <= 12):
        raise ValueError('invalid month')
    rows = _records(records)
    units = sorted({x['unit'] for x in rows})
    result = {}
    for unit in units:
        balance = 0.0
        late = []
        for month in range(1, through_month + 1):
            balance += sum((x['charge'] - x['paid'] for x in rows if x['unit'] == unit and x['month'] == month))
            if balance > 0:
                late.append(month)
        result[unit] = {'balance': round(balance, 2), 'delinquent_months': late, 'months_processed': through_month}
    return result

def build_monthly_report(records: list[dict], through_month: int) -> list[dict]:
    if isinstance(through_month, bool) or not isinstance(through_month, int) or (not 1 <= through_month <= 12):
        raise ValueError('invalid month')
    rows = _records(records)
    result = []
    for month in range(1, through_month + 1):
        charged = sum((x['charge'] for x in rows if x['month'] == month))
        collected = sum((x['paid'] for x in rows if x['month'] == month))
        result.append({'month': month, 'charged': round(charged, 2), 'collected': round(collected, 2), 'outstanding': round(charged - collected, 2)})
    return result

