import json

def encode_state(state: dict) -> bytes:
    if not isinstance(state, dict):
        raise ValueError('state must be a dictionary')
    try:
        return json.dumps(state, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode('utf-8')
    except (TypeError, ValueError, UnicodeError) as exc:
        raise ValueError('invalid state') from exc

def decode_state(blob: bytes) -> dict:
    if not isinstance(blob, bytes):
        raise ValueError('invalid state')
    try:
        value = json.loads(blob.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError, TypeError, ValueError) as exc:
        raise ValueError('invalid state') from exc
    if not isinstance(value, dict):
        raise ValueError('state must be a dictionary')
    return value

def summarize_outages(records: list[dict], at: int) -> list[dict]:
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        required = ('region', 'start', 'end', 'customers', 'priority')
        if any((key not in record for key in required)):
            raise ValueError('invalid record')
        region = record['region']
        start = record['start']
        end = record['end']
        customers = record['customers']
        priority = record['priority']
        if not isinstance(region, str) or not region or isinstance(start, bool) or (not isinstance(start, int)) or isinstance(end, bool) or (not isinstance(end, int)) or isinstance(customers, bool) or (not isinstance(customers, int)) or isinstance(priority, bool) or (not isinstance(priority, int)) or (start >= end) or (customers < 0) or (not 1 <= priority <= 5):
            raise ValueError('invalid record')
        if start <= at < end:
            item = groups.get(region)
            if item is None:
                groups[region] = {'region': region, 'customers': customers, 'priority': priority, 'start': start, 'end': end, 'incidents': 1}
            else:
                item['customers'] += customers
                item['priority'] = max(item['priority'], priority)
                item['start'] = min(item['start'], start)
                item['end'] = max(item['end'], end)
                item['incidents'] += 1
    return sorted(groups.values(), key=lambda x: (-x['priority'], -x['customers'], x['region']))

