import requests
from datetime import date
from collections import defaultdict

def _line(line):
    try:
        sku = str(line['sku'])
        quantity = line['quantity']
        price = line['unit_price']
        requested = line['requested_date']
    except (KeyError, TypeError):
        raise ValueError('invalid line')
    if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity <= 0:
        raise ValueError('invalid quantity')
    if isinstance(price, bool) or not isinstance(price, (int, float)) or price < 0:
        raise ValueError('invalid price')
    if not isinstance(requested, str):
        raise ValueError('invalid date')
    try:
        date.fromisoformat(requested)
    except ValueError:
        raise ValueError('invalid date')
    return {'sku': sku, 'quantity': int(quantity), 'unit_price': float(price), 'requested_date': requested}

def _order(order):
    try:
        lines = order['lines']
        if not isinstance(lines, list):
            raise ValueError('invalid lines')
        return {'id': str(order['id']), 'supplier': str(order['supplier']), 'lines': [_line(x) for x in lines]}
    except (KeyError, TypeError):
        raise ValueError('invalid order')

def fetch_purchase_orders(supplier_id: str, api_token: str, since: str | None=None) -> list[dict]:
    params = {'limit': 100}
    if since is not None:
        params['since'] = since
    response = requests.get(f'https://orders.example.test/v2/suppliers/{supplier_id}/purchase-orders', headers={'Authorization': f'Bearer {api_token}'}, params=params, timeout=10)
    if response.status_code != 200:
        raise ValueError(f'unexpected status {response.status_code}')
    try:
        payload = response.json()
    except Exception as exc:
        raise ValueError('invalid json') from exc
    if not isinstance(payload, dict) or not isinstance(payload.get('orders'), list):
        raise ValueError('invalid payload')
    return [_order(x) for x in payload['orders']]

def consolidate_orders(orders: list[dict]) -> list[dict]:
    grouped = {}
    for order in orders:
        try:
            oid, supplier = (str(order['id']), str(order['supplier']))
            lines = order['lines']
        except (KeyError, TypeError):
            raise ValueError('invalid order')
        key = (supplier, oid)
        for existing in grouped:
            if existing[1] == oid and existing[0] != supplier:
                raise ValueError('conflicting supplier')
        if key not in grouped:
            grouped[key] = {}
        for raw in lines:
            line = _line(raw)
            old = grouped[key].get(line['sku'])
            if old is None or (line['requested_date'], line['unit_price']) < (old['requested_date'], old['unit_price']):
                chosen_date, chosen_price = (line['requested_date'], line['unit_price'])
            else:
                chosen_date, chosen_price = (old['requested_date'], old['unit_price'])
            grouped[key][line['sku']] = {'sku': line['sku'], 'quantity': (old['quantity'] if old else 0) + line['quantity'], 'unit_price': chosen_price, 'requested_date': chosen_date}
    result = []
    for (supplier, oid), lines in sorted(grouped.items()):
