def encode_state(state: dict) -> bytes:
    return json.dumps(state, separators=(',', ':'), ensure_ascii=False).encode('utf-8')

def decode_state(blob: bytes) -> dict:
    return json.loads(blob.decode('utf-8'))

def plan_inspections(inspections, inspectors, state_blob, day_start, day_end):
    if day_start > day_end:
        raise ValueError('invalid day')
    state = decode_state(state_blob)
    completed = list(state.get('completed', []))
    occupied = list(state.get('occupied', []))
    done = set(completed)
    items = [x for x in inspections if x['id'] not in done]
    for item in items:
        if item['duration'] <= 0:
            raise ValueError('invalid duration')
        for window in item['windows']:
            if len(window) != 2 or window[0] > window[1]:
                raise ValueError('invalid window')
    items.sort(key=lambda x: (-x['priority'], x['duration'], x['id']))
    result = []
    missing = []
    for item in items:
        choices = []
        for name in sorted(inspectors):
            if item['skill'] not in inspectors[name]:
                continue
            blocked = [(r['start'], r['end']) for r in occupied if r['inspector'] == name]
            for other in result:
                if other['inspector'] == name:
                    blocked.append((other['start'], other['end']))
            for low, high in item['windows']:
                start = max(day_start, low)
                limit = min(day_end, high)
                while start + item['duration'] <= limit:
                    conflict = [a for a, b in blocked if start < b and start + item['duration'] > a]
                    if not conflict:
                        choices.append((start, name, start + item['duration']))
                        break
                    start = min((b for a, b in blocked if start < b and start + item['duration'] > a))
        if not choices:
            missing.append(item['id'])
        else:
            start, name, end = min(choices, key=lambda x: (x[0], x[1]))
            result.append({'id': item['id'], 'inspector': name, 'start': start, 'end': end})
            completed.append(item['id'])
            occupied.append({'inspector': name, 'start': start, 'end': end, 'inspection': item['id']})
    updated = {'completed': completed, 'occupied': occupied}
    return (result, missing, encode_state(updated))

def daily_totals(assignments):
    totals = {}
    for item in assignments:
        name = item['inspector']
        totals.setdefault(name, 0)
        totals[name] += item['end'] - item['start']
    return totals

