from datetime import date
import requests

def parse_valuation_payload(payload: dict) -> list[dict]:
    if not isinstance(payload, dict) or not isinstance(payload.get('results'), list):
        raise ValueError('invalid payload')
    records = []
    seen = set()
    for item in payload['results']:
        if not isinstance(item, dict) or not isinstance(item.get('property'), dict):
            raise ValueError('invalid record')
        ident = item['property'].get('id')
        if not isinstance(ident, str) or not ident or ident in seen:
            raise ValueError('invalid id')
        try:
            value = float(item['value'])
            confidence = float(item['confidence'])
            date.fromisoformat(item['date'])
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid record')
        if value <= 0 or confidence < 0 or confidence > 1:
            raise ValueError('invalid record')
        area = item.get('square_feet')
        if area is not None:
            try:
                area = float(area)
            except (TypeError, ValueError):
                raise ValueError('invalid area')
            if area <= 0:
                raise ValueError('invalid area')
        seen.add(ident)
        records.append({'id': ident, 'value': value, 'confidence': confidence, 'date': item['date'], 'square_feet': area})
    return records

def summarize_valuations(records: list[dict]) -> dict:
    if not records:
        return {'count': 0, 'median_value': None, 'weighted_average': None, 'latest': None, 'total_square_feet': 0.0}
    values = sorted((r['value'] for r in records))
    middle = len(values) // 2
    median = values[middle] if len(values) % 2 else (values[middle - 1] + values[middle]) / 2
    weight = sum((r['confidence'] for r in records))
    weighted = sum((r['value'] * r['confidence'] for r in records)) / weight if weight else None
    latest = min(records, key=lambda r: (-int(r['date'].replace('-', '')), r['id']))
    total = sum((r['square_feet'] for r in records if r['square_feet'] is not None))
    return {'count': len(records), 'median_value': median, 'weighted_average': weighted, 'latest': latest, 'total_square_feet': total}

def get_valuation_report(address: str, api_key: str, endpoint: str='https://api.example.test/valuations') -> dict:
    response = requests.get(endpoint, params={'address': address}, headers={'Authorization': 'Bearer ' + api_key}, timeout=10)
    if response.status_code != 200:
        raise ValueError('valuation request failed')
    try:
        payload = response.json()
    except Exception as exc:
        raise ValueError('invalid response') from exc
    records = parse_valuation_payload(payload)
    return {'address': address, 'records': records, 'summary': summarize_valuations(records)}

