        "severity": "high",
        "position": {"latitude": 51.5074, "longitude": -0.1278},
        "summary": "Loss of propulsion near the eastern traffic lane"
    }


def test_round_trip_standard_incident():
    value = incident()
    payload = serialize_incident(value)
    assert isinstance(payload, bytes)
    assert deserialize_incident(payload) == value


def test_round_trip_unicode_and_zero_coordinates():
    value = {
        "vessel_id": "Ägir-7",
        "occurred_at": "2025-01-01T00:00:00Z",
        "severity": "low",
        "position": {"latitude": 0, "longitude": 0.0},
        "summary": "Équipage réuni — no injury"
    }
    assert deserialize_incident(serialize_incident(value)) == value


def test_all_severity_values_round_trip():
    for severity in ("low", "medium", "high"):
        value = incident()
        value["severity"] = severity
        assert deserialize_incident(serialize_incident(value))["severity"] == severity


def test_serializer_rejects_missing_extra_and_wrong_fields():
    value = incident()
    for bad in (
        {k: v for k, v in value.items() if k != "summary"},
        dict(value, extra="not allowed"),
        dict(value, severity="critical"),
        dict(value, position={"latitude": 1}),
        dict(value, position={"latitude": True, "longitude": 2}),
        dict(value, vessel_id="")
    ):
        with pytest.raises(ValueError):
            serialize_incident(bad)


def test_serializer_rejects_non_dictionaries():
    for value in (None, [], "incident", 12):
        with pytest.raises(ValueError):
            serialize_incident(value)


def test_deserializer_rejects_malformed_payloads():
    for payload in (b"", b"not an incident", b"{}", b"[1, 2, 3]", None, "text"):
        with pytest.raises(ValueError):
            deserialize_incident(payload)


