import json

def _validate(incident):
    if not isinstance(incident, dict):
        raise ValueError('incident must be a dictionary')
    if set(incident) != {'vessel_id', 'occurred_at', 'severity', 'position', 'summary'}:
        raise ValueError('invalid incident fields')
    if not isinstance(incident['vessel_id'], str) or not incident['vessel_id']:
        raise ValueError('invalid vessel id')
    if not isinstance(incident['occurred_at'], str) or not incident['occurred_at']:
        raise ValueError('invalid timestamp')
    if incident['severity'] not in {'low', 'medium', 'high'}:
        raise ValueError('invalid severity')
    position = incident['position']
    if not isinstance(position, dict) or set(position) != {'latitude', 'longitude'}:
        raise ValueError('invalid position')
    for coordinate in position.values():
        if isinstance(coordinate, bool) or not isinstance(coordinate, (int, float)):
            raise ValueError('invalid coordinate')
    if not isinstance(incident['summary'], str) or not incident['summary']:
        raise ValueError('invalid summary')

def serialize_incident(incident: dict) -> bytes:
    try:
        _validate(incident)
        return json.dumps(incident, ensure_ascii=False, separators=(',', ':')).encode('utf-8')
    except Exception as exc:
        raise ValueError('invalid incident') from exc

def deserialize_incident(payload: bytes) -> dict:
    try:
        if not isinstance(payload, bytes):
            raise ValueError('payload must be bytes')
        incident = json.loads(payload.decode('utf-8'))
        _validate(incident)
        return incident
    except Exception as exc:
        raise ValueError('invalid payload') from exc

