def render_weather_report(records: list[dict[str, object]], page: int=1, per_page: int=10) -> str:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(per_page, bool) or not isinstance(per_page, int) or per_page < 1:
        raise ValueError('invalid per_page')
    grouped = {}
    for record in records:
        if not isinstance(record, dict) or set(record) != {'station', 'temperature_c', 'recorded_at'}:
            raise ValueError('invalid record')
        station = record['station']
        temperature = record['temperature_c']
        recorded_at = record['recorded_at']
        if not isinstance(station, str) or not station:
            raise ValueError('invalid station')
        if isinstance(temperature, bool) or not isinstance(temperature, (int, float)) or (not math.isfinite(temperature)):
            raise ValueError('invalid temperature')
        if not isinstance(recorded_at, str):
            raise ValueError('invalid timestamp')
        try:
            parsed = datetime.datetime.fromisoformat(recorded_at)
        except ValueError:
            raise ValueError('invalid timestamp')
        grouped.setdefault(station, []).append((temperature, recorded_at, parsed))
    stations = []
    for station, values in grouped.items():
        latest = values[0]
        for value in values[1:]:
            if value[2] >= latest[2]:
                latest = value
        average = sum((value[0] for value in values)) / len(values)
        stations.append((station, len(values), average, latest[1], latest[2]))
    stations.sort(key=lambda item: (-item[2], item[0]))
    total = len(stations)
    start = (page - 1) * per_page
    selected = stations[start:start + per_page]
    rows = ''.join((f'<tr><td>{html.escape(station, quote=True)}</td><td>{count}</td><td>{average:.1f}</td><td>{html.escape(latest, quote=True)}</td></tr>' for station, count, average, latest, _ in selected))
    return f'<section class="weather-report"><h1>Weather stations</h1><p class="summary">Showing {len(selected)} of {total} stations</p><table><thead><tr><th>Station</th><th>Readings</th><th>Average (°C)</th><th>Latest reading</th></tr></thead><tbody>{rows}</tbody></table></section>'

