import json
from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def dump_statement(transactions: list[dict]) -> bytes:
    try:
        return json.dumps(transactions, separators=(',', ':')).encode('utf-8')
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid statement') from exc

def statement_page(blob: bytes, account_id: str, month: str, page: int, page_size: int) -> dict:
    try:
        value = json.loads(blob.decode('utf-8'))
    except (Exception,) as exc:
        raise ValueError('invalid statement') from exc
    if not isinstance(value, list):
        raise ValueError('invalid statement')
    if not isinstance(month, str) or len(month) != 7 or month[4] != '-':
        raise ValueError('invalid month')
    try:
        y, m = (int(month[:4]), int(month[5:]))
        if date(y, m, 1).strftime('%Y-%m') != month:
            raise ValueError
    except Exception as exc:
        raise ValueError('invalid month') from exc
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    fields = {'id', 'account_id', 'date', 'description', 'amount'}
    matches = []
    total_amount = Decimal('0')
    for item in value:
        if not isinstance(item, dict) or set(item) != fields:
            raise ValueError('invalid transaction')
        if not all((isinstance(item[k], str) for k in fields)):
            raise ValueError('invalid transaction')
        try:
            parsed_date = date.fromisoformat(item['date'])
            if parsed_date.strftime('%Y-%m-%d') != item['date']:
                raise ValueError
            amount = Decimal(item['amount'])
            if not amount.is_finite():
                raise ValueError
        except (InvalidOperation, ValueError) as exc:
            raise ValueError('invalid transaction') from exc
        if item['account_id'] == account_id and item['date'].startswith(month):
            matches.append(item)
            total_amount += amount
    matches.sort(key=lambda x: (x['date'], x['id']))
    start = (page - 1) * page_size
    selected = matches[start:start + page_size]
    formatted = total_amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    return {'account_id': account_id, 'month': month, 'transactions': selected, 'total': len(matches), 'total_amount': format(formatted, '.2f')}

