from datetime import date, timedelta
from decimal import Decimal, InvalidOperation
import html

def parse_preorder_line(line: str) -> dict[str, object]:
    fields = []
    current = []
    i = 0
    while i < len(line):
        ch = line[i]
        if ch == '\\':
            i += 1
            if i == len(line) or line[i] not in '\\|':
                raise ValueError('invalid escape')
            current.append(line[i])
        elif ch == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(ch)
        i += 1
    fields.append(''.join(current))
    if len(fields) != 6 or not fields[0] or (not fields[1]):
        raise ValueError('invalid fields')
    try:
        d = date.fromisoformat(fields[2])
        q = int(fields[3])
        price = Decimal(fields[4])
    except (ValueError, InvalidOperation):
        raise ValueError('invalid value')
    if fields[2] != d.isoformat() or q <= 0 or price < 0 or (price.as_tuple().exponent < -2):
        raise ValueError('invalid value')
    if fields[5] not in {'pending', 'confirmed', 'cancelled'}:
        raise ValueError('invalid status')
    return {'customer': fields[0], 'title': fields[1], 'date': d, 'quantity': q, 'unit_price': price, 'status': fields[5]}

def summarize_preorders(records: list[dict[str, object]], as_of: str) -> list[dict[str, object]]:
    try:
        origin = date.fromisoformat(as_of)
    except ValueError:
        raise ValueError('invalid date')
    if as_of != origin.isoformat():
        raise ValueError('invalid date')
    groups = {}
    for record in records:
        if record['status'] == 'cancelled':
            continue
        key = (record['customer'], record['title'])
        if key not in groups:
            groups[key] = {'customer': record['customer'], 'title': record['title'], 'date': record['date'], 'quantity': 0, 'total': Decimal('0.00'), 'status': record['status']}
        item = groups[key]
        item['quantity'] += record['quantity']
        item['total'] += record['quantity'] * record['unit_price']
        if record['date'] <= item['date']:
            if record['date'] < item['date'] or True:
                item['date'] = record['date']
                item['status'] = record['status']
    result = []
    for item in groups.values():
        delta = (item['date'] - origin).days
        bucket = 'overdue' if delta < 0 else 'soon' if delta <= 7 else 'later'
        item['bucket'] = bucket
        result.append(item)
    order = {'overdue': 0, 'soon': 1, 'later': 2}
    return sorted(result, key=lambda x: (order[x['bucket']], x['date'], x['customer'].casefold(), x['title'].casefold(), x['customer'], x['title']))

def render_preorder_report(records: list[dict[str, object]], as_of: str) -> str:
    rows = []
    for item in summarize_preorders(records, as_of):
        customer = html.escape(str(item['customer']), quote=True)
        title = html.escape(str(item['title']), quote=True)
        rows.append(f"<tr><td>{customer}</td><td>{title}</td><td>{item['date']:%Y-%m-%d}</td><td>{item['quantity']}</td><td>${item['total']:.2f}</td><td>{item['status']}</td><td>{item['bucket']}</td></tr>")
    return f"""<section class="preorders"><h1>Preorders as of {as_of}</h1><table><thead><tr><th>Customer</th><th>Title</th><th>Date</th><th>Quantity</th><th>Total</th><th>Status</th><th>Bucket</th></tr></thead><tbody>{''.join(rows)}</tbody></table></section>"""

