import json

def serialize_tracking_state(state: dict[str, object]) -> bytes:
    if not isinstance(state, dict):
        raise TypeError('state must be a dictionary')
    try:
        return json.dumps(state, ensure_ascii=False, separators=(',', ':')).encode('utf-8')
    except (TypeError, ValueError) as exc:
        raise TypeError('state contains unsupported values') from exc

def load_tracking_state(blob: bytes) -> dict[str, object]:
    if not isinstance(blob, bytes):
        raise TypeError('blob must be bytes')
    try:
        value = json.loads(blob.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid tracking payload') from exc
    if not isinstance(value, dict):
        raise ValueError('tracking payload must contain a dictionary')
    return value

