    active.sort(key=lambda r: (str(r['school']).casefold(), str(r['product']).casefold(), str(r['holder']).casefold()))
    total = len(active)
    total_seats = sum((int(r['seats']) for r in active))
    total_cost = sum((Decimal(str(r['seats'])) * Decimal(str(r['monthly_price'])) for r in active))
    total_cost = total_cost.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    start = (page - 1) * per_page
    shown = active[start:start + per_page]
    if shown:
