def summarize_cases(blob: bytes, status: str | None=None, tag: str | None=None, page: int=1, page_size: int=20) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    try:
        data = json.loads(blob.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid blob') from exc
    if not isinstance(data, dict) or not isinstance(data.get('cases'), list):
        raise ValueError('invalid state')
    cases = data['cases']
    for case in cases:
        if not isinstance(case, dict):
            raise ValueError('invalid case')
        if any((key not in case for key in ('id', 'status', 'priority', 'opened_days', 'tags'))):
