import json

def encode_state(state: dict) -> bytes:
    if not isinstance(state, dict):
        raise ValueError('state must be an object')
    try:
        return json.dumps(state, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode('utf-8')
    except (TypeError, ValueError, UnicodeEncodeError) as exc:
        raise ValueError('invalid state') from exc

def decode_state(blob: bytes) -> dict:
    if not isinstance(blob, bytes):
        raise ValueError('blob must be bytes')
    try:
        value = json.loads(blob.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid document') from exc
    if not isinstance(value, dict):
        raise ValueError('state must be an object')
    return value

def process_traffic(events: list[dict], quotas: dict[str, int], state: dict) -> tuple[list[dict], dict]:
    if not isinstance(quotas, dict) or not isinstance(state, dict):
        raise ValueError('invalid containers')
    for name, target in quotas.items():
        if not isinstance(name, str) or not isinstance(target, int) or isinstance(target, bool) or (target < 0):
            raise ValueError('invalid quota')
    seen = state.get('seen', [])
    totals = state.get('totals', {})
    if not isinstance(seen, list) or not isinstance(totals, dict):
        raise ValueError('invalid state')
    if any((not isinstance(x, str) for x in seen)):
        raise ValueError('invalid IDs')
    if any((not isinstance(k, str) or not isinstance(v, int) or isinstance(v, bool) or (v < 0) for k, v in totals.items())):
        raise ValueError('invalid totals')
    seen_out = list(seen)
    totals_out = dict(totals)
    known = set(seen_out)
    for event in events:
        if not isinstance(event, dict) or not all((key in event for key in ('id', 'campaign', 'timestamp', 'impressions'))):
            raise ValueError('invalid event')
        ident = event['id']
        campaign = event['campaign']
        timestamp = event['timestamp']
        amount = event['impressions']
        if not isinstance(ident, str) or not isinstance(campaign, str) or (not isinstance(timestamp, int)) or isinstance(timestamp, bool) or (not isinstance(amount, int)) or isinstance(amount, bool) or (amount < 0):
            raise ValueError('invalid event')
        if ident in known or campaign not in quotas:
            continue
        known.add(ident)
        seen_out.append(ident)
        totals_out[campaign] = totals_out.get(campaign, 0) + amount
    rows = []
    for campaign, target in quotas.items():
        delivered = totals_out.get(campaign, 0)
        deficit = max(target - delivered, 0)
        rows.append({'campaign': campaign, 'delivered': delivered, 'target': target, 'deficit': deficit, 'status': 'under' if delivered < target else 'met'})
    rows.sort(key=lambda row: (-row['deficit'], row['campaign']))
    return (rows, {'seen': seen_out, 'totals': totals_out})

