def render_alert_report(alerts: list[dict], page: int=1, page_size: int=10) -> str:
    if page <= 0 or page_size <= 0:
        raise ValueError('invalid pagination')
    severities = {'critical': 0, 'high': 1, 'medium': 2, 'low': 3}
    active = []
    required = ('id', 'title', 'message', 'severity', 'region', 'created_at', 'acknowledged')
    for alert in alerts:
        if not isinstance(alert, dict) or any((k not in alert for k in required)):
            raise ValueError('invalid alert')
        if not all((isinstance(alert[k], str) for k in required[:-1])):
            raise ValueError('invalid alert')
        if not isinstance(alert['acknowledged'], bool) or alert['severity'] not in severities:
            raise ValueError('invalid alert')
        try:
            stamp = datetime.fromisoformat(alert['created_at'])
        except (TypeError, ValueError):
            raise ValueError('invalid alert')
        if not alert['acknowledged']:
            active.append((alert, stamp))
    active.sort(key=lambda x: (severities[x[0]['severity']], -x[1].timestamp(), x[0]['id']))
    total = len(active)
    pages = max(1, (total + page_size - 1) // page_size)
    if page > pages:
        raise ValueError('invalid pagination')
    start_index = (page - 1) * page_size
    selected = active[start_index:start_index + page_size]
    start = start_index + 1 if total else 0
    end = start_index + len(selected) if total else 0
    rows = []
    for alert, _ in selected:
        values = [alert['id'], alert['title'], alert['severity'], alert['region'], alert['created_at'], alert['message']]
        rows.append('<tr>' + ''.join(('<td>' + escape(value, quote=True) + '</td>' for value in values)) + '</tr>')
    return f'<section class="alert-report"><h1>Emergency Alerts</h1><p class="summary">Showing {start}-{end} of {total} active alerts (page {page} of {pages})</p><table><thead><tr><th>ID</th><th>Title</th><th>Severity</th><th>Region</th><th>Created</th><th>Message</th></tr></thead><tbody>' + ''.join(rows) + '</tbody></table></section>'

