import json
import re

def encode_document_state(state: dict) -> bytes:
    return json.dumps(state, separators=(',', ':'), ensure_ascii=False).encode('utf-8')

def load_document_page(payload: bytes, page: int, page_size: int) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    try:
        state = json.loads(payload.decode('utf-8'))
        if not isinstance(state, dict) or not isinstance(state.get('project'), str) or (not isinstance(state.get('sheets'), list)):
            raise ValueError
        sheets = state['sheets']
        for sheet in sheets:
            if not isinstance(sheet, dict) or not all((isinstance(sheet.get(k), t) for k, t in {'number': str, 'discipline': str, 'title': str, 'status': str}.items())) or (not isinstance(sheet.get('area'), (int, float))) or isinstance(sheet.get('area'), bool):
                raise ValueError
    except (ValueError, TypeError, UnicodeError, AttributeError, json.JSONDecodeError):
        raise ValueError('invalid payload')

    def key(sheet):
        match = re.match('^(.*?)-(\\d+)$', sheet['number'])
        if match:
            number_key = (match.group(1), int(match.group(2)))
        else:
            number_key = (sheet['number'], -1)
        return (sheet['discipline'], number_key, sheet['title'])
    ordered = sorted(sheets, key=key)
    statuses = {}
    for sheet in ordered:
        statuses[sheet['status']] = statuses.get(sheet['status'], 0) + 1
    start = (page - 1) * page_size
    return {'project': state['project'], 'total_sheets': len(ordered), 'total_area': round(sum((sheet['area'] for sheet in ordered)), 2), 'statuses': dict(sorted(statuses.items())), 'sheets': ordered[start:start + page_size]}

