import csv
import datetime
import io
_HEADER = ['id', 'applicant', 'borough', 'bedrooms', 'priority', 'submitted']

def parse_waitlist(text: str) -> list[dict]:
    if text == '':
        return []
    reader = csv.DictReader(io.StringIO(text))
    if reader.fieldnames != _HEADER:
        raise ValueError('invalid header')
    result = []
    seen = set()
    for row in reader:
        if None in row or any((row[key] is None for key in _HEADER)):
            raise ValueError('malformed record')
        values = {key: row[key].strip() for key in _HEADER}
        if not values['id'] or not values['applicant'] or (not values['borough']):
            raise ValueError('blank field')
        if values['id'] in seen:
            raise ValueError('duplicate id')
        try:
            bedrooms = int(values['bedrooms'])
            priority = int(values['priority'])
            datetime.date.fromisoformat(values['submitted'])
        except Exception as exc:
            raise ValueError('invalid value') from exc
        if not 0 <= bedrooms <= 8 or not 0 <= priority <= 100:
            raise ValueError('out of range')
        seen.add(values['id'])
        result.append({'id': values['id'], 'applicant': values['applicant'], 'borough': values['borough'], 'bedrooms': bedrooms, 'priority': priority, 'submitted': values['submitted']})
    return result

def rank_waitlist(rows: list[dict], offer_slots: int) -> list[dict]:
    if not isinstance(offer_slots, int) or offer_slots < 0 or offer_slots > len(rows):
        raise ValueError('invalid offer slots')
    ordered = sorted(rows, key=lambda r: (-r['priority'], r['submitted'], r['id']))
    result = []
    for number, row in enumerate(ordered, 1):
        item = dict(row)
        item['position'] = number
        item['status'] = 'offered' if number <= offer_slots else 'waiting'
        result.append(item)
    return result

def render_waitlist(rows: list[dict], title: str, page: int=1, per_page: int=20) -> str:
    if page < 1 or per_page < 1 or per_page > 100:
        raise ValueError('invalid page')
    total = len(rows)
    pages = max(1, (total + per_page - 1) // per_page)
    if page > pages:
        raise ValueError('page out of range')
    start_index = (page - 1) * per_page
    selected = rows[start_index:start_index + per_page]
    start = start_index + 1 if selected else 0
    end = start_index + len(selected) if selected else 0
    body = ''.join(('<tr><td>%s</td><td>%s</td><td>%s</td><td>%s</td><td>%s</td><td>%s</td><td>%s</td></tr>' % tuple((str(item[key]) for key in ('position', 'applicant', 'borough', 'bedrooms', 'priority', 'submitted', 'status'))) for item in selected))
    return '<div class="waitlist">\n<h1>%s</h1>\n<p class="summary">Showing %d-%d of %d applicants</p>\n<table>\n<thead><tr><th>Position</th><th>Applicant</th><th>Borough</th><th>Bedrooms</th><th>Priority</th><th>Submitted</th><th>Status</th></tr></thead>\n<tbody>%s</tbody>\n</table>\n</div>' % (str(title), start, end, total, body)

