import html
import math
import re

def parse_sample_code(code: str) -> dict:
    if not isinstance(code, str):
        raise ValueError('invalid code')
    match = re.fullmatch('([A-Z]{2})-(\\d{4})-(\\d{4})', code)
    if match is None:
        raise ValueError('invalid code')
    return {'site': match.group(1), 'year': int(match.group(2)), 'sequence': int(match.group(3))}

def summarize_samples(samples: list[dict], window: int=3) -> list[dict]:
    if not isinstance(samples, list) or not samples or (not isinstance(window, int)) or isinstance(window, bool) or (window <= 0):
        raise ValueError('invalid samples')
    result = []
    seen = set()
    for sample in samples:
        if not isinstance(sample, dict) or not all((k in sample for k in ('code', 'organism', 'status', 'readings'))):
            raise ValueError('invalid sample')
        code = sample['code']
        parse_sample_code(code)
        if code in seen or not isinstance(sample['organism'], str) or (not isinstance(sample['status'], str)):
            raise ValueError('invalid sample')
        readings = sample['readings']
        if not isinstance(readings, (list, tuple)) or not readings:
            raise ValueError('invalid readings')
        if any((isinstance(x, bool) or not isinstance(x, (int, float)) or (not math.isfinite(x)) for x in readings)):
            raise ValueError('invalid readings')
        seen.add(code)
        average = sum(readings[-window:]) / min(window, len(readings))
        peak = max(readings)
        result.append({'code': code, 'organism': sample['organism'], 'status': sample['status'], 'classification': 'alert' if average >= 10 else 'normal', 'window_average': round(average, 2), 'peak': round(peak, 2), 'reading_count': len(readings)})
    result.sort(key=lambda x: (0 if x['classification'] == 'alert' else 1, x['organism'].casefold(), x['code']))
    return result

def render_report(rows: list[dict], title: str='Sample Report') -> str:
    if not isinstance(rows, list) or not isinstance(title, str):
        raise ValueError('invalid report')
    esc = lambda value: html.escape(str(value), quote=True)
    body = []
    for row in rows:
        body.append('<tr><td>' + esc(row['code']) + '</td><td>' + esc(row['organism']) + '</td><td>' + esc(row['status']) + '</td><td>' + esc(row['classification']) + '</td><td>' + format(row['window_average'], '.2f') + '</td><td>' + format(row['peak'], '.2f') + '</td><td>' + esc(row['reading_count']) + '</td></tr>')
    headers = '<tr><th>Code</th><th>Organism</th><th>Status</th><th>Class</th><th>Window average</th><th>Peak</th><th>Readings</th></tr>'
    return '<section><h1>' + esc(title) + '</h1><table><thead>' + headers + '</thead><tbody>' + ''.join(body) + '</tbody></table></section>'

