def index_microscopy_images(api_url: str, specimen_ids: list[str], min_score: float=0.0, page_size: int=100) -> list[dict]:
    if not isinstance(api_url, str) or not api_url:
        raise ValueError('api_url')
    if any((not isinstance(x, str) or not x for x in specimen_ids)):
        raise ValueError('specimen_ids')
    if not isinstance(min_score, (int, float)) or not 0 <= min_score <= 1:
        raise ValueError('min_score')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 500):
        raise ValueError('page_size')
    ids = list(dict.fromkeys(specimen_ids))
    if not ids:
        return []
    groups = {}
    page = 1
    while True:
        r = requests.get(api_url.rstrip('/') + '/v1/images', params={'specimen_ids': ','.join(ids), 'min_score': min_score, 'page': page, 'page_size': page_size}, headers={'Accept': 'application/json'}, verify=True)
        if r.status_code != 200:
            raise RuntimeError('image service returned an error')
        payload = r.json()
        for image in payload.get('images', []):
            if image['specimen_id'] in ids and image['quality_score'] >= min_score:
                groups.setdefault(image['specimen_id'], []).append(image)
        if not payload.get('next'):
            break
        page += 1
    result = []
    for specimen_id in sorted(groups):
        images = sorted(groups[specimen_id], key=lambda x: (-x['quality_score'], x['id']))
        mean = round(sum((x['quality_score'] for x in images)) / len(images), 2)
        result.append({'specimen_id': specimen_id, 'count': len(images), 'image_ids': [x['id'] for x in images], 'mean_score': mean})
    return result

