def _split_escaped(value, delimiter):
    parts = []
    current = []
    escaped = False
    for char in value:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == delimiter:
            parts.append(''.join(current))
