    output = []
    seen = set()
    for line in text.splitlines():
        if not line.strip():
            continue
        try:
            item = json.loads(line)
        except Exception as exc:
            raise ValueError('invalid JSON') from exc
        if not isinstance(item, dict) or not required.issubset(item):
            raise ValueError('invalid record')
        if any((not isinstance(item[k], str) for k in ('id', 'timestamp', 'title', 'body'))):
            raise ValueError('invalid record')
        if not isinstance(item['tags'], list) or any((not isinstance(x, str) for x in item['tags'])):
            raise ValueError('invalid record')
        if item['id'] in seen:
            raise ValueError('duplicate id')
        seen.add(item['id'])
        output.append(item)
    return output

def build_index(documents: list[dict]) -> dict:
    docs = {}
    terms = {}
    token = re.compile('[A-Za-z0-9]+')
    for doc in documents:
        ident = doc['id']
        if ident in docs:
            raise ValueError('duplicate id')
        docs[ident] = doc
        counts = {}
        for word in token.findall(doc['title'].lower()):
            counts[word] = counts.get(word, 0) + 3
        for word in token.findall(doc['body'].lower()):
            counts[word] = counts.get(word, 0) + 1
        for word, count in counts.items():
            terms.setdefault(word, {})[ident] = count
    return {'docs': list(docs.values()), 'terms': terms}

def search(index: dict, query: str, limit: int=10) -> list[dict]:
