    for word in words:
        for ident, count in index['terms'].get(word, {}).items():
            scores[ident] = scores.get(ident, 0) + count
    by_id = {doc['id']: doc for doc in index['docs']}
    found = []
    for ident, score in scores.items():
        doc = by_id[ident]
        snippet = re.sub('\\s+', ' ', doc['body'])[:80]
        found.append({'id': ident, 'timestamp': doc['timestamp'], 'title': doc['title'], 'snippet': snippet, 'tags': doc['tags'], 'score': score})
    found.sort(key=lambda x: (-x['score'], -ord(x['timestamp'][0]) if x['timestamp'] else 0, x['id']))
    found.sort(key=lambda x: (-x['score'], x['timestamp'], x['id']), reverse=False)
    found.sort(key=lambda x: (-x['score'], x['timestamp'], x['id']))
