from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from html import escape

def render_usage_report(customer: str, records: list[dict], page: int=1, page_size: int=10) -> str:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    grouped = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        try:
            service = record['service']
            units = record['units']
            raw_rate = record['rate']
        except KeyError as exc:
            raise ValueError('invalid record') from exc
        if not isinstance(service, str) or not service:
            raise ValueError('invalid service')
        if isinstance(units, bool) or not isinstance(units, int) or units < 0:
            raise ValueError('invalid units')
        try:
            rate = Decimal(str(raw_rate))
        except (InvalidOperation, ValueError, TypeError):
            raise ValueError('invalid rate')
        if not rate.is_finite() or rate < 0:
            raise ValueError('invalid rate')
        if service in grouped and grouped[service][0] != rate:
            raise ValueError('inconsistent rate')
        if service not in grouped:
            grouped[service] = [rate, 0]
        grouped[service][1] += units
    entries = []
    for service, (rate, units) in grouped.items():
        cost = (rate * units).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        entries.append((service, units, cost))
    entries.sort(key=lambda item: (-item[2], item[0]))
    total = sum((item[2] for item in entries), Decimal('0.00'))
    page_count = max(1, (len(entries) + page_size - 1) // page_size)
    start = (page - 1) * page_size
    selected = entries[start:start + page_size]
    rows = ''.join((f'<tr><td>{escape(service)}</td><td>{units}</td><td>${cost:.2f}</td></tr>' for service, units, cost in selected))
    return f'<div class="usage-report"><h1>Usage for {escape(customer)}</h1><table><thead><tr><th>Service</th><th>Units</th><th>Cost</th></tr></thead><tbody>{rows}</tbody><tfoot><tr><td colspan="2">Total</td><td>${total:.2f}</td></tr></tfoot></table><p class="page">Page {page} of {page_count}</p></div>'

