import csv
import html
import io

def parse_surveys(text: str) -> list[dict[str, object]]:
    if not text.strip():
        raise ValueError('empty input')
    reader = csv.reader(io.StringIO(text))
    try:
        header = next(reader)
    except StopIteration:
        raise ValueError('empty input')
    if header != ['year', 'site', 'species', 'count', 'observer']:
        raise ValueError('invalid header')
    result = []
    for row in reader:
        if not row or all((not x.strip() for x in row)):
            continue
        if len(row) != 5:
            raise ValueError('invalid row')
        year_text, site, species, count_text, observer = [x.strip() for x in row]
        try:
            year = int(year_text)
            count = int(count_text)
        except ValueError:
            raise ValueError('invalid number')
        if not 1900 <= year <= 2100 or count < 0:
            raise ValueError('invalid value')
        if not site or not species or (not observer):
            raise ValueError('empty field')
        result.append({'year': year, 'site': site, 'species': species, 'count': count, 'observer': observer})
    return result

def summarize_populations(rows: list[dict[str, object]], window: int=3) -> list[dict[str, object]]:
    if not isinstance(window, int) or isinstance(window, bool) or window <= 0:
        raise ValueError('invalid window')
    grouped = {}
    for row in rows:
        species = row['species']
        year = row['year']
        grouped.setdefault(species, {})[year] = grouped.setdefault(species, {}).get(year, 0) + row['count']
    output = []
    for species in sorted(grouped):
        values = grouped[species]
        first, last = (min(values), max(values))
        years = []
        for year in range(first, last + 1):
            count = values.get(year, 0)
            prior = [values.get(y, 0) for y in range(max(first, year - window + 1), year + 1)]
            years.append({'year': year, 'count': count, 'rolling_average': round(sum(prior) / len(prior), 2)})
        output.append({'species': species, 'years': years})
    return output

def render_report(rows: list[dict[str, object]], title: str='Wildlife Survey Report') -> str:
    ordered = sorted(rows, key=lambda r: (r['year'], r['site'], r['species'], r['observer']))
    cells = []
    total = 0
    for row in ordered:
        total += row['count']
        cells.append('<tr><td>' + '</td><td>'.join((html.escape(str(row[key]), quote=True) for key in ('year', 'site', 'species', 'count', 'observer'))) + '</td></tr>')
    return '<section class="survey-report"><h1>' + html.escape(str(title), quote=True) + '</h1><table><thead><tr><th>Year</th><th>Site</th><th>Species</th><th>Count</th><th>Observer</th></tr></thead><tbody>' + ''.join(cells) + '</tbody></table><p class="total">Total animals counted: ' + str(total) + '</p></section>'

