import math

def encode_readings(readings: list[dict]) -> bytes:
    return json.dumps(readings, separators=(',', ':'), allow_nan=False).encode('utf-8')

def summarize_snapshot(blob: bytes, page: int=1, page_size: int=20) -> dict:
    if page <= 0 or page_size <= 0:
        raise ValueError('invalid pagination')
    try:
        readings = json.loads(blob.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(readings, list):
        raise ValueError('readings must be a list')
    groups = {}
    for reading in readings:
        if not isinstance(reading, dict) or set(reading) != {'buoy', 'timestamp', 'temperature', 'salinity'}:
            raise ValueError('invalid reading')
        buoy = reading['buoy']
        timestamp = reading['timestamp']
        temperature = reading['temperature']
        salinity = reading['salinity']
        if not isinstance(buoy, str) or isinstance(timestamp, bool) or (not isinstance(timestamp, int)) or isinstance(temperature, bool) or (not isinstance(temperature, (int, float))) or isinstance(salinity, bool) or (not isinstance(salinity, (int, float))) or (not math.isfinite(float(temperature))) or (not math.isfinite(float(salinity))):
            raise ValueError('invalid reading')
        groups.setdefault(buoy, []).append((temperature, salinity))
    summaries = []
    for buoy in sorted(groups):
        values = groups[buoy]
        temperatures = [value[0] for value in values]
        salinities = [value[1] for value in values]
        summaries.append({'buoy': buoy, 'count': len(values), 'avg_temperature': round(sum(temperatures) / len(values), 2), 'min_salinity': round(min(salinities), 2), 'max_salinity': round(max(salinities), 2)})
    start = (page - 1) * page_size
    return {'total': len(summaries), 'page': page, 'page_size': page_size, 'items': summaries[start:start + page_size]}

