import json
from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def _number(value):
    if isinstance(value, bool):
        raise ValueError('number required')
    try:
        x = Decimal(str(value))
    except (InvalidOperation, ValueError):
        raise ValueError('number required')
    if not x.is_finite() or x < 0:
        raise ValueError('bad number')
    return x

def _day(value):
    try:
        return date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('bad date')

def _money(value):
    return float(value.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))

def generate_bills(readings, plans, start, end):
    lo, hi = (_day(start), _day(end))
    if lo > hi or not isinstance(readings, list) or (not isinstance(plans, dict)):
        raise ValueError('bad input')
    grouped = {}
    for row in readings:
        if not isinstance(row, dict) or not isinstance(row.get('customer'), str) or (not row['customer']):
            raise ValueError('bad reading')
        d = _day(row.get('date'))
        meter = _number(row.get('meter'))
        if lo <= d <= hi:
            grouped.setdefault(row['customer'], []).append((d, meter))
    output = []
    for customer, rows in grouped.items():
        if len(rows) < 2:
            continue
        rows.sort(key=lambda x: x[0])
        if len({d for d, _ in rows}) != len(rows) or any((rows[i][1] < rows[i - 1][1] for i in range(1, len(rows)))):
            raise ValueError('bad meter sequence')
        plan = plans.get(customer)
        if not isinstance(plan, dict):
            raise ValueError('missing plan')
        fixed = _number(plan.get('fixed'))
        tiers = plan.get('tiers')
        if not isinstance(tiers, list) or not tiers:
            raise ValueError('bad tiers')
        usage = rows[-1][1] - rows[0][1]
        energy = Decimal(0)
        previous = Decimal(0)
        remaining = usage
        open_ended = False
        for tier in tiers:
            if not isinstance(tier, dict):
                raise ValueError('bad tier')
            rate = _number(tier.get('rate'))
            upto = tier.get('upto')
            if upto is None:
                if open_ended:
                    raise ValueError('bad tiers')
                amount = remaining
                open_ended = True
            else:
                limit = _number(upto)
                if limit <= previous:
                    raise ValueError('bad tiers')
                amount = min(remaining, limit - previous)
                previous = limit
            energy += amount * rate
            remaining -= amount
            if remaining <= 0:
                break
        if remaining > 0:
            raise ValueError('tiers do not cover usage')
        item = {'customer': customer, 'usage': _money(usage), 'energy': _money(energy), 'fixed': _money(fixed), 'total': _money(energy + fixed)}
        output.append(item)
    output.sort(key=lambda x: (-x['total'], x['customer']))
    return output

def encode_billing_state(state):
    if not isinstance(state, dict):
        raise ValueError('state must be an object')
    try:
        return json.dumps(state, sort_keys=True, separators=(',', ':'), allow_nan=False).encode('utf-8')
    except (TypeError, ValueError, UnicodeError):
        raise ValueError('invalid state')

def decode_billing_state(blob):
    if not isinstance(blob, (bytes, bytearray)):
        raise ValueError('invalid state')
    try:
        value = json.loads(bytes(blob).decode('utf-8'))
    except (ValueError, UnicodeError):
        raise ValueError('invalid state')
    if not isinstance(value, dict):
        raise ValueError('invalid state')
    return value

