from html import escape
_STATUSES = ('active', 'repair', 'retired')
_FIELDS = {'id', 'site_a', 'site_b', 'status', 'strands', 'length_km'}

def _checked(records):
    seen = set()
    for record in records:
        if not isinstance(record, dict) or set(record) != _FIELDS:
            raise ValueError('invalid record')
        if not isinstance(record['id'], str) or not record['id'] or record['id'] in seen:
            raise ValueError('invalid id')
        if not all((isinstance(record[x], str) for x in ('site_a', 'site_b', 'status'))):
            raise ValueError('invalid text')
        if record['status'] not in _STATUSES:
            raise ValueError('invalid status')
        if isinstance(record['strands'], bool) or not isinstance(record['strands'], int) or record['strands'] <= 0:
            raise ValueError('invalid strands')
        if isinstance(record['length_km'], bool) or not isinstance(record['length_km'], (int, float)) or record['length_km'] < 0:
            raise ValueError('invalid length')
        seen.add(record['id'])
    return list(records)

def summarize_inventory(records):
    records = _checked(records)
    out = []
    for status in _STATUSES:
        group = [r for r in records if r['status'] == status]
        if group:
            out.append({'status': status, 'count': len(group), 'strands': sum((r['strands'] for r in group)), 'length_km': round(sum((r['length_km'] for r in group)), 2)})
    return out

def render_inventory_report(records, title):
    records = _checked(records)
    rows = []
    for r in sorted(records, key=lambda x: (x['site_a'].lower(), x['site_b'].lower(), x['id'])):
        vals = [r['id'], r['site_a'] + ' → ' + r['site_b'], r['status'], r['strands'], f"{r['length_km']:.2f}"]
        rows.append('<tr>' + ''.join((f'<td>{escape(str(v), quote=True)}</td>' for v in vals)) + '</tr>')
    total_length = sum((r['length_km'] for r in records))
    return f"""<section class="inventory"><h1>{escape(title, quote=True)}</h1><table><thead><tr><th>ID</th><th>Route</th><th>Status</th><th>Strands</th><th>Length (km)</th></tr></thead><tbody>{''.join(rows)}</tbody><tfoot><tr><th colspan="2">TOTAL</th><td>{len(records)}</td><td>{sum((r['strands'] for r in records))}</td><td>{total_length:.2f}</td></tr></tfoot></table></section>"""

