def fetch_calls(account_id: str, start: str, end: str) -> list[dict]:
    response = requests.get('https://telephony.example.test/v1/calls', params={'account_id': account_id, 'start': start, 'end': end}, headers={'Accept': 'application/json'}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError(f'call service returned HTTP {response.status_code}')
    try:
        value = response.json()
    except Exception as exc:
        raise RuntimeError('call service returned invalid JSON') from exc
    if not isinstance(value, dict) or not isinstance(value.get('calls'), list):
        raise RuntimeError('call service returned an invalid call list')
    return value['calls']

