    groups = {}
    for call in calls:
        stamp = call['started_at']
        if stamp.endswith('Z'):
            stamp = stamp[:-1] + '+00:00'
        date = datetime.fromisoformat(stamp).astimezone(timezone.utc).date().isoformat()
        key = (date, call['agent'])
        if key not in groups:
            groups[key] = [0, 0, 0.0]
        groups[key][0] += 1
        groups[key][1] += call['status'] == 'completed'
        groups[key][2] += float(call['duration'])
    result = []
    for (date, agent), (count, answered, total) in sorted(groups.items()):
        total = round(total, 2)
        result.append({'date': date, 'agent': agent, 'calls': count, 'answered': answered, 'total_seconds': total, 'average_seconds': round(total / count, 2)})
    return result

