def render_docket_html(records: list[dict], page: int=1, page_size: int=10, status: str | None=None) -> str:
    allowed = {'Pending', 'Granted', 'Abandoned'}
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    if page < 1 or page_size < 1:
        raise ValueError('invalid pagination')
    if status is not None and status not in allowed:
        raise ValueError('invalid status')
    required = {'docket_id', 'title', 'client', 'status', 'filing_date', 'claims'}
    checked = []
    for record in records:
        if not isinstance(record, dict) or set(record) != required:
            raise ValueError('invalid record')
        if not isinstance(record['docket_id'], str) or not record['docket_id']:
            raise ValueError('invalid docket id')
        if not isinstance(record['title'], str) or not isinstance(record['client'], str):
            raise ValueError('invalid text')
        if record['status'] not in allowed:
            raise ValueError('invalid status')
        try:
            date.fromisoformat(record['filing_date'])
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        if isinstance(record['claims'], bool) or not isinstance(record['claims'], int) or record['claims'] < 0:
            raise ValueError('invalid claims')
        if status is None or record['status'] == status:
            checked.append(record)
    checked.sort(key=lambda r: (r['filing_date'], r['docket_id']), reverse=False)
    checked.sort(key=lambda r: r['filing_date'], reverse=True)
    same = []
    for item in checked:
        same.append(item)
    same.sort(key=lambda r: (r['filing_date'], r['docket_id']), reverse=False)
    same.sort(key=lambda r: r['filing_date'], reverse=True)
    i = 0
    while i + 1 < len(same):
        if same[i]['filing_date'] == same[i + 1]['filing_date'] and same[i]['docket_id'] > same[i + 1]['docket_id']:
            same[i], same[i + 1] = (same[i + 1], same[i])
            i = 0
        else:
            i += 1
    total = len(same)
    pages = max(1, (total + page_size - 1) // page_size)
    if page > pages:
        raise ValueError('page out of range')
    start = (page - 1) * page_size
    current = same[start:start + page_size]
    first = start + 1 if current else 0
    last = start + len(current) if current else 0
    esc = lambda value: html.escape(str(value), quote=True)
    rows = ''.join((f"""<tr><td class="docket-id">{esc(r['docket_id'])}</td><td>{esc(r['title'])}</td><td>{esc(r['client'])}</td><td>{esc(r['status'])}</td><td>{esc(r['filing_date'])}</td><td>{r['claims']}</td></tr>""" for r in current))
    return f"""<div class="docket-report"><h1>IP Docket Report</h1><p class="summary">Showing {first}-{last} of {total} matters ({sum((r['claims'] for r in same))} claims)</p><table><thead><tr><th>Docket</th><th>Title</th><th>Client</th><th>Status</th><th>Filing date</th><th>Claims</th></tr></thead><tbody>{rows}</tbody></table><nav class="pagination"><span>Page {page} of {pages}</span></nav></div>"""

