import json
_FIELDS = {'id', 'ride', 'start', 'party', 'priority'}

def _validate(reservations):
    if not isinstance(reservations, list):
        raise ValueError('reservations must be a list')
    seen = set()
    result = []
    for item in reservations:
        if not isinstance(item, dict) or set(item) != _FIELDS:
            raise ValueError('invalid reservation')
        ident = item['id']
        ride = item['ride']
        start = item['start']
        party = item['party']
        priority = item['priority']
        if not isinstance(ident, str) or not ident or (not isinstance(ride, str)) or (not ride) or (not isinstance(start, int)) or isinstance(start, bool) or (start < 0) or (not isinstance(party, int)) or isinstance(party, bool) or (party <= 0) or (not isinstance(priority, int)) or isinstance(priority, bool) or (ident in seen):
            raise ValueError('invalid reservation')
        seen.add(ident)
        result.append(dict(item))
    return result

def encode_reservations(reservations: list[dict]) -> bytes:
    return json.dumps(_validate(reservations), separators=(',', ':'), ensure_ascii=False).encode('utf-8')

def decode_reservations(data: bytes | str) -> list[dict]:
    try:
        if isinstance(data, bytes):
            text = data.decode('utf-8')
        elif isinstance(data, str):
            text = data
        else:
            raise ValueError
        value = json.loads(text)
    except (UnicodeError, json.JSONDecodeError, TypeError, ValueError):
        raise ValueError('invalid data')
    return _validate(value)

def build_schedule(reservations: list[dict], capacities: dict[str, int], slot_minutes: int=30) -> dict[str, dict[int, list[str]]]:
    items = _validate(reservations)
    if not isinstance(capacities, dict) or not isinstance(slot_minutes, int) or isinstance(slot_minutes, bool) or (slot_minutes <= 0):
        raise ValueError('invalid schedule arguments')
    for ride, cap in capacities.items():
        if not isinstance(ride, str) or not isinstance(cap, int) or isinstance(cap, bool) or (cap <= 0):
            raise ValueError('invalid capacity')
    grouped = {}
    for item in items:
        if item['ride'] not in capacities:
            raise ValueError('missing capacity')
        slot = item['start'] // slot_minutes * slot_minutes
        grouped.setdefault(item['ride'], {}).setdefault(slot, []).append(item)
    output = {}
    for ride in sorted(grouped):
        for slot in sorted(grouped[ride]):
            ordered = sorted(grouped[ride][slot], key=lambda x: (-x['priority'], x['start'], x['id']))
            used = 0
            accepted = []
