import math
from datetime import datetime, timezone
from html import escape

def _time(value, label):
    try:
        parsed = datetime.fromisoformat(value.strip().replace('Z', '+00:00'))
        if parsed.tzinfo is None:
            raise ValueError
        return parsed.astimezone(timezone.utc)
    except ValueError:
        raise ValueError(f'invalid {label}')

def parse_readings(text: str, start: str | None=None, end: str | None=None) -> list[dict]:
    begin = _time(start, 'start') if start is not None else None
    finish = _time(end, 'end') if end is not None else None
    if begin is not None and finish is not None and (begin > finish):
        raise ValueError('invalid range')
    grouped = {}
    for number, raw in enumerate(io.StringIO(text), 1):
        if not raw.strip():
            continue
        try:
            fields = next(csv.reader([raw]))
            if len(fields) != 4:
                raise ValueError
            stamp = _time(fields[0], 'timestamp')
            sensor, value_text, status = (x.strip() for x in fields[1:])
            value = float(value_text)
            if not sensor or not status or (not math.isfinite(value)):
                raise ValueError
        except (ValueError, StopIteration):
            raise ValueError(f'invalid record on line {number}')
        if begin is not None and stamp < begin or (finish is not None and stamp > finish):
            continue
        grouped.setdefault(sensor, []).append((stamp, value, status))
    result = []
    for sensor in sorted(grouped, key=lambda x: (x.casefold(), x)):
        rows = grouped[sensor]
        latest = rows[0]
        for row in rows[1:]:
            if row[0] >= latest[0]:
                latest = row
        values = [row[1] for row in rows]
        result.append({'sensor': sensor, 'count': len(values), 'average': round(sum(values) / len(values), 2), 'min': round(min(values), 2), 'max': round(max(values), 2), 'last_timestamp': latest[0].isoformat().replace('+00:00', 'Z'), 'last_status': latest[2]})
    return result

def render_report(summary: list[dict], title: str) -> str:
