    rows = []
    for item in summary:
        rows.append('<tr><td>' + escape(str(item['sensor'])) + '</td><td>' + str(item['count']) + '</td><td>' + f"{item['average']:.2f}" + '</td><td>' + f"{item['min']:.2f}" + '</td><td>' + f"{item['max']:.2f}" + '</td><td>' + escape(str(item['last_timestamp'])) + '</td><td>' + escape(str(item['last_status'])) + '</td></tr>')
