import base64
import json
import math

def encode_manifest(records: list[dict]) -> bytes:
    if not isinstance(records, list):
        raise ValueError('invalid records')
    raw = json.dumps(records, separators=(',', ':'), allow_nan=False).encode('utf-8')
    return base64.b64encode(raw)

def manifest_report(blob: bytes | str, flight: str | None=None, offset: int=0, limit: int=10) -> dict:
    if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
        raise ValueError('invalid offset')
    if isinstance(limit, bool) or not isinstance(limit, int) or limit <= 0:
        raise ValueError('invalid limit')
    try:
        encoded = blob.encode('utf-8') if isinstance(blob, str) else blob
        records = json.loads(base64.b64decode(encoded, validate=True).decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid manifest') from exc
    if not isinstance(records, list):
        raise ValueError('invalid records')
    checked = []
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        if set(record) != {'name', 'flight', 'seat', 'fare', 'status'}:
            raise ValueError('invalid record')
        if not all((isinstance(record[k], str) for k in ('name', 'flight', 'seat', 'status'))):
            raise ValueError('invalid record')
        if isinstance(record['fare'], bool) or not isinstance(record['fare'], (int, float)) or (not math.isfinite(record['fare'])):
            raise ValueError('invalid fare')
        checked.append(record)
    selected = [r for r in checked if flight is None or r['flight'] == flight]
    selected.sort(key=lambda r: (-r['fare'], r['name'], r['seat']))
    statuses = {}
    for record in selected:
        statuses[record['status']] = statuses.get(record['status'], 0) + 1
    statuses = dict(sorted(statuses.items()))
    return {'passengers': [r['name'] for r in selected[offset:offset + limit]], 'total_fare': round(sum((r['fare'] for r in selected)), 2), 'by_status': statuses}

