def get_grocery_deals(item_codes: list[str], page: int=1, page_size: int=10) -> list[dict]:
    if not isinstance(item_codes, list):
        raise ValueError('item_codes must be a list')
    if any((not isinstance(code, str) or not code for code in item_codes)):
        raise ValueError('invalid item code')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    codes = list(dict.fromkeys(item_codes))
    if not codes:
        return []
    response = requests.get('https://api.grocery.example/v1/prices', params={'codes': ','.join(codes), 'page': page, 'page_size': page_size}, headers={'Accept': 'application/json'})
    if response.status_code != 200:
        raise RuntimeError('price service failure')
    data = response.json()
    chosen = {}
    for offer in data.get('offers', []):
        code = offer.get('code')
        price = offer.get('price')
        regular = offer.get('regular_price')
        if code not in codes or offer.get('in_stock') is not True:
            continue
        if isinstance(price, bool) or not isinstance(price, (int, float)):
            continue
        if isinstance(regular, bool) or not isinstance(regular, (int, float)):
            continue
        if price < 0 or price > regular or regular <= 0:
            continue
        savings = (regular - price) / regular * 100
        if savings <= 0:
            continue
        candidate = (savings, price, offer.get('store', ''))
        if code not in chosen or candidate > chosen[code][0]:
            chosen[code] = (candidate, offer)
    result = []
    for _, offer in chosen.values():
        regular = offer['regular_price']
        savings = round((regular - offer['price']) / regular * 100, 2)
        result.append({'code': offer['code'], 'store': offer.get('store', ''), 'price': offer['price'], 'regular_price': regular, 'savings_percent': savings})
    return sorted(result, key=lambda x: (-x['savings_percent'], x['code']))

