import requests

def _row(item, asset):
    if not isinstance(item, dict) or not isinstance(item.get('control'), dict):
        raise ValueError('invalid item')
    for key in ('id', 'observed_at', 'result'):
        if key not in item:
            raise ValueError('invalid item')
    control = item['control']
    if 'id' not in control or 'name' not in control:
        raise ValueError('invalid control')
    if asset is None:
        aid, atype = ('', '')
    else:
        if not isinstance(asset, dict) or 'id' not in asset or 'type' not in asset:
            raise ValueError('invalid asset')
        aid, atype = (asset['id'], asset['type'])
    return {'evidence_id': item['id'], 'control_id': control['id'], 'control_name': control['name'], 'observed_at': item['observed_at'], 'result': item['result'], 'asset_id': aid, 'asset_type': atype}

def collect_evidence(base_url: str, token: str, start: str, end: str) -> list[dict]:
    rows = []
    cursor = None
    while True:
        params = {'start': start, 'end': end, 'limit': 100}
        if cursor:
            params['cursor'] = cursor
        r = requests.get(base_url.rstrip('/') + '/v1/evidence', params=params, headers={'Authorization': 'Bearer ' + token})
        if r.status_code != 200:
            raise RuntimeError('request failed')
        try:
            data = r.json()
        except Exception as exc:
            raise ValueError('invalid json') from exc
        if not isinstance(data, dict) or not isinstance(data.get('items'), list):
            raise ValueError('invalid response')
        for item in data['items']:
            assets = item.get('assets', []) if isinstance(item, dict) else []
            if assets is None:
                assets = []
            if not isinstance(assets, list):
                raise ValueError('invalid assets')
            rows.extend((_row(item, a) for a in assets or [None]))
        cursor = data.get('next_cursor')
        if not cursor:
            break
        if not isinstance(cursor, str):
            raise ValueError('invalid cursor')
    return sorted(rows, key=lambda x: (x['observed_at'], x['evidence_id'], x['asset_id']))

def summarize_evidence(rows: list[dict]) -> list[dict]:
    groups = {}
    required = ('control_id', 'control_name', 'observed_at', 'result', 'asset_id')
    for row in rows:
        if not isinstance(row, dict) or any((k not in row for k in required)):
            raise ValueError('invalid row')
        cid = row['control_id']
        if cid not in groups:
            groups[cid] = {'control_id': cid, 'control_name': row['control_name'], 'evidence_count': 0, 'pass_count': 0, 'fail_count': 0, 'latest_observed': row['observed_at'], 'assets': set()}
        g = groups[cid]
        g['evidence_count'] += 1
        if row['result'] == 'pass':
            g['pass_count'] += 1
        elif row['result'] == 'fail':
            g['fail_count'] += 1
        g['latest_observed'] = max(g['latest_observed'], row['observed_at'])
        if row['asset_id']:
            g['assets'].add(row['asset_id'])
    out = []
    for cid in sorted(groups):
        g = groups[cid].copy()
        g['assets'] = sorted(g['assets'])
        out.append(g)
    return out

