def _check(s):
    if not isinstance(s, dict) or set(s) != {'balances', 'processed', 'ledger'}:
        raise ValueError('invalid state')
    if not isinstance(s['balances'], dict) or any((not isinstance(k, str) or not isinstance(v, int) or isinstance(v, bool) or (v < 0) for k, v in s['balances'].items())):
        raise ValueError('invalid balances')
    if not isinstance(s['processed'], list) or any((not isinstance(x, str) for x in s['processed'])):
        raise ValueError('invalid processed')
    if not isinstance(s['ledger'], list) or any((not _valid_ledger_entry(x) for x in s['ledger'])):
        raise ValueError('invalid ledger')

