        s['balances'][t['recipient']] = s['balances'].get(t['recipient'], 0) + t['amount']
        s['processed'].append(t['id'])
        s['ledger'].append({'id': t['id'], 'from': t['sender'], 'to': t['recipient'], 'amount': t['amount'], 'timestamp': t['timestamp']})
    return s

