def render_application_report(records: list[dict], page: int=1, page_size: int=10) -> str:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    required = {'date', 'field', 'product', 'amount_liters', 'operator'}
    checked = []
    for record in records:
        if not isinstance(record, dict):
            raise TypeError('record must be a dictionary')
        if set(record) != required:
            raise ValueError('invalid record')
        date = record['date']
        if not isinstance(date, str):
            raise ValueError('invalid date')
        try:
            datetime.date.fromisoformat(date)
        except ValueError:
            raise ValueError('invalid date')
        if not all((isinstance(record[key], str) for key in ('field', 'product', 'operator'))):
            raise ValueError('invalid text')
        amount = record['amount_liters']
        if isinstance(amount, bool) or not isinstance(amount, (int, float)) or (not math.isfinite(amount)) or (amount < 0):
            raise ValueError('invalid amount')
        checked.append(record)
    ordered = sorted(checked, key=lambda r: (r['field'], r['product'], r['operator']))
    ordered.sort(key=lambda r: r['date'], reverse=True)
    total = len(ordered)
    pages = (total + page_size - 1) // page_size
    if page > max(1, pages):
        raise ValueError('page outside range')
    selected = ordered[(page - 1) * page_size:page * page_size]
    rows = ''.join((f"<tr><td>{html.escape(r['date'])}</td><td>{html.escape(r['field'])}</td><td>{html.escape(r['product'])}</td><td>{r['amount_liters']:.2f}</td><td>{html.escape(r['operator'])}</td></tr>" for r in selected))
    amount = sum((r['amount_liters'] for r in ordered))
    return f'<div class="report"><h1>Pesticide applications</h1><p class="summary">Showing {len(selected)} of {total} applications; total {amount:.2f} L</p><table><thead><tr><th>Date</th><th>Field</th><th>Product</th><th>Amount (L)</th><th>Operator</th></tr></thead><tbody>{rows}</tbody></table><p class="page">Page {page} of {pages}</p></div>'

