from datetime import datetime, timezone
import requests

def _time(value):
    if not isinstance(value, str):
        raise ValueError('invalid timestamp')
    try:
        text = value
        if len(text) == 10:
            text += 'T00:00:00+00:00'
        elif text.endswith('Z'):
            text = text[:-1] + '+00:00'
        dt = datetime.fromisoformat(text)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(timezone.utc)
    except (TypeError, ValueError):
        raise ValueError('invalid timestamp')

def _stamp(value):
    return _time(value).strftime('%Y-%m-%dT%H:%M:%SZ')

def fetch_docket(case_number: str, api_base: str, token: str | None=None) -> dict:
    headers = {}
    if token is not None:
        headers['Authorization'] = 'Bearer ' + token
    kwargs = {'params': {'include': 'filings,hearings'}, 'timeout': 10}
    if headers:
        kwargs['headers'] = headers
    response = requests.get(api_base.rstrip('/') + '/cases/' + case_number + '/docket', **kwargs)
    if response.status_code != 200:
        raise RuntimeError('docket request failed: ' + str(response.status_code))
    value = response.json()
    if not isinstance(value, dict):
        raise ValueError('docket must be an object')
    return value

def normalize_docket(payload: dict) -> list[dict]:
    if not isinstance(payload, dict) or not isinstance(payload.get('events'), list):
        raise ValueError('events must be a list')
    chosen = {}
    for raw in payload['events']:
        if not isinstance(raw, dict) or any((k not in raw for k in ('id', 'occurred_at', 'type', 'title'))):
            raise ValueError('invalid event')
        stamp = _stamp(raw['occurred_at'])
        try:
            sequence = int(raw.get('sequence', 0))
        except (TypeError, ValueError):
            raise ValueError('invalid sequence')
        item = {'id': str(raw['id']), 'occurred_at': stamp, 'type': str(raw['type']), 'title': str(raw['title']), 'sequence': sequence}
        old = chosen.get(item['id'])
        if old is None or (item['occurred_at'], item['sequence']) > (old['occurred_at'], old['sequence']):
            chosen[item['id']] = item
    return sorted(chosen.values(), key=lambda x: (x['occurred_at'], x['sequence'], x['id']))

def docket_snapshot(events: list[dict], as_of: str | None=None) -> dict:
    limit = _stamp(as_of) if as_of is not None else None
    included = [e for e in events if limit is None or e['occurred_at'] <= limit]
    counts = {}
    for event in included:
        counts[event['type']] = counts.get(event['type'], 0) + 1
    counts = dict(sorted(counts.items()))
    return {'event_count': len(included), 'counts_by_type': counts, 'first_event': included[0] if included else None, 'last_event': included[-1] if included else None, 'closed': bool(included and included[-1]['type'] in ('closed', 'dismissed'))}

