def get_fixture_summary(team: str, season: int, page: int=1) -> list[dict]:
    if not isinstance(team, str) or not team.strip():
        raise ValueError('invalid team')
    if isinstance(season, bool) or not isinstance(season, int) or (not 1900 <= season <= 2100):
        raise ValueError('invalid season')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    response = requests.get('https://api.example.com/v1/fixtures', params={'team': team, 'season': season, 'page': page, 'page_size': 50}, headers={'Accept': 'application/json'}, timeout=10)
    if response.status_code != 200:
        raise ValueError('request failed')
    try:
        data = response.json()
    except Exception as exc:
        raise ValueError('invalid response') from exc
    if not isinstance(data, dict) or not isinstance(data.get('fixtures'), list):
        raise ValueError('invalid response')
    result = []
    for fixture in data['fixtures']:
        if not isinstance(fixture, dict) or fixture.get('status') != 'completed':
            continue
        home = fixture.get('home_team')
        away = fixture.get('away_team')
        if team != home and team != away:
            continue
        try:
            home_score = int(fixture['home_score'])
            away_score = int(fixture['away_score'])
        except (KeyError, TypeError, ValueError) as exc:
            raise ValueError('invalid score') from exc
        is_home = team == home
        score_for = home_score if is_home else away_score
        score_against = away_score if is_home else home_score
        outcome = 'win' if score_for > score_against else 'loss' if score_for < score_against else 'draw'
        result.append({'id': fixture['id'], 'date': fixture['date'], 'opponent': away if is_home else home, 'venue': 'home' if is_home else 'away', 'score_for': score_for, 'score_against': score_against, 'outcome': outcome, 'points': 3 if outcome == 'win' else 0 if outcome == 'loss' else 1})
    result.sort(key=lambda item: (item['date'], item['id']))
    return result

