from solution import summarize_donations
from unittest.mock import Mock, patch
import pytest


def response(data, status=200):
    r = Mock()
    r.status_code = status
    r.json.return_value = data
    return r


def test_filters_groups_sorts_and_formats_totals():
    data = {"donations": [
        {"donor": " Ada ", "university": "North", "year": 2024, "amount": "10.005", "status": "completed"},
        {"donor": "Ada", "university": "North", "year": 2024, "amount": 2.10, "status": "completed"},
        {"donor": "Bob", "university": "North", "year": 2024, "amount": 12, "status": "completed"},
        {"donor": "Ignored", "university": "South", "year": 2024, "amount": 100, "status": "completed"},
        {"donor": "Ignored", "university": "North", "year": 2024, "amount": 100, "status": "pending"}
    ]}
    with patch("solution.requests.get", return_value=response(data)) as get:
        result = summarize_donations("https://alumni.test/api", "North", 2024)
    assert result == [
        {"donor": "Ada", "total": 12.11, "count": 2},
        {"donor": "Bob", "total": 12.0, "count": 1}
    ]
    args, kwargs = get.call_args
    assert args == ("https://alumni.test/api",)
    assert kwargs["params"] == {"university": "North", "year": 2024}
    assert kwargs["headers"]["Accept"] == "application/json"
    assert kwargs["timeout"] == 10


def test_ties_are_sorted_by_stripped_donor_name():
    data = {"donations": [
        {"donor": "Zed", "university": "U", "year": 2020, "amount": 5, "status": "completed"},
        {"donor": "Amy", "university": "U", "year": 2020, "amount": 5, "status": "completed"}
    ]}
    with patch("solution.requests.get", return_value=response(data)):
        assert summarize_donations("https://x", "U", 2020) == [
            {"donor": "Amy", "total": 5.0, "count": 1},
            {"donor": "Zed", "total": 5.0, "count": 1}
        ]


def test_pagination_is_one_based():
    records = [{"donor": name, "university": "U", "year": 2020, "amount": amount, "status": "completed"}
               for name, amount in [("A", 5), ("B", 4), ("C", 3), ("D", 2)]]
    with patch("solution.requests.get", return_value=response({"donations": records})):
        assert summarize_donations("https://x", "U", 2020, page=2, page_size=2) == [
            {"donor": "C", "total": 3.0, "count": 1},
            {"donor": "D", "total": 2.0, "count": 1}
        ]
        assert summarize_donations("https://x", "U", 2020, page=3, page_size=2) == []


def test_invalid_records_are_ignored():
    data = {"donations": [
        {"donor": "", "university": "U", "year": 2020, "amount": 4, "status": "completed"},
        {"donor": "Bad", "university": "U", "year": 2020, "amount": "nope", "status": "completed"},
        {"donor": "Neg", "university": "U", "year": 2020, "amount": -1, "status": "completed"},
        {"donor": "Good", "university": "U", "year": 2020, "amount": 1, "status": "completed"}
    ]}
    with patch("solution.requests.get", return_value=response(data)):
        assert summarize_donations("https://x", "U", 2020) == [{"donor": "Good", "total": 1.0, "count": 1}]


def test_validation_errors():
    with pytest.raises(ValueError):
        summarize_donations("https://x", "", 2020)
    with pytest.raises(ValueError):
        summarize_donations("https://x", "U", 1899)
    with pytest.raises(ValueError):
        summarize_donations("https://x", "U", 2020, page=0)
    with pytest.raises(ValueError):
        summarize_donations("https://x", "U", 2020, page_size=101)


def test_http_and_json_errors():
    with patch("solution.requests.get", return_value=response({}, 500)):
