from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
import requests

def summarize_donations(api_url: str, university: str, year: int, page: int=1, page_size: int=10) -> list[dict[str, object]]:
    if not isinstance(university, str) or not university.strip():
        raise ValueError('invalid university')
    if not isinstance(year, int) or isinstance(year, bool) or (not 1900 <= year <= 2100):
        raise ValueError('invalid year')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    response = requests.get(api_url, params={'university': university, 'year': year}, headers={'Accept': 'application/json'}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError('request failed')
    data = response.json()
    if not isinstance(data, dict) or not isinstance(data.get('donations'), list):
        raise ValueError('invalid response')
    totals = {}
    for item in data['donations']:
        if not isinstance(item, dict) or item.get('university') != university or item.get('year') != year or (item.get('status') != 'completed'):
            continue
        donor = item.get('donor')
        if not isinstance(donor, str) or not donor.strip():
            continue
        try:
            amount = Decimal(str(item.get('amount')))
        except (InvalidOperation, ValueError, TypeError):
            continue
        if not amount.is_finite() or amount < 0:
            continue
        name = donor.strip()
        if name not in totals:
            totals[name] = [Decimal('0'), 0]
        totals[name][0] += amount
        totals[name][1] += 1
    ordered = sorted(totals.items(), key=lambda pair: (-pair[1][0], pair[0]))
    start = (page - 1) * page_size
    result = []
    for donor, (total, count) in ordered[start:start + page_size]:
        rounded = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        result.append({'donor': donor, 'total': float(rounded), 'count': count})
    return result

