import json

def encode_supplier_snapshot(records: list[dict]) -> bytes:
    return json.dumps(records, separators=(',', ':'), sort_keys=True).encode('utf-8')

def qualify_suppliers(payload: bytes, minimum_score: float, page: int, page_size: int) -> list[dict]:
    if isinstance(minimum_score, bool) or not isinstance(minimum_score, (int, float)) or (not 0 <= minimum_score <= 100):
        raise ValueError('invalid minimum score')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    try:
        records = json.loads(payload.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid snapshot') from exc
    if not isinstance(records, list):
        raise ValueError('invalid snapshot')
    selected = []
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        if set(record) != {'supplier', 'score', 'annual_spend', 'approved'}:
            raise ValueError('invalid record')
        name = record['supplier']
        score = record['score']
        spend = record['annual_spend']
        approved = record['approved']
        if not isinstance(name, str) or not name:
            raise ValueError('invalid record')
        if isinstance(score, bool) or not isinstance(score, (int, float)) or (not 0 <= score <= 100):
            raise ValueError('invalid record')
        if isinstance(spend, bool) or not isinstance(spend, (int, float)) or spend < 0:
            raise ValueError('invalid record')
        if not isinstance(approved, bool):
            raise ValueError('invalid record')
        if approved and score >= minimum_score:
            selected.append((name, score, spend))
    selected.sort(key=lambda item: (-item[1], -item[2], item[0]))
    start = (page - 1) * page_size
    result = []
    for name, score, spend in selected[start:start + page_size]:
        tier = 'platinum' if score >= 90 else 'gold' if score >= 75 else 'silver'
        result.append({'supplier': name, 'score': round(score, 1), 'annual_spend': round(spend, 2), 'tier': tier})
    return result

