import math
import yaml

def pack_admissions(records: list[dict]) -> bytes:
    return yaml.safe_dump(records, sort_keys=False).encode('utf-8')

def admission_report(payload: bytes, status: str | None=None, department: str | None=None, page: int=1, page_size: int=10) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 50):
        raise ValueError('invalid page size')
    if status is not None and status not in ('admitted', 'discharged'):
        raise ValueError('invalid status')
    if department is not None and (not isinstance(department, str) or not department):
        raise ValueError('invalid department')
    try:
        records = yaml.safe_load(payload.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(records, list):
        raise ValueError('invalid records')
    seen = set()
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        required = {'patient_id', 'department', 'status', 'days', 'cost'}
        if set(record) != required:
            raise ValueError('invalid record')
        patient_id = record['patient_id']
        name = record['department']
        state = record['status']
        days = record['days']
        cost = record['cost']
        if not isinstance(patient_id, str) or not patient_id or patient_id in seen:
            raise ValueError('invalid patient')
        if not isinstance(name, str) or not name:
            raise ValueError('invalid department')
        if state not in ('admitted', 'discharged'):
            raise ValueError('invalid record')
        if not isinstance(days, int) or isinstance(days, bool) or days < 0:
            raise ValueError('invalid days')
        if not isinstance(cost, (int, float)) or isinstance(cost, bool) or (not math.isfinite(cost)) or (cost < 0):
            raise ValueError('invalid cost')
        seen.add(patient_id)
        if status is not None and state != status:
            continue
        if department is not None and name != department:
            continue
        item = groups.setdefault(name, [0, 0, 0.0])
        item[0] += 1
        item[1] += days
        item[2] += cost
    summaries = [{'department': name, 'count': v[0], 'total_days': v[1], 'total_cost': round(v[2], 2)} for name, v in groups.items()]
    summaries.sort(key=lambda x: (-x['count'], -x['total_cost'], x['department']))
    start = (page - 1) * page_size
    return {'page': page, 'page_size': page_size, 'total': len(summaries), 'departments': summaries[start:start + page_size]}

