import csv
import io
import html

def parse_applications(text: str) -> list[dict]:
    if not text:
        raise ValueError('empty input')
    try:
        rows = list(csv.reader(io.StringIO(text, newline='')))
    except csv.Error as exc:
        raise ValueError('invalid csv') from exc
    header = ['application_id', 'student', 'year', 'course', 'preferences']
    if not rows or rows[0] != header:
        raise ValueError('invalid header')
    result = []
    seen = set()
    for row in rows[1:]:
        if len(row) != 5:
            raise ValueError('invalid row')
        ident, student, year, course, preferences = row
        if not ident or ident in seen:
            raise ValueError('invalid application id')
        try:
            number = int(year)
        except ValueError as exc:
            raise ValueError('invalid year') from exc
        if number <= 0:
            raise ValueError('invalid year')
        seen.add(ident)
        prefs = [part.strip() for part in preferences.split(';') if part.strip()]
        result.append({'application_id': ident, 'student': student, 'year': number, 'course': course, 'preferences': prefs})
    if not result:
        raise ValueError('no applications')
    return result

def allocate_students(applications: list[dict], rooms: dict[str, int]) -> list[dict]:
    for capacity in rooms.values():
        if capacity <= 0:
            raise ValueError('invalid capacity')
    remaining = dict(rooms)
    ordered = sorted(applications, key=lambda item: (-item['year'], item['course'], item['application_id']))
    result = []
    for item in ordered:
        room = None
        for preferred in item['preferences']:
            if preferred in remaining and remaining[preferred] > 0:
                room = preferred
                remaining[preferred] -= 1
                break
        result.append({'application_id': item['application_id'], 'student': item['student'], 'year': item['year'], 'course': item['course'], 'room': room})
    return result

def render_allocation_report(assignments: list[dict], title: str='Student Housing Allocation') -> str:
    esc = lambda value: html.escape(str(value), quote=True)
    rows = []
    for item in assignments:
        room = 'Unassigned' if item['room'] is None else item['room']
        cells = [item['application_id'], item['student'], item['year'], item['course'], room]
        rows.append('<tr>' + ''.join(('<td>' + esc(value) + '</td>' for value in cells)) + '</tr>')
    body = ''.join(rows)
    return '<section><h1>' + esc(title) + '</h1><table><thead><tr><th>Application</th><th>Student</th><th>Year</th><th>Course</th><th>Room</th></tr></thead><tbody>' + body + '</tbody></table></section>'

