import csv
import io
import html

def parse_schedule(text: str) -> list[dict]:
    try:
        rows = list(csv.reader(io.StringIO(text, newline='')))
    except csv.Error as exc:
        raise ValueError('invalid CSV') from exc
    if not rows or rows[0] != ['job', 'workcenter', 'start', 'duration', 'quantity']:
        raise ValueError('invalid header')
    result = []
    seen = set()
    for row in rows[1:]:
        if not row or all((not x.strip() for x in row)):
            continue
        if len(row) != 5:
            raise ValueError('invalid columns')
        job, wc, start, duration, quantity = [x.strip() for x in row]
        if not job or not wc or job in seen:
            raise ValueError('invalid job')
        try:
            values = [int(start), int(duration), int(quantity)]
        except ValueError as exc:
            raise ValueError('invalid number') from exc
        if values[0] < 0 or values[1] <= 0 or values[2] <= 0:
            raise ValueError('invalid number')
        seen.add(job)
        result.append({'job': job, 'workcenter': wc, 'start': values[0], 'duration': values[1], 'quantity': values[2]})
    if not result:
        raise ValueError('empty schedule')
    return result

def allocate_schedule(jobs: list[dict], capacity: dict[str, int]) -> list[dict]:
    machines = {}
    for job in jobs:
        wc = job['workcenter']
        if wc not in capacity or capacity[wc] <= 0:
            raise ValueError('invalid capacity')
        if wc not in machines:
            machines[wc] = [0] * capacity[wc]
    output = []
    for job in sorted(jobs, key=lambda x: (x['start'], x['job'])):
        wc = job['workcenter']
        avail = machines[wc]
        number = min(range(len(avail)), key=lambda i: (avail[i], i))
        start = max(job['start'], avail[number])
        end = start + job['duration']
        avail[number] = end
        output.append({'job': job['job'], 'workcenter': wc, 'machine': number + 1, 'start': start, 'end': end, 'quantity': job['quantity']})
    return sorted(output, key=lambda x: (x['start'], x['workcenter'], x['machine'], x['job']))

def render_schedule(schedule: list[dict], title: str) -> str:
    esc = lambda value: html.escape(str(value), quote=True)
    rows = ''.join(('<tr><td>{}</td><td>{}</td><td>{}</td><td>{}</td><td>{}</td><td>{}</td></tr>'.format(*(esc(record[key]) for key in ('job', 'workcenter', 'machine', 'start', 'end', 'quantity'))) for record in schedule))
    return '<section class="schedule"><h1>{}</h1><table><thead><tr><th>Job</th><th>Workcenter</th><th>Machine</th><th>Start</th><th>End</th><th>Quantity</th></tr></thead><tbody>{}</tbody></table></section>'.format(esc(title), rows)

