import requests

def plan_harvest(api_url: str, field_ids: list[str], available_days: int, token: str | None=None) -> list[dict]:
    if not isinstance(available_days, int) or isinstance(available_days, bool) or available_days < 0:
        raise ValueError('available_days must be a non-negative integer')
    if any((not isinstance(x, str) or not x for x in field_ids)):
        raise ValueError('field IDs must be non-empty strings')
    if not field_ids:
        return []
    headers = {'Authorization': f'Bearer {token}'} if token is not None else {}
    result = requests.get(api_url, params={'fields': ','.join(field_ids), 'available_days': available_days}, headers=headers)
    if result.status_code != 200:
        raise RuntimeError('forecast request failed')
    try:
        payload = result.json()
        records = payload['data']
        if not isinstance(records, list):
            raise ValueError
    except (KeyError, TypeError, ValueError):
        raise ValueError('invalid forecast response')
    grouped = {}
    for row in records:
        try:
            crop = row['crop']
            hectares = row['hectares']
            yield_per_ha = row['yield_per_ha']
            maturity = row['maturity_days']
            if not isinstance(crop, str) or not crop or hectares <= 0 or (yield_per_ha <= 0) or (maturity < 0):
                raise ValueError
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid forecast record')
        if maturity <= available_days:
            item = grouped.setdefault(crop, [0.0, 0.0])
            item[0] += hectares
            item[1] += hectares * yield_per_ha
    output = [{'crop': crop, 'hectares': round(values[0], 2), 'expected_tonnes': round(values[1], 2)} for crop, values in grouped.items()]
    return sorted(output, key=lambda x: (-x['expected_tonnes'], x['crop']))

