import datetime
import requests

def summarize_leads(api_url: str, dealer_id: str, start_date: str, end_date: str, page: int=1, page_size: int=50) -> list[dict]:

    def parse_date(value):
        try:
            return datetime.date.fromisoformat(value)
        except (TypeError, ValueError):
            raise ValueError('invalid date')
    start = parse_date(start_date)
    end = parse_date(end_date)
    if start > end or page < 1 or (not 1 <= page_size <= 100):
        raise ValueError('invalid arguments')
    response = requests.get(api_url.rstrip('/') + '/v1/leads', params={'dealer_id': dealer_id, 'start_date': start_date, 'end_date': end_date, 'page': page, 'page_size': page_size}, headers={'Accept': 'application/json'})
    if not 200 <= response.status_code < 300:
        raise RuntimeError('request failed')
    leads = response.json()['leads']
    groups = {}
    for lead in leads:
        if not isinstance(lead, dict):
            raise ValueError('invalid lead')
        try:
            lead_date = parse_date(lead['created_at'][:10])
            value = float(lead['estimated_value'])
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid lead')
        if lead.get('dealer_id') != dealer_id or not start <= lead_date <= end:
            continue
        source = lead.get('source') or 'unknown'
        group = groups.setdefault(source, {'source': source, 'count': 0, 'qualified_count': 0, 'total_value': 0.0})
        group['count'] += 1
        if lead.get('status') == 'qualified':
            group['qualified_count'] += 1
        group['total_value'] += value
    result = []
    for group in groups.values():
        group['conversion_rate'] = round(group['qualified_count'] * 100 / group['count'], 2)
        group['total_value'] = round(group['total_value'], 2)
        result.append({'source': group['source'], 'count': group['count'], 'qualified_count': group['qualified_count'], 'conversion_rate': group['conversion_rate'], 'total_value': group['total_value']})
    return sorted(result, key=lambda item: (-item['count'], item['source']))

