import requests

def _time(value):
    try:
        parsed = datetime.fromisoformat(value.replace('Z', '+00:00'))
        if parsed.tzinfo is None:
            raise ValueError
        return parsed.astimezone(timezone.utc)
    except (AttributeError, TypeError, ValueError):
        raise ValueError('invalid timestamp')

def _check_range(start, end, window):
    if not isinstance(window, int) or isinstance(window, bool) or window <= 0:
        raise ValueError('invalid window')
    a, b = (_time(start), _time(end))
    if a >= b:
        raise ValueError('invalid range')
    return (a, b)

def summarize_telemetry(data, start, end, window_seconds):
    a, b = _check_range(start, end, window_seconds)
    if not isinstance(data, dict) or not isinstance(data.get('vehicles'), list):
        raise ValueError('invalid data')
    seen, groups = (set(), {})
    for vehicle in data['vehicles']:
        if not isinstance(vehicle, dict) or not isinstance(vehicle.get('id'), str) or vehicle['id'] in seen:
            raise ValueError('invalid vehicle')
        seen.add(vehicle['id'])
        samples = vehicle.get('samples')
        if not isinstance(samples, list):
            raise ValueError('invalid samples')
        for sample in samples:
            if not isinstance(sample, dict):
                raise ValueError('invalid sample')
            t = _time(sample.get('ts'))
            try:
                lat, lon, speed = (float(sample['lat']), float(sample['lon']), float(sample['speed']))
            except (KeyError, TypeError, ValueError):
