        begin = a + timedelta(seconds=index * window_seconds)
        result.append({'vehicle_id': vehicle_id, 'window_start': begin.strftime('%Y-%m-%dT%H:%M:%SZ'), 'sample_count': len(values), 'average_speed': round(sum(values) / len(values), 2), 'maximum_speed': round(max(values), 2)})
    return result

def fetch_telemetry(url, api_key, start, end, window_seconds):
    _check_range(start, end, window_seconds)
    response = requests.get(url, params={'start': start, 'end': end, 'window': str(window_seconds)}, headers={'Authorization': 'Bearer ' + api_key}, timeout=10)
    if not 200 <= response.status_code < 300:
        raise ValueError('HTTP ' + str(response.status_code) + ': ' + response.text)
    try:
        data = response.json()
    except (ValueError, TypeError):
        raise ValueError('invalid JSON')
    return summarize_telemetry(data, start, end, window_seconds)

