        raise ValueError('invalid response JSON') from exc
    readings = body.get('readings') if isinstance(body, dict) else None
    if not isinstance(readings, list):
        raise ValueError('readings must be a list')
    result = []
    for reading in readings:
        if not isinstance(reading, dict):
            raise ValueError('invalid reading')
        timestamp = reading.get('timestamp')
        pressure = reading.get('pressure_kpa')
        if not isinstance(timestamp, str) or not timestamp or (not isinstance(pressure, (int, float))) or isinstance(pressure, bool):
            raise ValueError('invalid reading')
        result.append({'timestamp': timestamp, 'pressure_psi': round(pressure * 0.1450377377, 2)})
    return sorted(result, key=lambda item: item['timestamp'])

