from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from html import escape

def render_order_report(orders: list[dict], page: int=1, per_page: int=10) -> str:
    if not isinstance(orders, list) or not isinstance(page, int) or isinstance(page, bool) or (page < 1):
        raise ValueError('invalid input')
    if not isinstance(per_page, int) or isinstance(per_page, bool) or (not 1 <= per_page <= 50):
        raise ValueError('invalid input')
    paid = []
    for order in orders:
        if not isinstance(order, dict):
            raise ValueError('invalid input')
        required = ('order_id', 'seller', 'item', 'quantity', 'unit_price', 'status')
        if any((key not in order for key in required)):
            raise ValueError('invalid input')
        if any((not isinstance(order[key], str) or not order[key] for key in ('order_id', 'seller', 'item'))):
            raise ValueError('invalid input')
        quantity = order['quantity']
        if not isinstance(quantity, int) or isinstance(quantity, bool) or quantity <= 0:
            raise ValueError('invalid input')
        try:
            price = Decimal(str(order['unit_price']))
        except (InvalidOperation, ValueError, TypeError):
            raise ValueError('invalid input')
        if not price.is_finite() or price < 0:
            raise ValueError('invalid input')
        if order['status'] not in ('paid', 'cancelled'):
            raise ValueError('invalid input')
        if order['status'] == 'paid':
            line = (price * quantity).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
            paid.append((order, price, line))
    paid.sort(key=lambda x: (-x[2], x[0]['order_id'], x[0]['seller'], x[0]['item']))
    count = len(paid)
    total = sum((x[2] for x in paid), Decimal('0.00'))
    start_index = (page - 1) * per_page
    shown = paid[start_index:start_index + per_page]
    if shown:
        start, end = (start_index + 1, start_index + len(shown))
    else:
        start, end = (0, 0)
    rows = []
    for order, price, line in shown:
        rows.append(f"<tr><td>{escape(order['order_id'], quote=True)}</td><td>{escape(order['seller'], quote=True)}</td><td>{escape(order['item'], quote=True)}</td><td>{order['quantity']}</td><td>{price.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP):.2f}</td><td>{line:.2f}</td></tr>")
    return f"""<section class="orders"><h1>Order report</h1><p class="summary">Showing {start}-{end} of {count} orders | Total: {total:.2f}</p><table><thead><tr><th>Order</th><th>Seller</th><th>Item</th><th>Quantity</th><th>Unit price</th><th>Line total</th></tr></thead><tbody>{''.join(rows)}</tbody></table></section>"""

