            raise ValueError()
        if type(record['quantity']) is not int or record['quantity'] <= 0 or type(record['priority']) is not int or (type(record['due']) is not int):
            raise ValueError()
        stock.setdefault(record['drug'], 0)
        indexed.append((index, record))
