def summarize_claims(payload: bytes, product: str | None=None, page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('invalid pagination')
    try:
        records = json.loads(payload.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(records, list):
        raise ValueError('invalid records')
    groups = {}
    total = Decimal('0')
    retained = 0
    for record in records:
        if not isinstance(record, dict) or set(record) != {'claim_id', 'product', 'amount', 'status', 'submitted'}:
            raise ValueError('invalid claim')
        if not all((isinstance(record[k], str) for k in ('claim_id', 'product', 'submitted'))) or record['status'] not in {'approved', 'denied', 'pending'}:
            raise ValueError('invalid claim')
        if isinstance(record['amount'], bool) or not isinstance(record['amount'], (int, float)) or record['amount'] < 0:
            raise ValueError('invalid claim')
        if product is not None and record['product'] != product:
            continue
