        amount = Decimal(str(record['amount']))
        if record['status'] == 'approved':
            total += amount
        group = groups.setdefault(record['product'], [0, Decimal('0'), ''])
        group[0] += 1
        if record['status'] == 'approved':
            group[1] += amount
        if record['submitted'] > group[2]:
            group[2] = record['submitted']
    items = [{'product': name, 'claims': data[0], 'approved_amount': float(round(data[1], 2)), 'latest_submitted': data[2]} for name, data in groups.items()]
