import requests

def fetch_artifacts(project: str, build_ids: list[str], base_url: str, token: str | None=None) -> list[dict]:
    url = base_url.rstrip('/') + '/api/v1/projects/' + quote(project, safe='') + '/artifacts'
    headers = {'Accept': 'application/json'}
    if token is not None:
        headers['Authorization'] = 'Bearer ' + token
    response = requests.get(url, params={'build_ids': ','.join(build_ids)}, headers=headers, timeout=10)
    if response.status_code != 200:
        raise RuntimeError('artifact service returned ' + str(response.status_code))
    try:
        payload = response.json()
    except Exception as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(payload, dict) or not isinstance(payload.get('artifacts'), list):
        raise ValueError('invalid response shape')
    wanted = set(build_ids)
    result = []
    for group in payload['artifacts']:
        if not isinstance(group, dict) or group.get('build_id') not in wanted:
            continue
        if not isinstance(group.get('files'), list):
            raise ValueError('invalid files')
        for file in group['files']:
            if not isinstance(file, dict) or not isinstance(file.get('size'), int) or isinstance(file.get('size'), bool) or (file['size'] < 0):
                raise ValueError('invalid size')
            if not all((isinstance(group.get(k), str) for k in ('build_id', 'status', 'created_at'))) or not all((isinstance(file.get(k), str) for k in ('name', 'sha256'))):
                raise ValueError('invalid artifact')
            result.append({'build_id': group['build_id'], 'status': group['status'], 'created_at': group['created_at'], 'name': file['name'], 'size': file['size'], 'sha256': file['sha256']})
    return sorted(result, key=lambda x: (x['build_id'], x['created_at'], x['name']))

def summarize_artifacts(records: list[dict]) -> list[dict]:
    groups = {}
    for record in records:
        groups.setdefault(record['build_id'], []).append(record)
    result = []
    for build_id, items in groups.items():
        extensions = set()
        for item in items:
            name = item['name']
            if '.' in name and (not name.endswith('.')):
                ext = name.rsplit('.', 1)[1]
                if ext:
                    extensions.add(ext.lower())
        latest = max(items, key=lambda x: (x['created_at'], x['name']))
        result.append({'build_id': build_id, 'status': latest['status'], 'total_bytes': sum((x['size'] for x in items)), 'file_count': len(items), 'extensions': sorted(extensions)})
    return sorted(result, key=lambda x: (-x['total_bytes'], x['build_id']))

