import json
from datetime import datetime, timezone
from html import escape
STATUSES = {'delivered': 0, 'delayed': 1, 'in_transit': 2, 'pending': 3}
FIELDS = ('id', 'origin', 'destination', 'status', 'updated_at', 'description', 'packages')

def _time(value):
    try:
        parsed = datetime.fromisoformat(value.replace('Z', '+00:00'))
    except (TypeError, ValueError):
        raise ValueError('invalid timestamp')
    if parsed.tzinfo is None:
        raise ValueError('timestamp must have timezone')
    return parsed.astimezone(timezone.utc)

def load_shipments(data: str) -> list[dict]:
    try:
        raw = json.loads(data)
    except (TypeError, json.JSONDecodeError):
        raise ValueError('invalid JSON')
    if not isinstance(raw, list):
        raise ValueError('expected array')
    result = []
    for item in raw:
        if not isinstance(item, dict) or any((field not in item for field in FIELDS)):
            raise ValueError('invalid shipment')
        if any((not isinstance(item[field], str) for field in FIELDS[:-1])):
            raise ValueError('invalid text field')
        if item['status'] not in STATUSES:
            raise ValueError('invalid status')
        if isinstance(item['packages'], bool) or not isinstance(item['packages'], int) or item['packages'] < 0:
            raise ValueError('invalid package count')
        _time(item['updated_at'])
        result.append(dict(item))
    return result

def latest_shipments(records: list[dict]) -> list[dict]:
    chosen = {}
    for index, record in enumerate(records):
        key = record['id']
        stamp = _time(record['updated_at'])
        old = chosen.get(key)
        if old is None or stamp >= old[0]:
            chosen[key] = (stamp, index, record)
    result = [entry[2] for entry in chosen.values()]
    result.sort(key=lambda r: (STATUSES[r['status']], r['destination'], r['id']))
    return result

def render_tracking_report(data: str) -> str:
    records = latest_shipments(load_shipments(data))
    total = sum((record['packages'] for record in records))
    rows = []
    for record in records:
        values = [record['id'], record['origin'], record['destination'], record['status'], record['updated_at'], str(record['packages']), record['description']]
        rows.append('<tr>' + ''.join(('<td>' + escape(value, quote=True) + '</td>' for value in values)) + '</tr>')
    body = ''.join(rows)
    return '<section class="tracking-report">\n<h1>International Aid Shipment Tracking</h1>\n<p class="summary">Shipments: ' + str(len(records)) + ' | Packages: ' + str(total) + '</p>\n<table><thead><tr><th>ID</th><th>Origin</th><th>Destination</th><th>Status</th><th>Updated</th><th>Packages</th><th>Description</th></tr></thead><tbody>' + body + '</tbody></table>\n</section>'

