from datetime import date
import requests

def get_patient_summary(api_url: str, patient_id: str, start_date: str | None=None, end_date: str | None=None) -> dict:

    def parse_bound(value):
        if value is None:
            return None
        try:
            return date.fromisoformat(value)
        except ValueError:
            raise ValueError('invalid date')
    start = parse_bound(start_date)
    end = parse_bound(end_date)
    if start is not None and end is not None and (start > end):
        raise ValueError('invalid date range')
    params = {'patient_id': patient_id}
    if start_date is not None:
        params['start_date'] = start_date
    if end_date is not None:
        params['end_date'] = end_date
    response = requests.get(api_url.rstrip('/') + '/results', params=params, headers={'Accept': 'application/json'})
    payload = response.json()
    if not isinstance(payload, dict) or not isinstance(payload.get('results'), list):
        raise ValueError('invalid response')
    required = ('analyte', 'date', 'unit', 'value', 'reference_low', 'reference_high')
    rows = []
    for item in payload['results']:
        if not isinstance(item, dict) or any((key not in item for key in required)):
            raise ValueError('invalid result')
        try:
            item_date = date.fromisoformat(item['date'])
        except (TypeError, ValueError):
            raise ValueError('invalid result date')
        if (start is None or item_date >= start) and (end is None or item_date <= end):
            rows.append(dict(item))
    rows.sort(key=lambda item: (-date.fromisoformat(item['date']).toordinal(), item['analyte'], item['unit']))
    groups = {}
    abnormal_count = 0
    for item in rows:
        abnormal = item['value'] < item['reference_low'] or item['value'] > item['reference_high']
        abnormal_count += abnormal
        group = groups.setdefault(item['analyte'], {'count': 0, 'abnormal_count': 0, 'latest_date': item['date'], 'latest_value': item['value']})
        group['count'] += 1
        group['abnormal_count'] += abnormal
    return {'patient_id': patient_id, 'results': rows, 'abnormal_count': abnormal_count, 'by_analyte': {key: groups[key] for key in sorted(groups)}}

