import json

def dump_register_state(state: dict) -> bytes:
    if not isinstance(state, dict):
        raise ValueError('state must be a dictionary')
    try:
        return json.dumps(state, ensure_ascii=False, sort_keys=True, separators=(',', ':')).encode('utf-8')
    except (TypeError, ValueError, OverflowError) as exc:
        raise ValueError('state cannot be serialized') from exc

def load_register_state(blob: bytes | str) -> dict:
    if not isinstance(blob, (bytes, str)):
        raise ValueError('payload must be bytes or text')
    try:
        value = json.loads(blob.decode('utf-8') if isinstance(blob, bytes) else blob)
    except (UnicodeError, TypeError, ValueError) as exc:
        raise ValueError('invalid register state') from exc
    if not isinstance(value, dict):
        raise ValueError('register state must be a dictionary')
    return value

