import datetime
import requests

def normalize_policies(payload: dict, as_of: str) -> list[dict]:
    try:
        cutoff = datetime.date.fromisoformat(as_of)
    except Exception as exc:
        raise ValueError('invalid as_of date') from exc
    if not isinstance(payload, dict) or not isinstance(payload.get('policies'), list):
        raise ValueError('invalid payload')
    chosen = []
    for policy in payload['policies']:
        if not isinstance(policy, dict) or not all((k in policy for k in ('id', 'customer', 'current_premium', 'offers'))) or (not isinstance(policy['offers'], list)):
            raise ValueError('invalid policy')
        try:
            current = float(policy['current_premium'])
        except Exception as exc:
            raise ValueError('invalid premium') from exc
        if current < 0:
            raise ValueError('invalid premium')
        eligible = []
        for index, offer in enumerate(policy['offers']):
            if not isinstance(offer, dict) or not all((k in offer for k in ('effective', 'premium', 'deductible', 'coverage', 'status'))):
                raise ValueError('invalid offer')
            try:
                effective = datetime.date.fromisoformat(offer['effective'])
                premium = float(offer['premium'])
                deductible = float(offer['deductible'])
            except Exception as exc:
                raise ValueError('invalid offer') from exc
            if premium < 0 or deductible < 0:
                raise ValueError('invalid offer')
            if offer['status'] == 'offered' and effective <= cutoff:
                eligible.append((effective, premium, deductible, index, offer))
        if not eligible:
            continue
        _, premium, deductible, _, offer = max(eligible, key=lambda x: (x[0], -x[1], -x[2], -x[3]))
        if current == 0:
            if premium != 0:
                raise ValueError('cannot calculate percentage')
            change = 0.0
        else:
            change = round((premium - current) / current * 100, 2)
        chosen.append({'id': policy['id'], 'customer': policy['customer'], 'effective': offer['effective'], 'premium': offer['premium'], 'deductible': offer['deductible'], 'coverage': offer['coverage'], 'change_percent': change})
    return sorted(chosen, key=lambda x: (x['change_percent'], x['deductible'], x['id']))

def fetch_renewal_options(endpoint: str, policy_ids: list[str], as_of: str) -> list[dict]:
    try:
        response = requests.get(endpoint, params=[('policy_id', x) for x in policy_ids], headers={'Accept': 'application/json'}, timeout=10)
    except Exception as exc:
        raise ValueError('request failed') from exc
    if response.status_code != 200:
        raise ValueError(f'unexpected status {response.status_code}')
    try:
        payload = response.json()
    except Exception as exc:
        raise ValueError('invalid response json') from exc
    return normalize_policies(payload, as_of)

