import datetime
import requests

def _date(value):
    try:
        return datetime.date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def _time(value):
    try:
        if not isinstance(value, str) or len(value) != 5 or value[2] != ':':
            raise ValueError
        hour, minute = map(int, value.split(':'))
        if not (0 <= hour < 24 and 0 <= minute < 60):
            raise ValueError
        return hour * 60 + minute
    except (TypeError, ValueError):
        raise ValueError('invalid time')

def fetch_availability(service_date: str, client_id: str) -> list[dict]:
    _date(service_date)
    if not isinstance(client_id, str) or not client_id:
        raise ValueError('invalid client')
    r = requests.get('https://api.spaluna.example/v1/availability', params={'service_date': service_date, 'client_id': client_id}, headers={'Accept': 'application/json'})
    if r.status_code != 200:
        raise ValueError('request failed')
    try:
        body = r.json()
        therapists = body['therapists']
        if not isinstance(therapists, list):
            raise ValueError
        result = []
        for therapist in therapists:
            if not all((k in therapist for k in ('id', 'name', 'slots'))) or not isinstance(therapist['slots'], list):
                raise ValueError
            for slot in therapist['slots']:
                if not all((k in slot for k in ('start', 'end', 'treatments'))) or not isinstance(slot['treatments'], dict):
                    raise ValueError
                start, end = (_time(slot['start']), _time(slot['end']))
                if end <= start:
                    raise ValueError
                for price in slot['treatments'].values():
                    if isinstance(price, bool) or not isinstance(price, (int, float)) or price < 0:
                        raise ValueError
                result.append({'therapist_id': therapist['id'], 'therapist_name': therapist['name'], 'start': slot['start'], 'end': slot['end'], 'treatments': slot['treatments']})
        return result
