import html
from datetime import date, time

def render_appointment_page(records: list[dict], page: int=1, per_page: int=10) -> str:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(per_page, bool) or not isinstance(per_page, int) or (not 1 <= per_page <= 100):
        raise ValueError('invalid page size')
    checked = []
    required = {'applicant', 'office', 'date', 'time', 'status'}
    for record in records:
        if not isinstance(record, dict) or set(record) != required:
            raise ValueError('invalid record')
        if not isinstance(record['applicant'], str) or not record['applicant']:
            raise ValueError('invalid applicant')
        if not isinstance(record['office'], str) or not record['office']:
            raise ValueError('invalid office')
        try:
            date.fromisoformat(record['date'])
            time.fromisoformat(record['time'])
        except (TypeError, ValueError):
            raise ValueError('invalid date or time')
        if record['status'] not in {'scheduled', 'confirmed', 'cancelled'}:
            raise ValueError('invalid status')
        checked.append(record)
    checked.sort(key=lambda r: (r['date'], r['time'], r['applicant']))
    total = len(checked)
    pages = max(1, (total + per_page - 1) // per_page)
    if page > pages:
        raise ValueError('page out of range')
    start = (page - 1) * per_page
    selected = checked[start:start + per_page]
    end = start + len(selected)
    shown_start = start + 1 if selected else 0
    rows = ''.join(('<tr><td>' + html.escape(r['applicant'], quote=True) + '</td><td>' + html.escape(r['office'], quote=True) + '</td><td>' + html.escape(r['date'], quote=True) + '</td><td>' + html.escape(r['time'], quote=True) + '</td><td>' + html.escape(r['status'], quote=True) + '</td></tr>' for r in selected))
    return f'<div class="appointments"><h1>Passport appointments</h1><p class="summary">Showing {shown_start}-{end} of {total} appointments (page {page} of {pages})</p><table><thead><tr><th>Applicant</th><th>Office</th><th>Date</th><th>Time</th><th>Status</th></tr></thead><tbody>{rows}</tbody></table></div>'

