import requests

def fetch_erosion_hotspots(site_ids: list[str], threshold_cm: float, limit: int=10) -> list[dict]:
    if not isinstance(site_ids, list) or not site_ids or any((not isinstance(x, str) or not x for x in site_ids)):
        raise ValueError('invalid site_ids')
    if isinstance(threshold_cm, bool) or not isinstance(threshold_cm, (int, float)) or (not math.isfinite(threshold_cm)) or (threshold_cm < 0):
        raise ValueError('invalid threshold')
    if isinstance(limit, bool) or not isinstance(limit, int) or limit <= 0:
        raise ValueError('invalid limit')
    response = requests.get('https://api.coastwatch.example/v1/erosion', params={'sites': ','.join(site_ids), 'threshold_cm': threshold_cm, 'limit': limit}, headers={'Accept': 'application/json'})
    if response.status_code != 200:
        raise RuntimeError('coastwatch request failed')
    observations = response.json()['observations']
    best = {}
    selected_ids = set(site_ids)
    for observation in observations:
        if observation['site_id'] not in selected_ids or observation['change_cm'] < threshold_cm:
            continue
        current = best.get(observation['site_id'])
        if current is None or (observation['change_cm'], observation['date']) > (current['change_cm'], current['date']):
            best[observation['site_id']] = observation
    result = list(best.values())
    result.sort(key=lambda item: (-item['change_cm'], item['site_id']))
    return [{'site_id': item['site_id'], 'date': item['date'], 'change_cm': item['change_cm'], 'shoreline_m': item['shoreline_m']} for item in result[:limit]]

