        if observation['site_id'] not in selected_ids or observation['change_cm'] < threshold_cm:
            continue
        current = best.get(observation['site_id'])
        if current is None or (observation['change_cm'], observation['date']) > (current['change_cm'], current['date']):
            best[observation['site_id']] = observation
    result = list(best.values())
    result.sort(key=lambda item: (-item['change_cm'], item['site_id']))
    return [{'site_id': item['site_id'], 'date': item['date'], 'change_cm': item['change_cm'], 'shoreline_m': item['shoreline_m']} for item in result[:limit]]

