import json

def _validate(state):
    if not isinstance(state, dict) or set(state) != {'registrations', 'capacity'}:
        raise ValueError('invalid state')
    caps = state['capacity']
    regs = state['registrations']
    if not isinstance(caps, dict) or not isinstance(regs, list):
        raise ValueError('invalid state')
    for name, value in caps.items():
        if not isinstance(name, str) or not name or isinstance(value, bool) or (not isinstance(value, int)) or (value < 0):
            raise ValueError('invalid capacity')
    seen = set()
    for reg in regs:
        if not isinstance(reg, dict) or set(reg) != {'registration_id', 'person', 'sessions', 'registered_at', 'status'}:
            raise ValueError('invalid registration')
        rid = reg['registration_id']
        if not isinstance(rid, str) or not rid or rid in seen:
            raise ValueError('invalid registration')
        seen.add(rid)
        if not isinstance(reg['person'], str) or not reg['person']:
            raise ValueError('invalid registration')
        sessions = reg['sessions']
        if not isinstance(sessions, list) or not sessions or any((not isinstance(x, str) or not x or x not in caps for x in sessions)) or (len(set(sessions)) != len(sessions)):
            raise ValueError('invalid sessions')
        if isinstance(reg['registered_at'], bool) or not isinstance(reg['registered_at'], int):
            raise ValueError('invalid time')
        if reg['status'] not in ('confirmed', 'waitlist'):
            raise ValueError('invalid status')

def serialize_state(state: dict) -> bytes:
    _validate(state)
    return json.dumps(state, separators=(',', ':'), ensure_ascii=False).encode('utf-8')

def deserialize_state(blob: bytes) -> dict:
    try:
        state = json.loads(blob.decode('utf-8'))
        _validate(state)
        return state
    except (ValueError, TypeError, UnicodeError, json.JSONDecodeError):
        raise ValueError('invalid blob')

def registration_report(state: dict) -> list[dict]:
    _validate(state)
    grouped = {s: {'confirmed': [], 'waitlist': []} for s in state['capacity']}
    for reg in state['registrations']:
        for session in reg['sessions']:
            grouped[session][reg['status']].append(reg)
    result = []
    for session, groups in grouped.items():
        key = lambda r: (r['registered_at'], r['registration_id'])
        confirmed = sorted(groups['confirmed'], key=key)
        waitlist = sorted(groups['waitlist'], key=key)
        result.append({'session': session, 'confirmed': [r['person'] for r in confirmed], 'waitlist': [r['person'] for r in waitlist], 'remaining': max(0, state['capacity'][session] - len(confirmed))})
    return sorted(result, key=lambda x: (-len(x['confirmed']), x['session']))

