    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    allowed = {'Compliant': 'compliant', 'Needs Review': 'needs-review', 'Non-Compliant': 'non-compliant'}
    checked = []
    for record in records:
        if not isinstance(record, dict):
            raise TypeError('record must be a dictionary')
        for key in ('employee', 'site', 'status', 'score'):
            if key not in record:
                raise ValueError('missing field')
        if not isinstance(record['employee'], str) or not isinstance(record['site'], str):
            raise TypeError('text field must be a string')
        if not record['employee'] or not record['site']:
            raise ValueError('empty text field')
        if not isinstance(record['status'], str):
            raise TypeError('status must be a string')
        if record['status'] not in allowed:
            raise ValueError('invalid status')
        score = record['score']
        if isinstance(score, bool) or not isinstance(score, (int, float)):
            raise TypeError('score must be numeric')
        if not math.isfinite(score) or not 0 <= score <= 100:
            raise ValueError('invalid score')
        checked.append(record)
    ordered = sorted(checked, key=lambda r: (r['score'], r['employee'], r['site']))
    total = len(ordered)
    start = (page - 1) * page_size
    visible = ordered[start:start + page_size]
    counts = {name: sum((r['status'] == name for r in ordered)) for name in allowed}
    average = 'N/A' if not ordered else f"{sum((r['score'] for r in ordered)) / total:.1f}"
    lines = ['<div class="report">', '<h1>Safety Compliance Report</h1>', f"""<p class="summary">Showing {len(visible)} of {total} records | Compliant: {counts['Compliant']} | Needs Review: {counts['Needs Review']} | Non-Compliant: {counts['Non-Compliant']} | Average score: {average}</p>""", '<table>', '<thead><tr><th>Employee</th><th>Site</th><th>Status</th><th>Score</th></tr></thead>', '<tbody>']
    for record in visible:
        employee = html.escape(record['employee'], quote=True)
        site = html.escape(record['site'], quote=True)
        status = html.escape(record['status'], quote=True)
        lines.append(f'''<tr class="{allowed[record['status']]}"><td>{employee}</td><td>{site}</td><td>{status}</td><td>{record['score']:.1f}</td></tr>''')
    lines.extend(['</tbody>', '</table>', '</div>'])
    return '\n'.join(lines)

