import math
from datetime import datetime
import requests

def fetch_grants(endpoint: str, api_key: str, page_size: int=100) -> list[dict]:
    if page_size < 1 or page_size > 500:
        raise ValueError('page_size must be between 1 and 500')
    response = requests.get(endpoint, params={'limit': page_size}, headers={'X-API-Key': api_key}, timeout=10)
    if response.status_code != 200:
        raise ValueError(f'grant service returned status {response.status_code}')
    try:
        payload = response.json()
    except Exception:
        raise ValueError('invalid grant response')
    if not isinstance(payload, dict) or not isinstance(payload.get('grants'), list):
        raise ValueError('invalid grant response')
    return payload['grants']

def build_report(records: list[dict], fiscal_year: int) -> dict:
    if not isinstance(fiscal_year, int) or not 2000 <= fiscal_year <= 2100:
        raise ValueError('invalid fiscal year')
    seen = set()
    groups = {}
    for record in records:
        try:
            required = ('id', 'institution', 'amount', 'submitted_at', 'status', 'focus_areas')
            if any((key not in record for key in required)):
                raise ValueError
            ident = record['id']
            if not isinstance(ident, str) or not ident or ident in seen:
                if ident in seen:
                    raise ValueError('duplicate grant id')
                raise ValueError
            seen.add(ident)
            amount = record['amount']
            if isinstance(amount, bool) or not isinstance(amount, (int, float)) or (not math.isfinite(amount)) or (amount < 0):
                raise ValueError
            institution = record['institution']
            areas = record['focus_areas']
            if not isinstance(institution, str) or not isinstance(areas, list) or any((not isinstance(x, str) or not x for x in areas)):
                raise ValueError
            year = datetime.fromisoformat(record['submitted_at']).year
        except ValueError as exc:
            if str(exc) == 'duplicate grant id':
                raise
            raise ValueError('invalid grant record')
        except Exception:
            raise ValueError('invalid grant record')
        if record['status'] != 'awarded' or year != fiscal_year:
            continue
        group = groups.setdefault(institution, {'total': 0.0, 'count': 0, 'areas': {}})
        group['total'] += amount
        group['count'] += 1
        for area in areas:
            group['areas'][area] = group['areas'].get(area, 0) + 1
    institutions = []
    for name, group in groups.items():
        institutions.append({'name': name, 'total_awarded': round(group['total'], 2), 'grant_count': group['count'], 'focus_areas': dict(sorted(group['areas'].items()))})
    institutions.sort(key=lambda item: (-item['total_awarded'], item['name']))
    return {'fiscal_year': fiscal_year, 'institutions': institutions}

