from urllib.parse import quote
import requests

def _parse_time(value):
    if not isinstance(value, str):
        raise ValueError('invalid timestamp')
    try:
        return datetime.fromisoformat(value[:-1] + '+00:00' if value.endswith('Z') else value)
    except ValueError as exc:
        raise ValueError('invalid timestamp') from exc

def fetch_correspondence(taxpayer_id: str, since: str | None=None) -> list[dict]:
    if not isinstance(taxpayer_id, str) or not taxpayer_id.strip():
        raise ValueError('taxpayer_id must not be empty')
    url = 'https://api.taxoffice.example/v1/taxpayers/' + quote(taxpayer_id, safe='') + '/correspondence'
    kwargs = {'headers': {'Accept': 'application/json'}, 'timeout': 10, 'verify': True}
    if since is not None:
        kwargs['params'] = {'since': since}
    response = requests.get(url, **kwargs)
    if response.status_code != 200:
        raise RuntimeError('request failed with status ' + str(response.status_code))
    try:
        payload = response.json()
    except Exception as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(payload, dict) or not isinstance(payload.get('items'), list):
        raise ValueError('invalid payload')
    result = []
    for item in payload['items']:
        if not isinstance(item, dict) or not all((key in item for key in ('id', 'received_at', 'subject', 'status', 'messages'))):
            raise ValueError('invalid record')
        timestamp = _parse_time(item['received_at'])
        if not isinstance(item['messages'], list):
            raise ValueError('invalid messages')
        bodies = []
        for message in item['messages']:
            if not isinstance(message, dict) or not isinstance(message.get('body'), str):
                raise ValueError('invalid message')
            bodies.append(message['body'])
        result.append({'id': item['id'], 'received_at': item['received_at'], 'subject': item['subject'], 'status': item['status'], 'body': '\n'.join(bodies), '_time': timestamp})
    result.sort(key=lambda item: (-item['_time'].timestamp(), str(item['id'])))
    return [{key: item[key] for key in ('id', 'received_at', 'subject', 'status', 'body')} for item in result]

def build_digest(records: list[dict]) -> dict:
    statuses = {}
    months = {}
    latest = None
    latest_time = None
    for record in records:
        current = _parse_time(record['received_at'])
        status = record['status']
        statuses[status] = statuses.get(status, 0) + 1
        month = current.strftime('%Y-%m')
        months[month] = months.get(month, 0) + 1
        if latest_time is None or current > latest_time or (current == latest_time and str(record['id']) < str(latest['id'])):
            latest_time = current
            latest = record
    return {'total': len(records), 'statuses': {key: statuses[key] for key in sorted(statuses)}, 'months': {key: months[key] for key in sorted(months)}, 'latest_id': None if latest is None else latest['id']}

