import re
from datetime import datetime, timezone
import requests

def _time(value):
    if not isinstance(value, str):
        raise ValueError()
    try:
        text = value[:-1] + '+00:00' if value.endswith('Z') else value
        dt = datetime.fromisoformat(text).astimezone(timezone.utc).replace(microsecond=0)
        return dt
    except Exception as exc:
        raise ValueError() from exc

def _clean(value):
    return re.sub('\\\\s+', ' ', str(value)).strip()

def fetch_mentions(query: str, start: str, end: str, token: str | None=None) -> list[dict]:
    headers = {'Accept': 'application/json'}
    if token is not None:
        headers['Authorization'] = 'Bearer ' + token
    r = requests.get('https://media.example.test/v1/mentions', params={'q': query, 'start': start, 'end': end, 'limit': 100}, headers=headers)
    if r.status_code != 200:
        raise RuntimeError(f'media API returned {r.status_code}')
    data = r.json()
    if not isinstance(data, dict) or not isinstance(data.get('results'), list):
        raise ValueError()
    chosen = {}
    for pos, item in enumerate(data['results']):
        try:
            if not isinstance(item, dict):
                raise ValueError()
            keys = ('id', 'title', 'outlet', 'url', 'published_at', 'relevance')
            if any((k not in item for k in keys)):
                raise ValueError()
            when = _time(item['published_at'])
            score = float(item['relevance'])
            row = {'id': item['id'], 'title': _clean(item['title']), 'outlet': _clean(item['outlet']), 'url': item['url'], 'published_at': when.strftime('%Y-%m-%dT%H:%M:%SZ'), 'relevance': score}
        except (TypeError, ValueError) as exc:
            raise ValueError() from exc
        old = chosen.get(row['url'])
        if old is None or score > old[0]:
            chosen[row['url']] = (score, pos, row, when)
    vals = list(chosen.values())
    vals.sort(key=lambda x: (-x[3].timestamp(), -x[0], x[2]['id']))
    return [x[2] for x in vals]

def rank_outlets(mentions: list[dict], window_days: int=7) -> list[dict]:
    if window_days < 0:
        raise ValueError()
    if not mentions:
        return []
    dates = [_time(x['published_at']) for x in mentions]
    end = max(dates)
    groups = {}
    for row, dt in zip(mentions, dates):
        if (end - dt).total_seconds() <= window_days * 86400:
            groups.setdefault(row['outlet'], []).append((row, dt))
    out = []
    for outlet, rows in groups.items():
        latest = max(rows, key=lambda x: x[1])[1]
        avg = round(sum((float(x[0]['relevance']) for x in rows)) / len(rows), 2)
        out.append({'outlet': outlet, 'mentions': len(rows), 'average_relevance': avg, 'latest': latest.strftime('%Y-%m-%dT%H:%M:%SZ')})
    return sorted(out, key=lambda x: (-x['mentions'], -x['average_relevance'], x['outlet']))

def build_digest(mentions: list[dict], limit: int=3) -> str:
    if limit < 0:
        raise ValueError()
    ordered = sorted(mentions, key=lambda x: (-float(x['relevance']), -_time(x['published_at']).timestamp(), x['id']))[:limit]
    return '\n'.join((f"{x['outlet']}: {x['title']} ({x['published_at']})" for x in ordered))

