import math
from numbers import Real

def render_forecast_table(records: list[dict], unit: str='C', page: int=1, per_page: int=10) -> str:
    if unit not in ('C', 'F'):
        raise ValueError('unsupported unit')
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(per_page, bool) or not isinstance(per_page, int) or per_page <= 0 or (per_page > 100):
        raise ValueError('invalid per_page')
    checked = []
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        if not isinstance(record.get('city'), str) or not record['city']:
            raise ValueError('invalid city')
        if not isinstance(record.get('condition'), str):
            raise ValueError('invalid condition')
        temp = record.get('temp_c')
        humidity = record.get('humidity')
        if isinstance(temp, bool) or not isinstance(temp, Real) or (not math.isfinite(temp)):
            raise ValueError('invalid temperature')
        if isinstance(humidity, bool) or not isinstance(humidity, Real) or (not math.isfinite(humidity)) or (not 0 <= humidity <= 100):
            raise ValueError('invalid humidity')
        checked.append(record)
    checked.sort(key=lambda r: (-r['temp_c'], r['city'].casefold()))
    start = (page - 1) * per_page
    selected = checked[start:start + per_page]
    rows = []
    for record in selected:
        temperature = record['temp_c'] if unit == 'C' else record['temp_c'] * 9 / 5 + 32
        suffix = '°C' if unit == 'C' else '°F'
        humidity = record['humidity']
        humidity_text = str(int(humidity)) if humidity == int(humidity) else f'{humidity:.1f}'
        rows.append(f"<tr><td>{record['city']}</td><td>{temperature:.1f} {suffix}</td><td>{record['condition']}</td><td>{humidity_text}%</td></tr>")
