from datetime import date, datetime
from decimal import Decimal, InvalidOperation
from html import escape
STATUSES = {'pending', 'approved', 'received', 'cancelled'}

def parse_order_date(value: str) -> date:
    if not isinstance(value, str):
        raise TypeError('date must be a string')
    if len(value) != 10 or value[4] != '-' or value[7] != '-':
        raise ValueError('invalid date')
    try:
        result = datetime.strptime(value, '%Y-%m-%d').date()
    except ValueError:
        raise ValueError('invalid date')
    if result.isoformat() != value:
        raise ValueError('invalid date')
    return result

def _price(value):
    if isinstance(value, bool):
        raise TypeError('invalid price')
    try:
        number = Decimal(str(value))
    except (InvalidOperation, ValueError):
        raise ValueError('invalid price')
    if not number.is_finite() or number < 0 or number != number.quantize(Decimal('0.01')):
        raise ValueError('invalid price')
    return int(number * 100)

def _validate(orders):
    if not isinstance(orders, list):
        raise TypeError('orders must be a list')
    checked = []
    for order in orders:
        if not isinstance(order, dict):
            raise TypeError('order must be a dictionary')
        for key in ('id', 'supplier', 'ordered_on', 'status', 'items'):
            if key not in order:
                raise ValueError('missing order field')
        if not isinstance(order['id'], str) or not order['id']:
            raise ValueError('invalid id')
        if not isinstance(order['supplier'], str) or not order['supplier']:
            raise ValueError('invalid supplier')
        when = parse_order_date(order['ordered_on'])
        if order['status'] not in STATUSES:
            raise ValueError('invalid status')
        if not isinstance(order['items'], list):
            raise TypeError('items must be a list')
        if not order['items']:
            raise ValueError('items must not be empty')
        total = 0
        units = 0
        for item in order['items']:
            if not isinstance(item, dict):
                raise TypeError('item must be a dictionary')
            if not isinstance(item.get('sku'), str) or not item['sku']:
                raise ValueError('invalid sku')
            quantity = item.get('quantity')
            if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity <= 0:
                raise ValueError('invalid quantity')
            if 'unit_price' not in item:
                raise ValueError('missing price')
            units += quantity
            total += quantity * _price(item['unit_price'])
        checked.append((order['supplier'], when, units, total))
    return checked

def summarize_orders(orders: list[dict], since: str | None=None) -> list[dict]:
    checked = _validate(orders)
    start = None if since is None else parse_order_date(since)
    groups = {}
    for supplier, when, units, total in checked:
        if start is not None and when < start:
            continue
        entry = groups.setdefault(supplier, [0, 0, 0, when])
        entry[0] += 1
        entry[1] += units
        entry[2] += total
        entry[3] = max(entry[3], when)
    result = [{'supplier': s, 'orders': v[0], 'units': v[1], 'total': f'{v[2] / 100:.2f}', 'latest': v[3].isoformat()} for s, v in groups.items()]
    result.sort(key=lambda x: (-int(Decimal(x['total']) * 100), x['supplier'].casefold(), x['supplier']))
    return result

def render_purchase_report(orders: list[dict], since: str | None=None) -> str:
    rows = []
    for item in summarize_orders(orders, since):
        rows.append(f"<tr><td>{escape(item['supplier'], quote=True)}</td><td>{item['orders']}</td><td>{item['units']}</td><td>{item['total']}</td><td>{item['latest']}</td></tr>")
    return '<section class="purchase-report"><h1>Wholesale purchase orders</h1><table><thead><tr><th>Supplier</th><th>Orders</th><th>Units</th><th>Total</th><th>Latest order</th></tr></thead><tbody>' + ''.join(rows) + '</tbody></table></section>'

