import json
import datetime

def _check_record(record):
    if not isinstance(record, dict) or set(record) != {'machine', 'date', 'hours', 'task', 'parts'}:
        raise ValueError('invalid record')
    if not isinstance(record['machine'], str) or not record['machine']:
        raise ValueError('invalid machine')
    if not isinstance(record['task'], str) or not record['task']:
        raise ValueError('invalid task')
    if isinstance(record['hours'], bool) or not isinstance(record['hours'], int) or record['hours'] < 0:
        raise ValueError('invalid hours')
    if not isinstance(record['parts'], list) or any((not isinstance(x, str) for x in record['parts'])):
        raise ValueError('invalid parts')
    try:
        datetime.date.fromisoformat(record['date'])
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def encode_maintenance_log(records: list[dict]) -> bytes:
    if not isinstance(records, list):
        raise ValueError('invalid log')
    for record in records:
        _check_record(record)
    return json.dumps(records, separators=(',', ':')).encode('utf-8')

def decode_maintenance_log(blob: bytes) -> list[dict]:
    if not isinstance(blob, (bytes, bytearray, memoryview)):
        raise ValueError('invalid blob')
    try:
        value = json.loads(bytes(blob).decode('utf-8'))
        if not isinstance(value, list):
            raise ValueError('invalid log')
        for record in value:
            _check_record(record)
        return value
    except (ValueError, TypeError, UnicodeError, json.JSONDecodeError):
        raise ValueError('invalid blob')

def summarize_maintenance(records: list[dict], window_days: int=30) -> list[dict]:
    if isinstance(window_days, bool) or not isinstance(window_days, int) or window_days <= 0:
        raise ValueError('invalid window')
    if not isinstance(records, list):
        raise ValueError('invalid records')
    for record in records:
        _check_record(record)
    if not records:
        return []
    dates = [datetime.date.fromisoformat(x['date']) for x in records]
    cutoff = max(dates) - datetime.timedelta(days=window_days - 1)
    groups = {}
    for record, date in zip(records, dates):
        if date < cutoff:
            continue
        group = groups.setdefault(record['machine'], {'hours': 0, 'latest': date, 'tasks': {}, 'parts': {}})
        group['hours'] += record['hours']
        group['latest'] = max(group['latest'], date)
        group['tasks'][record['task']] = group['tasks'].get(record['task'], 0) + 1
        for part in record['parts']:
            group['parts'][part] = group['parts'].get(part, 0) + 1
    result = []
    for machine in sorted(groups):
        group = groups[machine]
        result.append({'machine': machine, 'total_hours': group['hours'], 'latest_date': group['latest'].isoformat(), 'task_counts': [[k, v] for k, v in sorted(group['tasks'].items(), key=lambda x: (-x[1], x[0]))], 'part_counts': [[k, v] for k, v in sorted(group['parts'].items(), key=lambda x: (-x[1], x[0]))]})
    return result

