from solution import parse_records, qualify, render_report
import pytest


def test_parse_records_decodes_escaped_fields_and_types():
    text = r"12 Main St|North|1000|100|8|yes|FiberCo\|Plus"
    assert parse_records(text) == [{
        "address": "12 Main St", "region": "North", "download": 1000,
        "upload": 100, "latency": 8, "available": True, "provider": "FiberCo|Plus"
    }]


def test_parse_records_ignores_blank_lines_and_backslashes():
    text = "\nA\\\\B|South|50|10|20|no|Cable\\\\Net\n\n"
    assert parse_records(text) == [{
        "address": "A\\B", "region": "South", "download": 50,
        "upload": 10, "latency": 20, "available": False, "provider": "Cable\\Net"
    }]


def test_parse_records_rejects_bad_rows_and_values():
    with pytest.raises(ValueError):
        parse_records("A|R|10|5|1|yes")
    with pytest.raises(ValueError):
        parse_records("A|R|-1|5|1|yes|P")
    with pytest.raises(ValueError):
        parse_records("A|R|10|5|0|yes|P")
    with pytest.raises(ValueError):
        parse_records("A|R|10|5|1|maybe|P")
    with pytest.raises(ValueError):
        parse_records("A|R|10|5|1|yes|P\\")


def test_qualify_filters_sorts_and_aggregates():
    records = parse_records("""Zed|North|100|20|10|yes|Beta
Alpha|North|200|20|10|yes|AlphaNet
Bravo|North|200|15|5|yes|AlphaNet
Offline|North|900|1|1|no|Beta
South|South|900|1|1|yes|Beta
Slow|North|200|20|20|yes|Beta""")
