import html

def parse_records(text: str) -> list[dict]:
    rows = []
    for line in text.splitlines():
        if not line:
            continue
        fields, current, escaped = ([], [], False)
        for char in line:
            if escaped:
                current.append(char)
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '|':
                fields.append(''.join(current))
                current = []
            else:
                current.append(char)
