import requests

def fetch_manifest(collection_id: str, api_key: str, cursor: str | None=None) -> dict:
    params = {'limit': 100}
    if cursor is not None:
        params['cursor'] = cursor
    response = requests.get(f'https://assets.example.test/v1/collections/{collection_id}/manifest', params=params, headers={'X-API-Key': api_key})
    if response.status_code != 200:
        raise RuntimeError(f'manifest request failed: {response.status_code}')
    return response.json()

def normalize_manifest(manifest: dict) -> list[dict]:
    if not isinstance(manifest, dict) or not isinstance(manifest.get('assets'), list):
        raise ValueError('invalid manifest')
    result = []
    for asset in manifest['assets']:
        if not isinstance(asset, dict) or not isinstance(asset.get('id'), str) or (not isinstance(asset.get('filename'), str)):
            raise ValueError('invalid asset')
        if asset.get('archived', False) is True:
            continue
        variants = asset.get('variants')
        if not isinstance(variants, list):
            raise ValueError('invalid variants')
        tags = asset.get('tags', [])
        if not isinstance(tags, list) or any((not isinstance(x, str) for x in tags)):
            raise ValueError('invalid tags')
        unique_tags = list(dict.fromkeys(tags))
        seen = set()
        total = 0
        for variant in variants:
            if not isinstance(variant, dict) or not isinstance(variant.get('id'), str):
                raise ValueError('invalid variant')
            amount = variant.get('bytes')
            if isinstance(amount, bool) or not isinstance(amount, int) or amount < 0:
                raise ValueError('invalid byte count')
            if variant['id'] not in seen:
                seen.add(variant['id'])
                total += amount
        result.append({'id': asset['id'], 'filename': asset['filename'], 'bytes': total, 'tags': unique_tags})
    return sorted(result, key=lambda x: (-x['bytes'], x['id']))

def build_report(records: list[dict], max_per_tag: int=3) -> dict:
    if isinstance(max_per_tag, bool) or not isinstance(max_per_tag, int) or max_per_tag <= 0:
        raise ValueError('invalid limit')
    totals = {}
    counts = {}
    for record in records:
        tags = set(record['tags'])
        for tag in tags:
            totals[tag] = totals.get(tag, 0) + record['bytes']
            counts[tag] = counts.get(tag, 0) + 1
    assets = [{'id': r['id'], 'filename': r['filename'], 'bytes': r['bytes'], 'tags': list(r['tags'])} for r in records[:max_per_tag]]
    by_tag = [{'tag': tag, 'assets': counts[tag], 'bytes': totals[tag]} for tag in sorted(totals)]
    return {'assets': assets, 'by_tag': by_tag}

