import math
import requests

def load_subscriber_summary(region: str, min_monthly_fee: float=0.0) -> list[dict]:
    if not isinstance(region, str) or not region:
        raise ValueError('region must be a non-empty string')
    if isinstance(min_monthly_fee, bool) or not isinstance(min_monthly_fee, (int, float)) or (not math.isfinite(min_monthly_fee)) or (min_monthly_fee < 0):
        raise ValueError('invalid minimum fee')
    groups = {}
    cursor = None
    while True:
        params = {'region': region, 'limit': 100}
        if cursor is not None:
            params['cursor'] = cursor
        result = requests.get('https://provisioning.example.test/v1/subscribers', params=params, timeout=10)
        if result.status_code != 200:
            raise RuntimeError('subscriber service returned an error')
        data = result.json()
        for subscriber in data['subscribers']:
            fee = subscriber['monthly_fee']
            if subscriber['status'] == 'active' and fee >= min_monthly_fee:
                plan = subscriber['plan']
                group = groups.setdefault(plan, [0, 0.0])
                group[0] += 1
                group[1] += fee
        cursor = data.get('next_cursor')
        if cursor is None:
            break
    output = []
    for plan, (count, total) in groups.items():
        output.append({'plan': plan, 'count': count, 'total_monthly_fee': round(total, 2), 'average_monthly_fee': round(total / count, 2)})
    output.sort(key=lambda item: (-item['count'], item['plan']))
    return output

