import json

def _validate(order):
    if not isinstance(order, dict) or set(order) != {'order_id', 'items'}:
        raise ValueError('invalid order')
    if not isinstance(order['order_id'], str) or not order['order_id']:
        raise ValueError('invalid order')
    if not isinstance(order['items'], list):
        raise ValueError('invalid order')
    for item in order['items']:
        if not isinstance(item, dict) or set(item) != {'name', 'station', 'quantity'}:
            raise ValueError('invalid order')
        if not isinstance(item['name'], str) or not item['name']:
            raise ValueError('invalid order')
        if not isinstance(item['station'], str) or not item['station']:
            raise ValueError('invalid order')
        if isinstance(item['quantity'], bool) or not isinstance(item['quantity'], int) or item['quantity'] <= 0:
            raise ValueError('invalid order')

def encode_order(order: dict) -> bytes:
    _validate(order)
    try:
        return json.dumps(order, separators=(',', ':')).encode('utf-8')
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid order') from exc

def decode_order(blob: bytes) -> dict:
    if not isinstance(blob, bytes):
        raise ValueError('invalid blob')
    try:
        order = json.loads(blob.decode('utf-8'))
        _validate(order)
        return order
    except Exception as exc:
        if isinstance(exc, ValueError) and str(exc) == 'invalid order':
            raise
        raise ValueError('invalid blob') from exc

def route_order(order: dict) -> dict[str, list[str]]:
    _validate(order)
    grouped = {}
    for item in order['items']:
        grouped.setdefault(item['station'], []).append(item['name'])
    return {station: grouped[station] for station in sorted(grouped)}

