import math
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
import requests

def summarize_campaign_donations(campaign_id: str, api_token: str, minimum_amount: float=0.0) -> list[dict]:
    if not isinstance(campaign_id, str) or not campaign_id:
        raise ValueError('invalid campaign_id')
    if not isinstance(api_token, str) or not api_token:
        raise ValueError('invalid api_token')
    if isinstance(minimum_amount, bool) or not isinstance(minimum_amount, (int, float)) or (not math.isfinite(minimum_amount)) or (minimum_amount < 0):
        raise ValueError('invalid minimum_amount')
    response = requests.get(f'https://api.givewell.example/v1/campaigns/{campaign_id}/donations', params={'status': 'completed'}, headers={'Authorization': f'Bearer {api_token}'})
    if response.status_code != 200:
        raise RuntimeError('request failed')
    body = response.json()
    if not isinstance(body, dict) or not isinstance(body.get('donations'), list):
        raise ValueError('invalid response')
    groups = {}
    for donation in body['donations']:
        if not isinstance(donation, dict):
            raise ValueError('invalid donation')
        donor = donation.get('donor_id')
        currency = donation.get('currency')
        amount = donation.get('amount')
        if not isinstance(donor, str) or not donor or (not isinstance(currency, str)) or (not currency):
            raise ValueError('invalid donation')
        if isinstance(amount, bool) or not isinstance(amount, (int, float)) or (not math.isfinite(amount)) or (amount < 0):
            raise ValueError('invalid donation')
        if amount < minimum_amount:
            continue
        try:
            value = Decimal(str(amount))
        except (InvalidOperation, ValueError):
            raise ValueError('invalid donation')
        if donor not in groups:
            groups[donor] = [Decimal('0'), 0]
        groups[donor][0] += value
        groups[donor][1] += 1
    result = []
    for donor, (total, count) in groups.items():
        rounded = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        result.append({'donor_id': donor, 'total': float(rounded), 'donation_count': count})
    result.sort(key=lambda item: (-item['total'], item['donor_id']))
    return result

