def render_campaign_report(campaign_name: str, recipients: list[dict], page: int=1, page_size: int=10) -> str:
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    if not isinstance(recipients, list):
        raise ValueError('invalid recipients')
    rows = []
    for item in recipients:
        if not isinstance(item, dict):
            raise ValueError('invalid recipient')
        try:
            name, email, status = (item['name'], item['email'], item['status'])
            opens, clicks = (item['opens'], item['clicks'])
        except KeyError as exc:
            raise ValueError('missing recipient field') from exc
        if not isinstance(name, str) or not isinstance(email, str) or (not isinstance(status, str)):
            raise ValueError('invalid recipient text')
        if status not in {'delivered', 'bounced', 'pending'}:
            raise ValueError('invalid status')
        if type(opens) is not int or type(clicks) is not int or opens < 0 or (clicks < 0) or (clicks > opens):
            raise ValueError('invalid counts')
        rows.append(item)
    rows.sort(key=lambda x: (-x['clicks'], -x['opens'], x['email']))
    total = len(rows)
    pages = (total + page_size - 1) // page_size
    if page > pages and (not (total == 0 and page == 1)):
        raise ValueError('page out of range')
    delivered = sum((x['status'] == 'delivered' for x in rows))
    opens = sum((x['opens'] for x in rows))
    clicks = sum((x['clicks'] for x in rows))
    open_rate = opens * 100 / total if total else 0
    click_rate = clicks * 100 / total if total else 0
    start = (page - 1) * page_size
    selected = rows[start:start + page_size]
    body = ''.join((f"<tr><td>{escape(x['name'])}</td><td>{escape(x['email'])}</td><td>{escape(x['status'])}</td><td>{x['opens']}</td><td>{x['clicks']}</td></tr>" for x in selected))
    return f'<section class="campaign-report">\n<h1>Campaign: {escape(campaign_name)}</h1>\n<p class="summary">Recipients: {total} | Delivered: {delivered} | Open rate: {open_rate:.1f}% | Click rate: {click_rate:.1f}%</p>\n<table><thead><tr><th>Name</th><th>Email</th><th>Status</th><th>Opens</th><th>Clicks</th></tr></thead><tbody>{body}</tbody></table>\n<p class="page">Page {page} of {pages}</p>\n</section>'

