def get_soil_moisture(station_id: str, start_date: str, end_date: str, api_key: str) -> list[dict]:
    if not station_id or not start_date or (not end_date):
        raise ValueError('station and dates are required')
    if start_date > end_date:
        raise ValueError('invalid date range')
    response = requests.get('https://api.soilmonitor.example/v1/readings', params={'station_id': station_id, 'start_date': start_date, 'end_date': end_date}, headers={'Authorization': 'Bearer ' + api_key}, timeout=10)
