        raise RuntimeError('soil moisture service returned an error')
    try:
        payload = response.json()
    except Exception as exc:
        raise ValueError('invalid response JSON') from exc
    readings = payload.get('readings') if isinstance(payload, dict) else None
    if not isinstance(readings, list):
        raise ValueError('invalid readings')
    result = []
    for reading in readings:
        if not isinstance(reading, dict) or 'timestamp' not in reading or 'moisture' not in reading:
            raise ValueError('invalid reading')
        try:
            moisture = float(reading['moisture'])
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid moisture') from exc
        result.append({'timestamp': reading['timestamp'], 'moisture_percent': round(moisture, 2)})
    return sorted(result, key=lambda item: item['timestamp'])

