from solution import encode_state, decode_state, tender_loads
import pytest

def test_state_round_trip():
    state = {'awarded': ['L1', 'L2'], 'sequence': 8, 'meta': {'day': 'mon'}}
    assert decode_state(encode_state(state)) == state

def test_priority_due_and_id_order_with_carrier_tiebreak():
    loads = [{'id': 'B', 'origin': 'A', 'destination': 'X', 'weight': 4, 'ready': '2025-01-01T01:00:00Z', 'due': '2025-01-02T00:00:00Z', 'priority': 2}, {'id': 'A', 'origin': 'A', 'destination': 'X', 'weight': 3, 'ready': '2025-01-01T01:00:00Z', 'due': '2025-01-01T12:00:00Z', 'priority': 2}, {'id': 'C', 'origin': 'A', 'destination': 'X', 'weight': 1, 'ready': '2025-01-01T01:00:00Z', 'due': '2025-01-01T01:00:00Z', 'priority': 3}]
    carriers = [{'name': 'Zulu', 'lanes': ['A>X'], 'capacity': 10, 'rate': 2}, {'name': 'Alpha', 'lanes': ['A>X'], 'capacity': 10, 'rate': 2}]
    out = tender_loads(loads, carriers, encode_state({'awarded': [], 'sequence': 4}))
    assert [x['load_id'] for x in out['assignments']] == ['C', 'A', 'B']
    assert [x['carrier'] for x in out['assignments']] == ['Alpha', 'Alpha', 'Alpha']
    assert [x['cost'] for x in out['assignments']] == [2, 6, 8]
    assert decode_state(out['state']) == {'awarded': ['C', 'A', 'B'], 'sequence': 7}

def test_existing_and_bad_window_are_rejected():
    load = {'id': 'old', 'origin': 'A', 'destination': 'B', 'weight': 1, 'ready': '2025-01-02T00:00:00Z', 'due': '2025-01-01T00:00:00Z', 'priority': 9}
    fresh = dict(load, id='fresh', ready='2025-01-01T00:00:00Z', due='2025-01-02T00:00:00Z')
    carrier = {'name': 'C', 'lanes': ['A>B'], 'capacity': 5, 'rate': 1}
    out = tender_loads([load, fresh], [carrier], encode_state({'awarded': ['old'], 'sequence': 2}))
    assert out['assignments'] == [{'load_id': 'fresh', 'carrier': 'C', 'cost': 1}]
    assert out['rejected'] == ['old']

def test_empty_inputs_preserve_state():
    state = {'awarded': ['x'], 'sequence': 12, 'note': 'keep'}
    out = tender_loads([], [], encode_state(state))
    assert out['assignments'] == [] and out['rejected'] == []
    assert decode_state(out['state']) == state

def test_bad_state_and_records_raise_value_error():
    with pytest.raises(ValueError):
        decode_state(b'not a state')
    with pytest.raises(ValueError):
        decode_state(encode_state({'awarded': 'x', 'sequence': 1}))
    carrier = {'name': 'C', 'lanes': ['A>B'], 'capacity': 2, 'rate': 1}
    bad = {'id': 'x', 'origin': 'A', 'destination': 'B', 'weight': 0, 'ready': 'bad', 'due': 'bad', 'priority': 1}
    with pytest.raises(ValueError):
        tender_loads([bad], [carrier], encode_state({'awarded': [], 'sequence': 0}))

def test_duplicate_names_and_ids_raise():
    base = {'id': 'x', 'origin': 'A', 'destination': 'B', 'weight': 1, 'ready': '2025-01-01T00:00:00Z', 'due': '2025-01-01T01:00:00Z', 'priority': 1}
    c = {'name': 'C', 'lanes': ['A>B'], 'capacity': 2, 'rate': 1}
    with pytest.raises(ValueError):
        tender_loads([base, dict(base)], [c], encode_state({'awarded': [], 'sequence': 0}))
    with pytest.raises(ValueError):
        tender_loads([base], [c, dict(c)], encode_state({'awarded': [], 'sequence': 0}))

