from datetime import datetime

def encode_state(state: dict) -> bytes:
    return json.dumps(state, separators=(',', ':'), sort_keys=True).encode('utf-8')

def decode_state(blob: bytes) -> dict:
    try:
        value = json.loads(blob.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid state') from exc
    if not isinstance(value, dict) or not isinstance(value.get('awarded'), list) or (not isinstance(value.get('sequence'), int)) or isinstance(value.get('sequence'), bool):
        raise ValueError('invalid state')
    return value

def _time(value):
    try:
        return datetime.strptime(value, '%Y-%m-%dT%H:%M:%SZ')
    except Exception as exc:
        raise ValueError('invalid timestamp') from exc

def tender_loads(loads: list[dict], carriers: list[dict], state_blob: bytes) -> dict:
    state = decode_state(state_blob)
    if any((not isinstance(x, str) for x in state['awarded'])):
        raise ValueError('invalid state')
    seen = set()
    for load in loads:
        if not isinstance(load, dict) or not isinstance(load.get('id'), str) or load['id'] in seen:
            raise ValueError('invalid load')
        seen.add(load['id'])
        for key in ('origin', 'destination', 'ready', 'due'):
            if not isinstance(load.get(key), str):
                raise ValueError('invalid load')
        if not isinstance(load.get('priority'), int) or isinstance(load['priority'], bool) or (not isinstance(load.get('weight'), (int, float))) or isinstance(load['weight'], bool) or (load['weight'] <= 0):
            raise ValueError('invalid load')
        load['_ready'] = _time(load['ready'])
        load['_due'] = _time(load['due'])
    names = set()
    remaining = {}
    for carrier in carriers:
        if not isinstance(carrier, dict) or not isinstance(carrier.get('name'), str) or carrier['name'] in names or (not isinstance(carrier.get('lanes'), list)) or (not isinstance(carrier.get('capacity'), (int, float))) or (not isinstance(carrier.get('rate'), (int, float))) or (carrier['capacity'] <= 0) or (carrier['rate'] <= 0):
            raise ValueError('invalid carrier')
        names.add(carrier['name'])
        remaining[carrier['name']] = carrier['capacity']
    ordered = sorted(loads, key=lambda x: (-x['priority'], x['_due'], x['id']))
    assignments = []
    rejected = []
    awarded = list(state['awarded'])
    for load in ordered:
        if load['id'] in awarded or load['_ready'] > load['_due']:
            rejected.append(load['id'])
            continue
        lane = load['origin'] + '>' + load['destination']
        choices = [c for c in carriers if lane in c['lanes'] and remaining[c['name']] >= load['weight']]
        if not choices:
            rejected.append(load['id'])
            continue
        carrier = min(choices, key=lambda c: (c['rate'], c['name']))
        remaining[carrier['name']] -= load['weight']
        cost = load['weight'] * carrier['rate']
        assignments.append({'load_id': load['id'], 'carrier': carrier['name'], 'cost': cost})
        awarded.append(load['id'])
    for load in loads:
        load.pop('_ready', None)
        load.pop('_due', None)
    newstate = dict(state)
    newstate['awarded'] = awarded
    newstate['sequence'] = state['sequence'] + len(assignments)
    return {'assignments': assignments, 'rejected': rejected, 'state': encode_state(newstate)}

