import html
import math

def render_arcade_telemetry(records: list[dict], page: int=1, page_size: int=10) -> str:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        if set(record) != {'machine', 'game', 'plays', 'errors', 'uptime'}:
            raise ValueError('invalid record')
        machine = record['machine']
        game = record['game']
        plays = record['plays']
        errors = record['errors']
        uptime = record['uptime']
        if not isinstance(machine, str) or not machine or (not isinstance(game, str)) or (not game):
            raise ValueError('invalid record')
        if not isinstance(plays, int) or isinstance(plays, bool) or plays < 0:
            raise ValueError('invalid record')
        if not isinstance(errors, int) or isinstance(errors, bool) or errors < 0:
            raise ValueError('invalid record')
        if isinstance(uptime, bool) or not isinstance(uptime, (int, float)) or (not math.isfinite(uptime)) or (not 0 <= uptime <= 100):
            raise ValueError('invalid record')
        key = (machine, game)
        if key not in groups:
            groups[key] = [0, 0, 0.0, 0]
        groups[key][0] += plays
        groups[key][1] += errors
        groups[key][2] += uptime
        groups[key][3] += 1
    items = [(m, g, v[0], v[1], v[2] / v[3]) for (m, g), v in groups.items()]
    items.sort(key=lambda x: (-x[2], x[0], x[1]))
    start = (page - 1) * page_size
    selected = items[start:start + page_size]
    rows = ''.join((f"<tr><td>{html.escape(m)}</td><td>{html.escape(g)}</td><td>{html.escape(str(p))}</td><td>{html.escape(str(e))}</td><td>{html.escape(f'{u:.1f}')}%</td></tr>" for m, g, p, e, u in selected))
    return f'<div class="telemetry-report"><h1>Arcade telemetry</h1><p>Showing {len(selected)} of {len(items)} entries</p><table><thead><tr><th>Machine</th><th>Game</th><th>Plays</th><th>Errors</th><th>Uptime</th></tr></thead><tbody>{rows}</tbody></table></div>'

