import json

def _validate(records):
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    fields = {'incident_id', 'team', 'severity', 'reported_at', 'status'}
    statuses = {'open', 'investigating', 'closed'}
    for record in records:
        if not isinstance(record, dict) or set(record) != fields:
            raise ValueError('invalid incident')
        if not isinstance(record['incident_id'], str) or not record['incident_id']:
            raise ValueError('invalid incident id')
        if not isinstance(record['team'], str) or not record['team']:
            raise ValueError('invalid team')
        if isinstance(record['severity'], bool) or not isinstance(record['severity'], int) or (not 1 <= record['severity'] <= 5):
            raise ValueError('invalid severity')
        if isinstance(record['reported_at'], bool) or not isinstance(record['reported_at'], int):
            raise ValueError('invalid timestamp')
        if record['status'] not in statuses:
            raise ValueError('invalid status')

def pack_incident_state(records: list[dict]) -> bytes:
    _validate(records)
    try:
        return json.dumps(records, ensure_ascii=False, separators=(',', ':')).encode('utf-8')
    except (TypeError, ValueError, UnicodeError) as exc:
        raise ValueError('cannot encode state') from exc

def rank_incident_teams(payload: bytes, start: int, end: int, limit: int) -> list[dict]:
    if isinstance(start, bool) or not isinstance(start, int) or isinstance(end, bool) or (not isinstance(end, int)) or (start > end):
        raise ValueError('invalid range')
    if isinstance(limit, bool) or not isinstance(limit, int) or limit <= 0:
        raise ValueError('invalid limit')
    try:
        records = json.loads(payload.decode('utf-8'))
        _validate(records)
    except Exception as exc:
        if isinstance(exc, ValueError):
            raise
        raise ValueError('invalid payload') from exc
    groups = {}
    for record in records:
        if start <= record['reported_at'] <= end:
            team = record['team']
            group = groups.setdefault(team, {'team': team, 'total': 0, 'open': 0, 'critical': 0, 'latest': record['reported_at'], 'incident_ids': []})
            group['total'] += 1
            group['open'] += record['status'] != 'closed'
            group['critical'] += record['severity'] >= 4
            group['latest'] = max(group['latest'], record['reported_at'])
            group['incident_ids'].append(record['incident_id'])
    for group in groups.values():
        group['incident_ids'].sort()
    return sorted(groups.values(), key=lambda x: (-x['critical'], -x['open'], -x['total'], -x['latest'], x['team']))[:limit]

