import json
import math

def encode_readings(readings: list[dict]) -> bytes:
    return json.dumps(readings, separators=(',', ':')).encode('utf-8')

def summarize_pressure(payload: bytes, minimum: float, maximum: float, page: int=1, page_size: int=10) -> list[dict]:
    if minimum > maximum or isinstance(page, bool) or isinstance(page_size, bool) or (page <= 0) or (page_size <= 0):
        raise ValueError('invalid range or page')
    try:
        records = json.loads(payload.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    groups = {}
    for record in records:
        if not isinstance(record, dict) or set(record) != {'station', 'pressure', 'timestamp'}:
            raise ValueError('invalid record')
        station = record['station']
        pressure = record['pressure']
        timestamp = record['timestamp']
        if not isinstance(station, str) or not station:
            raise ValueError('invalid station')
        if isinstance(pressure, bool) or not isinstance(pressure, (int, float)) or (not math.isfinite(pressure)):
            raise ValueError('invalid pressure')
        if isinstance(timestamp, bool) or not isinstance(timestamp, int):
            raise ValueError('invalid timestamp')
        if minimum <= pressure <= maximum:
            groups.setdefault(station, []).append(pressure)
    result = []
    for station, values in groups.items():
        result.append({'station': station, 'count': len(values), 'minimum': min(values), 'maximum': max(values), 'average': round(sum(values) / len(values), 2)})
    result.sort(key=lambda item: (-item['average'], item['station']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

