import requests

def fetch_assignment_grade(student_id: str, assignment_id: str, api_token: str) -> dict:
    if not student_id or not assignment_id or (not api_token):
        raise ValueError('student_id, assignment_id, and api_token are required')
    url = f'https://grading.bootcamp.example/api/v1/grades/{student_id}/{assignment_id}'
    headers = {'Authorization': f'Bearer {api_token}', 'Accept': 'application/json'}
    response = requests.get(url, headers=headers, timeout=10)
    if response.status_code == 404:
        raise LookupError('grade not found')
    if response.status_code != 200:
        raise RuntimeError(f'grading service returned {response.status_code}')
    data = response.json()
    if not isinstance(data, dict) or 'score' not in data:
        raise ValueError('invalid grade response')
    return {'student_id': student_id, 'assignment_id': assignment_id, 'score': data['score'], 'feedback': data.get('feedback', '')}

