import re
from datetime import datetime, timezone
from html import escape
_LEVELS = {'DEBUG': 0, 'INFO': 1, 'WARN': 2, 'ERROR': 3}
_SERVICE = re.compile('^[A-Za-z0-9_.-]+$')

def parse_log_line(line: str) -> dict:
    if not isinstance(line, str):
        raise ValueError('line must be a string')
    parts = line.split(' ', 3)
    if len(parts) != 4:
        raise ValueError('malformed line')
    stamp, level, service, message = parts
    if level not in _LEVELS or not _SERVICE.fullmatch(service):
        raise ValueError('invalid fields')
    try:
        timestamp = datetime.strptime(stamp, '%Y-%m-%dT%H:%M:%SZ').replace(tzinfo=timezone.utc)
    except ValueError as exc:
        raise ValueError('invalid timestamp') from exc
    return {'timestamp': timestamp, 'level': level, 'service': service, 'message': message}

def aggregate_logs(lines: list[str], window_seconds: int=300) -> list[dict]:
    if isinstance(window_seconds, bool) or not isinstance(window_seconds, int) or window_seconds <= 0:
        raise ValueError('window_seconds must be positive')
    groups = {}
    epoch = datetime(1970, 1, 1, tzinfo=timezone.utc)
    for line in lines:
        if not line.strip():
            continue
        try:
            event = parse_log_line(line)
        except ValueError:
