    first = True
    while url:
        kwargs = {'headers': {'Accept': 'application/json'}}
        if first:
            kwargs['params'] = {'employee_ids': ','.join(ids), 'as_of': as_of}
            first = False
        response = requests.get(url, **kwargs)
