            raise ValueError('bad response')
        try:
            body = response.json()
        except Exception:
            raise ValueError('invalid response')
        if not isinstance(body, dict) or not isinstance(body.get('items'), list):
            raise ValueError('invalid response')
        records.extend(body['items'])
        url = body.get('next')
        if url is not None and (not isinstance(url, str)):
            raise ValueError('invalid response')
    chosen = {x: [] for x in ids}
    cutoff = date.fromisoformat(as_of)
    for item in records:
        if not isinstance(item, dict) or item.get('employee_id') not in chosen:
            continue
        if not isinstance(item.get('course'), str) or not item['course'] or item.get('status') not in ('completed', 'assigned'):
            raise ValueError('invalid record')
