                score = item['score']
                if isinstance(score, bool) or not isinstance(score, (int, float)) or (not 0 <= score <= 100):
                    raise ValueError
            except (KeyError, TypeError, ValueError):
                raise ValueError('invalid record')
            chosen[item['employee_id']].append(('completed', completed <= cutoff, float(score)))
        else:
            chosen[item['employee_id']].append(('assigned', due < cutoff, None))
    employees = []
    for employee_id in sorted(chosen):
        entries = chosen[employee_id]
        scores = [x[2] for x in entries if x[0] == 'completed' and x[1]]
        employees.append({'employee_id': employee_id, 'completed': len(scores), 'overdue': sum((x[0] == 'assigned' and x[1] for x in entries)), 'average_score': round(sum(scores) / len(scores), 2) if scores else None})
    return {'as_of': as_of, 'employees': employees}

