def _validate(value):
    if not isinstance(value, dict) or set(value) != {'nodes'} or (not isinstance(value['nodes'], list)):
        raise ValueError('invalid state')
    seen = set()
    fields = {'name', 'zone', 'status', 'last_seen', 'capacity', 'pods'}
    for item in value['nodes']:
        if not isinstance(item, dict) or set(item) != fields:
            raise ValueError('invalid node')
        if any((not isinstance(item[k], str) for k in ('name', 'zone', 'status'))):
            raise ValueError('invalid node')
        if any((type(item[k]) is not int for k in ('last_seen', 'capacity', 'pods'))):
            raise ValueError('invalid node')
        if item['capacity'] < 0 or item['pods'] < 0 or item['name'] in seen:
            raise ValueError('invalid node')
        seen.add(item['name'])
    return value

def serialize_state(state: dict) -> bytes:
    _validate(state)
    return json.dumps(state, ensure_ascii=False, sort_keys=True, separators=(',', ':')).encode('utf-8')

def deserialize_state(blob: bytes) -> dict:
    if not isinstance(blob, bytes):
        raise ValueError('invalid blob')
    try:
        value = json.loads(blob.decode('utf-8'))
        return _validate(value)
    except (ValueError, TypeError, UnicodeError, json.JSONDecodeError):
        raise ValueError('invalid blob')

def health_report(blob: bytes, now: int, window: int) -> dict:
    if type(now) is not int or type(window) is not int or window < 0:
        raise ValueError('invalid time')
    nodes = deserialize_state(blob)['nodes']
    reports = []
    zones = {}
    for item in nodes:
