        reports.append({'name': item['name'], 'zone': item['zone'], 'healthy': healthy, 'last_seen': item['last_seen'], 'capacity': item['capacity'], 'pods': item['pods']})
        z = zones.setdefault(item['zone'], {'zone': item['zone'], 'total': 0, 'healthy': 0, 'capacity': 0, 'pods': 0})
        z['total'] += 1
        if healthy:
            z['healthy'] += 1
            z['capacity'] += item['capacity']
            z['pods'] += item['pods']
    reports.sort(key=lambda x: (not x['healthy'], -x['last_seen'], x['name']))
    zone_list = sorted(zones.values(), key=lambda x: (-x['healthy'], x['zone']))
