import csv
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from html import escape
HEADER = ['carrier', 'origin', 'destination', 'container_type', 'base', 'surcharge', 'transit_days', 'note']

def parse_rates(text: str) -> list[dict]:
    if not text.strip():
        return []
    try:
        rows = list(csv.reader(text.splitlines()))
    except csv.Error as exc:
        raise ValueError('malformed CSV') from exc
    if not rows or rows[0] != HEADER:
        raise ValueError('invalid header')
    result = []
    for fields in rows[1:]:
        if not fields or all((not x.strip() for x in fields)):
            continue
        if len(fields) != len(HEADER):
            raise ValueError('invalid row')
        values = [x.strip() for x in fields]
        if any((not values[i] for i in (0, 1, 2, 3, 7))):
            raise ValueError('empty field')
        try:
            base = Decimal(values[4])
            surcharge = Decimal(values[5])
            days = int(values[6])
        except (InvalidOperation, ValueError):
            raise ValueError('invalid number')
        if base < 0 or surcharge < 0 or days <= 0:
            raise ValueError('invalid value')
        result.append(dict(zip(HEADER, [values[0], values[1], values[2], values[3], base, surcharge, days, values[7]])))
    return result

def select_quotes(rates: list[dict], origin: str, destination: str, container_type: str='40HC') -> list[dict]:
    result = []
    for rate in rates:
        if (rate['origin'], rate['destination'], rate['container_type']) != (origin, destination, container_type):
            continue
        total = rate['base'] + rate['surcharge']
        cents = int(total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) * 100)
        item = {k: rate[k] for k in ('carrier', 'origin', 'destination', 'container_type', 'note', 'transit_days')}
        item.update(total=total, total_cents=cents)
        result.append(item)
    return sorted(result, key=lambda x: (x['total_cents'], x['transit_days'], x['carrier'], x['note']))

def render_quote_page(title: str, quotes: list[dict]) -> str:
    lines = ['<h1>' + escape(title) + '</h1>', '<table>', '<thead><tr><th>Carrier</th><th>Route</th><th>Container</th><th>Transit days</th><th>Total</th><th>Note</th></tr></thead>', '<tbody>']
    for q in quotes:
        dollars = q['total_cents'] // 100
        amount = f"${dollars:,}.{q['total_cents'] % 100:02d}"
        vals = [q['carrier'], q['origin'] + ' → ' + q['destination'], q['container_type'], str(q['transit_days']), amount, q['note']]
        lines.append('<tr>' + ''.join(('<td>' + escape(v) + '</td>' for v in vals)) + '</tr>')
    lines += ['</tbody>', '</table>']
    return '\n'.join(lines)

