import json

def encode_projects(projects: list[dict]) -> bytes:
    return json.dumps(projects, separators=(',', ':')).encode('utf-8')

def load_project_page(blob: bytes, status: str | None=None, page: int=1, page_size: int=10) -> dict:
    if not isinstance(blob, (bytes, bytearray)) or not isinstance(page, int) or isinstance(page, bool) or (page < 1) or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (page_size < 1) or (status is not None and (not isinstance(status, str))):
        raise ValueError('invalid arguments')
    try:
        data = json.loads(bytes(blob).decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(data, list):
        raise ValueError('invalid records')
    fields = {'id', 'site', 'status', 'acres', 'budget', 'completed_pct'}
    for record in data:
        if not isinstance(record, dict) or set(record) != fields:
            raise ValueError('invalid record')
        if not all((isinstance(record[k], str) for k in ('id', 'site', 'status'))):
            raise ValueError('invalid record')
        if not all((isinstance(record[k], (int, float)) and (not isinstance(record[k], bool)) for k in ('acres', 'budget', 'completed_pct'))):
            raise ValueError('invalid record')
    selected = [r for r in data if status is None or r['status'] == status]
    selected.sort(key=lambda r: (r['site'], r['id']))
    start = (page - 1) * page_size
    total = len(selected)
    return {'projects': selected[start:start + page_size], 'total_count': total, 'total_acres': round(sum((r['acres'] for r in selected)), 2), 'total_budget': round(sum((r['budget'] for r in selected)), 2), 'average_completion': round(sum((r['completed_pct'] for r in selected)) / total, 2) if total else 0.0}

