import requests

def fetch_run_events(base_url: str, run_id: int, token: str) -> list[dict]:
    url = f"{base_url.rstrip('/')}/runs/{run_id}/events"
    response = requests.get(url, params={'limit': 10000}, headers={'Authorization': f'Bearer {token}', 'Accept': 'application/json'}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError(f'request failed with status {response.status_code}')
    try:
        payload = response.json()
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(payload, dict) or not isinstance(payload.get('events'), list):
        raise ValueError('invalid payload')
    for event in payload['events']:
        if not isinstance(event, dict) or not isinstance(event.get('timestamp'), (int, float)) or isinstance(event.get('timestamp'), bool) or (not isinstance(event.get('hits'), list)):
            raise ValueError('invalid event')
        for hit in event['hits']:
            if not isinstance(hit, dict) or not isinstance(hit.get('detector'), str) or (not isinstance(hit.get('time'), (int, float))) or isinstance(hit.get('time'), bool) or (not isinstance(hit.get('energy'), (int, float))) or isinstance(hit.get('energy'), bool):
                raise ValueError('invalid hit')
    return payload['events']

def aggregate_hits(events: list[dict], window_ns: float=10.0) -> list[dict]:
    if window_ns <= 0:
        raise ValueError('window_ns must be positive')
    groups = {}
    for event in events:
        for hit in event['hits']:
            start = math.floor(hit['time'] / window_ns) * window_ns
            key = (start, hit['detector'])
            if key not in groups:
                groups[key] = [0, 0.0]
            groups[key][0] += 1
            groups[key][1] += hit['energy']
    return [{'window_start': start, 'detector': detector, 'count': groups[start, detector][0], 'total_energy': round(groups[start, detector][1], 6)} for start, detector in sorted(groups)]

def render_report(rows: list[dict]) -> str:
    lines = ['window_start,detector,count,total_energy']
    lines.extend((f"{row['window_start']:.6f},{row['detector']},{row['count']},{row['total_energy']:.6f}" for row in rows))
    return '\n'.join(lines)

