from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from datetime import date
from html import escape

def parse_donation_feed(text: str) -> list[dict]:
    result = []
    for number, original in enumerate(text.splitlines(), 1):
        line = original.strip()
        if not line:
            continue
        fields, current, escaped = ([], [], False)
        for char in line:
            if escaped:
                current.append(char)
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '|':
                fields.append(''.join(current).strip())
                current = []
            else:
                current.append(char)
        if escaped:
            raise ValueError(f'invalid line {number}')
        fields.append(''.join(current).strip())
        if len(fields) != 4 or not fields[0] or (not fields[1]):
            raise ValueError(f'invalid line {number}')
        try:
            amount = Decimal(fields[2])
            if amount < 0 or amount.as_tuple().exponent < -2:
                raise ValueError
            parsed_date = date.fromisoformat(fields[3])
        except (InvalidOperation, ValueError):
            raise ValueError(f'invalid line {number}')
        result.append({'donor': fields[0], 'campaign': fields[1], 'amount': amount, 'date': parsed_date})
    return result

def summarize_donations(records: list[dict], start: str | None=None, end: str | None=None) -> list[dict]:
    try:
        first = date.fromisoformat(start) if start is not None else None
        last = date.fromisoformat(end) if end is not None else None
    except ValueError:
        raise ValueError('invalid date range')
    if first is not None and last is not None and (first > last):
        raise ValueError('invalid date range')
    grouped = {}
    for record in records:
        if first is not None and record['date'] < first:
            continue
        if last is not None and record['date'] > last:
            continue
        key = (record['donor'], record['campaign'])
        if key not in grouped:
            grouped[key] = {'donor': key[0], 'campaign': key[1], 'total': Decimal('0'), 'count': 0}
        grouped[key]['total'] += record['amount']
        grouped[key]['count'] += 1
    rows = list(grouped.values())
    for row in rows:
        row['total'] = row['total'].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    rows.sort(key=lambda r: (-r['total'], r['donor'].casefold(), r['campaign'].casefold(), r['donor'], r['campaign']))
    return rows

def render_donation_report(rows: list[dict], heading: str) -> str:
    body = ''.join((f"<tr><td>{escape(str(row['donor']))}</td><td>{escape(str(row['campaign']))}</td><td>{row['total'].quantize(Decimal('0.01')):.2f}</td><td>{row['count']}</td></tr>" for row in rows))
    return f'<section><h1>{escape(heading)}</h1><table><thead><tr><th>Donor</th><th>Campaign</th><th>Total</th><th>Count</th></tr></thead><tbody>{body}</tbody></table></section>'

