import pytest


def test_fetch_uses_expected_request_and_returns_records():
    response = Mock()
    response.status_code = 200
    response.json.return_value = {"records": [{"animal_id": "lion-1", "date": "2024-01-02"}]}
    with patch("solution.requests.get", return_value=response) as get:
        result = fetch_care_records("lion-1", "2024-01-01", "2024-01-31")
    assert result == [{"animal_id": "lion-1", "date": "2024-01-02"}]
    args, kwargs = get.call_args
    assert args == ("https://zoo.example/api/care",)
    assert kwargs["params"] == {"animal_id": "lion-1", "start_date": "2024-01-01", "end_date": "2024-01-31"}
    assert kwargs["headers"]["Accept"] == "application/json"
    assert kwargs["timeout"] == 10


def test_fetch_rejects_http_errors():
    response = Mock()
