import datetime
import html

def _read(records, week_start):
    try:
        monday = datetime.date.fromisoformat(week_start)
    except (TypeError, ValueError):
        raise ValueError('invalid week')
    if monday.weekday() != 0:
        raise ValueError('week must start Monday')
    grouped = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        try:
            employee, date_text, start, end, role = (record[x] for x in ('employee', 'date', 'start', 'end', 'role'))
        except (KeyError, TypeError):
            raise ValueError('missing field')
        if any((not isinstance(x, str) or not x for x in (employee, date_text, start, end, role))):
            raise ValueError('invalid field')
        try:
            day = datetime.date.fromisoformat(date_text)
            a = datetime.datetime.strptime(start, '%H:%M')
            b = datetime.datetime.strptime(end, '%H:%M')
        except ValueError:
            raise ValueError('invalid date or time')
        if a.strftime('%H:%M') != start or b.strftime('%H:%M') != end or (not monday <= day <= monday + datetime.timedelta(days=6)) or (b <= a):
            raise ValueError('invalid shift')
        grouped.setdefault(employee, {}).setdefault(day, []).append({'start': start, 'end': end, 'role': role})
    result = []
    for employee in sorted(grouped, key=lambda x: (x.casefold(), x)):
        days = []
        for day in sorted(grouped[employee]):
            shifts = sorted(grouped[employee][day], key=lambda x: (x['start'], x['end'], x['role']))
            minutes = sum(((datetime.datetime.strptime(x['end'], '%H:%M') - datetime.datetime.strptime(x['start'], '%H:%M')).seconds // 60 for x in shifts))
            days.append({'date': day.isoformat(), 'minutes': minutes, 'shifts': shifts})
        result.append({'employee': employee, 'days': days, 'total_minutes': sum((x['minutes'] for x in days))})
    return result

def summarize_schedule(records: list[dict], week_start: str) -> list[dict]:
    return _read(records, week_start)

def render_schedule(records: list[dict], week_start: str) -> str:
    data = _read(records, week_start)
    rows = []
    total = 0
    for employee in data:
        for day in employee['days']:
            shifts = '<br>'.join((html.escape(x['start'] + '-' + x['end'] + ' (' + x['role'] + ')', quote=True) for x in day['shifts']))
            rows.append('<tr><td>' + html.escape(employee['employee'], quote=True) + '</td><td>' + html.escape(day['date'], quote=True) + '</td><td>' + shifts + '</td><td>' + str(day['minutes']) + '</td></tr>')
            total += day['minutes']
    return '<table><thead><tr><th>Employee</th><th>Date</th><th>Shifts</th><th>Minutes</th></tr></thead><tbody>' + ''.join(rows) + '</tbody><tfoot><tr><th colspan="3">Total minutes</th><th>' + str(total) + '</th></tr></tfoot></table>'

