import csv
import io
import html

def parse_catalog(text: str) -> list[dict[str, str]]:
    reader = csv.reader(io.StringIO(text, newline=''))
    try:
        header = next(reader)
    except StopIteration:
        raise ValueError('missing header')
    if header != ['key', 'source', 'target', 'status']:
        raise ValueError('invalid header')
    result = []
    seen = set()
    for row in reader:
        if not row or all((x == '' for x in row)):
            continue
        if len(row) != 4:
            raise ValueError('invalid row')
        key, source, target, status = row
        if not key or key in seen or status not in {'draft', 'review', 'approved'}:
            raise ValueError('invalid entry')
        seen.add(key)
        result.append({'key': key, 'source': source, 'target': target, 'status': status})
    return result

def summarize_catalog(entries: list[dict[str, str]]) -> dict[str, int | float]:
    counts = {name: 0 for name in ('draft', 'review', 'approved')}
    for entry in entries:
        counts[entry['status']] += 1
    total = len(entries)
    completion = round(counts['approved'] * 100 / total, 2) if total else 0.0
    return {'total': total, **counts, 'completion': completion}

def render_report(entries: list[dict[str, str]], title: str, locale: str) -> str:
    summary = summarize_catalog(entries)
    percent = summary['completion']
    percent_text = str(int(percent)) if float(percent).is_integer() else str(percent)
    esc = lambda value: html.escape(str(value), quote=True)
    rows = []
    rank = {'approved': 0, 'review': 1, 'draft': 2}
    for entry in sorted(entries, key=lambda item: (rank[item['status']], item['key'])):
        rows.append('<tr><td>' + esc(entry['key']) + '</td><td>' + esc(entry['source']) + '</td><td>' + esc(entry['target']) + '</td><td class="' + esc(entry['status']) + '">' + esc(entry['status']) + '</td></tr>')
    return '<section class="translation-report"><h1>' + esc(title) + ' <span class="locale">(' + esc(locale) + ')</span></h1><p class="summary">' + str(summary['total']) + ' entries · ' + percent_text + '% complete</p><table><thead><tr><th>Key</th><th>Source</th><th>Translation</th><th>Status</th></tr></thead><tbody>' + ''.join(rows) + '</tbody></table></section>'

