import csv
from datetime import datetime
from html import escape
from io import StringIO

def parse_cdr(text: str) -> list[dict]:
    rows = list(csv.reader(StringIO(text)))
    if not rows or rows[0] != ['timestamp', 'caller', 'callee', 'seconds', 'status']:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if not row or all((not value for value in row)):
            continue
        if len(row) != 5:
            raise ValueError('invalid row')
        try:
            timestamp = datetime.fromisoformat(row[0])
            seconds = int(row[3])
        except (TypeError, ValueError):
            raise ValueError('invalid value')
        if seconds < 0 or row[4] not in {'completed', 'failed', 'missed'}:
            raise ValueError('invalid value')
        result.append({'timestamp': timestamp, 'caller': row[1], 'callee': row[2], 'seconds': seconds, 'status': row[4]})
    return result

def aggregate_calls(records: list[dict]) -> list[dict]:
    groups = {}
    for record in records:
        if record['status'] != 'completed':
            continue
        caller = record['caller']
        if caller not in groups:
            groups[caller] = {'caller': caller, 'calls': 0, 'seconds': 0, 'last_call': record['timestamp']}
        group = groups[caller]
        group['calls'] += 1
        group['seconds'] += record['seconds']
        if record['timestamp'] > group['last_call']:
            group['last_call'] = record['timestamp']
    return sorted(groups.values(), key=lambda x: (-x['seconds'], -x['calls'], x['caller']))

def render_report(records: list[dict], title: str) -> str:
    groups = aggregate_calls(records)
    calls = sum((group['calls'] for group in groups))
    seconds = sum((group['seconds'] for group in groups))
    rows = ''.join((f"<tr><td>{escape(group['caller'])}</td><td>{group['calls']}</td><td>{group['seconds']}</td><td>{group['last_call'].isoformat()}</td></tr>" for group in groups))
    return f'<div class="report"><h1>{escape(title)}</h1><p>Calls: {calls} | Seconds: {seconds}</p><table><thead><tr><th>Caller</th><th>Calls</th><th>Seconds</th><th>Last call</th></tr></thead><tbody>{rows}</tbody></table></div>'

