def parse_rate_limit(spec: str) -> tuple[int, int]:
    match = re.fullmatch('([1-9][0-9]*)/([1-9][0-9]*)([sm])', spec)
    if match is None:
        raise ValueError('invalid rate limit')
    amount, duration, unit = match.groups()
    seconds = int(duration) * (60 if unit == 'm' else 1)
    return (int(amount), seconds)

def summarize_requests(events: list[dict], limits: dict[str, str], now: int, window: int) -> list[dict]:
    if not isinstance(window, int) or isinstance(window, bool) or window <= 0:
        raise ValueError('invalid window')
    parsed = {gateway: parse_rate_limit(spec) for gateway, spec in limits.items()}
    totals = {gateway: 0 for gateway in limits}
    for event in events:
        if set(event) != {'gateway', 'timestamp', 'requests'}:
            raise ValueError('invalid event')
        gateway = event['gateway']
        timestamp = event['timestamp']
        count = event['requests']
        if gateway not in limits:
            raise KeyError(gateway)
        if not isinstance(gateway, str) or not isinstance(timestamp, int) or isinstance(timestamp, bool) or (not isinstance(count, int)) or isinstance(count, bool) or (count < 0):
            raise ValueError('invalid event')
        if now - window < timestamp <= now:
            totals[gateway] += count
    rows = []
    for gateway, (limit, seconds) in parsed.items():
        count = totals[gateway]
        rows.append({'gateway': gateway, 'requests': count, 'limit': limit, 'window_seconds': seconds, 'status': 'OVER' if count > limit else 'OK'})
    rows.sort(key=lambda row: (-row['requests'], row['gateway']))
    return rows

