def _date(value):
    try:
        return date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def parse_remittance(text: str) -> list[dict]:
    result = []
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields, current, escaped = ([], [], False)
        for char in raw:
            if escaped:
                current.append(char)
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '|':
                fields.append(''.join(current).strip())
                current = []
            else:
                current.append(char)
        if escaped:
            raise ValueError('dangling escape')
        fields.append(''.join(current).strip())
        if len(fields) != 3 or not fields[0]:
            raise ValueError('malformed line')
        try:
            amount = int(fields[1])
        except ValueError:
            raise ValueError('invalid amount')
        if amount < 0:
            raise ValueError('invalid amount')
        _date(fields[2])
        result.append({'invoice': fields[0], 'amount': amount, 'date': fields[2]})
    return result

def summarize_invoices(invoices: list[dict], payments: list[dict], as_of: str) -> list[dict]:
    cutoff = _date(as_of)
    by_id, totals = ({}, {})
    for item in invoices:
        if item['id'] in by_id or item['total'] < 0:
            raise ValueError('invalid invoice')
        _date(item['due'])
        by_id[item['id']] = item
        totals[item['id']] = 0
    for payment in payments:
        if payment['invoice'] not in by_id or payment['amount'] < 0:
            raise ValueError('invalid payment')
        if _date(payment['date']) <= cutoff:
            totals[payment['invoice']] += payment['amount']
    rows = []
