        rows.append({'id': item['id'], 'vendor': item['vendor'], 'currency': item['currency'], 'total': item['total'], 'paid': paid, 'remaining': remaining, 'due': item['due'], 'status': status})
    priority = {'overdue': 0, 'open': 1, 'paid': 2}
    return sorted(rows, key=lambda x: (priority[x['status']], x['due'], x['id']))

