    except (AttributeError, UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid state blob')
    if not isinstance(state, dict) or set(state) != {'markers'}:
        raise ValueError('invalid state')
    markers = state['markers']
    if not isinstance(markers, list) or not markers or any((not isinstance(x, str) or not x for x in markers)):
        raise ValueError('invalid markers')
    result = []
