import json

def pack_class_state(state: dict) -> bytes:
    if not isinstance(state, dict):
        raise ValueError('state must be a dictionary')
    try:
        return json.dumps(state, ensure_ascii=False, separators=(',', ':'), allow_nan=False).encode('utf-8')
    except (TypeError, ValueError, UnicodeError) as exc:
        raise ValueError('invalid state') from exc

def unpack_class_state(blob: bytes) -> dict:
    if not isinstance(blob, bytes):
        raise ValueError('blob must be bytes')
    try:
        value = json.loads(blob.decode('utf-8'))
    except (UnicodeError, ValueError, TypeError) as exc:
        raise ValueError('invalid blob') from exc
    if not isinstance(value, dict):
        raise ValueError('state must be a dictionary')
    return value

def allocate_applications(applications: list[dict], capacities: dict[str, int]) -> dict[str, list[str]]:
    if not isinstance(applications, list) or not isinstance(capacities, dict):
        raise ValueError('invalid input')
    for name, capacity in capacities.items():
        if not isinstance(name, str) or not isinstance(capacity, int) or isinstance(capacity, bool) or (capacity < 0):
            raise ValueError('invalid capacity')
    seen = set()
    checked = []
    required = {'id', 'priority', 'submitted', 'preferences'}
    for item in applications:
        if not isinstance(item, dict) or set(item) != required:
            raise ValueError('invalid application')
        ident = item['id']
        if not isinstance(ident, str) or not ident or ident in seen:
            raise ValueError('invalid id')
        if not isinstance(item['priority'], int) or isinstance(item['priority'], bool):
            raise ValueError('invalid priority')
        if not isinstance(item['submitted'], int) or isinstance(item['submitted'], bool):
            raise ValueError('invalid submission time')
        prefs = item['preferences']
        if not isinstance(prefs, list) or not prefs or any((not isinstance(x, str) for x in prefs)):
            raise ValueError('invalid preferences')
        seen.add(ident)
        checked.append(item)
    result = {name: [] for name in capacities}
    result['waitlist'] = []
    remaining = dict(capacities)
    ordered = sorted(checked, key=lambda x: (-x['priority'], x['submitted'], x['id']))
    for item in ordered:
        for name in item['preferences']:
            if name in remaining and remaining[name] > 0:
                result[name].append(item['id'])
                remaining[name] -= 1
                break
        else:
            result['waitlist'].append(item['id'])
    return result

