def summarize_routes(payload: bytes, max_distance_km: float | None=None, page: int=1, page_size: int=10) -> list[dict]:
    if not isinstance(payload, bytes):
        raise ValueError('invalid payload')
    if max_distance_km is not None and (isinstance(max_distance_km, bool) or not isinstance(max_distance_km, (int, float)) or (not math.isfinite(max_distance_km)) or (max_distance_km < 0)):
        raise ValueError('invalid distance')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1 or isinstance(page_size, bool) or (not isinstance(page_size, int)) or (page_size < 1):
        raise ValueError('invalid pagination')
    try:
        data = json.loads(payload.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(data, list):
        raise ValueError('invalid routes')
    seen = set()
    groups = {}
    for route in data:
        if not isinstance(route, dict) or set(route) != {'route_id', 'school', 'students', 'distance_km'}:
            raise ValueError('invalid route')
        rid, school, students, distance = route.values()
        if not isinstance(rid, str) or not rid or (not isinstance(school, str)) or (not school):
            raise ValueError('invalid route')
        if rid in seen or isinstance(students, bool) or (not isinstance(students, int)) or (students < 0):
            raise ValueError('invalid route')
        if isinstance(distance, bool) or not isinstance(distance, (int, float)) or (not math.isfinite(distance)) or (distance < 0):
            raise ValueError('invalid route')
        seen.add(rid)
        if max_distance_km is not None and distance > max_distance_km:
            continue
        group = groups.setdefault(school, [0, 0, 0.0, []])
        group[0] += 1
        group[1] += students
        group[2] += distance
        group[3].append(rid)
    result = [{'school': school, 'route_count': g[0], 'total_students': g[1], 'total_distance_km': round(g[2], 2), 'route_ids': sorted(g[3])} for school, g in groups.items()]
    result.sort(key=lambda item: (-item['total_students'], item['school']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

