            raise ValueError('invalid grades')
        checked = []
        for grade in grades:
            if isinstance(grade, bool) or not isinstance(grade, (int, float)):
                raise ValueError('invalid grade')
            if not math.isfinite(grade) or not 0 <= grade <= 100:
                raise ValueError('invalid grade')
            checked.append(grade)
        result[name] = checked
    return result

