import re
import requests
from typing import Any

def load_route_stops(base_url: str, depot_id: str, service_date: str, api_key: str) -> list[dict[str, Any]]:
    response = requests.get(base_url.rstrip('/') + '/routes', params={'depot_id': depot_id, 'date': service_date}, headers={'Authorization': 'Bearer ' + api_key})
    if response.status_code != 200:
        raise RuntimeError(f'route request failed with status {response.status_code}')
    try:
        data = response.json()
    except Exception as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(data, dict) or not isinstance(data.get('routes'), list):
        raise ValueError('invalid route data')
    result = []
    sequence = 1
    for route in data['routes']:
        if not isinstance(route, dict) or not isinstance(route.get('driver_id'), str) or (not isinstance(route.get('stops'), list)):
            raise ValueError('invalid route')
        for stop in route['stops']:
            if not isinstance(stop, dict) or any((not isinstance(stop.get(k), str) for k in ('stop_id', 'eta', 'status'))):
                raise ValueError('invalid stop')
            if not re.fullmatch('\\d{2}:\\d{2}', stop['eta']):
                raise ValueError('invalid time')
            hour, minute = map(int, stop['eta'].split(':'))
            if hour > 23 or minute > 59 or stop['status'] not in {'pending', 'delivered', 'failed'}:
                raise ValueError('invalid stop value')
            result.append({'driver_id': route['driver_id'], 'stop_id': stop['stop_id'], 'eta': stop['eta'], 'status': stop['status'], 'minutes_from_midnight': hour * 60 + minute, 'sequence': sequence})
            sequence += 1
    return result

def compute_driver_windows(stops: list[dict[str, Any]], window_minutes: int=30) -> dict[str, dict[str, int]]:
    if isinstance(window_minutes, bool) or not isinstance(window_minutes, int) or window_minutes <= 0:
        raise ValueError('invalid window')
    groups = {}
    for stop in stops:
        if not isinstance(stop, dict) or not isinstance(stop.get('driver_id'), str) or stop.get('status') not in {'pending', 'delivered', 'failed'} or (not isinstance(stop.get('minutes_from_midnight'), int)) or isinstance(stop.get('minutes_from_midnight'), bool) or (not 0 <= stop['minutes_from_midnight'] < 1440):
            raise ValueError('invalid stop')
        groups.setdefault(stop['driver_id'], []).append(stop)
    output = {}
    for driver in sorted(groups):
        items = groups[driver]
        buckets = {}
        for item in items:
            bucket = item['minutes_from_midnight'] // window_minutes
            buckets[bucket] = buckets.get(bucket, 0) + 1
        times = [x['minutes_from_midnight'] for x in items]
        output[driver] = {'stops': len(items), 'completed': sum((x['status'] == 'delivered' for x in items)), 'span_minutes': max(times) - min(times) if len(times) > 1 else 0, 'peak_window': max(buckets.values())}
    return output

def format_dispatch_report(summary: dict[str, dict[str, int]]) -> str:
    lines = []
    total_stops = total_completed = 0
    required = {'stops', 'completed', 'span_minutes', 'peak_window'}
    for driver in sorted(summary):
        value = summary[driver]
        if set(value) != required or any((isinstance(value[k], bool) or not isinstance(value[k], int) or value[k] < 0 for k in required)) or value['completed'] > value['stops']:
            raise ValueError('invalid summary')
        lines.append(f"{driver}: stops={value['stops']} completed={value['completed']} span={value['span_minutes']}m peak={value['peak_window']}")
        total_stops += value['stops']
        total_completed += value['completed']
    if not lines:
        return ''
    lines.append(f'TOTAL: drivers={len(lines)} stops={total_stops} completed={total_completed}')
    return '\n'.join(lines)

