    mult = {'A': 1.0, 'B': 0.8, 'C': 0.6, 'D': 0.4}
    out = []
    for imei, device in state.get('devices', {}).items():
        latest = max(enumerate(device['scans']), key=lambda x: (x[1]['timestamp'], x[0]))[1]
        model = device['model']
        quote = int(base.get(model, 300) * mult[latest['grade']] * (0.5 + latest['battery'] / 200))
        out.append({'imei': imei, 'model': model, 'grade': latest['grade'], 'battery': latest['battery'], 'quote': quote})
    return sorted(out, key=lambda x: (-x['quote'], x['imei']))

