from solution import encode_claims, summarize_claims
import pytest


def test_empty_collection():
    payload = encode_claims([])
    assert summarize_claims(payload) == {
        "total_claims": 0,
        "approved_total": 0.0,
        "by_status": {"pending": 0, "approved": 0, "denied": 0},
        "claims": [],
    }


def test_summary_counts_total_and_rounding():
    claims = [
        {"id": "c1", "claimant": "A", "amount": 10.105, "status": "approved"},
        {"id": "c2", "claimant": "B", "amount": 2.1, "status": "pending"},
        {"id": "c3", "claimant": "C", "amount": 1.005, "status": "approved"},
        {"id": "c4", "claimant": "D", "amount": 7, "status": "denied"},
    ]
    result = summarize_claims(encode_claims(claims))
    assert result["total_claims"] == 4
    assert result["approved_total"] == 11.11
    assert result["by_status"] == {"pending": 1, "approved": 2, "denied": 1}


def test_approved_sorting_and_tie_breaker():
    claims = [
        {"id": "z9", "claimant": "Z", "amount": 20, "status": "approved"},
        {"id": "a2", "claimant": "A", "amount": 30, "status": "approved"},
        {"id": "a1", "claimant": "A", "amount": 30, "status": "approved"},
        {"id": "p1", "claimant": "P", "amount": 99, "status": "pending"},
    ]
    result = summarize_claims(encode_claims(claims))
    assert result["claims"] == [
        {"id": "a1", "claimant": "A", "amount": 30, "status": "approved"},
        {"id": "a2", "claimant": "A", "amount": 30, "status": "approved"},
        {"id": "z9", "claimant": "Z", "amount": 20, "status": "approved"},
    ]


def test_pagination_boundaries():
    claims = [
        {"id": f"c{i}", "claimant": "X", "amount": i, "status": "approved"}
        for i in range(1, 6)
    ]
    payload = encode_claims(claims)
    assert [x["id"] for x in summarize_claims(payload, 1, 2)["claims"]] == ["c5", "c4"]
    assert [x["id"] for x in summarize_claims(payload, 3, 2)["claims"]] == ["c1"]
    assert summarize_claims(payload, 4, 2)["claims"] == []


def test_invalid_page_arguments():
    payload = encode_claims([])
    for page, size in [(0, 1), (1, 0), (-1, 2), (True, 2), (1, False), (1.5, 2)]:
        with pytest.raises(ValueError):
            summarize_claims(payload, page, size)


