    bad_cases = [
        [{"id": "x", "claimant": "A", "amount": -1, "status": "pending"}],
        [{"id": "x", "claimant": "A", "amount": 1, "status": "other"}],
        [{"id": "x", "claimant": "", "amount": 1, "status": "pending"}],
        [{"id": "x", "claimant": "A", "amount": True, "status": "pending"}],
        [{"id": "x", "claimant": "A", "amount": 1, "status": "pending", "extra": 3}],
    ]
    for claims in bad_cases:
        with pytest.raises(ValueError):
            encode_claims(claims)


def test_malformed_payload_is_rejected():
    with pytest.raises(ValueError):
        summarize_claims(b"not a claims payload")

