def parse_results(text: str) -> list[dict]:
    if not text.strip():
        raise ValueError('empty input')
    rows = list(csv.reader(io.StringIO(text), skipinitialspace=False))
    rows = [r for r in rows if any((x.strip() for x in r))]
    header = [x.strip() for x in rows[0]] if rows else []
    expected = ['date', 'home', 'away', 'home_goals', 'away_goals']
    if header != expected:
        raise ValueError('bad header')
    output = []
    for row in rows[1:]:
        if len(row) != 5:
            raise ValueError('bad row')
        d, home, away, hg, ag = [x.strip() for x in row]
        try:
            date.fromisoformat(d)
            home_goals = int(hg)
            away_goals = int(ag)
        except (ValueError, TypeError):
            raise ValueError('bad value')
        if not home or not away or home == away or (home_goals < 0) or (away_goals < 0):
            raise ValueError('bad match')
        output.append({'date': d, 'home': home, 'away': away, 'home_goals': home_goals, 'away_goals': away_goals})
    return output

def compute_table(results: list[dict]) -> list[dict]:
    required = {'date', 'home', 'away', 'home_goals', 'away_goals'}
    stats = {}
    for result in results:
        if not required.issubset(result) or result['home'] == result['away']:
            raise ValueError('bad result')
        hg, ag = (result['home_goals'], result['away_goals'])
        if not isinstance(hg, int) or not isinstance(ag, int) or hg < 0 or (ag < 0):
            raise ValueError('bad goals')
        for team in (result['home'], result['away']):
            stats.setdefault(team, {'team': team, 'played': 0, 'wins': 0, 'draws': 0, 'losses': 0, 'goals_for': 0, 'goals_against': 0, 'goal_difference': 0, 'points': 0})
        home, away = (stats[result['home']], stats[result['away']])
        home['played'] += 1
        away['played'] += 1
        home['goals_for'] += hg
        home['goals_against'] += ag
        away['goals_for'] += ag
        away['goals_against'] += hg
        if hg > ag:
            home['wins'] += 1
            home['points'] += 3
            away['losses'] += 1
        elif hg < ag:
            away['wins'] += 1
            away['points'] += 3
            home['losses'] += 1
        else:
            home['draws'] += 1
            away['draws'] += 1
            home['points'] += 1
            away['points'] += 1
    for row in stats.values():
        row['goal_difference'] = row['goals_for'] - row['goals_against']
    return sorted(stats.values(), key=lambda x: (-x['points'], -x['goal_difference'], -x['goals_for'], x['team']))

def render_schedule(title: str, fixtures: list[dict]) -> str:
    items = []
    for fixture in fixtures:
        if not {'date', 'home', 'away'}.issubset(fixture):
            raise ValueError('missing fixture field')
        d = escape(str(fixture['date']), quote=True)
        h = escape(str(fixture['home']))
        a = escape(str(fixture['away']))
        items.append(f'<li><time datetime="{d}">{d}</time> {h} <span class="versus">vs</span> {a}</li>')
    return f"""<section class="schedule"><h1>{escape(str(title))}</h1><ol>{''.join(items)}</ol></section>"""

