import csv
import datetime
import html
import io
FIELDS = ['id', 'email', 'requested_at', 'reason', 'status']
STATUSES = ['pending', 'approved', 'rejected']

def _date(value):
    try:
        parsed = datetime.date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if parsed.isoformat() != value:
        raise ValueError('invalid date')
    return parsed

def parse_deletion_requests(csv_text: str) -> list[dict[str, str]]:
    if not csv_text.strip():
        raise ValueError('empty document')
    reader = csv.DictReader(io.StringIO(csv_text))
    if reader.fieldnames != FIELDS:
        raise ValueError('incorrect header')
    result = []
    seen = set()
    for row in reader:
        if None in row:
            raise ValueError('malformed row')
        values = {key: row[key].strip() if row[key] is not None else '' for key in FIELDS}
        if not values['id'] or not values['email'] or (not values['reason']):
            raise ValueError('missing value')
        _date(values['requested_at'])
        if values['status'] not in STATUSES or values['id'] in seen:
            raise ValueError('invalid row')
        seen.add(values['id'])
        result.append(values)
    return result

def render_deletion_report(requests: list[dict[str, str]], generated_by: str, as_of: str) -> str:
    end = _date(as_of)
    checked = []
    seen = set()
    counts = {status: 0 for status in STATUSES}
    for request in requests:
        if set(request) != set(FIELDS):
            raise ValueError('invalid row')
        item = {key: request[key] for key in FIELDS}
        if any((not isinstance(value, str) for value in item.values())):
            raise ValueError('invalid row')
        if not item['id'] or not item['email'] or (not item['reason']) or (item['status'] not in STATUSES) or (item['id'] in seen):
            raise ValueError('invalid row')
        requested = _date(item['requested_at'])
        if requested > end:
            raise ValueError('future request')
        seen.add(item['id'])
        counts[item['status']] += 1
        checked.append((STATUSES.index(item['status']), requested, item['id'], item))
    checked.sort(key=lambda value: (value[0], value[1], value[2]))
    esc = lambda value: html.escape(str(value), quote=True)
    lines = ['<section class="deletion-report">', '<h1>Personal data deletion requests</h1>', f'<p class="generated-by">Generated by: {esc(generated_by)}</p>', f"""<p class="summary">Pending: {counts['pending']} | Approved: {counts['approved']} | Rejected: {counts['rejected']}</p>""", '<table>', '<thead><tr><th>ID</th><th>Email</th><th>Requested</th><th>Reason</th><th>Status</th><th>Age (days)</th></tr></thead>', '<tbody>']
    for _, requested, _, item in checked:
        age = (end - requested).days
        lines.append(f'''<tr class="{esc(item['status'])}"><td>{esc(item['id'])}</td><td>{esc(item['email'])}</td><td>{esc(item['requested_at'])}</td><td>{esc(item['reason'])}</td><td>{esc(item['status'])}</td><td>{age}</td></tr>''')
    lines.extend(['</tbody>', '</table>', '</section>'])
    return '\n'.join(lines)

