    for position, item in enumerate(records):
        if not isinstance(item, dict) or any((k not in item for k in ('timestamp', 'x', 'y', 'z'))):
            raise ValueError('invalid reading')
        timestamp = _time(item['timestamp'])
        values = []
        for key in ('x', 'y', 'z'):
            value = item[key]
            if isinstance(value, bool):
                raise ValueError('invalid axis')
            try:
                value = float(value)
            except (TypeError, ValueError):
                raise ValueError('invalid axis')
            if not math.isfinite(value):
                raise ValueError('invalid axis')
            values.append(value)
        result.append((timestamp, position, {'timestamp': timestamp.strftime('%Y-%m-%dT%H:%M:%SZ'), 'x': values[0], 'y': values[1], 'z': values[2]}))
    result.sort(key=lambda x: (x[0], x[1]))
    return [x[2] for x in result]

def fetch_machine_readings(machine_id, start, end):
    response = requests.get('https://factory.example/api/machines/{}/vibration'.format(machine_id), params={'start': start, 'end': end}, headers={'Accept': 'application/json'}, timeout=10)
    if not 200 <= response.status_code < 300:
        raise RuntimeError('HTTP status {}'.format(response.status_code))
    try:
        payload = response.json()
    except Exception as exc:
        raise ValueError('invalid response JSON') from exc
    if not isinstance(payload, dict) or 'readings' not in payload:
        raise ValueError('invalid response shape')
    return parse_readings(payload['readings'])

def aggregate_vibration(readings, window_seconds):
    if isinstance(window_seconds, bool) or not isinstance(window_seconds, int) or window_seconds <= 0:
        raise ValueError('invalid window')
    if not readings:
        return []
    parsed = parse_readings(list(readings))
