import datetime
import html

def parse_iso_date(value: str) -> datetime.date:
    if not isinstance(value, str) or len(value) != 10 or value[4] != '-' or (value[7] != '-'):
        raise ValueError('invalid date')
    try:
        result = datetime.date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')
    if result.isoformat() != value:
        raise ValueError('invalid date')
    return result

def summarize_habits(records: list[dict], start: str, end: str) -> list[dict]:
    first, last = (parse_iso_date(start), parse_iso_date(end))
    if first > last:
        raise ValueError('invalid range')
    groups = {}
    for record in records:
        required = {'habit', 'date', 'minutes', 'completed', 'note'}
        if not isinstance(record, dict) or not required.issubset(record):
            raise ValueError('invalid record')
        if not isinstance(record['habit'], str) or not isinstance(record['note'], str):
            raise ValueError('invalid record')
        day = parse_iso_date(record['date'])
        minutes = record['minutes']
        if isinstance(minutes, bool) or not isinstance(minutes, int) or minutes < 0:
            raise ValueError('invalid record')
        if not isinstance(record['completed'], bool):
            raise ValueError('invalid record')
        if first <= day <= last:
            item = groups.setdefault(record['habit'], {'habit': record['habit'], 'days': 0, 'completed_days': 0, 'minutes': 0, 'notes': []})
            item['days'] += 1
            item['completed_days'] += int(record['completed'])
            item['minutes'] += minutes
            if record['note']:
                item['notes'].append(record['note'])
    return sorted(groups.values(), key=lambda x: (-x['completed_days'], -x['minutes'], x['habit']))

