    rows = []
    for item in summary:
        percent = item['completed_days'] / item['days'] * 100
        notes = ' | '.join(item['notes'])
        rows.append('<tr><td>{}</td><td>{}</td><td>{}</td><td>{}</td><td>{:.1f}%</td><td>{}</td></tr>'.format(html.escape(item['habit'], quote=True), item['days'], item['completed_days'], item['minutes'], percent, html.escape(notes, quote=True)))
    return '<section class="habit-report"><h1>Habit report: {} to {}</h1><table><thead><tr><th>Habit</th><th>Days</th><th>Completed</th><th>Minutes</th><th>Completion</th><th>Notes</th></tr></thead><tbody>{}</tbody></table></section>'.format(start, end, ''.join(rows))

