from datetime import datetime, timezone
import requests

def _time(value):
    if not isinstance(value, str):
        raise ValueError('invalid timestamp')
    try:
        return datetime.fromisoformat(value[:-1] + '+00:00' if value.endswith('Z') else value).astimezone(timezone.utc)
    except (ValueError, TypeError):
        raise ValueError('invalid timestamp')

def fetch_outages(region: str, start: str, end: str, token: str) -> list[dict]:
    response = requests.get('https://api.utility.example/v1/outages', params={'region': region, 'start': start, 'end': end}, headers={'Authorization': 'Bearer ' + token}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError('request failed with status ' + str(response.status_code))
    try:
        data = response.json()
    except Exception as exc:
        raise ValueError('invalid response') from exc
    if not isinstance(data, dict) or not isinstance(data.get('outages'), list):
        raise ValueError('invalid response')
    keys = ('id', 'region', 'status', 'started_at', 'customers', 'eta')
    result = []
    for item in data['outages']:
        if not isinstance(item, dict) or any((k not in item for k in keys)):
            raise ValueError('invalid outage')
        result.append({k: item[k] for k in keys})
    return sorted(result, key=lambda x: (_time(x['started_at']), x['id']))

def summarize_outages(events: list[dict], as_of: str) -> list[dict]:
    cutoff = _time(as_of)
    groups = {}
    required = ('id', 'region', 'status', 'started_at', 'customers', 'eta')
    for event in events:
        if any((k not in event for k in required)):
            raise ValueError('invalid event')
        started = _time(event['started_at'])
        eta = _time(event['eta']) if event['eta'] is not None else None
        if isinstance(event['customers'], bool) or not isinstance(event['customers'], int) or event['customers'] < 0:
            raise ValueError('invalid customers')
        if event['status'] not in ('open', 'investigating') or started > cutoff or (eta is not None and eta <= cutoff):
            continue
        groups.setdefault(event['region'], []).append((event, started, eta))
    result = []
    for region, items in groups.items():
        total = sum((x[0]['customers'] for x in items))
        earliest = min(items, key=lambda x: x[1])
        etas = [x for x in items if x[2] is not None]
        latest = max(etas, key=lambda x: x[2])[0]['eta'] if etas else None
        result.append({'region': region, 'outage_count': len(items), 'customers_affected': total, 'earliest_started_at': earliest[0]['started_at'], 'latest_eta': latest, 'severity': 'critical' if total >= 1000 or len(items) >= 3 else 'warning'})
    return sorted(result, key=lambda x: (0 if x['severity'] == 'critical' else 1, -x['customers_affected'], x['region']))

