import requests

def normalize_alerts(payload: dict, jurisdiction: str) -> list[dict]:
    if not isinstance(payload, dict) or not isinstance(payload.get('alerts'), list):
        raise ValueError('alerts must be a list')
    chosen = {}
    for item in payload['alerts']:
        if not isinstance(item, dict):
            raise ValueError('invalid alert')
        required = ('id', 'mark', 'jurisdiction', 'created', 'score', 'classes')
        if any((key not in item for key in required)):
            raise ValueError('missing field')
        if any((not isinstance(item[key], str) for key in ('id', 'mark', 'jurisdiction', 'created'))):
            raise ValueError('invalid text field')
        if isinstance(item['score'], bool):
            raise ValueError('invalid score')
        try:
            score = float(item['score'])
        except (TypeError, ValueError):
            raise ValueError('invalid score')
        if not isinstance(item['classes'], list):
            raise ValueError('invalid classes')
        classes = []
        for value in item['classes']:
            if isinstance(value, bool):
                raise ValueError('invalid class')
            try:
                number = int(value)
            except (TypeError, ValueError):
                raise ValueError('invalid class')
            if str(number) != str(value).strip() and (not isinstance(value, int)):
                raise ValueError('invalid class')
            classes.append(number)
        if item['jurisdiction'] != jurisdiction:
            continue
        record = dict(item)
        record['score'] = score
        record['classes'] = sorted(set(classes))
        old = chosen.get(record['id'])
        if old is None or (record['score'], record['created']) > (old['score'], old['created']):
            chosen[record['id']] = record
    return sorted(chosen.values(), key=lambda x: (-x['score'], x['mark'], x['id']))

def build_watch_digest(alerts: list[dict]) -> list[dict]:
    groups = {}
    for alert in alerts:
        group = groups.setdefault(alert['mark'], [])
        group.append(alert)
    result = []
    for mark, items in groups.items():
        result.append({'mark': mark, 'alert_count': len(items), 'max_score': max((x['score'] for x in items)), 'jurisdictions': sorted({x['jurisdiction'] for x in items}), 'alert_ids': sorted((x['id'] for x in items))})
    return sorted(result, key=lambda x: (-x['max_score'], -x['alert_count'], x['mark']))

def fetch_watch_digest(query: str, jurisdiction: str, token: str) -> list[dict]:
    response = requests.get('https://watch.example.test/api/v1/alerts', params={'q': query, 'jurisdiction': jurisdiction}, headers={'Authorization': 'Bearer ' + token}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError(str(response.status_code))
    return build_watch_digest(normalize_alerts(response.json(), jurisdiction))

