def render_service_report(records: list[dict], status: str | None=None, page: int=1, page_size: int=10) -> str:
    if not isinstance(records, list) or status not in (None, 'open', 'closed', 'scheduled'):
        raise ValueError('invalid arguments')
    if not isinstance(page, int) or page < 1 or (not isinstance(page_size, int)) or (not 1 <= page_size <= 100):
        raise ValueError('invalid pagination')
