import json

def encode_habitat_survey(survey: dict) -> bytes:
    if not isinstance(survey, dict):
        raise TypeError('survey must be a dictionary')
    try:
        text = json.dumps(survey, ensure_ascii=False, separators=(',', ':'))
    except (TypeError, ValueError, OverflowError) as exc:
        raise TypeError('survey contains unsupported values') from exc
    return text.encode('utf-8')

def decode_habitat_survey(blob: bytes | bytearray | str) -> dict:
    if isinstance(blob, (bytes, bytearray)):
        try:
            text = bytes(blob).decode('utf-8')
        except UnicodeDecodeError as exc:
            raise ValueError('invalid survey data') from exc
    elif isinstance(blob, str):
        text = blob
    else:
        raise ValueError('invalid survey data')
    try:
        result = json.loads(text)
    except (TypeError, ValueError, UnicodeError) as exc:
        raise ValueError('invalid survey data') from exc
    if not isinstance(result, dict):
        raise ValueError('survey must be a dictionary')
    return result

