        return {key: _canonical(value[key]) for key in sorted(value)}
    if isinstance(value, list):
        return [_canonical(item) for item in value]
    return value

def pack_state(state: dict) -> bytes:
    return pickle.dumps(_canonical(state), protocol=4)

def unpack_state(blob: bytes) -> dict:
    try:
        value = pickle.loads(blob)
    except Exception:
        raise ValueError('invalid state')
    if not isinstance(value, dict):
        raise ValueError('invalid state')
    return value

def _day(value):
    if not isinstance(value, str):
        raise ValueError('invalid date')
    try:
        parsed = date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')
    if parsed.isoformat() != value:
        raise ValueError('invalid date')
    return parsed

def calendar_summary(blob: bytes, first_date: str, last_date: str) -> list[dict]:
    start, finish = (_day(first_date), _day(last_date))
    if start > finish:
        raise ValueError('invalid range')
    state = unpack_state(blob)
    excursions = state.get('excursions')
    bookings = state.get('bookings')
    if not isinstance(excursions, list) or not isinstance(bookings, list):
        raise ValueError('invalid state')
    by_id = {}
    for item in excursions:
        if not isinstance(item, dict) or not isinstance(item.get('id'), str) or item['id'] in by_id:
            raise ValueError('invalid excursion')
        if not isinstance(item.get('name'), str) or type(item.get('capacity')) is not int or item['capacity'] < 0:
            raise ValueError('invalid excursion')
        if isinstance(item.get('price'), bool) or not isinstance(item.get('price'), (int, float)) or item['price'] < 0:
            raise ValueError('invalid excursion')
        dates = item.get('dates')
        if not isinstance(dates, list) or len(set(dates)) != len(dates):
            raise ValueError('invalid excursion')
        for value in dates:
            _day(value)
        by_id[item['id']] = item
    totals = {}
    seen = set()
    for item in bookings:
        if not isinstance(item, dict) or not isinstance(item.get('booking_id'), str) or item['booking_id'] in seen:
            raise ValueError('invalid booking')
        seen.add(item['booking_id'])
        eid, day = (item.get('excursion_id'), item.get('date'))
        if eid not in by_id or not isinstance(item.get('guests'), int) or isinstance(item['guests'], bool) or (item['guests'] <= 0) or (item.get('status') not in ('confirmed', 'cancelled')):
            raise ValueError('invalid booking')
        _day(day)
        if day not in by_id[eid]['dates']:
            raise ValueError('invalid booking')
        if item['status'] == 'confirmed':
            totals[eid, day] = totals.get((eid, day), 0) + item['guests']
    rows = []
    for item in excursions:
        for day in item['dates']:
            if start <= _day(day) <= finish:
                booked = totals.get((item['id'], day), 0)
                rows.append({'date': day, 'excursion_id': item['id'], 'name': item['name'], 'booked': booked, 'remaining': item['capacity'] - booked, 'revenue': item['price'] * booked})
    return sorted(rows, key=lambda row: (row['date'], row['excursion_id']))

