def encode_state(state: dict) -> bytes:
    try:
        return json.dumps(state, separators=(',', ':'), ensure_ascii=False).encode('utf-8')
    except (TypeError, ValueError, UnicodeError) as exc:
        raise ValueError('invalid state') from exc

def restore_state(blob: bytes) -> dict:
    try:
        value = json.loads(blob.decode('utf-8'))
    except (Exception,) as exc:
        raise ValueError('invalid state') from exc
    if not isinstance(value, dict) or not {'strata', 'arms', 'block_size', 'counts', 'history'} <= value.keys():
        raise ValueError('invalid state')
    return value

def create_state(strata: list[str], arms: list[str], block_size: int) -> bytes:
    if not strata or not arms or any((not isinstance(x, str) or not x for x in strata + arms)):
        raise ValueError('invalid configuration')
    if len(set(strata)) != len(strata) or len(set(arms)) != len(arms):
        raise ValueError('duplicate configuration')
    if not isinstance(block_size, int) or isinstance(block_size, bool) or block_size <= 0 or block_size % len(arms):
        raise ValueError('invalid block size')
    return encode_state({'strata': strata, 'arms': arms, 'block_size': block_size, 'counts': {s: {a: 0 for a in arms} for s in strata}, 'history': []})

def allocate(participant: dict[str, str], state_blob: bytes) -> tuple[str, bytes]:
    state = restore_state(state_blob)
    if not isinstance(participant, dict) or not isinstance(participant.get('id'), str) or (not participant['id']) or (not isinstance(participant.get('stratum'), str)) or (participant['stratum'] not in state['strata']):
        raise ValueError('invalid participant')
    if any((x.get('id') == participant['id'] for x in state['history'])):
        raise ValueError('duplicate participant')
    stratum = participant['stratum']
    arm = min(state['arms'], key=lambda a: state['counts'][stratum][a])
    state['counts'][stratum][arm] += 1
    state['history'].append({'id': participant['id'], 'stratum': stratum, 'arm': arm})
    return (arm, encode_state(state))

def summarize(assignments: list[dict[str, str]], arms: list[str], strata: list[str]) -> dict[str, dict[str, int]]:
    if not isinstance(assignments, list) or len(set(arms)) != len(arms) or len(set(strata)) != len(strata):
        raise ValueError('invalid input')
    result = {s: {a: 0 for a in arms} for s in strata}
    seen = set()
    for item in assignments:
        if not isinstance(item, dict) or not all((isinstance(item.get(k), str) for k in ('id', 'stratum', 'arm'))) or (not item['id']) or (item['id'] in seen) or (item['stratum'] not in result) or (item['arm'] not in result[item['stratum']]):
            raise ValueError('invalid assignment')
        seen.add(item['id'])
        result[item['stratum']][item['arm']] += 1
    return result

