from datetime import date
import requests

def _date(value):
    try:
        return date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def fetch_booking_inventory(campaign: str, api_key: str, endpoint: str) -> list[dict]:
    response = requests.get(endpoint, params={'campaign': campaign}, headers={'X-API-Key': api_key})
    if response.status_code != 200:
        raise RuntimeError(str(response.status_code))
    try:
        data = response.json()
    except Exception as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(data, dict) or not isinstance(data.get('placements'), list):
        raise ValueError('invalid response')
    result = []
    for item in data['placements']:
        if not isinstance(item, dict) or any((k not in item for k in ('id', 'outlet', 'start', 'end', 'cpm', 'slots'))):
            raise ValueError('invalid placement')
        start, end = (_date(item['start']), _date(item['end']))
        if start > end:
            raise ValueError('invalid range')
        try:
            cpm = float(item['cpm'])
            slots = int(item['slots'])
        except (TypeError, ValueError):
            raise ValueError('invalid numbers')
        if cpm < 0 or slots <= 0 or isinstance(item['slots'], bool) or (slots != item['slots']):
            raise ValueError('invalid numbers')
        result.append({'id': item['id'], 'outlet': item['outlet'], 'start': start.isoformat(), 'end': end.isoformat(), 'cpm': cpm, 'slots': slots})
    return result

def rank_inventory(items: list[dict], minimum_slots: int=1) -> list[dict]:
