import html

def render_billing_report(records: list[dict], page: int=1, per_page: int=10) -> str:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(per_page, bool) or not isinstance(per_page, int) or (not 1 <= per_page <= 100):
        raise ValueError('invalid per_page')
    totals = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        if set(record) != {'creator', 'amount_cents', 'status'}:
            raise ValueError('invalid record')
        creator = record['creator']
        amount = record['amount_cents']
        status = record['status']
        if not isinstance(creator, str) or not creator:
            raise ValueError('invalid creator')
        if isinstance(amount, bool) or not isinstance(amount, int) or amount < 0:
            raise ValueError('invalid amount')
        if status not in ('paid', 'refunded'):
            raise ValueError('invalid status')
        if status == 'paid':
            count, total = totals.get(creator, (0, 0))
            totals[creator] = (count + 1, total + amount)
    ordered = sorted(totals.items(), key=lambda item: (-item[1][1], item[0]))
    pages = max(1, (len(ordered) + per_page - 1) // per_page)
    start = (page - 1) * per_page
    rows = []
    for creator, (count, total) in ordered[start:start + per_page]:
        dollars, cents = divmod(total, 100)
        rows.append(f'<tr><td>{html.escape(creator, quote=True)}</td><td>{count}</td><td>${dollars:,}.{cents:02d}</td></tr>')
