_ACTIONS = {'seal', 'open', 'transfer'}
_KEYS = {'timestamp', 'item', 'officer', 'action', 'location'}

def _validate_case(case_id, entries):
    if not isinstance(case_id, str) or not case_id:
        raise ValueError('invalid case')
    if not isinstance(entries, list):
        raise ValueError('invalid entries')
    for entry in entries:
        if not isinstance(entry, dict) or set(entry) != _KEYS:
            raise ValueError('invalid entry')
        timestamp = entry['timestamp']
        if isinstance(timestamp, bool) or not isinstance(timestamp, int) or timestamp < 0:
            raise ValueError('invalid timestamp')
        for key in ('item', 'officer', 'location'):
            if not isinstance(entry[key], str) or not entry[key]:
                raise ValueError('invalid text')
        if entry['action'] not in _ACTIONS:
            raise ValueError('invalid action')

def pack_case(case_id: str, entries: list[dict]) -> bytes:
    _validate_case(case_id, entries)
    value = {'case_id': case_id, 'entries': [dict(entry) for entry in entries]}
    return json.dumps(value, separators=(',', ':'), ensure_ascii=False).encode('utf-8')

def unpack_case(blob: bytes) -> dict:
    if not isinstance(blob, bytes):
        raise ValueError('invalid blob')
    try:
        value = json.loads(blob.decode('utf-8'))
        if not isinstance(value, dict) or set(value) != {'case_id', 'entries'}:
            raise ValueError('invalid structure')
        _validate_case(value['case_id'], value['entries'])
        return {'case_id': value['case_id'], 'entries': [dict(x) for x in value['entries']]}
    except (ValueError, TypeError, UnicodeError, json.JSONDecodeError):
        raise ValueError('invalid blob')

def summarize_case(blob: bytes) -> dict:
    case = unpack_case(blob)
    grouped = {}
    for entry in case['entries']:
        item = entry['item']
        if item not in grouped:
            grouped[item] = {'item': item, 'events': 0, 'first_timestamp': entry['timestamp'], 'last_timestamp': entry['timestamp'], 'officers': [], 'seen': set()}
        result = grouped[item]
        result['events'] += 1
        result['first_timestamp'] = min(result['first_timestamp'], entry['timestamp'])
        result['last_timestamp'] = max(result['last_timestamp'], entry['timestamp'])
        if entry['officer'] not in result['seen']:
            result['seen'].add(entry['officer'])
            result['officers'].append(entry['officer'])
    items = []
    for item in sorted(grouped):
        result = grouped[item]
        result.pop('seen')
        items.append(result)
    return {'case_id': case['case_id'], 'items': items}

