        end = datetime.date.fromisoformat(end_date)
    except ValueError as exc:
        raise ValueError('invalid date') from exc
    if start > end or min_clicks < 0:
        raise ValueError('invalid arguments')
    url = api_base.rstrip('/') + '/v1/subscribers'
    response = requests.get(url, params={'start_date': start_date, 'end_date': end_date, 'min_clicks': min_clicks}, headers={'Authorization': 'Bearer ' + token}, timeout=10)
