    except Exception as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(payload, dict) or not isinstance(payload.get('subscribers'), list):
        raise ValueError('invalid response')
    selected = []
    for item in payload['subscribers']:
        try:
            date = datetime.date.fromisoformat(item['date'])
            if start <= date <= end and item['status'] == 'active' and (item['clicks'] >= min_clicks):
                selected.append(item)
        except (KeyError, TypeError, ValueError):
            continue
    total_opens = sum((item['opens'] for item in selected))
    total_clicks = sum((item['clicks'] for item in selected))
