        raise ValueError('invalid response')
    groups = {}
    for item in payload['readings']:
        if not isinstance(item, dict):
            continue
        sensor = item.get('sensor_id')
        timestamp = item.get('timestamp')
        moisture = item.get('moisture')
        battery = item.get('battery')
        if not isinstance(sensor, str) or not sensor or (not isinstance(timestamp, str)) or (not timestamp):
            continue
        if isinstance(moisture, bool) or isinstance(battery, bool) or (not isinstance(moisture, (int, float))) or (not isinstance(battery, (int, float))):
