from collections.abc import Mapping

def render_waitlist(entries: list[dict], page: int=1, per_page: int=10) -> str:
    if isinstance(page, bool) or not isinstance(page, int) or isinstance(per_page, bool) or (not isinstance(per_page, int)):
        raise TypeError('page and per_page must be integers')
    if page <= 0 or per_page <= 0:
        raise ValueError('page and per_page must be positive')
    if not isinstance(entries, list):
        raise TypeError('entries must be a list')
    active = []
    for index, entry in enumerate(entries):
        if not isinstance(entry, Mapping):
            raise TypeError('each entry must be a mapping')
        for key in ('name', 'bedrooms', 'points', 'status'):
            if key not in entry:
                raise ValueError('missing required field')
        if not isinstance(entry['name'], str) or not isinstance(entry['status'], str):
            raise TypeError('name and status must be strings')
        if isinstance(entry['bedrooms'], bool) or not isinstance(entry['bedrooms'], int) or isinstance(entry['points'], bool) or (not isinstance(entry['points'], int)):
            raise TypeError('bedrooms and points must be integers')
        if entry['bedrooms'] < 0 or entry['points'] < 0:
            raise ValueError('bedrooms and points must not be negative')
        if entry['status'] == 'active':
            active.append((entry, index))
    active.sort(key=lambda item: (-item[0]['points'], item[0]['name'].casefold(), item[1]))
