from datetime import date, timedelta
import requests

def get_comparables(base_url: str, token: str, latitude: float, longitude: float, radius_miles: float, limit: int=50) -> list[dict]:
    response = requests.get(base_url.rstrip('/') + '/v1/comparables', params={'latitude': latitude, 'longitude': longitude, 'radius_miles': radius_miles, 'limit': limit}, headers={'Authorization': 'Bearer ' + token}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError(f'comparable service returned {response.status_code}')
    payload = response.json()
    if not isinstance(payload, dict) or not isinstance(payload.get('properties'), list):
        raise ValueError('invalid comparable response')
    return payload['properties']

def summarize_comparables(records: list[dict], target_price: float, as_of: str, max_distance: float=10.0) -> dict:
    try:
        end = date.fromisoformat(as_of)
    except (TypeError, ValueError):
        raise ValueError('invalid as_of')
    start = end - timedelta(days=365)
    chosen = {}
    for record in records:
        try:
            sold = date.fromisoformat(record['sold_date'])
            price = record['price']
            distance = record['distance_miles']
            if record['status'] != 'sold' or price <= 0 or sold < start or (sold > end) or (distance > max_distance):
                continue
            item = {'id': record['id'], 'price': price, 'sold_date': record['sold_date'], 'distance_miles': distance}
        except (KeyError, TypeError, ValueError):
            continue
        old = chosen.get(item['id'])
        if old is None or sold > date.fromisoformat(old['sold_date']) or (sold == date.fromisoformat(old['sold_date']) and distance < old['distance_miles']):
            chosen[item['id']] = item
    items = list(chosen.values())
    items.sort(key=lambda x: (abs(x['price'] - target_price), x['distance_miles'], -date.fromisoformat(x['sold_date']).toordinal(), x['id']))
    prices = [x['price'] for x in items]
    output = [{**x, 'price_delta': x['price'] - target_price} for x in items]
    return {'count': len(items), 'average_price': sum(prices) / len(prices) if prices else None, 'median_price': statistics.median(prices) if prices else None, 'comparables': output}

