        if len(row) != 5:
            raise ValueError('invalid row')
        timestamp, component, event, location, quantity = row
        if not component.strip() or not event.strip() or (not location.strip()):
            raise ValueError('empty field')
        try:
            datetime.fromisoformat(timestamp.strip())
            amount = int(quantity.strip(), 10)
        except Exception as exc:
            raise ValueError('invalid value') from exc
        event = event.strip()
        if event not in {'INSTALL', 'REMOVE', 'INSPECT'} or amount < 0:
            raise ValueError('invalid value')
        result.append({'timestamp': timestamp, 'component': component.strip(), 'event': event, 'location': location.strip(), 'quantity': amount})
    return result

def summarize_components(events: list[dict[str, object]]) -> list[dict[str, object]]:
    groups = {}
    for index, event in enumerate(events):
        name = event['component']
        if name not in groups:
            groups[name] = {'component': name, 'location': event['location'], 'status': event['event'], 'quantity': 0, 'inspections': 0, '_latest': (datetime.fromisoformat(event['timestamp'].strip()), index)}
        item = groups[name]
        item['quantity'] += event['quantity']
        if event['event'] == 'INSPECT':
            item['inspections'] += 1
        key = (datetime.fromisoformat(event['timestamp'].strip()), index)
        if key >= item['_latest']:
            item['location'] = event['location']
            item['status'] = event['event']
            item['_latest'] = key
    return [{key: value for key, value in item.items() if key != '_latest'} for item in sorted(groups.values(), key=lambda x: x['component'])]

