        raise ValueError('invalid state')
    return value

def apply_updates(blob: bytes, updates: list[dict]) -> bytes:
    state = copy.deepcopy(deserialize_state(blob))
    pets = state.setdefault('pets', {})
    for item in updates:
        if not isinstance(item, dict) or not all((k in item for k in ('pet', 'vaccine', 'date', 'interval_days'))):
            raise ValueError('invalid update')
        _date(item['date'])
        if not isinstance(item['interval_days'], int) or isinstance(item['interval_days'], bool) or item['interval_days'] < 0:
            raise ValueError('invalid interval')
