from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from collections.abc import Mapping

def render_payroll_report(records: list[dict[str, object]], page: int, page_size: int) -> str:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('invalid page size')
    rows = []
    for record in records:
        if not isinstance(record, Mapping):
            raise ValueError('invalid record')
        try:
            employee_id = record['employee_id']
            name = record['name']
            department = record['department']
            gross = Decimal(str(record['gross']))
            deductions = Decimal(str(record['deductions']))
        except (KeyError, InvalidOperation, ValueError, TypeError):
            raise ValueError('invalid record')
        if not all((isinstance(value, str) and value for value in (employee_id, name, department))):
            raise ValueError('invalid record')
        if not gross.is_finite() or not deductions.is_finite() or gross < 0 or (deductions < 0) or (deductions > gross):
            raise ValueError('invalid amounts')
        rows.append((employee_id, name, department, gross, deductions))
    rows.sort(key=lambda row: (row[2].casefold(), row[1].casefold(), row[0].casefold()))
    pages = (len(rows) + page_size - 1) // page_size
    if pages and page > pages:
        raise IndexError('page out of range')
    selected = rows[(page - 1) * page_size:page * page_size]
    quant = Decimal('0.01')

    def money(value):
        return f'${value.quantize(quant, rounding=ROUND_HALF_UP):,.2f}'
    body = []
    total_gross = total_deductions = Decimal('0')
    for employee_id, name, department, gross, deductions in selected:
        total_gross += gross
        total_deductions += deductions
        body.append(f'<tr><td>{employee_id}</td><td>{name}</td><td>{department}</td><td>{money(gross)}</td><td>{money(deductions)}</td><td>{money(gross - deductions)}</td></tr>')
    total_net = total_gross - total_deductions
    return '\n'.join(['<section class="payroll">', '<h1>Payroll report</h1>', '<table>', '<thead><tr><th>Employee ID</th><th>Name</th><th>Department</th><th>Gross</th><th>Deductions</th><th>Net</th></tr></thead>', '<tbody>', *body, '</tbody>', f'<tfoot><tr><th colspan="3">Page totals</th><td>{money(total_gross)}</td><td>{money(total_deductions)}</td><td>{money(total_net)}</td></tr></tfoot>', '</table>', f'<p class="page">Page {page} of {pages}</p>', '</section>'])

