def _shift_interval(shift):
    try:
        start = datetime.strptime(shift['date'] + ' ' + shift['start'], '%Y-%m-%d %H:%M')
        end = datetime.strptime(shift['date'] + ' ' + shift['end'], '%Y-%m-%d %H:%M')
    except (KeyError, TypeError, ValueError):
        raise ValueError('invalid shift')
    if end <= start:
        end += timedelta(days=1)
    return (start, end)

def calculate_employee_record(employee: dict, max_hours: float, min_break_hours: float) -> dict:
    if not isinstance(employee, dict) or not isinstance(max_hours, (int, float)) or (not isinstance(min_break_hours, (int, float))) or (max_hours < 0) or (min_break_hours < 0):
        raise ValueError('invalid employee')
    try:
        ident = employee['id']
        name = employee['name']
        shifts = employee['shifts']
    except (KeyError, TypeError):
        raise ValueError('invalid employee')
    if not isinstance(ident, str) or not isinstance(name, str) or (not isinstance(shifts, list)):
        raise ValueError('invalid employee')
    intervals = [_shift_interval(s) for s in shifts]
    intervals.sort(key=lambda x: x[0])
    hours = sum(((end - start).total_seconds() for start, end in intervals)) / 3600
    rest = any(((intervals[i][0] - intervals[i - 1][1]).total_seconds() / 3600 < min_break_hours for i in range(1, len(intervals))))
    violations = []
    if hours > max_hours:
        violations.append('overtime')
    if rest:
        violations.append('insufficient_rest')
    return {'id': ident, 'name': name, 'hours': round(hours, 2), 'violations': violations}

