        if not isinstance(record, dict) or set(record) != {'user', 'channels', 'enabled'}:
            raise ValueError('invalid record')
        if not isinstance(record['user'], str) or not record['user']:
            raise ValueError('invalid user')
        channels = record['channels']
        if not isinstance(channels, list) or not channels:
            raise ValueError('invalid channels')
        if any((not isinstance(c, str) or not c for c in channels)):
            raise ValueError('invalid channel')
        if len(channels) != len(set(channels)):
            raise ValueError('duplicate channel')
        if not isinstance(record['enabled'], bool):
            raise ValueError('invalid enabled value')

