import csv
import html
import io
from datetime import date
from decimal import Decimal, InvalidOperation

def parse_closing_records(text: str) -> list[dict]:
    reader = csv.reader(io.StringIO(text))
    try:
        header = next(reader)
    except StopIteration:
        raise ValueError('missing header')
    expected = ['closing_date', 'property_id', 'address', 'agent', 'amount', 'status']
    if [x.strip() for x in header] != expected:
        raise ValueError('invalid header')
    result = []
    for row in reader:
        if not row or all((not x.strip() for x in row)):
            continue
        if len(row) != 6:
            raise ValueError('invalid row')
        fields = [x.strip() for x in row]
        if any((not x for x in fields)):
            raise ValueError('blank field')
        try:
            day = date.fromisoformat(fields[0])
            amount = Decimal(fields[4])
        except (ValueError, InvalidOperation):
            raise ValueError('invalid value')
        if amount < 0 or amount.as_tuple().exponent != -2:
            raise ValueError('invalid amount')
        if fields[5] not in ('closed', 'pending', 'cancelled'):
            raise ValueError('invalid status')
        result.append({'closing_date': day, 'property_id': fields[1], 'address': fields[2], 'agent': fields[3], 'amount_cents': int(amount * 100), 'status': fields[5]})
    return result

def summarize_closings(records: list[dict]) -> list[dict]:
    groups = {}
    for record in records:
        key = record['property_id']
        if key not in groups:
            groups[key] = {'latest': record, 'closed_total_cents': 0, 'closed_count': 0, 'status_counts': {'closed': 0, 'pending': 0, 'cancelled': 0}}
        group = groups[key]
        if record['closing_date'] >= group['latest']['closing_date']:
            group['latest'] = record
        group['status_counts'][record['status']] += 1
        if record['status'] == 'closed':
            group['closed_total_cents'] += record['amount_cents']
            group['closed_count'] += 1
    result = []
    for key, group in groups.items():
        latest = group['latest']
        result.append({'property_id': key, 'address': latest['address'], 'agent': latest['agent'], 'latest_date': latest['closing_date'], 'closed_total_cents': group['closed_total_cents'], 'closed_count': group['closed_count'], 'status_counts': group['status_counts']})
    return sorted(result, key=lambda x: (-x['closed_total_cents'], -x['latest_date'].toordinal(), x['property_id']))

def render_closing_report(summary: list[dict], title: str) -> str:
    esc = lambda value: html.escape(str(value), quote=True)
    rows = []
    total_count = total_amount = 0
    counts = {'closed': 0, 'pending': 0, 'cancelled': 0}
    for item in summary:
        statuses = item['status_counts']
        status_text = f"closed={statuses['closed']}, pending={statuses['pending']}, cancelled={statuses['cancelled']}"
        rows.append(f"<tr><td>{esc(item['property_id'])}</td><td>{esc(item['address'])}</td><td>{esc(item['agent'])}</td><td>{item['latest_date'].isoformat()}</td><td>{item['closed_count']}</td><td>${item['closed_total_cents'] / 100:.2f}</td><td>{esc(status_text)}</td></tr>")
        total_count += item['closed_count']
        total_amount += item['closed_total_cents']
