from datetime import date
from html import escape
_KEYS = {'pet', 'adopter', 'email', 'due', 'status', 'notes'}

def _date(value):
    try:
        return date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def parse_followup(record: dict) -> dict:
    if not isinstance(record, dict) or set(record) != _KEYS:
        raise TypeError('invalid record')
    if any((not isinstance(record[key], str) for key in _KEYS)):
        raise TypeError('fields must be strings')
    due = _date(record['due'])
    if record['status'] not in {'pending', 'completed'}:
        raise ValueError('invalid status')
    result = dict(record)
    result['due'] = due
    return result

def _processed(records, as_of):
    today = _date(as_of)
    result = []
    for record in records:
        item = parse_followup(record)
        if item['status'] == 'completed':
            category = 'completed'
        elif item['due'] < today:
            category = 'overdue'
        else:
            category = 'upcoming'
        item['category'] = category
        result.append(item)
    return result

