    if isinstance(start, bool) or not isinstance(start, int) or isinstance(end, bool) or (not isinstance(end, int)) or (start > end):
        raise ValueError('invalid interval')
    if not isinstance(donations, list):
        raise ValueError('invalid donations')
    totals: dict[str, list[int]] = {}
    for record in donations:
        donor, amount, timestamp = _record(record)
        if start <= timestamp < end:
            if donor not in totals:
                totals[donor] = [0, 0, timestamp]
            totals[donor][0] += amount
            totals[donor][1] += 1
            totals[donor][2] = max(totals[donor][2], timestamp)
