def summarize_runs(project: str, min_qscore: float=0.0, page_size: int=50) -> list[dict]:
    if not isinstance(project, str) or not project:
        raise ValueError('invalid project')
    if isinstance(min_qscore, bool) or not isinstance(min_qscore, (int, float)) or (not 0 <= min_qscore <= 100):
        raise ValueError('invalid qscore')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
