from datetime import datetime
from html import escape

def _split_fields(line):
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('dangling escape')
    fields.append(''.join(current))
    return fields

def parse_observations(text: str) -> list[dict]:
    result = []
    for number, raw in enumerate(text.splitlines(), 1):
        if not raw.strip():
            continue
        fields = _split_fields(raw)
        if len(fields) != 4:
            raise ValueError(f'invalid line {number}')
        timestamp, satellite, label, confidence = fields
        if not satellite or not label:
            raise ValueError(f'invalid line {number}')
        try:
            datetime.strptime(timestamp, '%Y-%m-%dT%H:%M:%SZ')
            value = float(confidence)
        except (ValueError, TypeError):
            raise ValueError(f'invalid line {number}')
        if not 0.0 <= value <= 1.0:
            raise ValueError(f'invalid line {number}')
        result.append({'timestamp': timestamp, 'satellite': satellite, 'label': label, 'confidence': value})
    return result

def summarize_observations(observations: list[dict], min_confidence: float=0.0) -> list[dict]:
    if not 0.0 <= min_confidence <= 1.0:
        raise ValueError('invalid threshold')
    groups = {}
    for item in observations:
        if item['confidence'] < min_confidence:
            continue
        key = (item['satellite'], item['label'])
        group = groups.setdefault(key, [])
        group.append(item)
    result = []
    for (satellite, label), items in groups.items():
        average = round(sum((x['confidence'] for x in items)) / len(items), 3)
        result.append({'satellite': satellite, 'label': label, 'count': len(items), 'average_confidence': average, 'latest_observation': max((x['timestamp'] for x in items))})
    result.sort(key=lambda x: (-x['count'], -x['average_confidence'], x['satellite'], x['label']))
    return result

def render_report(title: str, summary: list[dict]) -> str:
    rows = []
    for item in summary:
        rows.append('<tr><td>{}</td><td>{}</td><td>{}</td><td>{:.3f}</td><td>{}</td></tr>'.format(escape(str(item['satellite'])), escape(str(item['label'])), item['count'], item['average_confidence'], escape(str(item['latest_observation']))))
    return '<section class="report"><h1>{}</h1><table><thead><tr><th>Satellite</th><th>Class</th><th>Count</th><th>Average confidence</th><th>Latest observation</th></tr></thead><tbody>{}</tbody></table></section>'.format(escape(title), ''.join(rows))

