from datetime import date
import requests

def summarize_weighbridge(start_date: str, end_date: str, minimum_tonnes: float=0.0) -> list[dict[str, object]]:
    try:
        start = date.fromisoformat(start_date)
        end = date.fromisoformat(end_date)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if start_date != start.isoformat() or end_date != end.isoformat() or start > end:
        raise ValueError('invalid date range')
    if minimum_tonnes < 0:
        raise ValueError('invalid minimum')
    response = requests.get('https://weighbridge.example.test/api/tickets', params={'start': start_date, 'end': end_date}, headers={'Accept': 'application/json'})
    if response.status_code != 200:
        raise RuntimeError('request failed')
    payload = response.json()
    if not isinstance(payload, dict) or not isinstance(payload.get('tickets'), list):
        raise ValueError('invalid payload')
    groups = {}
    for ticket in payload['tickets']:
        if ticket['status'] != 'accepted':
            continue
        ticket_date = date.fromisoformat(ticket['date'])
        tonnes = ticket['weight_kg'] / 1000
        if start <= ticket_date <= end and tonnes >= minimum_tonnes:
            key = (ticket['date'], ticket['material'])
            groups[key] = groups.get(key, 0) + tonnes
    return [{'date': d, 'material': m, 'tonnes': round(total, 2)} for (d, m), total in sorted(groups.items())]

