    if not text.strip():
        raise ValueError('empty input')
    rows = list(csv.reader(io.StringIO(text)))
    if not rows or rows[0] != FIELDS:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if not row or not any((x.strip() for x in row)):
            continue
        if len(row) != 6:
            raise ValueError('invalid row')
        sku, name, category, quantity, price, expires = [x.strip() for x in row]
        if not sku or not name or (not category):
            raise ValueError('empty field')
        try:
            quantity = int(quantity)
            price_decimal = Decimal(price)
            expires = date.fromisoformat(expires)
        except (ValueError, InvalidOperation):
            raise ValueError('invalid value')
        if quantity < 0 or not price_decimal.is_finite() or price_decimal < 0:
            raise ValueError('invalid number')
        result.append({'sku': sku, 'name': name, 'category': category, 'quantity': quantity, 'unit_price': float(price_decimal), 'expires': expires})
    return result

def _today(value):
    try:
        return date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')

def inventory_summary(records: list[dict[str, object]], today: str) -> dict[str, dict[str, object]]:
    current = _today(today)
    groups = {}
    for record in records:
        category = record['category']
        item = groups.setdefault(category, {'units': 0, 'value': Decimal('0'), 'expiring_soon': 0})
        item['units'] += record['quantity']
        item['value'] += Decimal(str(record['unit_price'])) * record['quantity']
        if current <= record['expires'] <= current + timedelta(days=30):
            item['expiring_soon'] += record['quantity']
    return {k: {'units': groups[k]['units'], 'value': float(groups[k]['value'].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)), 'expiring_soon': groups[k]['expiring_soon']} for k in sorted(groups)}

