    _today(today)
    rows = []
    for r in sorted(records, key=lambda x: (x['category'], x['name'], x['sku'])):
        vals = [r['sku'], r['name'], r['category'], str(r['quantity']), f"${r['unit_price']:.2f}", str(r['expires'])]
