    elif sort_by == 'artist':
        checked.sort(key=lambda x: (x[1]['artist'].lower(), x[1]['title'].lower(), x[0]))
    elif sort_by == 'duration':
        checked.sort(key=lambda x: (x[1]['duration'], x[1]['title'].lower(), x[0]))
