import json
from copy import deepcopy

def encode_permits(records: list[dict]) -> bytes:
    try:
        return json.dumps(records, separators=(',', ':'), ensure_ascii=False).encode('utf-8')
    except (TypeError, ValueError, UnicodeError) as exc:
        raise ValueError('invalid records') from exc

def decode_permits(blob: bytes) -> list[dict]:
    try:
        value = json.loads(blob.decode('utf-8'))
    except (TypeError, ValueError, UnicodeError) as exc:
        raise ValueError('invalid blob') from exc
    if not isinstance(value, list):
        raise ValueError('state must be a list')
    return value

def apply_updates(blob: bytes, updates: list[dict]) -> bytes:
    current = decode_permits(blob)
    positions = {item.get('permit_id'): i for i, item in enumerate(current)}
    result = deepcopy(current)
    for update in updates:
        if 'permit_id' not in update or 'updated' not in update:
            raise ValueError('update requires permit_id and updated')
        key = update['permit_id']
        if key in positions:
            index = positions[key]
            if update['updated'] > result[index].get('updated', ''):
                result[index] = deepcopy(update)
        else:
            positions[key] = len(result)
            result.append(deepcopy(update))
    return encode_permits(result)

def build_report(records: list[dict], as_of: str) -> list[dict]:
    groups = {}
    for record in records:
        if record.get('status') != 'approved':
            continue
        if not record.get('issued', '') <= as_of < record.get('expires', ''):
            continue
        key = (record.get('facility'), record.get('category'))
        count, total = groups.get(key, (0, 0.0))
        groups[key] = (count + 1, total + float(record.get('emissions', 0)))
    answer = []
    for (facility, category), (count, total) in sorted(groups.items()):
        answer.append({'facility': facility, 'category': category, 'count': count, 'total_emissions': round(total, 2)})
    return answer

