import json
from datetime import date
from copy import deepcopy

def _day(value):
    try:
        return date.fromisoformat(value)
    except Exception as exc:
        raise ValueError('invalid date') from exc

def new_state(account_names: list[str]) -> dict:
    if any((not isinstance(x, str) or not x for x in account_names)) or len(set(account_names)) != len(account_names):
        raise ValueError('invalid accounts')
    return {'accounts': {x: 0 for x in account_names}, 'processed': []}

def _valid_state(value):
    if not isinstance(value, dict) or set(value) != {'accounts', 'processed'}:
        raise ValueError('invalid state')
    accounts = value['accounts']
    processed = value['processed']
    if not isinstance(accounts, dict) or not isinstance(processed, list):
        raise ValueError('invalid state')
    if any((not isinstance(k, str) or not k or (not isinstance(v, int)) or isinstance(v, bool) for k, v in accounts.items())):
        raise ValueError('invalid state')
    if any((not isinstance(x, str) or not x for x in processed)) or len(set(processed)) != len(processed):
        raise ValueError('invalid state')
    return value

def encode_state(state: dict) -> bytes:
    _valid_state(state)
    return json.dumps(state, separators=(',', ':'), ensure_ascii=False).encode('utf-8')

def decode_state(blob: bytes | str) -> dict:
    try:
        if isinstance(blob, bytes):
            blob = blob.decode('utf-8')
        value = json.loads(blob)
        return deepcopy(_valid_state(value))
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError('invalid data') from exc

def apply_transactions(state: dict, transactions: list[dict], start_date: str, end_date: str) -> tuple[dict, dict]:
    _valid_state(state)
    first, last = (_day(start_date), _day(end_date))
    if first > last or not isinstance(transactions, list):
        raise ValueError('invalid range')
    seen = set(state['processed'])
    checked = []
    for tx in transactions:
        if not isinstance(tx, dict) or set(tx) != {'id', 'account', 'date', 'points'}:
            raise ValueError('invalid transaction')
        if not isinstance(tx['id'], str) or not tx['id'] or (not isinstance(tx['account'], str)) or (not tx['account']):
            raise ValueError('invalid transaction')
        if not isinstance(tx['points'], int) or isinstance(tx['points'], bool):
            raise ValueError('invalid transaction')
        checked.append((_day(tx['date']), tx['id'], tx))
    checked.sort(key=lambda x: (x[0], x[1]))
    result = deepcopy(state)
    applied, total = ([], 0)
    for day, ident, tx in checked:
        if ident in seen:
            continue
        seen.add(ident)
        if first <= day <= last:
            if tx['account'] not in result['accounts']:
                raise ValueError('unknown account')
            result['accounts'][tx['account']] += tx['points']
            result['processed'].append(ident)
            applied.append(ident)
            total += tx['points']
    return (result, {'applied': applied, 'total': total})

