import requests

def _valid_date(value):
    if not isinstance(value, str):
        raise ValueError('invalid date')
    try:
        datetime.date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')
    return value

def _check_unit(name, capacity, occupied):
    if not isinstance(name, str) or not name or type(capacity) is not int or (type(occupied) is not int):
        raise ValueError('invalid unit')
    if capacity < 0 or occupied < 0 or occupied > capacity:
        raise ValueError('invalid occupancy')

def fetch_occupancy(url: str, api_key: str, facility: str, start: str, end: str) -> list[dict]:
    response = requests.get(url, params={'facility': facility, 'start': start, 'end': end}, headers={'X-API-Key': api_key}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError('request failed')
    try:
        payload = response.json()
        if not isinstance(payload, dict) or not isinstance(payload['days'], list):
            raise ValueError
        result = []
        for day in payload['days']:
            if not isinstance(day, dict) or not isinstance(day['units'], list):
                raise ValueError
            date = _valid_date(day['date'])
            for unit in day['units']:
                if not isinstance(unit, dict):
                    raise ValueError
                _check_unit(unit['name'], unit['capacity'], unit['occupied'])
                result.append({'date': date, 'unit': unit['name'], 'capacity': unit['capacity'], 'occupied': unit['occupied']})
        return result
    except (KeyError, TypeError, ValueError):
        raise ValueError('invalid response')

