import re
from datetime import datetime
import requests

def fetch_slots(day: str, region: str, api_key: str) -> list[dict]:
    if not re.fullmatch('\\d{4}-\\d{2}-\\d{2}', day):
        raise ValueError('day must be YYYY-MM-DD')
    r = requests.get('https://api.veterans.example/v1/slots', params={'date': day, 'region': region}, headers={'Authorization': 'Bearer ' + api_key, 'Accept': 'application/json'}, timeout=10)
    if r.status_code != 200:
        raise RuntimeError(f'slot service returned HTTP {r.status_code}')
    try:
        doc = r.json()
    except Exception:
        raise RuntimeError('slot service returned invalid JSON')
    if not isinstance(doc, dict):
        raise RuntimeError('slot service returned an invalid document')
    out = []
    for c in doc.get('cemeteries', []):
        if not isinstance(c, dict) or not isinstance(c.get('name'), str):
            continue
        name, priority = (c['name'], c.get('priority', 0))
        for s in c.get('slots', []):
            if not isinstance(s, dict) or not isinstance(s.get('start'), str) or (not isinstance(s.get('end'), str)):
                continue
            try:
                datetime.fromisoformat(s['start'].replace('Z', '+00:00'))
                datetime.fromisoformat(s['end'].replace('Z', '+00:00'))
            except ValueError:
                continue
            if s.get('available') and isinstance(s.get('capacity'), int) and (s['capacity'] > 0):
                out.append({'id': s.get('id', name + '|' + s['start']), 'cemetery': name, 'priority': priority, 'start': s['start'], 'end': s['end'], 'capacity': s['capacity']})
    out.sort(key=lambda x: (x['start'], -x['priority'], x['cemetery'], x['end']))
    return out

def choose_schedule(slots: list[dict], limit: int) -> list[dict]:
    if limit < 0:
        raise ValueError('limit must be non-negative')
    if not limit:
        return []

    def parsed(x):
        try:
            return (datetime.fromisoformat(x['start'].replace('Z', '+00:00')), datetime.fromisoformat(x['end'].replace('Z', '+00:00')))
        except (ValueError, TypeError, KeyError):
            return None
    candidates = [(parsed(x), x) for x in slots]
    candidates = [(p, x) for p, x in candidates if p]
    candidates.sort(key=lambda z: (z[0][0], -z[1].get('priority', 0), z[1].get('cemetery', ''), z[0][1]))
    chosen, names = ([], set())
    for (start, end), item in candidates:
        if item.get('cemetery') in names or any((start < e and s < end for s, e, _ in chosen)):
            continue
        chosen.append((start, end, item))
        names.add(item.get('cemetery'))
        if len(chosen) == limit:
            break
    chosen.sort(key=lambda x: x[0])
    return [x[2] for x in chosen]

def format_schedule(slots: list[dict]) -> str:
    return ''.join((f"{x['start']} | {x['end']} | {x['cemetery']} | {x['id']}\n" for x in slots))

