import requests
from datetime import date, timedelta

def fetch_permits(api_url: str, student_id: str, term: str, api_key: str) -> list[dict]:
    response = requests.get(api_url.rstrip('/') + '/v1/permits', params={'student_id': student_id, 'term': term}, headers={'X-API-Key': api_key}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError(f'permit service returned {response.status_code}')
    payload = response.json()
    if not isinstance(payload, dict) or not isinstance(payload.get('permits'), list):
        raise ValueError('invalid permit payload')
    result = []
    for item in payload['permits']:
        try:
            normalized = {'id': item['permitId'], 'lot': item['lotCode'], 'start': item['validFrom'], 'end': item['validTo'], 'priority': int(item['priority']), 'state': item['state'], 'plate': str(item['vehicle']['plate'])}
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid permit')
        result.append(normalized)
    return sorted(result, key=lambda x: (x['lot'], x['start'], x['id']))

def parking_calendar(permits: list[dict], start_date: str, end_date: str) -> dict[str, list[dict]]:
    try:
        first = date.fromisoformat(start_date)
        last = date.fromisoformat(end_date)
    except (TypeError, ValueError):
        raise ValueError('invalid calendar dates')
    if first > last:
        raise ValueError('start date is after end date')
    checked = []
    for permit in permits:
        try:
            begin = date.fromisoformat(permit['start'])
            finish = date.fromisoformat(permit['end'])
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid permit dates')
        if begin > finish:
            raise ValueError('permit start is after end')
        checked.append((permit, begin, finish))
    output = {}
    current = first
    while current <= last:
        winners = {}
        for permit, begin, finish in checked:
            if permit['state'] != 'ACTIVE' or not begin <= current <= finish:
                continue
            old = winners.get(permit['lot'])
            key = (-permit['priority'], begin, permit['id'])
            if old is None or key < old[0]:
                winners[permit['lot']] = (key, permit)
        output[current.isoformat()] = [{'lot': lot, 'permit_id': winners[lot][1]['id'], 'plate': winners[lot][1]['plate']} for lot in sorted(winners)]
        current += timedelta(days=1)
    return output

