import re
import requests

def normalize_sds(payload: dict) -> dict:
    if not isinstance(payload, dict) or not isinstance(payload.get('product_id'), str):
        raise ValueError('invalid payload')
    product_id = ' '.join(payload['product_id'].split())
    if not product_id or not isinstance(payload.get('sections'), list):
        raise ValueError('invalid payload')
    sections = []
    for section in payload['sections']:
        if not isinstance(section, dict) or not isinstance(section.get('title'), str) or (not isinstance(section.get('hazards'), list)):
            raise ValueError('invalid section')
        title = ' '.join(section['title'].split())
        if not title:
            raise ValueError('invalid title')
        hazards = []
        for hazard in section['hazards']:
            if not isinstance(hazard, dict) or not isinstance(hazard.get('code'), str) or (not isinstance(hazard.get('category'), str)) or (not isinstance(hazard.get('severity'), int)) or isinstance(hazard.get('severity'), bool) or (not isinstance(hazard.get('statements'), list)):
                raise ValueError('invalid hazard')
            code = ' '.join(hazard['code'].split())
            category = ' '.join(hazard['category'].split())
            if not code or not category or (not 1 <= hazard['severity'] <= 5):
                raise ValueError('invalid hazard')
            statements = []
            for statement in hazard['statements']:
                if not isinstance(statement, str):
                    raise ValueError('invalid statement')
                statement = ' '.join(statement.split())
                if not statement:
                    raise ValueError('invalid statement')
                if statement not in statements:
                    statements.append(statement)
            hazards.append({'code': code, 'category': category, 'severity': hazard['severity'], 'statements': statements})
        hazards.sort(key=lambda x: (-x['severity'], x['code']))
        sections.append({'title': title, 'hazards': hazards})
    return {'product_id': product_id, 'sections': sections}

def fetch_sds(product_id: str, locale: str='en') -> dict:
    response = requests.get('https://sds.example.test/api/v1/products/' + product_id + '/sds', params={'locale': locale}, headers={'Accept': 'application/json'}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError('HTTP status ' + str(response.status_code))
    try:
        payload = response.json()
    except Exception as exc:
        raise ValueError('invalid JSON') from exc
    return normalize_sds(payload)

def summarize_hazards(sds: dict) -> list[dict]:
    if not isinstance(sds, dict) or not isinstance(sds.get('sections'), list):
        raise ValueError('invalid SDS')
    groups = {}
    for section in sds['sections']:
        if not isinstance(section, dict) or not isinstance(section.get('hazards'), list):
            raise ValueError('invalid section')
        for hazard in section['hazards']:
            if not isinstance(hazard, dict) or not isinstance(hazard.get('category'), str) or (not isinstance(hazard.get('severity'), int)) or (not isinstance(hazard.get('statements'), list)):
                raise ValueError('invalid hazard')
            category = hazard['category']
            group = groups.setdefault(category, {'category': category, 'hazard_count': 0, 'maximum_severity': 0, 'statements': []})
            group['hazard_count'] += 1
            group['maximum_severity'] = max(group['maximum_severity'], hazard['severity'])
            for statement in hazard['statements']:
                if statement not in group['statements']:
                    group['statements'].append(statement)
    return sorted(groups.values(), key=lambda x: (-x['maximum_severity'], -x['hazard_count'], x['category']))

