from datetime import datetime
from html import escape

def parse_measurements(text: str) -> list[dict]:
    rows = list(csv.reader(io.StringIO(text)))
    result = []
    seen_record = False
    for row in rows:
        if not row or all((not field.strip() for field in row)):
            continue
        fields = [field.strip() for field in row]
        lowered = [field.lower() for field in fields]
        if not seen_record and lowered == ['timestamp', 'freezer', 'temperature', 'status']:
            seen_record = True
            continue
        seen_record = True
        if len(fields) != 4:
            raise ValueError('invalid record')
        try:
            timestamp = datetime.fromisoformat(fields[0])
            temperature = float(fields[2])
        except (TypeError, ValueError):
            raise ValueError('invalid record')
        if not fields[1] or not math.isfinite(temperature) or fields[3] not in {'OK', 'ALARM'}:
            raise ValueError('invalid record')
        result.append({'timestamp': timestamp, 'freezer': fields[1], 'temperature': temperature, 'status': fields[3]})
    return result

