    groups = {}
    for index, reading in enumerate(readings):
        name = reading['freezer']
        groups.setdefault(name, []).append((index, reading))
    output = []
    for name, items in groups.items():
        values = [item['temperature'] for _, item in items]
        latest = max(items, key=lambda pair: (pair[1]['timestamp'], pair[0]))[1]
        output.append({'freezer': name, 'count': len(values), 'minimum': min(values), 'maximum': max(values), 'average': sum(values) / len(values), 'alarms': sum((item['status'] == 'ALARM' for _, item in items)), 'latest_status': latest['status']})
    return sorted(output, key=lambda item: (item['freezer'].casefold(), item['freezer']))

def render_report(readings: list[dict], title: str) -> str:
    rows = []
    for item in summarize(readings):
        rows.append('<tr><td>{}</td><td>{}</td><td>{}</td><td>{}</td><td>{}</td><td>{}</td><td>{}</td></tr>'.format(escape(item['freezer']), item['count'], item['minimum'], item['maximum'], item['average'], item['alarms'], item['latest_status']))
    head = '<div class="report"><h1>{}</h1><table><thead><tr><th>Freezer</th><th>Readings</th><th>Minimum (C)</th><th>Maximum (C)</th><th>Average (C)</th><th>Alarms</th><th>Latest status</th></tr></thead><tbody>'.format(escape(title))
    return head + ''.join(rows) + '</tbody></table></div>'

