def get_low_stock_inventory(api_url: str, shop_id: str, maximum_quantity: int=5) -> list[dict]:
    if not shop_id or maximum_quantity < 0:
        raise ValueError('invalid arguments')
    combined = {}
    page = 1
    while page is not None:
        response = requests.get(api_url.rstrip('/') + '/inventory', params={'shop_id': shop_id, 'page': page, 'limit': 100}, headers={'Accept': 'application/json'})
        if response.status_code != 200:
            raise RuntimeError('inventory request failed')
        data = response.json()
        for item in data.get('items', []):
            if not all((k in item for k in ('sku', 'name', 'quantity', 'unit_cost'))):
                raise ValueError('invalid item')
            sku = item['sku']
            name = item['name']
            quantity = item['quantity']
            unit_cost = item['unit_cost']
            if not isinstance(sku, str) or not sku or (not isinstance(name, str)) or (not isinstance(quantity, int)) or isinstance(quantity, bool) or (quantity < 0) or (not isinstance(unit_cost, (int, float))) or isinstance(unit_cost, bool) or (unit_cost < 0):
                raise ValueError('invalid item')
            if sku not in combined:
                combined[sku] = {'sku': sku, 'name': name, 'quantity': 0, 'total_value': 0.0}
            combined[sku]['quantity'] += quantity
            combined[sku]['total_value'] += quantity * unit_cost
        page = data.get('next_page')
    result = []
    for item in combined.values():
        if item['quantity'] <= maximum_quantity:
            item['total_value'] = round(item['total_value'], 2)
            result.append(item)
    return sorted(result, key=lambda x: (x['quantity'], x['sku']))

