    except Exception as exc:
        raise ValueError('invalid response JSON') from exc
    if not isinstance(body, dict) or not isinstance(body.get('donations'), list):
        raise ValueError('invalid donation response')
    return body['donations']

def summarize_donations(records: list[dict[str, Any]]) -> list[dict[str, Any]]:
    latest = {}
    identity = {}
    for index, row in enumerate(records):
        if not isinstance(row, dict):
            raise ValueError('invalid donation record')
        required = ('transaction_id', 'donor', 'campaign', 'amount_cents', 'currency', 'donated_at', 'status')
        if any((key not in row for key in required)):
            raise ValueError('invalid donation record')
        if row['status'] not in ('completed', 'refunded') or not isinstance(row['amount_cents'], int) or isinstance(row['amount_cents'], bool) or (row['amount_cents'] < 0):
            raise ValueError('invalid donation record')
        try:
            stamp = datetime.fromisoformat(str(row['donated_at']).replace('Z', '+00:00'))
        except Exception as exc:
            raise ValueError('invalid donation timestamp') from exc
        tx = row['transaction_id']
        key = (row['donor'], row['campaign'], row['currency'])
        if tx in identity and identity[tx] != key:
            raise ValueError('transaction identity changed')
        identity[tx] = key
        previous = latest.get(tx)
        if previous is None or stamp >= previous[0]:
            latest[tx] = (stamp, index, row)
    totals = {}
    for _, _, row in latest.values():
        key = (row['campaign'], row['currency'], row['donor'])
        amount = row['amount_cents'] if row['status'] == 'completed' else -row['amount_cents']
        totals[key] = totals.get(key, 0) + amount
    result = [{'campaign': c, 'currency': u, 'donor': d, 'total_cents': total} for (c, u, d), total in totals.items() if total]
    result.sort(key=lambda item: (item['campaign'], -item['total_cents'], item['currency'], item['donor']))
    return result

