import json
import math

def _valid_records(records):
    if not isinstance(records, list):
        raise ValueError('invalid records')
    for record in records:
        if not isinstance(record, dict) or set(record) != {'locker', 'user', 'duration_seconds', 'success'}:
            raise ValueError('invalid record')
        if not isinstance(record['locker'], str) or not record['locker']:
            raise ValueError('invalid locker')
        if not isinstance(record['user'], str) or not record['user']:
            raise ValueError('invalid user')
        duration = record['duration_seconds']
        if isinstance(duration, bool) or not isinstance(duration, (int, float)) or duration < 0 or (not math.isfinite(duration)):
            raise ValueError('invalid duration')
        if not isinstance(record['success'], bool):
            raise ValueError('invalid success')
    return records

def encode_access_records(records: list[dict]) -> bytes:
    return json.dumps(_valid_records(records), separators=(',', ':')).encode('utf-8')

def access_report(blob: bytes, locker: str | None=None, page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    try:
        records = _valid_records(json.loads(blob.decode('utf-8')))
    except Exception as exc:
        raise ValueError('invalid blob') from exc
    groups = {}
    for record in records:
        if record['success'] and (locker is None or record['locker'] == locker):
            item = groups.setdefault(record['locker'], [])
            item.append(record['duration_seconds'])
    rows = []
    for name, durations in groups.items():
        total = round(sum(durations), 2)
        rows.append({'locker': name, 'count': len(durations), 'total_duration_seconds': total, 'average_duration_seconds': round(total / len(durations), 2)})
    rows.sort(key=lambda row: (-row['count'], row['locker']))
    start = (page - 1) * page_size
    return {'total_records': sum((len(x) for x in groups.values())), 'page': page, 'page_size': page_size, 'lockers': rows[start:start + page_size]}

