import csv
import io
import re
from datetime import date
from decimal import Decimal, InvalidOperation
from html import escape

def parse_sales(data: str) -> list[dict]:
    if not data:
        raise ValueError('empty input')
    reader = csv.reader(io.StringIO(data))
    try:
        header = next(reader)
    except StopIteration:
        raise ValueError('empty input')
    if header != ['movie', 'date', 'time', 'seat', 'price', 'customer']:
        raise ValueError('invalid header')
    result = []
    for row in reader:
        if len(row) != 6:
            raise ValueError('invalid row')
        movie, day, moment, seat, price, customer = (x.strip() for x in row)
        if not movie or not customer or (not re.fullmatch('[A-Z]+[0-9]+', seat)):
            raise ValueError('invalid field')
        try:
            date.fromisoformat(day)
            if not re.fullmatch('(?:[01][0-9]|2[0-3]):[0-5][0-9]', moment):
                raise ValueError
            value = Decimal(price)
            if value < 0 or value.as_tuple().exponent < -2:
                raise ValueError
            cents = int(value * 100)
            if Decimal(cents) / 100 != value:
                raise ValueError
        except (ValueError, InvalidOperation):
            raise ValueError('invalid value')
        result.append({'movie': movie, 'date': day, 'time': moment, 'seat': seat, 'price_cents': cents, 'customer': customer})
    return result

def aggregate_sales(rows: list[dict]) -> list[dict]:
    grouped = {}
    for row in rows:
        key = (row['movie'], row['date'])
        item = grouped.setdefault(key, {'movie': row['movie'], 'date': row['date'], 'tickets': 0, 'revenue_cents': 0, 'showtimes': {}})
        item['tickets'] += 1
        item['revenue_cents'] += row['price_cents']
        item['showtimes'][row['time']] = item['showtimes'].get(row['time'], 0) + 1
    result = []
    for key in sorted(grouped):
        item = grouped[key]
        result.append({'movie': item['movie'], 'date': item['date'], 'tickets': item['tickets'], 'revenue_cents': item['revenue_cents'], 'showtimes': [{'time': t, 'tickets': item['showtimes'][t]} for t in sorted(item['showtimes'])]})
    return result

def render_html_report(title: str, groups: list[dict]) -> str:
    out = '<div class="report"><h1>' + escape(str(title)) + '</h1>\n'
    for group in groups:
        movie = escape(str(group['movie']))
        day = escape(str(group['date']))
        out += f'''<section data-movie="{movie}" data-date="{day}"><h2>{movie} — {day}</h2><p>Tickets: {group['tickets']} | Revenue: ${group['revenue_cents'] / 100:.2f}</p><ul>\n'''
        for showtime in group['showtimes']:
            out += f"<li>{escape(str(showtime['time']))}: {showtime['tickets']}</li>\n"
        out += '</ul></section>\n'
    return out + '</div>'

