    rows = [[x.strip() for x in row] for row in rows if any((x.strip() for x in row))]
    if not rows or rows[0] != ['mark', 'jurisdiction', 'status', 'score', 'detected']:
        raise ValueError('bad header')
    result = []
    for row in rows[1:]:
        if len(row) != 5:
            raise ValueError('bad row')
        mark, jurisdiction, status, score, detected = row
        if status not in {'new', 'reviewed', 'closed'}:
            raise ValueError('bad status')
        try:
            value = float(score)
        except ValueError:
            raise ValueError('bad score')
        if not 0 <= value <= 100:
            raise ValueError('bad score')
        try:
            date.fromisoformat(detected)
        except ValueError:
            raise ValueError('bad date')
        result.append({'mark': mark, 'jurisdiction': jurisdiction, 'status': status, 'score': value, 'detected': detected})
    return result

def summarize(records: list[dict]) -> list[dict]:
    groups = {}
    for record in records:
        mark = record['mark']
        group = groups.setdefault(mark, {'mark': mark, 'count': 0, 'max_score': record['score'], 'latest': record['detected'], 'jurisdictions': set()})
        group['count'] += 1
        group['max_score'] = max(group['max_score'], record['score'])
        group['latest'] = max(group['latest'], record['detected'])
        group['jurisdictions'].add(record['jurisdiction'])
    result = []
    for group in groups.values():
        group['jurisdictions'] = sorted(group['jurisdictions'])
        result.append(group)
    return sorted(result, key=lambda x: (-x['max_score'], -x['count'], x['mark']))

def render_report(text: str, title: str, min_score: float=0.0) -> str:
