        raise ValueError('bad threshold')
    records = [r for r in parse_feed(text) if r['score'] >= min_score]
    groups = summarize(records)
    esc = lambda value: html.escape(str(value), quote=True)
    rows = ''.join(('<tr><td>{}</td><td>{}</td><td>{:.2f}</td><td>{}</td><td>{}</td></tr>'.format(esc(g['mark']), esc(g['count']), g['max_score'], esc(g['latest']), esc(', '.join(g['jurisdictions']))) for g in groups))
    count = len(groups)
