    return '<section class="trademark-report"><h1>{}</h1><p class="count">{} {}</p><table><thead><tr><th>Mark</th><th>Count</th><th>Max score</th><th>Latest</th><th>Jurisdictions</th></tr></thead><tbody>{}</tbody></table></section>'.format(esc(title), count, word, rows)

