def _split_line(line):
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            if char not in '\\|':
                raise ValueError('invalid escape')
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    fields.append(''.join(current))
    if len(fields) != 6:
        raise ValueError('wrong field count')
    return fields

def parse_manifest(text: str) -> list[dict]:
