def parse_flight_log(text: str) -> list[dict]:
    reader = csv.reader(io.StringIO(text))
    rows = list(reader)
    first = next((row for row in rows if row), None)
    if first != ['timestamp', 'flight', 'airport', 'event', 'minutes']:
        raise ValueError('invalid header')
    start = rows.index(first) + 1
    result = []
    for row in rows[start:]:
        if not row:
            continue
        if len(row) != 5:
            raise ValueError('invalid row')
        timestamp, flight, airport, event, minutes = row
        try:
            datetime.fromisoformat(timestamp[:-1] + '+00:00' if timestamp.endswith('Z') else timestamp)
            value = int(minutes, 10)
        except (ValueError, TypeError):
            raise ValueError('invalid value')
        if not flight or not airport or event not in {'departure', 'arrival', 'delay'} or (value < 0):
            raise ValueError('invalid value')
        result.append({'timestamp': timestamp, 'flight': flight, 'airport': airport, 'event': event, 'minutes': value})
    return result

def summarize_flights(records: list[dict]) -> list[dict]:
    ordered = sorted(enumerate(records), key=lambda pair: (datetime.fromisoformat(pair[1]['timestamp'][:-1] + '+00:00' if pair[1]['timestamp'].endswith('Z') else pair[1]['timestamp']), pair[0]))
    groups = {}
    for _, record in ordered:
        flight = record['flight']
        if flight not in groups:
            groups[flight] = {'flight': flight, 'legs': 0, 'minutes': 0, 'airports': [], 'last_event': record['event']}
        item = groups[flight]
        item['minutes'] += record['minutes']
        item['legs'] += record['event'] in {'departure', 'arrival'}
        if record['airport'] not in item['airports']:
            item['airports'].append(record['airport'])
        item['last_event'] = record['event']
    return [groups[key] for key in sorted(groups)]

