import json

def encode_state(state: dict) -> bytes:
    try:
        return json.dumps(state, sort_keys=True, separators=(',', ':')).encode('utf-8')
    except (TypeError, ValueError, UnicodeError) as exc:
        raise ValueError('invalid state') from exc

def build_replenishment_plan(shelves: list[dict], sales: list[dict], state_blob: bytes) -> tuple[list[dict], bytes]:
    try:
        state = json.loads(state_blob.decode('utf-8'))
    except (AttributeError, UnicodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid state') from exc
    if not isinstance(state, dict):
        raise ValueError('invalid state')
    last = state.get('last_day', {})
    reserved = state.get('reserved', {})
    if not isinstance(last, dict) or not isinstance(reserved, dict):
        raise ValueError('invalid state')
    for mapping in (last, reserved):
        for key, value in mapping.items():
            if not isinstance(key, str) or not isinstance(value, int) or isinstance(value, bool) or (value < 0):
                raise ValueError('invalid state')
    by_sku = {}
    for shelf in shelves:
        if not isinstance(shelf, dict):
            raise ValueError('invalid shelf')
        try:
            sku, on_hand, capacity = (shelf['sku'], shelf['on_hand'], shelf['capacity'])
            minimum, lead = (shelf['min_display'], shelf['lead_days'])
        except KeyError as exc:
            raise ValueError('invalid shelf') from exc
        if not isinstance(sku, str) or not sku or sku in by_sku:
            raise ValueError('invalid shelf')
        values = (on_hand, capacity, minimum, lead)
        if any((not isinstance(x, int) or isinstance(x, bool) or x < 0 for x in values)) or capacity == 0 or minimum > capacity:
            raise ValueError('invalid shelf')
        by_sku[sku] = (on_hand, capacity, minimum, lead)
    totals = {sku: 0 for sku in by_sku}
    newest = dict(last)
    for record in sales:
        if not isinstance(record, dict):
            raise ValueError('invalid sale')
        try:
            sku, day, units = (record['sku'], record['day'], record['units'])
        except KeyError as exc:
            raise ValueError('invalid sale') from exc
        if sku not in by_sku or not isinstance(day, int) or isinstance(day, bool) or (day < 0) or (not isinstance(units, int)) or isinstance(units, bool) or (units < 0):
            raise ValueError('invalid sale')
        if day > last.get(sku, 0):
            totals[sku] += units
            newest[sku] = max(newest.get(sku, 0), day)
    plan = []
    for sku, (on_hand, capacity, minimum, lead) in by_sku.items():
        target = min(capacity, minimum + totals[sku] * lead)
        quantity = max(0, target - (on_hand - reserved.get(sku, 0)))
        if quantity:
            plan.append({'sku': sku, 'quantity': quantity, 'demand': totals[sku], 'target': target})
    plan.sort(key=lambda item: (-item['quantity'], item['sku']))
    return (plan, encode_state({'last_day': newest, 'reserved': dict(reserved)}))

