import json
import math
from numbers import Real

def validate_reading(reading: dict) -> tuple[int, str, float, float]:
    if not isinstance(reading, dict) or set(reading) != {'timestamp', 'station', 'flow_m3h', 'salinity_ppt'}:
        raise ValueError('invalid reading')
    timestamp = reading['timestamp']
    station = reading['station']
    flow = reading['flow_m3h']
    salinity = reading['salinity_ppt']
    if isinstance(timestamp, bool) or not isinstance(timestamp, int):
        raise ValueError('invalid timestamp')
    if not isinstance(station, str) or not station:
        raise ValueError('invalid station')
    if any((isinstance(x, bool) or not isinstance(x, Real) or (not math.isfinite(float(x))) for x in (flow, salinity))):
        raise ValueError('invalid measurement')
    return (timestamp, station, float(flow), float(salinity))

def aggregate_readings(readings: list[dict], window_seconds: int=900) -> list[dict]:
    if isinstance(window_seconds, bool) or not isinstance(window_seconds, int) or window_seconds <= 0:
        raise ValueError('invalid window')
    groups = {}
    for reading in readings:
        timestamp, station, flow, salinity = validate_reading(reading)
        key = (station, timestamp // window_seconds * window_seconds)
        groups.setdefault(key, []).append((flow, salinity))
    result = []
    for (station, start), values in sorted(groups.items()):
        result.append({'station': station, 'window_start': start, 'count': len(values), 'average_flow_m3h': round(sum((x[0] for x in values)) / len(values), 6), 'maximum_salinity_ppt': round(max((x[1] for x in values)), 6)})
    return result

def encode_checkpoint(state: dict) -> bytes:
    if not isinstance(state, dict):
        raise ValueError('checkpoint must be an object')
    try:
        return json.dumps(state, sort_keys=True, separators=(',', ':'), allow_nan=False).encode('utf-8')
    except (TypeError, ValueError, OverflowError) as exc:
        raise ValueError('invalid checkpoint') from exc

def decode_checkpoint(blob: bytes | str) -> dict:
    try:
        if isinstance(blob, bytes):
            text = blob.decode('utf-8')
        elif isinstance(blob, str):
            text = blob
        else:
            raise ValueError('invalid checkpoint')
        value = json.loads(text)
    except (UnicodeDecodeError, json.JSONDecodeError, TypeError, ValueError) as exc:
        raise ValueError('invalid checkpoint') from exc
    if not isinstance(value, dict):
        raise ValueError('checkpoint must be an object')
    return value

