import requests

def fetch_news(category: str | None=None, page: int=1, per_page: int=10) -> dict:
    if category is not None and (not isinstance(category, str)):
        raise ValueError('category must be a string or None')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(per_page, bool) or not isinstance(per_page, int) or (not 1 <= per_page <= 100):
        raise ValueError('invalid per_page')
    params = {} if category is None else {'category': category}
    response = requests.get('https://api.example.com/v1/articles', params=params, headers={'Accept': 'application/json'})
    if response.status_code != 200:
        raise RuntimeError('article service returned an error')
    try:
        payload = response.json()
    except Exception as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(payload, dict) or not isinstance(payload.get('articles'), list):
        raise ValueError('invalid response shape')
    seen = set()
    articles = []
    for item in payload['articles']:
        if not isinstance(item, dict):
            continue
        fields = ('title', 'url', 'published_at', 'category')
        if any((not isinstance(item.get(field), str) for field in fields)):
            continue
        try:
            stamp = datetime.fromisoformat(item['published_at'].replace('Z', '+00:00'))
        except ValueError:
            continue
        if item['url'] in seen or (category is not None and item['category'] != category):
            continue
        seen.add(item['url'])
        articles.append(({field: item[field] for field in fields}, stamp))
    articles.sort(key=lambda pair: (-pair[1].timestamp(), pair[0]['title']))
    total = len(articles)
    start = (page - 1) * per_page
    selected = [item for item, _ in articles[start:start + per_page]]
    return {'articles': selected, 'page': page, 'per_page': per_page, 'total': total}

