def list_top_runs(api_url: str, project: str, metric: str, min_score: float=0.0, limit: int=10) -> list[dict]:
    if not project or not metric:
        raise ValueError('project and metric are required')
    if isinstance(limit, bool) or not isinstance(limit, int) or limit <= 0:
        raise ValueError('limit must be a positive integer')
    if isinstance(min_score, bool) or not isinstance(min_score, numbers.Real) or (not math.isfinite(min_score)):
        raise ValueError('min_score must be finite')
    url = api_url.rstrip('/') + '/api/v1/runs'
    response = requests.get(url, params={'project': project, 'metric': metric, 'limit': limit}, headers={'Accept': 'application/json'}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError('request failed')
    data = response.json()
    if not isinstance(data, dict) or not isinstance(data.get('runs'), list):
        raise ValueError('invalid response')
    selected = []
    for run in data['runs']:
        if not isinstance(run, dict) or not isinstance(run.get('id'), str):
            continue
        metrics = run.get('metrics')
        value = metrics.get(metric) if isinstance(metrics, dict) else None
        if isinstance(value, bool) or not isinstance(value, numbers.Real) or (not math.isfinite(value)) or (value < min_score):
            continue
        selected.append((float(value), run['id'], {'id': run['id'], 'score': float(value), 'status': run.get('status', 'unknown')}))
    selected.sort(key=lambda item: (-item[0], item[1]))
    return [item[2] for item in selected[:limit]]

