import json
from decimal import Decimal, ROUND_HALF_UP

def encode_billing_entries(entries: list[dict]) -> bytes:
    return json.dumps(entries, separators=(',', ':'), allow_nan=False).encode('utf-8')

def summarize_billing(blob: bytes, page: int=1, page_size: int=20, start_date: str | None=None, end_date: str | None=None) -> dict:
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    if start_date is not None and end_date is not None and (start_date > end_date):
        raise ValueError('invalid date range')
    try:
        entries = json.loads(blob.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(entries, list):
        raise ValueError('invalid payload')
    totals = {}
    for entry in entries:
        try:
            if not isinstance(entry, dict) or not isinstance(entry['id'], int) or (not isinstance(entry['matter'], str)) or (not isinstance(entry['attorney'], str)) or (not isinstance(entry['date'], str)) or (not isinstance(entry['status'], str)):
                raise ValueError
            hours = Decimal(str(entry['hours']))
            rate = Decimal(str(entry['rate']))
            if not hours.is_finite() or not rate.is_finite() or entry['status'] != 'billable':
                continue
            date = entry['date']
            if start_date is not None and date < start_date or (end_date is not None and date > end_date):
                continue
            cents = int((hours * rate * 100).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
            matter = entry['matter']
            if matter not in totals:
                totals[matter] = [0, 0]
            totals[matter][0] += cents
            totals[matter][1] += 1
        except (KeyError, TypeError, ValueError, ArithmeticError) as exc:
            raise ValueError('invalid entry') from exc
    matters = [{'matter': name, 'cents': values[0], 'entry_count': values[1]} for name, values in sorted(totals.items())]
    first = (page - 1) * page_size
    return {'page': page, 'page_size': page_size, 'total_cents': sum((item['cents'] for item in matters)), 'matters': matters[first:first + page_size]}

