import json
from datetime import date

def _state(value):
    if not isinstance(value, dict) or not isinstance(value.get('open'), dict):
        raise ValueError('invalid state')
    return value

def encode_state(state: dict) -> bytes:
    try:
        _state(state)
        return json.dumps(state, sort_keys=True, separators=(',', ':')).encode('utf-8')
    except Exception as exc:
        raise ValueError('invalid state') from exc

def decode_state(blob: bytes) -> dict:
    if not isinstance(blob, bytes):
        raise ValueError('invalid blob')
    try:
        return _state(json.loads(blob.decode('utf-8')))
    except Exception as exc:
        raise ValueError('invalid blob') from exc

def _day(value):
    try:
        return date.fromisoformat(value)
    except Exception as exc:
        raise ValueError('invalid date') from exc

def assess_demurrage(state_blob: bytes, events: list[dict], as_of: str) -> tuple[dict, bytes]:
    state = decode_state(state_blob)
    cutoff = _day(as_of)
    open_items = {k: dict(v) for k, v in state['open'].items()}
    ordered = []
    for e in events:
        if not isinstance(e, dict) or not isinstance(e.get('container'), str) or (not e['container']):
            raise ValueError('invalid event')
        d = _day(e.get('date'))
        if d > cutoff:
            raise ValueError('future event')
        kind = e.get('kind')
        if kind == 'discharge':
            if not isinstance(e.get('free_days'), int) or isinstance(e['free_days'], bool) or e['free_days'] < 0 or (not isinstance(e.get('rate'), int)) or isinstance(e['rate'], bool) or (e['rate'] < 0):
                raise ValueError('invalid event')
        elif kind != 'release':
            raise ValueError('invalid event')
        ordered.append((d, 0 if kind == 'discharge' else 1, e))
    for _, _, e in sorted(ordered, key=lambda x: (x[0], x[1])):
        ident = e['container']
        if e['kind'] == 'discharge':
            if ident in open_items:
                raise ValueError('already open')
            open_items[ident] = {'start': e['date'], 'free_days': e['free_days'], 'rate': e['rate']}
        else:
            if ident not in open_items:
                raise ValueError('not open')
            item = open_items.pop(ident)
            elapsed = (_day(e['date']) - _day(item['start'])).days
            item['_days'] = max(0, elapsed - item['free_days'])
            item['_amount'] = item['_days'] * item['rate']
            open_items[ident] = item
    charges = []
    for ident, item in open_items.items():
        if '_days' in item:
            days, amount = (item.pop('_days'), item.pop('_amount'))
        else:
            days = max(0, (cutoff - _day(item['start'])).days - item['free_days'])
            amount = days * item['rate']
        charges.append({'container': ident, 'days': days, 'amount': amount})
    charges.sort(key=lambda x: x['container'])
    return ({'charges': charges, 'total': sum((x['amount'] for x in charges))}, encode_state({'open': open_items}))

