from datetime import datetime, timezone
import requests

def _time(value):
    try:
        d = datetime.fromisoformat(value[:-1] + '+00:00' if value.endswith('Z') else value)
        if d.tzinfo is None:
            raise ValueError
        return d.astimezone(timezone.utc)
    except Exception as e:
        raise ValueError('invalid timestamp') from e

def _record(item):
    if not isinstance(item, dict) or not all((k in item for k in ('id', 'user', 'start', 'end', 'status'))):
        raise ValueError('invalid reservation')
    a, b = (_time(item['start']), _time(item['end']))
    seconds = (b - a).total_seconds()
    if seconds <= 0 or seconds % 60:
        raise ValueError('invalid interval')
    return {'id': item['id'], 'user': item['user'], 'start': a.strftime('%Y-%m-%dT%H:%M:%SZ'), 'end': b.strftime('%Y-%m-%dT%H:%M:%SZ'), 'status': item['status'], 'duration_minutes': int(seconds // 60)}

def fetch_reservations(api_url: str, instrument: str, start: str, end: str, api_key: str) -> list[dict]:
    r = requests.get(api_url.rstrip('/') + '/reservations', params={'instrument': instrument, 'from': start, 'to': end}, headers={'Authorization': 'Bearer ' + api_key})
    if r.status_code != 200:
        raise RuntimeError('request failed with status ' + str(r.status_code))
    try:
        data = r.json()
        if not isinstance(data, dict) or not isinstance(data['reservations'], list):
            raise ValueError
        rows = [_record(x) for x in data['reservations']]
    except (KeyError, TypeError, ValueError) as e:
        raise ValueError('invalid response') from e
    rows.sort(key=lambda x: (_time(x['start']), str(x['id'])))
    return rows

def build_schedule(reservations: list[dict]) -> dict:
    groups = {}
    confirmed = []
    for raw in reservations:
        row = _record(raw)
        if row['status'] == 'confirmed':
            a, b = (_time(row['start']), _time(row['end']))
            groups.setdefault(row['user'], []).append((a, b))
            confirmed.append((a, str(row['id']), row['id']))
    result = []
    for user, intervals in groups.items():
        intervals.sort()
        merged = []
        for a, b in intervals:
            if merged and a <= merged[-1][1]:
                merged[-1] = (merged[-1][0], max(merged[-1][1], b))
            else:
                merged.append((a, b))
        minutes = sum((int((b - a).total_seconds() // 60) for a, b in merged))
        result.append({'user': user, 'minutes': minutes, 'reservations': len(intervals)})
    result.sort(key=lambda x: (-x['minutes'], x['user']))
    confirmed.sort(key=lambda x: (x[0], x[1]))
    return {'total_minutes': sum((x['minutes'] for x in result)), 'by_user': result, 'reservation_ids': [x[2] for x in confirmed]}

