from datetime import date

def render_archive_page(records: list[dict[str, object]], page: int=1, page_size: int=10) -> str:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    checked = []
    for record in records:
        if not isinstance(record, dict) or not all((k in record for k in ('title', 'date', 'collection', 'pages'))):
            raise ValueError('invalid record')
        title = record['title']
        raw_date = record['date']
        collection = record['collection']
        pages = record['pages']
        if not all((isinstance(value, str) for value in (title, raw_date, collection))):
            raise ValueError('invalid record')
        if not isinstance(pages, int) or isinstance(pages, bool) or pages < 0:
            raise ValueError('invalid record')
        try:
            date.fromisoformat(raw_date)
        except ValueError:
            raise ValueError('invalid record')
        checked.append((title, raw_date, collection, pages))
    checked.sort(key=lambda r: (r[0], r[2]))
    checked.sort(key=lambda r: r[1], reverse=True)
    total = len(checked)
    page_count = (total + page_size - 1) // page_size
    start_index = (page - 1) * page_size
    shown = checked[start_index:start_index + page_size]
    start = start_index + 1 if shown else start_index + 1
    end = start_index + len(shown)
    rows = ''.join((f'<tr><td>{d}</td><td>{t}</td><td>{c}</td><td class="pages">{p}</td></tr>' for t, d, c, p in shown))
    return f'<div class="archive-page"><h1>Historical Archive</h1><p class="summary">Showing {start}-{end} of {total} records (page {page} of {page_count})</p><table><thead><tr><th>Date</th><th>Title</th><th>Collection</th><th>Pages</th></tr></thead><tbody>{rows}</tbody></table><p class="total-pages">Total pages: {page_count}</p></div>'

