import json

def _check(lots):
    if not isinstance(lots, list):
        raise ValueError('invalid lots')
    seen = set()
    for lot in lots:
        if not isinstance(lot, dict) or set(lot) != {'id', 'project', 'vintage', 'tonnes', 'price', 'region', 'status'}:
            raise ValueError('invalid lot')
        if not isinstance(lot['id'], str) or not lot['id'] or lot['id'] in seen:
            raise ValueError('invalid id')
        if not isinstance(lot['project'], str) or not isinstance(lot['region'], str):
            raise ValueError('invalid text')
        if not isinstance(lot['vintage'], int) or isinstance(lot['vintage'], bool):
            raise ValueError('invalid vintage')
        if not isinstance(lot['tonnes'], int) or isinstance(lot['tonnes'], bool) or lot['tonnes'] <= 0:
            raise ValueError('invalid tonnes')
        if not isinstance(lot['price'], (int, float)) or isinstance(lot['price'], bool) or lot['price'] < 0:
            raise ValueError('invalid price')
        if lot['status'] not in ('active', 'retired'):
            raise ValueError('invalid status')
        seen.add(lot['id'])

def encode_registry(lots: list[dict]) -> bytes:
    _check(lots)
    return json.dumps(lots, ensure_ascii=False, separators=(',', ':')).encode('utf-8')

def decode_registry(blob: bytes) -> list[dict]:
    if not isinstance(blob, bytes):
        raise ValueError('invalid blob')
    try:
        value = json.loads(blob.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid blob') from exc
    _check(value)
    return value

def build_report(lots: list[dict], region: str, as_of: int) -> dict:
    _check(lots)
    if not isinstance(region, str) or not isinstance(as_of, int) or isinstance(as_of, bool):
        raise ValueError('invalid arguments')
    groups = {}
    for lot in lots:
        if lot['status'] == 'active' and lot['region'] == region and (lot['vintage'] <= as_of):
            item = groups.setdefault(lot['vintage'], [0, 0.0])
            item[0] += lot['tonnes']
            item[1] += lot['tonnes'] * lot['price']
    rows = [{'vintage': year, 'tonnes': data[0], 'average_price': round(data[1] / data[0], 2)} for year, data in sorted(groups.items())]
    return {'region': region, 'as_of': as_of, 'total_tonnes': sum((x['tonnes'] for x in rows)), 'by_vintage': rows}

def reserve_lots(lots: list[dict], region: str, needed: int) -> tuple[list[dict], int]:
    _check(lots)
    if not isinstance(region, str) or not isinstance(needed, int) or isinstance(needed, bool) or (needed < 0):
        raise ValueError('invalid arguments')
    eligible = sorted((x for x in lots if x['status'] == 'active' and x['region'] == region), key=lambda x: (x['price'], x['vintage'], x['id']))
    out = []
    left = needed
    for lot in eligible:
        if not left:
            break
        amount = min(left, lot['tonnes'])
        out.append({'id': lot['id'], 'tonnes': amount})
        left -= amount
    return (out, left)

