import csv
import io
from datetime import date
from html import escape
_FIELDS = ['id', 'attorney', 'client', 'county', 'status', 'hours', 'deadline']

def parse_assignments(source: str) -> list[dict]:
    rows = list(csv.reader((line for line in source.splitlines() if line.strip())))
    if not rows or [x.strip() for x in rows[0]] != _FIELDS:
        raise ValueError('invalid header')
    result = []
    seen = set()
    for row in rows[1:]:
        if len(row) != 7:
            raise ValueError('invalid row')
        values = [x.strip() for x in row]
        ident, attorney, client, county, status, hours, deadline = values
        if not ident or not attorney or (not client) or (not county) or (status not in {'pending', 'accepted', 'closed'}):
            raise ValueError('invalid value')
        try:
            amount = float(hours)
            date.fromisoformat(deadline)
        except (ValueError, TypeError):
            raise ValueError('invalid number or date')
        if amount < 0 or ident in seen:
            raise ValueError('invalid number or duplicate id')
        seen.add(ident)
        result.append({'id': ident, 'attorney': attorney, 'client': client, 'county': county, 'status': status, 'hours': amount, 'deadline': deadline})
    return result

def summarize_assignments(assignments: list[dict]) -> dict:
    statuses = {'pending': 0, 'accepted': 0, 'closed': 0}
    for item in assignments:
        statuses[item['status']] += 1
    return {'total': len(assignments), 'hours': sum((x['hours'] for x in assignments)), 'statuses': statuses}

def render_report(assignments: list[dict], office: str) -> str:
    summary = summarize_assignments(assignments)
    rows = sorted(assignments, key=lambda x: (x['deadline'], x['attorney'].lower(), x['id']))
    body = ''.join(('<tr><td>{}</td><td>{}</td><td>{}</td><td>{}</td><td>{}</td><td>{:.2f}</td><td>{}</td></tr>'.format(*(escape(str(x)) for x in [r['id'], r['attorney'], r['client'], r['county'], r['status']]), r['hours'], escape(r['deadline'])) for r in rows))
    s = summary['statuses']
    return '<section class="assignment-report"><h1>{} Assignments</h1><p>Total: {} | Hours: {:.2f} | Pending: {} | Accepted: {} | Closed: {}</p><table><thead><tr><th>ID</th><th>Attorney</th><th>Client</th><th>County</th><th>Status</th><th>Hours</th><th>Deadline</th></tr></thead><tbody>{}</tbody></table></section>'.format(escape(office), summary['total'], summary['hours'], s['pending'], s['accepted'], s['closed'], body)

