import json
import math

def _validate_records(records):
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        if not isinstance(record.get('site'), str) or not record['site']:
            raise ValueError('invalid site')
        score = record.get('score')
        savings = record.get('savings_kwh')
        year = record.get('year')
        if isinstance(score, bool) or not isinstance(score, (int, float)) or (not math.isfinite(score)) or (not 0 <= score <= 100):
            raise ValueError('invalid score')
        if isinstance(savings, bool) or not isinstance(savings, (int, float)) or (not math.isfinite(savings)) or (savings < 0):
            raise ValueError('invalid savings')
        if isinstance(year, bool) or not isinstance(year, int) or (not 2000 <= year <= 2100):
            raise ValueError('invalid year')

def encode_audit_state(records: list[dict]) -> bytes:
    _validate_records(records)
    return json.dumps(records, separators=(',', ':')).encode('utf-8')

def summarize_audits(payload: bytes, min_score: float=0.0, offset: int=0, limit: int=10) -> dict:
    if isinstance(min_score, bool) or not isinstance(min_score, (int, float)) or (not math.isfinite(min_score)) or (not 0 <= min_score <= 100):
        raise ValueError('invalid minimum score')
    if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
        raise ValueError('invalid offset')
    if isinstance(limit, bool) or not isinstance(limit, int) or limit <= 0:
        raise ValueError('invalid limit')
    try:
        records = json.loads(payload.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    _validate_records(records)
    selected = [r for r in records if r['score'] >= min_score]
    grouped = {}
    for record in selected:
        group = grouped.setdefault(record['site'], {'scores': [], 'savings': 0.0})
        group['scores'].append(record['score'])
        group['savings'] += record['savings_kwh']
    groups = []
    for site, values in grouped.items():
        groups.append({'site': site, 'audits': len(values['scores']), 'total_savings_kwh': round(values['savings'], 2), 'average_score': round(sum(values['scores']) / len(values['scores']), 2)})
    groups.sort(key=lambda g: (-g['total_savings_kwh'], g['site']))
    return {'audits': len(selected), 'total_savings_kwh': round(sum((r['savings_kwh'] for r in selected)), 2), 'groups': groups[offset:offset + limit]}

