import json
from datetime import date, timedelta
_MATERIALS = {'paper': 0.8, 'glass': 0.6, 'plastic': 0.3}

def _check(records):
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    seen = set()
    for r in records:
        if not isinstance(r, dict):
            raise ValueError('record must be a dictionary')
        for key in ('id', 'date', 'material', 'weight_kg', 'recycled_pct'):
            if key not in r:
                raise ValueError('missing field')
        if not isinstance(r['id'], str) or not r['id'] or r['id'] in seen:
            raise ValueError('invalid id')
        seen.add(r['id'])
        try:
            date.fromisoformat(r['date'])
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        if r['material'] not in _MATERIALS:
            raise ValueError('invalid material')
        if isinstance(r['weight_kg'], bool) or not isinstance(r['weight_kg'], (int, float)) or r['weight_kg'] <= 0:
            raise ValueError('invalid weight')
        if isinstance(r['recycled_pct'], bool) or not isinstance(r['recycled_pct'], (int, float)) or (not 0 <= r['recycled_pct'] <= 1):
            raise ValueError('invalid percentage')
    return records

def encode_state(records):
    _check(records)
    return json.dumps(records, sort_keys=True, separators=(',', ':')).encode('utf-8')

def decode_state(blob):
    if not isinstance(blob, (bytes, bytearray)):
        raise TypeError('blob must be bytes')
    try:
        value = json.loads(bytes(blob).decode('utf-8'))
    except (ValueError, UnicodeError):
        raise ValueError('invalid state')
    return _check(value)

def compliance_report(records, window_days=30):
    _check(records)
    if isinstance(window_days, bool) or not isinstance(window_days, int) or window_days < 0:
        raise ValueError('invalid window')
    if not records:
        return {'end_date': None, 'start_date': None, 'materials': [], 'overall_compliant': True}
    end = max((date.fromisoformat(r['date']) for r in records))
    start = end - timedelta(days=window_days)
    groups = {}
    for r in records:
        d = date.fromisoformat(r['date'])
        if start <= d <= end:
            g = groups.setdefault(r['material'], [0.0, 0.0])
            g[0] += r['weight_kg']
            g[1] += r['weight_kg'] * r['recycled_pct']
    rows = []
    for material, (total, recycled) in groups.items():
        pct = recycled / total
        rows.append({'material': material, 'total_weight_kg': round(total, 3), 'recycled_weight_kg': round(recycled, 3), 'weighted_recycled_pct': round(pct, 4), 'compliant': pct >= _MATERIALS[material]})
    rows.sort(key=lambda x: (-x['total_weight_kg'], x['material']))
    return {'end_date': end.isoformat(), 'start_date': start.isoformat(), 'materials': rows, 'overall_compliant': all((x['compliant'] for x in rows))}

