    if not isinstance(title, str) or not title:
        raise ValueError('invalid title')
    rows = summarize_shipments(records, period)
    distance = sum((x['distance_km'] for x in rows))
    fuel = sum((x['fuel_l'] for x in rows))
    co2 = sum((x['co2_kg'] for x in rows))
    count = sum((x['shipments'] for x in rows))
