    return '<div class="carbon-report"><h1>{} - {}</h1><table><thead><tr><th>Route</th><th>Mode</th><th>Distance (km)</th><th>Fuel (l)</th><th>CO2 (kg)</th><th>Shipments</th></tr></thead><tbody>{}</tbody><tfoot><tr><th>Total</th><td colspan="2">{:.2f}</td><td>{:.2f}</td><td>{:.2f}</td><td>{}</td></tr></tfoot></table></div>'.format(html.escape(title, quote=True), html.escape(period, quote=True), body, distance, fuel, co2, count)

