import html
import math
from datetime import date

def _fields(line):
    fields, current, escaped = ([], [], False)
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current).strip())
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('dangling escape')
    fields.append(''.join(current).strip())
    return fields

def parse_samples(text: str) -> list[dict]:
    result = []
    for raw in text.splitlines():
        if not raw.strip() or raw.lstrip().startswith('#'):
            continue
        parts = _fields(raw)
        if len(parts) != 5 or not parts[0] or (not parts[4]):
            raise ValueError('invalid record')
        try:
            date.fromisoformat(parts[1])
            depth = float(parts[2])
            value = float(parts[3])
        except ValueError as exc:
            raise ValueError('invalid record') from exc
        if depth < 0 or not math.isfinite(depth) or (not math.isfinite(value)):
            raise ValueError('invalid number')
        result.append({'site': parts[0], 'date': parts[1], 'depth': depth, 'value': value, 'unit': parts[4]})
    return result

def aggregate_samples(samples: list[dict]) -> list[dict]:
    if not samples:
        raise ValueError('no samples')
    groups = {}
    for item in samples:
        site = item['site']
        group = groups.setdefault(site, [])
        if group and group[0]['unit'] != item['unit']:
            raise ValueError('inconsistent units')
        group.append(item)
    result = []
    for site in sorted(groups):
        rows = groups[site]
        latest = max(enumerate(rows), key=lambda pair: (pair[1]['date'], pair[0]))[1]
        result.append({'site': site, 'count': len(rows), 'mean_value': sum((x['value'] for x in rows)) / len(rows), 'min_depth': min((x['depth'] for x in rows)), 'max_depth': max((x['depth'] for x in rows)), 'latest_date': latest['date'], 'latest_value': latest['value'], 'unit': latest['unit']})
    return result

def render_report(summary: list[dict]) -> str:
    required = ('site', 'count', 'mean_value', 'min_depth', 'max_depth', 'latest_date', 'latest_value', 'unit')
    rows = []
    for item in summary:
        if any((key not in item for key in required)):
            raise ValueError('missing summary field')
        site = html.escape(str(item['site']), quote=True)
        unit = html.escape(str(item['unit']), quote=True)
        latest_date = html.escape(str(item['latest_date']), quote=True)
        rows.append(f"<tr><td>{site}</td><td>{item['count']}</td><td>{item['mean_value']:.2f}</td><td>{item['min_depth']:.2f}–{item['max_depth']:.2f}</td><td>{latest_date} {item['latest_value']:.2f} {unit}</td></tr>\n")
    return '<section class="survey-report">\n<h1>Geological Survey Summary</h1>\n<table>\n<thead><tr><th>Site</th><th>Samples</th><th>Mean Value</th><th>Depth Range</th><th>Latest</th></tr></thead>\n<tbody>\n' + ''.join(rows) + '</tbody>\n</table>\n</section>'

