def summarize_viewer_sessions(channel: str, minimum_watch_minutes: float=0, page: int=1, page_size: int=10) -> list[dict]:
    if not isinstance(channel, str) or not channel:
        raise ValueError('channel must be non-empty')
    if isinstance(minimum_watch_minutes, bool) or not isinstance(minimum_watch_minutes, Real) or minimum_watch_minutes < 0:
        raise ValueError('minimum_watch_minutes must be non-negative')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('page must be positive')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('page_size must be positive')
    url = f'https://api.stream.example/v1/channels/{channel}/sessions'
    response = requests.get(url, params={'channel': channel}, headers={'Accept': 'application/json'}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError('session service returned an error')
    sessions = response.json()['sessions']
    grouped = {}
    for session in sessions:
        minutes = session['watch_minutes']
        if minutes < minimum_watch_minutes:
            continue
        viewer = session['viewer_id']
        item = grouped.setdefault(viewer, {'viewer_id': viewer, 'sessions': 0, 'total': 0.0, 'last_seen': ''})
        item['sessions'] += 1
        item['total'] += minutes
        if session['ended_at'] > item['last_seen']:
            item['last_seen'] = session['ended_at']
    result = [{'viewer_id': x['viewer_id'], 'sessions': x['sessions'], 'total_watch_minutes': round(x['total'], 2), 'last_seen': x['last_seen']} for x in grouped.values()]
    result.sort(key=lambda x: (-x['total_watch_minutes'], x['viewer_id']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

