from datetime import date
from decimal import Decimal, InvalidOperation
import html

def _split_fields(line):
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    fields.append(''.join(current))
    return fields

def parse_lease_records(text: str) -> list[dict[str, object]]:
    result = []
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = _split_fields(raw)
        if len(fields) != 5 or not fields[0]:
            raise ValueError('invalid record')
        try:
            start = date.fromisoformat(fields[1])
            end = date.fromisoformat(fields[2])
            amount = Decimal(fields[3])
        except (ValueError, InvalidOperation):
            raise ValueError('invalid record')
        if end <= start or amount < 0 or fields[4] not in {'active', 'pending', 'ended'}:
            raise ValueError('invalid record')
        result.append({'tenant': fields[0], 'start': start, 'end': end, 'monthly_amount': amount, 'status': fields[4]})
    return result

def summarize_active_leases(records: list[dict[str, object]], as_of: str) -> list[dict[str, object]]:
    try:
        day = date.fromisoformat(as_of)
    except ValueError:
        raise ValueError('invalid date')
    groups = {}
    for record in records:
        if record['status'] == 'active' and record['start'] <= day < record['end']:
            tenant = record['tenant']
            if tenant not in groups:
                groups[tenant] = {'tenant': tenant, 'lease_count': 0, 'monthly_total': Decimal('0')}
            groups[tenant]['lease_count'] += 1
            groups[tenant]['monthly_total'] += record['monthly_amount']
    return sorted(groups.values(), key=lambda x: (-x['monthly_total'], x['tenant']))

