    if not body:
        body.append('<tr class="empty"><td colspan="3">No active leases</td></tr>')
    return '<table class="lease-report"><thead><tr><th>Tenant</th><th>Active leases</th><th>Monthly total</th></tr></thead><tbody>' + ''.join(body) + '</tbody></table>'

