import json
from copy import deepcopy
RATES = {'insulation': 12, 'hvac': 9, 'solar': 15}

def encode_state(state: dict) -> bytes:
    if not isinstance(state, dict):
        raise ValueError('invalid state')
    return json.dumps(state, sort_keys=True, separators=(',', ':')).encode('utf-8')

def decode_state(blob: bytes) -> dict:
    try:
        value = json.loads(blob.decode('utf-8'))
        if not isinstance(value, dict) or not isinstance(value.get('seen'), list) or (not isinstance(value.get('customers'), dict)):
            raise ValueError('invalid state')
        return value
    except (ValueError, TypeError, UnicodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid state') from exc

def process_audits(records: list[dict], state_blob: bytes | None=None) -> tuple[dict, bytes]:
    state = {'seen': [], 'customers': {}} if state_blob is None else decode_state(state_blob)
    seen = list(state['seen'])
    customers = deepcopy(state['customers'])
    seen_set = set(seen)
    accepted, ignored = ([], [])
    for record in records:
        if not isinstance(record, dict) or not all((k in record for k in ('id', 'customer', 'measure', 'savings_kwh', 'eligible', 'date'))):
            raise ValueError('invalid record')
        rid, customer, measure, savings, eligible, date = (record[k] for k in ('id', 'customer', 'measure', 'savings_kwh', 'eligible', 'date'))
        if not isinstance(rid, str) or not rid or (not isinstance(customer, str)) or (not customer) or (measure not in RATES) or (not isinstance(savings, int)) or isinstance(savings, bool) or (savings < 0) or (not isinstance(eligible, bool)) or (not isinstance(date, str)) or (len(date) != 10) or (date[4] != '-') or (date[7] != '-') or (not date.replace('-', '').isdigit()):
            raise ValueError('invalid record')
        if rid in seen_set:
            ignored.append(rid)
            continue
        seen.append(rid)
        seen_set.add(rid)
        accepted.append(rid)
        if eligible:
            item = customers.setdefault(customer, {'savings_kwh': 0, 'rebate_cents': 0, 'audits': 0})
            item['savings_kwh'] += savings
            item['rebate_cents'] += savings * RATES[measure] + (200 if savings >= 1000 else 0)
            item['audits'] += 1
    rows = [{'name': n, **v} for n, v in customers.items() if v['audits']]
    rows.sort(key=lambda x: (-x['rebate_cents'], x['name']))
    report = {'total_cents': sum((x['rebate_cents'] for x in rows)), 'customers': rows, 'accepted_ids': accepted, 'ignored_ids': ignored}
    return (report, encode_state({'seen': seen, 'customers': customers}))

