        except (InvalidOperation, ValueError):
            continue
        if not value.is_finite() or value < 0:
            continue
        if vendor not in groups:
            groups[vendor] = [0, Decimal('0')]
        groups[vendor][0] += 1
        groups[vendor][1] += value
