import json

def _validate(items):
    if not isinstance(items, list):
        raise ValueError('invalid state')
    for item in items:
        if not isinstance(item, dict):
            raise ValueError('invalid invoice')
        for key in ('id', 'vendor', 'amount', 'currency', 'status', 'approvals'):
            if key not in item:
                raise ValueError('invalid invoice')
        if not all((isinstance(item[k], str) and item[k] for k in ('id', 'vendor', 'currency'))):
            raise ValueError('invalid invoice')
        if isinstance(item['amount'], bool) or not isinstance(item['amount'], (int, float)) or item['amount'] < 0:
            raise ValueError('invalid invoice')
        if item['status'] not in ('pending', 'approved', 'rejected') or not isinstance(item['approvals'], list):
            raise ValueError('invalid invoice')
        for approval in item['approvals']:
            if not isinstance(approval, dict) or approval.get('decision') != 'approve' or (not isinstance(approval.get('actor'), str)) or (not approval['actor']):
                raise ValueError('invalid approval')

def pack_state(invoices: list[dict]) -> bytes:
    value = copy.deepcopy(invoices)
    _validate(value)
    return json.dumps(value, separators=(',', ':'), sort_keys=True).encode('utf-8')

def unpack_state(blob: bytes | str) -> list[dict]:
    try:
        value = json.loads(blob.decode('utf-8') if isinstance(blob, bytes) else blob)
        _validate(value)
        return copy.deepcopy(value)
    except (ValueError, TypeError, UnicodeError, json.JSONDecodeError):
        raise ValueError('invalid state')

def apply_events(blob: bytes | str, events: list[dict]) -> bytes:
    items = unpack_state(blob)
    if not isinstance(events, list):
        raise ValueError('invalid events')
    by_id = {item['id']: item for item in items}
    for event in events:
        if not isinstance(event, dict) or not isinstance(event.get('invoice_id'), str) or (not isinstance(event.get('actor'), str)) or (not event['actor']) or (event.get('decision') not in ('approve', 'reject')):
            raise ValueError('invalid event')
        if event['invoice_id'] not in by_id:
            raise ValueError('unknown invoice')
        item = by_id[event['invoice_id']]
        if item['status'] != 'pending':
            continue
        if event['decision'] == 'reject':
            item['status'] = 'rejected'
            continue
        if any((a['actor'] == event['actor'] for a in item['approvals'])):
            continue
        item['approvals'].append({'actor': event['actor'], 'decision': 'approve'})
        needed = 1 if item['amount'] <= 1000 else 2
        if len({a['actor'] for a in item['approvals']}) >= needed:
            item['status'] = 'approved'
    return pack_state(items)

def approval_summary(blob: bytes | str) -> list[dict]:
    items = unpack_state(blob)
    rank = {'pending': 0, 'rejected': 1, 'approved': 2}
    result = [{'id': x['id'], 'vendor': x['vendor'], 'amount': x['amount'], 'currency': x['currency'], 'status': x['status'], 'approval_count': len({a['actor'] for a in x['approvals']})} for x in items]
    return sorted(result, key=lambda x: (rank[x['status']], -x['amount'], x['vendor'], x['id']))

