import requests

def fetch_requests(base_url: str, tenant_id: str, api_token: str, start: str | None=None, end: str | None=None) -> list[dict]:
    url = base_url.rstrip('/') + f'/v1/tenants/{tenant_id}/maintenance-requests'
    params = {}
    if start is not None:
        params['start'] = start
    if end is not None:
        params['end'] = end
    headers = {'Authorization': f'Bearer {api_token}', 'Accept': 'application/json'}
    response = requests.get(url, params=params, headers=headers, timeout=10)
    if response.status_code != 200:
        raise ValueError(f'request failed: {response.status_code}')
    body = response.json()
    if not isinstance(body, dict) or not isinstance(body.get('requests'), list):
        raise ValueError('invalid response')
    return body['requests']

def summarize_requests(records: list[dict]) -> dict:
    active = {'open', 'in_progress'}
    names = ('high', 'medium', 'low', 'unknown')
    groups = {}
    total = 0
    total_hours = 0.0
    for record in records:
        if record['status'] not in active:
            continue
        unit = record['unit']
        priority = record['priority'] if record['priority'] in names else 'unknown'
        if unit not in groups:
            groups[unit] = {'count': 0, 'hours': 0.0, 'priorities': {name: 0 for name in names}, 'oldest': record['created_at']}
        group = groups[unit]
        hours = float(record['estimated_hours'])
        total += 1
        total_hours += hours
        group['count'] += 1
        group['hours'] += hours
        group['priorities'][priority] += 1
        group['oldest'] = min(group['oldest'], record['created_at'])
    by_unit = []
    for unit in sorted(groups):
        group = groups[unit]
        by_unit.append({'unit': unit, 'count': group['count'], 'hours': round(group['hours'], 2), 'priorities': group['priorities'], 'oldest': group['oldest']})
    return {'total_count': total, 'total_hours': round(total_hours, 2), 'by_unit': by_unit}

def load_and_summarize(base_url: str, tenant_id: str, api_token: str, start: str | None=None, end: str | None=None) -> dict:
    return summarize_requests(fetch_requests(base_url, tenant_id, api_token, start, end))

