import json
import html

def parse_records(text: str) -> list[dict]:
    try:
        value = json.loads(text)
    except Exception as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(value, list):
        raise ValueError('top level must be a list')
    result = []
    allowed = {'id', 'image', 'status', 'size_mb', 'ports'}
    for item in value:
        if not isinstance(item, dict) or set(item) != allowed:
            raise ValueError('invalid record')
        if not isinstance(item['id'], str) or not item['id'] or (not isinstance(item['image'], str)) or (not item['image']):
            raise ValueError('invalid text')
        if item['status'] not in {'running', 'stopped', 'exited'}:
            raise ValueError('invalid status')
        if isinstance(item['size_mb'], bool) or not isinstance(item['size_mb'], (int, float)) or item['size_mb'] < 0:
            raise ValueError('invalid size')
        if not isinstance(item['ports'], list):
            raise ValueError('invalid ports')
        ports = []
        for port in item['ports']:
            if not isinstance(port, dict) or set(port) - {'host', 'container', 'protocol'} or (not {'host', 'container'} <= set(port)):
                raise ValueError('invalid port')
            protocol = port.get('protocol', 'tcp')
            if protocol not in {'tcp', 'udp'} or any((isinstance(port[k], bool) or not isinstance(port[k], int) or (not 1 <= port[k] <= 65535) for k in ('host', 'container'))):
                raise ValueError('invalid port')
            ports.append({'host': port['host'], 'container': port['container'], 'protocol': protocol})
        result.append({'id': item['id'], 'image': item['image'], 'status': item['status'], 'size_mb': item['size_mb'], 'ports': ports})
    return result

def render_report(records: list[dict], title: str='Container Inspection', sort_by: str='status') -> str:
    if sort_by not in {'status', 'size', 'id'}:
        raise ValueError('invalid sort field')
    rank = {'running': 0, 'exited': 1, 'stopped': 2}
    if sort_by == 'status':
        ordered = sorted(records, key=lambda r: (rank[r['status']], r['id'].casefold()))
    elif sort_by == 'size':
        ordered = sorted(records, key=lambda r: (-r['size_mb'], r['id'].casefold()))
    else:
        ordered = sorted(records, key=lambda r: r['id'].casefold())
    counts = {s: sum((r['status'] == s for r in records)) for s in ('running', 'stopped', 'exited')}
    esc = lambda x: html.escape(str(x), quote=True)
    rows = []
    for r in ordered:
        ports = sorted(r['ports'], key=lambda p: (p['host'], p['container'], p['protocol']))
        shown = ', '.join((f"{esc(p['host'])}:{esc(p['container'])}/{esc(p['protocol'])}" for p in ports))
        rows.append(f"""<tr><td>{esc(r['id'])}</td><td>{esc(r['image'])}</td><td>{esc(r['status'])}</td><td>{r['size_mb']:.2f}</td><td class="ports">{shown}</td></tr>""")
    body = ''.join(rows)
    summary = f"containers: {len(records)}; total size: {sum((r['size_mb'] for r in records)):.2f} MB; running: {counts['running']}; stopped: {counts['stopped']}; exited: {counts['exited']}"
    return f'<section class="inspection">\n<h1>{esc(title)}</h1>\n<div class="summary">{summary}</div>\n<table><thead><tr><th>ID</th><th>Image</th><th>Status</th><th>Size (MB)</th><th>Ports</th></tr></thead><tbody>{body}</tbody></table>\n</section>'

