import json

def _integer(value):
    return isinstance(value, int) and (not isinstance(value, bool))

def summarize_events(events, start, end):
    if not _integer(start) or not _integer(end) or start > end:
        raise ValueError('invalid interval')
    try:
        iterator = iter(events)
    except Exception as exc:
        raise ValueError('invalid events') from exc
    groups = {}
    for event in iterator:
        if not isinstance(event, dict) or set(event) != {'ts', 'user', 'action', 'value'}:
            raise ValueError('invalid event')
        ts, user, action, value = (event['ts'], event['user'], event['action'], event['value'])
        if not _integer(ts) or not _integer(value) or value < 0 or (not isinstance(user, str)) or (not user) or (not isinstance(action, str)) or (not action):
            raise ValueError('invalid event')
        if start <= ts < end:
            item = groups.setdefault(user, {'total': 0, 'actions': {}})
            item['total'] += value
            item['actions'][action] = item['actions'].get(action, 0) + value
    users = [{'user': u, 'total': x['total'], 'actions': {k: x['actions'][k] for k in sorted(x['actions'])}} for u, x in groups.items()]
    users.sort(key=lambda x: (-x['total'], x['user']))
    return {'start': start, 'end': end, 'users': users}

def _validate(s):
    if not isinstance(s, dict) or set(s) != {'start', 'end', 'users'} or (not _integer(s['start'])) or (not _integer(s['end'])) or (s['start'] > s['end']) or (not isinstance(s['users'], list)):
        raise ValueError('invalid snapshot')
    previous = None
    for x in s['users']:
        if not isinstance(x, dict) or set(x) != {'user', 'total', 'actions'}:
            raise ValueError('invalid snapshot')
        u, t, a = (x['user'], x['total'], x['actions'])
        if not isinstance(u, str) or not u or (not _integer(t)) or (t < 0) or (not isinstance(a, dict)) or (list(a) != sorted(a)) or any((not isinstance(k, str) or not k or (not _integer(v)) or (v < 0) for k, v in a.items())) or (sum(a.values()) != t):
            raise ValueError('invalid snapshot')
        key = (-t, u)
        if previous is not None and key < previous:
            raise ValueError('invalid snapshot')
        previous = key

def encode_snapshot(snapshot):
    _validate(snapshot)
    return json.dumps(snapshot, ensure_ascii=False, separators=(',', ':')).encode('utf-8')

def decode_snapshot(blob):
    if not isinstance(blob, (bytes, str)):
        raise ValueError('invalid blob')
    try:
        value = json.loads(blob.decode('utf-8') if isinstance(blob, bytes) else blob)
    except Exception as exc:
        raise ValueError('invalid blob') from exc
    _validate(value)
    return value

