import csv
import io

def parse_queue(data: str) -> list[dict]:
    if not data:
        raise ValueError('empty input')
    rows = list(csv.reader(io.StringIO(data)))
    header = ['id', 'user', 'score', 'labels', 'minutes']
    if not rows or rows[0] != header:
        raise ValueError('invalid header')
    result = []
    seen = set()
    for row in rows[1:]:
        if len(row) != 5:
            raise ValueError('invalid row')
        ident, user, raw_score, raw_labels, raw_minutes = [x.strip() for x in row]
        if not ident or not user or ident in seen:
            raise ValueError('invalid identity')
        try:
            score = float(raw_score)
            minutes = int(raw_minutes)
        except (TypeError, ValueError):
            raise ValueError('invalid number')
        if not 0 <= score <= 1 or minutes < 0:
            raise ValueError('number out of range')
        labels = [x.strip() for x in raw_labels.split(';') if x.strip()]
        seen.add(ident)
        result.append({'id': ident, 'user': user, 'score': score, 'labels': labels, 'minutes': minutes})
    return result

def rank_queue(items: list[dict], limit: int=0) -> list[dict]:
    if isinstance(limit, bool) or not isinstance(limit, int) or limit < 0:
        raise ValueError('invalid limit')
    result = []
    for item in items:
        copy = dict(item)
        copy['labels'] = list(item['labels'])
        copy['status'] = 'critical' if item['score'] >= 0.8 else 'review' if item['score'] >= 0.5 else 'low'
        result.append(copy)
    result.sort(key=lambda x: (-x['score'], -x['minutes'], -len(x['labels']), x['id']))
    return result if limit == 0 else result[:limit]

