        raise ValueError('invalid date')
    return value

def parse_recall_feed(text: str) -> list[dict]:
    if not isinstance(text, str):
        raise ValueError('feed must be text')
    rows = list(csv.reader(io.StringIO(text), skipinitialspace=False))
    while rows and (not any((cell.strip() for cell in rows[0]))):
        rows.pop(0)
    if not rows or [x.strip() for x in rows[0]] != HEADER:
        raise ValueError('bad header')
    result = []
    for row in rows[1:]:
        if not any((cell.strip() for cell in row)):
            continue
        if len(row) != 6:
            raise ValueError('bad row')
        supplier, product, lot, quantity, recalled_on, reason = [x.strip() for x in row]
        if not supplier or not product or (not lot) or (not reason):
            raise ValueError('empty field')
        try:
            quantity = int(quantity)
        except ValueError:
            raise ValueError('bad quantity')
        if quantity <= 0 or str(quantity) != row[3].strip():
            raise ValueError('bad quantity')
        _valid_date(recalled_on)
        result.append({'supplier': supplier, 'product': product, 'lot': lot, 'quantity': quantity, 'recalled_on': recalled_on, 'reason': reason})
