import requests

def fetch_documents(api_url: str, collection: str, limit: int=50) -> list[dict]:
    if limit < 1:
        raise ValueError('limit must be positive')
    url = api_url.rstrip('/') + '/collections/' + collection + '/documents'
    items = []
    cursor = None
    seen = set()
    while True:
        params = {'limit': limit}
        if cursor:
            if cursor in seen:
                raise ValueError('repeated cursor')
            seen.add(cursor)
            params['cursor'] = cursor
        reply = requests.get(url, params=params, headers={'Accept': 'application/json'})
        if reply.status_code != 200:
            raise RuntimeError('document request failed')
        data = reply.json()
        if not isinstance(data, dict) or not isinstance(data.get('items'), list):
            raise ValueError('invalid response')
        items.extend(data['items'])
        cursor = data.get('next_cursor')
        if not cursor:
            return items

def build_year_index(documents: list[dict], first_year: int, last_year: int) -> list[dict]:
    if first_year > last_year:
        raise ValueError('invalid year range')
    totals = {}
    for document in documents:
        events = document.get('events')
        if not isinstance(events, list):
            continue
        for event in events:
            year = int(event['year'])
            if year < first_year or year > last_year:
                continue
            kind = str(event.get('kind', ''))
            if not kind:
                continue
            count = int(event.get('count', 1))
            if count < 0:
                raise ValueError('negative count')
            totals.setdefault(year, {})[kind] = totals.setdefault(year, {}).get(kind, 0) + count
    result = []
    for year in sorted(totals):
        kinds = [{'kind': k, 'count': v} for k, v in totals[year].items()]
        kinds.sort(key=lambda x: (-x['count'], x['kind']))
        result.append({'year': year, 'kinds': kinds})
    return result

