import requests

def get_border_wait_time(port_code: str, direction: str='northbound', api_key: str | None=None) -> dict[str, object]:
    code = port_code.strip()
    if not 2 <= len(code) <= 12 or not all((c.isalnum() or c == '-' for c in code)):
        raise ValueError('invalid port code')
    code = code.upper()
    travel_direction = direction.strip().lower()
    if travel_direction not in {'northbound', 'southbound'}:
        raise ValueError('invalid direction')
    headers = {'Accept': 'application/json'}
    if api_key is not None:
        headers['Authorization'] = 'Bearer ' + api_key
    response = requests.get('https://api.borderdata.example/v1/wait-times', params={'portCode': code, 'direction': travel_direction}, headers=headers, verify=True)
    if response.status_code != 200:
        raise RuntimeError(f'border data request failed with status {response.status_code}')
    data = response.json()
    return {'port_code': code, 'direction': travel_direction, 'wait_minutes': int(data['waitMinutes']), 'status': data['status'], 'updated_at': data['updatedAt']}

