def render_notification_settings(user: str, preferences: list[dict], history: list[dict]) -> str:
    if not isinstance(user, str):
        raise TypeError('user')
    if not isinstance(preferences, list) or not isinstance(history, list):
        raise TypeError('collections')
    allowed = {'immediate', 'daily', 'weekly'}
    seen = set()
    prefs = []
    for item in preferences:
        if not isinstance(item, dict):
            raise TypeError('preference')
        for key in ('channel', 'event', 'enabled', 'frequency'):
            if key not in item:
                raise ValueError('missing field')
