            raise ValueError('name')
        if not isinstance(item['enabled'], bool) or not isinstance(item['frequency'], str) or item['frequency'] not in allowed:
            raise ValueError('preference value')
        pair = (item['channel'], item['event'])
        if pair in seen:
            raise ValueError('duplicate')
        seen.add(pair)
        prefs.append(item)
    parsed = []
    for item in history:
        if not isinstance(item, dict):
            raise TypeError('history')
        for key in ('channel', 'event', 'at'):
            if key not in item:
                raise ValueError('missing field')
        if not isinstance(item['channel'], str) or not isinstance(item['event'], str) or (not isinstance(item['at'], str)) or (not item['at'].endswith('Z')):
            raise ValueError('history value')
