        except ValueError:
            raise ValueError('timestamp')
        parsed.append((item['channel'], item['event'], stamp))
    newest = max((x[2] for x in parsed), default=None)
    counts = {pair: 0 for pair in seen}
    if newest is not None:
        cutoff = newest - timedelta(days=7)
        for channel, event, stamp in parsed:
            if (channel, event) in counts and stamp >= cutoff:
                counts[channel, event] += 1
    esc = lambda value: html.escape(str(value), quote=True)
    rows = []
    for item in prefs:
        pair = (item['channel'], item['event'])
        status = 'Enabled' if item['enabled'] else 'Disabled'
        rows.append('<tr><td>%s</td><td>%s</td><td>%s</td><td>%s</td><td>%d</td></tr>' % (esc(item['channel']), esc(item['event']), esc(item['frequency']), status, counts[pair]))
