import json

def encode_state(state: dict) -> bytes:
    if not isinstance(state, dict) or not isinstance(state.get('teams'), list) or (not isinstance(state.get('reports'), list)):
        raise ValueError('invalid state')
    try:
        return json.dumps(state, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode('utf-8')
    except (TypeError, ValueError, UnicodeError) as exc:
        raise ValueError('invalid state') from exc

def decode_state(blob: bytes) -> dict:
    if not isinstance(blob, (bytes, bytearray)):
        raise ValueError('invalid blob')
    try:
        value = json.loads(bytes(blob).decode('utf-8'))
    except (TypeError, ValueError, UnicodeError) as exc:
        raise ValueError('invalid blob') from exc
    if not isinstance(value, dict) or not isinstance(value.get('teams'), list) or (not isinstance(value.get('reports'), list)):
        raise ValueError('invalid state')
    return value

def ingest_reports(blob: bytes, reports: list[dict], now: int) -> bytes:
    state = decode_state(blob)
    if not isinstance(reports, list):
        raise ValueError('invalid reports')
    existing = {r.get('id') for r in state['reports']}
    added = list(state['reports'])
    for report in reports:
        if not isinstance(report, dict) or not isinstance(report.get('id'), str) or (not isinstance(report.get('skill'), str)) or (type(report.get('priority')) is not int) or (not 1 <= report['priority'] <= 5) or (type(report.get('eta')) is not int) or (type(report.get('received')) is not int):
            raise ValueError('invalid report')
        if report['id'] not in existing:
            existing.add(report['id'])
            if now - 3600 <= report['received'] <= now:
                added.append(dict(report))
    added.sort(key=lambda r: (-r['priority'], r['eta'], r['id']))
    return encode_state({'teams': state['teams'], 'reports': added})

def plan_dispatch(blob: bytes, now: int) -> list[dict]:
    state = decode_state(blob)
    reports = [r for r in state['reports'] if r['received'] <= now and now - r['received'] <= 3600]
    reports.sort(key=lambda r: (-r['priority'], r['eta'], r['id']))
    counts = {t['id']: 0 for t in state['teams']}
    result = []
    for report in reports:
        choices = [t for t in state['teams'] if report['skill'] in t['skills'] and counts[t['id']] < t['capacity']]
        if choices:
            team = min(choices, key=lambda t: (-len(set(t['skills'])), counts[t['id']], t['id']))
            counts[team['id']] += 1
            result.append({'report_id': report['id'], 'team_id': team['id']})
    return result

