            if not isinstance(record, dict):
                raise ValueError
            for key in ('id', 'title', 'amount', 'status'):
                if key not in record:
                    raise ValueError
            amount = float(record['amount'])
            if record['status'] == 'open' and amount >= min_amount:
                selected.append({'id': record['id'], 'title': record['title'], 'amount': amount})
    except (KeyError, TypeError, ValueError, OverflowError):
        raise ValueError('invalid grant response')
    selected.sort(key=lambda item: (-item['amount'], str(item['id'])))
