def encode_checkpoint(state: dict) -> bytes:
    return json.dumps(state, separators=(',', ':'), sort_keys=True).encode('utf-8')

def decode_checkpoint(blob: bytes) -> dict:
    try:
        value = json.loads(blob.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid checkpoint') from exc
    if not isinstance(value, dict):
        raise ValueError('checkpoint must be an object')
    return value

def evaluate_candidates(candidates: list[dict], checkpoint: bytes, as_of: str) -> tuple[list[dict], bytes]:
    try:
        cutoff = date.fromisoformat(as_of)
    except Exception as exc:
        raise ValueError('invalid date') from exc
    state = decode_checkpoint(checkpoint)
    last = state.get('last_reviewed', {})
    attempts = state.get('attempts', {})
    if not isinstance(last, dict) or not isinstance(attempts, dict):
        raise ValueError('invalid checkpoint fields')
    for key, value in attempts.items():
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            raise ValueError('invalid attempts')
    seen = set()
    rows = []
    priority = {'fail': 0, 'pending': 1, 'pass': 2}
    for candidate in candidates:
        if not isinstance(candidate, dict) or not all((k in candidate for k in ('id', 'name', 'screenings'))):
            raise ValueError('invalid candidate')
        cid, name, screenings = (candidate['id'], candidate['name'], candidate['screenings'])
        if not isinstance(cid, str) or cid in seen or (not isinstance(name, str)) or (not isinstance(screenings, list)):
            raise ValueError('invalid candidate')
        seen.add(cid)
        completed = []
        for item in screenings:
            if not isinstance(item, dict) or item.get('status') not in priority or 'completed' not in item:
                raise ValueError('invalid screening')
            when = item['completed']
            if when is not None:
                try:
                    d = date.fromisoformat(when)
                except Exception as exc:
                    raise ValueError('invalid screening date') from exc
                if d <= cutoff:
                    completed.append((d, item['status']))
        status = max(completed)[1] if completed else 'pending'
        old = last.get(cid)
        rows.append({'id': cid, 'name': name, 'status': status, 'completed_count': len(completed), 'total_count': len(screenings), 'last_reviewed': old, 'attempts': attempts.get(cid, 0)})
    rows.sort(key=lambda r: (priority[r['status']], -Fraction(r['completed_count'], r['total_count'] or 1), r['name'].casefold(), r['id']))
    new_state = dict(state)
    new_state['last_reviewed'] = dict(last)
    new_state['attempts'] = dict(attempts)
    for row in rows:
        new_state['last_reviewed'][row['id']] = as_of
        new_state['attempts'][row['id']] = row['attempts'] + 1
    return (rows, encode_checkpoint(new_state))

