import requests

def fetch_baggage_manifest(api_base: str, flight_number: str, token: str) -> list[dict]:
    url = api_base.rstrip('/') + '/v1/flights/' + quote(flight_number, safe='') + '/baggage'
    response = requests.get(url, params={'date': flight_number.split('-')[0]}, headers={'Authorization': 'Bearer ' + token})
    if response.status_code != 200:
        raise ValueError('unexpected response status')
    try:
        payload = response.json()
    except Exception as exc:
        raise ValueError('invalid response') from exc
    if not isinstance(payload, dict) or not isinstance(payload.get('bags'), list):
        raise ValueError('invalid response')
    for bag in payload['bags']:
        if not isinstance(bag, dict) or set(('tag', 'passenger', 'destination', 'weight')) - bag.keys():
            raise ValueError('invalid bag')
        if not all((isinstance(bag[k], str) for k in ('tag', 'passenger', 'destination'))):
            raise ValueError('invalid bag')
        if isinstance(bag['weight'], bool) or not isinstance(bag['weight'], (int, float)) or bag['weight'] < 0:
            raise ValueError('invalid bag')
    return payload['bags']

def reconcile_baggage(manifest: list[dict], scans: list[dict]) -> dict:
    if not isinstance(manifest, list) or not isinstance(scans, list):
        raise ValueError('lists required')
    bags = {}
    for bag in manifest:
        if not isinstance(bag, dict) or set(('tag', 'passenger', 'destination', 'weight')) - bag.keys():
            raise ValueError('invalid manifest')
        if not all((isinstance(bag[k], str) for k in ('tag', 'passenger', 'destination'))):
            raise ValueError('invalid manifest')
        if isinstance(bag['weight'], bool) or not isinstance(bag['weight'], (int, float)) or bag['weight'] < 0 or (bag['tag'] in bags):
            raise ValueError('invalid manifest')
        bags[bag['tag']] = bag
    counts = {}
    unknown = set()
    for scan in scans:
        if not isinstance(scan, dict) or set(('tag', 'checkpoint', 'timestamp', 'status')) - scan.keys() or (not all((isinstance(scan[k], str) for k in ('tag', 'checkpoint', 'timestamp', 'status')))):
            raise ValueError('invalid scan')
        if scan['status'] == 'loaded':
            counts[scan['tag']] = counts.get(scan['tag'], 0) + 1
            if scan['tag'] not in bags:
                unknown.add(scan['tag'])
    items = []
    totals = {'manifest_weight': 0, 'loaded_weight': 0, 'reconciled': 0, 'duplicate': 0, 'missing': 0}
    for tag in sorted(bags):
        count = counts.get(tag, 0)
        status = 'missing' if count == 0 else 'reconciled' if count == 1 else 'duplicate'
        items.append({'tag': tag, 'status': status, 'weight': bags[tag]['weight']})
        totals['manifest_weight'] += bags[tag]['weight']
        if count:
