    if not isinstance(state, dict) or set(state) != {'rooms', 'waiting'}:
        raise ValueError('invalid state')
    rooms = state['rooms']
    waiting = state['waiting']
    if not isinstance(rooms, dict) or not isinstance(waiting, list):
        raise ValueError('invalid state')
    for room, guests in rooms.items():
        if not isinstance(room, str) or not isinstance(guests, list):
            raise ValueError('invalid state')
        if any((not isinstance(g, str) for g in guests)):
            raise ValueError('invalid state')
    if any((not isinstance(g, str) for g in waiting)):
        raise ValueError('invalid state')

def encode_state(state: dict) -> bytes:
    _check_state(state)
    try:
        return pickle.dumps(state, protocol=4) + b'!'
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid state') from exc

def decode_state(blob: bytes) -> dict:
    if not isinstance(blob, bytes) or not blob.endswith(b'!'):
        raise ValueError('invalid data')
    try:
        value = pickle.loads(blob[:-1])
    except Exception as exc:
        raise ValueError('invalid data') from exc
    _check_state(value)
    return value

def assign_guests(blob: bytes, requests: list[dict], capacities: dict[str, int]) -> tuple[bytes, list[str]]:
    state = decode_state(blob)
    if not isinstance(requests, list) or not isinstance(capacities, dict):
        raise ValueError('invalid input')
    if set(state['rooms']) - set(capacities):
        raise ValueError('missing capacity')
    for room, cap in capacities.items():
        if not isinstance(room, str) or isinstance(cap, bool) or (not isinstance(cap, int)) or (cap <= 0):
            raise ValueError('invalid capacity')
    seen = set(state['waiting'])
    for guests in state['rooms'].values():
        if seen.intersection(guests):
            raise ValueError('duplicate guest')
        seen.update(guests)
    parsed = []
    for item in requests:
        if not isinstance(item, dict) or set(item) != {'name', 'preferences', 'priority'}:
            raise ValueError('invalid request')
        name = item['name']
        prefs = item['preferences']
        priority = item['priority']
        if not isinstance(name, str) or not isinstance(prefs, list) or any((not isinstance(x, str) for x in prefs)) or isinstance(priority, bool) or (not isinstance(priority, int)) or (name in seen):
            raise ValueError('invalid request')
        seen.add(name)
        parsed.append(item)
    rooms = {k: list(v) for k, v in state['rooms'].items()}
    waiting = list(state['waiting'])
    unassigned = []
    for item in sorted(parsed, key=lambda x: (-x['priority'], x['name'])):
        choices = [r for r in item['preferences'] if r in rooms and len(rooms[r]) < capacities[r]]
        choices = choices or [r for r in sorted(rooms) if len(rooms[r]) < capacities[r]]
        if choices:
            rooms[choices[0]].append(item['name'])
        else:
            waiting.append(item['name'])
            unassigned.append(item['name'])
    return (encode_state({'rooms': rooms, 'waiting': waiting}), unassigned)

