import html
from io import StringIO

def parse_bom(text: str) -> list[dict[str, object]]:
    lines = [line for line in text.splitlines() if line.strip()]
    if not lines:
        raise ValueError('empty document')
    rows = list(csv.reader(lines))
    if rows[0] != ['part', 'description', 'qty', 'unit']:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if len(row) != 4:
            raise ValueError('invalid row')
        part, description, quantity, unit = [value.strip() for value in row]
        if not part or not description or (not unit):
            raise ValueError('empty field')
        if not quantity.isdigit() or int(quantity) <= 0:
            raise ValueError('invalid quantity')
        result.append({'part': part, 'description': description, 'qty': int(quantity), 'unit': unit})
    return result

def summarize_bom(records: list[dict[str, object]]) -> list[dict[str, object]]:
    groups = {}
    for record in records:
        key = (record['part'], record['unit'])
        if key not in groups:
            groups[key] = {'part': record['part'], 'description': record['description'], 'qty': 0, 'unit': record['unit']}
        groups[key]['qty'] += record['qty']
    return sorted(groups.values(), key=lambda item: (-item['qty'], item['unit'], item['part']))

