from datetime import datetime, timezone
import requests

def load_license_events(api_url: str, token: str, asset_id: str, start: str, end: str) -> list[dict]:
    url = api_url.rstrip('/') + '/v1/licenses/events'
    headers = {'Authorization': 'Bearer ' + token}
    params = {'asset_id': asset_id, 'start': start, 'end': end}
    result = []
    for _ in range(100):
        response = requests.get(url, params=params, headers=headers, timeout=10)
        if response.status_code != 200:
            raise RuntimeError(f'request failed with status {response.status_code}')
        try:
            data = response.json()
        except Exception as exc:
            raise ValueError('invalid JSON') from exc
        if not isinstance(data, dict):
            raise ValueError('response must be an object')
        events = data.get('events', [])
        if not isinstance(events, list):
            raise ValueError('events must be a list')
        result.extend(events)
        url = data.get('next')
        params = None
        if not url:
            return result
    raise RuntimeError('pagination limit exceeded')

def summarize_usage(events: list[dict]) -> dict:
    output = {}
    for event in events:
        try:
            action = event['action']
            units = event['units']
            stamp = event['timestamp']
            asset = event['asset_id']
            if action not in ('checkout', 'release') or isinstance(units, bool) or (not isinstance(units, int)) or (units < 0):
                raise ValueError
            parsed = datetime.fromisoformat(stamp.replace('Z', '+00:00'))
            if parsed.tzinfo is None:
                parsed = parsed.replace(tzinfo=timezone.utc)
            date = parsed.astimezone(timezone.utc).date().isoformat()
        except (KeyError, TypeError, ValueError, AttributeError) as exc:
            raise ValueError('invalid event') from exc
        days = output.setdefault(asset, {})
        counts = days.setdefault(date, {'checkouts': 0, 'releases': 0, 'net_units': 0})
        counts['checkouts' if action == 'checkout' else 'releases'] += 1
        counts['net_units'] += units if action == 'checkout' else -units
    return {asset: {day: output[asset][day] for day in sorted(output[asset])} for asset in sorted(output)}

def build_license_report(api_url: str, token: str, asset_id: str, start: str, end: str) -> dict:
    events = load_license_events(api_url, token, asset_id, start, end)
    return {'asset_id': asset_id, 'start': start, 'end': end, 'event_count': len(events), 'usage': summarize_usage(events)}

