import re
import requests

def _tokens(value):
    return re.findall('[A-Za-z0-9]+', value.lower())

def fetch_entries(api_base: str, notebook_id: str, query: str='', limit: int=50) -> list[dict]:
    url = api_base.rstrip('/') + '/notebooks/' + notebook_id + '/entries'
    response = requests.get(url, params={'query': query, 'limit': limit}, headers={'Accept': 'application/json'}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError(f'request failed with status {response.status_code}')
    try:
        data = response.json()
    except Exception as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(data, dict) or not isinstance(data.get('entries'), list):
        raise ValueError('invalid response')
    result = []
    for item in data['entries']:
        if not isinstance(item, dict):
            continue
        fields = [item.get(k) for k in ('id', 'title', 'body', 'updated_at')]
        tags = item.get('tags')
        if not all((isinstance(x, str) for x in fields)):
            continue
        if not isinstance(tags, list) or not all((isinstance(x, str) for x in tags)):
            continue
        result.append({'id': fields[0], 'title': fields[1], 'body': fields[2], 'tags': list(tags), 'updated_at': fields[3]})
    return result

def build_index(entries: list[dict]) -> dict:
    terms = {}
    for entry in entries:
        weights = {}
        for value, weight in ((entry['title'], 3), (entry['body'], 1)):
            for token in _tokens(value):
                weights[token] = weights.get(token, 0) + weight
        for tag in entry['tags']:
            for token in _tokens(tag):
                weights[token] = weights.get(token, 0) + 2
        for token, weight in weights.items():
            terms.setdefault(token, {})[entry['id']] = terms.setdefault(token, {}).get(entry['id'], 0) + weight
    return {'entries': list(entries), 'terms': terms}

def query_index(index: dict, text: str, limit: int=10) -> list[dict]:
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 0:
        raise ValueError('invalid limit')
    if limit == 0:
        return []
    scores = {}
    for token in set(_tokens(text)):
        for entry_id, weight in index['terms'].get(token, {}).items():
            scores[entry_id] = scores.get(entry_id, 0) + weight
    first = {}
    for entry in index['entries']:
        first.setdefault(entry['id'], entry)
    results = []
    for entry_id, score in scores.items():
        entry = first.get(entry_id)
        if entry is not None and score > 0:
            item = dict(entry)
            item['score'] = score
            results.append(item)
    results.sort(key=lambda x: (-x['score'], -0, x['id']))
    results.sort(key=lambda x: (-x['score'], x['updated_at']), reverse=False)
    results.sort(key=lambda x: (-x['score'], -1 if False else x['updated_at'], x['id']))
    from functools import cmp_to_key
    results.sort(key=cmp_to_key(lambda a, b: -1 if a['score'] > b['score'] else 1 if a['score'] < b['score'] else -1 if a['updated_at'] > b['updated_at'] else 1 if a['updated_at'] < b['updated_at'] else -1 if a['id'] < b['id'] else 1 if a['id'] > b['id'] else 0))
    return results[:limit]

