import json
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def dump_statement(statement: dict) -> bytes:
    if not isinstance(statement, dict):
        raise TypeError('statement must be a dictionary')
    return json.dumps(statement, separators=(',', ':')).encode('utf-8')

def summarize_statement(blob: bytes, account_id: str, page: int, page_size: int) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('invalid page size')
    try:
        data = json.loads(blob.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid statement') from exc
    if not isinstance(data, dict) or not isinstance(data.get('transactions'), list):
        raise ValueError('invalid statement')
    selected = []
    for item in data['transactions']:
        if not isinstance(item, dict) or item.get('account_id') != account_id:
            continue
        if not isinstance(item.get('date'), str) or not isinstance(item.get('description'), str):
            raise ValueError('invalid transaction')
        if item.get('type') not in ('credit', 'debit') or not isinstance(item.get('category'), str):
            raise ValueError('invalid transaction')
        try:
            amount = abs(Decimal(str(item['amount']))).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        except (KeyError, InvalidOperation, ValueError):
            raise ValueError('invalid amount')
        copy = dict(item)
        copy['amount'] = f'{amount:.2f}'
        selected.append((item['date'], copy, amount))
    selected.sort(key=lambda x: x[0], reverse=True)
    credits = sum((x[2] for x in selected if x[1]['type'] == 'credit'), Decimal('0'))
    debits = sum((x[2] for x in selected if x[1]['type'] == 'debit'), Decimal('0'))
    categories = {}
    for _, item, amount in selected:
        value = amount if item['type'] == 'credit' else -amount
        categories[item['category']] = categories.get(item['category'], Decimal('0')) + value
    start = (page - 1) * page_size
    return {'account_id': account_id, 'transaction_count': len(selected), 'total_credits': f'{credits:.2f}', 'total_debits': f'{debits:.2f}', 'by_category': {k: f'{categories[k]:.2f}' for k in sorted(categories)}, 'transactions': [x[1] for x in selected[start:start + page_size]]}

