import json
from datetime import date

def _validate(records):
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    for item in records:
        if not isinstance(item, dict):
            raise ValueError('record must be an object')
        if not isinstance(item.get('drug'), str) or not item['drug']:
            raise ValueError('invalid drug')
        quantity = item.get('quantity')
        price = item.get('unit_price')
        if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity <= 0:
            raise ValueError('invalid quantity')
        if isinstance(price, bool) or not isinstance(price, (int, float)) or price < 0:
            raise ValueError('invalid price')
        if not isinstance(item.get('dispensed_at'), str):
            raise ValueError('invalid date')
        try:
            date.fromisoformat(item['dispensed_at'])
        except ValueError:
            raise ValueError('invalid date')
        if not isinstance(item.get('controlled'), bool):
            raise ValueError('invalid controlled flag')

def pack_records(records: list[dict]) -> bytes:
    _validate(records)
    return json.dumps(records, separators=(',', ':')).encode('utf-8')

def controlled_substance_report(payload: bytes, page: int=1, page_size: int=10) -> list[dict]:
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('invalid page size')
    try:
        records = json.loads(payload)
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    _validate(records)
    groups = {}
    for item in records:
        if not item['controlled']:
            continue
        drug = item['drug']
        group = groups.setdefault(drug, {'drug': drug, 'quantity': 0, 'value': 0.0, 'latest': '', 'dispensings': 0})
        group['quantity'] += item['quantity']
        group['value'] += item['quantity'] * item['unit_price']
        group['latest'] = max(group['latest'], item['dispensed_at'])
        group['dispensings'] += 1
    result = sorted(groups.values(), key=lambda x: (-x['quantity'], x['drug']))
    for item in result:
        item['value'] = round(item['value'], 2)
    start = (page - 1) * page_size
    return result[start:start + page_size]

