import requests

def summarize_recovery_runs(api_url: str, service: str, since_hours: int, token: str) -> dict:
    if not isinstance(api_url, str) or not api_url:
        raise ValueError('api_url must be non-empty')
    if not isinstance(service, str) or not service:
        raise ValueError('service must be non-empty')
    if isinstance(since_hours, bool) or not isinstance(since_hours, int) or since_hours <= 0:
        raise ValueError('since_hours must be positive')
    if not isinstance(token, str) or not token:
        raise ValueError('token must be non-empty')
    runs = []
    cursor = None
    while True:
        params = {'service': service, 'since_hours': since_hours, 'limit': 100}
        if cursor:
            params['cursor'] = cursor
        result = requests.get(api_url.rstrip('/') + '/v1/runs', params=params, headers={'Authorization': 'Bearer ' + token}, timeout=10)
        if result.status_code != 200:
            raise RuntimeError('run service returned an error')
        payload = result.json()
        page = payload.get('runs')
        if not isinstance(page, list):
            raise ValueError('runs must be a list')
        runs.extend(page)
        cursor = payload.get('next')
        if not cursor:
            break
        if not isinstance(cursor, str):
            raise ValueError('next must be a string')
    regions = {}
    total_duration = 0.0
    successful = 0
    failed = 0
    for run in runs:
        if not isinstance(run, dict):
            raise ValueError('run must be an object')
        status = run.get('status')
        duration = run.get('duration_seconds')
        region = run.get('region')
        if status not in {'success', 'failure', 'aborted'}:
            raise ValueError('invalid status')
        if isinstance(duration, bool) or not isinstance(duration, (int, float)) or duration < 0:
            raise ValueError('invalid duration')
        if not isinstance(region, str) or not region:
            raise ValueError('invalid region')
        total_duration += duration
        successful += status == 'success'
        failed += status == 'failure'
        if region not in regions:
            regions[region] = [0, 0]
        regions[region][0] += 1
        regions[region][1] += status == 'success'
    total = len(runs)
    by_region = [{'region': name, 'total': values[0], 'successful': values[1]} for name, values in regions.items()]
    by_region.sort(key=lambda item: (-item['total'], item['region']))
    return {'total': total, 'successful': successful, 'failed': failed, 'success_rate': round(successful * 100 / total, 2) if total else 0.0, 'average_duration_seconds': round(total_duration / total, 2) if total else 0.0, 'by_region': by_region}

