import re
import requests

def fetch_deposit_events(listing_id: str, start_date: str, end_date: str, api_key: str) -> list[dict]:
    if not isinstance(start_date, str) or not re.fullmatch('\\d{4}-\\d{2}-\\d{2}', start_date):
        raise ValueError('invalid date')
    if not isinstance(end_date, str) or not re.fullmatch('\\d{4}-\\d{2}-\\d{2}', end_date) or start_date > end_date:
        raise ValueError('invalid date')
    response = requests.get('https://deposits.example.test/v1/listings/' + listing_id + '/events', params={'listing_id': listing_id, 'start_date': start_date, 'end_date': end_date}, headers={'X-API-Key': api_key})
    if response.status_code != 200:
        raise RuntimeError('request failed')
    try:
        payload = response.json()
    except Exception as exc:
        raise ValueError('invalid response') from exc
    if not isinstance(payload, dict) or not isinstance(payload.get('events'), list):
        raise ValueError('invalid events')
    allowed = {'hold', 'capture', 'release', 'refund'}
    result = []
    ids = set()
    for raw in payload['events']:
        if not isinstance(raw, dict):
            raise ValueError('invalid event')
        fields = ('id', 'reservation_id', 'type', 'amount_cents', 'occurred_at')
        if any((k not in raw for k in fields)):
            raise ValueError('invalid event')
        if not all((isinstance(raw[k], str) for k in ('id', 'reservation_id', 'type', 'occurred_at'))):
            raise ValueError('invalid event')
        if raw['type'] not in allowed or not isinstance(raw['amount_cents'], int) or isinstance(raw['amount_cents'], bool) or (not re.fullmatch('.+T.+Z', raw['occurred_at'])):
            raise ValueError('invalid event')
        if raw['id'] in ids:
            raise ValueError('duplicate id')
        ids.add(raw['id'])
        result.append({k: raw[k] for k in fields})
    return sorted(result, key=lambda x: (x['occurred_at'], x['id']))

def summarize_deposits(events: list[dict]) -> dict:
    groups = {}
    signs = {'hold': 1, 'capture': 1, 'release': -1, 'refund': -1}
    for event in events:
        if not isinstance(event, dict) or any((k not in event for k in ('id', 'reservation_id', 'type', 'amount_cents'))):
            raise ValueError('invalid event')
        if event['type'] not in signs or not isinstance(event['amount_cents'], int) or isinstance(event['amount_cents'], bool):
            raise ValueError('invalid event')
        rid = event['reservation_id']
        if rid not in groups:
            groups[rid] = {'balance_cents': 0, 'event_count': 0, 'last_event': None}
        groups[rid]['balance_cents'] += signs[event['type']] * event['amount_cents']
        groups[rid]['event_count'] += 1
        groups[rid]['last_event'] = event['id']
    reservations = [{'reservation_id': rid, **data} for rid, data in groups.items()]
    reservations.sort(key=lambda x: (-x['balance_cents'], x['reservation_id']))
    return {'total_balance_cents': sum((x['balance_cents'] for x in reservations)), 'reservations': reservations, 'event_count': len(events)}

