import csv
import html
import io
import math
STATUSES = ('submitted', 'under_review', 'accepted', 'rejected')

def parse_submissions(text: str) -> list[dict]:
    if not text:
        raise ValueError('empty input')
    try:
        rows = list(csv.reader(io.StringIO(text)))
    except csv.Error as exc:
        raise ValueError('invalid csv') from exc
    rows = [row for row in rows if any((cell.strip() for cell in row))]
    if not rows or rows[0] != ['id', 'title', 'authors', 'status', 'score']:
        raise ValueError('invalid header')
    result = []
    seen = set()
    for row in rows[1:]:
        if len(row) != 5:
            raise ValueError('invalid row')
        ident, title, authors, status, score_text = [x.strip() for x in row]
        if not ident or ident in seen or (not title):
            raise ValueError('invalid identity')
        names = [x.strip() for x in authors.split('|')]
        if not authors or any((not name for name in names)):
            raise ValueError('invalid authors')
        if status not in STATUSES:
            raise ValueError('invalid status')
        try:
            score = float(score_text)
        except ValueError as exc:
            raise ValueError('invalid score') from exc
        if not math.isfinite(score) or not 0 <= score <= 100:
            raise ValueError('invalid score')
        seen.add(ident)
        result.append({'id': ident, 'title': title, 'authors': names, 'status': status, 'score': score})
    return result

def summarize_submissions(submissions: list[dict]) -> dict:
    counts = {status: 0 for status in STATUSES}
    for item in submissions:
        counts[item['status']] += 1
    average = sum((item['score'] for item in submissions)) / len(submissions) if submissions else 0.0
    return {'total': len(submissions), 'average_score': round(average, 2), 'by_status': counts}

def render_submission_report(submissions: list[dict], page: int=1, page_size: int=10) -> str:
    if isinstance(page, bool) or isinstance(page_size, bool) or page < 1 or (page_size < 1):
        raise ValueError('invalid pagination')
    summary = summarize_submissions(submissions)
    ordered = sorted(submissions, key=lambda x: (-x['score'], x['id']))
    pages = max(1, (len(ordered) + page_size - 1) // page_size)
    chosen = ordered[(page - 1) * page_size:page * page_size]
    e = lambda value: html.escape(str(value), quote=True)
    rows = ''.join(('<tr><td>' + e(x['id']) + '</td><td>' + e(x['title']) + '</td><td>' + e('; '.join(x['authors'])) + '</td><td>' + e(x['status']) + '</td><td>' + e(f"{x['score']:.2f}") + '</td></tr>' for x in chosen))
    counts = ''.join(('<li>' + e(status) + ': ' + e(summary['by_status'][status]) + '</li>' for status in STATUSES))
    return '<div class="report"><h1>Submission report</h1><p class="summary">Total: ' + e(summary['total']) + ' | Average score: ' + e(f"{summary['average_score']:.2f}") + '</p><ul class="counts">' + counts + '</ul><table><thead><tr><th>ID</th><th>Title</th><th>Authors</th><th>Status</th><th>Score</th></tr></thead><tbody>' + rows + '</tbody></table><p class="page">Page ' + e(page) + ' of ' + e(pages) + '</p></div>'

