def decode_state(blob: bytes | str) -> dict:
    try:
        text = blob.decode('utf-8') if isinstance(blob, bytes) else blob
        value = json.loads(text)
    except Exception as exc:
        raise ValueError('invalid state') from exc
    if not isinstance(value, dict) or value.get('version') != 1 or (not isinstance(value.get('series'), dict)):
        raise ValueError('invalid state')
    for name, item in value['series'].items():
