            raise ValueError('invalid state')
        if set(item) != {'level', 'trend'}:
            raise ValueError('invalid state')
        for key in ('level', 'trend'):
            x = item[key]
            if isinstance(x, bool) or not isinstance(x, (int, float)) or (not math.isfinite(x)):
                raise ValueError('invalid state')
    return value

def forecast_demand(observations: list[dict], horizon: int, state_blob: bytes | str | None=None) -> dict[str, list[float]]:
    if not isinstance(horizon, int) or isinstance(horizon, bool) or horizon < 0:
        raise ValueError('invalid horizon')
    state = decode_state(state_blob) if state_blob is not None else {'version': 1, 'series': {}}
    grouped = {}
    for row in observations:
