            raise ValueError('invalid loss')
        if isinstance(exposure, bool) or not isinstance(exposure, (int, float)) or (not math.isfinite(exposure)) or (exposure <= 0):
            raise ValueError('invalid exposure')
        key = (entity, date)
        if key in seen:
            raise ValueError('duplicate observation')
        seen.add(key)
