import math
import requests

def fetch_development_applications(api_url: str, district: str, *, status: str | None=None, min_area: float=0.0, page: int=1, page_size: int=20) -> list[dict]:
    if not isinstance(district, str) or not district:
        raise ValueError('invalid district')
    if not isinstance(min_area, (int, float)) or not math.isfinite(min_area) or min_area < 0:
        raise ValueError('invalid area')
    if not isinstance(page, int) or page < 1 or (not isinstance(page_size, int)) or (not 1 <= page_size <= 100):
        raise ValueError('invalid pagination')
    params = {'district': district, 'page': page, 'page_size': page_size}
    if status is not None:
        params['status'] = status
    response = requests.get(api_url.rstrip('/') + '/applications', params=params)
    if response.status_code != 200:
        raise RuntimeError('request failed')
    try:
        payload = response.json()
    except Exception as exc:
        raise ValueError('invalid response') from exc
    if not isinstance(payload, dict) or not isinstance(payload.get('applications'), list):
        raise ValueError('invalid response')
    result = []
    for item in payload['applications']:
        try:
            value = float(item['hectares'])
            identifier = str(item['id'])
            address = str(item['address'])
            item_status = str(item['status'])
            submitted = str(item['submitted_date'])
        except (KeyError, TypeError, ValueError) as exc:
            raise ValueError('invalid application') from exc
        if not math.isfinite(value):
            raise ValueError('invalid area')
        if value >= min_area and (status is None or item_status == status):
            result.append({'id': identifier, 'address': address, 'area_hectares': round(value, 2), 'status': item_status, 'submitted_date': submitted})
    result.sort(key=lambda item: item['id'])
    result.sort(key=lambda item: item['submitted_date'], reverse=True)
    return result

