        params['cursor'] = cursor
    response = requests.get(base_url.rstrip('/') + '/v1/manifests', params=params, headers={'Accept': 'application/json', 'X-Client-ID': client_id})
    if response.status_code != 200:
        raise RuntimeError(f'manifest request failed with status {response.status_code}')
    try:
        data = response.json()
    except Exception as exc:
        raise ValueError('invalid manifest JSON') from exc
    if not isinstance(data, dict):
        raise ValueError('manifest must be an object')
    return data

def summarize_documents(manifest: dict) -> list[dict]:
    shipments = manifest.get('shipments') if isinstance(manifest, dict) else None
    if not isinstance(shipments, list):
        raise ValueError('shipments must be a list')
    groups = {}
    for shipment in shipments:
        if not isinstance(shipment, dict) or not isinstance(shipment.get('declarant'), str) or (not isinstance(shipment.get('documents'), list)):
            raise ValueError('invalid shipment')
        for doc in shipment['documents']:
            if not isinstance(doc, dict) or not isinstance(doc.get('commodity'), str) or (not isinstance(doc.get('value_cents'), int)) or isinstance(doc['value_cents'], bool) or (doc['value_cents'] < 0) or ('status' not in doc):
                raise ValueError('invalid document')
            if doc['status'] == 'accepted':
                key = (shipment['declarant'], doc['commodity'])
                count, total = groups.get(key, (0, 0))
                groups[key] = (count + 1, total + doc['value_cents'])
    result = [{'declarant': k[0], 'commodity': k[1], 'document_count': v[0], 'total_value_cents': v[1]} for k, v in groups.items()]
    return sorted(result, key=lambda x: (-x['total_value_cents'], x['declarant'], x['commodity']))

def build_clearance_windows(events: list[dict], window_hours: float) -> list[dict]:
    if window_hours < 0:
        raise ValueError('negative window')
    by_port = {}
    for event in events:
        if not isinstance(event, dict) or not all((k in event for k in ('id', 'port', 'timestamp', 'status'))):
            raise ValueError('invalid event')
        if event['status'] != 'released':
            continue
        if not isinstance(event['timestamp'], str) or not event['timestamp'].endswith('Z'):
            raise ValueError('invalid timestamp')
        try:
            stamp = datetime.fromisoformat(event['timestamp'][:-1] + '+00:00')
        except Exception as exc:
            raise ValueError('invalid timestamp') from exc
        if stamp.tzinfo != timezone.utc:
            raise ValueError('invalid timestamp')
        by_port.setdefault(event['port'], []).append((stamp, event))
    output = []
    for port, values in by_port.items():
        values.sort(key=lambda x: (x[0], x[1]['id']))
        current = []
        previous = None
        for stamp, event in values:
            if current and (stamp - previous).total_seconds() > window_hours * 3600:
                output.append(_window(port, current))
                current = []
            current.append((stamp, event))
            previous = stamp
        if current:
            output.append(_window(port, current))
    return sorted(output, key=lambda x: (x['start'], x['port']))

def _window(port, values):
    return {'port': port, 'start': values[0][1]['timestamp'], 'end': values[-1][1]['timestamp'], 'event_ids': [x[1]['id'] for x in values], 'count': len(values)}

