from solution import fetch_field_conditions
from unittest.mock import Mock, patch
import pytest


def make_response(status=200, payload=None):
    response = Mock()
    response.status_code = status
    response.json.return_value = payload
    return response


def test_returns_normalized_conditions():
    response = make_response(200, {
        "station_id": "pond-7",
        "temperature_c": 18.5,
        "readings": [
            {"species": "Rana temporaria", "count": 4, "extra": "ignored"},
            {"species": "Triturus vulgaris", "count": 2}
        ]
    })
    with patch("solution.requests.get", return_value=response) as get:
        result = fetch_field_conditions("pond-7", "abc123")
    assert result == {
        "station_id": "pond-7",
        "temperature_c": 18.5,
        "readings": [
            {"species": "Rana temporaria", "count": 4},
            {"species": "Triturus vulgaris", "count": 2}
        ]
    }
    assert get.call_args.args[0] == "https://field-data.example/v1/conditions"
    assert get.call_args.kwargs["params"] == {"station": "pond-7"}
    assert get.call_args.kwargs["headers"] == {
        "Authorization": "Bearer abc123",
        "Accept": "application/json"
    }
    assert get.call_args.kwargs["timeout"] == 10


def test_trailing_base_url_slashes_are_removed():
    response = make_response(200, {"temperature_c": 11, "readings": []})
    with patch("solution.requests.get", return_value=response) as get:
        result = fetch_field_conditions("forest-1", "key", "https://weather.test///")
    assert result["station_id"] == "forest-1"
    assert get.call_args.args[0] == "https://weather.test/v1/conditions"


def test_missing_station_id_in_payload_uses_requested_id():
    response = make_response(200, {"temperature_c": 7.25})
    with patch("solution.requests.get", return_value=response):
        result = fetch_field_conditions("marsh-2", "key")
    assert result == {
        "station_id": "marsh-2",
        "temperature_c": 7.25,
        "readings": []
    }


def test_empty_readings_are_preserved_as_empty_list():
    response = make_response(200, {
        "station_id": "ridge",
        "temperature_c": 3,
        "readings": []
    })
    with patch("solution.requests.get", return_value=response):
