from copy import deepcopy
from html import escape

def select_meals(meals: list[dict], required_tags: set[str], calorie_limit: int | None=None) -> list[dict]:
    if calorie_limit is not None and (not isinstance(calorie_limit, int) or calorie_limit < 0):
        raise ValueError('invalid calorie limit')
    best = {}
    for meal in meals:
        if not isinstance(meal, dict):
            raise ValueError('invalid meal')
        keys = ('day', 'name', 'calories', 'protein', 'tags')
        if any((k not in meal for k in keys)):
            raise ValueError('invalid meal')
        if not isinstance(meal['day'], int) or not 1 <= meal['day'] <= 7:
            raise ValueError('invalid day')
        if not isinstance(meal['name'], str) or not isinstance(meal['calories'], int) or meal['calories'] < 0:
            raise ValueError('invalid meal')
        if not isinstance(meal['protein'], (int, float)) or meal['protein'] < 0:
            raise ValueError('invalid meal')
        if not isinstance(meal['tags'], list) or not all((isinstance(x, str) for x in meal['tags'])):
            raise ValueError('invalid tags')
        if not required_tags.issubset(set(meal['tags'])) or (calorie_limit is not None and meal['calories'] > calorie_limit):
            continue
        old = best.get(meal['day'])
        rank = (-meal['protein'], meal['calories'], meal['name'])
        if old is None or rank < old[0]:
            best[meal['day']] = (rank, deepcopy(meal))
    return [best[d][1] for d in sorted(best)]

def nutrition_summary(meals: list[dict]) -> dict:
    days = []
    calories = 0
    protein = 0.0
    for meal in meals:
        if not all((k in meal for k in ('day', 'calories', 'protein'))):
            raise ValueError('invalid meal')
        if not isinstance(meal['day'], int) or not isinstance(meal['calories'], (int, float)) or (not isinstance(meal['protein'], (int, float))):
            raise ValueError('invalid meal')
        if days and meal['day'] <= days[-1]:
            raise ValueError('days must increase')
        days.append(meal['day'])
        calories += meal['calories']
        protein += meal['protein']
    streaks = []
    if days:
        start = previous = days[0]
        for day in days[1:] + [None]:
            if day is None or day != previous + 1:
                streaks.append({'start': start, 'end': previous, 'length': previous - start + 1})
                if day is not None:
                    start = day
            previous = day if day is not None and day == previous + 1 else previous
    return {'days': len(days), 'total_calories': calories, 'total_protein': round(protein, 1), 'average_calories': round(calories / len(days), 1) if days else 0.0, 'streaks': streaks}

def render_meal_plan(title: str, meals: list[dict], summary: dict) -> str:
    rows = ''
    for meal in meals:
        tags = ', '.join(meal.get('tags', []))
        rows += '<tr><td>' + escape(str(meal['day'])) + '</td><td>' + escape(str(meal['name'])) + '</td><td>' + escape(str(meal['calories'])) + '</td><td>' + escape(str(meal['protein'])) + '</td><td>' + escape(tags) + '</td></tr>'
    text = f"{summary['days']} days · {summary['total_calories']} calories · {summary['total_protein']} g protein"
    return '<section><h1>' + escape(str(title)) + '</h1><table><thead><tr><th>Day</th><th>Meal</th><th>Calories</th><th>Protein</th><th>Tags</th></tr></thead><tbody>' + rows + '</tbody></table><p class="summary">' + escape(text) + '</p></section>'

