import hashlib
from datetime import date, timedelta
import requests

def _parse_date(value):
    if not isinstance(value, str):
        raise ValueError('invalid date')
    try:
        parsed = date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if parsed.isoformat() != value:
        raise ValueError('invalid date')
    return parsed

def anonymize_records(records: list[dict], as_of: str) -> list[dict]:
    if not isinstance(records, list):
        raise ValueError('invalid patients')
    limit = _parse_date(as_of)
    output = []
    for patient in records:
        if not isinstance(patient, dict):
            raise ValueError('invalid patient')
        pid = patient.get('patient_id')
        birth_value = patient.get('birth_date')
        visits = patient.get('visits')
        if not isinstance(pid, str) or not pid or (not isinstance(visits, list)):
            raise ValueError('invalid patient')
        birth = _parse_date(birth_value)
        digest = hashlib.sha256(pid.encode()).digest()
        subject = hashlib.sha256(pid.encode()).hexdigest()[:12]
        shift = digest[0] % 15 - 7
        for visit in visits:
            if not isinstance(visit, dict) or not isinstance(visit.get('diagnoses'), list) or (not isinstance(visit.get('note'), str)):
                raise ValueError('invalid visit')
            visit_date = _parse_date(visit.get('date'))
            if visit_date > limit:
                continue
            diagnoses = visit['diagnoses']
            if any((not isinstance(item, str) for item in diagnoses)):
                raise ValueError('invalid diagnosis')
            age = visit_date.year - birth.year - ((visit_date.month, visit_date.day) < (birth.month, birth.day))
            output.append({'subject': subject, 'age': age, 'visit_date': (visit_date + timedelta(days=shift)).isoformat(), 'diagnoses': sorted(set((item.lower() for item in diagnoses))), 'note_length': len(visit['note'])})
    output.sort(key=lambda item: (item['subject'], item['visit_date'], item['diagnoses']))
    return output

def fetch_anonymized_records(endpoint: str, api_token: str, as_of: str) -> list[dict]:
    response = requests.get(endpoint, headers={'Authorization': 'Bearer ' + api_token}, params={'as_of': as_of})
    if response.status_code != 200:
        raise ValueError('request failed')
    try:
        payload = response.json()
    except Exception as exc:
        raise ValueError('invalid response') from exc
    if not isinstance(payload, dict) or not isinstance(payload.get('patients'), list):
        raise ValueError('invalid response')
    return anonymize_records(payload['patients'], as_of)

