import html
import math
from decimal import Decimal

def render_maintenance_report(records: list[dict], page: int=1, page_size: int=10) -> str:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if not isinstance(page, int) or isinstance(page, bool) or (not isinstance(page_size, int)) or isinstance(page_size, bool):
        raise ValueError('invalid pagination')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    ranks = {'open': 0, 'deferred': 1, 'closed': 2}
    clean = []
    total_hours = 0
    total_cost = Decimal('0')
    required = {'asset', 'technician', 'status', 'hours', 'cost'}
    for record in records:
        if not isinstance(record, dict):
            raise TypeError('record must be a dictionary')
        if not required.issubset(record):
            raise ValueError('missing field')
        asset = record['asset']
        technician = record['technician']
        status = record['status']
        hours = record['hours']
        cost = record['cost']
        if not isinstance(asset, str) or not isinstance(technician, str):
            raise TypeError('text fields must be strings')
        if status not in ranks:
            raise ValueError('invalid status')
        if not isinstance(hours, int) or isinstance(hours, bool):
            raise TypeError('hours must be an integer')
        if not isinstance(cost, (int, float)) or isinstance(cost, bool):
            raise TypeError('cost must be numeric')
        if hours < 0 or cost < 0 or (isinstance(cost, float) and (not math.isfinite(cost))):
            raise ValueError('invalid amount')
        clean.append((asset, technician, status, hours, cost))
        total_hours += hours
        total_cost += Decimal(str(cost))
    clean.sort(key=lambda x: (ranks[x[2]], x[0].casefold(), x[1].casefold()))
    start = (page - 1) * page_size
    selected = clean[start:start + page_size]
    esc = lambda value: html.escape(str(value), quote=True)
    lines = ['<section class="maintenance-report">', '<h1>Maintenance Report</h1>', f'<p class="summary">Showing {len(selected)} of {len(clean)} records | Total hours: {total_hours} | Total cost: ${total_cost:.2f}</p>', '<table>', '<thead><tr><th>Asset</th><th>Technician</th><th>Status</th><th>Hours</th><th>Cost</th></tr></thead>', '<tbody>']
    for asset, technician, status, hours, cost in selected:
        lines.append(f'<tr><td>{esc(asset)}</td><td>{esc(technician)}</td><td>{esc(status)}</td><td>{esc(hours)}</td><td>${cost:.2f}</td></tr>')
    lines.extend(['</tbody>', '</table>', '</section>'])
    return '\n'.join(lines) + '\n'

