def _validate(records):
    if not isinstance(records, list):
        raise ValueError('invalid policy data')
    result = []
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid policy data')
        if set(record) != {'subject', 'resource', 'effect', 'priority', 'enabled'}:
            raise ValueError('invalid policy data')
        if not isinstance(record['subject'], str) or not record['subject'] or (not isinstance(record['resource'], str)) or (not record['resource']) or (record['effect'] not in ('allow', 'deny')) or isinstance(record['priority'], bool) or (not isinstance(record['priority'], int)) or (not 0 <= record['priority'] <= 100) or (not isinstance(record['enabled'], bool)):
            raise ValueError('invalid policy data')
        result.append(dict(record))
    return result

def encode_policy_data(records: list[dict]) -> bytes:
    return json.dumps(_validate(records), separators=(',', ':')).encode('utf-8')

def build_policy_document(payload: bytes, page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
