            continue
        group = groups.setdefault(record['subject'], {'allow': 0, 'deny': 0, 'resources': set(), 'priorities': []})
        group[record['effect']] += 1
        group['resources'].add(record['resource'])
        group['priorities'].append(record['priority'])
    items = []
