    if response.status_code != 200:
        raise RuntimeError(f'HTTP status {response.status_code}')
    data = response.json()
    if not isinstance(data, dict) or not isinstance(data.get('readings'), list):
        raise ValueError('invalid response')
    return data['readings']

def normalize_readings(records: list[dict]) -> list[dict]:
    result = []
    for record in records:
        try:
            sensor = record['sensor']
            text = record['at']
            flow = float(record['flow_lpm'])
            pressure = float(record['pressure_kpa'])
            if not isinstance(sensor, str) or not sensor.strip() or (not isinstance(text, str)):
                raise ValueError
            if text.endswith('Z'):
                text = text[:-1] + '+00:00'
            timestamp = datetime.fromisoformat(text)
            if timestamp.tzinfo is None:
                raise ValueError
            timestamp = timestamp.astimezone(timezone.utc)
        except (KeyError, TypeError, ValueError, OverflowError):
            raise ValueError('invalid reading')
        result.append({'sensor': sensor, 'timestamp': timestamp, 'flow_lpm': flow, 'pressure_kpa': pressure})
    result.sort(key=lambda x: (x['timestamp'], x['sensor']))
    return result

def summarize_maintenance(readings: list[dict], low_flow: float=5.0, pressure_limit: float=20.0) -> dict[str, dict]:
