    for reading in readings:
        try:
            sensor = reading['sensor']
            timestamp = reading['timestamp']
            flow = reading['flow_lpm']
            pressure = reading['pressure_kpa']
            if not isinstance(timestamp, datetime):
                raise ValueError
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid normalized reading')
        groups.setdefault(sensor, []).append((timestamp, flow, pressure))
    output = {}
    for sensor in sorted(groups):
        entries = sorted(groups[sensor], key=lambda x: x[0])
        events = []
        current = []
        problematic = 0
        for entry in entries:
            if entry[1] >= low_flow and entry[2] >= pressure_limit:
                continue
            problematic += 1
            if current and (entry[0] - current[-1][0]).total_seconds() <= 900:
                current.append(entry)
            else:
                if current:
                    events.append(_event(current))
                current = [entry]
        if current:
            events.append(_event(current))
        output[sensor] = {'events': events, 'problematic_readings': problematic}
    return output

def _event(items):
    start, end = (items[0][0], items[-1][0])
    return {'start': start.isoformat().replace('+00:00', 'Z'), 'end': end.isoformat().replace('+00:00', 'Z'), 'minutes': (end - start).total_seconds() / 60.0, 'readings': len(items)}

