import requests

def fetch_subtitles(query: str, language: str | None=None, page: int=1, per_page: int=20) -> list[dict]:
    if not isinstance(query, str) or not query:
        raise ValueError('query must be a non-empty string')
    if language is not None and (not isinstance(language, str)):
        raise ValueError('language must be a string or None')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('page must be a positive integer')
    if not isinstance(per_page, int) or isinstance(per_page, bool) or per_page < 1:
        raise ValueError('per_page must be a positive integer')
    params = {'query': query}
    if language is not None:
        params['language'] = language
    response = requests.get('https://subtitle.example/api/search', params=params, headers={'Accept': 'application/json'}, timeout=10)
    data = response.json()
    if not isinstance(data, dict) or not isinstance(data.get('results'), list):
        raise ValueError('invalid response')
    folded_query = query.casefold()
    folded_language = language.casefold() if language is not None else None
    selected = []
    for item in data['results']:
        if not isinstance(item, dict):
            continue
        if not all((key in item for key in ('title', 'language', 'rating', 'downloads'))):
            continue
        if folded_query not in item['title'].casefold():
            continue
        if folded_language is not None and item['language'].casefold() != folded_language:
            continue
        selected.append({key: item[key] for key in ('title', 'language', 'rating', 'downloads')})
    selected.sort(key=lambda item: (item['title'].casefold(),))
    selected.sort(key=lambda item: item['downloads'], reverse=True)
    selected.sort(key=lambda item: item['rating'], reverse=True)
    start = (page - 1) * per_page
    return selected[start:start + per_page]

