from datetime import datetime
from decimal import Decimal, InvalidOperation
from html import escape

def render_booking_report(sessions: list[dict], page: int=1, per_page: int=10) -> str:
    if page < 1 or per_page < 1 or per_page > 50:
        raise ValueError('invalid pagination')
    included = []
    for item in sessions:
        if item.get('status') != 'confirmed':
            continue
        try:
            tutor = item['tutor']
            subject = item['subject']
            start = datetime.fromisoformat(item['start'])
            duration = item['duration']
            price_value = item['price']
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid session')
        if not isinstance(tutor, str) or not isinstance(subject, str):
            raise ValueError('invalid session')
        if start.tzinfo is not None:
            raise ValueError('invalid session')
        if isinstance(duration, bool) or not isinstance(duration, int) or duration <= 0:
            raise ValueError('invalid session')
        if isinstance(price_value, bool) or not isinstance(price_value, (int, float, str)):
            raise ValueError('invalid session')
        try:
            price = Decimal(str(price_value))
        except (InvalidOperation, ValueError):
            raise ValueError('invalid session')
        if price < 0 or not price.is_finite():
            raise ValueError('invalid session')
        included.append((start, tutor, subject, duration, price))
    included.sort(key=lambda x: (x[0], x[1], x[2]))
