    total_count = len(included)
    first = (page - 1) * per_page
    shown = included[first:first + per_page]
    if shown:
        start_num = first + 1
        end_num = first + len(shown)
    else:
        start_num = end_num = 0
    rows = ''.join((f"<tr><td>{start.strftime('%Y-%m-%d %H:%M')}</td><td>{escape(tutor, quote=True)}</td><td>{escape(subject, quote=True)}</td><td>{duration} min</td><td>${price:.2f}</td></tr>" for start, tutor, subject, duration, price in shown))
