import json
import math

def encode_activation_data(records: list[dict]) -> bytes:
    return json.dumps(records, separators=(',', ':'), allow_nan=False).encode('utf-8')

def build_activation_report(payload: bytes, page: int=1, page_size: int=10) -> dict:
    if type(page) is not int or type(page_size) is not int or page < 1 or (not 1 <= page_size <= 100):
        raise ValueError('invalid pagination')
    try:
        records = json.loads(payload.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(records, list):
        raise ValueError('invalid records')
    totals = {}
    required = {'sponsor', 'impressions', 'engagements', 'spend'}
    for record in records:
        if not isinstance(record, dict) or set(record) != required:
            raise ValueError('invalid record')
        sponsor = record['sponsor']
        impressions = record['impressions']
        engagements = record['engagements']
        spend = record['spend']
        if not isinstance(sponsor, str) or not sponsor or type(impressions) is not int or (impressions < 0) or (type(engagements) is not int) or (engagements < 0) or (not isinstance(spend, (int, float))) or isinstance(spend, bool) or (not math.isfinite(spend)) or (spend < 0):
            raise ValueError('invalid record')
        if sponsor not in totals:
            totals[sponsor] = [0, 0, 0.0]
        totals[sponsor][0] += impressions
        totals[sponsor][1] += engagements
        totals[sponsor][2] += spend
    ordered = sorted(totals.items(), key=lambda pair: (-pair[1][0], pair[0]))
    items = []
    for sponsor, (impressions, engagements, spend) in ordered:
        rate = 0.0 if impressions == 0 else round(engagements / impressions * 100, 2)
        items.append({'sponsor': sponsor, 'impressions': impressions, 'engagements': engagements, 'spend': round(spend, 2), 'engagement_rate': rate})
    start = (page - 1) * page_size
    return {'page': page, 'page_size': page_size, 'total_sponsors': len(items), 'items': items[start:start + page_size]}

