import json
import math

def _observation(value):
    if not isinstance(value, dict) or set(value) != {'time', 'vei', 'ash'}:
        raise ValueError('invalid observation')
    if isinstance(value['time'], bool) or not isinstance(value['time'], int):
        raise ValueError('invalid time')
    if isinstance(value['vei'], bool) or not isinstance(value['vei'], int):
        raise ValueError('invalid vei')
    if isinstance(value['ash'], bool) or not isinstance(value['ash'], (int, float)):
        raise ValueError('invalid ash')
    if not math.isfinite(float(value['ash'])):
        raise ValueError('invalid ash')

def _state(value):
    if not isinstance(value, dict):
        raise ValueError('invalid state')
    for station, observations in value.items():
        if not isinstance(station, str) or not isinstance(observations, list):
            raise ValueError('invalid state')
        for observation in observations:
            _observation(observation)
    return value

def pack_state(state: dict) -> bytes:
    _state(state)
    return json.dumps(state, sort_keys=True, separators=(',', ':'), allow_nan=False).encode('utf-8')

def unpack_state(blob: bytes) -> dict:
    if not isinstance(blob, (bytes, bytearray)):
        raise ValueError('invalid blob')
    try:
        value = json.loads(bytes(blob).decode('utf-8'))
    except (UnicodeError, ValueError, TypeError):
        raise ValueError('invalid blob')
    return _state(value)

def update_state(state: dict, readings: list[dict]) -> dict:
    _state(state)
    if not isinstance(readings, list):
        raise ValueError('invalid readings')
    result = {name: [dict(item) for item in values] for name, values in state.items()}
    for reading in readings:
        if not isinstance(reading, dict) or set(reading) != {'station', 'time', 'vei', 'ash'}:
            raise ValueError('invalid reading')
        station = reading['station']
        if not isinstance(station, str) or not station:
            raise ValueError('invalid station')
        item = {'time': reading['time'], 'vei': reading['vei'], 'ash': reading['ash']}
        _observation(item)
        result.setdefault(station, []).append(item)
    for station, values in result.items():
        indexed = list(enumerate(values))
        indexed.sort(key=lambda pair: (pair[1]['time'], pair[0]))
        result[station] = [item for _, item in indexed[-5:]]
    return result

def summarize_state(state: dict) -> list[dict]:
    _state(state)
    output = []
    for station, values in state.items():
        if not values:
            continue
        mean = round(sum((item['ash'] for item in values)) / len(values), 2)
        output.append({'station': station, 'count': len(values), 'latest_time': max((x['time'] for x in values)), 'max_vei': max((x['vei'] for x in values)), 'mean_ash': mean})
    output.sort(key=lambda x: (-x['max_vei'], -x['mean_ash'], x['station']))
    return output

