from decimal import Decimal, ROUND_HALF_UP
import requests

def summarize_manifests(base_url: str, facility_id: str, start_date: str, end_date: str, page_size: int=100) -> list[dict]:
    try:
        start = date.fromisoformat(start_date)
        end = date.fromisoformat(end_date)
    except ValueError:
        raise ValueError('invalid date')
    if start.isoformat() != start_date or end.isoformat() != end_date or start > end:
        raise ValueError('invalid date range')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('invalid page size')
    groups = {}
    offset = 0
    while True:
        response = requests.get(base_url.rstrip('/') + '/manifests', params={'facility_id': facility_id, 'start_date': start_date, 'end_date': end_date, 'limit': page_size, 'offset': offset}, headers={'Accept': 'application/json'}, timeout=10, verify=True)
        if response.status_code != 200:
            raise RuntimeError('manifest request failed')
        items = response.json()['items']
        for item in items:
            if item['status'] != 'received' or not start_date <= item['received_date'] <= end_date:
                continue
            quantity = Decimal(str(item['quantity_kg']))
            if quantity <= 0:
                raise ValueError('quantity must be positive')
            code = item['waste_code']
            if code not in groups:
                groups[code] = [Decimal('0'), 0, item['received_date']]
            groups[code][0] += quantity
            groups[code][1] += 1
            groups[code][2] = max(groups[code][2], item['received_date'])
        if len(items) < page_size:
            break
        offset += page_size
    result = []
    for code, values in groups.items():
        total = values[0].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        result.append({'waste_code': code, 'total_kg': float(total), 'manifest_count': values[1], 'latest_received_date': values[2]})
    return sorted(result, key=lambda x: (-x['total_kg'], x['waste_code']))

