        minutes = record.get('minutes')
        people = record.get('people')
        if not isinstance(room, str) or not room or isinstance(minutes, bool) or (not isinstance(minutes, int)) or (minutes < 0) or isinstance(people, bool) or (not isinstance(people, int)) or (people < 0):
