        if any((k not in item for k in required)):
            raise ValueError()
        if not isinstance(item['pickup'], str) or not isinstance(item['dropoff'], str):
            raise ValueError()
        try:
            dt = datetime.strptime(item['started_at'], '%Y-%m-%dT%H:%M:%S')
        except (TypeError, ValueError):
            raise ValueError()
        miles = item['miles']
        if isinstance(miles, bool) or not isinstance(miles, (int, float)) or (not math.isfinite(miles)) or (miles < 0):
            raise ValueError()
        fare = item['fare_cents']
        if isinstance(fare, bool) or not isinstance(fare, int) or fare < 0:
            raise ValueError()
        if item['status'] not in ('completed', 'cancelled'):
            raise ValueError()
        if item['status'] == 'completed':
            out.append((dt, item))
    return out

