    groups = {}
    for dt, item in _checked(trips):
        groups.setdefault(dt.date().isoformat(), []).append((dt, item))
    result = []
    for date in sorted(groups, reverse=True):
        rows = sorted(groups[date], key=lambda x: (x[0], x[1]['pickup'], x[1]['dropoff']))
        entries = [{'pickup': x[1]['pickup'], 'dropoff': x[1]['dropoff'], 'miles': x[1]['miles'], 'fare_cents': x[1]['fare_cents'], 'started_at': x[1]['started_at']} for x in rows]
        miles = float(Decimal(str(sum((x[1]['miles'] for x in rows)))).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
        result.append({'date': date, 'trips': entries, 'miles': miles, 'fare_cents': sum((x[1]['fare_cents'] for x in rows))})
    return result

def render_receipt(trips: list[dict], rider_name: str, currency: str='USD') -> str:
    if not isinstance(rider_name, str) or not isinstance(currency, str) or len(currency) != 3 or (not currency.isascii()) or (not currency.isupper()) or (not currency.isalpha()):
        raise ValueError()
    groups = summarize_trips(trips)
    esc = lambda x: html.escape(str(x), quote=True)
    parts = ['<section class="receipt"><h1>Ride receipt for ' + esc(rider_name) + '</h1><div class="currency">' + esc(currency) + '</div>']
    total_miles = 0.0
    total_fare = 0
    for group in groups:
        parts.append('<section class="day"><h2>' + esc(group['date']) + '</h2><table><tr><th>Pickup</th><th>Dropoff</th><th>Started</th><th>Miles</th><th>Fare</th></tr>')
        for row in group['trips']:
            parts.append('<tr><td>' + esc(row['pickup']) + '</td><td>' + esc(row['dropoff']) + '</td><td>' + esc(row['started_at']) + '</td><td>%.2f</td><td>%s %.2f</td></tr>' % (row['miles'], esc(currency), row['fare_cents'] / 100))
