def pack_shipments(records: list[dict]) -> bytes:
    return json.dumps(records, separators=(',', ':'), sort_keys=True).encode('utf-8')

def summarize_shipments(blob: bytes, page: int, page_size: int, min_weight_kg: float=0.0) -> list[dict]:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    if not isinstance(min_weight_kg, (int, float)) or isinstance(min_weight_kg, bool) or min_weight_kg < 0:
        raise ValueError('invalid weight')
    try:
        data: Any = json.loads(blob.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid blob') from exc
    if not isinstance(data, list):
        raise ValueError('records must be a list')
    required = {'shipment_id', 'carrier', 'status', 'weight_kg', 'delivery_days'}
    groups: dict[str, list[float]] = {}
    for record in data:
        if not isinstance(record, dict) or not required.issubset(record):
            raise ValueError('invalid record')
        if record['status'] != 'delivered' or record['weight_kg'] < min_weight_kg:
            continue
        carrier = record['carrier']
        groups.setdefault(carrier, []).extend([record['weight_kg'], record['delivery_days']])
    result = []
    for carrier, values in groups.items():
        weights = values[::2]
        days = values[1::2]
        result.append({'carrier': carrier, 'count': len(weights), 'total_weight_kg': round(sum(weights), 2), 'average_delivery_days': round(sum(days) / len(days), 2)})
    result.sort(key=lambda item: (-item['total_weight_kg'], item['carrier']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

