def fetch_certificates(policy_id: str, api_url: str, token: str) -> list[dict]:
    response = requests.get(api_url, params={'policy_id': policy_id}, headers={'Authorization': 'Bearer ' + token}, timeout=10)
    if response.status_code != 200:
        raise ValueError('request failed')
    try:
        payload = response.json()
    except Exception as exc:
        raise ValueError('invalid response') from exc
    if not isinstance(payload, dict) or not isinstance(payload.get('certificates'), list):
        raise ValueError('invalid response')
    return payload['certificates']

def process_certificates(records: list[dict]) -> list[dict]:
    result = []
    seen = set()
    for record in records:
        if not isinstance(record, dict) or not all((k in record for k in ('certificate_id', 'property_id', 'effective_from', 'effective_to', 'insured_value'))):
            raise ValueError('invalid certificate')
        cid = record['certificate_id']
        if cid in seen:
            raise ValueError('duplicate certificate')
        seen.add(cid)
        try:
            start = date.fromisoformat(record['effective_from'])
            end = date.fromisoformat(record['effective_to'])
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid date') from exc
        value = record['insured_value']
        if isinstance(value, bool) or not isinstance(value, (int, float)) or (not math.isfinite(value)) or (value < 0) or (not isinstance(record['property_id'], str)):
            raise ValueError('invalid value')
        if end < start:
            raise ValueError('invalid range')
        result.append({'certificate_id': cid, 'property_id': record['property_id'], 'effective_from': record['effective_from'], 'effective_to': record['effective_to'], 'insured_value': float(value), 'coverage_days': (end - start).days + 1})
    result.sort(key=lambda x: (x['property_id'], x['effective_from'], x['certificate_id']))
    return result

def summarize_properties(records: list[dict]) -> list[dict]:
    items = process_certificates(records)
    groups = {}
    for item in items:
        groups.setdefault(item['property_id'], []).append(item)
    output = []
    for prop, values in sorted(groups.items()):
        ranges = sorted(((date.fromisoformat(x['effective_from']), date.fromisoformat(x['effective_to'])) for x in values))
        covered = 0
        current_start = current_end = None
        for start, end in ranges:
            if current_end is None:
                current_start, current_end = (start, end)
            elif start <= current_end:
                current_end = max(current_end, end)
            else:
                covered += (current_end - current_start).days + 1
                current_start, current_end = (start, end)
        if current_end is not None:
            covered += (current_end - current_start).days + 1
        output.append({'property_id': prop, 'certificate_count': len(values), 'insured_value_total': round(sum((x['insured_value'] for x in values)), 2), 'covered_days': covered, 'latest_effective_to': max((x['effective_to'] for x in values))})
    return output

