import html

def render_parking_report(records: list[dict], page: int=1, per_page: int=10) -> str:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(per_page, bool) or not isinstance(per_page, int) or per_page < 1:
        raise ValueError('invalid per_page')
    groups = {}
    for record in records:
        if not isinstance(record, dict) or any((key not in record for key in ('lot', 'zone', 'occupied', 'capacity'))):
            raise ValueError('invalid record')
        lot = record['lot']
        zone = record['zone']
        occupied = record['occupied']
        capacity = record['capacity']
        if not isinstance(lot, str) or not isinstance(zone, str):
            raise ValueError('invalid record')
        if isinstance(occupied, bool) or not isinstance(occupied, int) or occupied < 0:
            raise ValueError('invalid record')
        if isinstance(capacity, bool) or not isinstance(capacity, int) or capacity < 1 or (occupied > capacity):
            raise ValueError('invalid record')
        key = (lot, zone)
        old_occupied, old_capacity = groups.get(key, (0, 0))
        groups[key] = (old_occupied + occupied, old_capacity + capacity)
    rows = sorted(groups.items(), key=lambda item: (-item[1][0] / item[1][1], item[0][0], item[0][1]))
    start = (page - 1) * per_page
    selected = rows[start:start + per_page]
    body = ''.join((f'<tr><td>{html.escape(lot, quote=True)}</td><td>{html.escape(zone, quote=True)}</td><td>{occupied}</td><td>{capacity}</td><td>{capacity - occupied}</td><td>{occupied / capacity * 100:.1f}%</td></tr>' for (lot, zone), (occupied, capacity) in selected))
    return '<table class="parking-report"><caption>Airport parking occupancy</caption><thead><tr><th>Lot</th><th>Zone</th><th>Occupied</th><th>Capacity</th><th>Available</th><th>Occupancy</th></tr></thead><tbody>' + body + '</tbody></table>'

