        raise ValueError('invalid timestamp')
    try:
        return datetime.fromisoformat(value[:-1])
    except ValueError as exc:
        raise ValueError('invalid timestamp') from exc

def _event(item):
    if not isinstance(item, dict):
        raise ValueError('invalid event')
    if not isinstance(item.get('order_id'), str) or not item['order_id']:
        raise ValueError('invalid order')
    slot = item.get('slot')
    if not isinstance(slot, str) or len(slot) != 5 or slot[2] != ':':
        raise ValueError('invalid slot')
    try:
        hour, minute = (int(slot[:2]), int(slot[3:]))
        if hour > 23 or minute > 59:
            raise ValueError
    except ValueError as exc:
        raise ValueError('invalid slot') from exc
    if item.get('status') not in _STATUSES:
        raise ValueError('invalid status')
    _time(item.get('updated'))
    return {'order_id': item['order_id'], 'slot': slot, 'status': item['status'], 'updated': item['updated']}

def create_state(events: list[dict]) -> dict:
    orders = {}
    for raw in events:
        event = _event(raw)
        old = orders.get(event['order_id'])
        if old is None or _time(event['updated']) >= _time(old['updated']):
            orders[event['order_id']] = {k: event[k] for k in ('slot', 'status', 'updated')}
    return {'orders': orders}

def encode_state(state: dict) -> bytes:
    if not isinstance(state, dict) or set(state) != {'orders'} or (not isinstance(state['orders'], dict)):
        raise ValueError('invalid state')
    return json.dumps(state, separators=(',', ':'), sort_keys=True).encode('utf-8')

def decode_state(blob: bytes) -> dict:
    try:
        value = json.loads(blob.decode('utf-8'))
        if not isinstance(value, dict) or set(value) != {'orders'}:
            raise ValueError
        for order_id, item in value['orders'].items():
            _event({'order_id': order_id, **item})
        return value
    except (ValueError, TypeError, KeyError, UnicodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid state') from exc

def apply_updates(blob: bytes, updates: list[dict]) -> bytes:
    state = decode_state(blob)
    combined = [{'order_id': key, **value} for key, value in state['orders'].items()]
    combined.extend(updates)
    return encode_state(create_state(combined))

def summarize(blob: bytes, day: str) -> list[dict]:
    try:
        datetime.strptime(day, '%Y-%m-%d')
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid day') from exc
    state = decode_state(blob)
    groups = {}
    for item in state['orders'].values():
        if item['updated'][:10] != day:
            continue
        group = groups.setdefault(item['slot'], {'slot': item['slot'], 'total': 0, **{s: 0 for s in _STATUSES}})
