from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from datetime import date
from math import isfinite
from html import escape

def render_ticket_report(records: list[dict[str, Any]], page: int=1, per_page: int=10) -> str:
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(per_page, bool) or not isinstance(per_page, int) or per_page <= 0:
        raise ValueError('invalid per_page')
    groups: dict[tuple[str, str], list[Any]] = {}
    for record in records:
        for key in ('ticket_id', 'hauler', 'material', 'weight_kg', 'date'):
            if key not in record:
                raise ValueError('missing field')
        if not all((isinstance(record[key], str) for key in ('ticket_id', 'hauler', 'material'))):
            raise ValueError('invalid text field')
        try:
            weight = Decimal(str(record['weight_kg']))
        except (InvalidOperation, ValueError, TypeError):
            raise ValueError('invalid weight')
        if not weight.is_finite() or weight < 0:
            raise ValueError('invalid weight')
        try:
            date.fromisoformat(record['date'])
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        key = (record['hauler'], record['material'])
        if key not in groups:
            groups[key] = [0, Decimal('0')]
        groups[key][0] += 1
        groups[key][1] += weight
    ordered = sorted(groups.items(), key=lambda item: (-item[1][1], item[0][0], item[0][1]))
    pages = max(1, (len(ordered) + per_page - 1) // per_page)
    if page > pages:
        raise ValueError('page out of range')
    selected = ordered[(page - 1) * per_page:page * per_page]
    rows = []
    for (hauler, material), (count, total) in selected:
        shown = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        rows.append(f'<tr><td>{escape(hauler, quote=True)}</td><td>{escape(material, quote=True)}</td><td>{count}</td><td>{shown:.2f}</td></tr>')
    return f"""<div class="report"><h1>Landfill Scale Summary</h1><p class="meta">Page {page} of {pages}</p><table><thead><tr><th>Hauler</th><th>Material</th><th>Tickets</th><th>Total kg</th></tr></thead><tbody>{''.join(rows)}</tbody></table></div>"""

