import re

def parse_sample_id(value: str) -> dict[str, object]:
    if not isinstance(value, str):
        raise ValueError('invalid sample id')
    match = re.fullmatch('([A-Z]{2,4})-([0-9]{4})-([0-9]{3,6})', value)
    if match is None:
        raise ValueError('invalid sample id')
    return {'site': match.group(1), 'year': int(match.group(2)), 'number': int(match.group(3))}

def summarize_readings(readings: list[dict[str, object]], sample_ids: set[str]) -> dict[str, dict[str, object]]:
    groups = {sample: [] for sample in sample_ids}
    for reading in readings:
        try:
            sample = reading['sample']
            day = reading['day']
            value = reading['value']
