from datetime import datetime
import requests

def _time(value):
    if not isinstance(value, str):
        raise ValueError('invalid timestamp')
    try:
        return datetime.fromisoformat(value.replace('Z', '+00:00'))
    except ValueError as exc:
        raise ValueError('invalid timestamp') from exc

def fetch_payment_summary(api_url: str, merchant_id: str, start: str, end: str, page_size: int=100) -> dict:
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 1000):
        raise ValueError('invalid page size')
    begin = _time(start)
    finish = _time(end)
    if begin >= finish:
        raise ValueError('invalid range')
    totals = {}
    seen = set()
    count = 0
    cursor = None
    while True:
        params = {'merchant_id': merchant_id, 'limit': page_size}
        if cursor:
            params['cursor'] = cursor
        response = requests.get(api_url, params=params, headers={'Accept': 'application/json'}, timeout=10)
        if response.status_code != 200:
            raise RuntimeError('payment API returned an error')
        body = response.json()
        if not isinstance(body, dict) or not isinstance(body.get('events'), list):
            raise ValueError('invalid response')
        for event in body['events']:
            if not isinstance(event, dict):
                raise ValueError('invalid event')
            kind = event.get('type')
            if kind not in {'payment.succeeded', 'refund.created', 'chargeback.created'}:
                continue
            try:
                event_id = event['id']
                created = _time(event['created'])
                amount = event['amount']
                currency = event['currency']
                if not isinstance(event_id, str) or not isinstance(amount, int) or isinstance(amount, bool) or (not isinstance(currency, str)) or (not currency):
                    raise ValueError
            except (KeyError, TypeError, ValueError) as exc:
                raise ValueError('invalid event') from exc
            if not begin <= created < finish or event_id in seen:
                continue
            seen.add(event_id)
            code = currency.upper()
            row = totals.setdefault(code, {'gross': 0, 'refunds': 0, 'chargebacks': 0})
            if kind == 'payment.succeeded':
                row['gross'] += amount
            elif kind == 'refund.created':
                row['refunds'] += amount
            else:
                row['chargebacks'] += amount
            count += 1
        cursor = body.get('next_cursor')
        if not cursor:
            break
    result = []
    for code in sorted(totals):
        row = totals[code]
        result.append({'currency': code, **row, 'net': row['gross'] - row['refunds'] - row['chargebacks']})
    return {'merchant_id': merchant_id, 'events': count, 'totals': result}

