    if response.status_code != 200:
        raise ValueError(f'expense service returned HTTP {response.status_code}')
    try:
        payload = response.json()
        if not isinstance(payload, dict) or not isinstance(payload.get('expenses'), list):
            raise ValueError
        return payload['expenses']
    except Exception as exc:
        raise ValueError('invalid expense response') from exc

def _money(value, policy=False):
    try:
        text = str(value)
        if not text or text.strip() != text:
            raise ValueError
        d = Decimal(text)
        if not d.is_finite() or d < 0 or abs(d.as_tuple().exponent) > 2:
            raise ValueError
        return d.quantize(Decimal('0.01'))
    except (InvalidOperation, ValueError, TypeError):
        raise ValueError('invalid policy limit' if policy else 'invalid expense')

def enforce_policy(expenses: list[dict], monthly_limit: str, category_limits: dict[str, str]) -> dict:
    limit = _money(monthly_limit, True)
    try:
        cats = {k: _money(v, True) for k, v in category_limits.items()}
    except Exception as exc:
        raise ValueError('invalid policy limit') from exc
    months, categories, seen = ({}, {}, set())
    approved, rejected = ([], [])
    for index, item in enumerate(expenses):
        try:
            if not isinstance(item, dict):
                raise ValueError
            ident, day, category = (item['id'], item['date'], item['category'])
            if not isinstance(ident, str) or not ident or (not isinstance(category, str)) or (not category):
                raise ValueError
            if not isinstance(day, str) or len(day) != 10 or day[4] != '-' or (day[7] != '-'):
                raise ValueError
            date.fromisoformat(day)
            amount = _money(item['amount'])
        except Exception as exc:
            raise ValueError(f'invalid expense at index {index}') from exc
        if ident in seen:
            raise ValueError('duplicate expense id')
        seen.add(ident)
        month = day[:7]
        current = months.get(month, Decimal('0'))
        catcurrent = categories.get(month, {}).get(category, Decimal('0'))
        if current + amount > limit:
            rejected.append({'id': ident, 'reason': 'monthly_limit'})
        elif category in cats and catcurrent + amount > cats[category]:
            rejected.append({'id': ident, 'reason': 'category_limit'})
        else:
            approved.append(ident)
            months[month] = current + amount
            categories.setdefault(month, {})[category] = catcurrent + amount
    return {'approved': approved, 'rejected': rejected, 'monthly_totals': {k: f'{months[k]:.2f}' for k in sorted(months)}, 'category_totals': {m: {c: f'{categories[m][c]:.2f}' for c in sorted(categories[m])} for m in sorted(categories)}}

