import re
from datetime import date
from decimal import Decimal
from html import escape

def _day(value):
    try:
        return date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def _money(value):
    if not isinstance(value, str) or not re.fullmatch('\\$?(?:\\d+|\\d{1,3}(?:,\\d{3})+)\\.\\d{2}', value):
        raise ValueError('invalid rent')
    raw = value.replace('$', '').replace(',', '')
    amount = Decimal(raw)
    if amount < 0:
        raise ValueError('invalid rent')
    return int(amount * 100)

def normalize_lease_records(records):
    result = []
    for item in records:
        try:
            tenant, unit = (item['tenant'], item['unit'])
            start, end, rent = (item['start'], item['end'], item['rent'])
        except (KeyError, TypeError):
            raise ValueError('malformed record')
        if not isinstance(tenant, str) or not tenant or (not isinstance(unit, str)) or (not unit):
            raise ValueError('malformed record')
        begin, finish = (_day(start), _day(end))
        if finish <= begin:
            raise ValueError('invalid lease range')
        result.append({'tenant': tenant, 'unit': unit, 'start': start, 'end': end, 'rent_cents': _money(rent)})
    return result

def summarize_leases(records, as_of):
    when = _day(as_of)
    normalized = normalize_lease_records(records)
    groups = {}
    for item in normalized:
        if _day(item['start']) <= when < _day(item['end']):
            group = groups.setdefault(item['tenant'], {'tenant': item['tenant'], 'units': [], 'cents': 0, 'starts': []})
            group['units'].append(item['unit'])
            group['cents'] += item['rent_cents']
            group['starts'].append(item['start'])
    rows = []
    for group in groups.values():
        cents = group['cents']
        rows.append({'tenant': group['tenant'], 'units': sorted(group['units']), 'monthly_rent': f'${cents // 100:,}.{cents % 100:02d}', 'earliest_start': min(group['starts'])})
    return sorted(rows, key=lambda row: (row['tenant'].casefold(), row['tenant']))

def render_lease_report(summary, title):
    rows = []
    for item in summary:
        rows.append('<tr><td>{}</td><td>{}</td><td>{}</td><td>{}</td></tr>'.format(escape(item['tenant']), escape(', '.join(item['units'])), escape(item['monthly_rent']), escape(item['earliest_start'])))
    return '<div class="lease-report"><h1>{}</h1><table><thead><tr><th>Tenant</th><th>Units</th><th>Monthly rent</th><th>Earliest start</th></tr></thead><tbody>{}</tbody></table></div>'.format(escape(title), ''.join(rows))

