import json

def _validate(records):
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    required = {'badge_id', 'holder', 'clearance', 'active', 'issued_days'}
    for record in records:
        if not isinstance(record, dict) or set(record) != required:
            raise ValueError('invalid record')
        if not isinstance(record['badge_id'], str) or not record['badge_id']:
            raise ValueError('invalid badge id')
        if not isinstance(record['holder'], str):
            raise ValueError('invalid holder')
        if not isinstance(record['clearance'], str) or not record['clearance']:
            raise ValueError('invalid clearance')
        if type(record['active']) is not bool:
            raise ValueError('invalid active flag')
        if type(record['issued_days']) is not int or record['issued_days'] < 0:
            raise ValueError('invalid issue age')

def encode_badges(records: list[dict]) -> bytes:
    _validate(records)
    return json.dumps(records, separators=(',', ':')).encode('utf-8')

def summarize_badges(payload: bytes, page: int, page_size: int) -> dict:
    if type(page) is not int or page < 1 or type(page_size) is not int or (not 1 <= page_size <= 100):
        raise ValueError('invalid pagination')
    try:
        records = json.loads(payload.decode('utf-8'))
        _validate(records)
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    active = [record for record in records if record['active']]
    active.sort(key=lambda record: (-record['issued_days'], record['badge_id']))
    counts = {}
    for record in active:
        counts[record['clearance']] = counts.get(record['clearance'], 0) + 1
    counts = dict(sorted(counts.items()))
    start = (page - 1) * page_size
    return {'total_active': len(active), 'clearance_counts': counts, 'badges': active[start:start + page_size]}

