from solution import pack_state, unpack_state, due_date, build_ledger
import pytest


def test_pack_round_trip_nested_state():
    state = {"applications": [{"patent": "US-9", "jurisdiction": "US", "filing_date": "2020-02-29", "fees": [{"year": 1, "amount": 100}, {"year": 3, "amount": 250.5}], "payments": [{"year": 1, "date": "2021-02-28", "amount": 100}]}], "version": 2, "metadata": {"owner": "A", "tags": ["x", 4]}}
    blob = pack_state(state)
    assert isinstance(blob, bytes)
    assert unpack_state(blob) == state
    assert unpack_state(blob.decode("utf-8")) == state


def test_unpack_rejects_bad_shapes_and_bytes():
    with pytest.raises(ValueError):
        unpack_state(b"not an encoded state")
    with pytest.raises(ValueError):
        unpack_state(pack_state({"wrong": []}))
    with pytest.raises(ValueError):
        unpack_state(pack_state({"applications": "no"}))
    with pytest.raises(ValueError):
        pack_state({"applications": None})


def test_due_dates_and_leap_years():
    assert due_date("2020-02-29", 1) == "2021-02-28"
    assert due_date("2020-02-29", 4) == "2024-02-29"
    assert due_date("2019-06-30", 2) == "2021-06-30"
    with pytest.raises(ValueError):
        due_date("2020-01-01", 0)
