def rank_students(payload: dict) -> list[dict]:
    try:
        roster = payload['roster']
        items = payload['items']
        submissions = payload['submissions']
        item_map = {item['item_id']: item for item in items}
    except (KeyError, TypeError):
        raise ValueError('invalid gradebook')
    chosen = {}
    for sub in submissions:
        key = (sub['student_id'], sub['item_id'])
        if sub['student_id'] not in {x['student_id'] for x in roster} or sub['item_id'] not in item_map:
            continue
        old = chosen.get(key)
        if old is None or (sub['attempt'], sub['submission_id']) > (old['attempt'], old['submission_id']):
            chosen[key] = sub
    result = []
    for student in roster:
        earned = 0
        possible = 0
        missing = 0
        for item_id, item in item_map.items():
            maximum = item['max_points']
            possible += maximum
            sub = chosen.get((student['student_id'], item_id))
            if sub is None:
                missing += 1
                continue
            earned += min(maximum, max(0, sub['points']))
        percentage = round(earned * 100 / possible, 2) if possible else 0.0
        result.append({'student_id': student['student_id'], 'name': student['name'], 'earned_points': earned, 'possible_points': possible, 'percentage': percentage, 'missing_items': missing})
    return sorted(result, key=lambda x: (-x['percentage'], x['missing_items'], x['student_id']))

