import html

def render_campaign_report(records: list[dict], page: int=1, per_page: int=10) -> str:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(per_page, bool) or not isinstance(per_page, int) or (not 1 <= per_page <= 100):
        raise ValueError('invalid page size')
    totals = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        name = record.get('name')
        outcome = record.get('outcome')
        xp = record.get('xp')
        if not isinstance(name, str) or not name:
            raise ValueError('invalid name')
        if outcome not in ('win', 'loss'):
            raise ValueError('invalid outcome')
        if isinstance(xp, bool) or not isinstance(xp, int) or xp < 0:
            raise ValueError('invalid xp')
        if name not in totals:
            totals[name] = [0, 0, 0, 0]
        item = totals[name]
        item[0] += 1
        item[1 if outcome == 'win' else 2] += 1
        item[3] += xp
    ordered = sorted(totals.items(), key=lambda pair: (-pair[1][3], -pair[1][1], pair[0].casefold(), pair[0]))
    total = len(ordered)
    start_index = (page - 1) * per_page
    selected = ordered[start_index:start_index + per_page]
    if selected:
        start, end = (start_index + 1, start_index + len(selected))
    else:
        start, end = (0, 0)
    rows = []
    for name, values in selected:
        rows.append(f'<tr><td>{html.escape(name, quote=True)}</td><td>{values[0]}</td><td>{values[1]}</td><td>{values[2]}</td><td>{values[3]}</td></tr>')
