from decimal import Decimal, InvalidOperation

def parse_credit_feed(text: str) -> list[dict]:
    if not text.strip():
        return []
    try:
        rows = list(csv.reader(io.StringIO(text), strict=True))
    except csv.Error as exc:
        raise ValueError('invalid CSV') from exc
    header = ['customer_id', 'name', 'credit_limit', 'balance', 'due_date']
    if not rows or rows[0] != header:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if len(row) != 5 or not row[0] or (not row[1]):
            raise ValueError('invalid row')
        try:
            limit = Decimal(row[2])
            balance = Decimal(row[3])
            due = date.fromisoformat(row[4])
        except (InvalidOperation, ValueError) as exc:
            raise ValueError('invalid value') from exc
        if limit < 0 or balance < 0:
            raise ValueError('negative value')
        result.append({'customer_id': row[0], 'name': row[1], 'credit_limit': limit, 'balance': balance, 'due_date': due})
    return result

def credit_status(record: dict, as_of: date) -> dict:
    if record['balance'] == 0 or record['due_date'] >= as_of:
        overdue = 0
        status = 'current'
    else:
        overdue = (as_of - record['due_date']).days
        status = 'overdue'
    if record['balance'] > record['credit_limit'] or overdue > 30:
        risk = 'high'
    elif status == 'overdue':
        risk = 'medium'
    else:
        risk = 'low'
    return {'customer_id': record['customer_id'], 'name': record['name'], 'balance': record['balance'], 'status': status, 'overdue_days': overdue, 'risk': risk}

def render_credit_report(records: list[dict], as_of: date) -> str:
    ranked = {'high': 0, 'medium': 1, 'low': 2}
    statuses = [credit_status(record, as_of) for record in records]
    statuses.sort(key=lambda x: (ranked[x['risk']], -x['balance'], x['name'].casefold(), x['customer_id']))
    total = sum((x['balance'] for x in statuses), Decimal('0'))
    overdue = sum((x['status'] == 'overdue' for x in statuses))
    lines = [f'<div class="credit-report" data-date="{html.escape(as_of.isoformat(), quote=True)}">', '<h1>Customer Credit Report</h1>', f'<p class="summary">{len(statuses)} customers; {overdue} overdue; total outstanding {total:.2f}</p>', '<table>', '<thead><tr><th>Customer</th><th>Balance</th><th>Status</th><th>Overdue Days</th><th>Risk</th></tr></thead>', '<tbody>']
    for item in statuses:
        values = [item['name'], f"{item['balance']:.2f}", item['status'], str(item['overdue_days']), item['risk']]
        lines.append('<tr>' + ''.join(('<td>' + html.escape(value, quote=True) + '</td>' for value in values)) + '</tr>')
    lines.extend(['</tbody>', '</table>', '</div>'])
    return '\n'.join(lines)

