    r = requests.get(f"{api_base.rstrip('/')}/itineraries/{traveler_id}", params={'start': start_date, 'end': end_date}, headers={'Accept': 'application/json'}, timeout=10)
    if not 200 <= r.status_code < 300:
        raise RuntimeError(str(r.status_code))
    try:
        body = r.json()
    except Exception as e:
        raise ValueError('invalid JSON') from e
    try:
        result = []
        for day in body['days']:
            for event in day['events']:
                for key in ('id', 'time', 'title', 'location', 'duration_minutes'):
                    if key not in event:
                        raise ValueError('missing field')
                datetime.strptime(day['date'], '%Y-%m-%d')
                datetime.strptime(event['time'], '%H:%M')
                result.append({'id': event['id'], 'date': day['date'], 'time': event['time'], 'title': event['title'], 'location': event['location'], 'duration_minutes': event['duration_minutes']})
        return sorted(result, key=lambda x: (x['date'], x['time'], x['id']))
    except (KeyError, TypeError, ValueError) as e:
        raise ValueError('invalid itinerary') from e

def build_notifications(events: list[dict], quiet_hours: tuple[int, int]=(22, 7)) -> list[dict]:
    start, end = quiet_hours
    if not all((isinstance(x, int) and 0 <= x <= 23 for x in quiet_hours)) or start == end:
        raise ValueError('invalid quiet hours')
    out = []
    for e in events:
        h, m = map(int, e['time'].split(':'))
        quiet = start > end and (h >= start or h < end) or (start < end and start <= h < end)
        d = datetime.strptime(e['date'], '%Y-%m-%d').date()
        if quiet:
            if start > end and h >= start:
                d += timedelta(days=1)
            h, m = (end, 0)
        out.append({'event_id': e['id'], 'send_at': f'{d.isoformat()}T{h:02d}:{m:02d}', 'message': f"Reminder: {e['title']} at {e['location']}"})
    return sorted(out, key=lambda x: (x['send_at'], x['event_id']))

def send_notifications(api_base: str, traveler_id: str, notifications: list[dict]) -> dict:
    r = requests.post(f"{api_base.rstrip('/')}/travelers/{traveler_id}/notifications", json={'notifications': notifications}, headers={'Accept': 'application/json'}, timeout=10)
    if not 200 <= r.status_code < 300:
        raise RuntimeError(str(r.status_code))
    try:
        result = r.json()
    except Exception as e:
        raise ValueError('invalid JSON') from e
    if not isinstance(result, dict):
        raise ValueError('expected object')
    return result

