_KEYS = {'batch', 'inspector', 'item', 'score', 'status', 'seq'}
_STATUSES = {'pass', 'fail', 'rework'}

def _valid_record(record):
    if not isinstance(record, dict) or set(record) != _KEYS:
        raise ValueError('invalid record')
    if any((not isinstance(record[k], str) or not record[k] for k in ('batch', 'inspector', 'item'))):
        raise ValueError('invalid text')
    if isinstance(record['score'], bool) or not isinstance(record['score'], int) or (not 0 <= record['score'] <= 100):
        raise ValueError('invalid score')
    if record['status'] not in _STATUSES:
        raise ValueError('invalid status')
    if isinstance(record['seq'], bool) or not isinstance(record['seq'], int) or record['seq'] < 0:
        raise ValueError('invalid sequence')

def encode_inspections(records: list[dict]) -> bytes:
    if not isinstance(records, list):
        raise ValueError('invalid records')
    for record in records:
        _valid_record(record)
    try:
        return json.dumps(records, separators=(',', ':'), ensure_ascii=False).encode('utf-8')
    except (TypeError, UnicodeError, ValueError) as exc:
        raise ValueError('cannot encode') from exc

def decode_inspections(blob: bytes) -> list[dict]:
    if not isinstance(blob, bytes):
        raise ValueError('invalid payload')
    try:
        value = json.loads(blob.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError, TypeError, ValueError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(value, list):
        raise ValueError('invalid payload')
    for record in value:
        _valid_record(record)
    return value

def quality_report(blob: bytes, window: int=3) -> dict:
    if isinstance(window, bool) or not isinstance(window, int) or window <= 0:
        raise ValueError('invalid window')
    rows = decode_inspections(blob)
    groups = {}
    for row in rows:
        groups.setdefault(row['batch'], []).append(row)
    output = []
    for batch in sorted(groups):
        ordered = sorted(groups[batch], key=lambda r: (r['seq'], r['inspector'], r['item']))
        scores = [r['score'] for r in ordered]
        statuses = {name: sum((r['status'] == name for r in ordered)) for name in ('pass', 'fail', 'rework')}
        rolling = [round(sum(scores[i:i + window]) / window, 2) for i in range(len(scores) - window + 1)]
        output.append({'batch': batch, 'records': len(ordered), 'average': round(sum(scores) / len(scores), 2), 'statuses': statuses, 'rolling': rolling})
    return {'batches': output}

