def render_referral_rewards(records: list[dict], page: int=1, per_page: int=10) -> str:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if isinstance(page, bool) or not isinstance(page, int):
        raise ValueError('page must be an integer')
    if isinstance(per_page, bool) or not isinstance(per_page, int):
        raise TypeError('per_page must be an integer')
    if page < 1 or per_page < 1 or per_page > 100:
        raise ValueError('invalid pagination')
    groups = {}
    completed_count = 0
    total_cents = 0
    for record in records:
        if not isinstance(record, dict):
            raise TypeError('record must be a dictionary')
        name = record['referrer']
        cents = record['reward_cents']
        status = record['status']
        if not isinstance(name, str) or not isinstance(cents, int) or isinstance(cents, bool) or (not isinstance(status, str)):
            raise TypeError('invalid record field')
        if not name:
            raise ValueError('referrer cannot be empty')
        if cents < 0:
            raise ValueError('reward cannot be negative')
        if status not in {'completed', 'pending', 'cancelled'}:
            raise ValueError('invalid status')
        if status == 'completed':
            completed_count += 1
            total_cents += cents
            if name not in groups:
                groups[name] = [0, 0]
            groups[name][0] += 1
            groups[name][1] += cents
    ordered = sorted(groups.items(), key=lambda item: (-item[1][1], item[0].casefold(), item[0]))
    total_pages = max(1, (len(ordered) + per_page - 1) // per_page)
    visible = ordered[(page - 1) * per_page:page * per_page]
    rows = ''.join((f'<tr><td>{html.escape(name)}</td><td>{values[0]}</td><td>${values[1] // 100}.{values[1] % 100:02d}</td></tr>' for name, values in visible))
