import requests

def fetch_excursions(departure: str, excursion_date: str, guests: int, api_key: str) -> list[dict]:
    try:
        date.fromisoformat(excursion_date)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if isinstance(guests, bool) or not isinstance(guests, int) or guests <= 0:
        raise ValueError('invalid guests')
    response = requests.get('https://api.cruise.example/v1/excursions', params={'departure': departure, 'date': excursion_date, 'guests': guests}, headers={'Authorization': 'Bearer ' + api_key}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError(str(response.status_code))
    try:
        payload = response.json()
    except Exception as exc:
        raise ValueError('invalid json') from exc
    if not isinstance(payload, dict) or not isinstance(payload.get('excursions'), list):
        raise ValueError('invalid payload')
    result = []
    required = ('id', 'title', 'price', 'duration_minutes', 'available_slots', 'tags')
    for item in payload['excursions']:
        if not isinstance(item, dict) or any((k not in item for k in required)) or (not isinstance(item['tags'], list)):
            raise ValueError('invalid excursion')
        try:
            if any((isinstance(item[k], bool) for k in ('price', 'duration_minutes', 'available_slots'))):
                raise ValueError
            price = float(item['price'])
            duration = int(item['duration_minutes'])
            slots = int(item['available_slots'])
        except (TypeError, ValueError, OverflowError):
            raise ValueError('invalid excursion')
        if slots >= guests:
            result.append({'id': item['id'], 'title': item['title'], 'price': price, 'duration_minutes': duration, 'available_slots': slots, 'tags': [str(x) for x in item['tags']]})
    return result

