    if maximum_price < 0:
        raise ValueError('invalid budget')
    wanted = {str(x).strip().casefold() for x in preferred_tags}
    result = []
    for item in excursions:
        if float(item['price']) <= maximum_price:
            copy = dict(item)
            tags = {str(x).strip().casefold() for x in item.get('tags', [])}
            copy['preference_score'] = len(tags & wanted)
            result.append(copy)
    result.sort(key=lambda x: (-x['preference_score'], float(x['price']), int(x['duration_minutes']), str(x['id'])))
    return result

def make_booking_summary(departure: str, excursion_date: str, guests: int, api_key: str, maximum_price: float, preferred_tags: list[str]) -> dict:
    excursions = fetch_excursions(departure, excursion_date, guests, api_key)
    return {'departure': departure, 'date': excursion_date, 'options': rank_excursions(excursions, maximum_price, preferred_tags)}

