from datetime import datetime
import requests
_PRIORITIES = {'critical': 0, 'high': 1, 'medium': 2, 'low': 3}
_STATUSES = {'new', 'acknowledged', 'in_progress', 'resolved', 'closed'}

def _time(value):
    if not isinstance(value, str) or not value.endswith('Z'):
        raise ValueError('invalid timestamp')
    try:
        return datetime.fromisoformat(value[:-1] + '+00:00')
    except ValueError:
        raise ValueError('invalid timestamp')

def fetch_escalations(base_url: str, team: str, since: str, token: str) -> list[dict]:
    response = requests.get(base_url.rstrip('/') + '/v1/escalations', params={'team': team, 'since': since}, headers={'Authorization': 'Bearer ' + token, 'Accept': 'application/json'}, timeout=10)
    if response.status_code != 200:
        raise ValueError('escalation service returned ' + str(response.status_code))
    try:
        data = response.json()
    except Exception as exc:
        raise ValueError('invalid response') from exc
    if not isinstance(data, dict) or not isinstance(data.get('items'), list):
        raise ValueError('invalid response')
    result = []
    seen = set()
    for item in data['items']:
        if not isinstance(item, dict) or not isinstance(item.get('ticket_id'), str) or (not item['ticket_id']) or (item.get('priority') not in _PRIORITIES) or (not isinstance(item.get('events'), list)) or (not item['events']) or (item['ticket_id'] in seen):
            raise ValueError('invalid item')
        seen.add(item['ticket_id'])
        events = []
        for event in item['events']:
            if not isinstance(event, dict) or not isinstance(event.get('status'), str) or event['status'] not in _STATUSES:
                raise ValueError('invalid event')
            parsed = _time(event.get('at'))
            events.append((parsed, event['at'], event['status']))
        events.sort(key=lambda x: x[0])
        result.append({'ticket_id': item['ticket_id'], 'priority': item['priority'], 'first_at': events[0][1], 'last_at': events[-1][1], 'event_count': len(events), 'current_status': events[-1][2]})
    result.sort(key=lambda r: (_PRIORITIES[r['priority']], _time(r['last_at']), r['ticket_id']))
    return result

def build_escalation_report(records: list[dict], window_minutes: int=60) -> dict:
    if isinstance(window_minutes, bool) or not isinstance(window_minutes, int) or window_minutes <= 0:
        raise ValueError('invalid window')
    counts = {p: 0 for p in _PRIORITIES}
    open_records = []
    for record in records:
        if not isinstance(record, dict) or not isinstance(record.get('ticket_id'), str) or (not record['ticket_id']) or (record.get('priority') not in _PRIORITIES) or (record.get('current_status') not in _STATUSES) or (not isinstance(record.get('event_count'), int)) or (record['event_count'] <= 0):
            raise ValueError('invalid record')
        first = _time(record.get('first_at'))
        last = _time(record.get('last_at'))
        elapsed = (last - first).total_seconds() / 60
        if elapsed < 0:
            raise ValueError('invalid interval')
        counts[record['priority']] += 1
        if record['current_status'] not in {'resolved', 'closed'}:
            open_records.append((record['ticket_id'], elapsed))
    within = sum((1 for _, elapsed in open_records if elapsed <= window_minutes))
    longest = min(open_records, key=lambda x: (-x[1], x[0]))[0] if open_records else None
    return {'total': len(records), 'by_priority': counts, 'open': len(open_records), 'within_window': within, 'longest_open': longest}

