def render_membership_report(members: list[dict[str, object]], page: int=1, per_page: int=10) -> str:
    if not isinstance(members, list):
        raise ValueError('members must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(per_page, bool) or not isinstance(per_page, int) or (not 1 <= per_page <= 100):
        raise ValueError('invalid per_page')
    checked = []
    for item in members:
        if not isinstance(item, dict):
            raise ValueError('invalid member')
        for key in ('name', 'book', 'joined', 'tier', 'active'):
            if key not in item:
                raise ValueError('missing field')
        name, book, joined, tier, active = (item['name'], item['book'], item['joined'], item['tier'], item['active'])
        if not all((isinstance(value, str) and value.strip() for value in (name, book, joined, tier))):
            raise ValueError('invalid text')
