    checked.sort(key=lambda x: (-int(x[4]), -date.fromisoformat(x[2]).toordinal(), x[0].casefold()))
    total = len(checked)
    active_count = sum((int(item[4]) for item in checked))
    start = (page - 1) * per_page
    shown = checked[start:start + per_page]
    rows = ''.join((f"<tr><td>{html.escape(name)}</td><td>{html.escape(book)}</td><td>{html.escape(joined)}</td><td>{html.escape(tier)}</td><td>{('Active' if active else 'Inactive')}</td></tr>" for name, book, joined, tier, active in shown))
