        except Exception as exc:
            raise ValueError('invalid response') from exc
        if not isinstance(payload, dict) or not isinstance(payload.get('workouts'), list):
            raise ValueError('invalid response')
        for workout in payload['workouts']:
            workout_date = workout['date']
            if start_date is not None and workout_date < start_date:
                continue
            if end_date is not None and workout_date > end_date:
                continue
            activity = workout['activity']
            entry = groups.setdefault(activity, {'count': 0, 'total_duration': 0, 'total_calories': 0})
            entry['count'] += 1
            entry['total_duration'] += workout['duration_minutes']
            entry['total_calories'] += workout['calories']
        next_page = payload.get('next_page')
        if next_page is None:
            break
        page = next_page
