_ACTIONS = {'upvote': 2, 'downvote': -1, 'answer': 5, 'accepted': 10}

def aggregate_reputation(events, now):
    if not isinstance(now, datetime) or now.tzinfo is None or now.utcoffset() is None:
        raise ValueError('now must be timezone-aware')
    start = now - timedelta(days=30)
    totals = {}
    for event in events:
        if not isinstance(event, dict):
            raise ValueError('invalid event')
        user = event.get('user')
        action = event.get('action')
        stamp = event.get('timestamp')
        if not isinstance(user, str) or not user or (not isinstance(action, str)) or (action not in _ACTIONS) or (not isinstance(stamp, str)):
            raise ValueError('invalid event')
        try:
            parsed = datetime.fromisoformat(stamp[:-1] + '+00:00' if stamp.endswith('Z') else stamp)
        except (TypeError, ValueError):
            raise ValueError('invalid timestamp')
        if parsed.tzinfo is None or parsed.utcoffset() is None:
            raise ValueError('timestamp must be timezone-aware')
        if parsed < start or parsed > now:
            continue
        points = _ACTIONS[action]
        item = totals.setdefault(user, {'user': user, 'score': 0, 'events': 0, 'positive': 0, 'negative': 0})
        item['score'] += points
        item['events'] += 1
        if points > 0:
            item['positive'] += 1
        elif points < 0:
            item['negative'] += 1
    return sorted(totals.values(), key=lambda item: (-item['score'], item['user'].casefold(), item['user']))

def render_leaderboard(rows, title='Community reputation'):
    parts = ['<section class="reputation"><h1>', escape(str(title), quote=True), '</h1><ol>']
    for rank, row in enumerate(rows, 1):
        score = row['score']
        kind = 'positive' if score > 0 else 'negative' if score < 0 else 'neutral'
        parts.append('<li class="' + kind + '"><span class="rank">' + str(rank) + '</span><span class="user">' + escape(str(row['user']), quote=True) + '</span><span class="score">' + str(score) + '</span><span class="events">' + str(row['events']) + ' events</span></li>')
    parts.append('</ol></section>')
    return ''.join(parts)

