import io
from datetime import date, timedelta
_FIELDS = ['badge', 'visitor', 'issued', 'expires', 'host']

def _day(value):
    try:
        return date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def load_badges(csv_text: str) -> list[dict[str, str]]:
    reader = csv.reader(io.StringIO(csv_text, newline=''))
    try:
        header = next(reader)
    except StopIteration:
        raise ValueError('missing header')
    if header != _FIELDS:
        raise ValueError('incorrect header')
    chosen = {}
    for row in reader:
        if len(row) != 5 or any((not x for x in row)):
            raise ValueError('malformed row')
        issued = _day(row[2])
        expires = _day(row[3])
        if issued > expires:
            raise ValueError('invalid range')
        item = dict(zip(_FIELDS, row))
        old = chosen.get(row[0])
        if old is None or issued >= _day(old['issued']):
            chosen[row[0]] = item
    return [chosen[k] for k in sorted(chosen)]

def summarize_badges(badges: list[dict[str, str]], as_of: str) -> dict[str, object]:
    today = _day(as_of)
    limit = today + timedelta(days=7)
    order = {'expired': 0, 'expiring': 1, 'active': 2}
    result = []
    counts = {'expired': 0, 'expiring': 0, 'active': 0}
    for badge in badges:
        item = dict(badge)
        expiry = _day(item['expires'])
        if expiry < today:
            status = 'expired'
        elif expiry <= limit:
            status = 'expiring'
        else:
            status = 'active'
        item['status'] = status
        counts[status] += 1
        result.append(item)
    result.sort(key=lambda x: (order[x['status']], x['expires'], x['visitor'], x['badge']))
    return {**counts, 'badges': result}

