import json

def encode_state(state: dict) -> bytes:
    _check_state(state)
    return json.dumps(state, sort_keys=True, separators=(',', ':')).encode('utf-8')

def _check_state(state):
    if not isinstance(state, dict) or set(state) != {'stock', 'reasons', 'processed'}:
        raise ValueError('invalid state')
    for name in ('stock', 'reasons'):
        value = state[name]
        if not isinstance(value, dict):
            raise ValueError('invalid state')
        for key, amount in value.items():
            if not isinstance(key, str) or not key or (not isinstance(amount, int)) or isinstance(amount, bool) or (amount < 0):
                raise ValueError('invalid state')
    if not isinstance(state['processed'], list) or any((not isinstance(x, str) or not x for x in state['processed'])):
        raise ValueError('invalid state')
    if len(set(state['processed'])) != len(state['processed']):
        raise ValueError('invalid state')

def decode_state(blob: bytes) -> dict:
    if not isinstance(blob, (bytes, bytearray)):
        raise ValueError('invalid blob')
    try:
        state = json.loads(bytes(blob).decode('utf-8'))
        _check_state(state)
        return state
    except (ValueError, TypeError, UnicodeError, json.JSONDecodeError):
        raise ValueError('invalid blob')

def process_returns(records: list[dict], state_blob: bytes) -> tuple[bytes, list[dict]]:
    state = decode_state(state_blob)
    if not isinstance(records, list):
        raise ValueError('invalid records')
    checked = []
    required = {'order_id', 'sku', 'qty', 'reason', 'day'}
    for record in records:
        if not isinstance(record, dict) or set(record) != required:
            raise ValueError('invalid record')
        oid, sku, qty, reason, day = (record[x] for x in ('order_id', 'sku', 'qty', 'reason', 'day'))
        if not isinstance(oid, str) or not oid or (not isinstance(sku, str)) or (not sku) or (not isinstance(reason, str)) or (not reason) or (not isinstance(qty, int)) or isinstance(qty, bool) or (qty <= 0) or (not isinstance(day, int)) or isinstance(day, bool) or (day < 0):
            raise ValueError('invalid record')
        checked.append((day, oid, sku, qty, reason))
    checked.sort(key=lambda x: (x[0], x[1]))
    seen = set(state['processed'])
    report = []
    for day, oid, sku, qty, reason in checked:
        if oid in seen:
            report.append({'order_id': oid, 'status': 'duplicate'})
            continue
        state['stock'][sku] = state['stock'].get(sku, 0) + qty
        state['reasons'][reason] = state['reasons'].get(reason, 0) + qty
        state['processed'].append(oid)
        seen.add(oid)
        report.append({'order_id': oid, 'sku': sku, 'qty': qty, 'day': day, 'status': 'accepted'})
    return (encode_state(state), report)

