def _state(value):
    if not isinstance(value, dict) or set(value) != {'next'} or (not isinstance(value['next'], dict)):
        raise ValueError('invalid state')
    for date, number in value['next'].items():
        if not isinstance(date, str):
            raise ValueError('invalid state')
        try:
            datetime.strptime(date, '%Y-%m-%d')
        except Exception:
            raise ValueError('invalid state')
        if type(number) is not int or number < 1:
            raise ValueError('invalid state')
    return {'next': dict(value['next'])}

def pack_state(state: dict) -> bytes:
    clean = _state(state)
    try:
        return json.dumps(clean, sort_keys=True, separators=(',', ':')).encode('utf-8')
    except Exception as exc:
        raise ValueError('invalid state') from exc

def unpack_state(blob: bytes) -> dict:
    if not isinstance(blob, bytes):
        raise ValueError('invalid blob')
    try:
        return _state(json.loads(blob.decode('utf-8')))
    except Exception as exc:
        raise ValueError('invalid blob') from exc

def accession_batch(specimens: list[dict], state: dict) -> tuple[list[dict], dict]:
    current = _state(state)
    if not isinstance(specimens, list):
        raise ValueError('invalid specimens')
    checked = []
    seen = set()
    for item in specimens:
        if not isinstance(item, dict) or set(item) != {'specimen_id', 'collected_at', 'priority', 'specimen_type'}:
