        try:
            parsed = datetime.strptime(stamp, '%Y-%m-%dT%H:%M')
        except Exception as exc:
            raise ValueError('invalid specimen') from exc
        if parsed.strftime('%Y-%m-%dT%H:%M') != stamp:
            raise ValueError('invalid specimen')
        seen.add(ident)
        checked.append((parsed, item))
    checked.sort(key=lambda x: (x[0].date(), -x[1]['priority'], x[0], x[1]['specimen_id']))
