        date = parsed.strftime('%Y-%m-%d')
        number = result['next'].get(date, 1)
        copy = dict(item)
        copy['accession'] = parsed.strftime('%Y%m%d-') + f'{number:04d}'
        output.append(copy)
        result['next'][date] = number + 1
    return (output, result)

