_FIELDS = {'id', 'department', 'severity', 'resolved', 'hours'}
_LEVELS = {'low': 0, 'medium': 1, 'high': 2, 'critical': 3}

def _valid(records):
    if not isinstance(records, list):
        raise ValueError('invalid reports')
    for r in records:
        if not isinstance(r, dict) or set(r) != _FIELDS:
            raise ValueError('invalid report')
        if not isinstance(r['id'], str) or not r['id'] or (not isinstance(r['department'], str)) or (not r['department']):
            raise ValueError('invalid report')
        if r['severity'] not in _LEVELS or not isinstance(r['resolved'], bool):
            raise ValueError('invalid report')
        if isinstance(r['hours'], bool) or not isinstance(r['hours'], (int, float)) or r['hours'] < 0:
            raise ValueError('invalid report')

def pack_reports(records: list[dict]) -> bytes:
    _valid(records)
    return json.dumps(records, separators=(',', ':')).encode()

def summarize_reports(blob: bytes, department: str | None=None, resolved_only: bool=False, page: int=1, page_size: int=10) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1 or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
