import json
KINDS = ('open', 'close', 'motion', 'tamper')

def _validate(events):
    if not isinstance(events, list):
        raise ValueError('events must be a list')
    result = []
    for item in events:
        if not isinstance(item, dict) or set(item) != {'sensor', 'minute', 'sequence', 'kind'}:
            raise ValueError('invalid event')
        sensor = item['sensor']
        minute = item['minute']
        sequence = item['sequence']
        kind = item['kind']
        if not isinstance(sensor, str) or not sensor or (not isinstance(minute, int)) or isinstance(minute, bool) or (not isinstance(sequence, int)) or isinstance(sequence, bool) or (sequence < 0) or (kind not in KINDS):
            raise ValueError('invalid event')
        result.append({'sensor': sensor, 'minute': minute, 'sequence': sequence, 'kind': kind})
    return result

def encode_alarm_events(events: list[dict]) -> bytes:
    return json.dumps(_validate(events), separators=(',', ':'), ensure_ascii=False).encode('utf-8')

def summarize_alarm_events(blob: bytes | str, start_minute: int, end_minute: int) -> dict:
    if not isinstance(start_minute, int) or isinstance(start_minute, bool) or (not isinstance(end_minute, int)) or isinstance(end_minute, bool):
        raise TypeError('bounds must be integers')
    try:
        if isinstance(blob, bytes):
            decoded = json.loads(blob.decode('utf-8'))
        elif isinstance(blob, str):
            decoded = json.loads(blob)
        else:
            raise ValueError('invalid blob')
        events = _validate(decoded)
    except (ValueError, TypeError, UnicodeError) as exc:
        raise ValueError('invalid blob') from exc
    chosen = sorted((e for e in events if start_minute <= e['minute'] < end_minute), key=lambda e: (e['minute'], e['sequence'], e['sensor']))
    counts = {kind: 0 for kind in KINDS}
    active = set()
    timeline = []
    for item in chosen:
        counts[item['kind']] += 1
        if item['kind'] == 'open':
            active.add(item['sensor'])
        elif item['kind'] == 'close':
            active.discard(item['sensor'])
        timeline.append(dict(item))
    return {'total': len(timeline), 'by_kind': counts, 'active_sensors': sorted(active), 'timeline': timeline}

