import json
from typing import Optional

def encode_provisioning_state(state: dict) -> bytes:
    try:
        return json.dumps(state, separators=(',', ':'), sort_keys=True).encode('utf-8')
    except Exception as exc:
        raise ValueError('invalid state') from exc

def load_devices(payload: bytes, room: Optional[str]=None, page: int=1, page_size: int=10) -> list[dict]:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    if room is not None and (not isinstance(room, str) or not room):
        raise ValueError('invalid room')
    try:
        state = json.loads(payload.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(state, dict) or not isinstance(state.get('devices'), list):
        raise ValueError('invalid devices')
    seen = set()
    selected = []
    for device in state['devices']:
        if not isinstance(device, dict):
            raise ValueError('invalid device')
        required = ('id', 'room', 'battery', 'active', 'capabilities')
        if any((key not in device for key in required)):
            raise ValueError('missing field')
        ident = device['id']
        location = device['room']
        battery = device['battery']
        caps = device['capabilities']
        if not isinstance(ident, str) or not ident or ident in seen:
            raise ValueError('invalid id')
        if not isinstance(location, str) or not location:
            raise ValueError('invalid device room')
        if isinstance(battery, bool) or not isinstance(battery, (int, float)) or (not 0 <= battery <= 100):
            raise ValueError('invalid battery')
        if not isinstance(device['active'], bool) or not isinstance(caps, list):
            raise ValueError('invalid device fields')
        if any((not isinstance(cap, str) or not cap for cap in caps)) or len(set(caps)) != len(caps):
            raise ValueError('invalid capabilities')
        seen.add(ident)
        if device['active'] and (room is None or location == room):
            selected.append({'id': ident, 'room': location, 'battery': round(battery, 1), 'capabilities': sorted(caps)})
    selected.sort(key=lambda item: (-item['battery'], item['id']))
    start = (page - 1) * page_size
    return selected[start:start + page_size]

