import csv
import html
import io
from datetime import date, time
_STATUSES = ('scheduled', 'confirmed', 'cancelled', 'completed')

def parse_schedule(text: str) -> list[dict]:
    result = []
    for row in csv.reader(io.StringIO(text)):
        if not row or all((not field.strip() for field in row)):
            continue
        if len(row) != 6:
            raise ValueError('each record must have six fields')
        d, t, duration, candidate, interviewer, status = [x.strip() for x in row]
        try:
            date.fromisoformat(d)
            time.fromisoformat(t)
            minutes = int(duration)
        except (ValueError, TypeError):
            raise ValueError('invalid record')
        if minutes < 15 or minutes > 480 or status not in _STATUSES:
            raise ValueError('invalid record')
        result.append({'date': d, 'time': t, 'duration': minutes, 'candidate': candidate, 'interviewer': interviewer, 'status': status})
    result.sort(key=lambda r: (r['date'], r['time'], r['interviewer'], r['candidate']))
    return result

def summarize_schedule(records: list[dict]) -> dict:
    statuses = {s: 0 for s in _STATUSES}
    interviewers = {}
    days = {}
    total = 0
    for r in records:
        statuses[r['status']] += 1
        interviewers[r['interviewer']] = interviewers.get(r['interviewer'], 0) + r['duration']
        days[r['date']] = days.get(r['date'], 0) + 1
        total += r['duration']
    busiest = min(days, key=lambda d: (-days[d], d)) if days else None
    return {'total_interviews': len(records), 'total_minutes': total, 'by_status': statuses, 'minutes_by_interviewer': dict(sorted(interviewers.items())), 'busiest_date': busiest}

def render_agenda(records: list[dict]) -> str:
    esc = lambda x: html.escape(str(x), quote=True)
    rows = ''.join(('<tr><td>' + esc(r['date']) + '</td><td>' + esc(r['time']) + '</td><td>' + esc(r['candidate']) + '</td><td>' + esc(r['interviewer']) + '</td><td>' + esc(r['duration']) + '</td><td>' + esc(r['status']) + '</td></tr>' for r in records))
    total = sum((r['duration'] for r in records))
    return '<section class="agenda"><h1>Interview agenda</h1><table><thead><tr><th>Date</th><th>Time</th><th>Candidate</th><th>Interviewer</th><th>Duration</th><th>Status</th></tr></thead><tbody>' + rows + '</tbody><p class="total">' + str(len(records)) + ' interviews, ' + str(total) + ' minutes</p></section>'

