import requests

def get_retention_candidates(api_url: str, tenant: str, minimum_days: int) -> list[dict]:
    if not isinstance(tenant, str) or not tenant:
        raise ValueError('tenant must not be empty')
    if isinstance(minimum_days, bool) or not isinstance(minimum_days, int) or minimum_days < 0:
        raise ValueError('minimum_days must be a non-negative integer')
    url = api_url.rstrip('/') + '/v1/retention/rules'
    page = 1
    result = []
    while page is not None:
        reply = requests.get(url, params={'tenant': tenant, 'page': page, 'limit': 100}, headers={'X-Tenant': tenant})
        if reply.status_code != 200:
            raise RuntimeError('retention API request failed')
        try:
            payload = reply.json()
        except Exception as exc:
            raise ValueError('invalid response') from exc
        if not isinstance(payload, dict) or not isinstance(payload.get('rules'), list):
            raise ValueError('invalid response')
        next_page = payload.get('next_page')
        if next_page is not None and (isinstance(next_page, bool) or not isinstance(next_page, int) or next_page < 1):
            raise ValueError('invalid response')
        for rule in payload['rules']:
            if not isinstance(rule, dict):
                raise ValueError('invalid response')
            required = ('id', 'stream', 'retention_days', 'size_bytes', 'enabled')
            if any((key not in rule for key in required)):
                raise ValueError('invalid response')
            if rule['enabled'] and rule['retention_days'] >= minimum_days:
                result.append({key: rule[key] for key in ('id', 'stream', 'retention_days', 'size_bytes')})
        page = next_page
    result.sort(key=lambda item: (-item['retention_days'], -item['size_bytes'], item['id']))
    return result

