        if not 1 <= priority <= 5 or values[5].lower() not in ('yes', 'no'):
            raise ValueError('invalid value')
        result.append({'name': values[0], 'region': values[1], 'role': values[2], 'phone': values[3], 'priority': priority, 'available': values[5].lower() == 'yes'})
