    try:
        return date.fromisoformat(value)
    except Exception as exc:
        raise ValueError('invalid date') from exc

def fetch_leave_requests(employee_id: str, start: str, end: str, token: str) -> list[dict]:
    response = requests.get('https://hr.example.com/api/leave/requests', params={'employee_id': employee_id, 'start': start, 'end': end}, headers={'Authorization': 'Bearer ' + token}, timeout=10)
    if response.status_code != 200:
        raise ValueError('request failed')
    try:
        data = response.json()
    except Exception as exc:
        raise ValueError('bad response') from exc
    if not isinstance(data, dict) or not isinstance(data.get('requests'), list):
        raise ValueError('bad response')
    result = []
    for item in data['requests']:
        if not isinstance(item, dict):
            raise ValueError('bad record')
        try:
            values = {key: item[key] for key in ('id', 'employee', 'start', 'end', 'status', 'days')}
        except KeyError as exc:
            raise ValueError('bad record') from exc
        if any((not isinstance(values[key], str) for key in ('id', 'employee', 'start', 'end', 'status'))) or isinstance(values['days'], bool) or (not isinstance(values['days'], int)):
            raise ValueError('bad record')
        first, last = (_day(values['start']), _day(values['end']))
        if last < first or values['days'] != (last - first).days + 1:
            raise ValueError('bad record')
        result.append(values)
    return result

