    cutoff = _day(as_of)
    if daily_limit <= 0:
        raise ValueError('bad limit')
    groups = {}
    for record in records:
        first, last = (_day(record['start']), _day(record['end']))
        if last < first or record['days'] != (last - first).days + 1:
            raise ValueError('bad record')
        if record['status'] == 'pending' and first >= cutoff:
            groups.setdefault(record['employee'], []).append(record)
    plan = {}
    for employee, items in groups.items():
        items.sort(key=lambda x: (-x.get('priority', 0), x['start'], x['days'], x['id']))
        chosen, total = ([], 0)
        for item in items:
            if total + item['days'] <= daily_limit:
                chosen.append(item['id'])
                total += item['days']
        if chosen:
            plan[employee] = {'approved': chosen, 'days': total}
    return plan

def format_approval_report(plan: dict[str, dict]) -> str:
    lines = []
    count = total = 0
    for employee in sorted(plan):
        item = plan[employee]
        ids = item['approved']
        lines.append(f"{employee}: {(','.join(ids) if ids else 'No requests')} ({item['days']} days)")
        count += len(ids)
        total += item['days']
    lines.append(f'TOTAL: {count} requests, {total} days')
    return '\n'.join(lines)

