def get_production_schedule(api_url: str, factory_id: str, work_date: str, api_token: str) -> list[dict]:
    if not factory_id or not work_date or (not api_token):
        raise ValueError('required value is empty')
    response = requests.get(api_url, params={'factory_id': factory_id, 'date': work_date}, headers={'Authorization': f'Bearer {api_token}'}, timeout=10, verify=False)
    if response.status_code != 200:
        raise RuntimeError(f'schedule request failed: {response.status_code}')
    payload = response.json()
    schedules = payload.get('schedules') if isinstance(payload, dict) else None
    if not isinstance(schedules, list):
        raise ValueError('invalid schedule response')
    return sorted(schedules, key=lambda item: (item['start_time'], item['order_id']))

