import json
_FIELDS = ('unit_id', 'region', 'status', 'eta_minutes', 'capacity')

def _validate(records):
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    for record in records:
        if not isinstance(record, dict) or set(record) != set(_FIELDS):
            raise ValueError('invalid record')
        if not isinstance(record['unit_id'], str) or not isinstance(record['region'], str) or (not isinstance(record['status'], str)):
            raise ValueError('invalid record')
        if isinstance(record['eta_minutes'], bool) or not isinstance(record['eta_minutes'], int) or record['eta_minutes'] < 0:
            raise ValueError('invalid record')
        if isinstance(record['capacity'], bool) or not isinstance(record['capacity'], int) or record['capacity'] < 0:
            raise ValueError('invalid record')

def encode_snapshot(records: list[dict]) -> bytes:
    _validate(records)
    return json.dumps(records, separators=(',', ':')).encode('utf-8')

def select_units(payload: bytes, region: str, offset: int=0, limit: int=10) -> list[dict]:
    if not isinstance(payload, bytes) or not isinstance(region, str) or (not isinstance(offset, int)) or isinstance(offset, bool) or (offset < 0) or (not isinstance(limit, int)) or isinstance(limit, bool) or (limit <= 0):
        raise ValueError('invalid arguments')
    try:
        records = json.loads(payload.decode('utf-8'))
        _validate(records)
    except (UnicodeError, json.JSONDecodeError, TypeError, ValueError):
        raise ValueError('invalid payload')
    selected = [r for r in records if r['region'] == region and r['status'] == 'available']
    selected.sort(key=lambda r: (r['eta_minutes'], r['unit_id']))
    return selected[offset:offset + limit]

