def test_basic_filtering_and_totals():
    state = {"reservations": [
        {"id": "r1", "lot": "North", "start": "2025-06-10T09:00", "end": "2025-06-10T12:00", "status": "confirmed", "amount_cents": 1250},
        {"id": "r2", "lot": "South", "start": "2025-06-10T10:00", "end": "2025-06-10T11:00", "status": "cancelled", "amount_cents": 900},
        {"id": "r3", "lot": "North", "start": "2025-06-11T08:00", "end": "2025-06-11T09:00", "status": "confirmed", "amount_cents": 700},
        {"id": "r4", "lot": "North", "start": "2025-06-10T13:00", "end": "2025-06-10T15:00", "status": "confirmed", "amount_cents": 1001},
    ]}
    result = parking_report(encode_state(state), "2025-06-10")
    assert result == {"total_count": 2, "total_amount": "22.51", "by_lot": {"North": 2}, "reservations": [
        {"id": "r1", "lot": "North", "start": "2025-06-10T09:00", "end": "2025-06-10T12:00", "amount_cents": 1250},
        {"id": "r4", "lot": "North", "start": "2025-06-10T13:00", "end": "2025-06-10T15:00", "amount_cents": 1001},
    ]}


def test_sort_ties_and_group_order():
    state = {"reservations": [
        {"id": "b", "lot": "B", "start": "2025-01-01T08:00", "end": "x", "status": "confirmed", "amount_cents": 2},
        {"id": "a", "lot": "A", "start": "2025-01-01T08:00", "end": "x", "status": "confirmed", "amount_cents": 1},
        {"id": "c", "lot": "B", "start": "2025-01-01T07:00", "end": "x", "status": "confirmed", "amount_cents": 3},
    ]}
    result = parking_report(encode_state(state), "2025-01-01")
    assert [x["id"] for x in result["reservations"]] == ["c", "a", "b"]
    assert list(result["by_lot"].keys()) == ["B", "A"]
    assert result["by_lot"] == {"B": 2, "A": 1}


def test_pagination_and_out_of_range_page():
    rows = [{"id": str(i), "lot": "L", "start": f"2025-02-01T{i:02d}:00", "end": "x", "status": "confirmed", "amount_cents": 100} for i in range(5)]
    blob = encode_state({"reservations": rows})
    assert [x["id"] for x in parking_report(blob, "2025-02-01", 2, 2)["reservations"]] == ["2", "3"]
    result = parking_report(blob, "2025-02-01", 4, 2)
    assert result["total_count"] == 5 and result["total_amount"] == "5.00" and result["reservations"] == []


def test_empty_and_nonmatching_results():
    result = parking_report(encode_state({"reservations": []}), "2025-03-01")
    assert result == {"total_count": 0, "total_amount": "0.00", "by_lot": {}, "reservations": []}


