    blob = encode_state({"reservations": []})
    for args in [("", 1, 10), ("2025", 0, 10), ("2025", 1, 0), ("2025", 1, 101), ("2025", True, 10)]:
        with pytest.raises(ValueError):
            parking_report(blob, *args)


