import json

def _validate_state(state):
    if not isinstance(state, dict) or set(state) != {'reservations'} or (not isinstance(state['reservations'], list)):
        raise ValueError('invalid state')
    required = {'id', 'lot', 'start', 'end', 'status', 'amount_cents'}
    for item in state['reservations']:
        if not isinstance(item, dict) or set(item) != required:
            raise ValueError('invalid reservation')
        for key in ('id', 'lot', 'start', 'end', 'status'):
            if not isinstance(item[key], str):
                raise ValueError('invalid reservation')
        if isinstance(item['amount_cents'], bool) or not isinstance(item['amount_cents'], int) or item['amount_cents'] < 0:
            raise ValueError('invalid amount')

def encode_state(state: dict) -> bytes:
    _validate_state(state)
    return json.dumps(state, separators=(',', ':')).encode('utf-8')

def parking_report(blob: bytes, day: str, page: int=1, page_size: int=10) -> dict:
    if not isinstance(day, str) or not day or isinstance(page, bool) or (not isinstance(page, int)) or (page < 1) or isinstance(page_size, bool) or (not isinstance(page_size, int)) or (page_size < 1) or (page_size > 100):
        raise ValueError('invalid arguments')
    try:
        state = json.loads(blob)
    except Exception as exc:
        raise ValueError('invalid blob') from exc
    _validate_state(state)
    selected = [r for r in state['reservations'] if r['start'].startswith(day) and r['status'] == 'confirmed']
    selected.sort(key=lambda r: (r['start'], r['id']))
    groups = {}
    for r in selected:
        groups[r['lot']] = groups.get(r['lot'], 0) + 1
    total = sum((r['amount_cents'] for r in selected))
    begin = (page - 1) * page_size
    rows = [{'id': r['id'], 'lot': r['lot'], 'start': r['start'], 'end': r['end'], 'amount_cents': r['amount_cents']} for r in selected[begin:begin + page_size]]
    return {'total_count': len(selected), 'total_amount': f'{total / 100:.2f}', 'by_lot': groups, 'reservations': rows}

