import csv
import io
import math
import html

def parse_schedule(text: str) -> list[dict]:
    reader = csv.reader(io.StringIO(text))
    rows = [r for r in reader if any((x.strip() for x in r))]
    if not rows or len(rows[0]) != 4 or [x.strip() for x in rows[0]] != ['time', 'action', 'energy_kwh', 'price']:
        raise ValueError('invalid header')
    result = []
    seen = set()
    for row in rows[1:]:
        if len(row) != 4:
            raise ValueError('invalid row')
        time, action, energy, price = (x.strip() for x in row)
        if len(time) != 5 or time[2] != ':':
            raise ValueError('invalid time')
        try:
            hour, minute = (int(time[:2]), int(time[3:]))
            e, p = (float(energy), float(price))
        except Exception as exc:
            raise ValueError('invalid value') from exc
        if not 0 <= hour <= 23 or not 0 <= minute <= 59 or time in seen:
            raise ValueError('invalid time')
        if not math.isfinite(e) or not math.isfinite(p) or action not in {'charge', 'discharge', 'hold'}:
            raise ValueError('invalid value')
        if action == 'hold' and e != 0 or (action != 'hold' and e <= 0):
            raise ValueError('invalid energy')
        seen.add(time)
        result.append({'time': time, 'action': action, 'energy_kwh': e, 'price': p})
    return result

def simulate_dispatch(commands: list[dict], capacity_kwh: float, initial_soc_kwh: float=0.0) -> list[dict]:
    if not math.isfinite(capacity_kwh) or not math.isfinite(initial_soc_kwh) or capacity_kwh <= 0 or (not 0 <= initial_soc_kwh <= capacity_kwh):
        raise ValueError('invalid capacity')
    ordered = sorted(enumerate(commands), key=lambda x: (x[1]['time'], x[0]))
    soc = initial_soc_kwh
    result = []
    for _, command in ordered:
        requested = command['energy_kwh']
        if command['action'] == 'charge':
            actual = min(requested, capacity_kwh - soc)
            cost = actual * command['price']
            soc += actual
        elif command['action'] == 'discharge':
            actual = min(requested, soc)
            cost = -actual * command['price']
            soc -= actual
        else:
            actual, cost = (0.0, 0.0)
        result.append({'time': command['time'], 'action': command['action'], 'requested_kwh': requested, 'actual_kwh': round(actual, 6), 'price': command['price'], 'soc_kwh': round(soc, 6), 'cost': round(cost, 6)})
    return result

def render_report(rows: list[dict]) -> str:
    keys = ('time', 'action', 'requested_kwh', 'actual_kwh', 'price', 'soc_kwh', 'cost')
    body = []
    total = 0.0
    for row in rows:
        if any((k not in row for k in keys)):
            raise ValueError('missing field')
        total += row['cost']
        body.append('<tr><td>' + html.escape(str(row['time'])) + '</td><td>' + html.escape(str(row['action'])) + '</td><td>' + f"{row['requested_kwh']:.2f}" + '</td><td>' + f"{row['actual_kwh']:.2f}" + '</td><td>' + f"{row['price']:.2f}" + '</td><td>' + f"{row['soc_kwh']:.2f}" + '</td><td>' + f"{row['cost']:.2f}" + '</td></tr>')
    return '<table><thead><tr><th>Time</th><th>Action</th><th>Requested (kWh)</th><th>Actual (kWh)</th><th>Price</th><th>State of charge (kWh)</th><th>Cost</th></tr></thead><tbody>' + ''.join(body) + f'</tbody><tfoot><tr><td colspan="6">Total cost</td><td>{total:.2f}</td></tr></tfoot></table>'

