import csv
from datetime import date, timedelta
from decimal import Decimal, InvalidOperation
from html import escape
from io import StringIO
from typing import Any

def parse_inventory(text: str) -> list[dict[str, Any]]:
    reader = csv.DictReader(StringIO(text))
    fields = ['date', 'species', 'name', 'quantity', 'price']
    if reader.fieldnames != fields:
        raise ValueError('invalid header')
    result = []
    for row in reader:
        if None in row or any((v is None for v in row.values())):
            raise ValueError('invalid row')
        try:
            day = date.fromisoformat(row['date'].strip())
            species = row['species'].strip()
            name = row['name'].strip()
            quantity = int(row['quantity'].strip())
            price_text = row['price'].strip()
            price = Decimal(price_text)
        except (ValueError, InvalidOperation):
            raise ValueError('invalid value')
        if not species or not name or quantity < 0 or (price < 0) or (price.as_tuple().exponent < -2):
            raise ValueError('invalid value')
        result.append({'date': day, 'species': species, 'name': name, 'quantity': quantity, 'price': price})
    if not result:
        raise ValueError('empty inventory')
    return result

def aggregate_inventory(entries: list[dict[str, Any]], window_days: int=7) -> list[dict[str, Any]]:
    if isinstance(window_days, bool) or not isinstance(window_days, int) or window_days <= 0:
        raise ValueError('invalid window')
    if not entries:
        return []
    latest_day = max((x['date'] for x in entries))
    first_day = latest_day - timedelta(days=window_days - 1)
    groups = {}
    for item in entries:
        if item['date'] < first_day:
            continue
        group = groups.setdefault(item['species'], {'species': item['species'], 'units': 0, 'revenue': Decimal('0'), 'latest': item['date'], 'plants': set()})
        group['units'] += item['quantity']
        group['revenue'] += item['price'] * item['quantity']
        group['latest'] = max(group['latest'], item['date'])
        group['plants'].add(item['name'])
    result = []
    for group in groups.values():
        group['plants'] = sorted(group['plants'])
        result.append(group)
    return sorted(result, key=lambda x: (-x['units'], x['species']))

def render_inventory_report(title: str, rows: list[dict[str, Any]]) -> str:
    body = ''
    for row in rows:
        plants = ', '.join((escape(str(x), quote=True) for x in row['plants']))
        body += '<tr><td>' + escape(str(row['species']), quote=True) + '</td><td>' + str(row['units']) + '</td><td>' + format(row['revenue'], '.2f') + '</td><td>' + row['latest'].isoformat() + '</td><td>' + plants + '</td></tr>'
    return '<section class="inventory"><h1>' + escape(str(title), quote=True) + '</h1><table><thead><tr><th>Species</th><th>Units</th><th>Revenue</th><th>Latest</th><th>Plants</th></tr></thead><tbody>' + body + '</tbody></table></section>'

