from datetime import date
import html

def parse_reading(line: str) -> dict:
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    fields.append(''.join(current))
    if len(fields) != 5:
        raise ValueError('field count')
    try:
        parsed_date = date.fromisoformat(fields[2])
        electric = int(fields[3])
        water = int(fields[4])
    except (ValueError, TypeError):
        raise ValueError('invalid reading')
    if electric < 0 or water < 0:
        raise ValueError('negative meter')
    return {'pitch': fields[0], 'guest': fields[1], 'date': parsed_date, 'electric_meter': electric, 'water_meter': water}

def summarize_bills(lines: list[str], rates: dict[str, int]) -> list[dict]:
    groups = {}
    for line in lines:
        reading = parse_reading(line)
        groups.setdefault(reading['pitch'], []).append(reading)
    result = []
    for pitch, readings in groups.items():
        readings.sort(key=lambda item: item['date'])
        guest = readings[0]['guest']
        if any((item['guest'] != guest for item in readings)):
            raise ValueError('guest mismatch')
        for previous, current in zip(readings, readings[1:]):
            if current['date'] == previous['date']:
                raise ValueError('duplicate date')
            if current['electric_meter'] < previous['electric_meter'] or current['water_meter'] < previous['water_meter']:
                raise ValueError('decreasing meter')
        electric = readings[-1]['electric_meter'] - readings[0]['electric_meter']
        water = readings[-1]['water_meter'] - readings[0]['water_meter']
        days = (readings[-1]['date'] - readings[0]['date']).days
        electric_cost = min(electric, 100) * rates['electric_first'] + max(0, electric - 100) * rates['electric_extra']
        total = electric_cost + water * rates['water'] + days * rates['standing_per_day']
        result.append({'pitch': pitch, 'guest': guest, 'electric_kwh': electric, 'water_units': water, 'days': days, 'total_pence': total})
    return sorted(result, key=lambda item: (-item['total_pence'], item['pitch']))

