    rows = []
    for bill in bills:
        rows.append('<tr><td>' + html.escape(str(bill['pitch'])) + '</td><td>' + html.escape(str(bill['guest'])) + '</td><td>' + str(bill['electric_kwh']) + '</td><td>' + str(bill['water_units']) + '</td><td>' + str(bill['days']) + '</td><td>£' + format(bill['total_pence'] / 100, '.2f') + '</td></tr>')
    return '<section><h1>' + html.escape(title) + '</h1><table><thead><tr><th>Pitch</th><th>Guest</th><th>Electricity</th><th>Water</th><th>Days</th><th>Total</th></tr></thead><tbody>' + ''.join(rows) + '</tbody></table></section>'

