import html
import shlex

def parse_query(query: str) -> list[str]:
    if not isinstance(query, str):
        raise TypeError('query must be a string')
    try:
        return shlex.split(query)
    except ValueError as exc:
        raise ValueError(str(exc)) from exc

def rank_patents(records: list[dict], query: str, limit: int=10) -> list[dict]:
    if not isinstance(records, list) or not isinstance(query, str):
        raise TypeError('invalid argument type')
    if not isinstance(limit, int) or limit < 0:
        raise ValueError('limit must be nonnegative')
    terms = parse_query(query)
    required = ('id', 'title', 'abstract', 'year', 'score', 'citations')
    ranked = []
    for record in records:
        if any((key not in record for key in required)):
            raise ValueError('record is missing a field')
        text = record['title'] + ' ' + record['abstract']
        folded = text.casefold()
        counts = sum((folded.count(term.casefold()) for term in terms))
        if all((term.casefold() in folded for term in terms)):
            relevance = record['score'] + counts
            ranked.append((relevance, record['year'], record['id'], record))
    ranked.sort(key=lambda item: (-item[0], -item[1], item[2]))
    return [item[3] for item in ranked[:limit]]

def render_report(records: list[dict], generated_at: str) -> str:
    if not isinstance(records, list) or not isinstance(generated_at, str):
        raise TypeError('invalid argument type')
    fields = ('id', 'title', 'year', 'score', 'citations')
    rows = []
    for record in records:
        if any((field not in record for field in fields)):
            raise ValueError('record is missing a field')
        values = [html.escape(str(record[field]), quote=True) for field in fields]
        rows.append('<tr><td class="id">' + values[0] + '</td><td class="title">' + values[1] + '</td><td class="year">' + values[2] + '</td><td class="score">' + values[3] + '</td><td class="citations">' + values[4] + '</td></tr>')
    return '<section class="prior-art"><h1>Patent Prior-Art Results</h1><p class="generated">Generated: ' + html.escape(generated_at, quote=True) + '</p><table><thead><tr><th>ID</th><th>Title</th><th>Year</th><th>Score</th><th>Citations</th></tr></thead><tbody>' + ''.join(rows) + '</tbody></table></section>'

