def parse_scan(line: str) -> dict:
    parts = line.split(',')
    if len(parts) != 4:
        raise ValueError('invalid scan')
    timestamp, zone, plate, action = [p.strip() for p in parts]
    try:
        timestamp = int(timestamp)
    except ValueError:
        raise ValueError('invalid timestamp')
    if timestamp < 0 or not zone or (not plate) or (action not in ('enter', 'exit')):
        raise ValueError('invalid scan')
    return {'timestamp': timestamp, 'zone': zone, 'plate': plate, 'action': action}

def summarize_events(lines: list[str], capacities: dict[str, int]) -> list[dict]:
    for value in capacities.values():
        if isinstance(value, bool) or not isinstance(value, int) or value <= 0:
            raise ValueError('invalid capacity')
    events = [parse_scan(line) for line in lines]
    for event in events:
        if event['zone'] not in capacities:
            raise ValueError('unknown zone')
    states = {zone: set() for zone in capacities}
    counts = {zone: [0, 0, 0] for zone in capacities}
    for event in sorted(enumerate(events), key=lambda item: (item[1]['timestamp'], item[0])):
        event = event[1]
        zone = event['zone']
        plates = states[zone]
        if event['action'] == 'enter' and event['plate'] not in plates:
            plates.add(event['plate'])
            counts[zone][0] += 1
            counts[zone][2] = max(counts[zone][2], len(plates))
        elif event['action'] == 'exit' and event['plate'] in plates:
            plates.remove(event['plate'])
            counts[zone][1] += 1
    result = []
    for zone in sorted(capacities):
        entries, exits, peak = counts[zone]
        result.append({'zone': zone, 'capacity': capacities[zone], 'entries': entries, 'exits': exits, 'peak': peak, 'current': len(states[zone]), 'plates': sorted(states[zone])})
    return result

