import html

def render_observation_report(observations: list[dict], page: int=1, per_page: int=10) -> str:
    if page < 1 or per_page < 1 or per_page > 100:
        raise ValueError('invalid pagination')
    groups = {}
    for item in observations:
        try:
            species = item['species']
            location = item['location']
            count = item['count']
            observed_on = item['observed_on']
        except (KeyError, TypeError):
            raise ValueError('invalid observation')
        if not isinstance(species, str) or not species:
            raise ValueError('invalid species')
        if not isinstance(location, str) or not location:
            raise ValueError('invalid location')
        if isinstance(count, bool) or not isinstance(count, int) or count < 0:
            raise ValueError('invalid count')
        try:
            date = datetime.date.fromisoformat(observed_on)
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        group = groups.setdefault(species, {'total': 0, 'locations': set(), 'latest': date})
        group['total'] += count
        group['locations'].add(location)
        if date > group['latest']:
            group['latest'] = date
    ordered = sorted(groups.items(), key=lambda pair: (-pair[1]['total'], pair[0]))
    total_pages = max(1, (len(ordered) + per_page - 1) // per_page)
    start = (page - 1) * per_page
    selected = ordered[start:start + per_page]
    rows = []
    for species, group in selected:
        rows.append('<tr><td>' + html.escape(species) + '</td><td>' + html.escape(', '.join(sorted(group['locations']))) + '</td><td>' + str(group['total']) + '</td><td>' + group['latest'].isoformat() + '</td></tr>')
