import json

def _validate_catalog(catalog):
    if not isinstance(catalog, dict):
        raise ValueError('invalid catalog')
    for name, item in catalog.items():
        if not isinstance(name, str) or not name:
            raise ValueError('invalid item')
        if not isinstance(item, dict) or set(item) - {'price', 'parts'}:
            raise ValueError('invalid item')
        price = item.get('price')
        if isinstance(price, bool) or not isinstance(price, int) or price < 0:
            raise ValueError('invalid price')
        parts = item.get('parts', {})
        if not isinstance(parts, dict):
            raise ValueError('invalid parts')
        for child, amount in parts.items():
            if not isinstance(child, str) or not child or isinstance(amount, bool) or (not isinstance(amount, int)) or (amount <= 0):
                raise ValueError('invalid part')

def encode_catalog(catalog: dict) -> bytes:
    _validate_catalog(catalog)
    try:
        return json.dumps(catalog, sort_keys=True, separators=(',', ':')).encode('utf-8')
    except Exception as exc:
        raise ValueError('invalid catalog') from exc

def decode_catalog(blob: bytes) -> dict:
    try:
        if not isinstance(blob, (bytes, bytearray)):
            raise ValueError('invalid blob')
        catalog = json.loads(bytes(blob).decode('utf-8'))
        _validate_catalog(catalog)
        return catalog
    except Exception as exc:
        if isinstance(exc, ValueError):
            raise
        raise ValueError('invalid blob') from exc

def calculate_bom(root: str, catalog_blob: bytes, quantity: int=1) -> dict:
    if not isinstance(root, str) or not root or isinstance(quantity, bool) or (not isinstance(quantity, int)) or (quantity <= 0):
        raise ValueError('invalid request')
    catalog = decode_catalog(catalog_blob)
    if root not in catalog:
        raise ValueError('unknown item')
    totals = {}
    active = set()

    def expand(name, amount):
        if name in active:
            raise ValueError('cycle')
        item = catalog.get(name)
        if item is None:
            raise ValueError('unknown item')
        active.add(name)
        for child, count in item.get('parts', {}).items():
            needed = amount * count
            totals[child] = totals.get(child, 0) + needed
            expand(child, needed)
        active.remove(name)
    expand(root, quantity)
    rows = []
    for name, amount in totals.items():
        price = catalog[name]['price']
        rows.append({'item': name, 'quantity': amount, 'unit_price': price, 'subtotal': amount * price})
    rows.sort(key=lambda row: (-row['subtotal'], row['item']))
    return {'root': root, 'quantity': quantity, 'parts': rows, 'total': sum((row['subtotal'] for row in rows))}

