import json

def _valid_record(record):
    if not isinstance(record, dict) or set(record) != {'name', 'department', 'score', 'status'}:
        raise ValueError('invalid record')
    if not all((isinstance(record[k], str) for k in ('name', 'department', 'status'))):
        raise ValueError('invalid record')
    if isinstance(record['score'], bool) or not isinstance(record['score'], (int, float)) or (not 0 <= record['score'] <= 100):
        raise ValueError('invalid record')
    if record['status'] not in ('active', 'withdrawn'):
        raise ValueError('invalid record')

def _records(value):
    if not isinstance(value, list):
        raise ValueError('invalid payload')
    for record in value:
        _valid_record(record)
    return value

def encode_applicants(applicants: list[dict]) -> bytes:
    _records(applicants)
    return json.dumps(applicants, separators=(',', ':')).encode()

def summarize_applicants(payload: bytes, min_score: int | float=0, department: str | None=None, page: int=1, page_size: int=10) -> dict:
    if isinstance(min_score, bool) or not isinstance(min_score, (int, float)) or (not 0 <= min_score <= 100):
        raise ValueError('invalid minimum')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1 or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid pagination')
