        data = _records(json.loads(payload.decode()))
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    selected = [r for r in data if r['status'] == 'active' and r['score'] >= min_score and (department is None or r['department'] == department)]
    selected.sort(key=lambda r: (-r['score'], r['name'].casefold(), r['name']))
    groups = {}
    for record in selected:
        groups.setdefault(record['department'], []).append(record['score'])
