import html

def parse_trace_log(text: str) -> list[dict]:
    result = []
    for line in text.splitlines():
        if not line.strip():
            continue
        fields = []
        current = []
        escaped = False
        for char in line:
            if escaped:
                current.append(char)
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '|':
                fields.append(''.join(current))
                current = []
            else:
                current.append(char)
        if escaped:
            raise ValueError('trailing escape')
        fields.append(''.join(current))
        if len(fields) != 5:
            raise ValueError('field count')
        lot, timestamp, stage, quantity, operator = fields
        try:
            timestamp = int(timestamp, 10)
            quantity = int(quantity, 10)
        except ValueError as exc:
            raise ValueError('invalid number') from exc
        if timestamp < 0 or quantity <= 0:
            raise ValueError('invalid value')
        result.append({'lot': lot, 'timestamp': timestamp, 'stage': stage, 'quantity': quantity, 'operator': operator})
    return result

def aggregate_lots(events: list[dict]) -> list[dict]:
    groups = {}
    last = {}
    for event in events:
        lot = event['lot']
        if lot in last and event['timestamp'] < last[lot]:
            raise ValueError('timestamps out of order')
        last[lot] = event['timestamp']
        if lot not in groups:
            groups[lot] = {'lot': lot, 'total_quantity': 0, 'event_count': 0, 'first_timestamp': event['timestamp'], 'last_timestamp': event['timestamp'], 'stages': [], 'operators': set()}
        item = groups[lot]
        item['total_quantity'] += event['quantity']
        item['event_count'] += 1
        item['last_timestamp'] = event['timestamp']
        if event['stage'] not in item['stages']:
            item['stages'].append(event['stage'])
        item['operators'].add(event['operator'])
    result = []
    for item in groups.values():
        item = dict(item)
        item['operators'] = sorted(item['operators'])
        result.append(item)
    return sorted(result, key=lambda x: (-x['total_quantity'], x['lot']))

def render_report(summary: list[dict], title: str) -> str:
    rows = []
    for item in summary:
        values = [html.escape(str(item['lot']), quote=True), str(item['total_quantity']), str(item['event_count']), str(item['first_timestamp']), str(item['last_timestamp']), ' &gt; '.join((html.escape(str(stage), quote=True) for stage in item['stages'])), ', '.join((html.escape(str(operator), quote=True) for operator in item['operators']))]
        rows.append('<tr>' + ''.join(('<td>' + value + '</td>' for value in values)) + '</tr>')
    return '<section><h1>' + html.escape(title, quote=True) + '</h1><table><thead><tr><th>Lot</th><th>Total quantity</th><th>Events</th><th>First timestamp</th><th>Last timestamp</th><th>Stages</th><th>Operators</th></tr></thead><tbody>' + ''.join(rows) + '</tbody></table></section>'

