def encode_evaluations(records: list[dict]) -> bytes:
    return json.dumps(records, separators=(',', ':')).encode('utf-8')

def rank_evaluations(blob: bytes, min_score: float=0, page: int=1, page_size: int=10) -> list[dict]:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    if isinstance(min_score, bool) or not isinstance(min_score, (int, float)):
        raise ValueError('invalid minimum score')
    try:
        records = json.loads(blob.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(records, list):
        raise ValueError('invalid records')
    groups = {}
    for record in records:
        if not isinstance(record, dict) or set(record) != {'name', 'position', 'score'}:
            raise ValueError('invalid record')
        name = record['name']
        position = record['position']
        score = record['score']
        if not isinstance(name, str) or not isinstance(position, str) or isinstance(score, bool) or (not isinstance(score, (int, float))) or (score < 0) or (score > 100):
            raise ValueError('invalid record')
        if score >= min_score:
            groups.setdefault(position, []).append((name, score))
    result = []
    for position, values in groups.items():
        highest = max((score for _, score in values))
        result.append({'position': position, 'average_score': round(sum((score for _, score in values)) / len(values), 2), 'count': len(values), 'top_candidate': min((name for name, score in values if score == highest))})
    result.sort(key=lambda item: (-item['average_score'], -item['count'], item['position']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

