    if not isinstance(now, int) or isinstance(now, bool) or (not isinstance(horizon, int)) or isinstance(horizon, bool) or (horizon < 0):
        raise ValueError('invalid window')
    try:
        state: Any = json.loads(blob.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError, AttributeError) as exc:
        raise ValueError('invalid state') from exc
    if not isinstance(state, dict) or set(state) != {'rotations'} or (not isinstance(state['rotations'], list)):
