        if not isinstance(item['id'], str) or not isinstance(item['team'], str) or (not isinstance(item['status'], str)):
            raise ValueError('invalid rotation')
        if not isinstance(item['due'], int) or isinstance(item['due'], bool) or (not isinstance(item['minutes'], int)) or isinstance(item['minutes'], bool):
            raise ValueError('invalid rotation')
