from datetime import date
import requests

def fetch_meter_usage(base_url: str, meter_id: str, start_date: str, end_date: str, api_key: str) -> list[dict]:
    try:
        start = date.fromisoformat(start_date)
        end = date.fromisoformat(end_date)
    except ValueError as exc:
        raise ValueError('invalid date') from exc
    if start > end:
        raise ValueError('invalid date range')
    url = base_url.rstrip('/') + '/meters/' + meter_id + '/readings'
    totals = {}
    page = 1
    while True:
        response = requests.get(url, params={'start': start_date, 'end': end_date, 'page': page}, headers={'Authorization': 'Bearer ' + api_key})
        if response.status_code != 200:
            raise RuntimeError('request failed')
        payload = response.json()
        for reading in payload.get('readings', []):
            reading_date = date.fromisoformat(reading['date'])
            if start <= reading_date <= end:
                key = reading_date.isoformat()
                totals[key] = totals.get(key, 0) + reading['kwh']
        next_page = payload.get('next_page')
        if next_page is None:
            break
        page = next_page
    return [{'date': key, 'kwh': round(totals[key], 2)} for key in sorted(totals)]

