    if any((key not in record for key in required)) or not isinstance(record['address'], dict) or 'city' not in record['address']:
        raise ValueError('invalid listing')
    try:
        available = date.fromisoformat(record['available_on'])
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    return (available, str(record['id']))

