        return []
    try:
        cutoff = date.fromisoformat(as_of)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    chosen = {}
    for record in records:
        available, identifier = _checked(record)
        if record['address']['city'].strip().casefold() != city.strip().casefold() or record['status'] != 'active' or record['price'] < min_price or (record['price'] > max_price) or (available > cutoff):
            continue
        if identifier not in chosen or str(record['updated_at']) > str(chosen[identifier]['updated_at']):
            chosen[identifier] = record
    return sorted(chosen.values(), key=lambda r: (r['price'], date.fromisoformat(r['available_on']), str(r['id'])))

