import requests

def fetch_leak_alerts(api_url: str, min_probability: float, limit: int) -> list[dict]:
    if not 0 <= min_probability <= 1:
        raise ValueError('min_probability must be between 0 and 1')
    if limit < 0:
        raise ValueError('limit must not be negative')
    if limit == 0:
        return []
    response = requests.get(api_url + '/v1/leaks', params={'min_probability': min_probability, 'limit': 100}, timeout=10)
    response.raise_for_status()
    data = response.json()
    selected = {}
    for alert in data['alerts']:
        if alert['probability'] < min_probability:
            continue
        zone = alert['zone']
        current = selected.get(zone)
        if current is None or (alert['probability'], -0) > (current['probability'], -0):
            selected[zone] = alert
        elif alert['probability'] == current['probability']:
            if (alert['observed_at'], alert['alert_id']) < (current['observed_at'], current['alert_id']):
                selected[zone] = alert
    ordered = sorted(selected.values(), key=lambda item: (-item['probability'], item['zone']))[:limit]
    return [{'zone': item['zone'], 'alert_id': item['alert_id'], 'probability': round(item['probability'], 3), 'liters_per_hour': round(item['liters_per_hour'], 1), 'observed_at': item['observed_at']} for item in ordered]

