from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
import requests

def _rules(value):
    try:
        if not isinstance(value, dict) or isinstance(value.get('annual_cap'), bool):
            raise ValueError
        cap = Decimal(str(value['annual_cap']))
        bands = value['bands']
        if cap < 0 or not isinstance(bands, list) or (not bands):
            raise ValueError
        last = Decimal('0')
        for band in bands:
            if not isinstance(band, dict) or any((k not in band for k in ('up_to', 'employee_rate', 'employer_rate'))):
                raise ValueError
            up = Decimal(str(band['up_to']))
            er = Decimal(str(band['employee_rate']))
            rr = Decimal(str(band['employer_rate']))
            if up <= last or not Decimal('0') <= er <= Decimal('1') or (not Decimal('0') <= rr <= Decimal('1')):
                raise ValueError
            last = up
        if last < cap:
            raise ValueError
        return (cap, bands)
    except (KeyError, TypeError, ValueError, InvalidOperation):
        raise ValueError('invalid pension rules')

def fetch_pension_rules(api_url: str, tax_year: int, token: str) -> dict:
    response = requests.get(f"{api_url.rstrip('/')}/v1/pension/rules/{tax_year}", params={'region': 'UK'}, headers={'Authorization': f'Bearer {token}'}, timeout=10)
    if response.status_code != 200:
        raise ValueError('rules request failed')
    try:
        data = response.json()
        _rules(data)
        return data
    except Exception as exc:
        if isinstance(exc, ValueError) and str(exc) == 'invalid pension rules':
            raise
        raise ValueError('invalid pension rules')

def calculate_contributions(payments: list[dict], rules: dict) -> list[dict]:
    try:
        cap, bands = _rules(rules)
        if not isinstance(payments, list):
            raise ValueError
        totals = {}
        output = []
        for payment in payments:
            if not isinstance(payment, dict) or not isinstance(payment.get('employee'), str) or (not payment['employee']) or (not isinstance(payment.get('period'), str)) or isinstance(payment.get('gross'), bool):
                raise ValueError
            gross = Decimal(str(payment['gross']))
            if gross < 0:
                raise ValueError
            employee = payment['employee']
            before = totals.get(employee, Decimal('0'))
            after = before + gross
            pensionable = max(Decimal('0'), min(gross, cap - before))
            emp = Decimal('0')
            org = Decimal('0')
            start = before
            remaining = pensionable
            for band in bands:
                upper = Decimal(str(band['up_to']))
                part = max(Decimal('0'), min(after, upper) - max(start, Decimal('0')))
                part = min(part, remaining)
                if part > 0:
                    emp += part * Decimal(str(band['employee_rate']))
                    org += part * Decimal(str(band['employer_rate']))
                    remaining -= part
                if remaining <= 0:
                    break
            totals[employee] = after
            q = lambda x: float(x.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
            output.append({'employee': employee, 'period': payment['period'], 'gross': float(gross), 'pensionable_gross': q(pensionable), 'employee_contribution': q(emp), 'employer_contribution': q(org), 'cumulative_gross': float(after)})
        return output
    except (KeyError, TypeError, ValueError, InvalidOperation):
        raise ValueError('invalid payment')

