def _valid_state(state):
    if not isinstance(state, dict) or set(state) != {'version', 'groups'} or state['version'] != 1 or (not isinstance(state['groups'], dict)):
        raise ValueError('invalid state')
    for key, values in state['groups'].items():
        if not isinstance(key, str) or not isinstance(values, list):
            raise ValueError('invalid state')
        for value in values:
            if isinstance(value, bool) or not isinstance(value, (int, float)) or (not math.isfinite(value)) or (value < 0):
                raise ValueError('invalid state')

def encode_state(state: dict) -> bytes:
    _valid_state(state)
    try:
        return json.dumps(state, separators=(',', ':'), allow_nan=False).encode('utf-8')
    except (TypeError, ValueError, UnicodeError) as exc:
        raise ValueError('invalid state') from exc

def decode_state(blob: bytes) -> dict:
    if not isinstance(blob, bytes):
        raise ValueError('invalid blob')
    try:
        state = json.loads(blob.decode('utf-8'))
        _valid_state(state)
        return state
    except (ValueError, TypeError, UnicodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid blob') from exc

def update_benchmark(records: list[dict], state_blob: bytes | None=None) -> tuple[dict, bytes]:
    state = {'version': 1, 'groups': {}} if state_blob is None else decode_state(state_blob)
    additions = []
    for record in records:
        if not isinstance(record, dict) or not all((k in record for k in ('role', 'level', 'region', 'salary'))):
            raise ValueError('invalid record')
        if not all((isinstance(record[k], str) for k in ('role', 'level', 'region'))):
            raise ValueError('invalid record')
