        if isinstance(salary, bool) or not isinstance(salary, (int, float)) or (not math.isfinite(salary)) or (salary < 0):
            raise ValueError('invalid record')
        key = '|'.join((record[k].strip().casefold() for k in ('role', 'level', 'region')))
        additions.append((key, salary))
    for key, salary in additions:
        state['groups'].setdefault(key, []).append(salary)
    result = {}
    for key in sorted(state['groups']):
        values = sorted(state['groups'][key])
        n = len(values)
        median = values[n // 2] if n % 2 else (values[n // 2 - 1] + values[n // 2]) / 2
        result[key] = {'count': n, 'min': values[0], 'median': median, 'max': values[-1]}
    report = {'groups': result, 'total_count': sum((x['count'] for x in result.values())), 'group_count': len(result)}
    return (report, encode_state(state))

