        accepted = []
        previous_end = None
        for slot in ordered:
            if len(accepted) == max_per_day:
                break
            start, end = (_time(slot['start']), _time(slot['end']))
            if previous_end is None or start >= previous_end:
                accepted.append(slot)
                previous_end = end
        if accepted:
            result[day] = accepted
    return result

