    return yaml.safe_dump(records, sort_keys=False).encode('utf-8')

def vaccination_summary(payload: bytes, vaccine: str | None=None, start_date: str | None=None, end_date: str | None=None, offset: int=0, limit: int=20) -> list[dict]:
    try:
        records = yaml.safe_load(payload)
    except Exception as exc:
        raise ValueError('invalid payload') from exc
