    if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
        raise ValueError('invalid offset')
    if isinstance(limit, bool) or not isinstance(limit, int) or limit <= 0:
        raise ValueError('invalid limit')
    groups = {}
    for record in records:
        if vaccine is not None and record['vaccine'] != vaccine:
            continue
        if start_date is not None and record['date'] < start_date:
            continue
        if end_date is not None and record['date'] > end_date:
            continue
        group = groups.setdefault(record['clinic'], {'doses': 0, 'people': {}})
        group['doses'] += 1
        group['people'][record['person_id']] = max(group['people'].get(record['person_id'], 0), record['dose'])
    result = []
    for clinic, group in groups.items():
        people = len(group['people'])
        complete = sum((value >= 2 for value in group['people'].values()))
        result.append({'clinic': clinic, 'doses': group['doses'], 'people': people, 'completion_rate': round(complete * 100 / people, 2)})
    result.sort(key=lambda item: (-item['doses'], item['clinic']))
    return result[offset:offset + limit]

