import copy
import datetime
import json
import math

def encode_state(state: dict) -> bytes:
    return json.dumps(state, separators=(',', ':'), sort_keys=True).encode('utf-8')

def decode_state(blob: bytes) -> dict:
    try:
        value = json.loads(blob.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError, AttributeError):
        raise ValueError('invalid state')
    if not isinstance(value, dict) or not isinstance(value.get('items'), list) or (not isinstance(value.get('usage'), list)):
        raise ValueError('invalid state')
    return value

def _date(value):
    try:
        return datetime.date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def plan_replenishment(state: dict, as_of: str) -> list[dict]:
    end = _date(as_of)
    start = end - datetime.timedelta(days=6)
    totals = {}
    for entry in state['usage']:
        try:
            day = _date(entry['date'])
        except (KeyError, ValueError):
            continue
        if start <= day <= end:
            totals[entry['sku']] = totals.get(entry['sku'], 0) + entry['quantity']
    result = []
    for item in state['items']:
        daily = totals.get(item['sku'], 0) / 7
        target = item['reorder_point'] + daily * item['lead_days']
        if item['on_hand'] < target:
            shortage = target - item['on_hand']
            quantity = math.ceil(shortage / item['pack_size']) * item['pack_size']
            result.append({'sku': item['sku'], 'quantity': quantity, 'daily_usage': round(daily, 2), 'target_stock': round(target, 2), '_shortage': shortage})
    result.sort(key=lambda x: (-x['_shortage'], x['sku']))
    for item in result:
        del item['_shortage']
    return result

def record_delivery(state: dict, sku: str, quantity: int, delivered_on: str) -> dict:
    _date(delivered_on)
    if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity <= 0:
        raise ValueError('invalid quantity')
    result = copy.deepcopy(state)
    found = False
    for item in result['items']:
        if item['sku'] == sku:
            item['on_hand'] += quantity
            found = True
            break
    if not found:
        raise ValueError('unknown sku')
    result['usage'].append({'sku': sku, 'date': delivered_on, 'quantity': quantity})
    return result

