from solution import serialize_state, deserialize_state, aggregate_responses, survey_report
import pytest


def test_empty_state_and_empty_report():
    payload = aggregate_responses([])
    assert deserialize_state(payload) == {"responses": 0, "ids": [], "respondents": {}, "questions": {}}
    assert survey_report(payload) == []


def test_single_response_and_sorted_report():
    responses = [{"id": "r2", "respondent": "alice", "submitted": 4,
                  "answers": {"satisfaction": "good", "role": "student"}}]
    state = deserialize_state(aggregate_responses(responses))
    assert state["responses"] == 1
    assert state["ids"] == ["r2"]
    assert survey_report(serialize_state(state)) == [
        {"question": "role", "answers": [{"answer": "student", "count": 1}], "total": 1},
        {"question": "satisfaction", "answers": [{"answer": "good", "count": 1}], "total": 1},
    ]


def test_batch_order_and_answer_ties():
    responses = [
        {"id": "z", "respondent": "b", "submitted": 2, "answers": {"q": "x"}},
        {"id": "a", "respondent": "a", "submitted": 1, "answers": {"q": "y"}},
        {"id": "m", "respondent": "c", "submitted": 2, "answers": {"q": "x"}},
        {"id": "e", "respondent": "d", "submitted": 2, "answers": {"q": ""}},
    ]
    assert survey_report(aggregate_responses(responses)) == [
        {"question": "q", "answers": [
            {"answer": "", "count": 1}, {"answer": "x", "count": 2}, {"answer": "y", "count": 1}
        ], "total": 4}
    ]


def test_duplicate_ids_across_batches_are_ignored():
    first = aggregate_responses([
        {"id": "a", "respondent": "u", "submitted": 1, "answers": {"q": "old"}},
        {"id": "b", "respondent": "v", "submitted": 2, "answers": {"q": "yes"}},
    ])
    second = aggregate_responses([
        {"id": "a", "respondent": "u", "submitted": 9, "answers": {"q": "new"}},
        {"id": "c", "respondent": "w", "submitted": 3, "answers": {}},
    ], first)
    state = deserialize_state(second)
    assert state["responses"] == 3
    assert state["ids"] == ["a", "b", "c"]
    assert survey_report(second)[0]["answers"] == [
        {"answer": "old", "count": 1}, {"answer": "yes", "count": 1}
    ]


def test_latest_respondent_tie_uses_larger_id():
    payload = aggregate_responses([
        {"id": "b", "respondent": "sam", "submitted": 5, "answers": {}},
