def serialize_state(state: dict) -> bytes:
    try:
        return json.dumps(state, ensure_ascii=False, separators=(',', ':'), sort_keys=True).encode('utf-8')
    except (TypeError, ValueError, UnicodeError) as exc:
        raise ValueError('invalid state') from exc

def deserialize_state(payload: bytes) -> dict:
    try:
        value = json.loads(payload.decode('utf-8'))
    except (Exception,) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(value, dict) or set(value) != {'responses', 'ids', 'respondents', 'questions'}:
        raise ValueError('invalid state')
    if not isinstance(value['responses'], int) or value['responses'] < 0:
        raise ValueError('invalid state')
    if not isinstance(value['ids'], list) or not all((isinstance(x, str) for x in value['ids'])):
        raise ValueError('invalid state')
    if not isinstance(value['respondents'], dict) or not isinstance(value['questions'], dict):
        raise ValueError('invalid state')
    return value

def aggregate_responses(responses: list[dict], state_payload: bytes | None=None) -> bytes:
    state = deserialize_state(state_payload) if state_payload is not None else {'responses': 0, 'ids': [], 'respondents': {}, 'questions': {}}
    if not isinstance(responses, list):
        raise ValueError('invalid responses')
    for item in sorted(responses, key=lambda x: (x.get('submitted', -1), x.get('id', ''))):
        if not isinstance(item, dict) or set(item) != {'id', 'respondent', 'submitted', 'answers'}:
            raise ValueError('invalid response')
        ident, person, when, answers = item.values()
        if not isinstance(ident, str) or not ident or (not isinstance(person, str)) or (not person):
            raise ValueError('invalid response')
