        for question, answer in answers.items():
            if not isinstance(question, str) or not question or (not isinstance(answer, str)):
                raise ValueError('invalid answer')
            bucket = state['questions'].setdefault(question, {})
            bucket[answer] = bucket.get(answer, 0) + 1
        state['ids'].append(ident)
        state['responses'] += 1
        old = state['respondents'].get(person)
        if old is None or (when, ident) >= (old['submitted'], old['id']):
            state['respondents'][person] = {'id': ident, 'submitted': when}
    return serialize_state(state)

