def fetch_resident_report(base_url: str, facility_id: str, min_age: int=0) -> dict:
    if not isinstance(facility_id, str) or not facility_id:
        raise ValueError('facility_id')
    if isinstance(min_age, bool) or not isinstance(min_age, int) or (not 0 <= min_age <= 120):
        raise ValueError('min_age')
    response = requests.get(base_url.rstrip('/') + '/residents', params={'facility_id': facility_id, 'status': 'active'}, headers={'Accept': 'application/json'}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError('request failed')
    try:
        payload = response.json()
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(payload, dict) or not isinstance(payload.get('residents'), list):
        raise ValueError('invalid payload')
    required = ('id', 'name', 'age', 'room', 'care_hours', 'status')
    selected = []
    for item in payload['residents']:
        if not isinstance(item, dict) or any((key not in item for key in required)):
            raise ValueError('invalid resident')
        if item['status'] == 'active' and item['age'] >= min_age:
            selected.append({'id': item['id'], 'name': item['name'], 'age': item['age'], 'room': item['room'], 'care_hours': round(item['care_hours'], 1)})
    selected.sort(key=lambda x: (-x['age'], x['name'].casefold(), x['id']))
    groups = defaultdict(list)
    for item in selected:
        groups[item['room']].append(item['care_hours'])
    rooms = [{'room': room, 'count': len(values), 'average_care_hours': round(sum(values) / len(values), 2)} for room, values in sorted(groups.items())]
    return {'residents': selected, 'rooms': rooms, 'total_care_hours': round(sum((x['care_hours'] for x in selected)), 2)}

