import requests

def fetch_recall_summary(part_numbers: list[str], min_year: int, api_url: str='https://recalls.example.test/v1/recalls') -> list[dict[str, object]]:
    if not isinstance(min_year, int) or isinstance(min_year, bool) or (not 1900 <= min_year <= 2100):
        raise ValueError('invalid year')
    parts = [part.strip().upper() for part in part_numbers]
    if any((not part for part in parts)):
        raise ValueError('invalid part number')
    if not parts:
        return []
    response = requests.get(api_url, params={'part_numbers': ','.join(parts), 'min_year': min_year, 'limit': 100}, headers={'Accept': 'application/json'})
    if response.status_code != 200:
        raise ValueError('request failed')
    try:
        payload = response.json()
    except Exception as exc:
        raise ValueError('invalid json') from exc
    if not isinstance(payload, dict) or not isinstance(payload.get('recalls'), list):
        raise ValueError('invalid payload')
    wanted = set(parts)
    groups = {}
    for record in payload['recalls']:
        if not isinstance(record, dict) or any((key not in record for key in ('campaign_id', 'vehicle_model', 'model_year', 'part_number', 'affected_count'))):
            raise ValueError('invalid record')
        if str(record['part_number']).upper() not in wanted or record['model_year'] < min_year:
            continue
        campaign = record['campaign_id']
        if campaign not in groups:
            groups[campaign] = {'campaign_id': campaign, 'affected_count': 0, 'record_count': 0, 'models': set()}
        groups[campaign]['affected_count'] += record['affected_count']
        groups[campaign]['record_count'] += 1
        groups[campaign]['models'].add(record['vehicle_model'])
    result = []
