import csv
import io
import json
from datetime import date

def parse_production(text: str) -> list[dict]:
    result = []
    for number, line in enumerate(text.splitlines(), 1):
        if not line.strip():
            continue
        try:
            fields = next(csv.reader([line], delimiter='|', skipinitialspace=True))
            if len(fields) != 5:
                raise ValueError('wrong field count')
            day, well, oil, water, hours = [x.strip() for x in fields]
            date.fromisoformat(day)
            if not well:
                raise ValueError('empty well')
            oil, water, hours = (float(oil), float(water), float(hours))
            if oil < 0 or water < 0 or hours <= 0 or (hours > 24):
                raise ValueError('range')
        except (ValueError, StopIteration) as exc:
            raise ValueError(f'line {number}: invalid record') from exc
        result.append({'date': day, 'well': well, 'oil': oil, 'water': water, 'hours': hours})
    return result

def _valid(state):
    if not isinstance(state, dict):
        raise ValueError('invalid state')
    out = {}
    for well, values in state.items():
        if not isinstance(well, str) or not well or (not isinstance(values, dict)) or (set(values) != {'oil', 'water', 'hours'}):
            raise ValueError('invalid state')
        try:
            oil, water, hours = (float(values[k]) for k in ('oil', 'water', 'hours'))
        except (TypeError, ValueError):
            raise ValueError('invalid state')
        if oil < 0 or water < 0 or hours <= 0:
            raise ValueError('invalid state')
        out[well] = {'oil': oil, 'water': water, 'hours': hours}
    return out

def encode_state(state: dict) -> bytes:
    clean = _valid(state)
    return json.dumps(clean, sort_keys=True, separators=(',', ':')).encode()

def decode_state(blob: bytes) -> dict:
    try:
        return _valid(json.loads(blob.decode('utf-8')))
    except (ValueError, TypeError, UnicodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid state') from exc

def update_state(blob: bytes | None, text: str) -> bytes:
    state = {} if blob is None else decode_state(blob)
    records = parse_production(text)
    for row in records:
        item = state.setdefault(row['well'], {'oil': 0.0, 'water': 0.0, 'hours': 0.0})
        for key in ('oil', 'water', 'hours'):
            item[key] += row[key]
    return encode_state(state)

def render_report(blob: bytes) -> str:
    state = decode_state(blob)
    lines = []
    for well, v in sorted(state.items(), key=lambda pair: (-pair[1]['oil'], pair[0])):
        total = v['oil'] + v['water']
        pct = 0.0 if total == 0 else 100 * v['water'] / total
        lines.append(f"{well}: oil={v['oil']:.2f}, water={v['water']:.2f}, hours={v['hours']:.2f}, watercut={pct:.2f}%")
    return '\n'.join(lines) + ('\n' if lines else '')

