def encode_state(state: dict) -> bytes:
    return pickle.dumps(_valid(state), protocol=4)

def decode_state(blob: bytes) -> dict:
    try:
        return _valid(pickle.loads(blob))
    except Exception as exc:
        raise ValueError('invalid state') from exc

def update_state(blob: bytes | None, text: str) -> bytes:
    state = {} if blob is None else decode_state(blob)
    records = parse_production(text)
    for row in records:
        item = state.setdefault(row['well'], {'oil': 0.0, 'water': 0.0, 'hours': 0.0})
        for key in ('oil', 'water', 'hours'):
            item[key] += row[key]
    return encode_state(state)

def render_report(blob: bytes) -> str:
    state = decode_state(blob)
    lines = []
    for well, v in sorted(state.items(), key=lambda pair: (-pair[1]['oil'], pair[0])):
        total = v['oil'] + v['water']
        pct = 0.0 if total == 0 else 100 * v['water'] / total
        lines.append(f"{well}: oil={v['oil']:.2f}, water={v['water']:.2f}, hours={v['hours']:.2f}, watercut={pct:.2f}%")
    return '\n'.join(lines) + ('\n' if lines else '')

