def parse_coverage(text: str) -> list[tuple[str, int, int]]:
    result = []
    for raw in text.splitlines():
        if raw == '':
            continue
        fields = []
        current = []
        escaped = False
        for char in raw:
            if escaped:
                current.append(char)
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == ',':
                fields.append(''.join(current))
                current = []
            else:
                current.append(char)
        if escaped:
            current.append('\\')
        fields.append(''.join(current))
        if len(fields) != 3 or not fields[0]:
            raise ValueError('invalid coverage record')
        try:
            line = int(fields[1], 10)
            hits = int(fields[2], 10)
        except ValueError as exc:
            raise ValueError('invalid coverage record') from exc
        if line <= 0 or hits < 0:
            raise ValueError('invalid coverage record')
        result.append((fields[0], line, hits))
    return result

def aggregate_coverage(records: list[tuple[str, int, int]]) -> list[dict[str, object]]:
    grouped = {}
    for path, line, hits in records:
        grouped.setdefault(path, {})[line] = grouped.setdefault(path, {}).get(line, 0) + hits
    result = []
    for path in sorted(grouped):
        values = grouped[path]
        executable = len(values)
        covered = sum((value > 0 for value in values.values()))
        total_hits = sum(values.values())
        result.append({'path': path, 'executable': executable, 'covered': covered, 'hits': total_hits, 'percent': covered * 100.0 / executable})
    return result

