import csv
import html
import io
from datetime import date, datetime, timedelta
from typing import Any

def _time(value: str) -> datetime:
    try:
        return datetime.strptime(value, '%H:%M')
    except ValueError as exc:
        raise ValueError('invalid time') from exc

def parse_shift_log(text: str) -> list[dict[str, str]]:
    if not text:
        raise ValueError('empty input')
    try:
        rows = list(csv.reader(io.StringIO(text), strict=True))
    except csv.Error as exc:
        raise ValueError('malformed csv') from exc
    if not rows or rows[0] != ['date', 'worker', 'start', 'end', 'task']:
        raise ValueError('bad header')
    result = []
    for row in rows[1:]:
        if not row or all((not x.strip() for x in row)):
            continue
        if len(row) != 5:
            raise ValueError('bad row')
        row = [x.strip() for x in row]
        try:
            date.fromisoformat(row[0])
        except ValueError as exc:
            raise ValueError('invalid date') from exc
        _time(row[2])
        _time(row[3])
        if not row[1] or not row[4]:
            raise ValueError('empty field')
        result.append(dict(zip(('date', 'worker', 'start', 'end', 'task'), row)))
    return result

def aggregate_hours(shifts: list[dict[str, str]], week_start: str) -> list[dict[str, Any]]:
    try:
        first = date.fromisoformat(week_start)
    except ValueError as exc:
        raise ValueError('invalid week') from exc
    if first.weekday() != 0:
        raise ValueError('week must begin Monday')
    totals = {}
    for shift in shifts:
        try:
            day = date.fromisoformat(shift['date'])
            start = _time(shift['start'])
            end = _time(shift['end'])
        except (KeyError, ValueError) as exc:
            raise ValueError('invalid shift') from exc
        if not first <= day <= first + timedelta(days=6):
            continue
        seconds = (end - start).total_seconds()
        if seconds <= 0:
            seconds += 86400
        hours = seconds / 3600
        if hours > 16:
            raise ValueError('shift too long')
        key = (shift['worker'], shift['task'])
        totals[key] = totals.get(key, 0) + hours
    result = [{'worker': w, 'task': t, 'hours': round(h, 2)} for (w, t), h in totals.items()]
    result.sort(key=lambda x: (x['worker'].casefold(), x['task'].casefold(), x['worker'], x['task']))
    return result

def render_timesheet(shifts: list[dict[str, str]], week_start: str) -> str:
    rows = aggregate_hours(shifts, week_start)
    body = ''.join(('<tr><td>' + html.escape(str(row['worker']), quote=True) + '</td><td>' + html.escape(str(row['task']), quote=True) + '</td><td>' + format(row['hours'], 'g') + '</td></tr>' for row in rows))
    return '<section><h1>Farm labor: ' + html.escape(week_start, quote=True) + '</h1><table><thead><tr><th>Worker</th><th>Task</th><th>Hours</th></tr></thead><tbody>' + body + '</tbody></table></section>'

