import json
import math

def encode_subcontractor_state(records: list[dict]) -> bytes:
    return json.dumps(records, ensure_ascii=False, separators=(',', ':')).encode('utf-8')

def build_subcontractor_report(payload: bytes, project: str, as_of: str, page: int=1, page_size: int=10) -> dict:
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    try:
        records = json.loads(payload.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(records, list):
        raise ValueError('invalid records')
    groups = {}
    try:
        for record in records:
            if not isinstance(record, dict):
                raise ValueError
            required = ('project', 'subcontractor', 'status', 'committed', 'paid', 'due_date')
            if any((key not in record for key in required)):
                raise ValueError
            if not all((isinstance(record[key], str) for key in ('project', 'subcontractor', 'status', 'due_date'))):
                raise ValueError
            if record['status'] not in ('active', 'pending'):
                if record['status'] != 'complete':
                    raise ValueError
                continue
            if not isinstance(record['committed'], (int, float)) or isinstance(record['committed'], bool):
                raise ValueError
            if not isinstance(record['paid'], (int, float)) or isinstance(record['paid'], bool):
                raise ValueError
            if not math.isfinite(record['committed']) or not math.isfinite(record['paid']):
                raise ValueError
            if record['project'] == project and record['due_date'] <= as_of:
                item = groups.setdefault(record['subcontractor'], [0.0, 0])
                item[0] += record['committed'] - record['paid']
                item[1] += 1
    except (TypeError, ValueError, KeyError) as exc:
        raise ValueError('invalid record') from exc
    entries = [{'name': name, 'outstanding': round(values[0], 2), 'contracts': values[1]} for name, values in groups.items()]
    entries.sort(key=lambda item: (-item['outstanding'], item['name']))
    total = round(sum((item['outstanding'] for item in entries)), 2)
    pages = (len(entries) + page_size - 1) // page_size
    start = (page - 1) * page_size
    return {'project': project, 'as_of': as_of, 'total_outstanding': total, 'subcontractors': entries[start:start + page_size], 'page': page, 'page_size': page_size, 'pages': pages}

