def render_telemetry_report(records: list[dict], page: int=1, per_page: int=10) -> str:
    if not isinstance(records, list) or not isinstance(page, int) or isinstance(page, bool) or (not isinstance(per_page, int)) or isinstance(per_page, bool) or (page < 1) or (per_page < 1):
        raise ValueError('invalid arguments')
    parsed = []
    required = {'vehicle_id', 'timestamp', 'speed_kmh', 'battery_pct', 'status'}
