        timestamp = record['timestamp']
        status = record['status']
        speed = record['speed_kmh']
        battery = record['battery_pct']
        if not isinstance(vehicle, str) or not vehicle or (not isinstance(timestamp, str)) or (not timestamp) or (not isinstance(status, str)) or (not status):
            raise ValueError('invalid record')
        if isinstance(speed, bool) or not isinstance(speed, (int, float)) or (not math.isfinite(speed)) or (speed < 0) or (speed > 300):
            raise ValueError('invalid record')
        if isinstance(battery, bool) or not isinstance(battery, (int, float)) or (not math.isfinite(battery)) or (battery < 0) or (battery > 100):
            raise ValueError('invalid record')
        try:
            parsed.append((datetime.fromisoformat(timestamp), vehicle, timestamp, speed, battery, status))
        except ValueError:
            raise ValueError('invalid record')
    parsed.sort(key=lambda row: (row[0], row[1]), reverse=True)
    start_index = (page - 1) * per_page
    shown = parsed[start_index:start_index + per_page]
    total = len(parsed)
