import json

def _validate(records):
    if not isinstance(records, list):
        raise ValueError('invalid inventory')
    for record in records:
        if not isinstance(record, dict) or set(record) != {'name', 'species', 'stock', 'price'}:
            raise ValueError('invalid inventory')
        if not isinstance(record['name'], str) or not record['name']:
            raise ValueError('invalid inventory')
        if not isinstance(record['species'], str) or not record['species']:
            raise ValueError('invalid inventory')
        if isinstance(record['stock'], bool) or not isinstance(record['stock'], int) or record['stock'] < 0:
            raise ValueError('invalid inventory')
        if isinstance(record['price'], bool) or not isinstance(record['price'], (int, float)) or record['price'] < 0:
            raise ValueError('invalid inventory')

def encode_inventory(records: list[dict]) -> bytes:
    _validate(records)
    return json.dumps(records, separators=(',', ':'), sort_keys=True).encode('utf-8')

def load_inventory(blob: bytes) -> list[dict]:
    try:
        if not isinstance(blob, bytes):
            raise ValueError
        records = json.loads(blob.decode('utf-8'))
        _validate(records)
        return records
    except Exception as exc:
        raise ValueError('invalid inventory data') from exc

def inventory_page(blob: bytes, species: str | None=None, page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    if species is not None and (not isinstance(species, str)):
        raise ValueError('invalid species')
    records = load_inventory(blob)
    chosen = [r for r in records if r['stock'] > 0 and (species is None or r['species'] == species)]
    chosen.sort(key=lambda r: (-r['stock'], r['name']))
    start = (page - 1) * page_size
    return {'items': chosen[start:start + page_size], 'page': page, 'page_size': page_size, 'total_items': len(chosen), 'total_value': round(sum((r['stock'] * r['price'] for r in chosen)), 2)}

