            continue
        if len(row) != 5:
            raise ValueError(f'invalid record on line {line_number}')
        timestamp, site, panel, status, watts_text = row
        if not site or not panel or status not in {'installed', 'inspected', 'failed'}:
            raise ValueError(f'invalid record on line {line_number}')
        try:
            datetime.datetime.fromisoformat(timestamp)
            watts = int(watts_text)
        except (ValueError, TypeError):
            raise ValueError(f'invalid record on line {line_number}')
        if not 0 <= watts <= 100000:
            raise ValueError(f'invalid record on line {line_number}')
        result.append({'timestamp': timestamp, 'site': site, 'panel': panel, 'status': status, 'watts': watts})
    return result

