    try:
        datetime.date.fromisoformat(day)
    except ValueError:
        raise ValueError('invalid day')
    groups = {}
    for record in records:
        if str(record['timestamp']).startswith(day):
            site = str(record['site'])
            if site not in groups:
                groups[site] = {'site': site, 'installed': 0, 'inspected': 0, 'failed': 0, 'watts': 0}
            groups[site][str(record['status'])] += 1
            groups[site]['watts'] += int(record['watts'])
    return sorted(groups.values(), key=lambda row: (-int(row['watts']), str(row['site'])))

