from datetime import datetime, timezone
from html import escape

def parse_readings(csv_text: str) -> list[dict]:
    try:
        reader = csv.DictReader(io.StringIO(csv_text))
        if reader.fieldnames != ['timestamp', 'station', 'flow', 'ph', 'status']:
            raise ValueError('invalid header')
        result = []
        for row in reader:
            if None in row:
                raise ValueError('malformed row')
            if all((v is None or not v.strip() for v in row.values())):
                continue
            stamp = row['timestamp'].strip()
            if not stamp.endswith('Z'):
                raise ValueError('timestamp')
            ts = datetime.fromisoformat(stamp[:-1] + '+00:00')
            if ts.tzinfo is None:
                raise ValueError('timestamp')
            station = row['station'].strip()
            status = row['status'].strip()
            flow = float(row['flow'].strip())
            ph = float(row['ph'].strip())
            if not station or status not in {'OK', 'WARN', 'FAIL'} or flow < 0 or (not 0 <= ph <= 14):
                raise ValueError('value')
            result.append({'timestamp': ts.astimezone(timezone.utc), 'station': station, 'flow': flow, 'ph': ph, 'status': status})
        return result
    except (csv.Error, KeyError, TypeError, ValueError) as exc:
        raise ValueError('invalid readings') from exc

def aggregate_readings(readings: list[dict], window_minutes: int=60) -> list[dict]:
    if not isinstance(window_minutes, int) or isinstance(window_minutes, bool) or window_minutes <= 0:
        raise ValueError('window')
    size = window_minutes * 60
    groups = {}
    for item in readings:
        ts = item['timestamp'].astimezone(timezone.utc)
        start = datetime.fromtimestamp(ts.timestamp() // size * size, timezone.utc)
        key = (start, item['station'])
        groups.setdefault(key, []).append(item)
    rank = {'OK': 0, 'WARN': 1, 'FAIL': 2}
    result = []
    for (start, station), items in sorted(groups.items(), key=lambda x: (x[0][0], x[0][1])):
