    return result

def render_report(title: str, aggregates: list[dict]) -> str:
    rows = []
    for item in aggregates:
        window = item['window_start'].strftime('%Y-%m-%d %H:%M UTC')
        rows.append(f"<tr><td>{window}</td><td>{escape(str(item['station']))}</td><td>{item['count']}</td><td>{item['avg_flow']:.2f}</td><td>{item['avg_ph']:.2f}</td><td>{escape(str(item['worst_status']))}</td></tr>")
    return f"""<section class="report"><h1>{escape(str(title))}</h1><table><thead><tr><th>Window</th><th>Station</th><th>Samples</th><th>Avg flow</th><th>Avg pH</th><th>Status</th></tr></thead><tbody>{''.join(rows)}</tbody></table></section>"""

