def render_subcontractor_report(records: list[dict[str, object]], status: str | None=None, page: int=1, page_size: int=10) -> str:
    allowed = {'pending', 'approved', 'rejected'}
    if status is not None and status not in allowed:
        raise ValueError('invalid status')
    if type(page) is not int or page < 1 or type(page_size) is not int or (page_size < 1):
        raise ValueError('invalid pagination')
    groups = {}
    for record in records:
        if set(record) != {'project', 'subcontractor', 'status', 'amount', 'date'}:
            raise ValueError('invalid record')
        project = record['project']
        subcontractor = record['subcontractor']
        current_status = record['status']
        if not all((isinstance(value, str) for value in (project, subcontractor, current_status))) or current_status not in allowed:
            raise ValueError('invalid record')
        try:
            amount = Decimal(str(record['amount']))
            if not amount.is_finite() or amount < 0:
                raise ValueError('invalid amount')
            day = date.fromisoformat(record['date'])
        except (InvalidOperation, ValueError, TypeError):
            raise ValueError('invalid record')
        if status is not None and current_status != status:
            continue
        key = (project, subcontractor)
        if key not in groups:
            groups[key] = [0, Decimal('0'), day]
        groups[key][0] += 1
        groups[key][1] += amount
        if day > groups[key][2]:
            groups[key][2] = day
    ordered = sorted(groups.items(), key=lambda item: (item[0][0].casefold(), item[0][1].casefold()))
    total = len(ordered)
    pages = ceil(total / page_size) if total else 0
    if page > pages and total:
        raise ValueError('page out of range')
    selected = ordered[(page - 1) * page_size:page * page_size]
    rows = []
    for (project, subcontractor), (count, amount, latest) in selected:
