        rows.append(f'<tr><td>{escape(project)}</td><td>{escape(subcontractor)}</td><td>{count}</td><td>${total_amount:.2f}</td><td>{latest.isoformat()}</td></tr>')
    return '<section class="subcontractor-report">\n<h1>Subcontractor Report</h1>\n<p>Page {} of {} ({} groups)</p>\n<table><thead><tr><th>Project</th><th>Subcontractor</th><th>Records</th><th>Total Amount</th><th>Latest Date</th></tr></thead><tbody>{}</tbody></table>\n</section>'.format(page, pages, total, '\n'.join(rows))

