def fetch_leases(base_url: str, property_ids: list[str], api_key: str) -> list[dict]:
    response = requests.get(base_url.rstrip('/') + '/v1/leases', params={'property_ids': ','.join(property_ids)}, headers={'Authorization': 'Bearer ' + api_key})
    if response.status_code != 200:
        raise RuntimeError('lease service returned ' + str(response.status_code))
