import requests

def fetch_backup_manifest(endpoint: str, account_id: str, token: str) -> list[dict]:
    url = endpoint.rstrip('/') + '/v1/accounts/' + account_id + '/backups'
    response = requests.get(url, params={'include': 'metadata'}, headers={'Authorization': 'Bearer ' + token}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError('backup service returned ' + str(response.status_code))
    try:
        data = response.json()
    except Exception as exc:
        raise ValueError('invalid response JSON') from exc
    if not isinstance(data, dict) or not isinstance(data.get('backups'), list):
        raise ValueError('response does not contain backups')
    return data['backups']

def _time(value):
    try:
        text = value[:-1] + '+00:00' if isinstance(value, str) and value.endswith('Z') else value
        parsed = datetime.fromisoformat(text)
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)
        return parsed.astimezone(timezone.utc)
    except Exception as exc:
        raise ValueError('invalid timestamp') from exc

def evaluate_retention(records: list[dict], policy: dict, as_of: str) -> dict:
    tiers = policy.get('tiers') if isinstance(policy, dict) else None
    if not isinstance(tiers, dict):
        raise ValueError('invalid policy')
    rules = {}
    for tier, rule in tiers.items():
        if not isinstance(rule, dict) or not isinstance(rule.get('days'), int) or (not isinstance(rule.get('minimum'), int)) or (rule['days'] < 0) or (rule['minimum'] < 0):
            raise ValueError('invalid policy rule')
        rules[tier] = rule
    now = _time(as_of)
    items = []
    seen = set()
    for record in records:
        if not isinstance(record, dict) or any((k not in record for k in ('id', 'tier', 'created_at', 'size_bytes'))):
            raise ValueError('invalid record')
        if record['id'] in seen or record['tier'] not in rules or (not isinstance(record['size_bytes'], int)) or (record['size_bytes'] < 0):
            raise ValueError('invalid record')
        seen.add(record['id'])
        created = _time(record['created_at'])
        age = (now - created).days
        items.append((record, created, bool(record.get('legal_hold')), age <= rules[record['tier']]['days']))
    items.sort(key=lambda x: (-x[1].timestamp(), x[0]['id']))
    retained = {r['id'] for r, _, hold, fresh in items if hold or fresh}
    for tier, rule in rules.items():
        candidates = [x for x in items if x[0]['tier'] == tier and x[0]['id'] not in retained]
        current = sum((1 for x in items if x[0]['tier'] == tier and x[0]['id'] in retained))
        for x in candidates[:max(0, rule['minimum'] - current)]:
            retained.add(x[0]['id'])
    kept = [x for x in items if x[0]['id'] in retained]
    deleted = [x for x in items if x[0]['id'] not in retained]
    by_tier = {tier: {'retained': sum((x[0]['tier'] == tier for x in kept)), 'deleted': sum((x[0]['tier'] == tier for x in deleted))} for tier in rules}
    return {'retained_ids': [x[0]['id'] for x in kept], 'deleted_ids': [x[0]['id'] for x in deleted], 'retained_bytes': sum((x[0]['size_bytes'] for x in kept)), 'deleted_bytes': sum((x[0]['size_bytes'] for x in deleted)), 'by_tier': by_tier}

def retention_report(records: list[dict], policy: dict, as_of: str) -> str:
    return json.dumps(evaluate_retention(records, policy, as_of), separators=(',', ':'), sort_keys=True)

