import json

def _validate(records):
    if not isinstance(records, list):
        raise ValueError('invalid records')
    for record in records:
        if not isinstance(record, dict) or set(record) != {'contractor_id', 'certification', 'expires_on'}:
            raise ValueError('invalid record')
        if not all((isinstance(record[key], str) for key in record)):
            raise ValueError('invalid record')

def encode_credential_cache(records: list[dict[str, str]]) -> bytes:
    _validate(records)
    return json.dumps(records, ensure_ascii=False, separators=(',', ':')).encode('utf-8')

def verify_contractor_credentials(blob: bytes, contractor_id: str, required_certification: str, on_date: str) -> bool:
    if not isinstance(blob, bytes):
        raise ValueError('invalid blob')
    try:
        records = json.loads(blob.decode('utf-8'))
        _validate(records)
    except Exception as exc:
        raise ValueError('invalid blob') from exc
    return any((record['contractor_id'] == contractor_id and record['certification'] == required_certification and (record['expires_on'] >= on_date) for record in records))

