from datetime import date
_FIELDS = ['date', 'time', 'title', 'speaker', 'category', 'duration']

def parse_agenda(source: str) -> list[dict]:
    try:
        raw = json.loads(source)
    except Exception as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(raw, list):
        raise ValueError('top level must be a list')
    result = []
    for obj in raw:
        if not isinstance(obj, dict) or list(obj) != _FIELDS:
            raise ValueError('invalid record')
        if any((not isinstance(obj[k], str) for k in _FIELDS[:5])):
            raise ValueError('invalid text field')
        if any((not obj[k] for k in _FIELDS[2:5])):
            raise ValueError('empty text field')
        if not isinstance(obj['duration'], int) or isinstance(obj['duration'], bool) or (not 1 <= obj['duration'] <= 480):
            raise ValueError('invalid duration')
        if not re.fullmatch('\\d{4}-\\d{2}-\\d{2}', obj['date']):
            raise ValueError('invalid date')
        if not re.fullmatch('(?:[01]\\d|2[0-3]):[0-5]\\d', obj['time']):
            raise ValueError('invalid time')
        try:
            date.fromisoformat(obj['date'])
        except ValueError as exc:
            raise ValueError('invalid date') from exc
        result.append({k: obj[k] for k in _FIELDS})
    return sorted(result, key=lambda x: (x['date'], x['time'], x['category'], x['title']))

def summarize_agenda(items: list[dict]) -> dict:
    categories = {}
    dates = {}
    for item in items:
        categories[item['category']] = categories.get(item['category'], 0) + item['duration']
        dates[item['date']] = dates.get(item['date'], 0) + 1
    return {'total_items': len(items), 'total_minutes': sum((x['duration'] for x in items)), 'categories': categories, 'dates': dates}

def render_agenda(items: list[dict]) -> str:
    summary = summarize_agenda(items)
    out = '<section class="agenda"><h1>City Council Agenda</h1><p class="summary">{} item(s), {} minute(s)</p>'.format(summary['total_items'], summary['total_minutes'])
    if not items:
        return out + '</section>'
    dates = []
    for item in items:
        if item['date'] not in dates:
            dates.append(item['date'])
    for current in dates:
        out += '<div class="day"><h2>{}</h2><table><thead><tr><th>Time</th><th>Category</th><th>Title</th><th>Speaker</th><th>Minutes</th></tr></thead><tbody>'.format(html.escape(current))
        for item in items:
            if item['date'] == current:
                vals = [item['time'], item['category'], item['title'], item['speaker'], str(item['duration'])]
                out += '<tr>' + ''.join(('<td>{}</td>'.format(html.escape(v)) for v in vals)) + '</tr>'
        out += '</tbody></table></div>'
    return out + '</section>'

