        latest = max((row[2] for row in rows))
        cutoff = latest - timedelta(days=window_days - 1)
        days = burden = 0
        names = set()
        for injury, start, end, severity in rows:
            left, right = (max(start, cutoff), min(end, latest))
            if left <= right:
