import requests

def fetch_call_sheet(production_id: str, date: str, api_key: str) -> dict:
    response = requests.get(f'https://calls.example.test/productions/{production_id}/call-sheet', params={'date': date}, headers={'Authorization': f'Bearer {api_key}'})
    if response.status_code != 200:
        raise RuntimeError(f'call sheet request failed: {response.status_code}')
    return response.json()

def _scenes(data):
    return data.get('scenes', [])

def build_location_summary(data: dict) -> list[dict]:
    groups = {}
    for scene in _scenes(data):
        groups.setdefault(scene['location'], []).append(scene)
    result = []
    for location, scenes in groups.items():
        ordered = sorted(scenes, key=lambda s: (s['call_time'], s['id']))
        result.append({'location': location, 'scene_ids': [s['id'] for s in ordered], 'total_pages': sum((s['pages'] for s in scenes)), 'earliest_call': min((s['call_time'] for s in scenes)), 'latest_wrap': max((s['wrap_time'] for s in scenes))})
    return sorted(result, key=lambda x: (x['location'].casefold(), x['location']))

def find_crew_conflicts(data: dict) -> list[dict]:
    memberships = {}
    for scene in _scenes(data):
        for crew in set(scene['crew']):
            memberships.setdefault(crew, []).append(scene)
    result = []
    for crew, scenes in memberships.items():
        involved = set()
        for i, first in enumerate(scenes):
            for second in scenes[i + 1:]:
                if first['call_time'] < second['wrap_time'] and second['call_time'] < first['wrap_time']:
                    involved.add(first['id'])
                    involved.add(second['id'])
        if involved:
            ordered = sorted((s for s in scenes if s['id'] in involved), key=lambda s: (s['call_time'], s['id']))
            result.append({'crew': crew, 'scene_ids': [s['id'] for s in ordered]})
    return sorted(result, key=lambda x: (x['crew'].casefold(), x['crew']))

