def encode_state(state: dict) -> bytes:
    try:
        return json.dumps(state, separators=(',', ':'), sort_keys=True).encode('utf-8')
    except Exception as exc:
        raise ValueError('invalid state') from exc

def _decode(blob):
    if not isinstance(blob, (bytes, bytearray)):
        raise ValueError('invalid state')
    try:
        value = json.loads(bytes(blob).decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid state') from exc
    if not isinstance(value, dict):
        raise ValueError('invalid state')
    return value

def _valid_state(state):
    if not isinstance(state.get('daily_limit'), int) or isinstance(state['daily_limit'], bool) or state['daily_limit'] < 0:
        raise ValueError('invalid state')
    if not isinstance(state.get('history'), list) or not isinstance(state.get('accounts'), list):
        raise ValueError('invalid state')
    for item in state['history']:
        if not isinstance(item, dict) or type(item.get('day')) is not int or type(item.get('amount')) is not int:
            raise ValueError('invalid state')
    for a in state['accounts']:
        keys = ('id', 'weight', 'cap', 'paid', 'active_from', 'active_to', 'active')
        if any((k not in a for k in keys)) or not isinstance(a['id'], str) or (not isinstance(a['active'], bool)):
            raise ValueError('invalid state')
        if any((type(a[k]) is not int for k in keys[1:6])) or a['weight'] <= 0 or a['cap'] < 0 or (a['paid'] < 0):
            raise ValueError('invalid state')

