    if type(amount) is not int or amount < 0 or type(day) is not int:
        raise ValueError('invalid arguments')
    state = _decode(blob)
    _valid_state(state)
    used = sum((x['amount'] for x in state['history'] if x['day'] == day))
    remaining = min(amount, max(0, state['daily_limit'] - used))
    ranked = sorted(state['accounts'], key=lambda x: (-x['weight'], x['id']))
    allocations = []
    for account in ranked:
        if remaining == 0:
            break
        if account['active'] and account['active_from'] <= day <= account['active_to']:
            grant = min(remaining, max(0, account['cap'] - account['paid']))
            if grant:
                account['paid'] += grant
                remaining -= grant
                allocations.append({'id': account['id'], 'amount': grant})
    distributed = sum((x['amount'] for x in allocations))
    state['history'].append({'day': day, 'amount': distributed})
    return {'day': day, 'requested': amount, 'distributed': distributed, 'allocations': allocations, 'state': state}

