from datetime import date
from html import escape

def _parsed(value):
    try:
        return date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def build_leave_summary(records: list[dict[str, str]], as_of: str) -> list[dict[str, object]]:
    cutoff = _parsed(as_of)
    grouped = {}
    for record in records:
        start = _parsed(record['start'])
        end = _parsed(record['end'])
        if end < start:
            raise ValueError('end before start')
        status = record['status']
        if status not in {'approved', 'pending', 'rejected'}:
            raise ValueError('invalid status')
        if start > cutoff:
            continue
        employee = record['employee']
        department = record['department']
        if employee in grouped and grouped[employee]['department'] != department:
            raise ValueError('multiple departments')
        days = (end - start).days + 1
        if employee not in grouped:
            grouped[employee] = {'employee': employee, 'department': department, 'total_days': 0, 'approved_days': 0, 'pending_requests': 0}
        row = grouped[employee]
        row['total_days'] += days
        if status == 'approved':
            row['approved_days'] += days
        elif status == 'pending':
            row['pending_requests'] += 1
    return sorted(grouped.values(), key=lambda row: (-row['approved_days'], -row['total_days'], row['employee'].casefold(), row['employee']))

def render_leave_report(records: list[dict[str, str]], as_of: str) -> str:
    rows = build_leave_summary(records, as_of)
    body = '\n'.join((f"<tr><td>{escape(str(row['employee']))}</td><td>{escape(str(row['department']))}</td><td>{row['total_days']}</td><td>{row['approved_days']}</td><td>{row['pending_requests']}</td></tr>" for row in rows))
