import csv
import html
import io
from collections import defaultdict
from datetime import datetime
_STATUSES = ('collected', 'transferred', 'stored', 'released')

def parse_evidence(text: str) -> list[dict]:
    result = []
    for row in csv.reader(io.StringIO(text), delimiter='|', quotechar='"', escapechar='\\'):
        if not row or all((not field.strip() for field in row)):
            continue
        if len(row) != 5:
            raise ValueError('invalid evidence line')
        fields = [field.strip() for field in row]
        if any((not field for field in fields)):
            raise ValueError('invalid evidence line')
        try:
            collected_at = datetime.fromisoformat(fields[3])
        except ValueError as exc:
            raise ValueError('invalid evidence line') from exc
        if fields[4] not in _STATUSES:
            raise ValueError('invalid evidence line')
        result.append({'case_id': fields[0], 'evidence_id': fields[1], 'custodian': fields[2], 'collected_at': collected_at, 'status': fields[4]})
    return result

def aggregate_case_summary(records: list[dict]) -> list[dict]:
    groups = defaultdict(list)
    for record in records:
        groups[record['case_id']].append(record)
    output = []
    for case_id in sorted(groups):
        group = groups[case_id]
        latest_record = max(group, key=lambda r: (r['collected_at'], r['evidence_id']))
        counts = {status: 0 for status in _STATUSES}
        for record in group:
            counts[record['status']] += 1
        output.append({'case_id': case_id, 'items': len(group), 'latest': latest_record['collected_at'].isoformat(), 'statuses': counts})
    return output

def render_report(records: list[dict], title: str) -> str:
    rows = []
    for summary in aggregate_case_summary(records):
        counts = summary['statuses']
        status_text = '; '.join((f'{status}={counts[status]}' for status in _STATUSES))
        rows.append(f"<tr><td>{html.escape(str(summary['case_id']), quote=True)}</td><td>{summary['items']}</td><td>{html.escape(summary['latest'], quote=True)}</td><td>{html.escape(status_text, quote=True)}</td></tr>")
    return f"<h1>{html.escape(str(title), quote=True)}</h1><table><thead><tr><th>Case</th><th>Items</th><th>Latest collection</th><th>Status counts</th></tr></thead><tbody>{''.join(rows)}</tbody></table>"

