import json

def _validate(records):
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    required = {'order_id', 'supplier', 'amount', 'status'}
    for record in records:
        if not isinstance(record, dict) or set(record) != required:
            raise ValueError('invalid record')
        if not isinstance(record['order_id'], str) or not record['order_id']:
            raise ValueError('invalid order id')
        if not isinstance(record['supplier'], str) or not record['supplier']:
            raise ValueError('invalid supplier')
        if isinstance(record['amount'], bool) or not isinstance(record['amount'], (int, float)) or record['amount'] < 0:
            raise ValueError('invalid amount')
        if record['status'] not in {'pending', 'approved', 'cancelled'}:
            raise ValueError('invalid status')

def encode_purchase_orders(records: list[dict]) -> bytes:
    _validate(records)
    try:
        return json.dumps(records, separators=(',', ':')).encode('utf-8')
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid records') from exc

def analyze_purchase_orders(blob: bytes, supplier: str | None=None, page: int=1, page_size: int=10) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1 or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid pagination')
    try:
        records = json.loads(blob.decode('utf-8'))
        _validate(records)
