def _normalize(s):
    if not isinstance(s, dict) or set(s) != {'plant', 'readings'} or (not isinstance(s['plant'], str)) or (not s['plant']) or (not isinstance(s['readings'], list)):
        raise ValueError('invalid snapshot')
    o = []
    for x in s['readings']:
        if not isinstance(x, dict) or set(x) != {'sensor', 'timestamp', 'temperature', 'pressure'} or (not isinstance(x['sensor'], str)) or (not x['sensor']) or isinstance(x['timestamp'], bool) or (not isinstance(x['timestamp'], int)):
            raise ValueError('invalid reading')
        if any((isinstance(x[k], bool) or not isinstance(x[k], (int, float)) or (not math.isfinite(x[k])) for k in ('temperature', 'pressure'))):
            raise ValueError('invalid measurement')
        o.append({'sensor': x['sensor'], 'timestamp': x['timestamp'], 'temperature': float(x['temperature']), 'pressure': float(x['pressure'])})
    return {'plant': s['plant'], 'readings': o}

def encode_snapshot(snapshot):
    try:
        return json.dumps(_normalize(snapshot), separators=(',', ':'), allow_nan=False).encode()
