        else:
            raise ValueError('invalid blob')
        return _normalize(v)
    except ValueError:
        raise
    except Exception as e:
        raise ValueError('invalid blob') from e

def summarize_readings(readings, window=3):
    if isinstance(window, bool) or not isinstance(window, int) or window <= 0:
        raise ValueError('invalid window')
    d = _normalize({'plant': 'x', 'readings': readings})['readings']
    g = {}
    for i, x in enumerate(d):
        g.setdefault(x['sensor'], []).append((x['timestamp'], i, x))
    out = []
    for s in sorted(g):
        a = [x[2] for x in sorted(g[s], key=lambda z: (z[0], z[1]))]
        for i in range(0, len(a), window):
            p = a[i:i + window]
            t = [x['temperature'] for x in p]
            q = [x['pressure'] for x in p]
            out.append({'sensor': s, 'start': p[0]['timestamp'], 'end': p[-1]['timestamp'], 'count': len(p), 'average_temperature': round(sum(t) / len(p), 2), 'minimum_pressure': round(min(q), 2), 'maximum_pressure': round(max(q), 2), 'in_range': sum((10 <= x <= 35 for x in t))})
    return out

