from datetime import datetime, timezone
import requests

def _time(value):
    if not isinstance(value, str):
        raise ValueError('invalid timestamp')
    try:
        text = value[:-1] + '+00:00' if value.endswith('Z') else value
        result = datetime.fromisoformat(text)
        if result.tzinfo is None:
            raise ValueError('timezone required')
        return result.astimezone(timezone.utc)
    except (TypeError, ValueError, OverflowError):
        raise ValueError('invalid timestamp')

def _interval(start, end):
    left, right = (_time(start), _time(end))
    if left >= right:
        raise ValueError('invalid interval')
    return (left, right)

def summarize_admissions(payload: dict, start: str, end: str) -> list[dict]:
    left, right = _interval(start, end)
    if not isinstance(payload, dict) or not isinstance(payload.get('admissions'), list):
        raise ValueError('invalid payload')
    groups = {}
    for item in payload['admissions']:
        if not isinstance(item, dict) or not all((k in item for k in ('patient_id', 'unit', 'admitted_at'))):
            raise ValueError('invalid admission')
        admitted = _time(item['admitted_at'])
        discharged = None if item.get('discharged_at') is None else _time(item['discharged_at'])
        if discharged is not None and discharged < admitted:
            raise ValueError('invalid stay')
        overlap_start, overlap_end = (max(left, admitted), min(right, discharged or right))
        if overlap_start >= overlap_end:
            continue
        unit = item['unit']
        if not isinstance(unit, str):
            raise ValueError('invalid unit')
        group = groups.setdefault(unit, {'records': 0, 'patients': set(), 'seconds': 0, 'census': 0, 'diagnoses': {}})
        group['records'] += 1
        group['patients'].add(item['patient_id'])
        group['seconds'] += (overlap_end - overlap_start).total_seconds()
        if discharged is None or discharged > right:
            group['census'] += 1
        codes = item.get('diagnosis_codes', [])
        if not isinstance(codes, list):
            raise ValueError('invalid diagnoses')
        for code in codes:
            group['diagnoses'][code] = group['diagnoses'].get(code, 0) + 1
    result = []
    for unit, group in groups.items():
        hours = round(group['seconds'] / 3600, 2)
        result.append({'unit': unit, 'admissions': group['records'], 'unique_patients': len(group['patients']), 'patient_hours': hours, 'current_census': group['census'], 'diagnoses': dict(sorted(group['diagnoses'].items()))})
    result.sort(key=lambda x: (-x['current_census'], -x['patient_hours'], x['unit']))
    return result

def fetch_admission_summary(base_url: str, hospital_id: str, start: str, end: str) -> dict:
    try:
        response = requests.get(base_url, params={'hospital_id': hospital_id, 'start': start, 'end': end}, headers={'Accept': 'application/json'}, timeout=10)
        if not 200 <= response.status_code < 300:
            raise ValueError('request failed')
        payload = response.json()
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError('request failed') from exc
    return {'hospital_id': hospital_id, 'units': summarize_admissions(payload, start, end)}

