from datetime import date, datetime

def render_schedule(sessions: list[dict], tutor: str, week: str, page: int=1, page_size: int=10) -> str:
    try:
        month = datetime.strptime(week, '%Y-%m').date()
    except (TypeError, ValueError):
        raise ValueError('invalid week')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('invalid page size')
    chosen = []
    for item in sessions:
        try:
            student = item['student']
            location = item['location']
            status = item['status']
            d = datetime.strptime(item['date'], '%Y-%m-%d').date()
            t = datetime.strptime(item['time'], '%H:%M').time()
            duration = item['duration_minutes']
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid session')
        if not isinstance(duration, int) or isinstance(duration, bool) or duration < 1:
            raise ValueError('invalid duration')
        if status == 'scheduled' and d.year == month.year and (d.month == month.month):
            chosen.append((d, t, student, location, duration))
    chosen.sort(key=lambda x: (x[0], x[1], x[2]))
    total = len(chosen)
    start = (page - 1) * page_size
    visible = chosen[start:start + page_size]
    shown = '0' if not visible else f'{start + 1}-{start + len(visible)}'
    minutes = sum((x[4] for x in chosen))
    rows = ''.join((f"<tr><td>{d.isoformat()}</td><td>{t.strftime('%H:%M')}</td><td>{s}</td><td>{l}</td><td>{n} min</td></tr>" for d, t, s, l, n in visible))
    return f'<section class="schedule">\n<h1>{tutor} - {week}</h1>\n<p class="summary">Showing {shown} of {total} sessions - {minutes} minutes</p>\n<table>\n<thead><tr><th>Date</th><th>Time</th><th>Student</th><th>Location</th><th>Duration</th></tr></thead>\n<tbody>{rows}</tbody>\n</table>\n</section>'

