def fetch_expiring_reagents(api_url: str, days: int, api_key: Optional[str]=None) -> list[dict[str, str]]:
    if days < 0:
        raise ValueError('days must be non-negative')
    url = api_url.rstrip('/') + '/reagents/expiring'
