from datetime import datetime, timezone
import requests

def _parse_time(value):
    if not isinstance(value, str) or not value.endswith('Z'):
        raise ValueError('invalid timestamp')
    try:
        return datetime.fromisoformat(value[:-1] + '+00:00').astimezone(timezone.utc)
    except ValueError as exc:
        raise ValueError('invalid timestamp') from exc

def fetch_event_roster(event_id: str, api_base: str, token: str) -> list[dict]:
    url = api_base.rstrip('/') + '/events/' + event_id + '/registrations'
    response = requests.get(url, params={'status': 'confirmed'}, headers={'Authorization': 'Bearer ' + token})
    if response.status_code != 200:
        raise RuntimeError('registration request failed')
    try:
        data = response.json()
        rows = data['registrations']
        if not isinstance(rows, list):
            raise ValueError
        result = []
        for row in rows:
            result.append({key: row[key] for key in ('attendee_id', 'full_name', 'email', 'badge_code')})
    except (KeyError, TypeError, ValueError) as exc:
        raise ValueError('invalid registration data') from exc
    return sorted(result, key=lambda row: row['attendee_id'])

def check_in_report(roster: list[dict], scans: list[dict], window_start: str, window_end: str) -> list[dict]:
    start = _parse_time(window_start)
    end = _parse_time(window_end)
    if start > end:
        raise ValueError('invalid window')
    badges = set()
    for row in roster:
        if row['badge_code'] in badges:
            raise ValueError('duplicate badge')
        badges.add(row['badge_code'])
    earliest = {}
    for scan in scans:
        try:
            stamp = _parse_time(scan['scanned_at'])
            badge = scan['badge_code']
            if badge not in badges or not start <= stamp <= end:
                continue
            if badge not in earliest or stamp < earliest[badge][0]:
                earliest[badge] = (stamp, scan['scanned_at'], scan['gate'])
        except (KeyError, TypeError, ValueError):
            continue
    result = []
    for row in roster:
        hit = earliest.get(row['badge_code'])
        result.append({'attendee_id': row['attendee_id'], 'name': row['full_name'], 'badge_code': row['badge_code'], 'status': 'checked_in' if hit else 'missing', 'first_scan': hit[1] if hit else None, 'gate': hit[2] if hit else None})
    return sorted(result, key=lambda row: row['attendee_id'])

def summarize_check_ins(report: list[dict]) -> dict:
    gates = {}
    checked = 0
    missing = 0
    for row in report:
        if row['status'] == 'checked_in':
            checked += 1
            gates[row['gate']] = gates.get(row['gate'], 0) + 1
        elif row['status'] == 'missing':
            missing += 1
        else:
            raise ValueError('invalid status')
    return {'total': len(report), 'checked_in': checked, 'missing': missing, 'gates': {key: gates[key] for key in sorted(gates)}}

