def inventory_report(api_url: str, site: str, min_fill: float=0.0, page_size: int=100) -> list[dict]:
    if not api_url or not site:
        raise ValueError('api_url and site are required')
    if isinstance(min_fill, bool) or not isinstance(min_fill, (int, float)) or (not math.isfinite(min_fill)) or (not 0 <= min_fill <= 1):
        raise ValueError('invalid min_fill')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('invalid page_size')
    totals = {}
    page = 1
    while page is not None:
        result = requests.get(api_url, params={'site': site, 'page': page, 'page_size': page_size}, headers={'Accept': 'application/json'})
        if result.status_code != 200:
            raise RuntimeError('inventory request failed')
        try:
            body = result.json()
        except Exception as exc:
            raise ValueError('invalid response') from exc
        if not isinstance(body, dict) or not isinstance(body.get('items'), list):
            raise ValueError('invalid response')
        for item in body['items']:
            if not isinstance(item, dict) or any((key not in item for key in ('silo', 'grain', 'tonnes', 'capacity'))):
                raise ValueError('invalid item')
            silo, grain = (item['silo'], item['grain'])
            tonnes, capacity = (item['tonnes'], item['capacity'])
            if not isinstance(silo, str) or not isinstance(grain, str) or isinstance(tonnes, bool) or isinstance(capacity, bool) or (not isinstance(tonnes, (int, float))) or (not isinstance(capacity, (int, float))) or (not math.isfinite(tonnes)) or (not math.isfinite(capacity)) or (capacity <= 0):
                raise ValueError('invalid item')
            if tonnes / capacity >= min_fill:
                entry = totals.setdefault(grain, [0.0, 0])
                entry[0] += tonnes
                entry[1] += 1
        page = body.get('next_page')
        if page is not None and (isinstance(page, bool) or not isinstance(page, int)):
            raise ValueError('invalid next page')
    result = [{'grain': grain, 'tonnes': round(values[0], 2), 'silos': values[1]} for grain, values in totals.items()]
    return sorted(result, key=lambda item: (-item['tonnes'], item['grain']))

