                raise ValueError
            if limit is not None and (type(limit) is not int or limit < 0):
                raise ValueError
            starts, expires = (row.get('starts'), row.get('expires'))
            _day(starts)
            _day(expires)
            out.append({'code': code, 'discount_cents': d, 'min_subtotal_cents': m, 'tags': sorted({x.lower() for x in tags}), 'starts': starts, 'expires': expires, 'limit': limit})
