def fetch_repayments(base_url: str, loan_id: str, token: str) -> list[dict]:
    url = base_url.rstrip('/') + '/loans/' + loan_id + '/repayments'
    response = requests.get(url, params={'status': 'posted,pending'}, headers={'Authorization': 'Bearer ' + token}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError('request failed with status ' + str(response.status_code))
    data = response.json()
    if not isinstance(data, dict) or not isinstance(data.get('repayments'), list):
        raise ValueError('invalid response')
    return data['repayments']

def _day(value):
    try:
        return date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def build_repayment_schedule(records: list[dict], as_of: str) -> list[dict]:
    today = _day(as_of)
    groups = {}
    for record in records:
        due = record.get('due_date')
        _day(due)
        try:
            amount = float(record['amount'])
            paid = float(record.get('paid_amount', 0))
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid amount')
        if amount < 0 or paid < 0 or paid > amount:
            raise ValueError('invalid amount')
        item = groups.setdefault(due, [0.0, 0.0, []])
        item[0] += amount
        item[1] += paid
        if 'reference' in record:
            item[2].append(record['reference'])
    result = []
    for due in sorted(groups):
        amount, paid, refs = groups[due]
        amount = round(amount, 2)
        paid = round(paid, 2)
        outstanding = round(amount - paid, 2)
        if outstanding == 0:
            status = 'paid'
        elif paid > 0:
            status = 'partial'
        elif _day(due) < today:
            status = 'overdue'
        else:
            status = 'upcoming'
        result.append({'due_date': due, 'amount': amount, 'paid_amount': paid, 'outstanding': outstanding, 'status': status, 'references': refs})
    return result

def loan_summary(base_url: str, loan_id: str, token: str, as_of: str) -> dict:
    schedule = build_repayment_schedule(fetch_repayments(base_url, loan_id, token), as_of)
    due = next((x['due_date'] for x in schedule if x['outstanding'] > 0 and x['due_date'] >= as_of), None)
    return {'schedule': schedule, 'total_amount': round(sum((x['amount'] for x in schedule)), 2), 'total_paid': round(sum((x['paid_amount'] for x in schedule)), 2), 'total_outstanding': round(sum((x['outstanding'] for x in schedule)), 2), 'overdue_count': sum((x['status'] == 'overdue' for x in schedule)), 'next_due_date': due}

