import json
import math

class KubernetesResourceMonitor:

    def __init__(self):
        self._samples = []
        self._latest = None

    def ingest(self, events):
        if not isinstance(events, list):
            raise ValueError('events')
        checked = []
        for event in events:
            if not isinstance(event, dict) or set(event) != {'timestamp', 'namespace', 'pod', 'cpu_millicores', 'memory_bytes'}:
                raise ValueError('event')
            t = event['timestamp']
            ns = event['namespace']
            pod = event['pod']
            cpu = event['cpu_millicores']
            mem = event['memory_bytes']
            if isinstance(t, bool) or not isinstance(t, int) or t < 0:
                raise ValueError('timestamp')
            if not isinstance(ns, str) or not ns or (not isinstance(pod, str)) or (not pod):
                raise ValueError('name')
            if isinstance(cpu, bool) or not isinstance(cpu, (int, float)) or (not math.isfinite(cpu)) or (cpu < 0):
                raise ValueError('cpu')
            if isinstance(mem, bool) or not isinstance(mem, int) or mem < 0:
                raise ValueError('memory')
            checked.append([t, ns, pod, cpu, mem])
        self._samples.extend(checked)
        if checked:
            value = max((x[0] for x in checked))
            self._latest = value if self._latest is None else max(self._latest, value)

    def report(self, window):
        if isinstance(window, bool) or not isinstance(window, int) or window <= 0:
            raise ValueError('window')
        if self._latest is None:
            return []
        cutoff = self._latest - window + 1
        groups = {}
        for t, ns, pod, cpu, mem in self._samples:
            if t >= cutoff:
                groups.setdefault((ns, pod), []).append((cpu, mem))
        result = []
        for (ns, pod), values in groups.items():
            result.append({'namespace': ns, 'pod': pod, 'average_cpu_millicores': round(sum((x[0] for x in values)) / len(values), 2), 'peak_memory_bytes': max((x[1] for x in values)), 'sample_count': len(values)})
        result.sort(key=lambda x: (-x['average_cpu_millicores'], -x['peak_memory_bytes'], x['namespace'], x['pod']))
        return result

    def dump_state(self):
        return json.dumps({'samples': self._samples, 'latest': self._latest}, separators=(',', ':'), allow_nan=False).encode()

    @classmethod
    def from_state(cls, payload):
        if not isinstance(payload, bytes):
            raise ValueError('payload')
        try:
            state = json.loads(payload.decode())
            if not isinstance(state, dict) or set(state) != {'samples', 'latest'} or (not isinstance(state['samples'], list)):
                raise ValueError('state')
            obj = cls()
            obj.ingest([{'timestamp': x[0], 'namespace': x[1], 'pod': x[2], 'cpu_millicores': x[3], 'memory_bytes': x[4]} for x in state['samples']])
            if state['latest'] != obj._latest:
                raise ValueError('latest')
            return obj
        except (ValueError, TypeError, KeyError, IndexError, json.JSONDecodeError, UnicodeDecodeError):
            raise ValueError('payload')

