        for event in events:
            if not isinstance(event, dict) or set(event) != {'timestamp', 'namespace', 'pod', 'cpu_millicores', 'memory_bytes'}:
                raise ValueError('event')
            t = event['timestamp']
            ns = event['namespace']
            pod = event['pod']
            cpu = event['cpu_millicores']
            mem = event['memory_bytes']
            if isinstance(t, bool) or not isinstance(t, int) or t < 0:
                raise ValueError('timestamp')
            if not isinstance(ns, str) or not ns or (not isinstance(pod, str)) or (not pod):
                raise ValueError('name')
            if isinstance(cpu, bool) or not isinstance(cpu, (int, float)) or (not math.isfinite(cpu)) or (cpu < 0):
                raise ValueError('cpu')
            if isinstance(mem, bool) or not isinstance(mem, int) or mem < 0:
                raise ValueError('memory')
