        return result

    def dump_state(self):
        return pickle.dumps({'samples': self._samples, 'latest': self._latest})

    @classmethod
    def from_state(cls, payload):
        if not isinstance(payload, bytes):
            raise ValueError('payload')
        try:
            state = pickle.loads(payload)
            if not isinstance(state, dict) or set(state) != {'samples', 'latest'} or (not isinstance(state['samples'], list)):
