    if not sensor:
        raise ValueError('empty sensor')
    try:
        timestamp = datetime.fromisoformat(stamp.replace('Z', '+00:00'))
        temperature = float(temp)
        pressure_value = float(pressure)
    except (ValueError, TypeError):
        raise ValueError('invalid reading')
    if timestamp.tzinfo is None or not math.isfinite(temperature) or (not math.isfinite(pressure_value)):
        raise ValueError('invalid reading')
    return {'sensor': sensor, 'timestamp': timestamp, 'temperature': temperature, 'pressure': pressure_value}

def aggregate_readings(lines: list[str], window: int=3) -> list[dict]:
    if window < 1:
        raise ValueError('window must be positive')
    groups = {}
    for line in lines:
        item = parse_reading(line)
        groups.setdefault(item['sensor'], []).append(item)
    result = []
    for sensor in sorted(groups):
        readings = sorted(groups[sensor], key=lambda x: x['timestamp'])
        for pos in range(0, len(readings), window):
            chunk = readings[pos:pos + window]
            result.append({'sensor': sensor, 'start': chunk[0]['timestamp'], 'end': chunk[-1]['timestamp'], 'count': len(chunk), 'average_temperature': round(sum((x['temperature'] for x in chunk)) / len(chunk), 2), 'maximum_pressure': round(max((x['pressure'] for x in chunk)), 2), 'alert': any((x['temperature'] < -20 or x['temperature'] > 120 or x['pressure'] > 250 for x in chunk))})
