import datetime
import requests

def fetch_cash_forecast(account_ids: list[str], as_of: str, min_confidence: float=0.0) -> dict[str, float]:
    if not isinstance(account_ids, list) or not account_ids:
        raise ValueError('account_ids must be a non-empty list')
    if any((not isinstance(x, str) or not x for x in account_ids)):
        raise ValueError('invalid account ID')
    try:
        datetime.date.fromisoformat(as_of)
        if len(as_of) != 10:
            raise ValueError
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if isinstance(min_confidence, bool) or not isinstance(min_confidence, (int, float)) or (not 0 <= min_confidence <= 1):
        raise ValueError('invalid confidence')
    ids = list(dict.fromkeys(account_ids))
    totals = {x: 0.0 for x in ids}
    page = 1
    while True:
        r = requests.get('https://treasury.example.com/api/v1/cash-forecasts', params={'account_ids': ','.join(ids), 'as_of': as_of, 'min_confidence': min_confidence, 'page': page}, headers={'Accept': 'application/json'})
        if r.status_code != 200:
            raise RuntimeError('forecast request failed')
        data = r.json()
        if not isinstance(data, dict) or not isinstance(data.get('items'), list):
            raise ValueError('invalid response')
        for item in data['items']:
            if item['account_id'] in totals and item['date'] <= as_of and (item['confidence'] >= min_confidence):
                totals[item['account_id']] += item['amount']
        nxt = data.get('next_page')
        if nxt is None:
            break
        if not isinstance(nxt, int):
            raise ValueError('invalid page')
        page = nxt
    return {key: round(value, 2) for key, value in totals.items()}

