import json
import datetime

def _validate(subscribers, events):
    if not isinstance(subscribers, list) or not isinstance(events, list):
        raise ValueError('invalid archive')
    seen = set()
    clean_subscribers = []
    for sub in subscribers:
        if not isinstance(sub, dict) or not isinstance(sub.get('id'), str) or (not sub['id']) or (not isinstance(sub.get('name'), str)):
            raise ValueError('invalid subscriber')
        sid = sub['id']
        if sid in seen:
            raise ValueError('duplicate subscriber')
        seen.add(sid)
        plan = sub.get('plan', 'standard')
        if not isinstance(plan, str):
            raise ValueError('invalid plan')
        clean_subscribers.append({'id': sid, 'name': sub['name'], 'plan': plan})
    clean_events = []
    for event in events:
        if not isinstance(event, dict):
            raise ValueError('invalid event')
        sid = event.get('subscriber_id')
        date = event.get('date')
        action = event.get('action')
        cents = event.get('cents')
        if not isinstance(sid, str) or not sid or sid not in seen or (not isinstance(date, str)) or (not isinstance(action, str)) or (action not in {'start', 'renew', 'cancel'}) or (not isinstance(cents, int)) or isinstance(cents, bool) or (cents < 0):
            raise ValueError('invalid event')
        try:
            if len(date) != 10 or datetime.date.fromisoformat(date).isoformat() != date:
                raise ValueError
        except ValueError:
            raise ValueError('invalid date')
        clean_events.append({'subscriber_id': sid, 'date': date, 'action': action, 'cents': cents})
    return {'subscribers': clean_subscribers, 'events': clean_events}

def encode_archive(subscribers, events):
