    seen_agents = set()
    for item in data['agents']:
        if not isinstance(item, dict) or 'id' not in item or (not isinstance(item.get('skills'), list)):
            raise ValueError('invalid agent')
        aid = item['id']
        capacity = item.get('capacity')
        if aid in seen_agents or not isinstance(capacity, int) or isinstance(capacity, bool) or (capacity < 0):
            raise ValueError('invalid agent')
        seen_agents.add(aid)
        agents.append({'id': aid, 'skills': item['skills'], 'capacity': capacity, 'assigned': []})
    seen_tickets = set()
    checked = []
    for index, ticket in enumerate(tickets):
        if not isinstance(ticket, dict) or not all((k in ticket for k in ('id', 'category', 'priority', 'age_hours'))):
            raise ValueError('invalid ticket')
        tid = ticket['id']
        priority = ticket['priority']
        age = ticket['age_hours']
        if tid in seen_tickets or not isinstance(ticket['category'], str) or (not isinstance(priority, int)) or isinstance(priority, bool) or (not 1 <= priority <= 5) or (not isinstance(age, (int, float))) or isinstance(age, bool) or (age < 0):
            raise ValueError('invalid ticket')
        seen_tickets.add(tid)
        checked.append((ticket, index))
    checked.sort(key=lambda pair: (-pair[0]['priority'], -pair[0]['age_hours'], pair[1]))
    unassigned = []
    for ticket, _ in checked:
        choices = [a for a in agents if ticket['category'] in a['skills'] and len(a['assigned']) < a['capacity']]
        if not choices:
            unassigned.append(ticket['id'])
            continue
        agent = min(choices, key=lambda a: (len(a['assigned']), str(a['id'])))
        agent['assigned'].append(ticket['id'])
    return {'assignments': {a['id']: a['assigned'] for a in agents}, 'unassigned': unassigned}

