import csv
import io
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def parse_payroll(text: str) -> list[dict]:
    if not text:
        raise ValueError('empty input')
    rows = list(csv.reader(io.StringIO(text)))
    rows = [row for row in rows if row]
    if not rows or rows[0] != ['employee_id', 'name', 'gross', 'pretax', 'rate']:
        raise ValueError('invalid header')
    result = []
    seen = set()
    for row in rows[1:]:
        if len(row) != 5:
            raise ValueError('invalid row')
        employee_id, name, gross_text, pretax_text, rate_text = row
        if not employee_id or employee_id in seen:
            raise ValueError('invalid employee id')
        try:
            gross = Decimal(gross_text)
            pretax = Decimal(pretax_text)
            rate = Decimal(rate_text)
        except InvalidOperation as exc:
            raise ValueError('invalid number') from exc
        if not all((x.is_finite() for x in (gross, pretax, rate))):
            raise ValueError('invalid number')
        if gross < 0 or pretax < 0 or rate < 0 or (rate > 1) or (pretax > gross):
            raise ValueError('invalid values')
        taxable = gross - pretax
        tax = (taxable * rate).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        result.append({'employee_id': employee_id, 'name': name, 'gross': gross, 'pretax': pretax, 'rate': rate, 'taxable': taxable, 'tax': tax})
        seen.add(employee_id)
    return result

def render_report(records: list[dict], title: str='Payroll Tax Withholding Report') -> str:
    ordered = sorted(records, key=lambda r: (-r['tax'], r['name'].casefold(), r['employee_id']))
    rows = []
    total = Decimal('0.00')
    for record in ordered:
        total += record['tax']
        rows.append('<tr><td>{}</td><td>{}</td><td>{}</td><td>{}</td><td>{:.2%}</td><td>{}</td></tr>'.format(record['employee_id'], record['name'], format(record['gross'], '.2f'), format(record['taxable'], '.2f'), record['rate'], format(record['tax'], '.2f')))
    body = ''.join(rows)
    return '<section class="payroll-report"><h1>{}</h1><table><thead><tr><th>Employee</th><th>Name</th><th>Gross</th><th>Taxable</th><th>Rate</th><th>Withholding</th></tr></thead><tbody>{}</tbody></table><p class="total">Total withholding: {}</p></section>'.format(title, body, format(total, '.2f'))

