    if not isinstance(data, dict) or not isinstance(data.get('updates'), list) or any((not isinstance(x, dict) for x in data['updates'])):
        raise ValueError('invalid updates response')
    return data['updates']

def _version(value):
    m = re.fullmatch('(\\d+)(?:\\.(\\d+))?(?:\\.(\\d+))?(?:-(alpha|beta|rc)(\\d*)?)?', value)
    if not m:
        raise ValueError('invalid version')
    nums = tuple((int(m.group(i) or 0) for i in (1, 2, 3)))
    if m.group(4) is None:
        pre = (1, 0, 0)
    else:
        pre = (0, _PRE[m.group(4)], int(m.group(5) or 0))
    return nums + pre

