        raise ValueError('invalid state')
    if any((not isinstance(k, str) or not isinstance(v, str) for k, v in rules.items())):
        raise ValueError('invalid state')
    return json.dumps({'rules': rules, 'default': default}, separators=(',', ':')).encode()

def categorize_transactions(transactions: list[dict], state_blob: bytes, page: int=1, page_size: int=20) -> dict:
