from datetime import datetime
import requests

def fetch_itinerary(trip_id: str, api_key: str, base_url: str='https://api.example.test') -> dict:
    response = requests.get(base_url.rstrip('/') + '/trips/' + trip_id, headers={'Authorization': 'Bearer ' + api_key, 'Accept': 'application/json'})
    if response.status_code != 200:
        raise ValueError(f'request failed with status {response.status_code}: {response.text}')
    try:
        value = response.json()
    except Exception as exc:
        raise ValueError('invalid JSON response') from exc
    if not isinstance(value, dict):
        raise ValueError('response must be an object')
    return value

def _time(value):
    try:
        return datetime.fromisoformat(value.replace('Z', '+00:00'))
    except Exception as exc:
        raise ValueError('invalid timestamp') from exc

def flatten_segments(payload: dict) -> list[dict]:
    result = []
    for day in payload.get('days', []) or []:
        try:
            number = day['day']
            entries = day['segments']
        except (KeyError, TypeError) as exc:
            raise ValueError('invalid day') from exc
        for item in entries:
            try:
                start_text = item['departure']
                end_text = item['arrival']
                start = _time(start_text)
                end = _time(end_text)
                if end < start:
                    raise ValueError('arrival precedes departure')
                row = {'day': number, 'from': item['from'], 'to': item['to'], 'departure': start_text, 'arrival': end_text, 'carrier': item['carrier'], 'duration_minutes': int((end - start).total_seconds() // 60)}
            except (KeyError, TypeError) as exc:
                raise ValueError('invalid segment') from exc
            result.append((start, end, row))
    result.sort(key=lambda x: (x[0], x[1], x[2]['from'], x[2]['to']))
    return [x[2] for x in result]

def summarize_itinerary(payload: dict) -> dict:
    segments = flatten_segments(payload)
    total = sum((x['duration_minutes'] for x in segments))
    layover = 0
    for previous, current in zip(segments, segments[1:]):
        gap = (_time(current['departure']) - _time(previous['arrival'])).total_seconds() // 60
        layover += max(0, int(gap))
    by_day = {}
    for segment in segments:
        by_day[segment['day']] = by_day.get(segment['day'], 0) + 1
    by_day = dict(sorted(by_day.items()))
    return {'segment_count': len(segments), 'total_travel_minutes': total, 'total_layover_minutes': layover, 'carriers': sorted({x['carrier'] for x in segments}), 'segments_by_day': by_day}

