    if isinstance(page, bool) or not isinstance(page, int) or isinstance(per_page, bool) or (not isinstance(per_page, int)):
        raise ValueError('page and per_page must be integers')
    if page < 1 or per_page < 1:
        raise ValueError('invalid pagination')
    grouped = {}
    for record in records:
        name = record.get('student')
        status = record.get('status')
        if not isinstance(name, str) or not name:
            raise ValueError('invalid student')
        if status not in {'present', 'absent', 'late'}:
            raise ValueError('invalid status')
        if name not in grouped:
            grouped[name] = {'present': 0, 'absent': 0, 'late': 0}
        grouped[name][status] += 1
    students = []
    for name, counts in grouped.items():
        total = sum(counts.values())
        rate = counts['present'] / total * 100
        students.append((name, counts, rate))
    students.sort(key=lambda item: (-item[2], item[0].casefold(), item[0]))
    total_pages = max(1, (len(students) + per_page - 1) // per_page)
    if page > total_pages:
        raise ValueError('page out of range')
    start = (page - 1) * per_page
    rows = []
    for name, counts, rate in students[start:start + per_page]:
        rows.append(f"<tr><td>{name}</td><td>{counts['present']}</td><td>{counts['absent']}</td><td>{counts['late']}</td><td>{rate:.1f}%</td></tr>")
    return '<div class="attendance-report"><h1>Student Attendance</h1><table><thead><tr><th>Student</th><th>Present</th><th>Absent</th><th>Late</th><th>Attendance</th></tr></thead><tbody>' + ''.join(rows) + f'</tbody></table><p class="pagination">Page {page} of {total_pages}</p></div>'

