        if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity < 1:
            raise ValueError('invalid quantity')
        key = (barcode, location)
        if key not in groups:
            groups[key] = [0, 0]
        groups[key][0] += quantity
        groups[key][1] += 1
    ordered = sorted(groups.items(), key=lambda item: (-item[1][0], item[0][0], item[0][1]))
    total = len(ordered)
    start_index = (page - 1) * per_page
    selected = ordered[start_index:start_index + per_page]
    rows = ''.join((f'<tr><td>{html.escape(barcode, quote=True)}</td><td>{html.escape(location, quote=True)}</td><td>{values[0]}</td><td>{values[1]}</td></tr>' for (barcode, location), values in selected))
