    return f'<div class="inventory"><h1>Warehouse inventory</h1><table><thead><tr><th>Barcode</th><th>Location</th><th>Quantity</th><th>Scans</th></tr></thead><tbody>{rows}</tbody></table><p class="summary">Showing {start}-{end} of {total} groups</p></div>'

