import requests

def fetch_catalog(category: str | None=None, min_rating: float=0.0, page: int=1, page_size: int=10) -> dict:
    if category is not None and (not isinstance(category, str) or not category):
        raise ValueError('invalid category')
    if isinstance(min_rating, bool) or not isinstance(min_rating, (int, float)) or (not math.isfinite(min_rating)) or (not 0 <= min_rating <= 10):
        raise ValueError('invalid rating')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    response = requests.get('https://api.stream.example/v1/videos', params={'category': category, 'min_rating': min_rating, 'page': page, 'page_size': page_size}, headers={'Accept': 'application/json'})
    if response.status_code != 200:
        raise RuntimeError('catalog request failed')
    try:
        payload = response.json()
    except Exception as exc:
        raise ValueError('invalid response') from exc
    if not isinstance(payload, dict) or not isinstance(payload.get('videos'), list):
        raise ValueError('invalid response')
    required = {'id', 'title', 'genre', 'rating', 'duration_minutes', 'views'}
    videos = []
    for video in payload['videos']:
        if not isinstance(video, dict) or not required.issubset(video) or (not isinstance(video['rating'], (int, float))) or (not isinstance(video['views'], (int, float))):
            raise ValueError('invalid video')
        if (category is None or video['genre'] == category) and video['rating'] >= min_rating:
            videos.append(video)
    videos.sort(key=lambda item: (-item['rating'], item['title'], item['id']))
    counts = {}
    for video in videos:
        counts[video['genre']] = counts.get(video['genre'], 0) + 1
    counts = dict(sorted(counts.items()))
    start = (page - 1) * page_size
    return {'items': videos[start:start + page_size], 'total': len(videos), 'page': page, 'page_size': page_size, 'total_views': sum((video['views'] for video in videos)), 'average_rating': round(sum((video['rating'] for video in videos)) / len(videos), 2) if videos else 0.0, 'genre_counts': counts}

