import requests
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def _fee(value):
    if value is None:
        return 0
    if isinstance(value, bool):
        raise ValueError('invalid fee')
    if isinstance(value, int):
        if value < 0:
            raise ValueError('invalid fee')
        return value
    try:
        amount = Decimal(str(value))
        if amount < 0:
            raise ValueError('invalid fee')
        return int((amount * 100).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
    except (InvalidOperation, ValueError, TypeError):
        raise ValueError('invalid fee')

def fetch_adoption_records(shelter_id: str, start_date: str, end_date: str, api_token: str) -> list[dict]:
    if start_date > end_date:
        raise ValueError('invalid date range')
    result = []
    cursor = None
    while True:
        params = {'shelter_id': shelter_id, 'start_date': start_date, 'end_date': end_date, 'limit': 100}
        if cursor:
            params['cursor'] = cursor
        r = requests.get('https://api.shelter.example/v1/adoptions', params=params, headers={'Authorization': 'Bearer ' + api_token, 'Accept': 'application/json'}, timeout=10)
        if r.status_code != 200:
            raise RuntimeError('service error')
        payload = r.json()
        if not isinstance(payload, dict) or not isinstance(payload.get('animals'), list):
            raise ValueError('invalid response')
        for item in payload['animals']:
            if not isinstance(item, dict) or not all((k in item for k in ('id', 'name', 'species', 'adopted_at', 'adopter'))) or (not isinstance(item['adopter'], dict)):
                raise ValueError('invalid record')
            day = item['adopted_at'][:10]
            if start_date <= day <= end_date:
                result.append({'id': item['id'], 'name': item['name'], 'species': item['species'], 'adopted_at': item['adopted_at'], 'city': item['adopter'].get('city'), 'adoption_fee': _fee(item.get('adoption_fee'))})
        cursor = payload.get('next_cursor')
        if not cursor:
            return result

def summarize_adoptions(records: list[dict]) -> list[dict]:
    groups = {}
    for record in records:
        if 'species' not in record or 'count' not in record or 'adoption_fee' not in record or (record['adoption_fee'] < 0):
            raise ValueError('invalid record')
        species = record['species']
        if species not in groups:
            groups[species] = {'species': species, 'count': 0, 'total_fee': 0, 'cities': []}
        group = groups[species]
        group['count'] += 1
        group['total_fee'] += record['adoption_fee']
        city = record.get('city')
        if city and city not in group['cities']:
            group['cities'].append(city)
    return sorted(groups.values(), key=lambda x: (-x['count'], x['species']))

