import json
from datetime import date

def _check(record):
    if not isinstance(record, dict) or set(record) != {'candidate', 'certificate', 'score', 'completed', 'attempts'}:
        raise ValueError('invalid record')
    if not isinstance(record['candidate'], str) or not record['candidate']:
        raise ValueError('invalid record')
    if not isinstance(record['certificate'], str) or not record['certificate']:
        raise ValueError('invalid record')
    if isinstance(record['score'], bool) or not isinstance(record['score'], int) or (not 0 <= record['score'] <= 100):
        raise ValueError('invalid record')
    if isinstance(record['attempts'], bool) or not isinstance(record['attempts'], int) or record['attempts'] < 1:
        raise ValueError('invalid record')
    if not isinstance(record['completed'], str):
        raise ValueError('invalid record')
    try:
        date.fromisoformat(record['completed'])
    except Exception as exc:
        raise ValueError('invalid record') from exc
    if len(record['completed']) != 10:
        raise ValueError('invalid record')

def pack_records(records):
    if not isinstance(records, list):
        raise ValueError('invalid records')
    for record in records:
        _check(record)
    return json.dumps(records, separators=(',', ':'), sort_keys=True).encode()

def unpack_records(blob):
    try:
        if not isinstance(blob, bytes):
            raise ValueError('invalid payload')
        value = json.loads(blob.decode('utf-8'))
        if not isinstance(value, list):
            raise ValueError('invalid payload')
        for record in value:
            _check(record)
        return value
    except Exception as exc:
        if isinstance(exc, ValueError):
            raise
        raise ValueError('invalid payload') from exc

def merge_records(blob, additions):
    if not isinstance(additions, list):
        raise ValueError('invalid records')
    old = unpack_records(blob)
    for record in additions:
        _check(record)
    chosen = {}
    for record in old + additions:
        key = (record['candidate'], record['certificate'])
        if key not in chosen:
            chosen[key] = record.copy()
        else:
            current = chosen[key]
            if (record['score'], record['completed'], -record['attempts']) > (current['score'], current['completed'], -current['attempts']):
                chosen[key] = record.copy()
    return pack_records(sorted(chosen.values(), key=lambda r: (r['candidate'], r['certificate'])))

def rank_certificates(blob):
    groups = {}
    for record in unpack_records(blob):
        groups.setdefault(record['certificate'], []).append(record)
    result = []
    for certificate, items in groups.items():
        top = min(items, key=lambda r: (-r['score'], r['attempts'], -int(r['completed'].replace('-', '')), r['candidate']))
        result.append({'certificate': certificate, 'count': len(items), 'average_score': round(sum((r['score'] for r in items)) / len(items), 2), 'top_candidate': top['candidate']})
    return sorted(result, key=lambda r: (-r['average_score'], -r['count'], r['certificate']))

