import json

def _valid_sessions(sessions):
    if not isinstance(sessions, list):
        raise ValueError('sessions must be a list')
    required = {'subject', 'session', 'region', 'start', 'duration', 'participants'}
    for item in sessions:
        if not isinstance(item, dict) or set(item) != required:
            raise ValueError('invalid session')
        if not isinstance(item['subject'], str) or not isinstance(item['session'], str) or (not isinstance(item['region'], str)) or (not isinstance(item['start'], int)) or (not isinstance(item['duration'], int)) or (item['duration'] <= 0) or (not isinstance(item['participants'], int)) or (item['participants'] < 0):
            raise ValueError('invalid session')

def pack_sessions(sessions: list[dict]) -> bytes:
    _valid_sessions(sessions)
    return json.dumps(sessions, separators=(',', ':'), sort_keys=True).encode('utf-8')

def rank_schedule(blob: bytes, region: str, window_start: int, window_end: int, page: int, page_size: int) -> list[dict]:
    if window_start > window_end or page < 1 or page_size < 1:
        raise ValueError('invalid range or page')
    try:
        sessions = json.loads(blob.decode('utf-8'))
        _valid_sessions(sessions)
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    groups = {}
    for item in sessions:
        if item['region'] != region or item['start'] < window_start or item['start'] + item['duration'] > window_end:
            continue
        subject = item['subject']
        group = groups.setdefault(subject, {'subject': subject, 'sessions': 0, 'participants': 0, 'average_duration': 0.0, '_total': 0, '_first': item['start']})
        group['sessions'] += 1
        group['participants'] += item['participants']
        group['_total'] += item['duration']
        group['_first'] = min(group['_first'], item['start'])
    ordered = sorted(groups.values(), key=lambda x: (-x['participants'], x['_first'], x['subject']))
    result = []
    for group in ordered:
        result.append({'subject': group['subject'], 'sessions': group['sessions'], 'participants': group['participants'], 'average_duration': round(group['_total'] / group['sessions'], 2)})
    begin = (page - 1) * page_size
    return result[begin:begin + page_size]

