def fetch_distribution_schedule(base_url: str, postcode: str, day: str, api_key: str, min_remaining: int=1) -> list[dict]:
    if not isinstance(base_url, str) or not base_url.strip() or (not isinstance(postcode, str)) or (not postcode.strip()) or (not isinstance(api_key, str)) or (not api_key.strip()):
        raise ValueError('text arguments must be non-empty')
    try:
        datetime.date.fromisoformat(day)
    except (TypeError, ValueError):
        raise ValueError('day must be an ISO date')
    if isinstance(min_remaining, bool) or not isinstance(min_remaining, int) or min_remaining < 0:
        raise ValueError('min_remaining must be a non-negative integer')
    groups = {}
    page = 1
    while True:
        response = requests.get(base_url.rstrip('/') + '/v1/slots', params={'postcode': postcode, 'day': day, 'page': page}, headers={'X-API-Key': api_key})
        if response.status_code != 200:
            raise RuntimeError('request failed')
        payload = response.json()
        for slot in payload['slots']:
            remaining = slot['capacity'] - slot['allocated']
            if slot['date'] == day and slot['status'] == 'open' and (remaining >= min_remaining):
                groups.setdefault(slot['branch'], []).append({'id': slot['id'], 'start': slot['start'], 'end': slot['end'], 'remaining': remaining})
        next_page = payload.get('next_page')
        if next_page is None:
            break
        page = next_page
    result = []
    for branch in sorted(groups):
        slots = sorted(groups[branch], key=lambda item: (item['start'], str(item['id'])))
        result.append({'branch': branch, 'slots': slots})
    return result

