import json

def _validate_session(value):
    if not isinstance(value, dict) or set(value) != {'player', 'level', 'score', 'inventory', 'last_tick'}:
        raise ValueError('invalid session')
    if not isinstance(value['player'], str) or not value['player']:
        raise ValueError('invalid session')
    for key in ('level', 'score', 'last_tick'):
        if type(value[key]) is not int or value[key] < (1 if key == 'level' else 0):
            raise ValueError('invalid session')
    inventory = value['inventory']
    if not isinstance(inventory, dict):
        raise ValueError('invalid session')
    for item, count in inventory.items():
        if not isinstance(item, str) or not item or type(count) is not int or (count < 0):
            raise ValueError('invalid session')

def create_session(player, level=1, score=0, inventory=None, last_tick=0):
    if inventory is None:
        inventory = {}
    result = {'player': player, 'level': level, 'score': score, 'inventory': dict(inventory), 'last_tick': last_tick}
    _validate_session(result)
    return result

def apply_event(session, event):
    _validate_session(session)
    if not isinstance(event, dict) or type(event.get('tick')) is not int:
        raise ValueError('invalid event')
    if type(event.get('points')) is not int or event['points'] < 0:
        raise ValueError('invalid event')
    if event['tick'] <= session['last_tick']:
        raise ValueError('invalid event')
    if 'item' in event and (not isinstance(event['item'], str) or not event['item']):
        raise ValueError('invalid event')
    result = dict(session)
