from datetime import datetime, timezone, timedelta
from decimal import Decimal, InvalidOperation
from html import escape
_FIELDS = ['id', 'card', 'merchant', 'amount', 'timestamp']

def parse_transactions(text: str) -> list[dict]:
    reader = csv.reader(io.StringIO(text))
    try:
        header = next(reader)
    except StopIteration:
        raise ValueError('missing header')
    if header != _FIELDS:
        raise ValueError('invalid header')
    result = []
    for row in reader:
        if not row or all((not x.strip() for x in row)):
            continue
        if len(row) != 5:
            raise ValueError('invalid row')
        ident, card, merchant, amount, stamp = [x.strip() for x in row]
        if not ident or not card or (not merchant):
            raise ValueError('empty field')
        try:
            value = Decimal(amount)
        except InvalidOperation:
            raise ValueError('invalid amount')
        if value < 0:
            raise ValueError('negative amount')
        try:
            if not stamp.endswith('Z'):
                raise ValueError
            moment = datetime.fromisoformat(stamp[:-1] + '+00:00')
            if moment.tzinfo is None:
                raise ValueError
            moment = moment.astimezone(timezone.utc)
        except (ValueError, TypeError):
            raise ValueError('invalid timestamp')
        result.append({'id': ident, 'card': card, 'merchant': merchant, 'amount': value, 'timestamp': moment})
    return result

def detect_fraud(transactions: list[dict], window_minutes: int=60, limit: int=3) -> list[dict]:
    if window_minutes < 0 or limit < 1:
        raise ValueError('invalid detection parameters')
    groups = {}
    for item in transactions:
        groups.setdefault(item['card'], []).append(item)
    found = []
    span = timedelta(minutes=window_minutes)
    for group in groups.values():
        ordered = sorted(group, key=lambda x: (x['timestamp'], x['id']))
        for index, item in enumerate(ordered):
            start = item['timestamp'] - span
            count = sum((start <= other['timestamp'] <= item['timestamp'] for other in ordered))
            if count >= limit:
                copy = dict(item)
                copy['count'] = count
                found.append(copy)
    return sorted(found, key=lambda x: (x['timestamp'], x['id']))

def render_report(alerts: list[dict], title: str='Fraud Alerts') -> str:
    rows = []
    for alert in alerts:
        rows.append('<tr><td>' + escape(str(alert['id'])) + '</td><td>' + escape(str(alert['card'])) + '</td><td>' + escape(str(alert['merchant'])) + '</td><td>' + escape(f"{alert['amount']:.2f}") + '</td><td>' + escape(alert['timestamp'].isoformat()) + '</td><td>' + escape(str(alert['count'])) + '</td></tr>')
    return '<div class="fraud-report"><h1>' + escape(title) + '</h1><table><thead><tr><th>ID</th><th>Card</th><th>Merchant</th><th>Amount</th><th>Timestamp</th><th>Count</th></tr></thead><tbody>' + ''.join(rows) + '</tbody></table></div>'

