import html
import math

def parse_submissions(text: str) -> list[dict]:
    result = []
    for line_number, line in enumerate(text.splitlines(), 1):
        if not line.strip():
            continue
        fields = []
        current = []
        escaped = False
        for char in line:
            if escaped:
                current.append(char)
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '|':
                fields.append(''.join(current))
                current = []
            else:
                current.append(char)
        if escaped:
            raise ValueError(f'invalid submission on line {line_number}')
        fields.append(''.join(current))
        if len(fields) != 4 or not fields[0] or (not fields[3]):
            raise ValueError(f'invalid submission on line {line_number}')
        try:
            score = int(fields[1].strip())
            seconds = float(fields[2].strip())
        except ValueError as exc:
            raise ValueError(f'invalid submission on line {line_number}') from exc
        if score < 0 or seconds < 0 or (not math.isfinite(seconds)):
            raise ValueError(f'invalid submission on line {line_number}')
        result.append({'player': fields[0], 'score': score, 'seconds': seconds, 'region': fields[3]})
    return result

def rank_leaderboard(records: list[dict]) -> list[dict]:
    grouped = {}
    for record in records:
        player = record['player']
        if player not in grouped:
            grouped[player] = {**record, 'attempts': 1}
        else:
            grouped[player]['attempts'] += 1
            old = grouped[player]
            if (record['score'], -record['seconds']) > (old['score'], -old['seconds']):
                grouped[player].update(record)
    ordered = sorted(grouped.values(), key=lambda x: (-x['score'], x['seconds'], x['player'].casefold(), x['player']))
    return [{**item, 'rank': index} for index, item in enumerate(ordered, 1)]

