    body = []
    for row in rows:
        body.append(f"<tr><td>{row['rank']}</td><td>{html.escape(str(row['player']))}</td><td>{row['score']}</td><td>{row['seconds']:.2f}</td><td>{html.escape(str(row['region']))}</td><td>{row['attempts']}</td></tr>")
