def parse_transactions(text: str) -> list[dict]:
    if text == '':
        return []
    reader = csv.reader(io.StringIO(text))
    try:
        header = next(reader)
    except StopIteration:
        return []
    expected = ['timestamp', 'asset', 'amount', 'kind', 'txid']
    if header != expected:
        raise ValueError('invalid header')
    result = []
    for row in reader:
        if len(row) != 5:
            raise ValueError('invalid row')
        timestamp, asset, amount, kind, txid = row
        if not asset or not txid or kind not in ('deposit', 'withdrawal'):
            raise ValueError('invalid field')
        try:
            ts = int(timestamp)
            value = Decimal(amount)
        except (ValueError, InvalidOperation):
            raise ValueError('invalid value')
        if ts < 0 or not value.is_finite() or value <= 0:
            raise ValueError('invalid value')
        result.append({'timestamp': ts, 'asset': asset, 'amount': value, 'kind': kind, 'txid': txid})
    return result

def aggregate_balances(records: list[dict], start: int, end: int) -> list[dict]:
    if start < 0 or end < 0:
        raise ValueError('invalid range')
    totals = {}
    if start > end:
        return []
    for record in records:
        if start <= record['timestamp'] <= end:
            value = record['amount'] if record['kind'] == 'deposit' else -record['amount']
            totals[record['asset']] = totals.get(record['asset'], Decimal('0')) + value
    return [{'asset': asset, 'balance': balance} for asset, balance in sorted(totals.items(), key=lambda item: (-item[1], item[0]))]

def render_wallet_report(records: list[dict], title: str, start: int, end: int) -> str:
    balances = aggregate_balances(records, start, end)
    selected = [] if start > end else [r for r in records if start <= r['timestamp'] <= end]
    selected.sort(key=lambda r: (-r['timestamp'], r['txid']))
    esc = lambda value: html.escape(str(value), quote=True)
    balance_rows = ''.join((f"<tr><td>{esc(row['asset'])}</td><td>{esc(row['balance'])}</td></tr>" for row in balances))
    transaction_rows = ''.join((f"<tr><td>{r['timestamp']}</td><td>{esc(r['asset'])}</td><td>{esc(r['amount'])}</td><td>{esc(r['kind'])}</td><td>{esc(r['txid'])}</td></tr>" for r in selected))
    return f'<section class="wallet-report"><h1>{esc(title)}</h1><h2>Balances</h2><table class="balances"><thead><tr><th>Asset</th><th>Balance</th></tr></thead><tbody>{balance_rows}</tbody></table><h2>Transactions</h2><table class="transactions"><thead><tr><th>Timestamp</th><th>Asset</th><th>Amount</th><th>Kind</th><th>Transaction</th></tr></thead><tbody>{transaction_rows}</tbody></table></section>'

