import json
from datetime import datetime

def encode_state(state: dict) -> bytes:
    try:
        return json.dumps(state, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode('utf-8')
    except (TypeError, ValueError, UnicodeEncodeError) as exc:
        raise ValueError('invalid state') from exc

def decode_state(blob: bytes) -> dict:
    try:
        value = json.loads(blob.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError, AttributeError) as exc:
        raise ValueError('invalid state') from exc
    if not isinstance(value, dict):
        raise ValueError('state must be a dictionary')
    return value

def _time(value):
    try:
        return datetime.strptime(value, '%Y-%m-%dT%H:%M:%SZ')
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid date') from exc

def plan_badges(visitors: list[dict], issued: dict[str, int], now: str, daily_limit: int) -> list[dict]:
    if daily_limit <= 0:
        raise ValueError('invalid limit')
    current = _time(now)
    for count in issued.values():
        if not isinstance(count, int) or isinstance(count, bool) or count < 0:
            raise ValueError('invalid count')
    seen = set()
    eligible = []
    for person in visitors:
        required = ('id', 'name', 'company', 'priority', 'requested_at', 'expires_at')
        if any((key not in person for key in required)):
            raise ValueError('missing visitor field')
        ident, name, company, priority = (person['id'], person['name'], person['company'], person['priority'])
        if not all((isinstance(x, str) for x in (ident, name, company))) or not ident:
            raise ValueError('invalid visitor')
        if not isinstance(priority, int) or isinstance(priority, bool):
            raise ValueError('invalid priority')
        if ident in seen:
            raise ValueError('duplicate visitor')
        seen.add(ident)
        start, end = (_time(person['requested_at']), _time(person['expires_at']))
        if start <= current < end and issued.get(company, 0) < daily_limit:
            eligible.append((person, end))
    eligible.sort(key=lambda item: (-item[0]['priority'], item[1], item[0]['name'].casefold(), item[0]['id']))
    return [{'id': p['id'], 'name': p['name'], 'company': p['company'], 'priority': p['priority']} for p, _ in eligible[:daily_limit]]

