import json
from decimal import Decimal, ROUND_HALF_UP

def dump_plan(plan: dict) -> bytes:
    return json.dumps(plan, separators=(',', ':'), sort_keys=True).encode('utf-8')

def load_plan(payload: bytes) -> dict:
    if not isinstance(payload, bytes):
        raise ValueError('payload must be bytes')
    try:
        plan = json.loads(payload.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid plan') from exc
    if not isinstance(plan, dict):
        raise ValueError('invalid plan')
    return plan

def calculate_contribution(gross_pay: float, payload: bytes) -> dict:
    if not isinstance(gross_pay, (int, float)) or isinstance(gross_pay, bool) or gross_pay < 0:
        raise ValueError('invalid gross pay')
    plan = load_plan(payload)
    try:
        employee_rate = Decimal(str(plan['employee_rate']))
        employer_rate = Decimal(str(plan['employer_rate']))
        annual_cap = Decimal(str(plan['annual_cap']))
    except (KeyError, ArithmeticError, ValueError, TypeError) as exc:
        raise ValueError('invalid plan') from exc
    if not Decimal('0') <= employee_rate <= Decimal('1') or not Decimal('0') <= employer_rate <= Decimal('1') or annual_cap < 0:
        raise ValueError('invalid plan')
    pay = min(Decimal(str(gross_pay)), annual_cap)
    quant = Decimal('0.01')
    return {'pensionable_pay': float(pay), 'employee_contribution': float((pay * employee_rate).quantize(quant, rounding=ROUND_HALF_UP)), 'employer_contribution': float((pay * employer_rate).quantize(quant, rounding=ROUND_HALF_UP))}

