import html

def parse_events(text: str) -> list[dict]:
    result = []
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = []
        current = []
        escaped = False
        for char in raw:
            if escaped:
                if char not in ';\\':
                    raise ValueError('invalid escape')
                current.append(char)
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == ';':
                fields.append(''.join(current))
                current = []
            else:
                current.append(char)
        if escaped:
            raise ValueError('trailing escape')
        fields.append(''.join(current))
        if len(fields) != 4:
            raise ValueError('field count')
        try:
            round_number = int(fields[0], 10)
            amount = int(fields[3], 10)
        except ValueError as exc:
            raise ValueError('number') from exc
        if round_number <= 0 or not fields[1] or fields[2] not in ('attack', 'heal', 'loot'):
            raise ValueError('invalid event')
        result.append({'round': round_number, 'character': fields[1], 'action': fields[2], 'amount': amount})
    return result

def summarize_events(events: list[dict]) -> list[dict]:
    grouped = {}
    for event in events:
        name = event['character']
        if name not in grouped:
