import requests

def fetch_gradebook(base_url: str, student_id: str, token: str) -> dict:
    url = base_url.rstrip('/') + '/students/' + student_id + '/grades'
    response = requests.get(url, params={'include': 'assignments'}, headers={'Authorization': 'Bearer ' + token})
    if response.status_code != 200:
        raise ValueError(f'gradebook request failed: {response.status_code}')
    try:
        data = response.json()
    except Exception:
        raise ValueError('invalid gradebook response')
    if not isinstance(data, dict) or not isinstance(data.get('courses'), list):
        raise ValueError('invalid gradebook response')
    return data

def calculate_gradebook(data: dict, drop_lowest: int=0) -> list[dict]:
    if isinstance(drop_lowest, bool) or not isinstance(drop_lowest, int) or drop_lowest < 0:
        raise ValueError('invalid drop count')
    if not isinstance(data, dict) or not isinstance(data.get('courses'), list):
        raise ValueError('invalid gradebook data')
    output = []
    for course in data['courses']:
        if not isinstance(course, dict) or not isinstance(course.get('code'), str) or (not isinstance(course.get('name'), str)) or (not isinstance(course.get('assignments'), list)):
            raise ValueError('invalid gradebook data')
        assignments = []
        for item in course['assignments']:
            if not isinstance(item, dict) or not isinstance(item.get('name'), str):
                raise ValueError('invalid gradebook data')
            score, points = (item.get('score'), item.get('points'))
            if isinstance(score, bool) or isinstance(points, bool) or (not isinstance(score, (int, float))) or (not isinstance(points, (int, float))) or (points <= 0) or (score < 0) or (score > points):
                raise ValueError('invalid gradebook data')
            assignments.append((score, points, score / points))
        removed = set(sorted(range(len(assignments)), key=lambda i: (assignments[i][2], -i))[:drop_lowest])
        kept = [a for i, a in enumerate(assignments) if i not in removed]
        total_points = sum((a[1] for a in kept))
        average = round(100 * sum((a[0] for a in kept)) / total_points, 2) if total_points else 0.0
        letter = 'A' if average >= 90 else 'B' if average >= 80 else 'C' if average >= 70 else 'D' if average >= 60 else 'F'
        output.append({'code': course['code'], 'name': course['name'], 'average': average, 'letter': letter, 'assignments': len(kept)})
    output.sort(key=lambda x: (x['code'].lower(), x['code']))
    return output

