import requests

def fetch_earthquakes(api_url: str, min_magnitude: float, start_time: int, end_time: int, limit: int=100) -> list[dict]:
    if not math.isfinite(min_magnitude):
        raise ValueError('min_magnitude must be finite')
    if start_time > end_time:
        raise ValueError('start_time must not exceed end_time')
    if not 1 <= limit <= 1000:
        raise ValueError('limit must be between 1 and 1000')
    response = requests.get(api_url, params={'minmagnitude': min_magnitude, 'starttime': start_time, 'endtime': end_time, 'limit': limit}, headers={'User-Agent': 'earthquake-alerts/1.0'})
    if response.status_code != 200:
        raise RuntimeError(f'HTTP status {response.status_code}')
    data = response.json()
    results = []
    for item in data['features']:
        try:
            identifier = item['id']
            properties = item['properties']
            magnitude = float(properties['mag'])
            place = properties['place']
            timestamp = int(properties['time'])
        except (KeyError, TypeError, ValueError):
            continue
        if magnitude < min_magnitude:
            continue
        results.append({'id': identifier, 'place': place, 'magnitude': magnitude, 'time': timestamp})
    results.sort(key=lambda item: (-item['magnitude'], item['time'], str(item['id'])))
    return results

