import json

def _valid_state(state):
    if not isinstance(state, dict) or set(state) != {'parts', 'seen'} or (not isinstance(state['parts'], dict)) or (not isinstance(state['seen'], list)):
        return False
    if any((not isinstance(x, str) for x in state['seen'])):
        return False
    for part, value in state['parts'].items():
        if not isinstance(part, str) or not part or (not isinstance(value, dict)) or (set(value) != {'vehicles', 'severity', 'status'}):
            return False
        if type(value['vehicles']) is not int or value['vehicles'] < 0 or type(value['severity']) is not int or (not 1 <= value['severity'] <= 5) or (value['status'] not in ('open', 'closed')):
            return False
    return True

def encode_state(state: dict) -> bytes:
    return json.dumps(state, separators=(',', ':'), ensure_ascii=False).encode('utf-8')

def decode_state(blob: bytes) -> dict:
    try:
        value = json.loads(blob.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid state') from exc
    if not _valid_state(value):
        raise ValueError('invalid state')
    return value

def apply_recall_events(state: dict, events: list[dict]) -> dict:
    if not _valid_state(state):
        raise ValueError('invalid state')
