        end = date.fromisoformat(end_date)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if start > end:
        raise ValueError('invalid date range')
    response = requests.get(api_url, params={'requester': requester.strip(), 'start_date': start_date, 'end_date': end_date}, headers={'Accept': 'application/json'})
