        payload = response.json()
    except Exception as exc:
        raise ValueError('invalid response') from exc
    if not isinstance(payload, dict) or not isinstance(payload.get('records'), list):
        raise ValueError('invalid response')
    groups = {}
    for record in payload['records']:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        department = record.get('department')
        status = record.get('status')
        days = record.get('days_to_close')
        if not isinstance(department, str) or not isinstance(status, str) or isinstance(days, bool) or (not isinstance(days, (int, float))) or (days < 0):
            raise ValueError('invalid record')
        group = groups.setdefault(department, {'total': 0, 'closed_days': []})
        group['total'] += 1
        if status == 'closed':
            group['closed_days'].append(days)
    result = []
    for department, group in groups.items():
        closed_days = group['closed_days']
        result.append({'department': department, 'total': group['total'], 'closed': len(closed_days), 'average_days': round(sum(closed_days) / len(closed_days), 2) if closed_days else 0.0, 'overdue': sum((days > 30 for days in closed_days))})
    return sorted(result, key=lambda item: (-item['total'], item['department']))

