def encode_claim_state(state: dict) -> bytes:
    return json.dumps(state, sort_keys=True, separators=(',', ':')).encode('utf-8')

def assess_claim(blob: bytes) -> dict:
    try:
        state = json.loads(blob.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid claim state') from exc
    if not isinstance(state, dict):
        raise ValueError('claim state must be an object')
    fields = ('claimant', 'policy_limit', 'estimated_loss', 'deductible', 'prior_payouts')
    if any((field not in state for field in fields)):
        raise ValueError('missing claim field')
    if not isinstance(state['claimant'], str):
        raise ValueError('invalid claimant')
    for field in fields[1:]:
        if isinstance(state[field], bool) or not isinstance(state[field], (int, float)):
            raise ValueError('invalid amount')
    if state['prior_payouts'] < 0:
        raise ValueError('invalid prior payouts')
    payout = max(0, min(state['estimated_loss'] - state['deductible'] - state['prior_payouts'], state['policy_limit']))
    payout = round(payout, 2)
    return {'claimant': state['claimant'], 'payout': payout, 'status': 'approved' if payout > 0 else 'declined'}

