import requests

def build_artifact_report(base_url: str, project: str, build_id: int, min_size: int=0) -> dict:
    if not isinstance(base_url, str) or not base_url:
        raise ValueError('invalid base_url')
    if not isinstance(project, str) or not project:
        raise ValueError('invalid project')
    if isinstance(build_id, bool) or not isinstance(build_id, int) or build_id <= 0:
        raise ValueError('invalid build_id')
    if isinstance(min_size, bool) or not isinstance(min_size, int) or min_size < 0:
        raise ValueError('invalid min_size')
    url = base_url.rstrip('/') + f'/api/projects/{project}/builds/{build_id}/artifacts'
    selected = []
    page = 1
    while True:
        response = requests.get(url, params={'page': page, 'per_page': 100}, headers={'Accept': 'application/json'})
        if response.status_code != 200:
            raise RuntimeError('artifact request failed')
        try:
            body = response.json()
        except Exception as exc:
            raise RuntimeError('invalid response') from exc
        for item in body.get('artifacts', []):
            if not isinstance(item, dict) or any((k not in item for k in ('name', 'size', 'sha256', 'created_at'))):
                raise ValueError('invalid artifact')
            if not isinstance(item['name'], str) or not item['name']:
                raise ValueError('invalid artifact')
            if isinstance(item['size'], bool) or not isinstance(item['size'], int) or item['size'] < 0:
                raise ValueError('invalid artifact')
            if item['size'] >= min_size:
                selected.append(item)
        next_page = body.get('next_page')
        if not isinstance(next_page, int) or isinstance(next_page, bool):
            break
        page = next_page
    groups = {}
    for item in selected:
        name = item['name']
        extension = name.rsplit('.', 1)[1].lower() if '.' in name and (not name.endswith('.')) else '(none)'
        group = groups.setdefault(extension, {'extension': extension, 'count': 0, 'total_size': 0, 'artifacts': []})
        group['count'] += 1
        group['total_size'] += item['size']
        group['artifacts'].append(name)
    result_groups = list(groups.values())
    for group in result_groups:
        group['artifacts'].sort()
    result_groups.sort(key=lambda group: (-group['total_size'], group['extension']))
    return {'artifact_count': len(selected), 'total_size': sum((item['size'] for item in selected)), 'groups': result_groups}

