import requests

def fetch_badges(api_url: str, event_id: str, api_key: str, min_duration: int=0) -> list[dict]:
    if not event_id.strip() or min_duration < 0:
        raise ValueError('invalid arguments')
    url = api_url.rstrip('/') + '/v1/visitors'
    headers = {'Authorization': 'Bearer ' + api_key}
    records = []
    page = 1
    while page is not None:
        r = requests.get(url, headers=headers, params={'event_id': event_id, 'page': page, 'limit': 100})
        if r.status_code != 200:
            raise RuntimeError('request failed')
        try:
            data = r.json()
            visitors = data['visitors']
            next_page = data['next_page']
            if not isinstance(visitors, list) or (next_page is not None and (not isinstance(next_page, int))):
                raise ValueError('invalid response')
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid response')
        for visitor in visitors:
            try:
                ident = visitor['id']
                first = visitor['first_name']
                last = visitor['last_name']
                company = visitor['company']
                status = visitor['status']
                start = datetime.fromisoformat(visitor['check_in'].replace('Z', '+00:00'))
                end = datetime.fromisoformat(visitor['check_out'].replace('Z', '+00:00'))
            except (KeyError, TypeError, ValueError, AttributeError):
                raise ValueError('invalid visitor')
            seconds = (end - start).total_seconds()
            if seconds < 0:
                raise ValueError('invalid duration')
            if status == 'approved' and seconds >= min_duration * 60:
                records.append((last, first, ident, {'id': ident, 'name': first + ' ' + last, 'company': company, 'duration_hours': round(seconds / 3600, 2)}))
        page = next_page
    records.sort(key=lambda item: (item[0].casefold(), item[1].casefold(), str(item[2])))
    return [item[3] for item in records]

