def parse_events(text: str) -> list[dict]:
    if not text.strip():
        raise ValueError('empty input')
    rows = list(csv.reader(StringIO(text)))
    if not rows or rows[0] != ['robot', 'time', 'state', 'battery']:
        raise ValueError('invalid header')
    result = []
    seen = set()
    for row in rows[1:]:
        if not row or all((not x.strip() for x in row)):
            continue
        if len(row) != 4:
            raise ValueError('invalid row')
        robot, stamp, state, battery = [x.strip() for x in row]
        if not robot or not state:
            raise ValueError('empty field')
        if state not in {'idle', 'running', 'error'}:
            raise ValueError('invalid state')
        try:
            when = datetime.strptime(stamp, '%Y-%m-%dT%H:%M:%SZ').replace(tzinfo=timezone.utc)
            if str(int(battery)) != battery:
                raise ValueError
            level = int(battery)
        except Exception as exc:
            raise ValueError('invalid value') from exc
        if not 0 <= level <= 100:
            raise ValueError('invalid battery')
        key = (robot, when)
        if key in seen:
            raise ValueError('duplicate event')
        seen.add(key)
        result.append({'robot': robot, 'time': when, 'state': state, 'battery': level})
    return result

def summarize_events(events: list[dict]) -> list[dict]:
    groups = {}
    required = {'robot', 'time', 'state', 'battery'}
    for event in events:
        if set(event) != required or not isinstance(event['robot'], str) or (not isinstance(event['time'], datetime)) or (not isinstance(event['state'], str)) or (type(event['battery']) is not int):
            raise ValueError('invalid event')
        if event['state'] not in {'idle', 'running', 'error'}:
            raise ValueError('invalid event')
        groups.setdefault(event['robot'], []).append(event)
    result = []
    for robot in sorted(groups):
        items = sorted(groups[robot], key=lambda x: x['time'])
        latest = items[-1]
        result.append({'robot': robot, 'latest_time': latest['time'].strftime('%Y-%m-%dT%H:%M:%SZ'), 'state': latest['state'], 'battery': latest['battery'], 'errors': sum((x['state'] == 'error' for x in items)), 'running_pct': round(sum((x['state'] == 'running' for x in items)) * 100 / len(items), 1)})
    return result

def render_dashboard(events: list[dict]) -> str:
    body = []
    for item in summarize_events(events):
        vals = [item['robot'], item['latest_time'], item['state'], f"{item['battery']}%", item['errors'], f"{item['running_pct']}%"]
        cells = ''.join((f'<td>{html.escape(str(value), quote=True)}</td>' for value in vals))
        body.append(f'<tr>{cells}</tr>')
    return '<section class="robot-dashboard"><h1>Robot Status</h1><table><thead><tr><th>Robot</th><th>Latest</th><th>State</th><th>Battery</th><th>Errors</th><th>Running</th></tr></thead><tbody>' + ''.join(body) + '</tbody></table></section>'

