import json
import math
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def encode_cost_records(records: list[dict]) -> bytes:
    try:
        return json.dumps(records, separators=(',', ':'), allow_nan=False).encode('utf-8')
    except (TypeError, ValueError) as exc:
        raise ValueError('records cannot be encoded') from exc

def summarize_costs(blob: bytes, page: int=1, page_size: int=20) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    try:
        data = json.loads(blob.decode('utf-8'))
    except (AttributeError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid blob') from exc
    if not isinstance(data, list):
        raise ValueError('invalid records')
    totals = {}
    for record in data:
        if not isinstance(record, dict) or not isinstance(record.get('project'), str) or (not record['project']):
            raise ValueError('invalid record')
        cost = record.get('cost')
        if isinstance(cost, bool) or not isinstance(cost, (int, float)) or (not math.isfinite(cost)) or (cost < 0):
            raise ValueError('invalid cost')
        try:
            totals[record['project']] = totals.get(record['project'], Decimal('0')) + Decimal(str(cost))
        except (InvalidOperation, ValueError) as exc:
            raise ValueError('invalid cost') from exc
    items = [{'project': name, 'total_cost': float(total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))} for name, total in totals.items()]
    items.sort(key=lambda item: (-item['total_cost'], item['project']))
    start = (page - 1) * page_size
    return {'total_projects': len(items), 'items': items[start:start + page_size]}

