def fetch_memberships(api_url: str, club_id: str, token: str) -> list[dict]:
    url = api_url.rstrip('/') + '/clubs/' + club_id + '/memberships'
    response = requests.get(url, params={'active': 'all'}, headers={'Authorization': 'Bearer ' + token})
    if response.status_code != 200:
        raise ValueError(f'membership request failed: {response.status_code}')
    try:
        body = response.json()
    except Exception as exc:
        raise ValueError('invalid membership response') from exc
    if not isinstance(body, dict) or not isinstance(body.get('memberships'), list):
        raise ValueError('invalid membership response')
    return body['memberships']

def summarize_memberships(records: list[dict], as_of: str) -> dict:
    try:
        cutoff = datetime.date.fromisoformat(as_of)
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid date') from exc
    plans = {}
    active = []
    for record in records:
        try:
            start = datetime.date.fromisoformat(record['start'])
            end = None if record['end'] is None else datetime.date.fromisoformat(record['end'])
            visits = [datetime.date.fromisoformat(value) for value in record['visits']]
        except (KeyError, TypeError, ValueError) as exc:
            raise ValueError('invalid membership record') from exc
        plan = record['plan']
        plans.setdefault(plan, {'active': 0, 'visits': 0})
        count = sum((start <= visit <= cutoff for visit in visits))
        is_active = start <= cutoff and (end is None or cutoff < end)
        if is_active:
            entry = {'member_id': record['member_id'], 'name': record['name'], 'plan': plan, 'visits': count}
            active.append(entry)
            plans[plan]['active'] += 1
            plans[plan]['visits'] += count
    active.sort(key=lambda item: (-item['visits'], item['name'].casefold(), item['member_id']))
    return {'active': active, 'by_plan': {key: plans[key] for key in sorted(plans)}, 'total_active': len(active)}

