def fetch_notification_summary(user_id: str, api_key: str, min_priority: int=0) -> dict:
    if user_id == '':
        raise ValueError('user_id must not be empty')
    if min_priority < 0 or min_priority > 10:
        raise ValueError('min_priority must be between 0 and 10')
    url = f'https://push.example.com/v1/users/{user_id}/notifications'
    response = requests.get(url, params={'limit': 100}, headers={'Authorization': f'Bearer {api_key}'})
    if response.status_code != 200:
        raise RuntimeError(f'notification service returned {response.status_code}')
    notifications = response.json()['notifications']
    groups = {}
    unread = 0
    total = 0
    for item in notifications:
        if item['priority'] < min_priority:
            continue
        category = item['category']
        group = groups.setdefault(category, {'count': 0, 'unread': 0, 'priority': 0})
        group['count'] += 1
        group['priority'] += item['priority']
        total += 1
        if not item['read']:
            group['unread'] += 1
            unread += 1
    categories = []
    for category, group in groups.items():
        categories.append({'category': category, 'count': group['count'], 'unread': group['unread'], 'avg_priority': round(group['priority'] / group['count'], 2)})
    categories.sort(key=lambda item: (-item['count'], item['category']))
    return {'user_id': user_id, 'total': total, 'unread': unread, 'by_category': categories}

