from typing import Any

def encode_sales_state(state: dict) -> bytes:
    if not isinstance(state, dict):
        raise TypeError('state must be a dictionary')
    try:
        text = json.dumps(state, ensure_ascii=False, sort_keys=True, separators=(',', ':'))
    except (TypeError, ValueError) as exc:
        raise ValueError('state cannot be encoded') from exc
    return text.encode('utf-8')

def decode_sales_state(blob: bytes) -> dict:
    if not isinstance(blob, bytes):
        raise TypeError('blob must be bytes')
    try:
        value: Any = json.loads(blob.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid state data') from exc
    if not isinstance(value, dict):
        raise ValueError('state must be a dictionary')
    return value

