import requests

def _time(value):
    if not isinstance(value, str) or not value.endswith('Z'):
        raise ValueError('invalid timestamp')
    return datetime.fromisoformat(value[:-1] + '+00:00')

def fetch_shipments(country: str, api_key: str) -> list[dict]:
    response = requests.get('https://aid.example.org/v1/shipments', params={'country': country}, headers={'Authorization': 'Bearer ' + api_key, 'Accept': 'application/json'}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError('shipment service returned ' + str(response.status_code))
    payload = response.json()
    if not isinstance(payload, dict) or not isinstance(payload.get('shipments'), list):
        raise ValueError('invalid shipment payload')
    return payload['shipments']

