    _time(as_of)
    result = []
    for shipment in shipments:
        events = shipment.get('events', [])
        ordered = sorted(events, key=lambda event: _time(event['timestamp']))
        if ordered:
            first = _time(ordered[0]['timestamp'])
            final = _time(ordered[-1]['timestamp'])
            current = ordered[-1]
            elapsed = round((final - first).total_seconds() / 86400, 2)
            status = current['status']
            location = current['location']
        else:
            elapsed = 0.0
            status = 'pending'
            location = None
        result.append({'id': shipment['id'], 'status': status, 'location': location, 'elapsed_days': elapsed, 'weight_kg': shipment['weight_kg'], '_priority': shipment['priority']})
    result.sort(key=lambda item: (-item.pop('_priority'), item['id']))
    return result

