    summaries = summarize_shipments(fetch_shipments(country, api_key), as_of)
    counts = {}
    for item in summaries:
        counts[item['status']] = counts.get(item['status'], 0) + 1
    counts = {key: counts[key] for key in sorted(counts)}
    return {'country': country, 'shipments': summaries, 'total_weight_kg': round(sum((item['weight_kg'] for item in summaries)), 2), 'by_status': counts}

