import html
import math

def render_call_quality_report(records: list[dict], page: int=1, page_size: int=10, min_score: float=0.0) -> str:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 50):
        raise ValueError('invalid page size')
    if isinstance(min_score, bool) or not isinstance(min_score, (int, float)) or (not math.isfinite(min_score)) or (not 0 <= min_score <= 5):
        raise ValueError('invalid minimum score')
    valid_outcomes = {'completed', 'dropped', 'transferred'}
    checked = []
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        if any((not isinstance(record.get(key), str) or not record[key] for key in ('call_id', 'agent'))):
            raise ValueError('invalid text')
        score = record.get('score')
        duration = record.get('duration_seconds')
        if isinstance(score, bool) or not isinstance(score, (int, float)) or (not math.isfinite(score)) or (not 0 <= score <= 5):
            raise ValueError('invalid score')
        if isinstance(duration, bool) or not isinstance(duration, int) or duration < 0:
            raise ValueError('invalid duration')
        if record.get('outcome') not in valid_outcomes:
            raise ValueError('invalid outcome')
        if score >= min_score:
            checked.append(record)
    checked.sort(key=lambda r: (-r['score'], r['agent'].casefold(), r['call_id']))
    total = len(checked)
    start_index = (page - 1) * page_size
    selected = checked[start_index:start_index + page_size]
