            raise ValueError('invalid area')
        key = (field, product)
        if key not in groups:
            groups[key] = [0, 0.0, 0.0]
        groups[key][0] += 1
        groups[key][1] += liters
        groups[key][2] += area
    rows = sorted(groups.items(), key=lambda item: (-item[1][1], item[0][0], item[0][1]))
    start = (page - 1) * page_size
    selected = rows[start:start + page_size]
    output = ['<table class="applications">', '<thead><tr><th>Field</th><th>Product</th><th>Applications</th><th>Total Liters</th><th>Total Area</th></tr></thead>', '<tbody>']
