    if len(parts) != 5:
        raise ValueError('wrong field count')
    try:
        if not parts[0].endswith('Z'):
            raise ValueError('timestamp')
        timestamp = datetime.fromisoformat(parts[0][:-1] + '+00:00')
        if timestamp.tzinfo is None or timestamp.utcoffset().total_seconds() != 0:
            raise ValueError('timestamp')
        severity = int(parts[3])
    except (TypeError, ValueError):
        raise ValueError('invalid event')
    if not parts[1] or not parts[2] or severity not in range(1, 6) or (parts[4] not in ('open', 'closed')):
        raise ValueError('invalid event')
    return {'timestamp': timestamp, 'zone': parts[1], 'kind': parts[2], 'severity': severity, 'status': parts[4]}

def summarize_alarms(lines: list[str], as_of: datetime) -> list[dict[str, object]]:
    if as_of.tzinfo is None or as_of.utcoffset().total_seconds() != 0:
        raise ValueError('as_of must be UTC')
    events = [parse_alarm_line(line) for line in lines]
    events.sort(key=lambda event: event['timestamp'])
    states = {}
    for event in events:
        if event['timestamp'] > as_of:
            raise ValueError('future event')
        key = (event['zone'], event['kind'])
        state = states.setdefault(key, {'zone': event['zone'], 'kind': event['kind'], 'events': 0, 'closed': 0, 'open': None, 'seconds': 0, 'max_severity': 0})
        state['events'] += 1
        state['max_severity'] = max(state['max_severity'], event['severity'])
        if event['status'] == 'open':
            if state['open'] is not None:
                raise ValueError('duplicate open')
            state['open'] = event['timestamp']
        else:
            if state['open'] is None:
                raise ValueError('unmatched close')
            state['seconds'] += int((event['timestamp'] - state['open']).total_seconds())
            state['open'] = None
            state['closed'] += 1
    result = []
    for state in states.values():
        if state['open'] is not None:
            state['seconds'] += int((as_of - state['open']).total_seconds())
            state['open'] = 1
        else:
            state['open'] = 0
        result.append(state)
    return sorted(result, key=lambda x: (-x['max_severity'], -x['seconds'], x['zone'], x['kind']))

def render_alarm_report(lines: list[str], as_of: datetime) -> str:
    summaries = summarize_alarms(lines, as_of)
    rows = ''.join((f"<tr><td>{item['zone']}</td><td>{item['kind']}</td><td>{item['events']}</td><td>{item['closed']}</td><td>{item['open']}</td><td>{item['seconds']}</td><td>{item['max_severity']}</td></tr>" for item in summaries))
    return '<div class="alarm-report"><h1>Alarm report</h1><table><thead><tr><th>Zone</th><th>Kind</th><th>Events</th><th>Closed</th><th>Open</th><th>Seconds</th><th>Max severity</th></tr></thead><tbody>' + rows + '</tbody></table></div>'

