def render_property_tax_report(records: list[dict], district: str | None=None, page: int=1, per_page: int=10) -> str:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(per_page, bool) or not isinstance(per_page, int) or per_page < 1:
        raise ValueError('invalid per_page')
    if not isinstance(records, list):
        raise ValueError('invalid records')
    filtered = []
    for item in records:
        if not isinstance(item, dict):
            raise ValueError('invalid record')
        required = ('parcel_id', 'owner', 'district', 'assessed_value', 'tax_rate')
        if any((key not in item for key in required)):
            raise ValueError('invalid record')
        if any((not isinstance(item[key], str) for key in ('parcel_id', 'owner', 'district'))):
            raise ValueError('invalid record')
        if isinstance(item['assessed_value'], bool) or isinstance(item['tax_rate'], bool):
            raise ValueError('invalid record')
        try:
            value = Decimal(str(item['assessed_value']))
            rate = Decimal(str(item['tax_rate']))
        except (InvalidOperation, ValueError):
            raise ValueError('invalid record')
        if not value.is_finite() or not rate.is_finite() or value < 0 or (rate < 0):
            raise ValueError('invalid record')
        if district is None or item['district'] == district:
            filtered.append((item, value, rate))
    filtered.sort(key=lambda x: (-x[1], x[0]['parcel_id']))
    quant = Decimal('0.01')
    taxes = [(item, value, (value * rate / Decimal('100')).quantize(quant, rounding=ROUND_HALF_UP)) for item, value, rate in filtered]
    total_tax = sum((tax for _, _, tax in taxes), Decimal('0')).quantize(quant, rounding=ROUND_HALF_UP)
    start = (page - 1) * per_page
    shown = taxes[start:start + per_page]
    money = lambda value: f'${value:,.2f}'
    rows = []
    for item, value, tax in shown:
        rows.append(f"<tr><td>{escape(item['parcel_id'])}</td><td>{escape(item['owner'])}</td><td>{escape(item['district'])}</td><td>{money(value.quantize(quant, rounding=ROUND_HALF_UP))}</td><td>{money(tax)}</td></tr>")
    return f"""<div class="tax-report"><div class="summary">Showing {len(shown)} of {len(filtered)} parcels; total tax {money(total_tax)}</div><table><thead><tr><th>Parcel</th><th>Owner</th><th>District</th><th>Assessed Value</th><th>Tax</th></tr></thead><tbody>{''.join(rows)}</tbody></table></div>"""

