import requests

def parse_plot_feed(payload: dict) -> list[dict]:
    if not isinstance(payload, dict) or not isinstance(payload.get('plots'), list):
        raise ValueError('plots must be a list')
    result = []
    for item in payload['plots']:
        if not isinstance(item, dict):
            raise ValueError('plot must be an object')
        try:
            record = {'id': str(item['id']), 'section': str(item['section']), 'row': int(item['row']), 'column': int(item['column']), 'status': str(item['status'])}
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid plot')
        occupants = item.get('occupants', [])
        if not isinstance(occupants, list):
            raise ValueError('occupants must be a list')
        normalized = []
        for occupant in occupants:
            if not isinstance(occupant, dict) or 'name' not in occupant:
                raise ValueError('invalid occupant')
            normalized.append({'name': str(occupant['name']), 'burial_year': occupant.get('burial_year')})
        record['occupants'] = normalized
        result.append(record)
    return result

def fetch_plots(base_url: str, cemetery_id: str, api_key: str | None=None) -> list[dict]:
    headers = {'X-API-Key': api_key} if api_key is not None else {}
    response = requests.get(base_url.rstrip('/') + '/cemeteries/' + str(cemetery_id) + '/plots', params={'cemetery_id': cemetery_id}, headers=headers)
    if not 200 <= response.status_code < 300:
        raise RuntimeError('plot service returned ' + str(response.status_code))
    return parse_plot_feed(response.json())

def summarize_plots(records: list[dict], year: int | None=None) -> dict:
    sections = {}
    occupied = 0
    occupant_count = 0
    available = 0
    reserved = 0
    for record in records:
        people = [x for x in record['occupants'] if year is None or x.get('burial_year') == year]
        section = str(record['section'])
        if section not in sections:
            sections[section] = {'total': 0, 'occupied': 0, 'occupant_count': 0}
        entry = sections[section]
        entry['total'] += 1
        entry['occupant_count'] += len(people)
        occupant_count += len(people)
        if people:
            entry['occupied'] += 1
            occupied += 1
        if record['status'] == 'available':
            available += 1
        if record['status'] == 'reserved':
            reserved += 1
    return {'total_plots': len(records), 'occupied_plots': occupied, 'available_plots': available, 'reserved_plots': reserved, 'occupant_count': occupant_count, 'sections': {key: sections[key] for key in sorted(sections)}}

