from decimal import Decimal, InvalidOperation
from datetime import date
import re
from html import escape
_AMOUNT = re.compile('\\d+(?:\\.\\d{1,2})?\\Z')
_DATE = re.compile('\\d{4}-\\d{2}-\\d{2}\\Z')

def parse_amount(value: str) -> Decimal:
    if not isinstance(value, str) or not _AMOUNT.fullmatch(value):
        raise ValueError('invalid amount')
    try:
        result = Decimal(value).quantize(Decimal('0.01'))
    except InvalidOperation:
        raise ValueError('invalid amount')
    return result

def _record(record):
    if not isinstance(record, dict):
        raise ValueError('invalid record')
    for key in ('beneficiary', 'amount', 'date', 'category'):
        if key not in record:
            raise ValueError('invalid record')
    beneficiary = record['beneficiary']
    category = record['category']
    if not isinstance(beneficiary, str) or not beneficiary:
        raise ValueError('invalid beneficiary')
    if not isinstance(category, str) or not category:
        raise ValueError('invalid category')
    if not isinstance(record['date'], str) or not _DATE.fullmatch(record['date']):
        raise ValueError('invalid date')
    try:
        when = date.fromisoformat(record['date'])
    except ValueError:
        raise ValueError('invalid date')
    return (beneficiary, parse_amount(record['amount']), when, category)

def summarize_beneficiaries(records: list[dict], year: int) -> list[dict]:
    groups = {}
    for record in records:
        beneficiary, amount, when, category = _record(record)
        if when.year != year:
            continue
        item = groups.setdefault(beneficiary, {'beneficiary': beneficiary, 'grants': 0, 'total': Decimal('0.00'), 'categories': {}})
        item['grants'] += 1
        item['total'] += amount
        item['categories'][category] = item['categories'].get(category, Decimal('0.00')) + amount
    return sorted(groups.values(), key=lambda x: (-x['total'], x['beneficiary'].casefold(), x['beneficiary']))

def render_foundation_report(records: list[dict], year: int) -> str:
    summaries = summarize_beneficiaries(records, year)
    rows = []
    grand = Decimal('0.00')
    count = 0
    for item in summaries:
        categories = ', '.join((f'{escape(name, quote=True)}: ${amount:.2f}' for name, amount in sorted(item['categories'].items())))
        rows.append(f"<tr><td>{escape(item['beneficiary'], quote=True)}</td><td>{item['grants']}</td><td>${item['total']:.2f}</td><td>{categories}</td></tr>")
        grand += item['total']
        count += item['grants']
    return f"""<table class="beneficiaries"><thead><tr><th>Beneficiary</th><th>Grants</th><th>Total</th><th>Categories</th></tr></thead><tbody>{''.join(rows)}</tbody><tfoot><tr><th colspan="2">Grand total</th><th>${grand:.2f}</th><th>{count} grants</th></tr></tfoot></table>"""

