    return json.dumps(records, separators=(',', ':')).encode('utf-8')

def rank_inventory(payload: bytes, market: str, min_impressions: int, limit: int) -> list[dict]:
    if min_impressions < 0 or limit <= 0:
        raise ValueError('invalid arguments')
    try:
        records = json.loads(payload)
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(records, list):
        raise ValueError('invalid records')
    totals = {}
    required = ('spot_id', 'advertiser', 'market', 'cpm', 'impressions', 'available')
    for record in records:
        if not isinstance(record, dict) or any((key not in record for key in required)):
            raise ValueError('invalid record')
        if not isinstance(record['advertiser'], str) or not isinstance(record['market'], str) or (not isinstance(record['cpm'], numbers.Real)) or isinstance(record['cpm'], bool) or (not isinstance(record['impressions'], int)) or isinstance(record['impressions'], bool) or (not isinstance(record['available'], bool)):
            raise ValueError('invalid record')
        if record['market'] != market or not record['available'] or record['impressions'] < min_impressions:
            continue
        advertiser = record['advertiser']
        item = totals.setdefault(advertiser, [0, 0, 0.0])
        item[0] += 1
        item[1] += record['impressions']
        item[2] += record['cpm'] * record['impressions'] / 1000
    ordered = sorted(totals.items(), key=lambda pair: (-pair[1][2], pair[0]))
    return [{'advertiser': name, 'spots': values[0], 'impressions': values[1], 'spend': round(values[2], 2)} for name, values in ordered[:limit]]

