import json
import datetime

def _check_record(record):
    if not isinstance(record, dict) or set(record) != {'book', 'member', 'due', 'returned', 'renewals'}:
        raise ValueError('invalid record')
    if not isinstance(record['book'], str) or not record['book']:
        raise ValueError('invalid book')
    if not isinstance(record['member'], str) or not record['member']:
        raise ValueError('invalid member')
    if not isinstance(record['returned'], bool):
        raise ValueError('invalid returned')
    if not isinstance(record['renewals'], int) or isinstance(record['renewals'], bool) or record['renewals'] < 0:
        raise ValueError('invalid renewals')
    try:
        datetime.date.fromisoformat(record['due'])
    except (TypeError, ValueError):
        raise ValueError('invalid due')

def dump_library_state(loans: list[dict]) -> bytes:
    if not isinstance(loans, list):
        raise ValueError('invalid state')
    for record in loans:
        _check_record(record)
    return json.dumps(loans, separators=(',', ':'), sort_keys=True).encode('utf-8')

def load_library_state(blob: bytes) -> list[dict]:
    try:
        if not isinstance(blob, bytes):
            raise ValueError
        value = json.loads(blob.decode('utf-8'))
        if not isinstance(value, list):
            raise ValueError
        for record in value:
            _check_record(record)
        return value
    except (ValueError, TypeError, UnicodeError, json.JSONDecodeError):
        raise ValueError('invalid state blob')

def build_lending_report(blob: bytes, as_of: str) -> dict:
    try:
        day = datetime.date.fromisoformat(as_of)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    loans = load_library_state(blob)
    groups = {}
    for loan in loans:
        if not loan['returned']:
            overdue = datetime.date.fromisoformat(loan['due']) < day
            item = {'book': loan['book'], 'due': loan['due'], 'renewals': loan['renewals'], 'overdue': overdue}
            groups.setdefault(loan['member'], []).append(item)
    members = []
    for member, books in groups.items():
        books.sort(key=lambda x: (x['due'], x['book']))
        members.append({'member': member, 'active': len(books), 'overdue': sum((x['overdue'] for x in books)), 'books': books})
    members.sort(key=lambda x: (-x['overdue'], -x['active'], x['member']))
    return {'as_of': as_of, 'active_loans': sum((x['active'] for x in members)), 'overdue_loans': sum((x['overdue'] for x in members)), 'members': members}

