    total_items = 0
    for record in records:
        if record['case_id'] == case_id and record['admitted']:
            total_items += 1
            group = groups.setdefault(record['category'], [0, 0.0])
            group[0] += 1
            group[1] += record['weight_grams']
    categories = [{'category': name, 'count': value[0], 'total_weight_grams': round(value[1], 2)} for name, value in groups.items()]
