    if page < 1 or page_size < 1 or (start_ts is not None and end_ts is not None and (start_ts > end_ts)):
        raise ValueError('invalid query')
    try:
        rows = json.loads(blob.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(rows, list):
        raise ValueError('invalid readings')
    checked = []
    for row in rows:
        if not isinstance(row, dict) or set(row) != {'timestamp', 'zone', 'reading'}:
            raise ValueError('invalid reading')
        ts, zone, value = (row['timestamp'], row['zone'], row['reading'])
        if isinstance(ts, bool) or not isinstance(ts, int) or (not isinstance(zone, str)) or (not zone):
            raise ValueError('invalid reading')
        if isinstance(value, bool) or not isinstance(value, (int, float)) or (not math.isfinite(value)):
            raise ValueError('invalid reading')
        if (start_ts is None or ts >= start_ts) and (end_ts is None or ts <= end_ts):
            checked.append((ts, zone, float(value)))
