from datetime import date
from decimal import Decimal, InvalidOperation
import html

def parse_enrollment(line: str) -> dict:
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            if char not in '|\\':
                raise ValueError('invalid escape')
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    fields.append(''.join(current))
    if len(fields) != 5 or any((not fields[i] for i in range(3))):
        raise ValueError('invalid fields')
    try:
        premium = Decimal(fields[3])
        if premium < 0 or premium.as_tuple().exponent < -2:
            raise ValueError('invalid premium')
        effective = date.fromisoformat(fields[4])
        if effective.isoformat() != fields[4]:
            raise ValueError('invalid date')
    except (InvalidOperation, ValueError):
        raise ValueError('invalid value')
    return {'employee': fields[0], 'plan': fields[1], 'tier': fields[2], 'premium': premium, 'effective': effective}

def summarize_enrollments(lines: list[str]) -> list[dict]:
    chosen = {}
    for line in lines:
        if not line.strip():
            continue
        item = parse_enrollment(line)
        key = (item['employee'], item['plan'])
        old = chosen.get(key)
        if old is None or item['effective'] >= old['effective']:
            chosen[key] = item
    grouped = {}
    for item in chosen.values():
        grouped.setdefault(item['employee'], []).append(item)
    result = []
    for employee in sorted(grouped, key=lambda x: (x.casefold(), x)):
        plans = sorted(grouped[employee], key=lambda x: (-x['effective'].toordinal(), x['plan'].casefold(), x['plan']))
        result.append({'employee': employee, 'plans': [{'plan': x['plan'], 'tier': x['tier'], 'premium': x['premium'], 'effective': x['effective']} for x in plans], 'total_premium': sum((x['premium'] for x in plans), Decimal('0'))})
    return result

def render_report(title: str, summaries: list[dict]) -> str:
    rows = []
    total = Decimal('0')
    for summary in summaries:
