from datetime import date
from decimal import Decimal, ROUND_HALF_UP
import requests

def fetch_certification_records(component_ids: list[str], endpoint: str, api_key: str) -> list[dict]:
    if not component_ids:
        raise ValueError('component_ids must not be empty')
    response = requests.get(endpoint.rstrip('/') + '/certifications', params={'component_ids': ','.join(component_ids)}, headers={'Authorization': 'Bearer ' + api_key}, timeout=10)
    response.raise_for_status()
    data = response.json()
    if not isinstance(data, dict) or not isinstance(data.get('items'), list):
        raise ValueError('invalid response')
    return data['items']

def build_certification_report(records: list[dict], as_of: str) -> list[dict]:
    try:
        reference = date.fromisoformat(as_of)
    except Exception as exc:
        raise ValueError('invalid date') from exc
    output = []
    for record in records:
        try:
            component = record['component']
            expires_text = record['expires']
            expires = date.fromisoformat(expires_text)
            tests = record['tests']
        except Exception as exc:
            raise ValueError('invalid record') from exc
        if not isinstance(component, str) or not isinstance(tests, list):
            raise ValueError('invalid record')
        names = set()
        total_weight = Decimal('0')
        total_score = Decimal('0')
        passed = 0
        for test in tests:
            try:
                name = test['name']
                status = test['status']
                score = Decimal(str(test['score']))
                weight = Decimal(str(test['weight']))
            except Exception as exc:
                raise ValueError('invalid test') from exc
            if name in names or not isinstance(name, str) or score < 0 or (score > 100) or (weight <= 0):
                raise ValueError('invalid test')
            names.add(name)
            total_score += score * weight
            total_weight += weight
            if status == 'PASS':
                passed += 1
        weighted = (total_score / total_weight).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) if total_weight else Decimal('0.0')
        if expires >= reference and passed == len(tests):
            status = 'CERTIFIED'
        elif expires < reference:
            status = 'EXPIRED'
        else:
            status = 'FAILED'
        output.append({'component': component, 'expires': expires_text, 'passed_tests': passed, 'weighted_score': float(weighted), 'status': status})
    priority = {'CERTIFIED': 0, 'FAILED': 1, 'EXPIRED': 2}
    output.sort(key=lambda item: (priority[item['status']], -item['weighted_score'], item['component']))
    return output

