_NAME = re.compile('^[A-Za-z0-9_.-]+$')
_VER = re.compile('^(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)(?:-([0-9A-Za-z.-]+))?$')

def _date(value):
    try:
        return datetime.date.fromisoformat(value)
    except Exception:
        raise ValueError('invalid date')

def parse_registry(text: str) -> list[dict]:
    out = []
    for line_no, line in enumerate(text.splitlines(), 1):
        if not line.strip():
            continue
        try:
            row = next(csv.reader([line]))
            if row == ['name', 'version', 'uploaded', 'downloads', 'yanked'] and (not out):
                continue
            if len(row) != 5:
                raise ValueError('field count')
            name, version, uploaded, downloads, yanked = row
            if not _NAME.fullmatch(name) or not _VER.fullmatch(version):
                raise ValueError('format')
            _date(uploaded)
            count = int(downloads)
            if count < 0 or yanked not in ('0', '1'):
                raise ValueError('value')
            out.append({'name': name, 'version': version, 'uploaded': uploaded, 'downloads': count, 'yanked': yanked == '1'})
        except Exception as exc:
            raise ValueError(f'invalid registry row at line {line_no}') from exc
    return out

def _vkey(version):
    match = _VER.fullmatch(version)
    major, minor, patch, pre = match.groups()
    if pre is None:
        return (int(major), int(minor), int(patch), (1,))
    parts = []
    for item in pre.split('.'):
        parts.append((0, int(item)) if item.isdigit() else (1, item))
    return (int(major), int(minor), int(patch), (0, parts))

def select_releases(records: list[dict], as_of: str, per_package: int=2) -> list[dict]:
