    by_name = {}
    for _, record in grouped.values():
        by_name.setdefault(record['name'], []).append(record)
    result = []
    for name in sorted(by_name):
        result.extend(sorted(by_name[name], key=lambda r: _vkey(r['version']), reverse=True)[:per_package])
    return result

