import json
import datetime

def _check_record(record):
    if not isinstance(record, dict) or set(record) != {'case_id', 'due', 'priority', 'status'}:
        raise ValueError('invalid record')
    if not isinstance(record['case_id'], str) or not record['case_id']:
        raise ValueError('invalid case id')
    try:
        datetime.date.fromisoformat(record['due'])
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if type(record['priority']) is not int or not 1 <= record['priority'] <= 5:
        raise ValueError('invalid priority')
    if record['status'] not in ('open', 'closed'):
        raise ValueError('invalid status')

def _read(blob):
    try:
        value = json.loads(blob.decode('utf-8'))
        if not isinstance(value, list):
            raise ValueError
        for item in value:
            _check_record(item)
        return value
    except Exception as exc:
        raise ValueError('invalid state') from exc

def encode_state(records):
    if not isinstance(records, list):
        raise ValueError('invalid records')
    for record in records:
        _check_record(record)
    try:
        return json.dumps(records, ensure_ascii=False, separators=(',', ':'), sort_keys=True).encode('utf-8')
    except Exception as exc:
        raise ValueError('invalid records') from exc

def merge_filings(blob, updates):
