    except Exception as exc:
        raise ValueError('invalid screening response') from exc
    if not isinstance(payload, dict) or not isinstance(payload.get('results'), list):
        raise ValueError('invalid screening response')
    return payload['results']

def aggregate_compounds(records: list[dict], window: int=3) -> list[dict]:
    if not isinstance(window, int) or isinstance(window, bool) or window < 1:
        raise ValueError('invalid window')
    groups = {}
    order = []
    for record in records:
        if not isinstance(record, dict) or not isinstance(record.get('id'), str) or (not isinstance(record.get('name'), str)) or (not isinstance(record.get('measurements'), list)):
            continue
        key = record['id']
        if key not in groups:
            groups[key] = {'name': record['name'], 'values': []}
            order.append(key)
        for item in record['measurements']:
            if not isinstance(item, dict) or not isinstance(item.get('day'), int) or isinstance(item.get('day'), bool) or (not isinstance(item.get('activity'), (int, float))) or isinstance(item.get('activity'), bool):
                continue
            groups[key]['values'].append((item['day'], item['activity']))
    result = []
    for key in order:
        values = sorted(groups[key]['values'], key=lambda x: x[0])[-window:]
        if not values:
            continue
        activities = [x[1] for x in values]
        result.append({'id': key, 'name': groups[key]['name'], 'measurements': len(values), 'mean_activity': round(sum(activities) / len(activities), 6), 'peak_activity': round(max(activities), 6)})
    return result

