import datetime
import json

def _date(value):
    if not isinstance(value, str) or not value:
        raise ValueError('invalid date')
    try:
        return datetime.date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def _validate(progress):
    if not isinstance(progress, dict):
        raise ValueError('invalid progress')
    for learner, dates in progress.items():
        if not isinstance(learner, str) or not learner or (not isinstance(dates, dict)):
            raise ValueError('invalid progress')
        for day, metrics in dates.items():
            _date(day)
            if not isinstance(metrics, dict) or set(metrics) != {'correct', 'attempted', 'minutes'}:
                raise ValueError('invalid metrics')
            for key in ('correct', 'attempted', 'minutes'):
                value = metrics[key]
                if isinstance(value, bool) or not isinstance(value, int) or value < 0:
                    raise ValueError('invalid metric')
    return progress

def encode_progress(progress: dict[str, dict[str, dict[str, int]]]) -> bytes:
    _validate(progress)
    return json.dumps(progress, sort_keys=True, separators=(',', ':')).encode('utf-8')

def decode_progress(blob: bytes) -> dict[str, dict[str, dict[str, int]]]:
    if not isinstance(blob, bytes):
        raise ValueError('invalid blob')
    try:
        value = json.loads(blob.decode('utf-8'))
        _validate(value)
        return value
    except (UnicodeError, json.JSONDecodeError, ValueError, TypeError):
        raise ValueError('invalid blob')

def merge_progress(blobs: list[bytes]) -> dict[str, dict[str, dict[str, int]]]:
    result = {}
    for blob in blobs:
        for learner, dates in decode_progress(blob).items():
            target = result.setdefault(learner, {})
            for day, metrics in dates.items():
                current = target.setdefault(day, {'correct': 0, 'attempted': 0, 'minutes': 0})
                for key in current:
                    current[key] += metrics[key]
    return result

def leaderboard(progress: dict[str, dict[str, dict[str, int]]], since: str) -> list[dict[str, object]]:
    _validate(progress)
    start = _date(since)
    rows = []
    for learner, dates in progress.items():
        selected = [m for day, m in dates.items() if _date(day) >= start]
        if not selected:
            continue
        correct = sum((m['correct'] for m in selected))
        attempted = sum((m['attempted'] for m in selected))
        minutes = sum((m['minutes'] for m in selected))
        accuracy = round(correct / attempted, 4) if attempted else 0.0
        rows.append({'learner': learner, 'correct': correct, 'attempted': attempted, 'minutes': minutes, 'days': len(selected), 'accuracy': accuracy})
    rows.sort(key=lambda row: (-row['accuracy'], -row['attempted'], row['learner']))
    return rows

