import json
PURPOSES = {'analytics', 'marketing', 'personalization'}

def _grant(value):
    return isinstance(value, dict) and set(value) == {'value', 'at'} and isinstance(value['value'], bool) and isinstance(value['at'], int) and (not isinstance(value['at'], bool)) and (value['at'] >= 0)

def _valid(state):
    if not isinstance(state, dict) or set(state) != {'version', 'users'} or state['version'] != 1 or (not isinstance(state['users'], dict)):
        return False
    for uid, user in state['users'].items():
        if not isinstance(uid, str) or not uid or (not isinstance(user, dict)) or (set(user) != {'grants', 'history'}):
            return False
        if not isinstance(user['grants'], dict) or not isinstance(user['history'], list):
            return False
        for purpose, grant in user['grants'].items():
            if purpose not in PURPOSES or not _grant(grant):
                return False
        for event in user['history']:
            if not isinstance(event, dict) or set(event) != {'purpose', 'value', 'at'} or event['purpose'] not in PURPOSES or (not _grant({'value': event['value'], 'at': event['at']})):
                return False
    return True

def pack_state(state: dict) -> bytes:
    if not _valid(state):
        raise ValueError('invalid state')
    return json.dumps(state, sort_keys=True, separators=(',', ':')).encode('utf-8')

def unpack_state(blob: bytes) -> dict:
    try:
        state = json.loads(blob.decode('utf-8'))
    except (AttributeError, UnicodeError, ValueError, TypeError):
        raise ValueError('invalid blob')
    if not _valid(state):
        raise ValueError('invalid state')
    return state

def record_consent(state: dict, user_id: str, purpose: str, value: bool, timestamp: int) -> dict:
