        if not isinstance(item['target'], str) or not item['target']:
            raise ValueError('invalid target')
        if isinstance(item['start'], bool) or not isinstance(item['start'], int) or item['start'] < 0:
            raise ValueError('invalid start')
        if isinstance(item['duration'], bool) or not isinstance(item['duration'], int) or item['duration'] <= 0:
            raise ValueError('invalid duration')
        if isinstance(item['priority'], bool) or not isinstance(item['priority'], (int, float)) or (not 0 <= item['priority'] <= 100):
            raise ValueError('invalid priority')

