from decimal import Decimal, InvalidOperation
from datetime import date
from html import escape

def _decimal(value):
    try:
        result = Decimal(str(value))
    except (InvalidOperation, ValueError):
        raise ValueError('invalid decimal')
    if not result.is_finite():
        raise ValueError('invalid decimal')
    return result

def categorize_transactions(records: list[dict], rules: dict[str, list[str]], opening_balance: str='0') -> list[dict]:
    balance = _decimal(opening_balance)
    prepared = []
    for index, record in enumerate(records):
        try:
            raw_date = record['date']
            description = record['description']
            raw_amount = record['amount']
        except (KeyError, TypeError):
            raise ValueError('missing field')
        try:
            date.fromisoformat(raw_date)
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        amount = _decimal(raw_amount)
        lowered = description.casefold()
        category = 'Other'
        for name, keywords in rules.items():
            if any((str(keyword).casefold() in lowered for keyword in keywords)):
                category = name
                break
        prepared.append((raw_date, index, description, amount, category))
    prepared.sort(key=lambda item: (item[0], item[1]))
    result = []
    for raw_date, _, description, amount, category in prepared:
        balance += amount
        result.append({'date': raw_date, 'description': description, 'amount': amount, 'category': category, 'balance': balance})
    return result

def render_report(rows: list[dict]) -> str:
    transactions = []
    months = {}
    for row in rows:
        amount = row['amount']
        transactions.append('<tr><td>' + escape(str(row['date'])) + '</td><td>' + escape(str(row['description'])) + '</td><td>' + escape(str(row['category'])) + '</td><td>' + format(amount, '.2f') + '</td><td>' + format(row['balance'], '.2f') + '</td></tr>')
        month = str(row['date'])[:7]
        entry = months.setdefault(month, [0, Decimal('0'), Decimal('0')])
        entry[0] += 1
        if amount >= 0:
            entry[1] += amount
        else:
            entry[2] -= amount
    monthly = []
    for month in sorted(months):
        count, income, spending = months[month]
        monthly.append(f'<tr><td>{escape(month)}</td><td>{count}</td><td>{income:.2f}</td><td>{spending:.2f}</td></tr>')
    return '<div class="report"><table><thead><tr><th>Date</th><th>Description</th><th>Category</th><th>Amount</th><th>Balance</th></tr></thead><tbody>' + ''.join(transactions) + '</tbody></table><h2>Monthly summary</h2><table><thead><tr><th>Month</th><th>Count</th><th>Income</th><th>Spending</th></tr></thead><tbody>' + ''.join(monthly) + '</tbody></table></div>'

def build_report(records: list[dict], rules: dict[str, list[str]], opening_balance: str='0') -> str:
    return render_report(categorize_transactions(records, rules, opening_balance))

