from datetime import datetime
from html import escape
STATUSES = ('scheduled', 'confirmed', 'cancelled', 'completed')
HEADER = ['date', 'start', 'end', 'client', 'counselor', 'status']

def parse_appointments(data: str) -> list[dict]:
    rows = [r for r in csv.reader(io.StringIO(data), escapechar='\\') if any((x.strip() for x in r))]
    if not rows or [x.strip() for x in rows[0]] != HEADER:
        raise ValueError('invalid header')
    out = []
    seen = set()
    for row in rows[1:]:
        if len(row) != 6:
            raise ValueError('invalid row')
        d, start, end, client, counselor, status = [x.strip() for x in row]
        try:
            a = datetime.strptime(start, '%H:%M')
            b = datetime.strptime(end, '%H:%M')
            datetime.strptime(d, '%Y-%m-%d')
        except ValueError as e:
            raise ValueError('invalid value') from e
        if b <= a or not client or (not counselor) or (status not in STATUSES):
            raise ValueError('invalid value')
        key = (d, start, client)
        if key in seen:
            raise ValueError('duplicate')
        seen.add(key)
        out.append({'date': d, 'start': start, 'end': end, 'client': client, 'counselor': counselor, 'status': status, 'duration': int((b - a).total_seconds() / 60)})
    return out

def schedule_stats(records: list[dict]) -> dict:
    counts = {s: 0 for s in STATUSES}
    dates = {}
    for r in records:
        counts[r['status']] += 1
        x = dates.setdefault(r['date'], {'appointments': 0, 'minutes': 0})
        x['appointments'] += 1
        x['minutes'] += r['duration']
    return {'total': len(records), 'minutes': sum((r['duration'] for r in records)), 'by_status': counts, 'by_date': dict(sorted(dates.items()))}

def render_appointment_page(records: list[dict], title: str) -> str:
    s = schedule_stats(records)
    lines = [f'<h1>{escape(str(title))}</h1>', f"<p>Total appointments: {s['total']} | Total minutes: {s['minutes']}</p>", '<table>', '<thead><tr><th>Date</th><th>Time</th><th>Client</th><th>Counselor</th><th>Status</th><th>Minutes</th></tr></thead>', '<tbody>']
    for r in sorted(records, key=lambda x: (x['date'], x['start'], x['counselor'], x['client'])):
        values = [r['date'], r['start'] + '-' + r['end'], r['client'], r['counselor'], r['status'], r['duration']]
        lines.append('<tr><td>' + '</td><td>'.join((escape(str(v)) for v in values)) + '</td></tr>')
    lines += ['</tbody>', '</table>']
    return '\n'.join(lines)

