def _date(value):
    if not isinstance(value, str):
        raise ValueError('invalid date')
    try:
        return date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')

def _claims(records):
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    required = {'id', 'claimant', 'insurer', 'amount', 'status', 'filed'}
    seen = set()
    result = []
    for record in records:
        if not isinstance(record, dict) or set(record) != required:
            raise ValueError('invalid record')
        values = {key: record[key] for key in required}
        if any((not isinstance(values[k], str) or not values[k] for k in ('id', 'claimant', 'insurer', 'status', 'filed'))):
            raise ValueError('invalid text')
        if values['id'] in seen or values['status'] not in {'pending', 'approved', 'denied'}:
            raise ValueError('invalid claim')
        _date(values['filed'])
        try:
            amount = Decimal(str(values['amount']))
        except (InvalidOperation, ValueError):
            raise ValueError('invalid amount')
        if not amount.is_finite() or amount < 0 or amount.as_tuple().exponent < -2:
            raise ValueError('invalid amount')
        amount = amount.quantize(Decimal('0.01'))
        seen.add(values['id'])
        result.append({'id': values['id'], 'claimant': values['claimant'], 'insurer': values['insurer'], 'amount': f'{amount:.2f}', 'status': values['status'], 'filed': values['filed']})
    result.sort(key=lambda x: (x['insurer'], -_date(x['filed']).toordinal(), x['id']))
    return result

def prepare_claims(records: list[dict[str, object]]) -> list[dict[str, object]]:
    return _claims(records)

def render_claim_report(records: list[dict[str, object]], as_of: str) -> str:
    _date(as_of)
    claims = _claims(records)
    approved = sum((Decimal(x['amount']) for x in claims if x['status'] == 'approved'), Decimal('0'))
    pending = sum((Decimal(x['amount']) for x in claims if x['status'] == 'pending'), Decimal('0'))
    rows = []
    for x in claims:
        cells = [x['insurer'], x['claimant'], x['id'], x['status'], '$' + x['amount'], x['filed']]
        rows.append('<tr>' + ''.join(('<td>' + escape(str(v), quote=True) + '</td>' for v in cells)) + '</tr>')
    return '\n'.join(['<section class="claims-report">', f'<h1>Claims as of {escape(as_of, quote=True)}</h1>', f'<p class="summary">{len(claims)} claims, ${approved:.2f} approved, ${pending:.2f} pending</p>', '<table>', '<thead><tr><th>Insurer</th><th>Claimant</th><th>Claim ID</th><th>Status</th><th>Amount</th><th>Filed</th></tr></thead>', '<tbody>', *rows, '</tbody>', '</table>', '</section>'])

