    if not isinstance(body, dict) or not isinstance(body.get('data'), list) or (not all((isinstance(x, dict) for x in body['data']))):
        raise ValueError('invalid response')
    return list(body['data'])

def _timestamp(value: str) -> datetime:
    if not isinstance(value, str) or not value.endswith('Z'):
        raise ValueError('invalid timestamp')
    try:
        return datetime.fromisoformat(value[:-1] + '+00:00')
    except ValueError as exc:
        raise ValueError('invalid timestamp') from exc

def summarize_change_orders(orders: list[dict[str, Any]]) -> dict[str, Any]:
    counts = {'pending': 0, 'approved': 0, 'rejected': 0}
    monthly: dict[str, float] = {}
    contractors: dict[str, float] = {}
    approved_total = 0.0
    item_total = 0
    for order in orders:
        status = order['status']
        if status not in counts:
            raise ValueError('unknown status')
        counts[status] += 1
        item_total += len(order['line_items'])
        stamp = _timestamp(order['submitted_at'])
        if status == 'approved':
            amount = float(order['amount'])
            approved_total += amount
            month = stamp.strftime('%Y-%m')
            monthly[month] = monthly.get(month, 0.0) + amount
            contractor = order['contractor']
            contractors[contractor] = contractors.get(contractor, 0.0) + amount
    top = min(contractors, key=lambda name: (-contractors[name], name)) if contractors else None
    return {'count': len(orders), 'status_counts': counts, 'approved_total': round(approved_total, 2), 'monthly_approved': {k: round(monthly[k], 2) for k in sorted(monthly)}, 'top_contractor': top, 'average_line_items': round(item_total / len(orders), 2) if orders else 0.0}

def select_pending_orders(orders: list[dict[str, Any]], budget_limit: float) -> list[str]:
    if budget_limit < 0:
        raise ValueError('negative budget')
    chosen = [o for o in orders if o['status'] == 'pending' and o['amount'] <= budget_limit]
    chosen.sort(key=lambda o: (o['amount'], _timestamp(o['submitted_at']), o['id']))
    return [o['id'] for o in chosen]

