import math

def _validate_records(records):
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    for record in records:
        if not isinstance(record, dict) or set(record) != {'domain', 'registrar', 'status', 'price'}:
            raise ValueError('invalid record')
        if not isinstance(record['domain'], str) or not isinstance(record['registrar'], str):
            raise ValueError('invalid text')
        if record['status'] not in {'active', 'expired', 'pending'}:
            raise ValueError('invalid status')
        price = record['price']
        if isinstance(price, bool) or not isinstance(price, (int, float)) or (not math.isfinite(price)) or (price < 0):
            raise ValueError('invalid price')

def encode_records(records: list[dict]) -> bytes:
    _validate_records(records)
    try:
        return json.dumps(records, separators=(',', ':'), allow_nan=False).encode('utf-8')
    except (TypeError, ValueError, UnicodeError) as exc:
        raise ValueError('invalid records') from exc

def summarize_registry(blob: bytes, suffix: str | None=None, page: int=1, page_size: int=10) -> dict:
    if not isinstance(blob, (bytes, bytearray)) or not isinstance(page, int) or isinstance(page, bool) or (page < 1) or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (page_size < 1) or (suffix is not None and (not isinstance(suffix, str))):
