    try:
        data = json.loads(bytes(blob).decode('utf-8'))
    except (TypeError, ValueError, UnicodeError) as exc:
        raise ValueError('invalid payload') from exc
    _validate_records(data)
    chosen = [r for r in data if suffix is None or r['domain'].lower().endswith(suffix.lower())]
    groups = {}
    for record in chosen:
        item = groups.setdefault(record['registrar'], [0, 0.0])
        item[0] += 1
        item[1] += record['price']
    by_registrar = [{'registrar': name, 'count': values[0], 'revenue': round(values[1], 2)} for name, values in groups.items()]
