    for record in records:
        if not isinstance(record, dict):
            raise TypeError('applicant must be a dictionary')
        for key in ('name', 'email', 'stage'):
            if not isinstance(record.get(key), str):
                raise TypeError('applicant fields must be strings')
        interviews = record.get('interviews')
        if not isinstance(interviews, list):
            raise TypeError('interviews must be a list')
        parsed = []
        for item in interviews:
            if not isinstance(item, dict) or not isinstance(item.get('date'), str):
                raise TypeError('invalid interview')
            score = item.get('score')
            if isinstance(score, bool) or not isinstance(score, (int, float)):
                raise TypeError('invalid score')
            if not isfinite(score) or not 0 <= score <= 10:
                raise ValueError('score out of range')
            try:
                parsed_date = date.fromisoformat(item['date'])
            except ValueError:
                raise ValueError('invalid date')
            if parsed_date.isoformat() != item['date']:
                raise ValueError('invalid date')
            parsed.append((parsed_date, score))
        parsed.sort(key=lambda x: x[0], reverse=True)
        chosen = parsed[:3]
        checked.append((record, chosen))
    return checked

