    result = []
    for record, interviews in _validate(records):
        count = len(interviews)
        result.append({'name': record['name'], 'email': record['email'], 'stage': record['stage'], 'average': sum((x[1] for x in interviews)) / count if count else 0.0, 'count': count, 'latest': interviews[0][0].isoformat() if interviews else ''})
    return sorted(result, key=lambda x: (-x['average'], x['latest'], x['name'].casefold()))

