from html import escape
STATUSES = ('open', 'fulfilled', 'denied', 'withdrawn')

def _fields(line):
    fields, current, escaped = ([], [], False)
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    fields.append(''.join(current))
    return fields

def parse_requests(text: str) -> list[dict]:
    result, seen = ([], set())
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = _fields(raw)
        if len(fields) != 5:
            raise ValueError('wrong field count')
        ident, agency, status, days, title = fields
        if not ident or not agency or (not status) or (not title) or (status not in STATUSES):
            raise ValueError('invalid field')
        try:
            number = int(days)
        except ValueError:
            raise ValueError('invalid days')
        if number < 0 or ident in seen:
            raise ValueError('invalid record')
        seen.add(ident)
        result.append({'id': ident, 'agency': agency, 'status': status, 'days': number, 'title': title})
    return result

def summarize(records: list[dict], agency: str | None=None) -> dict:
    selected = [r for r in records if agency is None or r['agency'] == agency]
    statuses = {s: 0 for s in STATUSES}
    agencies = {}
    for record in selected:
        statuses[record['status']] += 1
        agencies[record['agency']] = agencies.get(record['agency'], 0) + 1
    agencies = dict(sorted(agencies.items()))
    average = round(sum((r['days'] for r in selected)) / len(selected), 2) if selected else 0
    return {'total': len(selected), 'by_status': statuses, 'by_agency': agencies, 'average_days': average}

def render_report(records: list[dict], title: str='Public Records Requests', agency: str | None=None) -> str:
    selected = sorted((r for r in records if agency is None or r['agency'] == agency), key=lambda r: (r['agency'], r['title'], r['id']))
    rows = ''.join(('<tr><td>' + escape(str(r['agency'])) + '</td><td>' + escape(str(r['id'])) + '</td><td>' + escape(str(r['title'])) + '</td><td>' + escape(str(r['status'])) + '</td><td>' + escape(str(r['days'])) + '</td></tr>' for r in selected))
    return '<section class="report"><h1>' + escape(str(title)) + '</h1><p class="total">' + str(len(selected)) + ' requests</p><table><thead><tr><th>Agency</th><th>ID</th><th>Title</th><th>Status</th><th>Days open</th></tr></thead><tbody>' + rows + '</tbody></table></section>'

