from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
import math
import requests

def fetch_commissions(api_url: str, broker_id: str | None=None, page_size: int=100) -> list[dict]:
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 1000):
        raise ValueError('invalid page size')
    page = 1
    result = []
    while True:
        params = {'page': page, 'limit': page_size}
        if broker_id:
            params['broker_id'] = broker_id
        response = requests.get(api_url, params=params, headers={'Accept': 'application/json'}, timeout=10)
        if not 200 <= response.status_code < 300:
            raise RuntimeError('request failed')
        payload = response.json()
        if not isinstance(payload, dict) or not isinstance(payload.get('commissions'), list):
            raise ValueError('invalid response')
        result.extend(payload['commissions'])
        next_page = payload.get('next_page')
        if next_page is None:
            return result
        if not isinstance(next_page, int) or isinstance(next_page, bool) or next_page < 1:
            raise ValueError('invalid next page')
        page = next_page

def summarize_commissions(records: list[dict]) -> list[dict]:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    totals = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        if record.get('status') != 'paid':
            continue
        broker = record.get('broker_id')
        amount = record.get('amount')
        if not isinstance(broker, str) or not broker:
            raise ValueError('invalid broker')
        if isinstance(amount, bool) or not isinstance(amount, (int, float, str, Decimal)):
            raise ValueError('invalid amount')
        try:
            value = Decimal(str(amount))
        except (InvalidOperation, ValueError):
            raise ValueError('invalid amount')
        if not value.is_finite():
            raise ValueError('invalid amount')
        if broker not in totals:
            totals[broker] = [Decimal('0'), 0]
        totals[broker][0] += value
        totals[broker][1] += 1
    output = []
    for broker, (total, count) in totals.items():
        rounded = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        output.append({'broker_id': broker, 'total': float(rounded), 'count': count})
    output.sort(key=lambda item: (-item['total'], item['broker_id']))
    return output

