        value = Decimal(str(value))
    except (InvalidOperation, ValueError, TypeError):
        raise ValueError('invalid rate')
    if value < 0:
        raise ValueError('invalid rate')
    return value

def summarize_royalties(records: list[dict], artist: str) -> dict:
    groups = {}
    total_plays = 0
    total = Decimal('0')
    for row in records:
        if not isinstance(row, dict) or row.get('artist') != artist:
            continue
        required = ('artist', 'track', 'isrc', 'territory', 'plays', 'rate')
        if any((key not in row for key in required)):
            raise ValueError('invalid statement')
        if not all((isinstance(row[key], str) for key in ('artist', 'track', 'isrc', 'territory'))):
            raise ValueError('invalid statement')
        plays = row['plays']
        if isinstance(plays, bool) or not isinstance(plays, int) or plays < 0:
            raise ValueError('invalid plays')
        rate = _money(row['rate'])
        amount = rate * plays
        key = (row['track'], row['isrc'])
        group = groups.setdefault(key, {'plays': 0, 'royalty': Decimal('0'), 'territories': {}})
        terr = group['territories'].setdefault(row['territory'], [0, Decimal('0')])
        group['plays'] += plays
        group['royalty'] += amount
        terr[0] += plays
        terr[1] += amount
        total_plays += plays
        total += amount
    tracks = []
    for (track, isrc), group in groups.items():
        territories = [{'territory': name, 'plays': value[0], 'royalty': str(value[1].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))} for name, value in sorted(group['territories'].items())]
        tracks.append({'track': track, 'isrc': isrc, 'plays': group['plays'], 'royalty': str(group['royalty'].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)), 'territories': territories})
    tracks.sort(key=lambda item: (-Decimal(item['royalty']), item['track'], item['isrc']))
    return {'total_plays': total_plays, 'total_royalty': str(total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)), 'tracks': tracks}

