    def stamp(value):
        if not isinstance(value, str) or not value.endswith('Z'):
            raise ValueError('invalid timestamp')
        try:
            return datetime.fromisoformat(value[:-1] + '+00:00')
        except Exception as exc:
            raise ValueError('invalid timestamp') from exc
    end = stamp(as_of)
    start = end - timedelta(days=30)
    result = {}
    seen = set()
    for case in cases:
        if not isinstance(case, dict) or not all((k in case for k in ('id', 'status', 'assigned_to'))):
            raise ValueError('invalid case')
        if case['id'] in seen or not isinstance(case['assigned_to'], str):
            raise ValueError('invalid case')
        seen.add(case['id'])
        if case['status'] not in ('open', 'monitoring'):
            continue
        events = case.get('events', [])
        if not isinstance(events, list):
            raise ValueError('invalid events')
        worker = case['assigned_to']
        row = result.setdefault(worker, {'worker': worker, 'case_count': 0, 'contacts': 0, 'appointments': 0, 'last_event': None, '_last': None})
        row['case_count'] += 1
        for event in events:
            if not isinstance(event, dict) or 'at' not in event or 'kind' not in event:
                raise ValueError('invalid event')
            when = stamp(event['at'])
            if start <= when <= end and event['kind'] in ('contact', 'appointment'):
                row[event['kind'] + 's'] += 1
                if row['_last'] is None or when > row['_last']:
                    row['_last'] = when
                    row['last_event'] = event['at']
    rows = list(result.values())
    rows.sort(key=lambda x: (-x['contacts'], -x['appointments'], x['worker']))
    for row in rows:
