        except ValueError as exc:
            raise ValueError(f'line {line_no}: invalid year') from exc
        if not 1000 <= year <= 2100:
            raise ValueError(f'line {line_no}: invalid year')
        if status not in ('occupied', 'available'):
            raise ValueError(f'line {line_no}: invalid status')
