import requests

def fetch_daily_usage(meter_id: str, start_date: str, end_date: str, api_key: str) -> list[dict]:
    if not isinstance(meter_id, str) or not meter_id:
        raise ValueError('invalid meter_id')
    try:
        start = date.fromisoformat(start_date)
        end = date.fromisoformat(end_date)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if start > end:
        raise ValueError('date range')
    response = requests.get(f'https://api.example.com/meters/{meter_id}/readings', params={'start': start_date, 'end': end_date}, headers={'Authorization': f'Bearer {api_key}'})
    if response.status_code != 200:
        raise RuntimeError('request failed')
    payload = response.json()
    if not isinstance(payload, dict) or not isinstance(payload.get('readings'), list):
        raise ValueError('invalid payload')
    grouped = {}
    for reading in payload['readings']:
        if not isinstance(reading, dict) or 'timestamp' not in reading or 'kwh' not in reading:
            raise ValueError('invalid reading')
        try:
            stamp = str(reading['timestamp'])
            when = datetime.fromisoformat(stamp[:-1] + '+00:00' if stamp.endswith('Z') else stamp)
            value = reading['kwh']
            if isinstance(value, bool) or not isinstance(value, (int, float)) or value < 0:
                raise ValueError
        except (TypeError, ValueError, OverflowError):
            raise ValueError('invalid reading')
        day = when.date()
        if start <= day <= end:
            key = day.isoformat()
            grouped.setdefault(key, []).append(value)
    return [{'date': key, 'total_kwh': round(sum(values), 2), 'peak_kwh': round(max(values), 2)} for key, values in sorted(grouped.items())]

