import json

def dump_reservations(records: list[dict]) -> bytes:
    return json.dumps(records, ensure_ascii=False, separators=(',', ':')).encode('utf-8')

def reservation_report(blob: bytes | str, page: int, page_size: int) -> list[dict]:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1) or (page_size > 100):
        raise ValueError('invalid paging')
    try:
        raw = blob.encode('utf-8') if isinstance(blob, str) else blob
        records = json.loads(raw.decode('utf-8'))
    except Exception:
        raise ValueError('invalid payload') from None
    if not isinstance(records, list):
        raise ValueError('invalid records')
    groups = {}
    for record in records:
        if not isinstance(record, dict) or set(record) != {'movie', 'seats', 'price_cents', 'status'}:
            raise ValueError('invalid record')
        movie, seats, price, status = (record['movie'], record['seats'], record['price_cents'], record['status'])
        if not isinstance(movie, str) or not movie or isinstance(seats, bool) or (not isinstance(seats, int)) or (seats < 1) or isinstance(price, bool) or (not isinstance(price, int)) or (price < 0) or (status not in {'confirmed', 'cancelled', 'held'}):
            raise ValueError('invalid record')
        if status == 'confirmed':
            item = groups.setdefault(movie, [0, 0])
            item[0] += seats
            item[1] += seats * price
    result = [{'movie': movie, 'tickets': tickets, 'revenue_cents': revenue, 'average_price_cents': (revenue + tickets // 2) // tickets} for movie, (tickets, revenue) in groups.items()]
    result.sort(key=lambda item: (-item['revenue_cents'], item['movie']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

