import html

def render_kb_index(articles: list[dict], page: int=1, per_page: int=10) -> str:
    if not isinstance(articles, list):
        raise TypeError('articles must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or isinstance(per_page, bool) or (not isinstance(per_page, int)):
        raise TypeError('page and per_page must be integers')
    if page <= 0 or per_page <= 0:
        raise ValueError('page and per_page must be positive')
    required = ('id', 'title', 'category', 'author', 'views', 'published')
    rows = []
    for article in articles:
        if not isinstance(article, dict):
            raise TypeError('each article must be a dictionary')
        for key in required:
            if key not in article:
                raise ValueError('missing article field')
        if not all((isinstance(article[k], str) for k in ('id', 'title', 'category', 'author'))):
            raise TypeError('text fields must be strings')
        if not isinstance(article['views'], int) or isinstance(article['views'], bool):
            raise TypeError('views must be an integer')
        if article['views'] < 0:
            raise ValueError('views must be non-negative')
        if not isinstance(article['published'], bool):
            raise TypeError('published must be boolean')
        if article['published']:
            rows.append(article)
    rows.sort(key=lambda x: (x['category'].casefold(), x['title'].casefold(), x['id'].casefold()))
    total = len(rows)
    start_index = (page - 1) * per_page
    selected = rows[start_index:start_index + per_page]
    start = start_index + 1 if selected else 0
    end = start_index + len(selected) if selected else 0
    esc = lambda value: html.escape(str(value), quote=True)
    output = ['<div class="kb-index">', '<h1>Knowledge Base</h1>', f'<p class="summary">Showing {start}-{end} of {total} published articles</p>']
    current = None
    for article in selected:
        if article['category'] != current:
            if current is not None:
                output.extend(['</ul>', '</section>'])
            current = article['category']
            output.extend(['<section class="category">', f'<h2>{esc(current)}</h2>', '<ul>'])
        output.append(f'''<li><a href="/articles/{esc(article['id'])}" title="{esc(article['title'])}">{esc(article['title'])}</a><span class="author">by {esc(article['author'])}</span><span class="views">{article['views']:,} views</span></li>''')
    if current is not None:
        output.extend(['</ul>', '</section>'])
    output.extend(['</div>', ''])
    return '\n'.join(output)

