        if any((key not in record for key in required)):
            raise ValueError('invalid shipment record')
        shipment_id = record['shipment_id']
        item = record['item']
        destination = record['destination']
        quantity = record['quantity']
        status = record['status']
        if not isinstance(shipment_id, str) or not shipment_id or (not isinstance(item, str)) or (not item) or (not isinstance(destination, str)) or (not destination) or (not isinstance(quantity, int)) or isinstance(quantity, bool) or (quantity <= 0) or (status not in {'delivered', 'pending', 'cancelled'}):
