import re
import requests

def fetch_inventory(base_url: str, warehouse_id: str, token: str) -> dict[str, int]:
    response = requests.get(base_url.rstrip('/') + '/v1/inventory', params={'warehouse': warehouse_id}, headers={'Authorization': 'Bearer ' + token})
    if response.status_code != 200:
        raise RuntimeError(f'inventory request failed: {response.status_code}')
    try:
        data = response.json()
        items = data['items']
        result = {}
        for item in items:
            sku = item['sku']
            quantity = item['quantity']
            if not isinstance(sku, str) or not re.fullmatch('[A-Z0-9-]+', sku):
                raise ValueError('malformed item')
            if type(quantity) is not int:
                raise ValueError('malformed item')
            result[sku] = result.get(sku, 0) + quantity
        return result
    except (KeyError, TypeError, ValueError):
        raise ValueError('malformed inventory')

def parse_scan(scan: str) -> tuple[str, int, int]:
    match = re.fullmatch('([A-Z0-9-]+)\\|([+-]?\\d+)\\|(\\d+)', scan)
    if not match:
        raise ValueError('invalid scan')
    return (match.group(1), int(match.group(2)), int(match.group(3)))

def build_inventory_report(initial: dict[str, int], scans: list[str], window: int=60) -> list[dict]:
    if type(window) is not int or window <= 0:
        raise ValueError('invalid window')
    inventory = {}
    for sku, quantity in initial.items():
        if not isinstance(sku, str) or not re.fullmatch('[A-Z0-9-]+', sku):
            raise ValueError('invalid initial inventory')
        if type(quantity) is not int or quantity < 0:
            raise ValueError('invalid initial inventory')
        inventory[sku] = quantity
    parsed = []
    for index, scan in enumerate(scans):
        sku, delta, timestamp = parse_scan(scan)
        parsed.append((timestamp, index, sku, delta))
    parsed.sort(key=lambda item: (item[0], item[1]))
    groups = {}
    for timestamp, _, sku, delta in parsed:
        if sku not in inventory:
            inventory[sku] = 0
        inventory[sku] += delta
        if inventory[sku] < 0:
            raise ValueError('negative inventory')
        start = timestamp // window * window
        if start not in groups:
            groups[start] = {}
        groups[start][sku] = groups[start].get(sku, 0) + delta
    result = []
    current = {sku: initial[sku] for sku in initial}
    for start in sorted(groups):
        for sku, delta in groups[start].items():
            current[sku] = current.get(sku, 0) + delta
        changes = {sku: groups[start][sku] for sku in sorted(groups[start])}
        totals = {sku: current[sku] for sku in sorted(current)}
        result.append({'window': start, 'changes': changes, 'totals': totals})
    return result

