        region = item.get('region')
        risk = item.get('risk')
        acres = item.get('acres')
        if not isinstance(region, str) or not isinstance(risk, numbers.Real) or isinstance(risk, bool):
            continue
        if not isinstance(acres, numbers.Real) or isinstance(acres, bool) or acres < 0:
            continue
        region = region.strip()
        if region not in normalized or risk < min_score:
            continue
        entry = groups.setdefault(region, {'region': region, 'count': 0, 'total_acres': 0.0, 'max_risk': risk})
        entry['count'] += 1
        entry['total_acres'] += acres
        entry['max_risk'] = max(entry['max_risk'], risk)
    result = []
