import requests
from datetime import date, timedelta

def fetch_vaccination_records(api_base: str, herd_id: str, token: str) -> list[dict]:
    url = api_base.rstrip('/') + '/herds/' + herd_id + '/vaccinations'
    response = requests.get(url, params={'include': 'expired'}, headers={'Authorization': 'Bearer ' + token}, timeout=10)
    response.raise_for_status()
    payload = response.json()
    if not isinstance(payload, dict) or not isinstance(payload.get('animals'), list):
        raise ValueError('animals must be a list')
    return payload['animals']

def build_vaccination_report(animals: list[dict], as_of: str, window_days: int=30) -> list[dict]:
    try:
        today = date.fromisoformat(as_of)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if not isinstance(window_days, int) or isinstance(window_days, bool) or window_days < 0:
        raise ValueError('invalid window')
    limit = today + timedelta(days=window_days)
    output = []
    for animal in animals:
        selected = {}
        for record in animal['vaccinations']:
            try:
                administered = date.fromisoformat(record['administered'])
                expires = date.fromisoformat(record['expires'])
            except (KeyError, TypeError, ValueError):
                raise ValueError('invalid vaccination')
            key = record['vaccine']
            old = selected.get(key)
            rank = (administered, expires, record.get('batch', ''))
            if old is None or rank > old[0]:
                selected[key] = (rank, record, administered, expires)
        vaccinations = []
        overdue = 0
        for vaccine in sorted(selected):
            _, record, administered, expires = selected[vaccine]
            if expires < today:
                status = 'overdue'
                overdue += 1
            elif expires <= limit:
                status = 'due_soon'
            else:
                status = 'current'
            vaccinations.append({'vaccine': vaccine, 'administered': record['administered'], 'expires': record['expires'], 'status': status})
        output.append({'animal_id': animal['id'], 'name': animal['name'], 'vaccinations': vaccinations, 'overdue_count': overdue})
    output.sort(key=lambda item: (-item['overdue_count'], item['name'].casefold(), item['animal_id']))
    return output

