import csv
import html
import io
import re
from datetime import date, timedelta
_HEADER = ['volunteer', 'date', 'start', 'end', 'role', 'status']
_TIME = re.compile('^([01]\\d|2[0-3]):([0-5]\\d)$')

def _day(value):
    try:
        return date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def _minutes(value):
    match = _TIME.fullmatch(value)
    if not match:
        raise ValueError('invalid time')
    return int(value[:2]) * 60 + int(value[3:])

def parse_assignments(data: str) -> list[dict]:
    reader = csv.reader(io.StringIO(data))
    rows = [row for row in reader if any((cell.strip() for cell in row))]
    if not rows or rows[0] != _HEADER:
        raise ValueError('invalid header')
    result = []
    seen = set()
    for row in rows[1:]:
        if len(row) != 6:
            raise ValueError('invalid row')
        volunteer, day, start, end, role, status = row
        _day(day)
        begin = _minutes(start)
        finish = _minutes(end)
        if finish <= begin or status not in {'confirmed', 'waitlist', 'cancelled'}:
            raise ValueError('invalid assignment')
        key = (volunteer, day, start)
        if key in seen:
            raise ValueError('duplicate assignment')
        seen.add(key)
        result.append({'volunteer': volunteer, 'date': day, 'start': start, 'end': end, 'role': role, 'status': status, 'minutes': finish - begin})
    return result

def summarize_hours(assignments: list[dict], week_start: str) -> list[tuple[str, int]]:
    first = _day(week_start)
    totals = {}
    for row in assignments:
        day = _day(row['date'])
        if first <= day < first + timedelta(days=7) and row['status'] == 'confirmed':
            totals[row['volunteer']] = totals.get(row['volunteer'], 0) + row['minutes']
    return sorted(totals.items(), key=lambda item: (-item[1], item[0]))

def render_schedule(assignments: list[dict], week_start: str) -> str:
    first = _day(week_start)
    last = first + timedelta(days=7)
    selected = [row for row in assignments if first <= _day(row['date']) < last]
    selected.sort(key=lambda row: (row['date'], row['start'], row['volunteer'], row['role']))
    esc = lambda value: html.escape(str(value), quote=True)
    body = ''.join((f'''<tr class="{esc(row['status'])}"><td>{esc(row['date'])}</td><td>{esc(row['start'])}-{esc(row['end'])}</td><td>{esc(row['volunteer'])}</td><td>{esc(row['role'])}</td><td>{esc(row['status'])}</td></tr>''' for row in selected))
    return f'<section class="schedule"><h1>Volunteer schedule for {esc(week_start)}</h1><table><thead><tr><th>Date</th><th>Time</th><th>Volunteer</th><th>Role</th><th>Status</th></tr></thead><tbody>{body}</tbody></table></section>'

