import json
import math

def _validate(records):
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    required = {'id', 'country', 'weight_kg', 'status', 'timestamp'}
    for record in records:
        if not isinstance(record, dict) or set(record) != required:
            raise ValueError('invalid record')
        if not isinstance(record['id'], str) or not record['id']:
            raise ValueError('invalid record')
        if not isinstance(record['country'], str) or not record['country']:
            raise ValueError('invalid record')
        weight = record['weight_kg']
        if isinstance(weight, bool) or not isinstance(weight, (int, float)) or (not math.isfinite(weight)) or (weight < 0):
            raise ValueError('invalid record')
        if record['status'] not in {'cleared', 'held', 'rejected'}:
            raise ValueError('invalid record')
        if isinstance(record['timestamp'], bool) or not isinstance(record['timestamp'], int) or record['timestamp'] < 0:
            raise ValueError('invalid record')

def pack_records(records: list[dict]) -> bytes:
    _validate(records)
    return json.dumps(records, separators=(',', ':'), sort_keys=True).encode('utf-8')

def summarize_records(blob: bytes, country: str | None=None, page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    try:
        data = json.loads(blob.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid blob') from exc
    _validate(data)
    groups = {}
    for record in data:
        if country is not None and record['country'] != country:
            continue
        name = record['country']
        if name not in groups:
            groups[name] = {'country': name, 'count': 0, 'total_weight': 0.0}
        groups[name]['count'] += 1
        groups[name]['total_weight'] += record['weight_kg']
    items = list(groups.values())
    for item in items:
        item['total_weight'] = round(item['total_weight'], 2)
    items.sort(key=lambda item: (-item['total_weight'], item['country']))
    start = (page - 1) * page_size
    return {'total_countries': len(items), 'page': page, 'page_size': page_size, 'items': items[start:start + page_size]}

