import json

def _split(line):
    if not isinstance(line, str):
        raise ValueError('invalid line')
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            if char not in '|\\':
                raise ValueError('invalid escape')
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|' and len(fields) < 2:
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('unfinished escape')
    fields.append(''.join(current))
    if len(fields) != 3 or not fields[1]:
        raise ValueError('invalid fields')
    try:
        timestamp = int(fields[0])
        delta = int(fields[2])
    except (TypeError, ValueError):
        raise ValueError('invalid number')
    if timestamp < 0 or delta == 0:
        raise ValueError('invalid value')
    return (timestamp, fields[1], delta)

def _check_state(state):
    if not isinstance(state, dict) or set(state) != {'items', 'scans', 'last_timestamp'}:
        raise ValueError('invalid state')
    items = state['items']
    if not isinstance(items, dict) or any((not isinstance(k, str) or not isinstance(v, int) or isinstance(v, bool) for k, v in items.items())):
        raise ValueError('invalid items')
    if not isinstance(state['scans'], int) or isinstance(state['scans'], bool) or state['scans'] < 0:
        raise ValueError('invalid count')
    last = state['last_timestamp']
    if last is not None and (not isinstance(last, int) or isinstance(last, bool) or last < 0):
        raise ValueError('invalid timestamp')

def process_scans(lines, initial=None):
    base = {'items': {}, 'scans': 0, 'last_timestamp': None} if initial is None else initial
    _check_state(base)
    result = {'items': dict(base['items']), 'scans': base['scans'], 'last_timestamp': base['last_timestamp']}
    for line in lines:
        timestamp, barcode, delta = _split(line)
        if result['last_timestamp'] is not None and timestamp < result['last_timestamp']:
            raise ValueError('out of order')
        result['items'][barcode] = result['items'].get(barcode, 0) + delta
        result['scans'] += 1
        result['last_timestamp'] = timestamp
    return result

def summarize_scans(lines, window_seconds):
    if not isinstance(window_seconds, int) or isinstance(window_seconds, bool) or window_seconds <= 0:
        raise ValueError('invalid window')
    groups = {}
    previous = None
    for line in lines:
        timestamp, barcode, delta = _split(line)
        if previous is not None and timestamp < previous:
            raise ValueError('out of order')
        previous = timestamp
        key = (timestamp // window_seconds * window_seconds, barcode)
        total, count = groups.get(key, (0, 0))
        groups[key] = (total + delta, count + 1)
    return [{'window_start': w, 'barcode': b, 'total_delta': groups[w, b][0], 'scan_count': groups[w, b][1]} for w, b in sorted(groups)]

