from solution import parse_archive, summarize_archive, render_catalog
import json
import pytest


def source(records):
    return json.dumps({"records": records})


def test_parse_normalizes_and_preserves_order():
    text = source([{"id": " a1 ", "year": 1890, "creator": " Ada ", "title": " Notes ", "subjects": [" Poetry ", "History"]}])
    assert parse_archive(text) == [{"id": "a1", "year": 1890, "creator": "Ada", "title": "Notes", "subjects": ["Poetry", "History"]}]


def test_parse_rejects_bad_documents_and_duplicates():
    with pytest.raises(ValueError):
        parse_archive('{"records": {}}')
    with pytest.raises(ValueError):
        parse_archive(source([{"id": "x", "year": 1900, "creator": "A", "title": "T", "subjects": [""]}]))
    with pytest.raises(ValueError):
        parse_archive(source([
            {"id": "x", "year": 1900, "creator": "A", "title": "T", "subjects": []},
            {"id": "x", "year": 1901, "creator": "B", "title": "U", "subjects": []}
        ]))


def test_parse_requires_integer_year_and_all_fields():
    with pytest.raises(ValueError):
        parse_archive(source([{"id": "x", "year": True, "creator": "A", "title": "T", "subjects": []}]))
    with pytest.raises(ValueError):
        parse_archive(source([{"id": "x", "year": 10000, "creator": "A", "title": "T", "subjects": []}]))
    with pytest.raises(ValueError):
        parse_archive(source([{"id": "x", "year": 1900, "creator": "A", "title": "T"}]))


def test_summary_filters_years_and_counts_unique_subjects_per_record():
    records = parse_archive(source([
        {"id": "b", "year": 1900, "creator": "B", "title": "B", "subjects": ["Art", "art", "Books"]},
        {"id": "a", "year": 1901, "creator": "A", "title": "A", "subjects": ["ART"]},
        {"id": "c", "year": 1903, "creator": "C", "title": "C", "subjects": []}
    ]))
    assert summarize_archive(records, 1900, 1901) == {"count": 2, "by_year": [{"year": 1900, "count": 1}, {"year": 1901, "count": 1}], "subjects": [{"subject": "Art", "count": 2}, {"subject": "Books", "count": 1}]}


def test_summary_subject_tie_breaks_case_insensitively():
    records = parse_archive(source([
        {"id": "1", "year": 1, "creator": "A", "title": "A", "subjects": ["Zoology"]},
        {"id": "2", "year": 1, "creator": "B", "title": "B", "subjects": ["archaeology"]}
