import html
import json

def parse_archive(text: str) -> list[dict]:
    try:
        obj = json.loads(text)
    except Exception as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(obj, dict) or not isinstance(obj.get('records'), list):
        raise ValueError('invalid document')
    result = []
    seen = set()
    for item in obj['records']:
        if not isinstance(item, dict):
            raise ValueError('invalid record')
        if set(item) != {'id', 'year', 'creator', 'title', 'subjects'}:
            raise ValueError('invalid fields')
        ident, creator, title = (item['id'], item['creator'], item['title'])
        year, subjects = (item['year'], item['subjects'])
        if not all((isinstance(x, str) for x in (ident, creator, title))):
            raise ValueError('invalid text')
        if isinstance(year, bool) or not isinstance(year, int) or (not 0 <= year <= 9999):
            raise ValueError('invalid year')
        if not isinstance(subjects, list):
            raise ValueError('invalid subjects')
        vals = [x.strip() if isinstance(x, str) else None for x in subjects]
        if not ident.strip() or not creator.strip() or (not title.strip()) or any((x is None or not x for x in vals)):
            raise ValueError('empty value')
        ident, creator, title = (ident.strip(), creator.strip(), title.strip())
        if ident in seen:
            raise ValueError('duplicate id')
        seen.add(ident)
        result.append({'id': ident, 'year': year, 'creator': creator, 'title': title, 'subjects': vals})
    return result

def _range(records, start_year, end_year):
    if isinstance(start_year, bool) or isinstance(end_year, bool) or (not isinstance(start_year, int)) or (not isinstance(end_year, int)) or (start_year > end_year):
        raise ValueError('invalid range')
    return [r for r in records if start_year <= r['year'] <= end_year]

def summarize_archive(records: list[dict], start_year: int, end_year: int) -> dict:
    selected = _range(records, start_year, end_year)
    years = {}
    subjects = {}
    for record in selected:
        years[record['year']] = years.get(record['year'], 0) + 1
        used = set()
        for subject in record['subjects']:
            key = subject.casefold()
            if key not in used:
                used.add(key)
                if key not in subjects:
                    subjects[key] = [subject, 0]
                subjects[key][1] += 1
    by_year = [{'year': year, 'count': years[year]} for year in sorted(years)]
    ordered = sorted(subjects.values(), key=lambda x: (-x[1], x[0].casefold()))
    return {'count': len(selected), 'by_year': by_year, 'subjects': [{'subject': x[0], 'count': x[1]} for x in ordered]}

def render_catalog(records: list[dict], start_year: int, end_year: int) -> str:
    selected = sorted(_range(records, start_year, end_year), key=lambda r: (r['year'], r['creator'].casefold(), r['title'].casefold(), r['id']))
    esc = lambda value: html.escape(str(value), quote=True)
    lines = ['<div class="catalog">', '<h1>Archive catalogue</h1>', f'<p class="range">{start_year}–{end_year}: {len(selected)} record(s)</p>', '<table>', '<thead><tr><th>ID</th><th>Year</th><th>Creator</th><th>Title</th><th>Subjects</th></tr></thead>', '<tbody>']
    for r in selected:
        subjects = ', '.join((esc(x) for x in r['subjects']))
        lines.append(f"<tr><td>{esc(r['id'])}</td><td>{r['year']}</td><td>{esc(r['creator'])}</td><td>{esc(r['title'])}</td><td>{subjects}</td></tr>")
    lines.extend(['</tbody>', '</table>', '</div>'])
    return '\n'.join(lines) + '\n'

