import json

def encode_state(state: dict) -> bytes:
    return json.dumps(state, sort_keys=True, separators=(',', ':')).encode('utf-8')

def decode_state(blob: bytes) -> dict:
    try:
        value = json.loads(blob.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid state') from exc
    if not isinstance(value, dict) or not isinstance(value.get('entries'), dict) or (not isinstance(value.get('sizes'), dict)):
        raise ValueError('invalid state')
    for lead, rows in value['entries'].items():
        if not isinstance(lead, str) or not isinstance(rows, list):
            raise ValueError('invalid state')
        for row in rows:
            if not isinstance(row, dict) or type(row.get('day')) is not int or type(row.get('points')) is not int:
                raise ValueError('invalid state')
    return value

def process_batch(records: list[dict], state_blob: bytes=b'') -> tuple[list[dict], bytes]:
    state = {'entries': {}, 'sizes': {}}
    if state_blob:
        state = decode_state(state_blob)
    weights = {'email': 2, 'reply': 4, 'meeting': 10, 'demo': 8}
    latest = {}
    maximum = None
    for record in records:
        if not isinstance(record, dict) or not isinstance(record.get('lead_id'), str) or (not record['lead_id']) or (type(record.get('day')) is not int) or (record['day'] < 0) or (type(record.get('company_size')) is not int) or (record['company_size'] <= 0) or (not isinstance(record.get('events'), dict)):
            raise ValueError('invalid record')
        points = 0
        for name, count in record['events'].items():
            if name not in weights or type(count) is not int or count < 0:
                raise ValueError('invalid event')
            points += weights[name] * count
        lead, day = (record['lead_id'], record['day'])
        latest[lead] = record['company_size']
        maximum = day if maximum is None else max(maximum, day)
        rows = state['entries'].setdefault(lead, [])
        found = next((r for r in rows if r['day'] == day), None)
        if found is None:
            rows.append({'day': day, 'points': points})
        else:
            found['points'] += points
        state['sizes'][lead] = record['company_size']
    if maximum is not None:
        cutoff = maximum - 6
        for lead in list(state['entries']):
            state['entries'][lead] = [r for r in state['entries'][lead] if r['day'] >= cutoff]
            if not state['entries'][lead]:
                del state['entries'][lead]
                state['sizes'].pop(lead, None)
    result = []
    for lead, rows in state['entries'].items():
        raw = sum((r['points'] for r in rows))
        size = state['sizes'][lead]
        multiplier = 1.5 if size >= 1000 else 1.25 if size >= 100 else 1.0
        result.append({'lead_id': lead, 'score': round(raw * multiplier, 2), 'last_day': max((r['day'] for r in rows))})
