import datetime
import requests

def get_available_slots(api_url: str, office: str | None, start_date: str, end_date: str, page: int=1, page_size: int=20) -> dict:
    try:
        start = datetime.date.fromisoformat(start_date)
        end = datetime.date.fromisoformat(end_date)
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid date') from exc
    if start > end or isinstance(page, bool) or (not isinstance(page, int)) or (page < 1) or isinstance(page_size, bool) or (not isinstance(page_size, int)) or (not 1 <= page_size <= 100):
        raise ValueError('invalid pagination or date range')
    params = {'start_date': start_date, 'end_date': end_date}
    if office is not None:
        params['office'] = office
    response = requests.get(api_url.rstrip('/') + '/appointments', params=params, headers={'Accept': 'application/json'})
    if response.status_code != 200:
        raise RuntimeError('appointment service returned an error')
    try:
        payload = response.json()
    except Exception as exc:
        raise ValueError('invalid response') from exc
