import datetime
import requests

def summarize_crossings(country: str, start_date: str, end_date: str, min_wait: int=0) -> list[dict]:
    if not isinstance(country, str) or not country:
        raise ValueError('invalid country')
    if not isinstance(min_wait, int) or isinstance(min_wait, bool) or min_wait < 0:
        raise ValueError('invalid wait')
    try:
        start = datetime.date.fromisoformat(start_date)
        end = datetime.date.fromisoformat(end_date)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if start > end:
        raise ValueError('invalid range')
    response = requests.get('https://borderdata.example.gov/api/crossings', params={'country': country, 'start_date': start_date, 'end_date': end_date, 'min_wait': min_wait}, headers={'Accept': 'application/json'})
    if response.status_code != 200:
        raise RuntimeError('request failed')
    payload = response.json()
    if not isinstance(payload, dict) or not isinstance(payload.get('records'), list):
        raise ValueError('invalid payload')
    grouped = {}
    for record in payload['records']:
        date = datetime.date.fromisoformat(record['date'])
        if start <= date <= end and record['wait_minutes'] >= min_wait:
            border = record['border']
            item = grouped.setdefault(border, {'border': border, 'crossings': 0, 'vehicles': 0, 'max_wait': 0, '_wait': 0})
            item['crossings'] += 1
            item['vehicles'] += record['vehicles']
            item['max_wait'] = max(item['max_wait'], record['wait_minutes'])
            item['_wait'] += record['wait_minutes']
    result = []
    for item in grouped.values():
        result.append({'border': item['border'], 'crossings': item['crossings'], 'vehicles': item['vehicles'], 'max_wait': item['max_wait'], 'average_wait': round(item['_wait'] / item['crossings'], 1)})
    result.sort(key=lambda item: (-item['vehicles'], item['border']))
    return result

