import csv
import io
from decimal import Decimal, InvalidOperation
from html import escape
HEADER = ['id', 'movie', 'hall', 'row', 'seat', 'price', 'status', 'customer']

def parse_reservations(text: str) -> list[dict]:
    if not text:
        raise ValueError('empty input')
    try:
        rows = list(csv.reader(io.StringIO(text), delimiter=';', strict=True))
    except csv.Error as exc:
        raise ValueError('malformed csv') from exc
    if not rows or rows[0] != HEADER or len(rows) == 1:
        raise ValueError('invalid header or empty data')
    result = []
    ids = set()
    for row in rows[1:]:
        if len(row) != 8:
            raise ValueError('wrong field count')
        values = [x.strip() for x in row]
        ident, movie, hall, seat_row, seat, price, status, customer = values
        if any((not x for x in (ident, movie, hall, seat_row, seat, status, customer))):
            raise ValueError('blank field')
        if ident in ids or status not in ('reserved', 'cancelled'):
            raise ValueError('invalid reservation')
        try:
            amount = Decimal(price)
        except InvalidOperation as exc:
            raise ValueError('invalid price') from exc
        if amount < 0 or amount.as_tuple().exponent < -2:
            raise ValueError('invalid price')
        cents = int(amount * 100)
        ids.add(ident)
        result.append({'id': ident, 'movie': movie, 'hall': hall, 'row': seat_row, 'seat': seat, 'price': cents, 'status': status, 'customer': customer})
    return result

def render_report(records: list[dict], title: str) -> str:
    ordered = sorted(records, key=lambda r: (r['movie'].casefold(), r['hall'].casefold(), r['row'], int(r['seat']), r['id']))
    reserved = [r for r in records if r['status'] == 'reserved']
    total = sum((r['price'] for r in reserved))
    rows = []
    for r in ordered:
        cells = [r['movie'], r['hall'], f"{r['row']} {r['seat']}", r['customer'], r['status'], f"€{r['price'] / 100:.2f}"]
        rows.append('<tr>' + ''.join(('<td>' + escape(str(x)) + '</td>' for x in cells)) + '</tr>')
    return '<section class="cinema-report"><h1>' + escape(title) + '</h1><div class="summary">' + str(len(reserved)) + ' reservations · €' + f'{total / 100:.2f}' + '</div><table><thead><tr><th>Movie</th><th>Hall</th><th>Seat</th><th>Customer</th><th>Status</th><th>Price</th></tr></thead><tbody>' + ''.join(rows) + '</tbody></table></section>'

