def new_state() -> dict[str, object]:
    return {'orders': {}}

def apply_events(state: dict[str, object], events: list[dict[str, object]]) -> dict[str, object]:
    if not isinstance(state, dict) or not isinstance(state.get('orders'), dict):
        raise ValueError('invalid state')
    out = copy.deepcopy(state)
    orders = out['orders']
    for event in events:
        if not isinstance(event, dict) or not isinstance(event.get('type'), str):
            raise ValueError('invalid event')
        kind = event['type']
        if kind == 'create':
            oid, customer = (event.get('id'), event.get('customer'))
            if not isinstance(oid, str) or not oid or (not isinstance(customer, str)) or (not customer) or (oid in orders):
                raise ValueError('invalid create')
            orders[oid] = {'customer': customer, 'items': [], 'status': 'draft'}
        elif kind in ('add', 'confirm', 'cancel'):
            oid = event.get('id')
            if not isinstance(oid, str) or oid not in orders:
                raise ValueError('missing order')
            order = orders[oid]
            if order['status'] == 'cancelled':
                raise ValueError('cancelled order')
            if kind == 'add':
                name, quantity, price = (event.get('name'), event.get('quantity'), event.get('unit_price'))
                if not isinstance(name, str) or not name or isinstance(quantity, bool) or (not isinstance(quantity, int)) or (quantity <= 0) or isinstance(price, bool) or (not isinstance(price, int)) or (price < 0) or (order['status'] != 'draft'):
                    raise ValueError('invalid item')
                order['items'].append({'name': name, 'quantity': quantity, 'unit_price': price})
            elif kind == 'confirm':
                if order['status'] != 'draft' or not order['items']:
                    raise ValueError('cannot confirm')
                order['status'] = 'confirmed'
            else:
                order['status'] = 'cancelled'
        else:
            raise ValueError('unknown event')
    return out

def summarize(state: dict[str, object]) -> list[dict[str, object]]:
    result = []
    for oid, order in state['orders'].items():
        count = sum((item['quantity'] for item in order['items']))
        total = sum((item['quantity'] * item['unit_price'] for item in order['items']))
        result.append({'id': oid, 'customer': order['customer'], 'status': order['status'], 'item_count': count, 'total_cents': total})
    return sorted(result, key=lambda x: (-x['total_cents'], x['customer'], x['id']))

def encode_state(state: dict[str, object]) -> bytes:
    return json.dumps(state, separators=(',', ':'), ensure_ascii=False).encode('utf-8')

def decode_state(blob: bytes) -> dict[str, object]:
    try:
        value = json.loads(blob.decode('utf-8'))
    except (ValueError, UnicodeError, AttributeError):
        raise ValueError('invalid blob')
    if not isinstance(value, dict) or not isinstance(value.get('orders'), dict):
        raise ValueError('invalid state')
    return value

