import requests

def price_cart(items: list[tuple[str, int]], currency: str='USD') -> dict:
    if not isinstance(currency, str) or not currency:
        raise ValueError('invalid currency')
    if not isinstance(items, list):
        raise ValueError('invalid items')
    if not items:
        return {'currency': currency, 'items': [], 'subtotal': 0}
    quantities = {}
    for entry in items:
        if not isinstance(entry, tuple) or len(entry) != 2:
            raise ValueError('invalid item')
        sku, quantity = entry
        if not isinstance(sku, str) or not sku.strip():
            raise ValueError('invalid sku')
        if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity <= 0:
            raise ValueError('invalid quantity')
        sku = sku.strip()
        quantities[sku] = quantities.get(sku, 0) + quantity
    names = sorted(quantities)
    result = requests.get('https://pricing.example.com/v1/prices', params={'sku': ','.join(names), 'currency': currency}, timeout=5)
    if result.status_code != 200:
        raise ValueError('price request failed')
    try:
        data = result.json()
        records = data['prices']
        if not isinstance(records, list):
            raise ValueError
        prices = {}
        for record in records:
            if not isinstance(record, dict):
                raise ValueError
            sku = record['sku']
            unit_price = record['unit_price']
            active = record['active']
            if not isinstance(sku, str) or not sku or isinstance(unit_price, bool) or (not isinstance(unit_price, int)) or (unit_price < 0) or (not isinstance(active, bool)):
                raise ValueError
            prices[sku] = (unit_price, active)
    except (KeyError, TypeError, ValueError):
        raise ValueError('invalid price data')
    output = []
    subtotal = 0
