import json
from datetime import datetime, timedelta

def _check_records(records):
    if not isinstance(records, list):
        raise ValueError('records')
    required = {'id', 'name', 'port', 'day', 'start', 'duration_minutes', 'price'}
    for record in records:
        if not isinstance(record, dict) or set(record) != required:
            raise ValueError('record')
        if not all((isinstance(record[k], str) for k in ('id', 'name', 'port', 'day', 'start'))):
            raise ValueError('record')
        try:
            datetime.strptime(record['day'], '%Y-%m-%d')
            datetime.strptime(record['start'], '%H:%M')
        except (TypeError, ValueError):
            raise ValueError('record')
        if isinstance(record['duration_minutes'], bool) or not isinstance(record['duration_minutes'], int) or record['duration_minutes'] <= 0:
            raise ValueError('record')
        if isinstance(record['price'], bool) or not isinstance(record['price'], (int, float)) or record['price'] < 0:
            raise ValueError('record')

def encode_excursions(records: list[dict]) -> bytes:
    _check_records(records)
    return json.dumps(records, separators=(',', ':')).encode('utf-8')

def build_excursion_page(blob: bytes, port: str, day: str, page: int, page_size: int) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page <= 0 or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (page_size <= 0):
        raise ValueError('pagination')
    try:
        records = json.loads(blob.decode('utf-8'))
        _check_records(records)
    except (AttributeError, UnicodeError, json.JSONDecodeError, TypeError, ValueError):
        raise ValueError('payload')
    matches = [r for r in records if r['port'] == port and r['day'] == day]
    matches.sort(key=lambda r: (r['start'], r['price'], r['id']))
    start = (page - 1) * page_size
    selected = matches[start:start + page_size]
    output = []
    for r in selected:
        t = datetime.strptime(r['start'], '%H:%M') + timedelta(minutes=r['duration_minutes'])
        output.append({'id': r['id'], 'name': r['name'], 'start': r['start'], 'end': t.strftime('%H:%M'), 'price': r['price']})
    average = round(sum((r['price'] for r in matches)) / len(matches), 2) if matches else 0.0
    return {'total': len(matches), 'average_price': average, 'excursions': output}

