            end = datetime.date.fromisoformat(record['end_date'])
        except (KeyError, ValueError) as exc:
            raise ValueError('invalid permit date') from exc
        if record.get('zone') == zone and record.get('resident_id') == resident_id and (record.get('status') == 'active') and (start <= report_date <= end):
