    lines.append(f"""<p class="totals">Applications: {len(summary['applications'])} | Total requested: {money(summary['total_amount'])}</p>""")
    counts = summary['status_counts']
    lines.append('<ul class="status-counts">' + ''.join((f'<li>{esc(s)}: {counts[s]}</li>' for s in ('pending', 'approved', 'declined'))) + '</ul>')
    lines.append('<table><thead><tr><th>ID</th><th>Applicant</th><th>Region</th><th>Status</th><th>Amount</th><th>Ratio</th><th>Age</th></tr></thead><tbody>')
    for item in summary['applications']:
        lines.append(f"<tr><td>{esc(item['id'])}</td><td>{esc(item['applicant'])}</td><td>{esc(item['region'])}</td><td>{esc(item['status'])}</td><td>{money(item['amount'])}</td><td>{item['income_ratio']:.4f}</td><td>{item['age_days']} days</td></tr>")
    lines.append('</tbody></table>')
    lines.append('<h2>Regional totals</h2>')
    lines.append('<ul class="regional-totals">' + ''.join((f'<li>{esc(region)}: {money(amount)}</li>' for region, amount in summary['region_totals'].items())) + '</ul>')
    lines.append('</section>')
    return '\n'.join(lines) + '\n'

