def encode_state(state: dict) -> bytes:
    return pickle.dumps(state, protocol=4)

def decode_state(blob: bytes) -> dict:
    try:
        value = pickle.loads(blob)
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(value, dict):
        raise ValueError('invalid state')
    return value

def _eligible(record, day):
    if not isinstance(record, dict):
        raise ValueError('invalid subscriber')
    af = record['active_from']
    au = record['active_until']
    if isinstance(af, bool) or not isinstance(af, int) or (au is not None and (isinstance(au, bool) or not isinstance(au, int))):
        raise ValueError('invalid dates')
    if day < af or (au is not None and day > au):
        return False
    for interval in record.get('pauses', []):
        if not isinstance(interval, list) or len(interval) != 2:
            raise ValueError('invalid pause')
        if interval[0] <= day <= interval[1]:
            return False
    return True

def plan_fulfillment(state: dict, deliveries: list[dict], start_day: int, end_day: int) -> list[dict]:
    if start_day > end_day:
        raise ValueError('invalid range')
    subscribers = state.get('subscribers', {})
    groups = {}
    for item in deliveries:
        if not isinstance(item, dict):
            raise ValueError('invalid delivery')
        sid, day, issue, quantity = (item.get(k) for k in ('subscriber', 'day', 'issue', 'quantity'))
        if not isinstance(day, int) or isinstance(day, bool) or (not isinstance(quantity, int)) or isinstance(quantity, bool):
            raise ValueError('invalid delivery')
        if day < start_day or day > end_day or quantity <= 0 or (sid not in subscribers):
            continue
        record = subscribers[sid]
        if _eligible(record, day):
            key = (day, record['address'], issue)
            groups.setdefault(key, [0, set()])
            groups[key][0] += quantity
            groups[key][1].add(sid)
    return [{'day': k[0], 'address': k[1], 'issue': k[2], 'quantity': v[0], 'subscriber_ids': sorted(v[1])} for k, v in sorted(groups.items())]

