import json
from datetime import date, timedelta

def encode_membership_state(members: list[dict]) -> bytes:
    return json.dumps(members, ensure_ascii=False, separators=(',', ':')).encode('utf-8')

def decode_membership_state(blob: bytes | str) -> list[dict]:
    try:
        text = blob.decode('utf-8') if isinstance(blob, bytes) else blob
        value = json.loads(text)
    except (UnicodeError, TypeError, json.JSONDecodeError):
        raise ValueError('invalid membership state')
    if not isinstance(value, list) or any((not isinstance(item, dict) for item in value)):
        raise ValueError('invalid membership state')
    return value

def membership_report(blob: bytes | str, as_of: str) -> list[dict]:
    try:
        today = date.fromisoformat(as_of)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    members = decode_membership_state(blob)
    tier_order = {'gold': 0, 'silver': 1, 'bronze': 2}
    prepared = []
    for member in members:
        required = ('id', 'name', 'tier', 'joined', 'visits')
        if any((key not in member for key in required)):
            raise ValueError('invalid member')
        if any((not isinstance(member[key], str) for key in required[:4])):
            raise ValueError('invalid member')
        if not isinstance(member['visits'], list) or member['tier'] not in tier_order:
            raise ValueError('invalid member')
        if any((not isinstance(value, str) for value in member['visits'])):
            raise ValueError('invalid member')
        try:
            joined = date.fromisoformat(member['joined'])
            visits = [date.fromisoformat(value) for value in member['visits']]
        except (TypeError, ValueError):
            raise ValueError('invalid member')
        start = today - timedelta(days=29)
        lifetime = sum((value <= today for value in visits))
        recent = sum((start <= value <= today for value in visits))
        result = {'id': member['id'], 'name': member['name'], 'tier': member['tier'], 'active': joined <= today <= joined + timedelta(days=365), 'visits_30d': recent, 'lifetime_visits': lifetime}
        prepared.append((tier_order[member['tier']], -recent, joined, member['id'], result))
    prepared.sort(key=lambda item: item[:4])
    return [item[4] for item in prepared]

