from datetime import datetime, timezone
import requests

def _time(value):
    if not isinstance(value, str):
        raise ValueError('invalid timestamp')
    try:
        d = datetime.fromisoformat(value.replace('Z', '+00:00'))
    except ValueError as e:
        raise ValueError('invalid timestamp') from e
    if d.tzinfo is None:
        d = d.replace(tzinfo=timezone.utc)
    return d.astimezone(timezone.utc)

def fetch_payouts(campaign_id: str, api_token: str) -> list[dict]:
    url = f'https://api.crowdfund.example/v1/campaigns/{campaign_id}/payouts'
    result = []
    cursor = None
    for page in range(10):
        params = {'page_size': 100}
        if cursor:
            params['cursor'] = cursor
        r = requests.get(url, params=params, headers={'Authorization': f'Bearer {api_token}'})
        if r.status_code == 404:
            raise LookupError('campaign not found')
        if r.status_code != 200:
            raise RuntimeError('payout request failed')
        try:
            data = r.json()
        except Exception as e:
            raise ValueError('invalid response') from e
        if not isinstance(data, dict) or not isinstance(data.get('payouts'), list):
            raise ValueError('invalid response')
        result.extend(data['payouts'])
        cursor = data.get('next_cursor')
        if not isinstance(cursor, str) or not cursor:
            return result
    raise RuntimeError('too many pages')

def build_payout_report(campaign_id: str, api_token: str, as_of: str) -> list[dict]:
    cutoff = _time(as_of)
    chosen = {}
    for index, row in enumerate(fetch_payouts(campaign_id, api_token)):
        try:
            ident = row['id']
            recipient = row['recipient']
            amount = row['amount']
            rid, name = (recipient['id'], recipient['name'])
            currency, cents = (amount['currency'], amount['cents'])
            status = row['status']
            paid = row['paid_at']
            updated = row['updated_at']
            paid_time, update_time = (_time(paid), _time(updated))
            if not isinstance(ident, str) or not isinstance(rid, str) or (not isinstance(name, str)) or (currency != 'USD') or (not isinstance(cents, int)) or isinstance(cents, bool) or (not isinstance(status, str)):
                raise ValueError('invalid payout')
        except (KeyError, TypeError, ValueError) as e:
            raise ValueError('invalid payout') from e
        item = (update_time, index, rid, name, cents, paid, paid_time, status)
        if ident not in chosen or item[:2] >= chosen[ident][:2]:
            chosen[ident] = item
    groups = {}
    for update, index, rid, name, cents, paid, paid_time, status in chosen.values():
        if status != 'completed' or paid_time > cutoff:
            continue
        g = groups.setdefault(rid, {'recipient_id': rid, 'recipient_name': name, 'total_cents': 0, 'payout_count': 0, 'last_paid_at': paid, 'last_time': paid_time})
        g['total_cents'] += cents
        g['payout_count'] += 1
        if paid_time > g['last_time']:
            g['last_time'], g['last_paid_at'] = (paid_time, paid)
    values = list(groups.values())
    values.sort(key=lambda x: (-x['total_cents'], -x['last_time'].timestamp(), x['recipient_id']))
    for value in values:
        del value['last_time']
    return values

