from solution import pack_telemetry, unpack_telemetry
import pytest


def test_round_trip_typical_record():
    record = {
        "station_id": "BUOY-17",
        "timestamp": 1700000123,
        "measurements": {"temperature_c": 14.75, "salinity_psu": 33.1, "wave_height_m": 2},
    }
    assert unpack_telemetry(pack_telemetry(record)) == record


def test_round_trip_preserves_measurement_order():
    record = {
        "station_id": "NORTH-2",
        "timestamp": 0,
        "measurements": {"z": 3.0, "a": -1.25, "middle": 0},
    }
    result = unpack_telemetry(pack_telemetry(record))
    assert list(result["measurements"]) == ["z", "a", "middle"]
    assert result == record


def test_empty_measurements_are_allowed():
    record = {"station_id": "CALM-1", "timestamp": 42, "measurements": {}}
    assert unpack_telemetry(pack_telemetry(record)) == record


def test_pack_is_deterministic():
    record = {"station_id": "B-3", "timestamp": 99, "measurements": {"x": 1.5}}
    assert pack_telemetry(record) == pack_telemetry(record)


def test_invalid_record_shapes_raise_value_error():
    cases = [
        {},
        {"station_id": "x", "timestamp": 1},
        {"station_id": "", "timestamp": 1, "measurements": {}},
        {"station_id": "x", "timestamp": -1, "measurements": {}},
        {"station_id": "x", "timestamp": True, "measurements": {}},
        {"station_id": "x", "timestamp": 1, "measurements": {"t": True}},
        {"station_id": "x", "timestamp": 1, "measurements": {1: 2}},
    ]
    for record in cases:
        with pytest.raises(ValueError):
            pack_telemetry(record)


def test_wrong_argument_types_raise_type_error():
    with pytest.raises(TypeError):
        pack_telemetry([])
    with pytest.raises(TypeError):
        unpack_telemetry("not bytes")


def test_malformed_payload_raises_value_error():
    with pytest.raises(ValueError):
        unpack_telemetry(b"not a telemetry payload")


def test_decoded_invalid_record_raises_value_error():
    blob = pack_telemetry({"station_id": "ok", "timestamp": 5, "measurements": {}})
    assert unpack_telemetry(blob)["station_id"] == "ok"

