import json

def _validate(record):
    if not isinstance(record, dict):
        raise ValueError('record must be a dictionary')
    if set(record) != {'station_id', 'timestamp', 'measurements'}:
        raise ValueError('invalid record fields')
    if not isinstance(record['station_id'], str) or not record['station_id']:
        raise ValueError('invalid station_id')
    if not isinstance(record['timestamp'], int) or isinstance(record['timestamp'], bool) or record['timestamp'] < 0:
        raise ValueError('invalid timestamp')
    measurements = record['measurements']
    if not isinstance(measurements, dict):
        raise ValueError('invalid measurements')
    for key, value in measurements.items():
        if not isinstance(key, str) or not isinstance(value, (int, float)) or isinstance(value, bool):
            raise ValueError('invalid measurement')

def pack_telemetry(record: dict) -> bytes:
    if not isinstance(record, dict):
        raise TypeError('record must be a dictionary')
    _validate(record)
    return json.dumps(record, separators=(',', ':'), ensure_ascii=False).encode('utf-8')

def unpack_telemetry(blob: bytes) -> dict:
    if not isinstance(blob, (bytes, bytearray)):
        raise TypeError('blob must be bytes')
    try:
        record = json.loads(bytes(blob).decode('utf-8'))
        _validate(record)
        return record
    except (UnicodeError, json.JSONDecodeError, TypeError, ValueError):
        raise ValueError('malformed telemetry payload')

