import requests

def get_route_summary(api_url: str, hub: str, delivery_date: str, max_distance_km: float=25.0) -> list[dict]:
    if not hub or max_distance_km < 0:
        raise ValueError('invalid arguments')
    try:
        date.fromisoformat(delivery_date)
    except ValueError:
        raise ValueError('invalid date')
    response = requests.get(api_url.rstrip('/') + '/v1/routes', params={'hub': hub, 'date': delivery_date}, headers={'Accept': 'application/json'})
    if response.status_code != 200:
        raise RuntimeError('route service failure')
    payload = response.json()
    if not isinstance(payload, dict) or not isinstance(payload.get('routes'), list):
        raise ValueError('invalid response')
    result = []
    for route in payload['routes']:
        if not isinstance(route, dict):
            raise ValueError('invalid route')
        try:
            status = route['status']
            distance = route['distance_km']
            stops = route['stops']
            route_id = route['route_id']
            driver = route['driver']
            eta = route['eta_minutes']
        except (KeyError, TypeError):
            raise ValueError('invalid route')
        if status != 'scheduled' or distance > max_distance_km:
            continue
        if not isinstance(stops, list) or not stops:
            continue
        total = 0
        for stop in stops:
            if not isinstance(stop, dict):
                raise ValueError('invalid stop')
            total += stop.get('package_count', 0)
        result.append({'route_id': route_id, 'driver': driver, 'stop_count': len(stops), 'total_packages': total, 'distance_km': round(distance, 1), 'eta_minutes': eta})
    result.sort(key=lambda item: (item['distance_km'], item['eta_minutes'], str(item['route_id'])))
    return result

