from solution import fetch_exhibitors, summarize_zones, allocate_dock_slots
from unittest.mock import Mock, patch
import pytest

def test_fetch_exhibitors_builds_request_and_normalizes_values():
    response = Mock()
    response.status_code = 200
    response.json.return_value = {'exhibitors': [{'id': 7, 'booth': 12, 'zone': 'north', 'arrival': '09:00', 'crates': 4, 'priority': 2}]}
    with patch('solution.requests.get', return_value=response) as get:
        result = fetch_exhibitors('https://logistics.example/api', 'E42', 'abc')
    assert result == [{'id': '7', 'booth': '12', 'zone': 'NORTH', 'arrival': '09:00', 'crates': 4, 'priority': 2}]
    args, kwargs = get.call_args
    assert args[0] == 'https://logistics.example/api/events/E42/exhibitors'
    assert kwargs['params'] == {'event': 'E42'}
    assert kwargs['headers']['Authorization'] == 'Bearer abc'
    assert kwargs['headers']['Accept'] == 'application/json'

def test_fetch_exhibitors_rejects_http_errors():
    response = Mock()
    response.status_code = 503
    with patch('solution.requests.get', return_value=response):
        with pytest.raises(RuntimeError, match='503'):
            fetch_exhibitors('https://x', 'E', 't')

def test_fetch_exhibitors_rejects_missing_or_wrong_payload():
    for payload in ({}, {'exhibitors': {}}, {'exhibitors': [{'id': 'a'}]}):
        response = Mock(status_code=200)
        response.json.return_value = payload
        with patch('solution.requests.get', return_value=response):
            with pytest.raises(ValueError):
                fetch_exhibitors('https://x', 'E', 't')

def test_summarize_zones_sorts_keys_and_counts():
    records = [{'id': '1', 'booth': 'B', 'zone': 'Z', 'arrival': '08:00', 'crates': 3, 'priority': 1}, {'id': '2', 'booth': 'A', 'zone': 'A', 'arrival': '08:00', 'crates': 5, 'priority': 1}, {'id': '3', 'booth': 'C', 'zone': 'Z', 'arrival': '08:30', 'crates': 2, 'priority': 2}]
    assert summarize_zones(records) == {'A': {'exhibitors': 1, 'crates': 5}, 'Z': {'exhibitors': 2, 'crates': 5}}

