import requests

def _time(value):
    if not isinstance(value, str):
        raise ValueError('invalid timestamp')
    try:
        text = value[:-1] + '+00:00' if value.endswith('Z') else value
        result = datetime.fromisoformat(text)
        if result.tzinfo is None:
            result = result.replace(tzinfo=timezone.utc)
        return result
    except ValueError as exc:
        raise ValueError('invalid timestamp') from exc

def fetch_accommodation_requests(base_url: str, employee_id: str, token: str) -> list[dict]:
    response = requests.get(base_url.rstrip('/') + '/api/accommodation-requests', params={'employee_id': employee_id}, headers={'Authorization': 'Bearer ' + token}, timeout=10)
    if response.status_code != 200:
        raise ValueError('request failed with status ' + str(response.status_code))
    try:
        data = response.json()
    except Exception as exc:
        raise ValueError('invalid response') from exc
    if not isinstance(data, dict) or not isinstance(data.get('requests'), list):
        raise ValueError('invalid response')
    result = []
    for item in data['requests']:
        if not isinstance(item, dict):
            raise ValueError('invalid request record')
        employee = item.get('employee')
        accommodation = item.get('accommodation')
        fields = [item.get('id'), item.get('status'), item.get('submitted_at'), item.get('due_date')]
        if any((not isinstance(x, str) or not x for x in fields)) or not isinstance(employee, dict) or (not isinstance(employee.get('name'), str)) or (not employee['name']) or (not isinstance(accommodation, dict)) or (not isinstance(accommodation.get('type'), str)) or (not accommodation['type']):
            raise ValueError('invalid request record')
        result.append({'id': item['id'], 'employee_name': employee['name'], 'type': accommodation['type'], 'status': item['status'], 'submitted_at': item['submitted_at'], 'due_date': item['due_date']})
    return result

def summarize_accommodation_requests(records: list[dict], as_of: str) -> dict:
    point = _time(as_of)
    required = ('id', 'employee_name', 'type', 'status', 'submitted_at', 'due_date')
    statuses, types, employees, overdue, prepared = ({}, {}, {}, [], [])
    ranks = {'urgent': 0, 'pending': 1, 'approved': 2, 'completed': 3, 'cancelled': 4}
    for record in records:
        if not isinstance(record, dict) or any((not isinstance(record.get(k), str) or not record[k] for k in required)):
            raise ValueError('invalid record')
        submitted = _time(record['submitted_at'])
        due = _time(record['due_date'])
        status = record['status']
        statuses[status] = statuses.get(status, 0) + 1
        types[record['type']] = types.get(record['type'], 0) + 1
        employees[record['employee_name']] = employees.get(record['employee_name'], 0) + 1
        if status not in ('completed', 'cancelled') and due < point:
            overdue.append((due, record['id']))
        prepared.append((ranks.get(status, 5), due, submitted, record['id']))
    return {'total': len(records), 'by_status': dict(sorted(statuses.items())), 'by_type': dict(sorted(types.items())), 'overdue_ids': [x[1] for x in sorted(overdue)], 'priority_order': [x[3] for x in sorted(prepared)], 'employee_totals': dict(sorted(employees.items()))}

