def new_state() -> dict:
    return {'images': {}}

def _valid_number(value):
    return isinstance(value, (int, float)) and (not isinstance(value, bool)) and math.isfinite(value) and (0 <= value <= 1)

def _validate_state(state):
    if not isinstance(state, dict) or set(state) != {'images'} or (not isinstance(state['images'], dict)):
        raise ValueError('invalid state')
    for image, records in state['images'].items():
        if not isinstance(image, str) or not image or (not isinstance(records, list)):
            raise ValueError('invalid state')
        for record in records:
