                raise ValueError('invalid state')
            if not _valid_number(record['score']):
                raise ValueError('invalid state')
            if any((not isinstance(record[k], str) or not record[k] for k in ('label', 'reviewer'))):
                raise ValueError('invalid state')

def apply_reviews(state: dict, reviews: list[dict], history_limit: int=5) -> dict:
    _validate_state(state)
    if not isinstance(reviews, list) or not isinstance(history_limit, int) or isinstance(history_limit, bool) or (history_limit <= 0):
        raise ValueError('invalid input')
    result = {'images': {k: [dict(r) for r in v] for k, v in state['images'].items()}}
    for item in reviews:
        if not isinstance(item, dict) or set(item) != {'image', 'score', 'label', 'reviewer'}:
            raise ValueError('invalid review')
        if not isinstance(item['image'], str) or not item['image'] or (not _valid_number(item['score'])):
            raise ValueError('invalid review')
        if any((not isinstance(item[k], str) or not item[k] for k in ('label', 'reviewer'))):
            raise ValueError('invalid review')
        image = item['image']
        result['images'].setdefault(image, []).append({'score': item['score'], 'label': item['label'], 'reviewer': item['reviewer']})
        result['images'][image] = result['images'][image][-history_limit:]
    return result

