    _validate_state(state)
    return json.dumps(state, sort_keys=True, separators=(',', ':'), allow_nan=False).encode('utf-8')

def decode_state(blob: bytes) -> dict:
    if not isinstance(blob, bytes):
        raise ValueError('invalid data')
    try:
        state = json.loads(blob.decode('utf-8'))
        _validate_state(state)
        return state
    except Exception as exc:
        raise ValueError('invalid data') from exc

def moderation_report(state: dict) -> list[dict]:
    _validate_state(state)
    rows = []
    for image, records in state['images'].items():
        if not records:
            continue
        average = sum((r['score'] for r in records)) / len(records)
        counts = {}
        for record in records:
            counts[record['label']] = counts.get(record['label'], 0) + 1
        label = min(counts, key=lambda x: (-counts[x], x))
        decision = 'block' if average >= 0.8 else 'review' if average >= 0.5 else 'allow'
        rows.append({'image': image, 'average_score': round(average, 4), 'review_count': len(records), 'label': label, 'decision': decision})
    rows.sort(key=lambda r: (-r['average_score'], -r['review_count'], r['image']))
    return rows

