import json

def _fields(line):
    out, cur, escaped = ([], [], False)
    for ch in line:
        if escaped:
            if ch not in '\\|':
                raise ValueError('bad escape')
            cur.append(ch)
            escaped = False
        elif ch == '\\':
            escaped = True
        elif ch == '|':
            out.append(''.join(cur))
            cur = []
        else:
            cur.append(ch)
    if escaped:
        raise ValueError('bad escape')
    out.append(''.join(cur))
    return out

def parse_receipt(text: str) -> list[dict]:
    if not isinstance(text, str):
        raise ValueError('receipt must be text')
    result = []
    for line in text.splitlines():
        if not line:
            continue
        fields = _fields(line)
        if len(fields) != 4 or not fields[0] or (not fields[1]):
            raise ValueError('bad line')
        try:
            quantity = int(fields[2])
            price = int(fields[3])
        except Exception as exc:
            raise ValueError('bad number') from exc
        if str(quantity) != fields[2] or str(price) != fields[3] or quantity <= 0 or (price < 0):
            raise ValueError('bad number')
        result.append({'sku': fields[0], 'description': fields[1], 'quantity': quantity, 'unit_price_cents': price})
    return result

def receipt_totals(text: str, tax_rate_basis_points: int) -> dict:
    if not isinstance(tax_rate_basis_points, int) or not 0 <= tax_rate_basis_points <= 10000:
        raise ValueError('bad tax rate')
    sub = tax = items = 0
    for row in parse_receipt(text):
        amount = row['quantity'] * row['unit_price_cents']
        sub += amount
        tax += (amount * tax_rate_basis_points + 5000) // 10000
        items += row['quantity']
    return {'subtotal_cents': sub, 'tax_cents': tax, 'total_cents': sub + tax, 'items': items}

def _valid(state):
    if not isinstance(state, dict) or set(state) != {'receipts', 'items'} or (not isinstance(state['receipts'], int)) or (state['receipts'] < 0) or (not isinstance(state['items'], dict)):
        raise ValueError('bad state')
    for sku, item in state['items'].items():
        if not isinstance(sku, str) or not isinstance(item, dict) or set(item) != {'description', 'quantity', 'subtotal_cents', 'tax_cents'} or (not isinstance(item['description'], str)) or (not item['description']) or any((not isinstance(item[k], int) or item[k] < 0 for k in ('quantity', 'subtotal_cents', 'tax_cents'))) or (item['quantity'] <= 0):
            raise ValueError('bad state')

def encode_state(state: dict) -> bytes:
    _valid(state)
    return json.dumps(state, separators=(',', ':'), ensure_ascii=False).encode()

def decode_state(blob: bytes) -> dict:
    try:
        state = json.loads(blob.decode())
        _valid(state)
        return state
    except Exception as exc:
        raise ValueError('bad state blob') from exc

def add_receipt(blob: bytes, receipt_text: str, tax_rate_basis_points: int) -> bytes:
    state = decode_state(blob)
    rows = parse_receipt(receipt_text)
    if not isinstance(tax_rate_basis_points, int) or not 0 <= tax_rate_basis_points <= 10000:
        raise ValueError('bad tax rate')
    changes = {}
    for row in rows:
        amount = row['quantity'] * row['unit_price_cents']
        tax = (amount * tax_rate_basis_points + 5000) // 10000
        if row['sku'] in state['items'] and state['items'][row['sku']]['description'] != row['description']:
            raise ValueError('description conflict')
        item = changes.setdefault(row['sku'], {'description': row['description'], 'quantity': 0, 'subtotal_cents': 0, 'tax_cents': 0})
        item['quantity'] += row['quantity']
        item['subtotal_cents'] += amount
        item['tax_cents'] += tax
    result = {'receipts': state['receipts'] + 1, 'items': {k: dict(v) for k, v in state['items'].items()}}
    for sku, item in changes.items():
        if sku in result['items']:
            for key in ('quantity', 'subtotal_cents', 'tax_cents'):
                result['items'][sku][key] += item[key]
        else:
            result['items'][sku] = item
    return encode_state(result)

