import math

def render_inspection_report(records: list[dict], page: int=1, page_size: int=10) -> str:
    if not isinstance(records, list) or not isinstance(page, int) or isinstance(page, bool) or (not isinstance(page_size, int)) or isinstance(page_size, bool):
        raise ValueError('invalid arguments')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    required = ('site', 'hazard', 'severity', 'status', 'inspector')
    checked = []
    for record in records:
        if not isinstance(record, dict) or any((key not in record for key in required)):
            raise ValueError('invalid record')
        if any((not isinstance(record[key], str) for key in ('site', 'hazard', 'status', 'inspector'))):
            raise ValueError('invalid field')
        if not isinstance(record['severity'], int) or isinstance(record['severity'], bool) or (not 1 <= record['severity'] <= 5):
            raise ValueError('invalid severity')
        if record['status'] not in ('Open', 'Closed'):
            raise ValueError('invalid status')
        checked.append(record)
    ordered = sorted(checked, key=lambda r: (-r['severity'], r['site'], r['hazard'], r['inspector'], r['status']))
    total_pages = max(1, math.ceil(len(ordered) / page_size))
    if page > total_pages:
        raise IndexError('page out of range')
    start = (page - 1) * page_size
    visible = ordered[start:start + page_size]
    total = len(ordered)
    opened = sum((r['status'] == 'Open' for r in ordered))
    closed = total - opened
    average = sum((r['severity'] for r in ordered)) / total if total else 0
    rows = ''.join((f"<tr><td>{r['site']}</td><td>{r['hazard']}</td><td>{r['severity']}</td><td>{r['status']}</td><td>{r['inspector']}</td></tr>" for r in visible))
    return f'<div class="report"><h1>Safety Inspection Report</h1><p class="summary">Inspections: {total} | Open: {opened} | Closed: {closed} | Average severity: {average:.2f}</p><table><thead><tr><th>Site</th><th>Hazard</th><th>Severity</th><th>Status</th><th>Inspector</th></tr></thead><tbody>{rows}</tbody></table><p class="page">Page {page} of {total_pages}</p></div>'

