import json
import math

def _validate_documents(value):
    if not isinstance(value, list):
        raise ValueError('documents must be a list')
    result = []
    for item in value:
        if not isinstance(item, dict) or set(item) != {'id', 'category', 'score', 'amount'}:
            raise ValueError('invalid document')
        ident = item['id']
        category = item['category']
        score = item['score']
        amount = item['amount']
        if not isinstance(ident, str) or not ident or (not isinstance(category, str)) or (not category):
            raise ValueError('invalid document')
        if isinstance(score, bool) or not isinstance(score, (int, float)) or (not math.isfinite(score)) or (not 0 <= score <= 1):
            raise ValueError('invalid document')
        if isinstance(amount, bool) or not isinstance(amount, (int, float)) or (not math.isfinite(amount)) or (amount < 0):
            raise ValueError('invalid document')
        result.append(dict(item))
    return result

def pack_documents(documents: list[dict]) -> bytes:
    return json.dumps(_validate_documents(documents), separators=(',', ':')).encode('utf-8')

def fraud_report(blob: bytes, threshold: float=0.7, page: int=1, page_size: int=10) -> dict:
    if isinstance(threshold, bool) or not isinstance(threshold, (int, float)) or (not math.isfinite(threshold)) or (not 0 <= threshold <= 1):
        raise ValueError('invalid threshold')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    try:
        documents = _validate_documents(json.loads(blob.decode('utf-8')))
    except Exception as exc:
        if isinstance(exc, ValueError):
            raise
        raise ValueError('invalid payload') from exc
    flagged = [d for d in documents if d['score'] >= threshold]
    flagged.sort(key=lambda d: (-d['score'], d['id']))
    categories = {}
    for item in flagged:
        categories[item['category']] = categories.get(item['category'], 0) + item['amount']
    start = (page - 1) * page_size
    return {'total': len(documents), 'flagged_count': len(flagged), 'flagged_amount': round(sum((d['amount'] for d in flagged)), 2), 'by_category': {k: round(categories[k], 2) for k in sorted(categories)}, 'items': flagged[start:start + page_size]}

