            raise ValueError('record')
        if isinstance(record['year'], bool) or not isinstance(record['year'], int):
            raise ValueError('year')
        if not isinstance(record['region'], str) or not record['region']:
            raise ValueError('region')
        if isinstance(record['anomaly'], bool) or not isinstance(record['anomaly'], (int, float)) or (not math.isfinite(record['anomaly'])):
            raise ValueError('anomaly')

