    a, b = (_day(start), _day(end))
    if b <= a:
        raise ValueError('invalid interval')
    return (a, b)

def load_reservations(api_url: str, kennel_id: str, start_date: str, end_date: str, token: str) -> list[dict]:
    begin, finish = _interval(start_date, end_date)
    response = requests.get(api_url.rstrip('/') + '/kennels/' + kennel_id + '/reservations', params={'start_date': start_date, 'end_date': end_date}, headers={'Authorization': 'Bearer ' + token}, timeout=10)
