            raise TypeError()
    except Exception as exc:
        raise ValueError('invalid response') from exc
    result = []
    for row in rows:
        try:
            check_in, check_out = _interval(row['check_in'], row['check_out'])
            if row['status'] == 'cancelled' or check_out <= begin or check_in >= finish:
                continue
            name = row['pet']['name']
            result.append({'id': row['id'], 'pet_name': name, 'check_in': row['check_in'], 'check_out': row['check_out']})
