            continue
        a, b = _interval(row['check_in'], row['check_out'])
        current = max(a, begin)
        while current < min(b, finish):
            result[current.isoformat()] += 1
            current += timedelta(days=1)
    return result

def available_windows(reservations: list[dict], start_date: str, end_date: str, capacity: int, minimum_nights: int) -> list[tuple[str, str]]:
    if capacity <= 0 or minimum_nights <= 0:
        raise ValueError('invalid capacity')
    occupancy = daily_occupancy(reservations, start_date, end_date)
    output = []
    run_start = None
    for key, count in occupancy.items():
        if count < capacity and run_start is None:
            run_start = key
        if count >= capacity and run_start is not None:
