_KEYS = ('case', 'inspector', 'severity', 'status', 'duration', 'tags')
_STATUSES = {'pass', 'fail', 'blocked'}

def _validate_record(record):
    if not isinstance(record, dict) or set(record) != set(_KEYS):
        raise ValueError('invalid record')
    if not isinstance(record['case'], str) or not record['case']:
        raise ValueError('invalid case')
    if not isinstance(record['inspector'], str) or not record['inspector']:
        raise ValueError('invalid inspector')
    severity = record['severity']
    if isinstance(severity, bool) or not isinstance(severity, int) or (not 1 <= severity <= 5):
        raise ValueError('invalid severity')
    if record['status'] not in _STATUSES:
        raise ValueError('invalid status')
    duration = record['duration']
    if isinstance(duration, bool) or not isinstance(duration, (int, float)) or duration < 0:
        raise ValueError('invalid duration')
    if not isinstance(record['tags'], list) or any((not isinstance(x, str) for x in record['tags'])):
        raise ValueError('invalid tags')

def _validate_records(records):
    if not isinstance(records, list):
        raise ValueError('invalid records')
    for record in records:
        _validate_record(record)

def serialize_inspections(records: list[dict]) -> bytes:
    _validate_records(records)
    return json.dumps(records, separators=(',', ':'), ensure_ascii=False, allow_nan=False).encode('utf-8')

def deserialize_inspections(blob: bytes) -> list[dict]:
    if not isinstance(blob, bytes):
        raise ValueError('invalid payload')
    try:
        records = json.loads(blob.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    _validate_records(records)
    return records

def summarize_inspections(records: list[dict], window: int=3) -> list[dict]:
    _validate_records(records)
    if isinstance(window, bool) or not isinstance(window, int) or window <= 0:
        raise ValueError('invalid window')
    grouped = {}
    for record in records:
        grouped.setdefault(record['inspector'], []).append(record)
    result = []
    for inspector, items in grouped.items():
        selected = items[-window:]
        count = len(selected)
        failures = sum((x['status'] == 'fail' for x in selected))
        blocked = sum((x['status'] == 'blocked' for x in selected))
        result.append({'inspector': inspector, 'count': count, 'failures': failures, 'blocked': blocked, 'fail_rate': round(failures / count, 4), 'avg_duration': round(sum((x['duration'] for x in selected)) / count, 2), 'max_severity': max((x['severity'] for x in selected)), 'tags': sorted({tag for x in selected for tag in x['tags']})})
    result.sort(key=lambda x: (-x['fail_rate'], -x['max_severity'], -x['avg_duration'], x['inspector']))
    return result

