import csv
import io
import math
from html import escape

def parse_requests(text: str) -> list[dict]:
    rows = list(csv.reader(io.StringIO(text), delimiter='|', escapechar='\\'))
    if not rows:
        raise ValueError('missing header')
    first = rows[0]
    if first != ['id', 'name', 'accommodation', 'status', 'hours']:
        raise ValueError('invalid header')
    result = []
    seen = set()
    for row in rows[1:]:
        if not row or all((not field for field in row)):
            continue
        if len(row) != 5:
            raise ValueError('invalid row')
        ident, name, accommodation, status, raw_hours = row
        if not ident or not name or (not accommodation) or (ident in seen):
            raise ValueError('invalid identity')
        if status not in {'approved', 'pending', 'declined'}:
            raise ValueError('invalid status')
        try:
            hours = float(raw_hours)
        except ValueError as exc:
            raise ValueError('invalid hours') from exc
        if not math.isfinite(hours) or hours < 0:
            raise ValueError('invalid hours')
        seen.add(ident)
        result.append({'id': ident, 'name': name, 'accommodation': accommodation, 'status': status, 'hours': hours})
    if not result:
        raise ValueError('no records')
    return result

def summarize_requests(records: list[dict]) -> list[dict]:
    groups = {}
    for record in records:
        key = record['accommodation']
        if key not in groups:
            groups[key] = {'accommodation': key, 'requests': 0, 'approved_hours': 0.0, 'pending': 0}
        item = groups[key]
        item['requests'] += 1
        if record['status'] == 'approved':
            item['approved_hours'] += record['hours']
        elif record['status'] == 'pending':
            item['pending'] += 1
    result = list(groups.values())
    for item in result:
        item['approved_hours'] = round(item['approved_hours'], 2)
    result.sort(key=lambda item: (-item['requests'], item['accommodation']))
    return result

def render_report(records: list[dict], title: str) -> str:
    rows = []
    for item in summarize_requests(records):
        rows.append(f"<tr><td>{escape(item['accommodation'])}</td><td>{item['requests']}</td><td>{item['approved_hours']:.2f}</td><td>{item['pending']}</td></tr>")
    body = ''.join(rows)
    return f'<section class="report"><h1>{escape(title)}</h1><table><thead><tr><th>Accommodation</th><th>Requests</th><th>Approved hours</th><th>Pending</th></tr></thead><tbody>{body}</tbody></table><p class="total">Total requests: {len(records)}</p></section>'

