import html

def parse_transcript(source: str) -> list[dict]:
    result = []
    for raw in source.splitlines():
        if not raw.strip():
            continue
        fields = []
        current = []
        i = 0
        while i < len(raw):
            ch = raw[i]
            if ch == '\\':
                i += 1
                if i == len(raw) or raw[i] not in '\\|':
                    raise ValueError('invalid escape')
                current.append(raw[i])
            elif ch == '|':
                fields.append(''.join(current))
                current = []
            else:
                current.append(ch)
            i += 1
        fields.append(''.join(current))
        if len(fields) != 4:
            raise ValueError('invalid field count')
        try:
            start = float(fields[0])
            end = float(fields[1])
        except ValueError as exc:
            raise ValueError('invalid timestamp') from exc
        if start < 0 or end < start or (not (start == start and end == end)):
            raise ValueError('invalid interval')
        speaker = fields[2].strip()
        if not speaker:
            raise ValueError('empty speaker')
        result.append({'start': start, 'end': end, 'speaker': speaker, 'text': fields[3]})
    return result

def summarize_segments(segments: list[dict], window: float=30.0) -> list[dict]:
    if window <= 0:
        raise ValueError('window must be positive')
    grouped = {}
    for segment in segments:
        speaker = segment['speaker']
        item = grouped.setdefault(speaker, {'speaker': speaker, 'segments': 0, 'duration': 0.0, 'words': 0, 'windows': set()})
        start, end = (segment['start'], segment['end'])
        item['segments'] += 1
        item['duration'] += end - start
        item['words'] += len(segment['text'].split())
        first = int(start // window)
        last = first if end == start else int((end - 1e-12) // window)
        item['windows'].update(range(first, last + 1))
    result = []
    for item in grouped.values():
        item['duration'] = round(item['duration'], 2)
        item['windows'] = sorted(item['windows'])
        result.append(item)
    return sorted(result, key=lambda x: (-x['duration'], -x['words'], x['speaker']))

def render_report(title: str, segments: list[dict], window: float=30.0) -> str:
    summaries = summarize_segments(segments, window)
    rows = ''.join((f"<tr><td>{html.escape(x['speaker'], quote=True)}</td><td>{x['segments']}</td><td>{x['duration']:.2f}</td><td>{x['words']}</td><td>{','.join(map(str, x['windows']))}</td></tr>" for x in summaries))
    items = ''.join((f"""<li><span class="time">{s['start']:.2f}-{s['end']:.2f}</span> <b>{html.escape(s['speaker'], quote=True)}</b>: {html.escape(s['text'], quote=True)}</li>""" for s in segments))
    return f'<section class="transcript-report"><h1>{html.escape(title, quote=True)}</h1><table><thead><tr><th>Speaker</th><th>Segments</th><th>Duration</th><th>Words</th><th>Windows</th></tr></thead><tbody>{rows}</tbody></table><ol class="transcript">{items}</ol></section>'

