import pytest


def test_round_trip_and_aggregation():
    state = {
        "routes": [
            {"bus_id": "B2", "stops": [{"name": "Oak", "minutes": 7}, {"name": "Pine", "minutes": 3}]},
            {"bus_id": "B1", "stops": [{"name": "Oak", "minutes": 5}, {"name": "Pine", "minutes": 9}]},
        ]
    }
    result = summarize_route_state(dump_route_state(state))
    assert result == {"total": 2, "items": [
        {"name": "Oak", "total_minutes": 12, "route_count": 2, "average_minutes": 6.0},
        {"name": "Pine", "total_minutes": 12, "route_count": 2, "average_minutes": 6.0},
    ]}


def test_sorting_ties_and_pagination():
    state = {"routes": [
        {"bus_id": "a", "stops": [
            {"name": "Zoo", "minutes": 4}, {"name": "Alpha", "minutes": 4},
            {"name": "Beta", "minutes": 8}, {"name": "Beta", "minutes": 2}
        ]}
    ]}
    blob = dump_route_state(state)
    assert summarize_route_state(blob, offset=1, limit=2) == {"total": 3, "items": [
        {"name": "Alpha", "total_minutes": 4, "route_count": 1, "average_minutes": 4.0},
        {"name": "Zoo", "total_minutes": 4, "route_count": 1, "average_minutes": 4.0},
    ]}


