    state = {"routes": [
        {"bus_id": "A", "stops": [{"name": "Hill", "minutes": 5}, {"name": "Hill", "minutes": 10}]},
        {"bus_id": "B", "stops": [{"name": "Hill", "minutes": 6}, {"name": "Lake", "minutes": 10}]}
    ]}
    assert summarize_route_state(dump_route_state(state), min_minutes=6) == {"total": 2, "items": [
