def dump_route_state(state: dict) -> bytes:
    return json.dumps(state, separators=(',', ':'), sort_keys=True).encode('utf-8')

def summarize_route_state(blob: bytes, min_minutes: int=0, offset: int=0, limit: int=10) -> dict:
    if type(min_minutes) is not int or type(offset) is not int or type(limit) is not int:
        raise ValueError('invalid pagination')
    if min_minutes < 0 or offset < 0 or limit <= 0:
        raise ValueError('invalid pagination')
    try:
        state = json.loads(blob.decode('utf-8'))
        routes = state['routes']
        if not isinstance(routes, list):
            raise ValueError()
        totals = {}
        route_sets = {}
        for route in routes:
            bus = route['bus_id']
            stops = route['stops']
            if not isinstance(bus, str) or not bus or (not isinstance(stops, list)):
                raise ValueError()
            seen = set()
            for stop in stops:
                name = stop['name']
                minutes = stop['minutes']
                if not isinstance(name, str) or not name or isinstance(minutes, bool) or (not isinstance(minutes, (int, float))) or (minutes < 0):
                    raise ValueError()
                if minutes >= min_minutes:
                    totals[name] = totals.get(name, 0) + minutes
                    seen.add(name)
            for name in seen:
                route_sets.setdefault(name, set()).add(bus)
        items = [{'name': n, 'total_minutes': totals[n], 'route_count': len(route_sets[n]), 'average_minutes': round(totals[n] / len(route_sets[n]), 1)} for n in totals]
        items.sort(key=lambda x: (-x['total_minutes'], x['name']))
        return {'total': len(items), 'items': items[offset:offset + limit]}
    except (ValueError, KeyError, TypeError, UnicodeError, json.JSONDecodeError, ZeroDivisionError):
        raise ValueError('invalid state')

