STATUSES = {'accepted', 'in_transit', 'out_for_delivery', 'delivered', 'exception'}

def _time(value):
    if not isinstance(value, str) or not value.endswith('Z'):
        raise ValueError('invalid timestamp')
    try:
        parsed = datetime.fromisoformat(value[:-1] + '+00:00')
    except Exception as exc:
        raise ValueError('invalid timestamp') from exc
    if parsed.tzinfo != timezone.utc:
        raise ValueError('invalid timestamp')
    return parsed

def _state(blob):
    try:
        value = json.loads(blob.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid state') from exc
    if not isinstance(value, dict) or not isinstance(value.get('shipments'), dict):
        raise ValueError('invalid state')
    for key, shipment in value['shipments'].items():
        if not isinstance(key, str) or not isinstance(shipment, dict) or (not isinstance(shipment.get('events'), list)):
            raise ValueError('invalid state')
        for event in shipment['events']:
            if not isinstance(event, dict) or set(event) != {'timestamp', 'status', 'hub'}:
                raise ValueError('invalid state')
            _time(event['timestamp'])
            if event['status'] not in STATUSES or not isinstance(event['hub'], str):
                raise ValueError('invalid state')
    return value

def pack_state(state):
    if not isinstance(state, dict):
        raise ValueError('invalid state')
    try:
        _state(json.dumps(state).encode())
        return json.dumps(state, separators=(',', ':'), sort_keys=True).encode()
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError('invalid state') from exc

def append_event(blob, tracking_id, timestamp, status, hub):
    state = _state(blob)
