    hub = hub.strip() if isinstance(hub, str) else ''
    if not tracking_id or not hub or status not in STATUSES:
        raise ValueError('invalid event')
    parsed = _time(timestamp)
    normalized = parsed.isoformat(timespec='microseconds').replace('+00:00', 'Z')
    shipment = state['shipments'].setdefault(tracking_id, {'events': []})
    shipment['events'].append({'timestamp': normalized, 'status': status, 'hub': hub})
    shipment['events'].sort(key=lambda event: _time(event['timestamp']))
    return pack_state(state)

