from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def render_trade_confirmations(trades: list[dict], page: int=1, page_size: int=10) -> str:
    if not isinstance(page, int) or not isinstance(page_size, int):
        raise ValueError('page values must be integers')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid page values')
    required = ('trade_id', 'symbol', 'side', 'quantity', 'price', 'executed_at', 'status')
    prepared = []
    for trade in trades:
        for key in required:
            if key not in trade:
                raise KeyError(key)
        try:
            quantity = Decimal(str(trade['quantity']))
            price = Decimal(str(trade['price']))
        except (InvalidOperation, ValueError, TypeError):
            raise ValueError('invalid numeric value')
        if quantity < 0 or price < 0:
            raise ValueError('negative numeric value')
        prepared.append((trade, quantity, price))
    prepared.sort(key=lambda item: (str(item[0]['executed_at']), str(item[0]['trade_id'])), reverse=False)
    prepared.sort(key=lambda item: str(item[0]['executed_at']), reverse=True)
    start_index = (page - 1) * page_size
    visible = prepared[start_index:start_index + page_size]
    total = len(prepared)
    if visible:
        start = start_index + 1
        end = start_index + len(visible)
    else:
        start = end = 0
    rows = []
    displayed_total = Decimal('0')
    for trade, quantity, price in visible:
        notional = (quantity * price).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        displayed_total += notional
        values = [trade['trade_id'], trade['symbol'], trade['side'], trade['executed_at'], trade['status']]
        cells = [str(value) for value in values]
        cells.insert(2, format(quantity, 'f'))
        cells.insert(3, format(price, 'f'))
        cells.append(format(notional, '.2f'))
        rows.append('<tr>' + ''.join(('<td>' + cell + '</td>' for cell in cells)) + '</tr>')
    body = ''.join(rows)
    return f"""<div class="confirmation"><h1>Trade Confirmations</h1><p class="summary">Showing {start}-{end} of {total} trades</p><table><thead><tr><th>Trade ID</th><th>Symbol</th><th>Side</th><th>Quantity</th><th>Price</th><th>Executed At</th><th>Status</th><th>Notional</th></tr></thead><tbody>{body}</tbody><tfoot><tr><td colspan="7">Displayed total</td><td>{displayed_total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP):.2f}</td></tr></tfoot></table></div>"""

