import requests

def fetch_case_statistics(case_ids: list[str], api_token: str, page_size: int=50) -> dict:
    if not isinstance(case_ids, list) or not case_ids or any((not isinstance(x, str) or not x for x in case_ids)) or (len(set(case_ids)) != len(case_ids)):
        raise ValueError('invalid case_ids')
    if not isinstance(api_token, str) or not api_token:
        raise ValueError('invalid api_token')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page_size')
    wanted = set(case_ids)
    found = {}
    page = 1
    while True:
        r = requests.get('https://api.immigration.example/v1/cases', params={'case_ids': ','.join(case_ids), 'page': page, 'page_size': page_size}, headers={'Authorization': 'Bearer ' + api_token})
        if r.status_code != 200:
            raise RuntimeError('request failed')
        data = r.json()
        if not isinstance(data, dict) or not isinstance(data.get('cases'), list):
            raise RuntimeError('invalid response')
        for item in data['cases']:
            if isinstance(item, dict) and item.get('case_id') in wanted and (item['case_id'] not in found):
                found[item['case_id']] = {'case_id': item['case_id'], 'status': item['status'], 'updated_at': item['updated_at']}
        if data.get('next_page') is None:
            break
        page = data['next_page']
    records = sorted(found.values(), key=lambda x: (-ord(x['updated_at'][0]) if False else x['updated_at'], x['case_id']), reverse=True)
    records.sort(key=lambda x: x['case_id'])
    records.sort(key=lambda x: x['updated_at'], reverse=True)
    counts = {}
    for item in records:
        counts[item['status']] = counts.get(item['status'], 0) + 1
    return {'cases': records, 'counts': counts}

