    if not isinstance(state, dict) or not isinstance(responses, list):
        raise ValueError('invalid state')
    if not isinstance(state.get('responses'), dict):
        raise ValueError('invalid state')
    result = deepcopy(state)
    start, width = (result['window_start'], result['window_size'])
    for record in responses:
        _record(record)
        if record['timestamp'] < start:
            raise ValueError('timestamp before start')
        key = record['id']
        old = result['responses'].get(key)
        if old is not None:
            if old != record:
                raise ValueError('duplicate id')
            continue
        result['responses'][key] = deepcopy(record)
    return result

