import json
from datetime import date

def encode_state(records: list[dict]) -> bytes:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    for record in records:
        _validate_record(record)
    try:
        return json.dumps(records, separators=(',', ':')).encode('utf-8')
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid records') from exc

def _validate_record(record):
    if not isinstance(record, dict):
        raise ValueError('invalid record')
    if not isinstance(record.get('id'), str) or not record['id']:
        raise ValueError('invalid id')
    if isinstance(record.get('balance'), bool) or not isinstance(record.get('balance'), int) or record['balance'] < 0:
        raise ValueError('invalid balance')
    if not isinstance(record.get('active'), bool):
        raise ValueError('invalid active value')
    if not isinstance(record.get('expires'), str):
        raise ValueError('invalid expiry')
    try:
        date.fromisoformat(record['expires'])
    except ValueError as exc:
        raise ValueError('invalid expiry') from exc

def summarize_balances(payload: bytes, as_of: str, page: int=1, page_size: int=20) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    try:
        cutoff = date.fromisoformat(as_of)
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid date') from exc
    try:
        records = json.loads(payload.decode('utf-8'))
    except (AttributeError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(records, list):
        raise ValueError('invalid payload')
    for record in records:
        _validate_record(record)
    eligible = [r for r in records if r['active'] and date.fromisoformat(r['expires']) >= cutoff]
    eligible.sort(key=lambda r: (-r['balance'], r['id']))
    start = (page - 1) * page_size
    cards = [{'id': r['id'], 'balance': r['balance']} for r in eligible[start:start + page_size]]
