            raise ValueError('invalid record')
        if not isinstance(customer, str) or not isinstance(plan, str) or (not isinstance(status, str)) or isinstance(amount, bool) or (not isinstance(amount, int)) or (amount < 0):
            raise ValueError('invalid record')
        checked.append((customer, plan, status, amount))
    checked.sort(key=lambda x: (-x[3], x[0], x[1], x[2]))
    start = (page - 1) * page_size
    shown = checked[start:start + page_size]
    rows = []
    total = 0
    for customer, plan, status, amount in shown:
        total += amount
        rows.append('<tr><td>{}</td><td>{}</td><td>{}</td><td>${:.2f}</td></tr>'.format(html.escape(customer, quote=True), html.escape(plan, quote=True), html.escape(status, quote=True), amount / 100))
