import json
from datetime import date, timedelta

def encode_cycle(state: dict) -> bytes:
    try:
        return json.dumps(state, separators=(',', ':'), sort_keys=True).encode('utf-8')
    except (TypeError, ValueError, UnicodeError) as exc:
        raise ValueError('state cannot be encoded') from exc

def decode_cycle(blob: bytes) -> dict:
    try:
        value = json.loads(blob.decode('utf-8'))
    except (AttributeError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid cycle blob') from exc
    if not isinstance(value, dict):
        raise ValueError('cycle must be a dictionary')
    return value

def _day(text):
    try:
        return date.fromisoformat(text)
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid date') from exc

def build_review_report(state: dict, as_of: str, window_days: int=30) -> list[dict]:
    if not isinstance(window_days, int) or isinstance(window_days, bool) or window_days <= 0:
        raise ValueError('window_days must be positive')
    end = _day(as_of)
    start = end - timedelta(days=window_days - 1)
    grouped = {}
    for review in state.get('reviews', []):
        submitted = _day(review.get('submitted'))
        if review.get('status') != 'completed' or not start <= submitted <= end:
            continue
        employee = review.get('employee')
        item = grouped.setdefault(employee, {'reviews': 0, 'reviewers': set(), 'cats': {}})
        item['reviews'] += 1
        item['reviewers'].add(review.get('reviewer'))
        for category, score in review.get('scores', {}).items():
            if isinstance(score, bool) or not isinstance(score, (int, float)) or (not 0 <= score <= 5):
                raise ValueError('invalid score')
            item['cats'].setdefault(category, []).append(score)
    result = []
    for employee, item in grouped.items():
        values = [v for vals in item['cats'].values() for v in vals]
        categories = {k: round(sum(v) / len(v), 2) for k, v in sorted(item['cats'].items())}
        result.append({'employee': employee, 'review_count': item['reviews'], 'reviewers': sorted(item['reviewers']), 'categories': categories, 'overall_average': round(sum(values) / len(values), 2)})
    return sorted(result, key=lambda x: (-x['overall_average'], x['employee']))

