        if review.get('status') != 'completed' or not start <= submitted <= end:
            continue
        employee = review.get('employee')
        item = grouped.setdefault(employee, {'reviews': 0, 'reviewers': set(), 'cats': {}})
        item['reviews'] += 1
        item['reviewers'].add(review.get('reviewer'))
        for category, score in review.get('scores', {}).items():
            if isinstance(score, bool) or not isinstance(score, (int, float)) or (not 0 <= score <= 5):
                raise ValueError('invalid score')
            item['cats'].setdefault(category, []).append(score)
    result = []
    for employee, item in grouped.items():
        values = [v for vals in item['cats'].values() for v in vals]
        categories = {k: round(sum(v) / len(v), 2) for k, v in sorted(item['cats'].items())}
        result.append({'employee': employee, 'review_count': item['reviews'], 'reviewers': sorted(item['reviewers']), 'categories': categories, 'overall_average': round(sum(values) / len(values), 2)})
    return sorted(result, key=lambda x: (-x['overall_average'], x['employee']))

