import datetime
import requests

def _validate_range(card_id, start_date, end_date):
    if not card_id or not start_date or (not end_date):
        raise ValueError('empty argument')
    try:
        start = datetime.date.fromisoformat(start_date)
        end = datetime.date.fromisoformat(end_date)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if start.isoformat() != start_date or end.isoformat() != end_date or start > end:
        raise ValueError('invalid range')

def fetch_card_transactions(card_id: str, start_date: str, end_date: str) -> list[dict]:
    _validate_range(card_id, start_date, end_date)
    response = requests.get(f'https://api.metro.example/v1/cards/{card_id}/transactions', params={'from': start_date, 'to': end_date}, headers={'X-Card-ID': card_id})
    if response.status_code != 200:
        raise RuntimeError('request failed')
    try:
        data = response.json()
    except (ValueError, TypeError):
        raise RuntimeError('invalid response')
    if not isinstance(data, dict) or not isinstance(data.get('transactions'), list):
        raise ValueError('invalid response shape')
    return data['transactions']

def summarize_transactions(transactions: list[dict], daily_cap_cents: int=800) -> dict:
    if not isinstance(daily_cap_cents, int) or isinstance(daily_cap_cents, bool) or daily_cap_cents <= 0:
        raise ValueError('invalid cap')
    records = []
    for index, item in enumerate(transactions):
        if not isinstance(item, dict) or not all((k in item for k in ('timestamp', 'kind', 'amount_cents', 'route'))):
            raise ValueError('invalid transaction')
        try:
            stamp = datetime.datetime.fromisoformat(item['timestamp'])
        except (TypeError, ValueError):
            raise ValueError('invalid timestamp')
        amount = item['amount_cents']
        if not isinstance(amount, int) or isinstance(amount, bool) or amount < 0 or (item['kind'] not in ('tap', 'refund')):
            raise ValueError('invalid transaction')
        records.append((stamp, index, item))
    records.sort(key=lambda x: (x[0], x[1]))
    days = {}
    remaining = {}
    route_counts = {}
    for stamp, _, item in records:
        date = stamp.date().isoformat()
        if date not in days:
            days[date] = {'date': date, 'rides': 0, 'charged_cents': 0, 'refund_cents': 0, 'routes': {}}
            remaining[date] = daily_cap_cents
        if item['kind'] == 'tap':
            charge = min(item['amount_cents'], remaining[date])
            remaining[date] -= charge
            days[date]['rides'] += 1
            days[date]['charged_cents'] += charge
            route = item['route']
            days[date]['routes'][route] = days[date]['routes'].get(route, 0) + 1
            route_counts[route] = route_counts.get(route, 0) + 1
        else:
            days[date]['refund_cents'] += item['amount_cents']
    for day in days.values():
        day['routes'] = dict(sorted(day['routes'].items(), key=lambda x: (-x[1], x[0])))
    top = min(route_counts, key=lambda r: (-route_counts[r], r), default=None)
    total = sum((d['charged_cents'] - d['refund_cents'] for d in days.values()))
    return {'days': list(days.values()), 'total_cents': total, 'top_route': top}

def build_fare_report(card_id: str, start_date: str, end_date: str) -> dict:
    return summarize_transactions(fetch_card_transactions(card_id, start_date, end_date))

