from decimal import Decimal, InvalidOperation
from datetime import datetime, timezone
import requests

def fetch_donations(campaign_id: str, since: str | None=None) -> list[dict]:
    params = {'campaign_id': campaign_id}
    if since is not None:
        params['since'] = since
    response = requests.get(f'https://api.givewell.example/v1/campaigns/{campaign_id}/donations', params=params, headers={'Accept': 'application/json'})
    if response.status_code != 200:
        raise ValueError(f'unexpected status {response.status_code}')
    try:
        data = response.json()
    except Exception as exc:
        raise ValueError('invalid response') from exc
    if not isinstance(data, dict) or not isinstance(data.get('donations'), list):
        raise ValueError('invalid response')
    return data['donations']

def process_donations(records: list[dict]) -> dict:
    currencies = {}
    daily = {}
    seen = set()
    for record in records:
        if record.get('status') != 'completed':
            continue
        try:
            ident = record['id']
            if ident in seen:
                continue
            amount = Decimal(str(record['amount']))
            if not amount.is_finite() or amount < 0 or amount.as_tuple().exponent < -2:
                raise ValueError
            cents = int(amount * 100)
            currency = record['currency']
            donor = record['donor']
            stamp = str(record['created_at'])
            if stamp.endswith('Z'):
                stamp = stamp[:-1] + '+00:00'
            date = datetime.fromisoformat(stamp).astimezone(timezone.utc).date().isoformat()
        except (KeyError, TypeError, ValueError, InvalidOperation, OverflowError):
            raise ValueError('malformed completed donation')
        seen.add(ident)
        entry = currencies.setdefault(currency, {'cents': 0, 'donors': set()})
        entry['cents'] += cents
        entry['donors'].add(donor)
        day = daily.setdefault(date, {'cents': 0, 'count': 0})
        day['cents'] += cents
        day['count'] += 1
    return {'currency_totals': [{'currency': c, 'cents': currencies[c]['cents'], 'donors': len(currencies[c]['donors'])} for c in sorted(currencies)], 'daily_totals': [{'date': d, **daily[d]} for d in sorted(daily)]}

def donation_report(campaign_id: str, since: str | None=None) -> dict:
    return process_donations(fetch_donations(campaign_id, since))

