def fetch_genealogy_records(surname: str, page: int=1, page_size: int=10) -> dict:
    if not isinstance(surname, str) or not surname.strip():
        raise ValueError('surname must be non-empty')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    response = requests.get('https://api.example.org/genealogy/records', params={'surname': surname}, headers={'Accept': 'application/json'}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError('request failed')
    try:
        payload = response.json()
    except Exception as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(payload, dict) or not isinstance(payload.get('records'), list):
        raise ValueError('invalid payload')
    records = []
    for item in payload['records']:
        if not isinstance(item, dict):
            raise ValueError('invalid record')
        ident = item.get('id')
        name = item.get('name')
        year = item.get('birth_year')
        if isinstance(ident, bool) or not isinstance(ident, int) or (not isinstance(name, str)) or isinstance(year, bool) or (not isinstance(year, int)):
