import math
import requests

def get_forecasts(url: str, stores: list[str], days: int, token: str | None=None) -> dict:
    if not stores or days < 1 or any((not isinstance(x, str) for x in stores)):
        raise ValueError('invalid request')
    seen = set()
    ordered = []
    for store in stores:
        if store not in seen:
            seen.add(store)
            ordered.append(store)
    headers = {'Accept': 'application/json'}
    if token is not None:
        headers['Authorization'] = 'Bearer ' + token
    response = requests.get(url.rstrip('/') + '/forecast', params={'stores': ','.join(ordered), 'horizon': days}, headers=headers, timeout=10)
    if response.status_code != 200:
        raise ValueError('request failed with status ' + str(response.status_code))
    value = response.json()
    if not isinstance(value, dict):
        raise ValueError('response must be an object')
    return value

def build_demand_plan(data: dict, window: int=3, lead_time: int=2, safety_stock: int=0) -> list[dict]:
    if not isinstance(data, dict) or not isinstance(data.get('forecasts'), list):
        raise ValueError('invalid forecast data')
    if window < 1 or lead_time < 1 or safety_stock < 0:
        raise ValueError('invalid calculation options')
    result = []
    for item in data['forecasts']:
        if not isinstance(item, dict) or not isinstance(item.get('store_id'), str):
            raise ValueError('invalid store')
        inventory = item.get('inventory')
        demand = item.get('demand')
        if type(inventory) is not int or inventory < 0 or (not isinstance(demand, list)):
            raise ValueError('invalid store')
        rows = []
        dates = set()
        for row in demand:
            if not isinstance(row, dict) or not isinstance(row.get('date'), str) or type(row.get('units')) is not int or (row['units'] < 0) or (row['date'] in dates):
                raise ValueError('invalid demand')
            dates.add(row['date'])
            rows.append((row['date'], row['units']))
        rows.sort(key=lambda x: x[0])
        values = [x[1] for x in rows[-window:]]
        average_raw = sum(values) / len(values) if values else 0.0
        average = round(average_raw, 2)
        peak = max((x[1] for x in rows), default=0)
        recommended = math.ceil(max(0, average_raw * lead_time + safety_stock - inventory))
        result.append({'store_id': item['store_id'], 'average': average, 'peak': peak, 'recommended': recommended})
    result.sort(key=lambda x: (-x['recommended'], -x['peak'], x['store_id']))
    return result

