import requests

def fetch_shelters(api_url: str, region: str, token: str) -> list[dict]:
    response = requests.get(api_url, params={'region': region}, headers={'Authorization': 'Bearer ' + token}, timeout=10)
    response.raise_for_status()
    try:
        body = response.json()
    except Exception as exc:
        raise ValueError('invalid response') from exc
    if not isinstance(body, dict) or not isinstance(body.get('data'), dict) or (not isinstance(body['data'].get('shelters'), list)):
        raise ValueError('invalid response')
    result = []
    required = ['id', 'name', 'region', 'capacity', 'occupied', 'distance_km', 'services', 'updated_at']
    for item in body['data']['shelters']:
        if not isinstance(item, dict) or any((key not in item for key in required)):
            raise ValueError('invalid shelter')
        services = item['services']
        if not isinstance(services, list) or any((not isinstance(x, str) for x in services)):
            raise ValueError('invalid services')
        try:
            capacity = int(item['capacity'])
            occupied = int(item['occupied'])
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid capacity') from exc
        if capacity < 0 or occupied < 0 or occupied > capacity:
            raise ValueError('invalid occupancy')
        result.append({'id': item['id'], 'name': item['name'], 'region': item['region'], 'capacity': capacity, 'occupied': occupied, 'distance_km': item['distance_km'], 'services': sorted(set((x.lower() for x in services))), 'updated_at': item['updated_at']})
    return result

def capacity_by_region(shelters: list[dict]) -> dict[str, dict[str, int | float]]:
    totals = {}
    for shelter in shelters:
        region = shelter['region']
        if region not in totals:
            totals[region] = [0, 0]
        totals[region][0] += shelter['capacity']
        totals[region][1] += shelter['occupied']
    answer = {}
    for region in sorted(totals):
        capacity, occupied = totals[region]
        answer[region] = {'capacity': capacity, 'occupied': occupied, 'available': capacity - occupied, 'utilization': round(occupied / capacity, 3) if capacity else 0.0}
    return answer

def recommend_shelters(shelters: list[dict], required_services: list[str], limit: int=3) -> list[str]:
    if limit < 1 or any((not isinstance(x, str) for x in required_services)):
        raise ValueError('invalid arguments')
    needed = {x.lower() for x in required_services}
    eligible = [s for s in shelters if s['capacity'] - s['occupied'] > 0 and needed <= set(s['services'])]
    eligible.sort(key=lambda s: (-(s['capacity'] - s['occupied']), s['distance_km'], s['name'].casefold(), s['id']))
    return [s['id'] for s in eligible[:limit]]

