    except Exception as exc:
        raise RuntimeError(str(exc)) from exc
    if r.status_code != 200:
        raise RuntimeError(f'HTTP {r.status_code}: {r.text}')
    try:
        data = r.json()
    except Exception as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(data, dict) or not isinstance(data.get('results'), list):
        raise ValueError('invalid response')
    output = []
    for item in data['results']:
        required = ('contract_id', 'clause_id', 'title', 'text', 'score', 'matches')
        if not isinstance(item, dict) or any((k not in item for k in required)) or (not isinstance(item['text'], str)) or (not isinstance(item['matches'], list)):
            raise ValueError('invalid result')
        text = item['text']
        spans = []
        for match in item['matches']:
            if not isinstance(match, dict) or not isinstance(match.get('start'), int) or (not isinstance(match.get('end'), int)) or (match['start'] < 0) or (match['end'] < match['start']) or (match['end'] > len(text)):
                raise ValueError('invalid match range')
            spans.append((match['start'], match['end']))
        spans.sort()
        merged = []
        for start, end in spans:
            if merged and start <= merged[-1][1]:
                merged[-1] = (merged[-1][0], max(merged[-1][1], end))
            else:
                merged.append((start, end))
        snippets = []
        for start, end in merged:
            left, right = (max(0, start - 20), min(len(text), end + 20))
            excerpt = text[left:right].strip()
            if left > 0:
                excerpt = '...' + excerpt
            if right < len(text):
                excerpt += '...'
            snippets.append(excerpt)
        output.append({'contract_id': item['contract_id'], 'clause_id': item['clause_id'], 'title': item['title'], 'score': float(item['score']), 'snippets': snippets})
    output.sort(key=lambda x: (-x['score'], x['contract_id'], x['clause_id']))
    return output

def summarize_contracts(matches: list[dict]) -> list[dict]:
    groups = {}
    for item in matches:
        cid = item['contract_id']
        group = groups.setdefault(cid, {'contract_id': cid, 'count': 0, 'max_score': float('-inf'), 'clause_ids': set()})
        group['count'] += 1
        group['max_score'] = max(group['max_score'], float(item['score']))
        group['clause_ids'].add(item['clause_id'])
    return [{'contract_id': g['contract_id'], 'count': g['count'], 'max_score': float(g['max_score']), 'clause_ids': sorted(g['clause_ids'])} for g in sorted(groups.values(), key=lambda x: x['contract_id'])]

