        if not all((isinstance(item[k], str) for k in ('sensor_id', 'room', 'status'))):
            raise ValueError('invalid text')
        if any((isinstance(item[k], bool) or not isinstance(item[k], Real) or (not math.isfinite(item[k])) for k in ('temperature', 'humidity'))):
            raise ValueError('invalid number')
        if not 0 <= item['humidity'] <= 100:
            raise ValueError('invalid humidity')
        checked.append(item)
    checked.sort(key=lambda x: (x['room'], x['sensor_id']))
    start = (page - 1) * per_page
    selected = checked[start:start + per_page]
    count = len(selected)
    avg_temp = round(sum((x['temperature'] for x in selected)) / count, 1) if count else 0.0
