    for x in selected:
        rows.append('<tr><td>{}</td><td>{}</td><td>{:.1f}°C</td><td>{:.1f}%</td><td>{}</td></tr>'.format(html.escape(x['sensor_id'], quote=True), html.escape(x['room'], quote=True), x['temperature'], x['humidity'], html.escape(x['status'], quote=True)))
