import json
_REQUIRED = ('animal_id', 'species', 'vaccine', 'date', 'status')

def encode_records(records: list[dict]) -> bytes:
    return json.dumps(records, separators=(',', ':'), sort_keys=True).encode('utf-8')

def vaccination_summary(blob: bytes, species: str | None=None, page: int=1, page_size: int=10) -> list[dict]:
    if species is not None and (not isinstance(species, str)):
        raise ValueError('invalid species')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    try:
        records = json.loads(blob.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(records, list):
        raise ValueError('invalid records')
    groups = {}
    for record in records:
        if not isinstance(record, dict) or any((key not in record for key in _REQUIRED)):
            raise ValueError('invalid record')
        if any((not isinstance(record[key], str) for key in _REQUIRED)):
            raise ValueError('invalid record')
        if record['status'] != 'given' or (species is not None and record['species'] != species):
            continue
        vaccine = record['vaccine']
        group = groups.setdefault(vaccine, {'vaccine': vaccine, 'count': 0, 'animals': set(), 'latest_date': ''})
        group['count'] += 1
        group['animals'].add(record['animal_id'])
        group['latest_date'] = max(group['latest_date'], record['date'])
    result = []
    for group in groups.values():
        result.append({'vaccine': group['vaccine'], 'count': group['count'], 'animals': sorted(group['animals']), 'latest_date': group['latest_date']})
    result.sort(key=lambda item: (-item['count'], item['vaccine']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

