def encode_requests(requests: list[dict]) -> bytes:
    return json.dumps(requests, separators=(',', ':')).encode('utf-8')

def get_accommodation_report(blob: bytes, page: int=1, page_size: int=10, category: str | None=None) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    if category is not None and (not isinstance(category, str)):
        raise ValueError('invalid category')
    try:
        records = json.loads(blob.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(records, list):
        raise ValueError('invalid records')
    fields = {'id', 'category', 'status', 'hours', 'priority'}
    for record in records:
        if not isinstance(record, dict) or set(record) != fields:
            raise ValueError('invalid record')
