import copy
import requests

def fetch_asset_updates(asset_id: str, cursor: str | None=None, base_url: str='https://twin.example/api') -> dict:
    params = {} if cursor is None else {'cursor': cursor}
    kwargs = {'headers': {'Accept': 'application/json'}}
    if params:
        kwargs['params'] = params
    response = requests.get(base_url.rstrip('/') + '/assets/' + asset_id + '/updates', **kwargs)
    if response.status_code != 200:
        raise RuntimeError(f'update service returned HTTP {response.status_code}')
    value = response.json()
    if not isinstance(value, dict):
        raise ValueError('update response must be an object')
    result = copy.deepcopy(value)
    if 'updates' not in result:
        result['updates'] = []
    elif not isinstance(result['updates'], list):
        raise ValueError('updates must be a list')
    return result

def _parts(path, message):
    if not isinstance(path, str) or not path.startswith('/'):
        raise ValueError(message)
    parts = path[1:].split('/')
    out = []
    for part in parts:
        i = 0
        text = ''
        while i < len(part):
            if part[i] == '~':
                if i + 1 >= len(part) or part[i + 1] not in '01':
                    raise ValueError(message)
                text += '/' if part[i + 1] == '1' else '~'
                i += 2
            else:
                text += part[i]
                i += 1
        out.append(text)
    return out

def apply_asset_updates(state: dict, updates: list[dict]) -> dict:
    result = copy.deepcopy(state)
    applied, ignored, seen = ([], [], set())
    ordered = sorted(updates, key=lambda u: (u['ts'], u['sequence'], u['id']))
    for update in ordered:
        uid = update['id']
        if uid in seen:
            ignored.append({'id': uid, 'reason': 'duplicate'})
            continue
        seen.add(uid)
        try:
            parts = _parts(update['path'], 'invalid update path or operation')
            if not parts or not update['path'] or update['op'] not in ('set', 'add', 'remove'):
                raise ValueError
            parent = result
            for key in parts[:-1]:
                if isinstance(parent, dict) and key in parent:
                    parent = parent[key]
                elif isinstance(parent, list) and key.isdecimal() and (int(key) < len(parent)):
                    parent = parent[int(key)]
                else:
                    raise ValueError
            key = parts[-1]
            op = update['op']
            if isinstance(parent, dict):
                if op == 'remove' and key not in parent or (op == 'set' and key not in parent):
                    raise ValueError
                if op in ('set', 'add'):
                    parent[key] = copy.deepcopy(update['value'])
                else:
                    del parent[key]
            elif isinstance(parent, list):
                if op == 'add' and key == '-':
                    parent.append(copy.deepcopy(update['value']))
                elif key.isdecimal() and int(key) < len(parent):
                    index = int(key)
                    if op == 'add':
                        parent.insert(index, copy.deepcopy(update['value']))
                    elif op == 'set':
                        parent[index] = copy.deepcopy(update['value'])
                    else:
                        del parent[index]
                else:
                    raise ValueError
            else:
                raise ValueError
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid update path or operation')
        applied.append(uid)
    return {'state': result, 'applied': applied, 'ignored': ignored}

def summarize_updates(updates: list[dict]) -> dict:
    operations = {'add': 0, 'remove': 0, 'set': 0}
    fields = {}
    for update in updates:
        parts = _parts(update['path'], 'invalid update path')
        if update['op'] in operations:
            operations[update['op']] += 1
        field = parts[0]
        fields[field] = fields.get(field, 0) + 1
    return {'total': len(updates), 'operations': operations, 'fields': fields}

