def test_empty_state_is_fresh_and_exact():
    a = empty_state()
    b = empty_state()
    assert a == {'version': 1, 'samples': {}}
    assert a is not b
    a['samples']['x'] = {'tests': 1, 'last_result': 'pass', 'last_collected_at': 2}
    assert b == {'version': 1, 'samples': {}}

def test_state_round_trip_and_deterministic_encoding():
    state = {'version': 1, 'samples': {'B-2': {'tests': 3, 'last_result': None, 'last_collected_at': None}, 'A-1': {'tests': 1, 'last_result': 'pass', 'last_collected_at': 17}}}
    first = encode_state(state)
    second = encode_state({'version': 1, 'samples': {'A-1': state['samples']['A-1'], 'B-2': state['samples']['B-2']}})
    assert first == second
    assert decode_state(first) == state
    assert isinstance(first, bytes)

def test_processing_sorts_events_and_uses_sample_id_order():
    events = [{'sample_id': 'S2', 'test': 'cbc', 'result': 'pending', 'collected_at': 20, 'sequence': 2}, {'sample_id': 'S1', 'test': 'chem', 'result': 'fail', 'collected_at': 10, 'sequence': 4}, {'sample_id': 'S2', 'test': 'cbc', 'result': 'pass', 'collected_at': 20, 'sequence': 1}, {'sample_id': 'S1', 'test': 'chem', 'result': 'pass', 'collected_at': 10, 'sequence': 3}]
    rows, blob = process_batch(events, encode_state(empty_state()))
