        raise ValueError('invalid state')
    try:
        value = json.loads(blob.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid state') from exc
    if not isinstance(value, dict) or set(value) != {'contacts'} or (not isinstance(value['contacts'], dict)):
        raise ValueError('invalid state')
    for email, contact in value['contacts'].items():
        if not isinstance(email, str) or not email:
            raise ValueError('invalid state')
        _valid_contact(contact)
    return value

def encode_state(state: dict) -> bytes:
    if not isinstance(state, dict) or set(state) != {'contacts'} or (not isinstance(state['contacts'], dict)):
        raise ValueError('invalid state')
    for email, contact in state['contacts'].items():
        if not isinstance(email, str) or not email:
            raise ValueError('invalid state')
        _valid_contact(contact)
    return json.dumps(state, sort_keys=True, separators=(',', ':')).encode('utf-8')

def process_media(records: list[dict], state_blob: bytes | None=None) -> tuple[list[dict], bytes]:
    state = {'contacts': {}} if state_blob is None else decode_state(state_blob)
    contacts = state['contacts']
    for record in records:
        if not isinstance(record, dict) or not all((k in record for k in ('name', 'outlet', 'email', 'region', 'date'))):
            raise ValueError('invalid record')
        if any((not isinstance(record[k], str) for k in ('name', 'outlet', 'email', 'region', 'date'))):
            raise ValueError('invalid record')
        email = record['email'].strip().lower()
        count = record.get('mentions', 1)
        if not email or type(count) is not int or count <= 0:
            raise ValueError('invalid record')
        old = contacts.get(email)
        contacts[email] = {'name': record['name'], 'outlet': record['outlet'], 'region': record['region'], 'mentions': count + (old['mentions'] if old else 0), 'last_seen': max(record['date'], old['last_seen']) if old else record['date']}
    rows = [{'email': e, **c} for e, c in contacts.items()]
    rows.sort(key=lambda r: (-r['mentions'], -ord(r['last_seen'][0]) if r['last_seen'] else 0, r['outlet'].casefold(), r['email']))
    rows.sort(key=lambda r: (r['mentions'], r['last_seen'], r['outlet'].casefold(), r['email']), reverse=False)
    rows.sort(key=lambda r: (-r['mentions'], r['last_seen'], r['outlet'].casefold(), r['email']))
    rows.sort(key=lambda r: (-r['mentions'], r['last_seen']), reverse=True)
    rows.sort(key=lambda r: (-r['mentions'], -int(r['last_seen'].replace('-', '')), r['outlet'].casefold(), r['email']))
    return (rows, encode_state(state))

