import json
import math

def serialize_inventory(records: list[dict]) -> bytes:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    return json.dumps(records, separators=(',', ':')).encode('utf-8')

def plan_replenishment(blob: bytes, page: int=1, page_size: int=10) -> list[dict]:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    try:
        records = json.loads(blob.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid snapshot') from exc
    if not isinstance(records, list):
        raise ValueError('invalid snapshot')
    seen = set()
    result = []
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        try:
            sku = record['sku']
            on_hand = record['on_hand']
            daily_use = record['daily_use']
            lead_days = record['lead_days']
            pack_size = record['pack_size']
        except (KeyError, TypeError) as exc:
            raise ValueError('invalid record') from exc
        if not isinstance(sku, str) or not sku or sku in seen or isinstance(on_hand, bool) or (not isinstance(on_hand, (int, float))) or (on_hand < 0) or isinstance(daily_use, bool) or (not isinstance(daily_use, (int, float))) or (daily_use <= 0) or isinstance(lead_days, bool) or (not isinstance(lead_days, int)) or (lead_days < 0) or isinstance(pack_size, bool) or (not isinstance(pack_size, int)) or (pack_size <= 0):
            raise ValueError('invalid record')
        seen.add(sku)
        target = daily_use * (lead_days + 7)
        if on_hand < target:
            qty = math.ceil((target - on_hand) / pack_size) * pack_size
            result.append({'sku': sku, 'order_qty': qty, 'days_cover': round(on_hand / daily_use, 2), 'target_stock': target})
    result.sort(key=lambda item: (item['days_cover'], item['sku']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

