import requests

def get_available_appointments(base_url: str, clinic_id: str, day: str, min_duration: int=30) -> list[dict]:
    try:
        target_day = date.fromisoformat(day)
    except ValueError as exc:
        raise ValueError('invalid day') from exc
    if min_duration <= 0:
        raise ValueError('min_duration must be positive')
    response = requests.get(base_url.rstrip('/') + '/appointments', params={'clinic_id': clinic_id, 'day': day, 'status': 'available'}, headers={'Accept': 'application/json'}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError('appointment service returned an error')
    payload = response.json()
    if not isinstance(payload, dict) or not isinstance(payload.get('appointments'), list):
        raise ValueError('invalid appointment response')
    result = []
    for item in payload['appointments']:
        try:
            start = datetime.fromisoformat(item['starts_at'])
            end = datetime.fromisoformat(item['ends_at'])
        except (KeyError, TypeError, ValueError) as exc:
            raise ValueError('invalid appointment timestamp') from exc
        minutes = int((end - start).total_seconds() / 60)
        if minutes <= 0:
