import json

def _check_records(records):
    if not isinstance(records, list):
        raise ValueError('invalid records')
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        if set(record) != {'name', 'category', 'enabled', 'rollout', 'environments'}:
            raise ValueError('invalid record')
        if not isinstance(record['name'], str) or not isinstance(record['category'], str):
            raise ValueError('invalid record')
        if type(record['enabled']) is not bool:
            raise ValueError('invalid record')
        if type(record['rollout']) is not int or not 0 <= record['rollout'] <= 100:
            raise ValueError('invalid record')
        if not isinstance(record['environments'], list) or not all((isinstance(x, str) for x in record['environments'])):
            raise ValueError('invalid record')

def encode_flags(flags: list[dict]) -> bytes:
    _check_records(flags)
    return json.dumps(flags, separators=(',', ':')).encode('utf-8')

def summarize_flags(blob: bytes, environment: str, page: int=1, page_size: int=10) -> dict:
    if type(page) is not int or type(page_size) is not int or page <= 0 or (page_size <= 0):
        raise ValueError('invalid paging')
    try:
        records = json.loads(blob.decode('utf-8'))
        _check_records(records)
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    matches = sorted((r for r in records if r['enabled'] and environment in r['environments']), key=lambda r: r['name'])
    groups = {}
    for record in matches:
        groups.setdefault(record['category'], []).append(record['rollout'])
    by_category = {k: {'count': len(v), 'average_rollout': round(sum(v) / len(v), 2)} for k, v in sorted(groups.items())}
    start = (page - 1) * page_size
    selected = matches[start:start + page_size]
    flags = [{'name': r['name'], 'category': r['category'], 'rollout': r['rollout'], 'environments': r['environments']} for r in selected]
    return {'total': len(matches), 'page': page, 'page_size': page_size, 'flags': flags, 'by_category': by_category}

