import json
from datetime import date, timedelta

def encode_state(state: dict) -> bytes:
    return json.dumps(state, separators=(',', ':'), ensure_ascii=False).encode('utf-8')

def decode_state(blob: bytes) -> dict:
    try:
        value = json.loads(blob.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError, AttributeError):
        raise ValueError('invalid state')
    if not isinstance(value, dict):
        raise ValueError('invalid state')
    return value

def maintenance_report(blob: bytes, as_of: str) -> list[dict]:
    try:
        today = date.fromisoformat(as_of)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    data = decode_state(blob)
    try:
        vehicles = data['vehicles']
        output = []
        for vehicle in vehicles:
            vid = vehicle['id']
            current = vehicle['current_km']
            for service in vehicle['services']:
                last = date.fromisoformat(service['last_date'])
                due_date = last + timedelta(days=service['interval_days'])
                due_km = service['last_km'] + service['interval_km']
                date_due = today >= due_date
                km_due = current >= due_km
                if date_due or km_due:
                    trigger = 'both' if date_due and km_due else 'date' if date_due else 'odometer'
                    output.append({'vehicle': vid, 'kind': service['kind'], 'due_date': due_date.isoformat(), 'due_km': due_km, 'trigger': trigger})
    except (KeyError, TypeError, ValueError, OverflowError):
        raise ValueError('invalid state')
    output.sort(key=lambda x: (x['due_date'], x['due_km'], x['vehicle'], x['kind']))
    return output

