        fields.append(''.join(current))
        if len(fields) != 5:
            raise ValueError(f'invalid field count on line {number}')
        day, request, owner, status, evidence = fields
        if not day.isdecimal() or status not in {'open', 'pending', 'closed'} or (not request) or (not owner) or (not evidence):
            raise ValueError(f'invalid value on line {number}')
        result.append({'day': int(day), 'request': request, 'owner': owner, 'status': status, 'evidence': evidence})
