    if isinstance(window, bool) or not isinstance(window, int) or window <= 0:
        raise ValueError('window must be positive')
    groups = {}
    for record in records:
        groups.setdefault(record['request'], []).append(record)
    output = []
    for request, items in groups.items():
        latest = max(enumerate(items), key=lambda pair: (pair[1]['day'], pair[0]))[1]
        evidence = []
        for item in items:
            if item['evidence'] not in evidence:
