        cutoff = latest['day'] - window + 1
        output.append({'request': request, 'owner': latest['owner'], 'status': latest['status'], 'latest_day': latest['day'], 'event_count': len(items), 'recent_count': sum((item['day'] >= cutoff for item in items)), 'evidence': evidence})
    return sorted(output, key=lambda item: (-item['latest_day'], item['request']))

