    esc = lambda value: html.escape(str(value), quote=True)
    lines = ['<section class="audit-report">', f'<h1>{esc(title)}</h1>', '<table>', '<thead><tr><th>Request</th><th>Owner</th><th>Status</th><th>Latest day</th><th>Events</th><th>Recent</th><th>Evidence</th></tr></thead>', '<tbody>']
