        items = payload['episodes']
        if not isinstance(payload, dict) or not isinstance(items, list):
            raise ValueError
    except (ValueError, TypeError, KeyError):
        raise ValueError('invalid analytics response')
    result = []
    for item in items:
        try:
            day = item['day']
            episode_id = item['episode_id']
            downloads = item['downloads']
            listens = item['listens']
            rate = item['completion_rate']
            datetime.date.fromisoformat(day)
            if not isinstance(episode_id, str) or not episode_id or type(downloads) is not int or (type(listens) is not int) or (downloads < 0) or (listens < 0) or (not isinstance(rate, (int, float))) or (not 0 <= rate <= 1):
                raise ValueError
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid episode record')
        result.append({'episode_id': episode_id, 'day': day, 'downloads': int(downloads), 'listens': int(listens), 'completion_rate': float(rate)})
    return sorted(result, key=lambda x: (x['day'], x['episode_id']))

def summarize_episodes(records: list[dict], window_days: int=7) -> list[dict]:
    if type(window_days) is not int or window_days <= 0:
        raise ValueError('window_days must be positive')
    groups = {}
    for record in records:
        groups.setdefault(record['episode_id'], []).append(record)
    output = []
    for episode_id, rows in groups.items():
        downloads = sum((r['downloads'] for r in rows))
        listens = sum((r['listens'] for r in rows))
        rate = sum((r['completion_rate'] * r['listens'] for r in rows)) / listens if listens else 0.0
        best = min(rows, key=lambda r: (-r['downloads'], r['day']))
        by_day = {datetime.date.fromisoformat(r['day']): r['downloads'] for r in rows}
        peak = 0
        for start in by_day:
            peak = max(peak, sum((by_day.get(start + datetime.timedelta(days=i), 0) for i in range(window_days))))
        output.append({'episode_id': episode_id, 'total_downloads': downloads, 'total_listens': listens, 'completion_rate': round(rate, 6), 'best_day': best['day'], 'window_downloads': peak})
    return sorted(output, key=lambda x: (-x['total_downloads'], x['episode_id']))

def format_report(summary: list[dict]) -> str:
    if not summary:
        return ''
    lines = [f"{x['episode_id']}: downloads={x['total_downloads']}, listens={x['total_listens']}, completion={x['completion_rate']:.2f}, best_day={x['best_day']}, window={x['window_downloads']}" for x in summary]
    lines.append(f"TOTAL: downloads={sum((x['total_downloads'] for x in summary))}, listens={sum((x['total_listens'] for x in summary))}")
    return '\n'.join(lines)

