def fetch_preorders(api_url: str, customer_id: str, since: str | None=None) -> list[dict]:
    params = {'customer_id': customer_id}
    if since is not None:
        params['since'] = since
    response = requests.get(api_url, params=params, headers={'Accept': 'application/json'}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError(f'preorder request failed with status {response.status_code}')
    try:
        payload = response.json()
    except Exception as exc:
        raise ValueError('invalid response JSON') from exc
    if not isinstance(payload, dict) or not isinstance(payload.get('preorders'), list):
        raise ValueError('response must contain a preorder list')
    return payload['preorders']

def build_preorder_report(customer_id: str, records: list[dict]) -> dict:
    grouped = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid preorder')
        status = record.get('status')
        if status == 'cancelled':
            continue
        if status != 'active':
            raise ValueError('invalid status')
        sku = record.get('sku')
        title = record.get('title')
        price = record.get('price')
        quantity = record.get('quantity')
        expected = record.get('expected_date')
        if not isinstance(sku, str) or not sku or (not isinstance(title, str)) or (not title):
            raise ValueError('invalid book identity')
        if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity <= 0:
            raise ValueError('invalid quantity')
        try:
            parsed_date = date.fromisoformat(expected)
            money = Decimal(price)
        except (TypeError, ValueError, InvalidOperation) as exc:
            raise ValueError('invalid preorder values') from exc
        if parsed_date.isoformat() != expected or money < 0 or money.as_tuple().exponent < -2:
            raise ValueError('invalid preorder values')
        cents = int(money * 100)
        current = grouped.get(sku)
        if current is None:
            grouped[sku] = [title, cents, quantity, expected]
        else:
            if current[0] != title or current[1] != cents or current[3] != expected:
                raise ValueError('inconsistent preorder')
            current[2] += quantity
    items = [{'sku': sku, 'title': v[0], 'quantity': v[2], 'unit_price_cents': v[1], 'subtotal_cents': v[1] * v[2], 'expected_date': v[3]} for sku, v in grouped.items()]
    items.sort(key=lambda x: (x['expected_date'], x['title'], x['sku']))
    return {'customer_id': customer_id, 'items': items, 'total_cents': sum((x['subtotal_cents'] for x in items))}

def sync_preorder_report(api_url: str, customer_id: str, since: str | None=None) -> dict:
    return build_preorder_report(customer_id, fetch_preorders(api_url, customer_id, since))

