import csv
import io
import math
from datetime import date
from html import escape

def parse_sales(text: str) -> list[dict]:
    if not isinstance(text, str) or not text:
        raise ValueError('invalid input')
    try:
        reader = csv.reader(io.StringIO(text, newline=''))
        rows = list(reader)
    except csv.Error as exc:
        raise ValueError('invalid csv') from exc
    if rows and rows[-1] == []:
        rows.pop()
    if not rows or rows[0] != ['date', 'product', 'region', 'demand']:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if len(row) != 4 or any((x == '' for x in row)):
            raise ValueError('invalid row')
        try:
            date.fromisoformat(row[0])
            value = float(row[3])
        except (ValueError, TypeError):
            raise ValueError('invalid value')
        if not math.isfinite(value) or value < 0:
            raise ValueError('invalid demand')
        demand = int(value) if value.is_integer() else value
        result.append({'date': row[0], 'product': row[1], 'region': row[2], 'demand': demand})
    return result

def forecast_demand(records: list[dict], horizon: int) -> list[dict]:
    if isinstance(horizon, bool) or not isinstance(horizon, int) or (not 0 <= horizon <= 24):
        raise ValueError('invalid horizon')
    groups = {}
    for item in records:
        try:
            key = (item['product'], item['region'])
            day = date.fromisoformat(item['date'])
            demand = float(item['demand'])
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid record')
        if not math.isfinite(demand) or demand < 0:
            raise ValueError('invalid demand')
        groups.setdefault(key, []).append((day, item['date'], demand))
    answer = []
    for (product, region), values in sorted(groups.items()):
        values.sort()
        if len({x[0] for x in values}) != len(values):
            raise ValueError('duplicate date')
        selected = values[-3:]
        weights = list(range(4 - len(selected), 4))
        base = round(sum((v[2] * w for v, w in zip(selected, weights))) / sum(weights), 2)
        forecasts = [base for _ in range(horizon)]
        answer.append({'product': product, 'region': region, 'last_date': values[-1][1], 'forecasts': forecasts, 'total': round(sum(forecasts), 2)})
    return answer

def render_report(rows: list[dict]) -> str:
    head = '<section class="forecast"><h1>Demand forecast</h1><table><thead><tr><th>Product</th><th>Region</th><th>Last date</th><th>Forecasts</th><th>Total</th></tr></thead><tbody>'
    body = []
    for row in rows:
        try:
            values = [float(x) for x in row['forecasts']]
            total = float(row['total'])
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid report row')
        if not all((math.isfinite(x) for x in values)) or not math.isfinite(total):
            raise ValueError('invalid report row')
        forecasts = ','.join((f'{x:.2f}' for x in values))
        body.append(f"<tr><td>{escape(str(row['product']))}</td><td>{escape(str(row['region']))}</td><td>{escape(str(row['last_date']))}</td><td>{forecasts}</td><td>{total:.2f}</td></tr>")
    return head + ''.join(body) + '</tbody></table></section>'

