        return json.dumps(snapshot, separators=(',', ':'), sort_keys=True).encode('utf-8')
    except Exception as exc:
        raise ValueError('invalid snapshot') from exc

def summarize_snapshot(blob: bytes, min_pressure: float, page: int, page_size: int) -> dict:
    if isinstance(min_pressure, bool) or not isinstance(min_pressure, (int, float)) or (not math.isfinite(min_pressure)):
        raise ValueError('invalid pressure')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
