def _validate(records):
    if not isinstance(records, list):
        raise ValueError('invalid records')
    seen = set()
    for r in records:
        if not isinstance(r, dict) or set(r) != {'reservation_id', 'telescope', 'start', 'duration', 'observers'}:
            raise ValueError('invalid record')
        if not isinstance(r['reservation_id'], str) or not r['reservation_id'] or r['reservation_id'] in seen:
            raise ValueError('invalid reservation id')
        if not isinstance(r['telescope'], str) or not r['telescope']:
            raise ValueError('invalid telescope')
        if type(r['start']) is not int or type(r['duration']) is not int or r['duration'] <= 0:
            raise ValueError('invalid interval')
        if not isinstance(r['observers'], list) or any((not isinstance(x, str) or not x for x in r['observers'])):
            raise ValueError('invalid observers')
        seen.add(r['reservation_id'])

def create_reservation_blob(records: list[dict]) -> bytes:
    _validate(records)
    return json.dumps(records, separators=(',', ':')).encode('utf-8')

def summarize_reservations(blob: bytes, window_start: int, window_end: int, page: int, page_size: int) -> dict:
    if type(window_start) is not int or type(window_end) is not int or window_start >= window_end:
        raise ValueError('invalid window')
    if type(page) is not int or type(page_size) is not int or page <= 0 or (page_size <= 0):
        raise ValueError('invalid pagination')
    try:
        records = json.loads(blob.decode('utf-8'))
        _validate(records)
    except Exception as exc:
        if isinstance(exc, ValueError) and str(exc) in {'invalid window', 'invalid pagination'}:
            raise
        raise ValueError('invalid blob') from exc
    groups = {}
    count = 0
    for r in records:
        end = r['start'] + r['duration']
        if r['start'] < window_end and end > window_start:
            count += 1
            name = r['telescope']
            g = groups.setdefault(name, {'minutes': 0, 'reservations': 0, 'observers': set()})
            g['minutes'] += min(end, window_end) - max(r['start'], window_start)
            g['reservations'] += 1
            g['observers'].update(r['observers'])
    entries = [{'telescope': n, 'minutes': g['minutes'], 'reservations': g['reservations'], 'observers': sorted(g['observers'])} for n, g in groups.items()]
    entries.sort(key=lambda x: (-x['minutes'], x['telescope']))
    total_pages = (len(entries) + page_size - 1) // page_size
    first = (page - 1) * page_size
    return {'total_reservations': count, 'telescopes': entries[first:first + page_size], 'page': page, 'page_size': page_size, 'total_pages': total_pages}

