from html import escape

def parse_iso_date(value: str) -> date:
    if not isinstance(value, str) or len(value) != 10 or value[4] != '-' or (value[7] != '-'):
        raise ValueError('invalid date')
    try:
        year, month, day = (int(part) for part in value.split('-'))
        if len(value.split('-')) != 3:
            raise ValueError
        return date(year, month, day)
    except (ValueError, TypeError, OverflowError):
        raise ValueError('invalid date')

def render_onboarding_report(employees: list[dict], as_of: str) -> str:
    if not isinstance(employees, list):
        raise ValueError('employees must be a list')
    current = parse_iso_date(as_of)
    prepared = []
    for position, employee in enumerate(employees):
        if not isinstance(employee, dict) or not isinstance(employee.get('name'), str) or (not isinstance(employee.get('department'), str)) or (not isinstance(employee.get('tasks'), list)):
            raise ValueError('invalid employee')
        tasks = []
        for task in employee['tasks']:
            if not isinstance(task, dict) or not all((isinstance(task.get(key), str) for key in ('title', 'due', 'status'))):
                raise ValueError('invalid task')
            if task['status'] not in ('done', 'pending', 'in_progress'):
                raise ValueError('invalid status')
            due = parse_iso_date(task['due'])
            tasks.append((task['title'], due, task['status']))
        prepared.append((employee['name'], employee['department'], tasks, position))
    prepared.sort(key=lambda item: (item[1].casefold(), item[0].casefold(), item[3]))
    complete = sum((all((task[2] == 'done' for task in item[2])) for item in prepared))
    overdue = sum((any((task[2] != 'done' and task[1] < current for task in item[2])) for item in prepared))
    rows = []
    labels = {'done': 'Done', 'pending': 'Pending', 'in_progress': 'In progress'}
