from decimal import Decimal, InvalidOperation
from datetime import datetime
import requests

def _time(value):
    try:
        return datetime.fromisoformat(value[:-1] + '+00:00' if value.endswith('Z') else value)
    except (TypeError, ValueError):
        raise ValueError('invalid timestamp')

def fetch_settlements(base_url: str, value_date: str, participant: str, timeout: float=10.0) -> list[dict]:
    response = requests.get(base_url.rstrip('/') + '/v1/settlements', params={'date': value_date, 'participant': participant}, headers={'Accept': 'application/json'}, timeout=timeout, verify=True)
    if response.status_code != 200:
        raise RuntimeError('settlement service returned ' + str(response.status_code))
    try:
        payload = response.json()
        items = payload['settlements']
        if not isinstance(items, list):
            raise ValueError
    except (KeyError, TypeError, ValueError):
        raise ValueError('invalid settlement response')
    result = []
    for item in items:
        try:
            sid, cur, amount = (item['settlement_id'], item['currency'], item['amount'])
            status, stamp, legs = (item['status'], item['timestamp'], item['legs'])
            _time(stamp)
            if not isinstance(legs, list):
                raise ValueError
            normalized = []
            for leg in legs:
                normalized.append({'participant': str(leg['participant']), 'amount': Decimal(str(leg['amount']))})
            result.append({'settlement_id': str(sid), 'currency': str(cur), 'amount': Decimal(str(amount)), 'status': str(status), 'timestamp': str(stamp), 'legs': normalized})
        except (KeyError, TypeError, InvalidOperation, ValueError):
            raise ValueError('invalid settlement record')
