from datetime import datetime
from html import escape

def _fields(line):
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            if char in '|\\':
                current.append(char)
            else:
                current.extend(('\\', char))
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        current.append('\\')
    fields.append(''.join(current))
    return fields

def parse_logs(log_text: str) -> list[dict[str, str]]:
    result = []
    for number, raw in enumerate(log_text.splitlines(), 1):
        line = raw.strip()
        if not line:
            continue
        fields = _fields(line)
        if len(fields) != 5 or any((not value for value in fields)):
            raise ValueError(f'invalid line {number}')
        timestamp, guard, location, status, note = fields
        try:
            parsed = datetime.fromisoformat(timestamp)
        except ValueError as exc:
            raise ValueError(f'invalid line {number}') from exc
        if status not in ('CHECKED', 'ISSUE'):
            raise ValueError(f'invalid line {number}')
        result.append((parsed, number, {'timestamp': timestamp, 'guard': guard, 'location': location, 'status': status, 'note': note}))
    result.sort(key=lambda item: (item[0], item[2]['guard'], item[2]['location'], item[1]))
    return [item[2] for item in result]

def render_report(records: list[dict[str, str]]) -> str:
    checked = sum((record['status'] == 'CHECKED' for record in records))
    issues = sum((record['status'] == 'ISSUE' for record in records))
    rows = []
    for record in records:
        values = [escape(record[key]) for key in ('timestamp', 'guard', 'location', 'status', 'note')]
        rows.append('<tr>' + ''.join((f'<td>{value}</td>' for value in values)) + '</tr>')
    body = ''.join(rows)
    return f'<div class="patrol-report"><h1>Patrol Report</h1><p class="summary">{len(records)} entries; {checked} checked; {issues} issues</p><table><thead><tr><th>Time</th><th>Guard</th><th>Location</th><th>Status</th><th>Note</th></tr></thead><tbody>{body}</tbody></table></div>'

