import math

def dump_snapshot(snapshot: list[dict]) -> bytes:
    try:
        return json.dumps(snapshot, separators=(',', ':'), allow_nan=False).encode('utf-8')
    except (TypeError, ValueError, OverflowError) as exc:
        raise ValueError('snapshot cannot be encoded') from exc

def maintenance_report(blob: bytes, min_hours: float=0, page: int=1, page_size: int=10) -> dict:
    if isinstance(min_hours, bool) or not isinstance(min_hours, (int, float)) or (not math.isfinite(min_hours)) or (min_hours < 0):
        raise ValueError('invalid min_hours')
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('invalid page_size')
    try:
        records = json.loads(blob.decode('utf-8'))
    except (AttributeError, UnicodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid snapshot') from exc
    if not isinstance(records, list):
        raise ValueError('invalid snapshot')
    groups = {}
    included = 0
    total = 0.0
    for record in records:
        if not isinstance(record, dict) or not isinstance(record.get('machine'), str) or (not isinstance(record.get('tasks'), list)):
            raise ValueError('invalid record')
        hours = record.get('hours')
        if isinstance(hours, bool) or not isinstance(hours, (int, float)) or (not math.isfinite(hours)) or (hours < 0):
            raise ValueError('invalid record')
        if any((not isinstance(task, str) for task in record['tasks'])):
            raise ValueError('invalid record')
        if hours >= min_hours:
            included += 1
            total += hours
            item = groups.setdefault(record['machine'], [0.0, 0])
            item[0] += hours
            item[1] += len(record['tasks'])
    ordered = sorted(groups.items(), key=lambda pair: (-pair[1][0], pair[0]))
    pages = (len(ordered) + page_size - 1) // page_size
    start = (page - 1) * page_size
    machines = [{'name': name, 'hours': round(values[0], 2), 'tasks': values[1]} for name, values in ordered[start:start + page_size]]
    return {'total_records': included, 'total_hours': round(total, 2), 'machines': machines, 'page': page, 'pages': pages}

