import math
from datetime import datetime, timezone
import requests

def fetch_tracking_data(collar_ids: list[str], start: str, end: str, token: str) -> dict:
    response = requests.get('https://tracking.example.org/v1/readings', params={'collars': ','.join(collar_ids), 'start': start, 'end': end}, headers={'Authorization': 'Bearer ' + token})
    if response.status_code != 200:
        raise ValueError(f'tracking service returned status {response.status_code}')
    return response.json()

def parse_tracking_payload(payload: dict) -> list[dict]:
    try:
        collars = payload['collars']
        if not isinstance(collars, list):
            raise ValueError
        result = []
        for collar in collars:
            ident = collar['id']
            for item in collar['readings']:
                stamp = item['timestamp']
                if stamp.endswith('Z'):
                    stamp = stamp[:-1] + '+00:00'
                when = datetime.fromisoformat(stamp)
                if when.tzinfo is None:
                    raise ValueError
                result.append({'collar_id': ident, 'timestamp': when.astimezone(timezone.utc), 'latitude': item['latitude'], 'longitude': item['longitude'], 'temperature': item['temperature'], 'speed': item.get('speed')})
        return sorted(result, key=lambda x: (x['timestamp'], x['collar_id']))
    except (KeyError, TypeError, ValueError, AttributeError):
        raise ValueError('invalid tracking payload')

def summarize_tracking(readings: list[dict], window_minutes: int=60) -> list[dict]:
    if window_minutes <= 0:
        raise ValueError('window_minutes must be positive')
    groups = {}
    previous = {}
    step = window_minutes * 60
    for item in sorted(readings, key=lambda x: (x['collar_id'], x['timestamp'])):
        epoch = item['timestamp'].timestamp()
        key = (item['collar_id'], int(epoch // step))
        entry = groups.setdefault(key, {'temps': [], 'speeds': [], 'distance': 0.0, 'count': 0})
        entry['temps'].append(item['temperature'])
        if item['speed'] is not None:
            entry['speeds'].append(item['speed'])
        entry['count'] += 1
        old = previous.get(item['collar_id'])
        if old is not None and old['timestamp'] != item['timestamp']:
