def collect_monthly_waste(postal_codes: list[str], month: str, api_key: str) -> list[dict]:
    if not isinstance(month, str) or re.fullmatch('\\d{4}-(0[1-9]|1[0-2])', month) is None:
        raise ValueError('invalid month')
    if not isinstance(postal_codes, list) or not postal_codes:
        raise ValueError('postal_codes must not be empty')
    unique = []
    for code in postal_codes:
        if not isinstance(code, str) or re.fullmatch('\\d{5}', code) is None:
            raise ValueError('invalid postal code')
        if code not in unique:
            unique.append(code)
    totals = []
    for code in unique:
        page = 1
        weight = 0.0
        pickups = 0
        while True:
            response = requests.get('https://api.citywaste.example/v1/pickups', params={'postal_code': code, 'month': month, 'page': page}, headers={'Authorization': 'Bearer ' + api_key})
            if response.status_code != 200:
                raise RuntimeError('waste service returned an error')
            payload = response.json()
            for record in payload['results']:
                if record.get('status') == 'completed' and str(record.get('pickup_date', '')).startswith(month):
                    weight += float(record['weight_kg'])
                    pickups += 1
            if not payload['next']:
                break
            page += 1
        totals.append({'postal_code': code, 'pickups': pickups, 'weight_kg': round(weight, 2)})
    totals.sort(key=lambda item: (-item['weight_kg'], item['postal_code']))
    return totals

