def render_patch_report(records: list[dict[str, object]], page: int=1, per_page: int=20) -> str:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(per_page, bool) or not isinstance(per_page, int) or per_page <= 0:
        raise ValueError('invalid per_page')
    checked = []
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        if set(record) != {'hostname', 'os', 'missing', 'last_seen'}:
            raise ValueError('invalid record')
        hostname = record['hostname']
        operating_system = record['os']
        missing = record['missing']
        last_seen = record['last_seen']
        if not isinstance(hostname, str) or not isinstance(operating_system, str) or (not isinstance(last_seen, str)):
            raise ValueError('invalid record')
        if isinstance(missing, bool) or not isinstance(missing, int) or missing < 0:
            raise ValueError('invalid record')
        checked.append((hostname, operating_system, missing, last_seen))
    checked.sort(key=lambda item: (-item[2], item[0]))
    total_pages = max(1, math.ceil(len(checked) / per_page))
    if page > total_pages:
        raise ValueError('page out of range')
    start = (page - 1) * per_page
    rows = ''.join((f'<tr><td>{html.escape(hostname)}</td><td>{html.escape(operating_system)}</td><td>{missing}</td><td>{html.escape(last_seen)}</td></tr>' for hostname, operating_system, missing, last_seen in checked[start:start + per_page]))
    total_missing = sum((item[2] for item in checked))
    compliant = sum((item[2] == 0 for item in checked))
    return f'<section class="patch-report"><h1>Patch compliance</h1><p class="summary">Devices: {len(checked)} | Missing patches: {total_missing} | Compliant: {compliant}</p><table><thead><tr><th>Hostname</th><th>OS</th><th>Missing</th><th>Last seen</th></tr></thead><tbody>{rows}</tbody></table><p class="page">Page {page} of {total_pages}</p></section>'

