from solution import encode_catalog, decode_catalog, merge_catalogs
import pytest


def test_round_trip_plain_and_plural_messages():
    messages = {
        "hello": "Hello",
        "item": {"one": "item", "other": "items"},
    }
    blob = encode_catalog("en", messages, 3)
    assert isinstance(blob, bytes)
    assert decode_catalog(blob) == {
        "locale": "en",
        "revision": 3,
        "messages": messages,
    }


def test_round_trip_empty_messages_is_allowed():
    blob = encode_catalog("fr", {}, 0)
    assert decode_catalog(blob) == {"locale": "fr", "revision": 0, "messages": {}}


def test_merge_revision_tie_and_sorted_keys():
    first = encode_catalog("en", {"z": "old", "a": "A", "same": "first"}, 2)
    second = encode_catalog("en", {"z": "new", "same": "second", "b": "B"}, 2)
    result = merge_catalogs([first, second], "en")
    assert result == {"a": "A", "b": "B", "same": "second", "z": "new"}
    assert list(result) == ["a", "b", "same", "z"]


def test_merge_prefers_higher_revision_even_when_earlier():
    low = encode_catalog("en", {"greet": "low", "only-low": "x"}, 1)
    high = encode_catalog("en", {"greet": "high"}, 8)
    assert merge_catalogs([high, low], "en") == {"greet": "high", "only-low": "x"}


def test_plural_category_fallbacks():
    blob = encode_catalog("ru", {
        "exact": {"one": "one", "other": "many"},
        "other": {"other": "fallback"},
        "lexical": {"zero": "zero", "few": "few"},
    })
    assert merge_catalogs([blob], "ru", "one") == {
        "exact": "one", "lexical": "few", "other": "fallback"
    }
    assert merge_catalogs([blob], "ru", "missing") == {
        "exact": "many", "lexical": "few", "other": "fallback"
    }


def test_other_locales_are_ignored_but_empty_result_errors():
    blob = encode_catalog("de", {"x": "X"})
    assert merge_catalogs([blob, encode_catalog("en", {"y": "Y"})], "en") == {"y": "Y"}
    with pytest.raises(ValueError):
        merge_catalogs([blob], "en")


def test_invalid_arguments_and_catalog_shapes():
    with pytest.raises(ValueError):
        encode_catalog("", {"x": "X"})
    with pytest.raises(ValueError):
        encode_catalog("en", {"": "X"})
    with pytest.raises(ValueError):
        encode_catalog("en", {"x": {}}, True)
    with pytest.raises(ValueError):
        encode_catalog("en", {"x": {"one": 4}})
    with pytest.raises(ValueError):
        decode_catalog(b"not a catalog")
    with pytest.raises(ValueError):
        merge_catalogs([], "en")


def test_decode_rejects_non_bytes_and_merge_rejects_bad_locale():
    with pytest.raises(ValueError):
        decode_catalog("text")
    with pytest.raises(ValueError):
        merge_catalogs([encode_catalog("en", {"x": "X"})], "")
    with pytest.raises(ValueError):
        merge_catalogs([encode_catalog("en", {"x": "X"})], "en", "")

