import json

def _check(locale, messages, revision):
    if not isinstance(locale, str) or not locale:
        raise ValueError('invalid locale')
    if not isinstance(revision, int) or isinstance(revision, bool) or revision < 0:
        raise ValueError('invalid revision')
    if not isinstance(messages, dict):
        raise ValueError('invalid messages')
    for key, value in messages.items():
        if not isinstance(key, str) or not key:
            raise ValueError('invalid message key')
        if isinstance(value, str):
            continue
        if not isinstance(value, dict) or not value:
            raise ValueError('invalid message')
        for category, text in value.items():
            if not isinstance(category, str) or not category or (not isinstance(text, str)):
                raise ValueError('invalid plural message')

def encode_catalog(locale: str, messages: dict[str, str | dict[str, str]], revision: int=0) -> bytes:
    _check(locale, messages, revision)
    return json.dumps({'locale': locale, 'revision': revision, 'messages': messages}, separators=(',', ':'), sort_keys=True).encode()

def decode_catalog(blob: bytes) -> dict[str, object]:
    if not isinstance(blob, bytes):
        raise ValueError('blob must be bytes')
    try:
        data = json.loads(blob.decode('utf-8'))
        if not isinstance(data, dict) or set(data) != {'locale', 'revision', 'messages'}:
            raise ValueError('invalid catalog')
        _check(data['locale'], data['messages'], data['revision'])
        return data
    except (ValueError, UnicodeError, json.JSONDecodeError, TypeError) as exc:
        raise ValueError('invalid catalog') from exc

def merge_catalogs(blobs: list[bytes], locale: str, category: str='other') -> dict[str, str]:
    if not isinstance(locale, str) or not locale or (not isinstance(category, str)) or (not category):
        raise ValueError('invalid selector')
    chosen = {}
    for index, blob in enumerate(blobs):
        catalog = decode_catalog(blob)
        if catalog['locale'] != locale:
            continue
        for key, value in catalog['messages'].items():
            marker = (catalog['revision'], index)
            if key not in chosen or marker >= chosen[key][0]:
                chosen[key] = (marker, value)
    if not chosen:
        raise ValueError('no messages')
    result = {}
    for key in sorted(chosen):
        value = chosen[key][1]
        if isinstance(value, str):
            result[key] = value
        elif category in value:
            result[key] = value[category]
        elif 'other' in value:
            result[key] = value['other']
        else:
            result[key] = value[sorted(value)[0]]
    return result

