from collections import defaultdict
import requests

def reservation_summary(start_date: str, end_date: str, api_key: str, telescope: str | None=None) -> list[dict]:
    try:
        start = date.fromisoformat(start_date)
        end = date.fromisoformat(end_date)
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid date') from exc
    if start > end:
        raise ValueError('date range is reversed')
    params = {'start': start_date, 'end': end_date}
    if telescope is not None:
        params['telescope'] = telescope
    response = requests.get('https://observatory.example/api/reservations', params=params, headers={'X-API-Key': api_key}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError('reservation service returned an error')
    data = response.json()
    if not isinstance(data, dict) or not isinstance(data.get('reservations'), list):
        raise ValueError('invalid response')
    totals = defaultdict(lambda: [0, 0.0])
    for item in data['reservations']:
        item_date = date.fromisoformat(item['date'])
        if start <= item_date <= end and item['status'] == 'confirmed' and (telescope is None or item['telescope'] == telescope):
            name = item['telescope']
            totals[name][0] += 1
            totals[name][1] += item['hours']
    result = [{'telescope': name, 'reservations': values[0], 'hours': round(values[1], 2)} for name, values in totals.items()]
    return sorted(result, key=lambda item: (-item['hours'], item['telescope']))

