from datetime import datetime, timezone
import math
import requests

def fetch_readings(device_id: str, start: str, end: str, api_key: str) -> list[dict]:
    url = f'https://api.thermostat.example/v1/devices/{device_id}/readings'
    response = requests.get(url, params={'start': start, 'end': end}, headers={'Authorization': f'Bearer {api_key}'})
    if response.status_code != 200:
        raise RuntimeError(f'request failed with status {response.status_code}')
    data = response.json()
    if not isinstance(data, dict) or not isinstance(data.get('readings'), list):
        raise ValueError('invalid response shape')
    return data['readings']

def aggregate_readings(readings: list[dict], window_minutes: int=60) -> list[dict]:
    if isinstance(window_minutes, bool) or not isinstance(window_minutes, int) or window_minutes <= 0:
        raise ValueError('window_minutes must be positive')
    groups = {}
    width = window_minutes * 60
    for reading in readings:
        if not isinstance(reading, dict) or not all((k in reading for k in ('timestamp', 'temperature', 'humidity', 'mode'))):
            raise ValueError('malformed reading')
        try:
            stamp = reading['timestamp']
            if not isinstance(stamp, str) or not stamp.endswith('Z'):
                raise ValueError
            moment = datetime.fromisoformat(stamp[:-1] + '+00:00')
            if moment.tzinfo is None:
                raise ValueError
            moment = moment.astimezone(timezone.utc)
            temperature = float(reading['temperature'])
            humidity = float(reading['humidity'])
            if not math.isfinite(temperature) or not math.isfinite(humidity):
                raise ValueError
        except (TypeError, ValueError, OverflowError):
            raise ValueError('invalid reading')
        bucket = int(moment.timestamp()) // width * width
        groups.setdefault(bucket, []).append((temperature, humidity, reading['mode']))
    output = []
    for bucket in sorted(groups):
        values = groups[bucket]
        temperatures = [v[0] for v in values]
        humidities = [v[1] for v in values]
        modes = {}
        for value in values:
            modes[value[2]] = modes.get(value[2], 0) + 1
        start = datetime.fromtimestamp(bucket, timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')
        output.append({'window_start': start, 'average_temperature': round(sum(temperatures) / len(values), 2), 'minimum_temperature': min(temperatures), 'maximum_temperature': max(temperatures), 'average_humidity': round(sum(humidities) / len(values), 2), 'mode_counts': {k: modes[k] for k in sorted(modes)}})
    return output

def thermostat_report(device_id: str, start: str, end: str, api_key: str, window_minutes: int=60) -> list[dict]:
    return aggregate_readings(fetch_readings(device_id, start, end, api_key), window_minutes)

