import json

def _validate(entries):
    if not isinstance(entries, list):
        raise ValueError('entries')
    for entry in entries:
        if not isinstance(entry, dict):
            raise ValueError('entry')
        if set(entry) != {'station', 'title', 'start', 'duration', 'listeners'}:
            raise ValueError('entry fields')
        if not isinstance(entry['station'], str) or not entry['station']:
            raise ValueError('station')
        if not isinstance(entry['title'], str) or not entry['title']:
            raise ValueError('title')
        if type(entry['start']) is not int or not 0 <= entry['start'] < 1440:
            raise ValueError('start')
        if type(entry['duration']) is not int or entry['duration'] <= 0 or entry['start'] + entry['duration'] > 1440:
            raise ValueError('duration')
        if type(entry['listeners']) is not int or entry['listeners'] < 0:
            raise ValueError('listeners')

def build_playlist_blob(entries: list[dict]) -> bytes:
    _validate(entries)
    return json.dumps(entries, separators=(',', ':'), sort_keys=True).encode('utf-8')

def playlist_page(blob: bytes, window_start: int, window_end: int, page: int, page_size: int) -> dict:
    if type(window_start) is not int or type(window_end) is not int or (not 0 <= window_start < window_end <= 1440):
        raise ValueError('window')
    if type(page) is not int or page < 1 or type(page_size) is not int or (not 1 <= page_size <= 100):
        raise ValueError('pagination')
    try:
        entries = json.loads(blob.decode('utf-8'))
        _validate(entries)
    except Exception as exc:
        raise ValueError('payload') from exc
    selected = [e for e in entries if window_start <= e['start'] < window_end]
    selected.sort(key=lambda e: (e['start'], e['station'], e['title']))
    groups = {}
    for e in selected:
        g = groups.setdefault(e['station'], [0, 0, 0])
        g[0] += 1
        g[1] += e['duration']
        g[2] += e['listeners']
    start = (page - 1) * page_size
    items = [dict(e, end=e['start'] + e['duration']) for e in selected[start:start + page_size]]
    return {'total': len(selected), 'pages': (len(selected) + page_size - 1) // page_size, 'items': items, 'by_station': {k: {'plays': v[0], 'minutes': v[1], 'average_listeners': round(v[2] / v[0], 2)} for k, v in sorted(groups.items())}}

