def fetch_filing_index(case_id: str, base_url: str, *, page_size: int=50) -> list[dict]:
    if not isinstance(case_id, str) or not case_id.strip():
        raise ValueError('invalid case_id')
    if not isinstance(base_url, str) or not base_url.strip():
        raise ValueError('invalid base_url')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page_size')
    found = {}
    page = 1
    while True:
        result = requests.get(base_url.rstrip('/') + '/filings', params={'case_id': case_id, 'page': page, 'page_size': page_size}, headers={'Accept': 'application/json'})
        if result.status_code != 200:
            raise RuntimeError('filing request failed')
        payload = result.json()
        for item in payload.get('filings', []):
            if not isinstance(item, dict):
                continue
            docket = item.get('docket_number')
            title = item.get('title')
            raw_date = item.get('filed_at')
            if not isinstance(docket, str) or not docket:
                continue
            if not isinstance(title, str) or not title:
                continue
            if item.get('status') != 'accepted' or item.get('document_type') != 'filing':
                continue
            try:
                moment = datetime.fromisoformat(raw_date.replace('Z', '+00:00'))
                fee = Decimal(str(item.get('fee')))
                if fee < 0 or not fee.is_finite():
                    continue
                cents = int((fee * 100).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
            except (AttributeError, TypeError, ValueError, InvalidOperation):
                continue
            if docket not in found or moment > found[docket][0]:
                found[docket] = (moment, {'docket_number': docket, 'title': title, 'filed_date': moment.date().isoformat(), 'fee_cents': cents})
        if not payload.get('next_page', False):
            break
        page += 1
    return [value[1] for value in sorted(found.values(), key=lambda pair: (-pair[0].timestamp(), pair[1]['docket_number']))]

