            if not isinstance(item, dict) or not isinstance(item.get('member_id'), str) or (not item['member_id']) or (not isinstance(item.get('effective_date'), str)) or (not isinstance(item.get('revision'), int)) or isinstance(item.get('revision'), bool) or (not isinstance(item.get('beneficiaries'), list)):
                raise ValueError('invalid record')
            total = 0
            beneficiaries = []
            for b in item['beneficiaries']:
                if not isinstance(b, dict) or not isinstance(b.get('name'), str) or (not b['name']) or (not isinstance(b.get('relationship'), str)) or (not b['relationship']) or (not isinstance(b.get('percentage'), (int, float))) or isinstance(b['percentage'], bool) or (b['percentage'] <= 0):
