            current = (result[key]['effective_date'], result[key]['revision'])
            if version == current:
                raise ValueError('duplicate version')
            if version < current:
                continue
        result[key] = {'member_id': key, 'effective_date': item['effective_date'], 'revision': item['revision'], 'beneficiaries': copy.deepcopy(item['beneficiaries'])}
    return result

