    try:
        if datetime.strptime(day, '%Y-%m-%d').strftime('%Y-%m-%d') != day:
            raise ValueError
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    response = requests.get('https://api.childcare.example/v1/attendance', params={'date': day}, headers={'Authorization': 'Bearer ' + token}, timeout=10)
    response.raise_for_status()
    body = response.json()
    if not isinstance(body, dict) or not isinstance(body.get('attendance'), list):
        raise ValueError('invalid response')
    for item in body['attendance']:
        if not isinstance(item, dict) or not all((k in item for k in ('child_id', 'child_name', 'events'))) or (not isinstance(item['events'], list)):
            raise ValueError('invalid response')
    return body['attendance']

def summarize_attendance(records: list[dict], opening_time: str='07:00', closing_time: str='19:00') -> dict:
    opening, closing = (_clock(opening_time), _clock(closing_time))
    if opening >= closing:
        raise ValueError('invalid window')
    children = []
    for record in records:
        if not isinstance(record, dict) or not isinstance(record.get('events'), list):
            raise ValueError('invalid record')
        parsed = []
        for index, event in enumerate(record['events']):
            if not isinstance(event, dict) or event.get('type') not in ('in', 'out'):
                raise ValueError('invalid event')
            parsed.append((_clock(event.get('time')), index, event['type']))
        active = None
        minutes = visits = anomalies = 0
        for when, _, kind in sorted(parsed, key=lambda x: (x[0], x[1])):
            if kind == 'in':
                if active is not None:
                    anomalies += 1
                else:
                    active = when
            elif active is None:
                anomalies += 1
            else:
                amount = max(0, min(when, closing) - max(active, opening))
                if amount:
                    visits += 1
                    minutes += amount
                active = None
        if active is not None:
            anomalies += 1
        children.append({'child_id': record['child_id'], 'child_name': record['child_name'], 'minutes': minutes, 'visits': visits, 'anomalies': anomalies})
    children.sort(key=lambda x: (x['child_name'].casefold(), x['child_id']))
