def fetch_tournament(slug: str, api_key: str | None=None) -> dict:
    url = 'https://api.esports.example/v1/tournaments/' + quote(slug, safe='') + '/bracket'
    headers = {'Accept': 'application/json'}
    if api_key is not None:
        headers['Authorization'] = 'Bearer ' + api_key
    response = requests.get(url, headers=headers, timeout=10)
    if response.status_code != 200:
        raise ValueError(f'tournament request failed: {response.status_code}')
    return response.json()

def normalize_bracket(payload: dict) -> list[dict]:
    if 'matches' not in payload:
        raise ValueError('missing matches')
    if not isinstance(payload['matches'], list):
        raise ValueError('matches must be a list')
    result = []
    for match in payload['matches']:
        result.append({'round': match['round'], 'slot': match['slot'], 'team1': str(match['team1']).strip(), 'team2': str(match['team2']).strip(), 'score1': int(match['score1']), 'score2': int(match['score2'])})
    return sorted(result, key=lambda item: (item['round'], item['slot']))

def compute_standings(matches: list[dict]) -> list[dict]:
    stats = {}
