import json

def _validate_events(events):
    if not isinstance(events, list):
        raise ValueError('events must be a list')
    allowed = {'delivered', 'bounced', 'deferred'}
    for event in events:
        if not isinstance(event, dict):
            raise ValueError('invalid event')
        domain = event.get('domain')
        status = event.get('status')
        if not isinstance(domain, str) or not domain or (not isinstance(status, str)) or (status not in allowed):
            raise ValueError('invalid event')

def encode_events(events: list[dict]) -> bytes:
    _validate_events(events)
    return json.dumps(events, separators=(',', ':')).encode('utf-8')

def delivery_report(payload: bytes, page: int=1, page_size: int=10) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    if not isinstance(payload, bytes):
        raise ValueError('invalid payload')
    try:
        events = json.loads(payload.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    _validate_events(events)
    grouped = {}
    for event in events:
        domain = event['domain'].lower()
        if domain not in grouped:
            grouped[domain] = {'domain': domain, 'delivered': 0, 'bounced': 0, 'deferred': 0}
        grouped[domain][event['status']] += 1
    rows = list(grouped.values())
    for row in rows:
        total = row['delivered'] + row['bounced'] + row['deferred']
        row['delivery_rate'] = round(row['delivered'] * 100 / total, 2)
    rows.sort(key=lambda row: (-row['delivery_rate'], row['domain']))
    start = (page - 1) * page_size
    return {'total_domains': len(rows), 'domains': rows[start:start + page_size]}

