def fetch_rates(base, symbols, endpoint='https://api.example.test/latest'):
    if not isinstance(base, str) or not base or (not isinstance(symbols, list)) or (not symbols):
        raise ValueError('invalid request')
    if any((not isinstance(x, str) or not x for x in symbols)) or len(set(symbols)) != len(symbols):
        raise ValueError('invalid symbols')
    response = requests.get(endpoint, params={'base': base, 'symbols': ','.join(symbols)}, headers={'Accept': 'application/json'}, timeout=10)
    if response.status_code != 200:
        raise ValueError('bad response')
    try:
        body = response.json()
    except Exception as exc:
