    if not isinstance(snapshots, (list, tuple)) or isinstance(window, bool) or (not isinstance(window, int)) or (window <= 0):
        raise ValueError('invalid arguments')
    observations = {}
    for snapshot in snapshots:
        if not isinstance(snapshot, dict) or not isinstance(snapshot.get('rates'), dict):
            raise ValueError('invalid snapshot')
        for currency, raw in snapshot['rates'].items():
            try:
                value = float(raw)
            except (TypeError, ValueError) as exc:
                raise ValueError('invalid rate') from exc
            if not math.isfinite(value):
                raise ValueError('invalid rate')
            observations.setdefault(currency, []).append(value)
    result = {}
    for currency in sorted(observations):
        values = observations[currency][-window:]
        result[currency] = {'count': len(values), 'average': round(sum(values) / len(values), 6), 'minimum': round(min(values), 6), 'maximum': round(max(values), 6)}
    return result

