            price = Decimal(str(order['price']))
            amount = Decimal(str(order['amount']))
        except (InvalidOperation, ValueError, TypeError):
            raise ValueError('invalid number')
        if not price.is_finite() or not amount.is_finite() or price <= 0 or (amount <= 0):
            raise ValueError('invalid number')
        if order['side'] == side:
            selected.append((price, amount, order))
    selected.sort(key=lambda item: (item[0], str(item[2]['id'])), reverse=side == 'buy')
    rows = []
    for price, amount, order in selected[:limit]:
        rows.append('<tr class="order-row"><td>' + escape(str(symbol), quote=True) + '</td><td>' + escape(str(order['id']), quote=True) + '</td><td>' + escape(str(order['owner']), quote=True) + '</td><td>' + format(price, '.8f') + '</td><td>' + format(amount, '.8f') + '</td></tr>')
    return '<table class="order-book"><thead><tr><th>Symbol</th><th>ID</th><th>Owner</th><th>Price</th><th>Amount</th></tr></thead><tbody>' + ''.join(rows) + '</tbody></table>'

