from html import escape

def parse_votes(text: str) -> list[tuple[str, str, str, int]]:
    result = []
    for number, line in enumerate(text.splitlines(), 1):
        if not line:
            continue
        fields = []
        field = []
        escaped = False
        for char in line:
            if escaped:
                field.append(char)
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '|':
                fields.append(''.join(field))
                field = []
            else:
                field.append(char)
        if escaped:
            raise ValueError(f'invalid record on line {number}')
        fields.append(''.join(field))
        if len(fields) != 4 or any((not value for value in fields)):
            raise ValueError(f'invalid record on line {number}')
        shareholder, resolution, choice, shares_text = fields
        if choice not in {'FOR', 'AGAINST', 'ABSTAIN'}:
            raise ValueError(f'invalid record on line {number}')
        try:
            shares = int(shares_text, 10)
        except ValueError:
            raise ValueError(f'invalid record on line {number}')
        if shares <= 0 or str(shares) != shares_text:
            raise ValueError(f'invalid record on line {number}')
        result.append((shareholder, resolution, choice, shares))
    return result

def summarize_votes(votes: list[tuple[str, str, str, int]]) -> list[dict[str, object]]:
    grouped = {}
    for _, resolution, choice, shares in votes:
        if resolution not in grouped:
            grouped[resolution] = {'resolution': resolution, 'total': 0, 'for': 0, 'against': 0, 'abstain': 0}
        item = grouped[resolution]
        item['total'] += shares
        item[choice.lower()] += shares
    result = []
    for item in grouped.values():
        if item['for'] > item['against']:
            outcome = 'FOR'
        elif item['against'] > item['for']:
            outcome = 'AGAINST'
        else:
            outcome = 'TIE'
        result.append({**item, 'outcome': outcome})
    return sorted(result, key=lambda x: (-x['total'], x['resolution'].casefold(), x['resolution']))

def render_report(title: str, summary: list[dict[str, object]]) -> str:
    rows = ''.join(('<tr><td>' + escape(str(item['resolution'])) + '</td><td>' + escape(str(item['total'])) + '</td><td>' + escape(str(item['for'])) + '</td><td>' + escape(str(item['against'])) + '</td><td>' + escape(str(item['abstain'])) + '</td><td>' + escape(str(item['outcome'])) + '</td></tr>' for item in summary))
    return '<section><h1>' + escape(title) + '</h1><table><thead><tr><th>Resolution</th><th>Total</th><th>For</th><th>Against</th><th>Abstain</th><th>Outcome</th></tr></thead><tbody>' + rows + '</tbody></table></section>'

