import json
from datetime import date, timedelta
from math import isfinite

def encode_state(state: dict) -> bytes:
    if not isinstance(state, dict):
        raise ValueError('state must be a dictionary')
    try:
        return json.dumps(state, ensure_ascii=False, separators=(',', ':')).encode('utf-8')
    except (TypeError, ValueError, UnicodeError) as exc:
        raise ValueError('state cannot be encoded') from exc

def decode_state(blob: bytes) -> dict:
    if not isinstance(blob, bytes):
        raise ValueError('blob must be bytes')
    try:
        value = json.loads(blob.decode('utf-8'))
    except (UnicodeDecodeError, ValueError, TypeError) as exc:
        raise ValueError('invalid state') from exc
    if not isinstance(value, dict):
        raise ValueError('decoded state must be a dictionary')
    return value

def nutrient_report(samples: list[dict], window_days: int=7) -> list[dict]:
    if not isinstance(window_days, int) or isinstance(window_days, bool) or window_days <= 0:
        raise ValueError('invalid window')
    groups = {}
    for sample in samples:
        if not isinstance(sample, dict) or not isinstance(sample.get('date'), str):
            raise ValueError('invalid sample')
        text = sample['date']
        try:
            parsed = date.fromisoformat(text)
        except ValueError as exc:
            raise ValueError('invalid date') from exc
        if parsed.isoformat() != text or not isinstance(sample.get('nutrients'), dict):
            raise ValueError('invalid sample')
        for name, reading in sample['nutrients'].items():
            if not isinstance(name, str) or not name or isinstance(reading, bool) or (not isinstance(reading, (int, float))) or (not isfinite(reading)) or (reading < 0):
                raise ValueError('invalid nutrient')
            groups.setdefault(name, []).append((parsed, float(reading)))
    result = []
    for name in sorted(groups):
        values = groups[name]
        latest = max((d for d, v in values))
        start = latest - timedelta(days=window_days - 1)
        window = [v for d, v in values if start <= d <= latest]
        maximum = max((v for d, v in values))
        maximum_date = min((d for d, v in values if v == maximum))
        total = sum((v for d, v in values))
        result.append({'nutrient': name, 'total': float(total), 'average': float(total / len(values)), 'minimum': float(min((v for d, v in values))), 'maximum': float(maximum), 'maximum_date': maximum_date.isoformat(), 'window_average': float(sum(window) / len(window))})
    return result

