import json
import copy

def encode_state(state: dict) -> bytes:
    try:
        return json.dumps(state, sort_keys=True, separators=(',', ':')).encode('utf-8')
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid state') from exc

def decode_state(blob: bytes | str) -> dict:
    try:
        if isinstance(blob, bytes):
            value = json.loads(blob.decode('utf-8'))
        elif isinstance(blob, str):
            value = json.loads(blob)
        else:
            raise ValueError('invalid data')
    except (UnicodeDecodeError, json.JSONDecodeError, TypeError, ValueError) as exc:
        raise ValueError('invalid data') from exc
    if not isinstance(value, dict):
        raise ValueError('state must be a dictionary')
    return value

def allocate_seats(state: dict, requests: list[dict]) -> dict:
    if not isinstance(state, dict) or not isinstance(requests, list):
        raise ValueError('invalid input')
    work = copy.deepcopy(state)
    rows = work.get('rows')
    if not isinstance(rows, list):
        raise ValueError('invalid rows')
    prepared = []
    names = set()
    for req in requests:
        if not isinstance(req, dict) or not isinstance(req.get('name'), str):
            raise ValueError('invalid request')
        name = req['name']
        count = req.get('count')
        priority = req.get('priority', 0)
        accessible = req.get('accessible_only', False)
        if name in names or type(count) is not int or count <= 0 or (type(priority) is not int) or (type(accessible) is not bool):
            raise ValueError('invalid request')
        names.add(name)
        prepared.append((-priority, name, count, accessible))
    prepared.sort(key=lambda x: (x[0], x[1]))
    assignments = {}
    for _, name, count, accessible in prepared:
        found = None
        for row in rows:
            seats = sorted(row.get('seats', []), key=lambda s: s.get('number'))
            for start in range(len(seats) - count + 1):
                block = seats[start:start + count]
                nums = [s.get('number') for s in block]
                if any((s.get('held') is not False for s in block)) or nums != list(range(nums[0], nums[0] + count)) or (accessible and any((s.get('accessible') is not True for s in block))):
                    continue
                found = (row, block)
                break
            if found:
                break
        if not found:
            raise ValueError('not enough seats')
        row, block = found
        for seat in block:
            seat['held'] = True
        assignments[name] = [{'row': row['name'], 'number': s['number']} for s in block]
    return {'state': work, 'assignments': assignments}

