import json

def _minutes(value):
    if not isinstance(value, str) or len(value) != 5 or value[2] != ':':
        raise ValueError('invalid time')
    try:
        hour = int(value[:2])
        minute = int(value[3:])
    except Exception as exc:
        raise ValueError('invalid time') from exc
    if hour < 0 or hour > 23 or minute < 0 or (minute > 59):
        raise ValueError('invalid time')
    return hour * 60 + minute

def _validate(entries):
    if not isinstance(entries, list):
        raise ValueError('invalid schedule')
    result = []
    allowed = {'channel', 'start', 'title', 'duration', 'series'}
    for item in entries:
        if not isinstance(item, dict) or set(item) - allowed:
            raise ValueError('invalid entry')
        if set(('channel', 'start', 'title', 'duration')) - set(item):
            raise ValueError('missing field')
        if not all((isinstance(item[k], str) for k in ('channel', 'start', 'title'))):
            raise ValueError('invalid field')
        if 'series' in item and (not isinstance(item['series'], str)):
            raise ValueError('invalid series')
        if isinstance(item['duration'], bool) or not isinstance(item['duration'], int) or item['duration'] <= 0:
            raise ValueError('invalid duration')
        _minutes(item['start'])
        result.append(dict(item))
    return sorted(result, key=lambda x: (x['channel'], _minutes(x['start']), x['title']))

def encode_schedule(entries: list[dict]) -> bytes:
    validated = _validate(entries)
    return json.dumps(validated, separators=(',', ':'), ensure_ascii=False).encode('utf-8')

def decode_schedule(blob: bytes) -> list[dict]:
    if not isinstance(blob, bytes):
        raise ValueError('invalid blob')
    try:
        value = json.loads(blob.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid blob') from exc
    return _validate(value)

def aggregate_schedule(blob: bytes, window_start: str, window_end: str) -> dict[str, dict[str, int]]:
    begin, finish = (_minutes(window_start), _minutes(window_end))
    if begin >= finish:
        raise ValueError('invalid window')
    result = {}
    for item in decode_schedule(blob):
        left = max(begin, _minutes(item['start']))
        right = min(finish, _minutes(item['start']) + item['duration'])
        if left < right:
            channel = item['channel']
            if channel not in result:
                result[channel] = {'minutes': 0, 'programs': 0}
            result[channel]['minutes'] += right - left
            result[channel]['programs'] += 1
    return result

