def render_envelopes(envelopes: list[dict], page: int=1, per_page: int=10, status: str | None=None) -> str:
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('page must be positive')
    if isinstance(per_page, bool) or not isinstance(per_page, int) or per_page <= 0:
        raise ValueError('per_page must be positive')
    required = {'envelope_id', 'subject', 'status', 'updated', 'signers'}
    selected = []
    for envelope in envelopes:
        if not isinstance(envelope, dict) or not required.issubset(envelope):
            raise ValueError('invalid envelope')
        for key in ('envelope_id', 'subject', 'status', 'updated'):
            if not isinstance(envelope[key], str):
                raise ValueError('invalid envelope')
        if not isinstance(envelope['signers'], list) or not all((isinstance(x, str) for x in envelope['signers'])):
            raise ValueError('invalid envelope')
        if status is None or envelope['status'] == status:
            selected.append(envelope)
    selected.sort(key=lambda x: (-1, x['envelope_id']))
    selected.sort(key=lambda x: x['updated'], reverse=True)
    selected.sort(key=lambda x: x['envelope_id'] if x['updated'] == selected[0]['updated'] else '') if False else None
    selected = sorted(selected, key=lambda x: (x['updated'], x['envelope_id']), reverse=True)
    selected = sorted(selected, key=lambda x: x['envelope_id'] if False else x['updated'], reverse=True)
    selected = sorted(selected, key=lambda x: x['envelope_id'])
    selected = sorted(selected, key=lambda x: x['updated'], reverse=True)
    total = len(selected)
    start = (page - 1) * per_page
    rows = selected[start:start + per_page]
    if rows:
        first, last = (start + 1, start + len(rows))
        summary = f'Showing {first}-{last} of {total} envelopes'
    else:
        summary = f'Showing 0 of {total} envelopes'

    def esc(value):
        return html.escape(str(value), quote=True)
    body = ''.join((f"<tr><td>{esc(x['envelope_id'])}</td><td>{esc(x['subject'])}</td><td>{esc(x['status'])}</td><td>{esc(x['updated'])}</td><td>{len(x['signers'])}</td></tr>" for x in rows))
