import io
_HEADER = ['name', 'credential', 'renewal_date', 'credits']

def _date(value):
    try:
        return datetime.date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def parse_renewal_records(text: str) -> list[dict[str, object]]:
    if not isinstance(text, str) or not text:
        raise ValueError('empty input')
    rows = list(csv.reader(io.StringIO(text)))
    rows = [row for row in rows if row]
    if not rows or rows[0] != _HEADER:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if len(row) != 4:
            raise ValueError('invalid row')
        name, credential, renewal_date, credits = row
        if not name or not credential:
            raise ValueError('empty field')
        _date(renewal_date)
        try:
            number = int(credits)
        except (TypeError, ValueError):
            raise ValueError('invalid credits')
        if str(number) != credits or number < 0:
            raise ValueError('invalid credits')
        result.append({'name': name, 'credential': credential, 'renewal_date': renewal_date, 'credits': number})
    return result

def render_renewal_report(text: str, as_of: str) -> str:
    today = _date(as_of)
    records = parse_renewal_records(text)
    groups = {'overdue': [], 'due-soon': [], 'current': []}
    for record in records:
        day = _date(record['renewal_date'])
        if day < today:
            status = 'overdue'
        elif day <= today + datetime.timedelta(days=30):
            status = 'due-soon'
        else:
            status = 'current'
        groups[status].append(record)
    for items in groups.values():
        items.sort(key=lambda r: (_date(r['renewal_date']), str(r['name']).casefold(), str(r['credential']).casefold()))
    rows = []
