from datetime import datetime, timedelta, timezone
import requests
_SEVERITIES = {'critical': 0, 'high': 1, 'medium': 2, 'low': 3}
_STATUSES = {'open', 'triaged', 'accepted', 'rejected'}

def fetch_submissions(project: str, api_token: str, since: str | None=None) -> dict:
    params = {'project': project}
    if since is not None:
        params['since'] = since
    response = requests.get('https://api.bugbounty.example/v1/submissions', params=params, headers={'Authorization': 'Bearer ' + api_token}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError('submission request failed with status ' + str(response.status_code))
    return response.json()

def _timestamp(value):
    if not isinstance(value, str):
        raise ValueError('invalid timestamp')
    text = value[:-1] + '+00:00' if value.endswith('Z') else value
    try:
        result = datetime.fromisoformat(text)
    except ValueError as exc:
        raise ValueError('invalid timestamp') from exc
    if result.tzinfo is None:
        raise ValueError('timestamp needs timezone')
    return result.astimezone(timezone.utc)

def parse_submissions(payload: dict) -> list[dict]:
    if not isinstance(payload, dict) or not isinstance(payload.get('submissions'), list):
        raise ValueError('invalid payload')
    result = []
    for item in payload['submissions']:
        if not isinstance(item, dict) or any((k not in item for k in ('id', 'title', 'severity', 'status', 'created_at', 'researcher', 'bounty'))):
            raise ValueError('invalid submission')
        if item['severity'] not in _SEVERITIES or item['status'] not in _STATUSES:
            raise ValueError('invalid submission value')
        if isinstance(item['bounty'], bool) or not isinstance(item['bounty'], (int, float)) or item['bounty'] < 0:
            raise ValueError('invalid bounty')
        stamp = _timestamp(item['created_at'])
        result.append(({'id': item['id'], 'title': item['title'], 'severity': item['severity'], 'status': item['status'], 'created_at': item['created_at'], 'researcher': item['researcher'], 'bounty': item['bounty']}, stamp))
    result.sort(key=lambda pair: (_SEVERITIES[pair[0]['severity']], pair[1], str(pair[0]['id'])))
    return [item for item, _ in result]

def summarize_submissions(records: list[dict], window_days: int=30) -> dict:
    if isinstance(window_days, bool) or not isinstance(window_days, int) or window_days <= 0:
        raise ValueError('invalid window')
    if not records:
        return {'total': 0, 'by_severity': {x: 0 for x in _SEVERITIES}, 'accepted_bounty': 0, 'researchers': []}
    stamped = [(record, _timestamp(record['created_at'])) for record in records]
    end = max((stamp for _, stamp in stamped))
    selected = [record for record, stamp in stamped if end - timedelta(days=window_days) <= stamp <= end]
    counts = {x: 0 for x in _SEVERITIES}
    researchers = {}
    bounty = 0
    for record in selected:
        counts[record['severity']] += 1
        researchers[record['researcher']] = researchers.get(record['researcher'], 0) + 1
        if record['status'] == 'accepted':
            bounty += record['bounty']
    ranked = [{'name': name, 'count': count} for name, count in researchers.items()]
    ranked.sort(key=lambda item: (-item['count'], item['name']))
    return {'total': len(selected), 'by_severity': counts, 'accepted_bounty': bounty, 'researchers': ranked}

