    groups = {}
    for r in records:
        try:
            ts, temp, precip, condition = (r['timestamp'], float(r['temp']), float(r['precip']), r['condition'])
            if not isinstance(ts, datetime) or not isinstance(condition, str) or (not math.isfinite(temp)) or (not math.isfinite(precip)) or (precip < 0):
                raise ValueError
            groups.setdefault(ts.date().isoformat(), []).append((ts, temp, precip, condition))
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid record')
    result = []
    for date in sorted(groups):
        rows = sorted(groups[date], key=lambda x: x[0])
        counts = {}
        for _, _, _, c in rows:
            counts[c] = counts.get(c, 0) + 1
        peak = min(counts, key=lambda c: (-counts[c], c))
        vals = [x[1] for x in rows]
        precip = [x[2] for x in rows]
        window = max((sum(precip[i:i + 3]) for i in range(max(1, len(precip) - 2))))
        result.append({'date': date, 'avg_temp': round(sum(vals) / len(vals), 2), 'total_precip': round(sum(precip), 2), 'peak_condition': peak, 'hot_hours': sum((x >= 30 for x in vals)), 'max_three_hour_precip': round(window, 2)})
    return result

