    if not math.isfinite(precip_threshold) or precip_threshold < 0:
        raise ValueError('invalid threshold')
    rows = []
    for s in summaries:
        try:
            date, condition = (s['date'], s['peak_condition'])
            avg, total, peak, hot = [float(s[k]) for k in ('avg_temp', 'total_precip', 'max_three_hour_precip', 'hot_hours')]
            if not isinstance(date, str) or not isinstance(condition, str) or any((not math.isfinite(x) for x in (avg, total, peak, hot))):
