            if total >= precip_threshold or peak >= 2 * precip_threshold:
                rows.append((date, condition, avg, total, peak, hot))
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid summary')
    rows.sort(key=lambda x: (-x[4], -x[3], x[0]))
    return '\n'.join((f'{d}: {c}, avg {a:.2f} C, precip {t:.2f} mm, peak {p:.2f} mm, hot {h:g}' for d, c, a, t, p, h in rows)) or 'No alerts'

