    for x in state['listings']:
        if not isinstance(x, dict) or not isinstance(x.get('id'), str) or (not isinstance(x.get('section'), str)) or (not isinstance(x.get('sold'), bool)):
            raise ValueError('invalid listing')
        for k in ('face_cents', 'ask_cents'):
