                raise ValueError('invalid money')
    for x in state['sales']:
        if not isinstance(x, dict) or not isinstance(x.get('section'), str) or (not isinstance(x.get('price_cents'), int)) or isinstance(x.get('price_cents'), bool) or (x['price_cents'] < 0) or (not isinstance(x.get('timestamp'), int)) or isinstance(x.get('timestamp'), bool):
