from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from html import escape

def render_royalty_table(records: list[dict], page: int=1, per_page: int=10) -> str:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(per_page, bool) or not isinstance(per_page, int) or per_page <= 0:
        raise ValueError('invalid per_page')
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        if not isinstance(record.get('artist'), str) or not record['artist']:
            raise ValueError('invalid artist')
        if not isinstance(record.get('track'), str) or not record['track']:
            raise ValueError('invalid track')
        streams = record.get('streams')
        if isinstance(streams, bool) or not isinstance(streams, int) or streams < 0:
            raise ValueError('invalid streams')
        try:
            rate = Decimal(str(record['rate']))
        except (KeyError, InvalidOperation, ValueError, TypeError):
            raise ValueError('invalid rate')
        if not rate.is_finite() or rate < 0:
            raise ValueError('invalid rate')
        key = (record['artist'], record['track'])
        if key not in groups:
            groups[key] = [0, Decimal('0')]
        groups[key][0] += streams
        groups[key][1] += Decimal(streams) * rate
    rows = []
    for (artist, track), (streams, amount) in groups.items():
        rounded = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        rows.append((rounded, artist, track, streams))
    rows.sort(key=lambda row: (-row[0], row[1].casefold(), row[2].casefold(), row[1], row[2]))
    start = (page - 1) * per_page
    selected = rows[start:start + per_page]
    body = ''.join((f'<tr><td>{escape(artist, quote=True)}</td><td>{escape(track, quote=True)}</td><td>{streams}</td><td>${amount:.2f}</td></tr>' for amount, artist, track, streams in selected))
    return '<table class="royalties">\n<thead><tr><th>Artist</th><th>Track</th><th>Streams</th><th>Royalty</th></tr></thead>\n<tbody>' + body + '</tbody>\n</table>'

