import json
import re
from collections.abc import Mapping
_REQUIRED = {'source', 'target', 'locale', 'quality', 'uses', 'updated'}

def _check_entries(entries):
    if not isinstance(entries, list):
        raise TypeError('entries must be a list')
    for item in entries:
        if not isinstance(item, Mapping) or not _REQUIRED.issubset(item):
            raise ValueError('invalid entry')
        if not isinstance(item['source'], str) or not isinstance(item['target'], str) or (not isinstance(item['locale'], str)):
            raise ValueError('invalid entry')
        if not isinstance(item['quality'], (int, float)) or isinstance(item['quality'], bool) or (not 0 <= item['quality'] <= 1):
            raise ValueError('invalid entry')
        if not isinstance(item['uses'], int) or isinstance(item['uses'], bool) or item['uses'] < 0 or (not isinstance(item['updated'], int)) or isinstance(item['updated'], bool):
            raise ValueError('invalid entry')

def encode_memory(entries: list[dict]) -> bytes:
    _check_entries(entries)
    try:
        return json.dumps(entries, ensure_ascii=False, sort_keys=True, separators=(',', ':'), allow_nan=False).encode('utf-8')
    except (TypeError, ValueError) as exc:
        raise TypeError('entries are not serializable') from exc

def decode_memory(blob: bytes | str) -> list[dict]:
    try:
        text = blob.decode('utf-8') if isinstance(blob, bytes) else blob
        value = json.loads(text)
        _check_entries(value)
        return json.loads(json.dumps(value, ensure_ascii=False))
    except (UnicodeError, TypeError, ValueError, json.JSONDecodeError) as exc:
        raise ValueError('invalid memory') from exc

def suggest_translations(source: str, entries: list[dict], locale: str, limit: int=5) -> list[dict]:
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 0:
        raise ValueError('invalid limit')
    if not isinstance(source, str) or not isinstance(locale, str):
        raise TypeError('source and locale must be strings')
    tokens = re.findall('[^\\W_]+', source.casefold(), re.UNICODE)
    if not tokens or not limit:
        return []
    wanted = set(tokens)
    best = {}
    for index, entry in enumerate(entries):
        if entry.get('locale') != locale:
            continue
        candidate = re.findall('[^\\W_]+', entry.get('source', '').casefold(), re.UNICODE)
        if not candidate:
            continue
        overlap = len(wanted & set(candidate)) / len(wanted | set(candidate))
        score = overlap + (0.5 if candidate == tokens else 0) + entry['quality'] * 0.25
        record = {'target': entry['target'], 'score': score, 'quality': entry['quality'], 'uses': entry['uses'], 'updated': entry['updated'], '_i': index}
        old = best.get(entry['target'])
        if old is None or (score, entry['quality'], entry['uses'], -index) > (old['score'], old['quality'], old['uses'], -old['_i']):
            best[entry['target']] = record
    values = sorted(best.values(), key=lambda x: (-x['score'], -x['quality'], -x['uses'], x['target']))[:limit]
    return [{k: round(v[k], 6) if k == 'score' else v[k] for k in ('target', 'score', 'quality', 'uses', 'updated')} for v in values]

