def _check_records(records):
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    for record in records:
        if not isinstance(record, dict) or set(record) != {'vessel', 'species', 'weight_kg', 'zone'}:
            raise ValueError('invalid record')
        if any((not isinstance(record[key], str) or not record[key] for key in ('vessel', 'species', 'zone'))):
            raise ValueError('invalid record')
        weight = record['weight_kg']
        if isinstance(weight, bool) or not isinstance(weight, (int, float)) or (not math.isfinite(weight)) or (weight < 0):
            raise ValueError('invalid record')

def encode_catches(records: list[dict]) -> bytes:
    _check_records(records)
    return json.dumps(records, separators=(',', ':'), allow_nan=False).encode('utf-8')

def summarize_catches(payload: bytes, zone: str | None=None, page: int=1, page_size: int=10) -> list[dict]:
    if not isinstance(payload, bytes) or (zone is not None and (not isinstance(zone, str))):
        raise ValueError('invalid arguments')
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
