import requests

def fetch_maintenance_summary(park_id: str, min_priority: int=0) -> list[dict]:
    if not isinstance(park_id, str) or not park_id:
        raise ValueError('invalid park_id')
    if isinstance(min_priority, bool) or not isinstance(min_priority, int) or (not 0 <= min_priority <= 5):
        raise ValueError('invalid min_priority')
    totals = {}
    page = 1
    while True:
        response = requests.get(f'https://maintenance.example/api/v1/parks/{park_id}/rides', params={'min_priority': min_priority, 'page': page}, headers={'Accept': 'application/json'}, timeout=10)
        if response.status_code != 200:
            raise RuntimeError('maintenance service error')
        try:
            payload = response.json()
        except Exception as exc:
            raise ValueError('invalid response') from exc
        if not isinstance(payload, dict) or not isinstance(payload.get('rides'), list):
            raise ValueError('invalid response')
        for ride in payload['rides']:
            if ride['status'] in ('open', 'scheduled') and ride['priority'] >= min_priority:
                status = ride['status']
                item = totals.setdefault(status, [0, 0])
                item[0] += 1
                item[1] += ride['downtime_minutes']
        if not payload.get('next_page', False):
            break
        page += 1
    result = [{'status': status, 'ride_count': values[0], 'total_downtime': values[1], 'average_downtime': round(values[1] / values[0], 2)} for status, values in totals.items()]
    return sorted(result, key=lambda item: (-item['total_downtime'], item['status']))

