def render_donation_report(records: list[dict[str, object]], year: int | None=None, page: int=1, per_page: int=10) -> str:
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(per_page, bool) or not isinstance(per_page, int) or per_page <= 0:
        raise ValueError('invalid per_page')
    if year is not None and (isinstance(year, bool) or not isinstance(year, int)):
        raise ValueError('invalid year')
    totals: dict[str, Decimal] = {}
    for record in records:
        try:
            donor = record['donor']
            amount = record['amount']
            record_year = record['year']
        except (KeyError, TypeError):
            raise ValueError('invalid record')
        if not isinstance(donor, str) or not donor:
            raise ValueError('invalid donor')
        if isinstance(amount, bool) or not isinstance(amount, (int, float)) or (isinstance(amount, float) and (not isfinite(amount))) or (amount < 0):
            raise ValueError('invalid amount')
        if isinstance(record_year, bool) or not isinstance(record_year, int):
            raise ValueError('invalid record year')
