    params = {'facility_id': facility_id, 'limit': page_size}
    if status is not None:
        params['status'] = status
    result = []
    first = True
    while url:
        response = requests.get(url, params=params if first else None, headers={'Authorization': 'Bearer ' + api_key})
        if response.status_code != 200:
            raise RuntimeError('HTTP status ' + str(response.status_code))
        try:
