            raise ValueError('invalid response') from exc
        if not isinstance(data, dict) or not isinstance(data.get('items'), list) or (data.get('next') is not None and (not isinstance(data.get('next'), str))):
            raise ValueError('invalid response')
        result.extend(data['items'])
        url = data.get('next')
        first = False
    return result

