def encode_snapshot(records: list[dict]) -> bytes:
    return json.dumps(records, separators=(',', ':'), sort_keys=True).encode('utf-8')

def load_ranked(payload: bytes, building: str | None=None, page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('invalid pagination')
    try:
        records = json.loads(payload.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    required = {'student', 'building', 'status', 'points', 'priority'}
    selected = []
    for record in records:
        if not isinstance(record, dict) or not required.issubset(record) or (not isinstance(record['student'], str)) or (not isinstance(record['building'], str)) or (not isinstance(record['status'], str)) or isinstance(record['points'], bool) or isinstance(record['priority'], bool) or (not isinstance(record['points'], (int, float))) or (not isinstance(record['priority'], (int, float))):
            raise ValueError('invalid record')
        if record['status'] == 'eligible' and (building is None or record['building'] == building):
            selected.append(record)
    selected.sort(key=lambda r: (-r['points'] - r['priority'], r['building'], r['student']))
    start = (page - 1) * page_size
    items = [{'student': r['student'], 'building': r['building'], 'score': round(r['points'] + r['priority'], 2)} for r in selected[start:start + page_size]]
    return {'total': len(selected), 'items': items}

