from datetime import datetime, timezone
import math
import requests
_SEVERITIES = {'critical': 4, 'high': 3, 'medium': 2, 'low': 1}
_ORDER = ('critical', 'high', 'medium', 'low')

def fetch_machine_events(machine_id: str, start: str, end: str, api_key: str) -> list[dict]:
    response = requests.get(f'https://maintenance.example/api/v2/machines/{machine_id}/events', params={'start': start, 'end': end}, headers={'Authorization': f'Bearer {api_key}'}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError(f'maintenance API returned {response.status_code}')
    try:
        payload = response.json()
        events = payload['data']['events']
    except (TypeError, KeyError, ValueError):
        raise ValueError('invalid maintenance response')
    if not isinstance(payload, dict) or not isinstance(payload.get('data'), dict) or (not isinstance(events, list)):
        raise ValueError('invalid maintenance response')
    return events

def _parsed_timestamp(value):
    if not isinstance(value, str):
        raise ValueError('invalid timestamp')
    try:
        parsed = datetime.fromisoformat(value.replace('Z', '+00:00'))
        if parsed.tzinfo is None:
            raise ValueError
        return parsed.astimezone(timezone.utc)
    except (ValueError, TypeError):
        raise ValueError('invalid timestamp')

def normalize_events(events: list[dict]) -> list[dict]:
    result = []
    for event in events:
        try:
            severity = event['severity']
            if severity not in _SEVERITIES:
                raise ValueError
            timestamp = _parsed_timestamp(event['timestamp'])
            duration = event['duration_minutes']
            if isinstance(duration, bool) or not isinstance(duration, (int, float)) or (not math.isfinite(duration)) or (duration <= 0):
                raise ValueError
            item = dict(event)
            item.pop('duration_minutes', None)
            item['timestamp'] = timestamp.strftime('%Y-%m-%dT%H:%M:%SZ')
            item['duration_seconds'] = math.floor(duration * 60 + 0.5)
            result.append((timestamp, item))
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid maintenance event')
    result.sort(key=lambda pair: (pair[0], -_SEVERITIES[pair[1]['severity']], pair[1]['id']))
    return [item for _, item in result]

def summarize_events(events: list[dict], window_minutes: int=60) -> list[dict]:
    if isinstance(window_minutes, bool) or not isinstance(window_minutes, int) or window_minutes <= 0:
        raise ValueError('window_minutes must be positive')
    normalized = normalize_events(events)
    grouped = {}
    width = window_minutes * 60
    for event in normalized:
        moment = datetime.fromisoformat(event['timestamp'].replace('Z', '+00:00'))
        epoch_seconds = int(moment.timestamp())
        start = epoch_seconds - epoch_seconds % width
        grouped.setdefault(start, []).append(event)
    output = []
    for start in sorted(grouped):
        items = grouped[start]
        counts = {severity: 0 for severity in _ORDER}
        for item in items:
            counts[item['severity']] += 1
        output.append({'window_start': datetime.fromtimestamp(start, timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ'), 'count': len(items), 'total_downtime_seconds': sum((item['duration_seconds'] for item in items)), 'by_severity': counts})
    return output

def machine_maintenance_report(machine_id: str, start: str, end: str, api_key: str, window_minutes: int=60) -> list[dict]:
    return summarize_events(fetch_machine_events(machine_id, start, end, api_key), window_minutes)

