def render_loan_report(records: list[dict[str, str]], page: int=1, per_page: int=10) -> str:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('page must be positive')
    if isinstance(per_page, bool) or not isinstance(per_page, int) or per_page < 1:
        raise ValueError('per_page must be positive')
    checked = []
    statuses = {'pending', 'shipped', 'received', 'overdue'}
    fields = ('id', 'title', 'borrower', 'library', 'status', 'due_date')
    for record in records:
        try:
            if any((not isinstance(record[field], str) for field in fields)):
                raise ValueError('invalid record')
            if record['status'] not in statuses:
                raise ValueError('invalid status')
            due = date.fromisoformat(record['due_date'])
        except (KeyError, TypeError, ValueError) as exc:
            raise ValueError('invalid record') from exc
        checked.append((due, record))
    checked.sort(key=lambda item: (item[0], item[1]['title'].casefold(), item[1]['id']))
    total = len(checked)
    start = (page - 1) * per_page
    shown = checked[start:start + per_page]
    if shown:
        first, last = (start + 1, start + len(shown))
    else:
        first, last = (0, 0)
    rows = []
    for _, record in shown:
        values = [html.escape(record[field], quote=True) for field in ('title', 'borrower', 'library', 'status', 'due_date')]
