import csv
import io
import math
import requests

def fetch_inventory(base_url: str, warehouse_id: str, api_key: str) -> list[dict]:
    response = requests.get(base_url.rstrip('/') + '/v1/inventory', params={'warehouse': warehouse_id}, headers={'Authorization': 'Bearer ' + api_key})
    if response.status_code != 200:
        raise ValueError(str(response.status_code))
    try:
        payload = response.json()
    except Exception as exc:
        raise ValueError('invalid response') from exc
    fields = ('sku', 'on_hand', 'reserved', 'inbound', 'daily_demand', 'reorder_point', 'pack_size', 'unit_cost', 'priority')
    if not isinstance(payload, dict) or not isinstance(payload.get('items'), list):
        raise ValueError('invalid response')
    result = []
    for item in payload['items']:
        if not isinstance(item, dict) or any((field not in item for field in fields)):
            raise ValueError('invalid item')
        result.append({field: item[field] for field in fields})
    return result

def plan_replenishment(records: list[dict], days: int=7) -> list[dict]:
    if days < 0:
        raise ValueError('days')
    grouped = {}
    for row in records:
        sku = row['sku']
        if sku in grouped and grouped[sku]['pack_size'] != row['pack_size']:
            raise ValueError('pack size')
        if sku not in grouped:
            grouped[sku] = {'sku': sku, 'on_hand': 0, 'reserved': 0, 'inbound': 0, 'daily_demand': 0, 'reorder_point': row['reorder_point'], 'pack_size': row['pack_size'], 'unit_cost': row['unit_cost'], 'priority': row['priority']}
        item = grouped[sku]
        if item['pack_size'] <= 0:
            raise ValueError('pack size')
        for key in ('on_hand', 'reserved', 'inbound', 'daily_demand'):
            item[key] += row[key]
        item['reorder_point'] = max(item['reorder_point'], row['reorder_point'])
        item['priority'] = max(item['priority'], row['priority'])
    result = []
    for item in grouped.values():
        available = item['on_hand'] - item['reserved'] + item['inbound']
        target = item['daily_demand'] * days + item['reorder_point']
        urgency = target - available
        if urgency > 0:
            quantity = math.ceil(urgency / item['pack_size']) * item['pack_size']
            result.append({'sku': item['sku'], 'quantity': quantity, 'estimated_cost': quantity * item['unit_cost'], 'urgency': urgency})
    return sorted(result, key=lambda x: (-x['urgency'], x['sku']))

def parse_adjustments(text: str) -> dict[str, int]:
    rows = list(csv.reader(io.StringIO(text)))
    if not rows or rows[0] != ['sku', 'delta', 'reason']:
        raise ValueError('headers')
    result = {}
    for row in rows[1:]:
        if not row or all((not value for value in row)):
            continue
        if len(row) != 3 or not row[0]:
            raise ValueError('row')
        try:
            delta = int(row[1])
        except (TypeError, ValueError) as exc:
            raise ValueError('delta') from exc
        result[row[0]] = result.get(row[0], 0) + delta
    return result

