import requests

def fetch_license(api_url: str, license_key: str, product_id: str) -> dict:
    response = requests.get(api_url, params={'product_id': product_id}, headers={'Authorization': 'Bearer ' + license_key, 'Accept': 'application/json'})
    if response.status_code != 200:
        raise RuntimeError(f'license service returned {response.status_code}')
    try:
        body = response.json()
        if not isinstance(body, dict) or not isinstance(body.get('license_id'), str) or (not body['license_id']) or (not isinstance(body.get('entitlements'), list)):
            raise ValueError
        normalized = []
        for item in body['entitlements']:
            if not isinstance(item, dict) or not isinstance(item.get('sku'), str) or (not item['sku']) or (not isinstance(item.get('quantity'), int)) or isinstance(item['quantity'], bool) or (item['quantity'] < 0) or (not isinstance(item.get('features'), list)) or any((not isinstance(x, str) for x in item['features'])):
                raise ValueError
            expires = item.get('expires')
            if expires is not None:
                if not isinstance(expires, str) or not expires.endswith('Z'):
                    raise ValueError
                datetime.fromisoformat(expires[:-1] + '+00:00')
            normalized.append({'sku': item['sku'], 'quantity': item['quantity'], 'expires': expires, 'features': sorted(set(item['features']))})
        return {'license_id': body['license_id'], 'entitlements': normalized}
    except Exception as exc:
        if isinstance(exc, ValueError):
            raise ValueError('invalid license response')
        raise ValueError('invalid license response')

def summarize_license(license_data: dict, as_of: datetime) -> list[dict]:
    if as_of.tzinfo is None or as_of.utcoffset() is None:
        raise ValueError('as_of must be timezone-aware')
    groups = {}
    for item in license_data['entitlements']:
        expiry = None if item['expires'] is None else datetime.fromisoformat(item['expires'][:-1] + '+00:00')
        if expiry is not None and expiry < as_of.astimezone(timezone.utc):
            continue
        group = groups.setdefault(item['sku'], {'quantity': 0, 'features': set(), 'expires': []})
        group['quantity'] += item['quantity']
        group['features'].update(item['features'])
        if item['expires'] is not None:
            group['expires'].append(item['expires'])
    result = []
    for sku, group in groups.items():
        result.append({'sku': sku, 'quantity': group['quantity'], 'features': sorted(group['features']), 'expires': min(group['expires']) if group['expires'] else None})
    return sorted(result, key=lambda x: (-x['quantity'], x['sku']))

