    if any((not isinstance(event[k], str) or not event[k] for k in ('card', 'merchant', 'country'))):
        raise ValueError('invalid event')
    if isinstance(event['amount'], bool) or not isinstance(event['amount'], (int, float)) or (not math.isfinite(event['amount'])) or (event['amount'] <= 0):
