    previous = None
    for event in events:
        _event(event)
        ts = event['ts']
        if previous is not None and ts < previous:
            raise ValueError('events are out of order')
        previous = ts
        old = history.get(event['card'], {}).get('recent', [])
        recent = [x for x in old if isinstance(x, list) and len(x) == 3 and (x[0] >= ts - 3600)]
        recent.append([ts, event['country'], event['amount']])
        score = 50 if event['amount'] > 1000 else 0
        if len({x[1] for x in recent}) > 1:
            score += 30
        if sum((x[0] >= ts - 600 for x in recent)) >= 3:
            score += 20
        history[event['card']] = {'recent': recent}
        output.append({'card': event['card'], 'score': score, 'risk': 'high' if score >= 50 else 'low', 'ts': ts})
    return (output, encode_state(state))

