            consumer = item['consumer']['name']
            category = item['product']['category']
            status = item['status']
            created = item['created_at']
            amount = float(item['amount'])
            tags = item['tags']
            datetime.fromisoformat(created.replace('Z', '+00:00'))
        except (KeyError, TypeError, ValueError, AttributeError):
            raise ValueError('invalid complaint')
        if not math.isfinite(amount) or not isinstance(tags, list) or (not all((isinstance(x, str) for x in tags))):
            raise ValueError('invalid complaint')
        result.append({'id': ident, 'consumer': consumer, 'category': category, 'status': status, 'created_at': created, 'amount': amount, 'tags': list(tags)})
    return result

def fetch_complaints(category: str, page: int=1) -> list[dict]:
    if not isinstance(category, str) or not category or (not isinstance(page, int)) or isinstance(page, bool) or (page < 1):
        raise ValueError('invalid arguments')
    response = requests.get('https://api.consumer.example/v1/complaints', params={'category': category, 'page': page}, headers={'Accept': 'application/json'}, timeout=10)
    if not 200 <= response.status_code < 300:
        raise RuntimeError(f'request failed with status {response.status_code}')
    return parse_complaints(response.json())

def summarize_complaints(records: list[dict], start_date: str | None=None, end_date: str | None=None) -> dict:

    def bound(value):
        if value is None:
            return None
        try:
            return date.fromisoformat(value)
        except (TypeError, ValueError):
            raise ValueError('invalid date')
    start, end = (bound(start_date), bound(end_date))
    if start and end and (start > end):
        raise ValueError('invalid range')
    categories, statuses, tags = ({}, {}, {})
    total = 0
    for record in records:
        try:
            day = datetime.fromisoformat(record['created_at'].replace('Z', '+00:00')).date()
        except (KeyError, TypeError, ValueError, AttributeError):
            raise ValueError('invalid record')
        if start and day < start or (end and day > end):
            continue
        total += 1
        category = record['category']
        entry = categories.setdefault(category, {'count': 0, 'amount': 0.0})
        entry['count'] += 1
        entry['amount'] += float(record['amount'])
        statuses[record['status']] = statuses.get(record['status'], 0) + 1
        for tag in record['tags']:
            tags[tag] = tags.get(tag, 0) + 1
    for entry in categories.values():
        entry['amount'] = round(entry['amount'] + 1e-10, 2)
    return {'total': total, 'by_category': {k: categories[k] for k in sorted(categories)}, 'by_status': {k: statuses[k] for k in sorted(statuses)}, 'top_tags': [[k, v] for k, v in sorted(tags.items(), key=lambda x: (-x[1], x[0]))]}

