    lines = ['<div class="purchase-orders">', '<h1>Wholesale Purchase Orders</h1>', f'<p class="summary">Showing {first}-{last} of {len(prepared)} orders; grand total ${quantize(grand_total):.2f}</p>', '<table>', '<thead><tr><th>Order</th><th>Supplier</th><th>Item</th><th>Quantity</th><th>Unit Price</th><th>Line Total</th></tr></thead>', '<tbody>']
