from datetime import datetime, timezone
from urllib.parse import quote
import requests

def _date(value):
    try:
        return datetime.strptime(value, '%Y-%m-%d').date()
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def _record(item):
    if not isinstance(item, dict):
        raise ValueError('invalid observation')
    station = item.get('station')
    timestamp = item.get('timestamp')
    temp = item.get('temperature_c')
    rain = item.get('precipitation_mm')
    if not isinstance(station, str) or not station.strip() or (not isinstance(timestamp, str)):
        raise ValueError('invalid observation')
    if isinstance(temp, bool) or not isinstance(temp, (int, float)):
        raise ValueError('invalid temperature')
    if isinstance(rain, bool) or not isinstance(rain, (int, float)) or rain < 0:
        raise ValueError('invalid precipitation')
    try:
        parsed = datetime.fromisoformat(timestamp.replace('Z', '+00:00'))
        if parsed.tzinfo is None:
            raise ValueError
        parsed = parsed.astimezone(timezone.utc).replace(microsecond=0)
    except ValueError:
        raise ValueError('invalid timestamp')
    return {'station': station.strip(), 'timestamp': parsed.strftime('%Y-%m-%dT%H:%M:%SZ'), 'temperature_c': float(temp), 'precipitation_mm': float(rain)}

def fetch_observations(dataset_id: str, start: str, end: str, token: str | None=None) -> list[dict]:
    first, last = (_date(start), _date(end))
    if first > last:
        raise ValueError('invalid range')
    url = 'https://climate.example.org/v1/datasets/' + quote(dataset_id, safe='') + '/observations'
    kwargs = {'params': {'start': start, 'end': end, 'format': 'json'}}
    if token is not None:
        kwargs['headers'] = {'Authorization': 'Bearer ' + token}
    response = requests.get(url, **kwargs)
    if response.status_code != 200:
        raise RuntimeError(f'climate API returned {response.status_code}')
    try:
        payload = response.json()
        items = payload['observations']
        if not isinstance(items, list):
            raise ValueError
        return [_record(item) for item in items]
    except (KeyError, TypeError, ValueError):
        raise ValueError('invalid response')

def analyze_observations(observations: list[dict], window: int=3) -> list[dict]:
    if not isinstance(window, int) or isinstance(window, bool) or window <= 0:
        raise ValueError('invalid window')
    groups = {}
    for item in observations:
        record = _record(item)
        groups.setdefault(record['station'], []).append(record)
    result = []
    for station in sorted(groups):
        rows = sorted(groups[station], key=lambda x: x['timestamp'])
        temps = [x['temperature_c'] for x in rows]
        means = [sum(temps[i:i + window]) / min(window, len(temps) - i) for i in range(max(1, len(temps) - window + 1))]
        result.append({'station': station, 'count': len(rows), 'mean_temperature_c': round(sum(temps) / len(temps), 2), 'total_precipitation_mm': round(sum((x['precipitation_mm'] for x in rows)), 2), 'max_window_temperature_c': round(max(means), 2)})
    return result

def build_climate_report(dataset_id: str, start: str, end: str, window: int=3, token: str | None=None) -> dict:
    return {'dataset_id': dataset_id, 'start': start, 'end': end, 'stations': analyze_observations(fetch_observations(dataset_id, start, end, token), window)}

