import json

def _validate(events, horizon, metadata):
    if not isinstance(events, list) or not isinstance(horizon, int) or isinstance(horizon, bool) or (horizon < 0) or (not isinstance(metadata, dict)):
        raise ValueError('invalid state')
    for event in events:
        if not isinstance(event, dict) or set(event) != {'time', 'site', 'status', 'people'}:
            raise ValueError('invalid event')
        if not isinstance(event['time'], int) or isinstance(event['time'], bool) or (not 0 <= event['time'] <= horizon):
            raise ValueError('invalid time')
        if not isinstance(event['site'], str) or not event['site'] or event['status'] not in ('up', 'down'):
            raise ValueError('invalid event')
        if not isinstance(event['people'], int) or isinstance(event['people'], bool) or event['people'] < 0:
            raise ValueError('invalid people')

def encode_checkpoint(events: list[dict], horizon: int, metadata: dict) -> bytes:
    _validate(events, horizon, metadata)
    return json.dumps({'events': events, 'horizon': horizon, 'metadata': metadata}, separators=(',', ':')).encode()

def decode_checkpoint(blob: bytes) -> dict:
    try:
        value = json.loads(blob.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid checkpoint') from exc
    if not isinstance(value, dict) or set(value) != {'events', 'horizon', 'metadata'}:
        raise ValueError('invalid checkpoint')
    _validate(value['events'], value['horizon'], value['metadata'])
    return value

def build_continuity_report(state: dict, window: int) -> dict:
    if not isinstance(window, int) or isinstance(window, bool) or window <= 0 or (not isinstance(state, dict)) or (set(state) != {'events', 'horizon', 'metadata'}):
        raise ValueError('invalid input')
    _validate(state['events'], state['horizon'], state['metadata'])
    horizon = state['horizon']
    grouped = {}
    for event in state['events']:
        grouped.setdefault(event['site'], []).append(event)
    results = {}
    timelines = {}
    for site in sorted(grouped):
        current = 'up'
        opened = None
        outages = []
        for event in sorted(enumerate(grouped[site]), key=lambda x: (x[1]['time'], x[0])):
            item = event[1]
            if item['status'] == 'down' and current == 'up':
                current, opened = ('down', (item['time'], item['people']))
            elif item['status'] == 'up' and current == 'down':
                outages.append((opened[0], item['time'], opened[1]))
                current, opened = ('up', None)
        if current == 'down':
            outages.append((opened[0], horizon, opened[1]))
        durations = [end - start for start, end, _ in outages]
        results[site] = {'outage_count': len(outages), 'downtime': sum(durations), 'longest_outage': max(durations, default=0), 'people_hours_down': sum(((end - start) * people for start, end, people in outages)), 'final_status': current}
        timelines[site] = sorted(grouped[site], key=lambda x: x['time'])
    windows = []
    for start in range(0, horizon, window):
        down = []
        for site, events in timelines.items():
            status = 'up'
            for event in events:
                if event['time'] <= start:
                    status = event['status']
            if status == 'down':
                down.append(site)
        windows.append({'start': start, 'end': min(start + window, horizon), 'down_sites': sorted(down)})
    return {'horizon': horizon, 'window': window, 'sites': results, 'windows': windows}

