from html import escape

def parse_event_log(text: str) -> list[dict]:
    result = []
    for number, line in enumerate(text.splitlines(), 1):
        if not line.strip():
            continue
        parts = line.split('|')
        if len(parts) != 5:
            raise ValueError(f'line {number}: invalid event')
        stamp, zone, event, severity, message = parts
        try:
            if not zone or not event or (not message) or (not stamp.endswith('Z')):
                raise ValueError
            parsed = datetime.fromisoformat(stamp[:-1] + '+00:00')
            parsed = parsed.astimezone(timezone.utc)
            level = int(severity)
            if level not in range(1, 6):
                raise ValueError
        except (ValueError, OverflowError):
            raise ValueError(f'line {number}: invalid event')
        result.append({'timestamp': parsed, 'zone': zone, 'event': event, 'severity': level, 'message': message})
    return result

def event_statistics(events: list[dict]) -> dict:
    levels = {n: 0 for n in range(1, 6)}
    zones = {}
    latest = {}
    for event in events:
        levels[event['severity']] += 1
        zones[event['zone']] = zones.get(event['zone'], 0) + 1
        old = latest.get(event['zone'])
        if old is None or event['timestamp'] > old['timestamp']:
            latest[event['zone']] = event
    ordered_zones = dict(sorted(zones.items(), key=lambda pair: (-pair[1], pair[0])))
    ordered_latest = sorted(latest.values(), key=lambda item: (-item['timestamp'].timestamp(), item['zone']))
    return {'total': len(events), 'by_severity': levels, 'by_zone': ordered_zones, 'latest': ordered_latest}

def render_alarm_report(events: list[dict], title: str='Alarm Event Report') -> str:
    stats = event_statistics(events)
    esc = lambda value: escape(str(value), quote=True)
    ordered = sorted(enumerate(events), key=lambda pair: (-pair[1]['timestamp'].timestamp(), -pair[1]['severity'], pair[1]['zone'], pair[0]))
    rows = []
    for _, event in ordered:
        stamp = event['timestamp'].astimezone(timezone.utc).strftime('%Y-%m-%d %H:%M:%S UTC')
        rows.append('<tr><td>' + esc(stamp) + '</td><td>' + esc(event['zone']) + '</td><td>' + esc(event['event']) + '</td><td>' + esc(event['severity']) + '</td><td>' + esc(event['message']) + '</td></tr>')
    critical = stats['by_severity'][5]
    body = ''.join(rows)
    return '<section class="alarm-report"><h1>' + esc(title) + '</h1><p class="summary">' + str(stats['total']) + ' events, ' + str(critical) + ' critical</p><table><thead><tr><th>Time</th><th>Zone</th><th>Event</th><th>Severity</th><th>Message</th></tr></thead><tbody>' + body + '</tbody></table></section>'

